INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('f6da95e2-f02a-4f10-9d39-b693ba0df9bc', '缠论核心理论：笔、线段、中枢', '缠论的三大核心概念：笔（5根K线构成）、线段（至少3笔构成）、中枢（至少3段重叠区间）。理解这三个概念是掌握缠论的基础。', 'knowledge', '{缠论,技术分析,理论基础}', 'web-test', '''5根k线构成'':7B ''中枢'':4A,10B ''理解这三个概念是掌握缠论的基础'':12B ''笔'':2A,6B ''线段'':3A,8B ''缠论核心理论'':1A ''缠论的三大核心概念'':5B ''至少3段重叠区间'':11B ''至少3笔构成'':9B', '2026-08-18 22:30:54.30188', '2026-08-18 22:34:43.279832', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('5c0b3363-8662-45df-9429-b7975fae8a93', '成功案例：贵州茅台趋势判断', '2024年7月初，通过缠论分析判断贵州茅台形成30分钟级别中枢，预判将突破上行。实际在7月15日成功突破，获利12.5%。', 'experience', '{成功案例,贵州茅台,缠论,中枢}', 'web-test', '''2024年7月初'':3B ''实际在7月15日成功突破'':6B ''成功案例'':1A ''获利12.5'':7B ''贵州茅台趋势判断'':2A ''通过缠论分析判断贵州茅台形成30分钟级别中枢'':4B ''预判将突破上行'':5B', '2026-08-18 22:30:54.30188', '2026-08-18 22:34:43.279832', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('12f3fa5f-914b-4ee1-bde9-f99141772084', '市场规律：筹码分布与股价关系', '通过长期观察发现，当筹码高度集中在某一价格区间（单峰密集），且主力持仓比例超过50%时，突破该区间后往往有较大涨幅。', 'knowledge', '{筹码分布,主力,市场规律}', 'web-test', '''且主力持仓比例超过50'':6B ''单峰密集'':5B ''市场规律'':1A ''当筹码高度集中在某一价格区间'':4B ''时'':7B ''突破该区间后往往有较大涨幅'':8B ''筹码分布与股价关系'':2A ''通过长期观察发现'':3B', '2026-08-18 22:30:54.30188', '2026-08-18 22:34:43.279832', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('932d2678-d710-4c00-ab0d-da00c1335eef', '决策记录：新能源板块轮动策略', '8月初采用板块轮动策略，从锂电池龙头（宁德时代）切换到整车龙头（比亚迪）。理由是锂电池板块涨幅过大，资金开始向下游转移。', 'decision', '{板块轮动,新能源,策略}', 'web-test', '''8月初采用板块轮动策略'':3B ''从锂电池龙头'':4B ''决策记录'':1A ''切换到整车龙头'':6B ''宁德时代'':5B ''新能源板块轮动策略'':2A ''比亚迪'':7B ''理由是锂电池板块涨幅过大'':8B ''资金开始向下游转移'':9B', '2026-08-18 22:30:54.30188', '2026-08-18 22:34:43.279832', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('89d96206-0372-4a1e-8f1b-ca2a2242f030', '数据洞察：成交量与趋势反转', '统计2024年上半年数据发现：在趋势末期，当成交量连续3日放大超过前5日均量的150%，且股价涨幅不足3%时，有78%的概率在5日内出现反转。', 'data', '{数据分析,成交量,趋势反转}', 'web-test', '''且股价涨幅不足3'':6B ''在趋势末期'':4B ''当成交量连续3日放大超过前5日均量的150'':5B ''成交量与趋势反转'':2A ''数据洞察'':1A ''时'':7B ''有78'':8B ''的概率在5日内出现反转'':9B ''统计2024年上半年数据发现'':3B', '2026-08-18 22:30:54.30188', '2026-08-18 22:34:43.279832', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('32921479-fdee-4e48-8ad8-a68480ec1ef6', '失败教训：追高买入的风险', '6月底在新能源板块情绪高涨时追高买入多只个股，结果遭遇回调，损失8%。教训：不要在市场情绪极度乐观时追高，等待回调后再介入。', 'experience', '{失败教训,风险控制,追高}', 'web-test', '''6月底在新能源板块情绪高涨时追高买入多只个股'':3B ''不要在市场情绪极度乐观时追高'':7B ''失败教训'':1A ''损失8'':5B ''教训'':6B ''等待回调后再介入'':8B ''结果遭遇回调'':4B ''追高买入的风险'':2A', '2026-08-18 22:30:54.30188', '2026-08-18 22:34:43.279832', '{}');
