INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('03743094-e0b6-42d8-a1db-ded3340cc977', '验收发现架构断层（2026-08-13 批次6探针）：daily_recall_audit 任务（A', '{"kind": "episode", "scope": "global", "status": "active", "confidence": 0.3, "source": "agent", "provenance": {"channel": "terminal", "session_id": "bootstrap", "session_kind": "user"}, "payload": {"category": "fact"}, "body": "验收发现架构断层（2026-08-13 批次6探针）：daily_recall_audit 任务（A1-T2 记忆召回审计，cron 0 19 * * *）定义在 agent-ts/src/services/scheduler/tasks/agent-decision-tasks.ts 并注册到 agent 内存调度器（InMemorySchedulerStore，字符串ID task-daily_recall_audit-{ts}），但 scheduler_manage 工具只代理 quantsys-v2 后端调度器（/api/scheduler/tasks，整数ID，共40个任务）。两个调度器无同步——v2 的 40 个任务中无 daily_recall_audit，无法通过 scheduler_manage trigger（报 404 invalid literal for int）。修复方案：①v2后端补注册同名任务；②scheduler_manage 扩展支持 agent 内存调度器。同类任务 morning_ai_analysis/realtime_quick_check/daily_ai_review/weekly_evolution/weekly_memory_distill 预计同样只在内存调度器中。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:59}', NULL, '''-08'':3A,36B ''-13'':4A,37B ''/api/scheduler/tasks'':74B ''/src/services/scheduler/tasks/agent-decision-tasks.ts'':54B ''0'':48B ''0.3'':18B ''19'':49B ''2026'':2A,35B ''40'':80B ''404'':90B ''a'':10A ''a1'':44B ''a1-t2'':43B ''active'':16B ''agent'':20B,52B,56B,100B ''agent-ts'':51B ''ai'':104B ''analysis/realtime_quick_check/daily_ai_review/weekly_evolution/weekly_memory_distill'':105B ''audit'':8A,41B,64B,84B ''body'':33B ''bootstrap'':26B ''category'':31B ''channel'':22B ''confidence'':17B ''cron'':47B ''daily'':6A,39B,62B,82B ''episode'':12B ''fact'':32B ''for'':93B ''global'':14B ''id'':25B ''inmemoryschedulerstore'':58B ''int'':94B ''invalid'':91B ''kind'':11B,28B ''literal'':92B ''manage'':68B,87B,98B ''morning'':103B ''payload'':30B ''provenance'':21B ''quantsys'':71B ''quantsys-v2'':70B ''recall'':7A,40B,63B,83B ''scheduler'':67B,86B,97B ''scope'':13B ''session'':24B,27B ''