INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('28ce7212-221c-4d11-bd97-6e8cccb00c9d', '每日召回审计日报 2026-08-13', '{"kind": "episode", "scope": "global", "status": "testing", "confidence": 0.3, "source": "agent", "provenance": {"channel": "scheduler", "session_id": "daily_recall_audit", "session_kind": "scheduled-task"}, "payload": {"category": "daily-recall-audit"}, "body": "每日召回审计日报 2026-08-13：总数14，注入率64%（9注入/5抑制），抑制率36%（全部 empty-result，无分数阈值抑制）。标注 relevant 14条/irrelevant 1条（agent feedback，未覆盖 human）。关键发现：①scheduled-task 命中分数系统性偏低（0.016-0.031，远低于0.6阈值）仍全部注入，长任务 prompt 稀释语义相似度，内容抽查 14/15 相关，仅 memory 59（调度任务定义）离题；②早盘分析同 prompt 在 20:37 有候选、21:04 被 empty-result 抑制，召回结果不稳定；③评分直方图两极分化（0.0-0.1 共15 hit vs 0.9-1.0 共10 hit），wake-event/interactive-chat 高质量、scheduled-task 低质量；④本次审计会话 memory_write/memory_search 均报 MemoryProvider not initialized（scheduled-task 会话未初始化 provider）。建议：为 scheduled-task flow 设置分数下限（如 0.1）过滤纯 token 噪声；排查 bm25 索引时效性（新写入记忆当日可能未入索引）；为任务型长 prompt 考虑按记忆 category/scope 预过滤；修复 scheduled-task 会话的 MemoryProvider 初始化。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:61}', NULL, '''-0.031'':63B ''-0.1'':94B ''-08'':3A,37B ''-1.0'':99B ''-13'':4A,38B ''/interactive-chat'':105B ''0.0'':93B ''0.016'':62B ''0.1'':131B ''0.3'':12B ''0.9'':98B ''04'':85B ''14/15'':71B ''14条/irrelevant'':51B ''1条'':52B ''20'':81B ''2026'':2A,36B ''21'':84B ''37'':82B ''59'':75B ''9注入/5'':41B ''agent'':14B,53B ''audit'':22B,33B ''bm25'':136B ''body'':34B ''category'':29B ''category/scope'':142B ''channel'':16B ''confidence'':11B ''daily'':20B,31B ''daily-recall-audit'':30B ''empty'':46B,88B ''empty-result'':45B,87B ''episode'':6B ''event'':104B ''feedback'':54B ''flow'':128B ''global'':8B ''hit'':96B,101B ''human'':56B ''id'':19B ''initialized'':117B ''kind'':5B,24B ''memory'':74B,112B ''memoryprovider'':115B,149B ''not'':116B ''payload'':28B ''prompt'':68B,79B,140B ''provenance'':15B ''provid