INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('d849b5c2-2a04-4938-b644-b1d4109179a2', '早盘复核: 恐慌底缩量未确认, 保持现金纪律放弃弱信号', '{"kind": "episode", "scope": "global", "status": "active", "confidence": 0.3, "source": "agent", "provenance": {"channel": "api", "session_id": "morning_analysis_20260813", "session_kind": "cron"}, "payload": {}, "body": "2026-08-13 早盘分析(第2轮复核)维持观望：市场恐慌底(恐惧指数30)+机构悄悄建仓+30亿构成收割窗口，但成交量萎缩=底部未确认。机会扫描Top3(德业86/云铝82/今世缘80)均为价值/周期股，与当前成长风格47%不匹配且主力净流出(德业-0.52亿/云铝-1.35亿)，今世缘当日刚+13%止盈卖出回购即追高。决策：不买不卖，保持49%现金待命，等≥85分且带资金流入+量能确认的确定性信号。教训：恐慌底的价值股高分常是风格错配+资金流出的陷阱，缩量阶段不追涨。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:62}', NULL, '''+13'':55B ''+30'':36B ''-0.52'':49B ''-08'':28B ''-1.35'':52B ''-13'':29B ''0.3'':11B ''2026'':27B ''20260813'':21B ''85分且带资金流入'':62B ''active'':9B ''agent'':13B ''analysis'':20B ''api'':16B ''body'':26B ''channel'':15B ''confidence'':10B ''cron'':24B ''episode'':5B ''global'':7B ''id'':18B ''kind'':4B,23B ''morning'':19B ''payload'':25B ''provenance'':14B ''scope'':6B ''session'':17B,22B ''source'':12B ''status'':8B ''不买不卖'':58B ''不匹配且主力净流出'':47B ''与当前成长风格47'':46B ''云铝'':51B ''云铝82'':42B ''亿'':50B,53B ''亿构成收割窗口'':37B ''今世缘80'':43B ''今世缘当日刚'':54B ''但成交量萎缩'':38B ''保持49'':59B ''保持现金纪律放弃弱信号'':3A ''决策'':57B ''周期股'':45B ''均为价值'':44B ''市场恐慌底'':33B ''底部未确认'':39B ''德业'':48B ''德业86'':41B ''恐惧指数30'':34B ''恐慌底的价值股高分常是风格错配'':65B ''恐慌底缩量未确认'':2A ''教训'':64B ''早盘分析'':30B ''早盘复核'':1A ''机会扫描top3'':40B ''机构悄悄建仓'':35B ''止盈卖出回购即追高'':56B ''现金待命'':60B ''第2轮复核'':31B ''等'':61B ''维持观望'':32B ''缩量阶段不追涨'':67B ''资金流出的陷阱'':66B ''量能确认的确定性信号'':63B', '2026-08-25 21:21:30.487927', '2026-08-25 21:21:30.487927', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('989abd24-e6e9-4d8e-879c-87924f18dc95', 'morning_analysis重复推送去重+持仓观望纪律(2026-08-13)', '{"kind": "episode", "scope": "global", "status": "testing", "confidence": 0.7, "source": "agent", "provenance": {"flow": "morning_analysis", "channel": "scheduler", "session_kind": "scheduled-task"}, "payload": {}, "body": "2026-08-13早盘分析任务当晚被重复推送4次(20:40补跑/21:07首轮/21:43第2轮/22:05第3轮)，与daily_review同晚4次重复一致。处理：每轮核对状态未变(总资产103904/现金49.1%/持仓格力-0.08%+歌尔-1.79%)即record skip_duplicate，不做重复交易、不重发飞书、不重复写经验。持仓观望纪律：格力弱势横盘8天但无止损信号(仅-0.08%)不割；歌尔分批建仓计划内(-1.79%未触-4.5%止损)持有；49%现金待命等恐慌底部量能放大确认后再低吸。建议后端按trade_date对morning_analysis去重。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:63}', NULL, '''-0.08'':46B,58B ''-08'':5A,31B ''-1.79'':48B,61B ''-13'':6A,32B ''-4.5'':63B ''0.7'':14B ''05第3轮'':38B ''07首轮/21'':36B ''20'':34B ''2026'':4A,30B ''40补跑/21'':35B ''43第2轮/22'':37B ''49'':66B ''agent'':16B ''analysis'':20B ''analysis去重'':70B ''analysis重复推送去重'':2A ''body'':29B ''channel'':21B ''confidence'':13B ''date对morning'':69B ''duplicate'':51B ''episode'':8B ''flow'':18B ''global'':10B ''kind'':7B,24B ''morning'':1A,19B ''payload'':28B ''provenance'':17B ''review同晚4次重复一致'':40B ''scheduled'':26B ''scheduled-task'':25B ''scheduler'':22B ''scope'':9B ''session'':23B ''skip'':50B ''source'':15B ''status'':11B ''task'':27B ''testing'':12B ''不做重复交易'':52B ''不割'':59B ''不重发飞书'':53B ''不重复写经验'':54B ''与daily'':39B ''仅'':57B ''即record'':49B ''处理'':41B ''建议后端按trade'':68B ''总资产103904'':43B ''持仓格力'':45B ''持仓观望纪律'':3A,55B ''持有'':65B ''早盘分析任务当晚被重复推送4次'':33B ''未触'':62B ''格力弱势横盘8天但无止损信号'':56B ''歌尔'':47B ''歌尔分批建仓计划内'':60B ''止损'':64B ''每轮核对状态未变'':42B ''现金49.1'':44B ''现金待命等恐慌底部量能放大确认后再低吸'':67B', '2026-08-25 21:21:30.489908', '2026-08-25 21:21:30.489908', '{}');
