INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('8f4a00d3-2a94-4edc-9568-9bfea2b0871e', 'browser 工具使用经验：Bing 搜索(search action)返回大量 JS 噪音且结果', '{"kind": "episode", "scope": "global", "status": "active", "confidence": 0.3, "source": "agent", "provenance": {"channel": "terminal", "session_id": "default", "session_kind": "user"}, "payload": {"category": "fact"}, "body": "browser 工具使用经验：Bing 搜索(search action)返回大量 JS 噪音且结果不相关(返回泰国网站)；百度网页搜索有滑块验证码无法自动化；财联社 cls.cn/telegraph 可直接抓取实时电报(行情快照+板块异动)，但\"加载更多\"按钮点击无效，cls 搜索页按相关度排序返回旧闻。查当日盘面原因应直接抓财联社电报 + 东方财富收评文章。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:76}', NULL, '''/telegraph'':47B ''0.3'':17B ''action'':6A,38B ''active'':15B ''agent'':19B ''bing'':3A,35B ''body'':32B ''browser'':1A,33B ''category'':30B ''channel'':21B ''cls'':54B ''cls.cn'':46B ''cls.cn/telegraph'':45B ''confidence'':16B ''default'':25B ''episode'':11B ''fact'':31B ''global'':13B ''id'':24B ''js'':8A,40B ''kind'':10B,27B ''payload'':29B ''provenance'':20B ''scope'':12B ''search'':5A,37B ''session'':23B,26B ''source'':18B ''status'':14B ''terminal'':22B ''user'':28B ''东方财富收评文章'':57B ''但'':51B ''加载更多'':52B ''可直接抓取实时电报'':48B ''噪音且结果'':9A ''噪音且结果不相关'':41B ''工具使用经验'':2A,34B ''按钮点击无效'':53B ''搜索'':4A,36B ''搜索页按相关度排序返回旧闻'':55B ''板块异动'':50B ''查当日盘面原因应直接抓财联社电报'':56B ''百度网页搜索有滑块验证码无法自动化'':43B ''行情快照'':49B ''财联社'':44B ''返回大量'':7A,39B ''返回泰国网站'':42B', '2026-08-25 21:21:30.512765', '2026-08-25 21:21:30.512765', '{}');
