INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('9f8a570c-610a-43e2-bcc0-0a16c40840ad', 'RFC 003 盈利路线图（docs/rfcs/003-profitability-roadmap.', '{"kind": "episode", "scope": "global", "status": "testing", "confidence": 0.8, "source": "agent", "provenance": {"channel": "dsh", "session_kind": "agent"}, "payload": {"tags": ["RFC003", "盈利路线图", "因子管线", "model_predict", "2026-08-20"], "namespace": "decision"}, "body": "RFC 003 盈利路线图（docs/rfcs/003-profitability-roadmap.md，2026-08-20 创建）：PI Investment 通往股市盈利的 6 阶段计划。原则：盈利=数据地基×策略优势×风控纪律×反馈学习（乘法），不跳阶段、一切留痕。当前基线短板：S1 model_predict 恒等输出（预测为零）、S2 opponent_behavior 数据不可信、S3 因子两代管线并存（大写因子冻于 2026-05-20，新管线历史仅12天）、S4 策略未验证。阶段：P1 数据地基（过滤死因子/历史回填/死数据归档/新鲜度门禁）→ P2 策略验证 → P3 模型重建 → P4 模拟盘实战 → P5 归因迭代 → P6 资金放大（门槛制）。当前处于 Phase 1 未开始。每次推进要更新该文档勾选状态。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:79}', NULL, '''-05'':70B ''-08'':29B,39B ''-20'':30B,40B,71B ''0.8'':12B ''003'':2A,35B ''1'':95B ''2026'':28B,38B,69B ''6'':45B ''agent'':14B,20B ''behavior'':64B ''body'':33B ''channel'':16B ''confidence'':11B ''decision'':32B ''docs/rfcs/003-profitability-roadmap'':4A ''docs/rfcs/003-profitability-roadmap.md'':37B ''dsh'':17B ''episode'':6B ''global'':8B ''investment'':43B ''kind'':5B,19B ''model'':26B,58B ''namespace'':31B ''opponent'':63B ''p1'':76B ''p2'':82B ''p3'':84B ''p4'':86B ''p5'':88B ''p6'':90B ''payload'':21B ''phase'':94B ''pi'':42B ''predict'':27B,59B ''provenance'':15B ''rfc'':1A,34B ''rfc003'':23B ''s1'':57B ''s2'':62B ''s3'':66B ''s4'':73B ''scope'':7B ''session'':18B ''source'':13B ''status'':9B ''tags'':22B ''testing'':10B ''一切留痕'':55B ''不跳阶段'':54B ''乘法'':53B ''创建'':41B ''历史回填'':79B ''原则'':47B ''反馈学习'':52B ''因子两代管线并存'':67B ''因子管线'':25B ''大写因子冻于'':68B ''归因迭代'':89B ''当前基线短板'':56B ''当前处于'':93B ''恒等输出'':60B ''数据不可信'':65B ''数据地基'':49B,77B ''新管线历史仅12天'':72B ''新鲜度门禁'':81B ''未开始'':96B ''模型重建'':85B ''模拟盘实战'':87B ''死数据归档'':80B ''每次推进要更新该