INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('3326becc-c811-4751-b1c3-550715ddfbb4', '分工决策（2026-08-20，用户指定）：本 agent（agent-dh Web 会话）专注"如', '{"kind": "episode", "scope": "global", "status": "testing", "confidence": 0.8, "source": "agent", "provenance": {"channel": "dsh", "session_kind": "agent"}, "payload": {"tags": ["分工", "RFC003", "2026-08-20"], "namespace": "decision"}, "body": "分工决策（2026-08-20，用户指定）：本 agent（agent-dh Web 会话）专注\"如何在股市挣钱\"——市场分析、策略研究与验证、信号扫描、盯盘执行、交易复盘、推进 RFC 003 的 P2/P4/P5 阶段；基础设施修复（因子管线 P1、model_predict 恒等 S1、opponent_behavior S2、后端改动）由其他窗口 agent 完成，本 agent 不碰后端代码。RFC 003 文档已合并 main（commit 0b464c02）。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:80}', NULL, '''-08'':3A,36B,43B ''-20'':4A,37B,44B ''0.8'':22B ''003'':62B,84B ''0b464c02'':88B ''2026'':2A,35B,42B ''agent'':7A,9A,24B,30B,47B,49B,78B,81B ''agent-dh'':8A,48B ''behavior'':74B ''body'':40B ''channel'':26B ''commit'':87B ''confidence'':21B ''decision'':39B ''dh'':10A,50B ''dsh'':27B ''episode'':16B ''global'':18B ''kind'':15B,29B ''main'':86B ''model'':69B ''namespace'':38B ''opponent'':73B ''p1'':68B ''p2/p4/p5'':64B ''payload'':31B ''predict'':70B ''provenance'':25B ''rfc'':61B,83B ''rfc003'':34B ''s1'':72B ''s2'':75B ''scope'':17B ''session'':28B ''source'':23B ''status'':19B ''tags'':32B ''testing'':20B ''web'':11A,51B ''不碰后端代码'':82B ''专注'':13A,53B ''交易复盘'':59B ''会话'':12A,52B ''信号扫描'':57B ''分工'':33B ''分工决策'':1A,41B ''后端改动'':76B ''因子管线'':67B ''基础设施修复'':66B ''如'':14A ''如何在股市挣钱'':54B ''完成'':79B ''市场分析'':55B ''恒等'':71B ''推进'':60B ''文档已合并'':85B ''本'':6A,46B,80B ''用户指定'':5A,45B ''由其他窗口'':77B ''的'':63B ''盯盘执行'':58B ''策略研究与验证'':56B ''阶段'':65B', '2026-08-25 21:21:30.520326', '2026-08-25 21:21:30.520326', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('ea9588a3-d2d4-4c15-a3fa-55c78912ed86', 'RFC 004 盈利引擎系统设计（docs/rfcs/004-profit-engine-desig', '{"kind": "episode", "scope": "global", "status": "testing", "confidence": 0.8, "source": "agent", "provenance": {"channel": "dsh", "session_kind": "agent"}, "payload": {"tags": ["RFC004", "盈利引擎", "模块设计", "2026-08-20"], "namespace": "decision"}, "body": "RFC 004 盈利引擎系统设计（docs/rfcs/004-profit-engine-design.md，2026-08-20）：8 大模块。M0 数据地基（其他agent）、M1 市场感知（regime落库/主线识别）、M2 标的工厂（主线→标的映射/排雷）、M3 信号择时（信号分级ABC/策略回测）、M4 仓位风控（regime仓位映射/回撤熔断）、M5 执行（滑点建模）、M6 学习飞轮（归因/决策前强制检索/周报——护城河）、M7 对手博弈情报（差异化核心，需真实数据源）、M8 预测引擎（后置依赖M0）。建设顺序：第一波 M0+M1+M6+M4 并行；第二波 M2/M3/M7；第三波 M8。下一步：评审后按模块拆工单。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:81}', NULL, '''-08'':27B,37B ''-20'':28B,38B ''0.8'':12B ''004'':2A,33B ''2026'':26B,36B ''8'':39B ''agent'':14B,20B ''body'':31B ''channel'':16B ''confidence'':11B ''decision'':30B ''docs/rfcs/004-profit-engine-desig'':4A ''docs/rfcs/004-profit-engine-design.md'':35B ''dsh'':17B ''episode'':6B ''global'':8B ''kind'':5B,19B ''m0'':41B,79B ''m1'':44B,80B ''m2'':48B ''m2/m3/m7'':85B ''m3'':53B ''m4'':57B,82B ''m5'':61B ''m6'':64B,81B ''m7'':70B ''m8'':74B,87B ''namespace'':29B ''payload'':21B ''provenance'':15B ''regime仓位映射'':59B ''regime落库'':46B ''rfc'':1A,32B ''rfc004'':23B ''scope'':7B ''session'':18B ''source'':13B ''status'':9B ''tags'':22B ''testing'':10B ''下一步'':88B ''主线'':50B ''主线识别'':47B ''仓位风控'':58B ''信号分级abc'':55B ''信号择时'':54B ''其他agent'':43B ''决策前强制检索'':67B ''后置依赖m0'':76B ''周报'':68B ''回撤熔断'':60B ''大模块'':40B ''学习飞轮'':65B ''对手博弈情报'':71B ''差异化核心'':72B ''市场感知'':45B ''并行'':83B ''建设顺序'':77B ''归因'':66B ''执行'':62B ''护城河'':69B ''排雷'':52B ''数据地基'':42B ''标的工厂'':49B ''标的映射'':51B ''模块设计'':25B ''滑点建模'':63B ''盈利引擎'':24B ''盈利引擎系统设计'':3A,34B ''第一波'':78B ''第三波'':86B ''第二波'':84B ''策略回测'':56B ''评审后按模块拆工单'':89B ''需真实数据源'':73B ''预