INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('09f3af72-cdbb-4c68-9754-baa77600d516', 'RFC 005 盈利引擎工单包（docs/rfcs/005-profit-engine-work-t', '{"kind": "episode", "scope": "global", "status": "testing", "confidence": 0.7, "source": "agent", "provenance": {"channel": "dsh", "session_kind": "agent"}, "payload": {"tags": ["RFC005", "工单", "2026-08-20"], "namespace": "decision"}, "body": "RFC 005 盈利引擎工单包（docs/rfcs/005-profit-engine-work-tickets.md）：8 模块 26 个工单，含负责方（挣钱线/基建线）、依赖、可执行验收命令。启动波次：立即开工 M0-1~4(基建)、M1-1(regime落库)、M4-1(仓位映射)、M6-1(决策前强制检索)、M3-1(信号分级)；M0-2 回填后开 M1-2/M2-1/M3-2/M7-2；历史≥120日后开 M8-2/M6-4。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:82}', NULL, '''-08'':26B ''-1'':47B,51B,54B,57B,60B ''-2'':63B,66B,71B ''-20'':27B ''/m2-1/m3-2/m7-2'':67B ''/m6-4'':72B ''0.7'':12B ''005'':2A,32B ''120日后开'':69B ''2026'':25B ''26'':37B ''8'':35B ''agent'':14B,20B ''body'':30B ''channel'':16B ''confidence'':11B ''decision'':29B ''docs/rfcs/005-profit-engine-work-t'':4A ''docs/rfcs/005-profit-engine-work-tickets.md'':34B ''dsh'':17B ''episode'':6B ''global'':8B ''kind'':5B,19B ''m0'':46B,62B ''m1'':50B,65B ''m3'':59B ''m4'':53B ''m6'':56B ''m8'':70B ''namespace'':28B ''payload'':21B ''provenance'':15B ''regime落库'':52B ''rfc'':1A,31B ''rfc005'':23B ''scope'':7B ''session'':18B ''source'':13B ''status'':9B ''tags'':22B ''testing'':10B ''~4'':48B ''个工单'':38B ''仓位映射'':55B ''依赖'':42B ''信号分级'':61B ''决策前强制检索'':58B ''历史'':68B ''可执行验收命令'':43B ''含负责方'':39B ''启动波次'':44B ''回填后开'':64B ''基建'':49B ''基建线'':41B ''工单'':24B ''挣钱线'':40B ''模块'':36B ''盈利引擎工单包'':3A,33B ''立即开工'':45B', '2026-08-25 21:21:30.523854', '2026-08-25 21:21:30.523854', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('eea802e9-134b-4040-b780-b931e2ecc466', '方向调整（2026-08-20 用户确认）：方案一自主能力体系从"DevOps 自愈"转向"自进化挣', '{"kind": "episode", "scope": "global", "status": "testing", "confidence": 0.9, "source": "agent", "provenance": {"channel": "dsh", "session_kind": "agent"}, "payload": {"tags": ["自进化", "RFC005", "方向调整", "提示词进化", "知识蒸馏", "2026-08-20"], "namespace": "decision"}, "body": "方向调整（2026-08-20 用户确认）：方案一自主能力体系从\"DevOps 自愈\"转向\"自进化挣钱 Agent\"。用户明确不要诊断 bug/生成代码/测试基础设施那一套，要的是：自我改提示词、交易规则自主增删、策略参数自主调整，通过回测+模拟盘验证后自动启用，目标是越炒股越会挣钱。硬约束：必须遵守 A 股交易规则（9:30-15:00 交易时段、T+1 等），宪法层不可进化。已产出 agent-dh/docs/rfcs/005-self-evolving-agent.md（基因组=提示词+规则+参数+蒸馏知识；闭环=交易打标→盘后归因→每日蒸馏→周末变异→回测/模拟盘选择→周一启用）。原 MASTER-PLAN v1/v2 的 Sprint 0-9 废弃。待用户评审 RFC 005 后从 Phase 1（基因组地基：版本化+决策打标+宪法层）开工。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:83}', NULL, '''+1'':72B ''-08'':3A,35B,42B ''-15'':68B ''-20'':4A,36B,43B ''-9'':101B ''/docs/rfcs/005-self-evolving-agent.md'':79B ''0'':100B ''0.9'':18B ''00'':69B ''005'':105B ''1'':108B ''2026'':2A,34B,41B ''30'':67B ''9'':66B ''a'':64B ''agent'':20B,26B,50B,77B ''agent-dh'':76B ''body'':39B ''bug'':52B ''channel'':22B ''confidence'':17B ''decision'':38B ''devops'':7A,46B ''dh'':78B ''dsh'':23B ''episode'':12B ''global'':14B ''kind'':11B,25B ''master'':95B ''master-plan'':94B ''namespace'':37B ''payload'':27B ''phase'':107B ''plan'':96B ''provenance'':21B ''rfc'':104B ''rfc005'':30B ''scope'':13B ''session'':24B ''source'':19B ''sprint'':99B ''status'':15B ''t'':71B ''tags'':28B ''testing'':16B ''v1/v2'':97B ''交易打标'':86B ''交易时段'':70B ''交易规则自主增删'':57B ''决策打标'':111B ''原'':93B ''参数'':83B ''后从'':106B ''周一启用'':92B ''周末变异'':89B ''回测'':90B ''基因组'':80B ''基因组地基'':109B ''宪法层'':112B ''宪法层不可进化'':74B ''已产出'':75B ''废弃'':102B ''开工'':113B ''待用户评审'':103B ''必须遵守'':63B ''提示词'':81B ''提示词进化'':32B ''方向调整'':1A,31B,40B ''方案一自主能力体系从'':6A,45B ''模拟盘选择'':91B ''