INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('b1dd9465-62f2-416d-9f0c-4bad001035c0', 'RFC 005 补充决策（2026-08-20 用户）：自进化 Agent 并非禁止改代码——"改代', '{"kind": "episode", "scope": "global", "status": "testing", "confidence": 0.85, "source": "agent", "provenance": {"channel": "dsh", "session_kind": "agent"}, "payload": {"tags": ["自进化", "RFC005", "能力进化", "代码进化", "2026-08-20"], "namespace": "decision"}, "body": "RFC 005 补充决策（2026-08-20 用户）：自进化 Agent 并非禁止改代码——\"改代码是因为代码限制了能力\"。进化分两层：①认知进化（提示词/规则/参数/蒸馏知识）是主体，高频自动；②能力进化（改代码）按需触发，判定标准是\"认知被代码卡脖子\"（缺工具、数据不足、工具输出不可用于决策、重复认知劳动可固化）。能力进化门槛更高：自动测试→self_restart wip 部署→验证→合并，交易/风控/资金路径必须人工审批，且不得绕过宪法层硬校验。原 Master Plan Sprint 0-9 作为独立计划废弃，拒绝\"为自愈而自愈\"。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:84}', NULL, '''-08'':5A,35B,44B ''-20'':6A,36B,45B ''-9'':85B ''0'':84B ''0.85'':19B ''005'':2A,41B ''2026'':4A,34B,43B ''agent'':9A,21B,27B,48B ''body'':39B ''channel'':23B ''confidence'':18B ''decision'':38B ''dsh'':24B ''episode'':13B ''global'':15B ''kind'':12B,26B ''master'':81B ''namespace'':37B ''payload'':28B ''plan'':82B ''provenance'':22B ''restart'':71B ''rfc'':1A,40B ''rfc005'':31B ''scope'':14B ''self'':70B ''session'':25B ''source'':20B ''sprint'':83B ''status'':16B ''tags'':29B ''testing'':17B ''wip'':72B ''且不得绕过宪法层硬校验'':79B ''为自愈而自愈'':88B ''交易'':76B ''代码进化'':33B ''作为独立计划废弃'':86B ''判定标准是'':62B ''原'':80B ''参数'':55B ''合并'':75B ''工具输出不可用于决策'':66B ''并非禁止改代码'':10A,49B ''拒绝'':87B ''按需触发'':61B ''提示词'':53B ''改代'':11A ''改代码'':60B ''改代码是因为代码限制了能力'':50B ''数据不足'':65B ''是主体'':57B ''用户'':7A,46B ''缺工具'':64B ''能力进化'':32B,59B ''能力进化门槛更高'':68B ''自动测试'':69B ''自进化'':8A,30B,47B ''蒸馏知识'':56B ''补充决策'':3A,42B ''规则'':54B ''认知被代码卡脖子'':63B ''认知进化'':52B ''资金路径必须人工审批'':78B ''进化分两层'':51B ''部署'':73B ''重复认知劳动可固化'':67B ''风控'':77B ''验证'':74B ''高频自动'':58B', '2026-08-25 21:21:30.527369', '2026-08-25 21:21:30.527369', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('d54ae9bf-64e8-471e-8e21-98fa0f16f386', 'P2 策略验证初步进展（2026-08-20）：
- 完成回测基础设施验证：API POST /ap', '{"kind": "episode", "scope": "global", "status": "testing", "confidence": 0.7, "source": "agent", "provenance": {"channel": "dsh", "session_kind": "agent"}, "payload": {"tags": ["P2", "策略验证", "回测", "2026-08-20"], "namespace": "decision"}, "body": "P2 策略验证初步进展（2026-08-20）：\n- 完成回测基础设施验证：API POST /api/indicators/backtest 工作正常，返回 sharpe/return/drawdown/winRate 等指标\n- 实测案例：策略 365（趋势动量跟踪）× 002241（歌尔）× 2025-06~2026-08（14个月）→ 3笔交易、-6.2%收益、夏普-0.32、最大回撤-12%、胜率33%\n- 发现问题：①单次回测耗时 60s+，批量回测（5策略×3环境×3股票=45次）需 45+ 分钟；②部分策略在稳健股票（如600519茅台）上信号稀少（0笔交易）；③需更长时间窗口（≥60交易日）保证统计意义\n- 已筛选候选策略：266趋势跟踪/365趋势动量/182震荡猎手/245通道波段/416均值回归（覆盖趋势/震荡/反转三类）\n- 下一步：①补充批量回测脚本（后台运行）；②定义标准测试环境（牛市2024-09~12、熊市2024-01~08、震荡2025全年）；③统计达标策略数量（夏普>1、回撤<15%）；④淘汰不达标策略"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:85}', NULL, '''-0.32'':66B ''-01'':111B ''-06'':59B ''-08'':4A,32B,40B ''-09'':108B ''-12'':68B ''-20'':5A,33B,41B ''-6.2'':63B ''/182'':93B ''/245'':95B ''/416'':97B ''/ap'':9A ''/api/indicators/backtest'':46B ''0.7'':17B ''002241'':56B ''0笔交易'':85B ''1'':116B ''14个月'':61B ''15'':118B ''2025'':58B ''2026'':3A,31B,39B ''266趋势跟踪/365'':91B ''365'':54B ''3环境'':76B ''3笔交易'':62B ''3股票'':77B ''45'':80B ''45次'':78B ''5策略'':75B ''60s'':73B ''60交易日'':87B ''agent'':19B,25B ''api'':7A,44B ''body'':36B ''channel'':21B ''confidence'':16B ''decision'':35B ''dsh'':22B ''episode'':11B ''global'':13B ''kind'':10B,24B ''n'':42B,51B,70B,89B,102B ''namespace'':34B ''p2'':1A,28B,37B ''payload'':26B ''post'':8A,45B ''provenance'':20B ''scope'':12B ''session'':23B ''sharpe/return/drawdown/winrate'':49B ''source'':18B ''status'':14B ''tags'':27B ''testing'':15B ''~08'':112B ''~12'':109B ''~2026-08'':60B ''上信号稀少'':84B ''下一步'':103B ''保证统计意义'':88B ''分钟'':81B ''单次回测耗时'':72B ''反转三类'':101B ''发现问题'':71B ''后台运行'':105B ''回撤'':117B ''回测'':30B ''均值回归'':98B ''夏普'':65B,115B ''如600519茅台'':83B ''完成回测基础设施验证'':6A,43B ''定义标准测试环境'':106B ''实测案例'':52B ''工作正常'':47B ''已筛选候选策略'':90B ''批量回测'':74B ''收益'':6