INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('07e381de-5c7c-4548-bb92-f867b1738d77', 'P0-1 审计结论与 P0-2 方案（2026-08-20）：审计 RFC 006 发现 6 项问题', '{"kind": "episode", "scope": "global", "status": "testing", "confidence": 0.8, "source": "agent", "provenance": {"channel": "dsh", "session_kind": "agent"}, "payload": {"tags": ["RFC006", "RFC007", "P0-1审计", "P0-2", "genome", "2026-08-20"], "namespace": "decision"}, "body": "P0-1 审计结论与 P0-2 方案（2026-08-20）：审计 RFC 006 发现 6 项问题已修订入文档 §8：①self_system_prompt 工具现行 bug（返回 value is not lossless JSON，验收依赖它，列为 Step 0 必修）；②配置路径不能用 ~（Node 不展开，用 os.homedir()）；③{{genome_version}} 变量 provider 禁止返回 undefined（renderPrompt 会抛异常致全站请求失败）；④段内容须过花括号安检（{{ }} 会被当变量插值）；⑤重启回滚盲区——profile 侧 cordis.patch.yml/package.json 不在 self_restart git 安全网内，重启前须手动备份，启动失败先恢复备份；⑥验收措辞不写死工具总数。P0-2 方案已产出 agent-dh/docs/rfcs/007-genome-manager.md：4 个写工具（genome_update/genome_rollback/genome_history/genome_diff），版本模型=基因组代数 gN + 段版本，执行流含写锁→校验→git commit→热替换→渲染金丝雀（失败自动还原），6 条安全不变量（宪法永不变/永远可渲染/历史只增/单变量/可归因/无并发写）。预计 2-3 天。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:86}', NULL, '''-08'':8A,43B,55B ''-1'':2A,49B ''-2'':5A,40B,52B,110B ''-20'':9A,44B,56B ''-3'':141B ''/docs/rfcs/007-genome-manager.md'':115B ''/package.json'':100B ''0'':78B ''0.8'':23B ''006'':12A,59B ''1审计'':38B ''2'':140B ''2026'':7A,42B,54B ''4'':116B ''6'':14A,61B,131B ''8'':63B ''agent'':25B,31B,113B ''agent-dh'':112B ''body'':47B ''bug'':68B ''channel'':27B ''commit'':127B ''confidence'':22B ''cordis.patch.yml'':99B ''cordis.patch.yml/package.json'':98B ''decision'':46B ''dh'':114B ''dsh'':28B ''episode'':17B ''genome'':41B,85B,118B ''git'':104B,126B ''global'':19B ''gn'':122B ''is'':71B ''json'':74B ''kind'':16B,30B ''lossless'':73B ''namespace'':45B ''node'':81B ''not'':72B ''os.homedir'':84B ''p0'':1A,4A,37B,39B,48B,51B,109B ''p0-1审计'':36B ''payload'':32B ''profile'':96B ''prompt'':66B ''provenance'':26B