INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('31ba6c55-ccb9-42b6-8c8c-63ba1ff7fe0b', 'P0-1 完成验收（2026-08-20）：基因组插件（genome）接入成功，提示词段切分上线。验', '{"kind": "episode", "scope": "global", "status": "testing", "confidence": 0.9, "source": "agent", "provenance": {"channel": "dsh", "session_kind": "agent"}, "payload": {"tags": ["P0-1", "genome", "验收通过", "RFC006", "2026-08-20"], "namespace": "decision"}, "body": "P0-1 完成验收（2026-08-20）：基因组插件（genome）接入成功，提示词段切分上线。验收通过 6 条标准：①genome_list/genome_read 工具注册；②4个段文件就位（constitution 宪法层锁定 + principles/rules/lessons 可进化）；③genome.json 配置正确（g1，4段元数据含 order/class/locked）；④段文件存在且非空（constitution 10行/principles 8行/rules 6行/lessons 5行）；⑤git 独立版本库初始化（首次提交 0e643b0）；⑥constitution 内容逐字正确（6条宪法：交易时段/T+1/仓位/止损/数据驱动/零交易合法）。审计修复 A-1~A-5 全部落实。Profile 重启成功运行（PID 13722/19636）。代码已合并 main（commits: 33fb1347 systemPrompt依赖修复 + 40c71a5d merge + 6f212f71 genome实现 + 93211d9c lifecycle修复）。下一步：P0-2 genome_manager 工具化（RFC 007：版本快照/段更新/回滚/changelog）。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:89}', NULL, '''+1'':83B ''-08'':5A,36B,45B ''-1'':2A,31B,42B,90B ''-2'':110B ''-20'':6A,37B,46B ''/changelog'':119B ''/t'':82B ''0.9'':19B ''007'':115B ''0e643'':76B ''10行/principles'':69B ''13722/19636'':96B ''2026'':4A,35B,44B ''33fb1347'':100B ''40c71a5d'':102B ''4个段文件就位'':57B ''4段元数据含'':65B ''5行'':72B ''6'':52B ''6f212f71'':104B ''6条宪法'':80B ''6行/lessons'':71B ''8行/rules'':70B ''93211d9c'':106B ''a'':89B ''agent'':21B,27B ''b0'':77B ''body'':40B ''channel'':23B ''commits'':99B ''confidence'':18B ''constitution'':58B,68B,78B ''decision'':39B ''dsh'':24B ''episode'':13B ''g1'':64B ''genome'':8A,32B,48B,54B,111B ''genome.json'':62B ''genome实现'':105B ''git'':73B ''global'':15B ''kind'':12B,26B ''lifecycle修复'':107B ''list/genome_read'':55B ''main'':98B ''manager'':112B ''merge'':103B ''namespace'':38B ''order/class/locked'':66B ''p0'':1A,30B,41B,109B ''payload'':28B ''pid'':9