INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('235a37f7-0198-4cf3-a8b3-0a24a1e73bcd', 'RFC 003 盈利路线图审核结论（2026-08-20 晚，agent-dh）：实测核验文档声明基', '{"kind": "episode", "scope": "global", "status": "testing", "confidence": 0.8, "source": "agent", "provenance": {"channel": "dsh", "session_kind": "agent"}, "payload": {"tags": ["RFC003", "审核", "盈利路线图", "因子管线", "2026-08-20"], "namespace": "decision"}, "body": "RFC 003 盈利路线图审核结论（2026-08-20 晚，agent-dh）：实测核验文档声明基本属实无夸大。P1：1.1/1.2 达标（主力因子230交易日×5514股）；1.3 文档声称\"未归档\"错误——factor_values_legacy_20260820 实际存在含1599万行；1.4 新鲜度门禁确实未做。新发现误导源：factor_calculate 对资金流覆盖外股票（如600519）返回 2026-07-02 陈旧零值且无 stale 标记，P1 严格验收未通过。P2：30回测文件齐全但0策略达标（文档诚实），验收标准被改写降低。P3：R3 诊断报告无留档文件，违反\"一切留痕\"。P4：账户实测完全吻合（104275.71），603369 今世缘300股订单待次日验证成交。待办：更正文档1.3、补R3报告、新增M0-5工单（资金流stale标记）、明日验证603369成交。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:96}', NULL, '''-02'':76B ''-07'':75B ''-08'':5A,35B,44B ''-20'':6A,36B,45B ''/1.2'':53B ''0.8'':19B ''003'':2A,41B ''1.1'':52B ''1.3'':57B ''1.4'':66B ''104275.71'':93B ''2026'':4A,34B,43B,74B ''20260820'':64B ''30回测文件齐全但0策略达标'':83B ''5514股'':56B ''5工单'':101B ''603369'':94B ''agent'':9A,21B,27B,48B ''agent-dh'':8A,47B ''body'':39B ''calculate'':70B ''channel'':23B ''confidence'':18B ''decision'':38B ''dh'':10A,49B ''dsh'':24B ''episode'':13B ''factor'':61B,69B ''global'':15B ''kind'':12B,26B ''legacy'':63B ''namespace'':37B ''p1'':51B,80B ''p2'':82B ''p3'':86B ''p4'':91B ''payload'':28B ''provenance'':22B ''r3'':87B ''rfc'':1A,40B ''rfc003'':30B ''scope'':14B ''session'':25B ''source'':20B ''stale'':78B ''status'':16B ''tags'':29B ''testing'':17B ''values'':62B ''一切留痕'':90B ''严格验收未通过'':81B ''主力因子230交易日'':55B ''今世缘300股订单待次日验证成交'':95B ''因子管线'':33B ''如600519'':72B ''实测核验文档声明基'':11A ''实测核验文档声明基本属实无夸大'':50B ''实际存在含1599万行'':65B ''审核'':31B ''对资金流覆盖外股票'':71B ''待办'':96B ''文档声称'':58B ''文档诚实'':84B ''新发现误导源'':68B ''新增m0'':100B ''新增m0-5工单