INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('5127852b-8845-4951-ab9c-cffa380c2a25', 'P0-2 验收通过（2026-08-20，agent-dh genome 插件）：RFC 007 的', '{"kind": "episode", "scope": "global", "status": "testing", "confidence": 0.85, "source": "agent", "provenance": {"channel": "dsh", "session_kind": "agent"}, "payload": {"tags": ["P0-2验收", "genome", "RFC007", "验收通过", "2026-08-20"], "namespace": "decision"}, "body": "P0-2 验收通过（2026-08-20，agent-dh genome 插件）：RFC 007 的 8 条标准全部 E2E 验证通过。验收中发现并由我修复 5 个问题：①阻断性——genome 插件用 ctx.on(''ready'') 注册段/工具，cordis 加载器下该事件不触发，导致插件静默不加载（所有其他插件都是构造函数同步注册）；修复为构造函数同步初始化+失败回退内置宪法段（宪法永不缺席）。②B-1 渲染金丝雀原是哑炮（assemble 未 await + renderPrompt 不是 service 方法而是包级导出，?.() 静默跳过）；修复为 await assemble + import { renderPrompt } from ''@deepseek-ai/dsh-system-prompt'' 真实试渲染，失败自动还原（rollback 路径同样补齐自动还原）。③B-2 git 提交在写 genome.json 之前导致 commit 里元数据落后一代、CHANGELOG.md 永不入库、commit 标签用旧代数；修复为先写 genome.json+CHANGELOG 再 git add -A 提交。④B-3 首次更新后回滚必失败（g1 init 无 history 条目）；修复为 init 写 history 条目 + getHistoricalSection 文件级历史兜底（第 N 次提交=vN）+ getPreviousSectionVersion 兜底 current-1。⑤B-4 genome_update 返回 undefined 字段触发 not lossless JSON；修复为按需拼装返回。附带成果：rules 段规范化为 R-001~R-004（归因可引用）、live 基因组库补 .gitignore 排除 genome.lock、最终基因组 g6（principles v5 原文、rules v2、constitution/lessons v1）。遗留：genome 包无单元测试（RFC 要求未落实）；rollback commit message 有冗余文案；基因组目录在 ~/.dsh-agent-dh/genome。检查点分支 agent-self/20260820-191258 已 self_finalize(merge)。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:99}', NULL, '''-001'':163B ''-08'':5A,40B,49B ''-1'':81B,147B ''-2'':2A,46B,106B ''-20'':6A,41B,50B ''-3'':126B ''-4'':149B ''/.dsh-agent-dh/genome'':190B ''/20260820-191258'':195B ''/dsh-system-prompt'':100B ''0.85'':22B ''007'':13A,57B ''2026'':4A,39B,48B ''2验收'':35B ''5'':64B ''8'':59B ''a'':123B ''add'':122B ''agent'':8A,24B,30B,52B,193B ''agent-dh'':7A,51B ''agent-self'':192B ''ai'':99B ''assemble'':83B,93B ''await'':85B,92