INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('2fb7502b-6401-455d-bcf8-05abe82522b4', 'P0-3 决策打标最终验收通过（2026-08-20 19:45，E2E 实证）：自动追踪全链路活了', '{"kind": "episode", "scope": "global", "status": "testing", "confidence": 0.9, "source": "agent", "provenance": {"channel": "dsh", "session_kind": "agent"}, "payload": {"tags": ["P0-3验收", "learning", "决策打标", "genome_context", "2026-08-20"], "namespace": "decision"}, "body": "P0-3 决策打标最终验收通过（2026-08-20 19:45，E2E 实证）：自动追踪全链路活了——opportunity_scan 调用 → tools/post-execute waterfall 拦截 → autoTrack → genome_context 打标 → createMemory 持久化 → memory_search 可召回（证据：experience id 101，payload.genome_context.genome_version=g6，tags 含 genome:g6，duration_ms/reward 正确）。验收过程中修复 learning 插件 3 个 bug（其他 agent 只做了代码审查没做 E2E，自报\"验收通过\"不可信）：①监听了 DSH 不存在的事件 tool/before|after-execute（从不触发），改为真实 waterfall 扩展点 tools/pre-execute/tools/post-execute（监听器铁律：必须原样返回 prev、绝不抛异常，否则工具调用本身被污染）；②persistExperience 丢弃 genome_context 字段；③调用 client 不存在的方法 writeMemory（应为 createMemory POST /api/memory），错误被静默 catch 吞掉。另：learning+evolver 插件此前未注册进 profile cordis.patch.yml（P1 交付物没在运行），本次已接入（symlink+package.json+patch.yml）。遗留改进项：①persistExperience 把整个工具结果（几十KB）塞进 content，应截断；②rules_used 仍是占位空数组，需从决策上下文提取 R-ID；③experience_distill/prompt_evolver/daily_distill（P1 三工具）已加载但只做过静态审查（evolver 走 genome_update 唯一写入口、dry_run 默认 true，设计合规）。修复在 agent-self/20260820-194428 检查点链。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:102}', NULL, '''-08'':5A,38B,47B ''-20'':6A,39B,48B ''-3'':2A,44B ''/20260820-194428'':174B ''/api/memory'':125B ''0.9'':19B ''101'':72B ''19'':7A,49B ''2026'':4A,37B,46B ''3'':86B ''3验收'':32B ''45'':8A,50B ''after'':101B ''after-execute'':100B ''agent'':21B,27B,90B,172B ''agent-self'':171B ''autotrack'':60B ''body'':42B ''bug'':88B ''catch'':127B ''channel'':23B ''client'':119B ''confidence'':18B ''content'':146B ''context'':36B,62B,116B ''cordis.patch.yml'':134B ''createmem