INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('8c98dcf6-27a1-4c0b-b1cf-4955e09b8e43', 'RFC003 审核问题修复完成（2026-08-20 深夜，commit dac1451a + c9', '{"kind": "episode", "scope": "global", "status": "testing", "confidence": 0.9, "source": "agent", "provenance": {"channel": "dsh", "session_kind": "agent"}, "payload": {"tags": ["RFC003", "RFC006", "segfault", "OpenMP", "model_predict", "S1修复", "2026-08-20"], "namespace": "decision"}, "body": "RFC003 审核问题修复完成（2026-08-20 深夜，commit dac1451a + c921ee77）：①模型训练 segfault 根因=torch/mlflow(via domain.quantlib.ml)+sklearn 三份 OpenMP 与 Homebrew libomp 混载，worker 线程崩于 __kmp_suspend_initialize_thread；修复=trainer.py xgboost 延迟导入 + application/services/__init__ 去掉 order_service 急切导入 + domain/quantlib/__init__ 改 PEP562 惰性导入 + 训练子进程隔离（tools/_train_worker.py）。②S1 恒等输出根因之二=预测用 FactorRegistry 128 因子而训练用 DB 29 因子，特征名不匹配全补零；修复=ml_predict 新增 DB 因子路径+训练时保存 scaler。新模型 lightgbm_20260820_195134 AUC 0.5565 过门禁，600519→0.2822/000001→0.6996 有区分度。③M0-5 资金流陈旧零值已有 stale 标记（600519 六因子 stale_days=30）。④1.4 因子新鲜度门禁上线（quality-report 的 factor_freshness 段，检出 adx/cci/ma60/mfi14/volatility_20）。⑤RFC 006 已设计（回测可信度+策略验证漏斗+evolution 修复+信号追踪）。教训：验收驱动修复极有效——审核发现的问题全部当日闭环。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:113}', NULL, '''-08'':4A,36B,44B ''-20'':5A,37B,45B ''-5'':115B ''/000001'':111B ''0.2822'':110B ''0.5565'':107B ''0.6996'':112B ''0.9'':17B ''006'':136B ''1.4'':124B ''128'':88B ''195134'':105B ''2026'':3A,35B,43B ''20260820'':104B ''29'':91B ''30'':123B ''600519'':109B,119B ''adx/cci/ma60/mfi14/volatility_20'':134B ''agent'':19B,25B ''application/services/__init__'':73B ''auc'':106B ''body'':40B ''c9'':9A ''c921ee77'':49B ''channel'':21B ''commit'':7A,47B ''confidence'':16B ''dac1451a'':8A,48B ''days'':122B ''db'':90B,98B ''decision'':39B ''domain.quantlib.ml'':55B ''domain/quantlib/__init__'':78B ''dsh'':22B ''episode'':11B ''evolution'':140B ''factor'':130B ''