INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('ca23d412-c7e0-4e46-9531-201c495fa008', 'RFC 003 二次验收结论（2026-08-20 20:15，复核 commit dac1451a', '{"kind": "episode", "scope": "global", "status": "testing", "confidence": 0.8, "source": "agent", "provenance": {"channel": "dsh", "session_kind": "agent"}, "payload": {"tags": ["RFC003", "二次验收", "model_predict", "S1", "2026-08-20"], "namespace": "decision"}, "body": "RFC 003 二次验收结论（2026-08-20 20:15，复核 commit dac1451a）：P1 数据地基✅通过（1.4 因子新鲜度门禁实测检出 adx/cci/ma60/mfi14/volatility_20 与 SQL 一致；M0-5 stale_factors 标记生效）。P3 ⚠️有条件通过：API 层 S1 修复属实（lightgbm latest：600519→0.2822/000001→0.6996），新模型 test AUC 0.5565 过门禁（training_report 复核一致，但 train 0.86 vs test 0.56 过拟合迹象、样本仅100股）。3 个阻断 agent 实际使用的问题：①DSH model_predict 的 model_id 被后端 ml_async 当 model_type 处理，传新模型ID报错\"没有可用的模型\"；②默认路径仍解析旧 xgboost_20260603 恒等 0.4659；③model_evaluate 传未知 model_id 静默回退旧模型评估不报错（险些误导验收）。P2 仍未通过。后续设计已有 RFC 006（回测可信度）和 RFC 008（P2 验证门）。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:118}', NULL, '''-08'':5A,36B,45B ''-20'':6A,37B,46B ''-5'':62B ''/000001'':76B ''0.2822'':75B ''0.4659'':117B ''0.5565'':81B ''0.56'':91B ''0.6996'':77B ''0.8'':19B ''0.86'':88B ''003'':2A,42B ''006'':129B ''008'':133B ''1.4'':55B ''15'':8A,48B ''20'':7A,47B ''2026'':4A,35B,44B ''20260603'':115B ''3'':94B ''600519'':74B ''adx/cci/ma60/mfi14/volatility_20'':57B ''agent'':21B,27B,96B ''api'':68B ''async'':106B ''auc'':80B ''body'':40B ''channel'':23B ''commit'':10A,50B ''confidence'':18B ''dac1451a'':11A,51B ''decision'':39B ''dsh'':24B,98B ''episode'':13B ''evaluate'':119B ''factors'':64B ''global'':15B ''id'':103B,122B ''kind'':12B,26B ''latest'':73B ''lightgbm'':72B ''m0'':61B ''ml'':105B ''model'':32B,99B,102B,108B,118B,121B ''namespace'':38B ''p1'':52B ''p2'':125B,134B ''p3'':66B ''payload'':28B ''predict'':33B,100B ''provenance'':22B ''report'':84B ''rfc'':1A,41B,128B,132B ''rfc003'':30B