INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('2919cd43-ff83-4d4e-9e80-35aeb8a8feca', 'P2 验证门上线并 E2E 验收通过（2026-08-20 20:30，RFC 008）：自进化闭环', '{"kind": "episode", "scope": "global", "status": "testing", "confidence": 0.9, "source": "agent", "provenance": {"channel": "dsh", "session_kind": "agent"}, "payload": {"tags": ["P2验证门", "RFC008", "验收通过", "自进化闭环", "2026-08-20"], "namespace": "decision"}, "body": "P2 验证门上线并 E2E 验收通过（2026-08-20 20:30，RFC 008）：自进化闭环的安全闸就位。链路实证：prompt_evolver dry_run=false → lessons 以 stage=candidate 应用（g8）→ candidates.json 登记观察期 5 天 → validation_gate(judge, force) 裁决 → genome_promote 转正留谱系 → 清理 g9。全链路 git 留痕清晰。实施中修复 2 个新 bug：①evolver 跨工具调用用了不存在的 ctx.tools.list()（生产必崩），改为 ToolRuntime.execute({name,arguments,signal}) 正规入口；②裁决数据精度——BM25 检索 genome:gN 串版本，改为按 payload.genome_context.genome_version 精确过滤。新工具：genome_promote（转正）、candidate_status（观察队列）、validation_gate（裁决：恶化>0.1 回滚/样本<3 延期 2 天/否则转正）。实施偏差记录在 RFC 008 §8（stage 默认 active 人工变更直接正式版；回测门挂起待策略参数入基因组；candidate 仓位收紧未实现）。当前局限：reward 信号粗糙（trade 固定 0.5 占位）、无 regime 对齐、验证粒度是段版本级。至此自进化闭环完整：交易打标(g7)→盘后调度(schedule-1 每日15:30)→蒸馏(evolver)→candidate 应用→观察→裁决转正/回滚。genome 当前 g9。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:123}', NULL, '''-08'':6A,36B,46B ''-1'':152B ''-20'':7A,37B,47B ''0.1'':117B ''0.5'':141B ''0.9'':20B ''008'':11A,51B,127B ''2'':83B,122B ''20'':8A,48B ''2026'':5A,35B,45B ''3'':120B ''30'':9A,49B,154B ''5'':67B ''8'':128B ''active'':131B ''agent'':22B,28B ''arguments'':93B ''bm25'':97B ''body'':40B ''bug'':85B ''candidate'':62B,110B,134B,157B ''candidates.json'':65B ''channel'':24B ''confidence'':19B ''ctx.tools.list'':88B ''decision'':39B ''dry'':56B ''dsh'':25B ''e2e'':3A,43B ''episode'':14B ''evolver'':55B,86B,156B ''false'':58B ''force'':72B ''g7'':149B ''g8'':64B ''g9'':78B,164B ''gate'':70B,114B ''genome'':74B,99B,107B,162B ''git'':80B ''global'':16B ''gn'':100B ''judge'':71B ''kind'':