INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('3d82c1d9-761b-4dd1-bb77-55319ea62c0d', '质量债三任务全部完成并 E2E 验证（2026-08-20 21:25）：①reward 真实化——', '{"kind": "episode", "scope": "global", "status": "testing", "confidence": 0.85, "source": "agent", "provenance": {"channel": "dsh", "session_kind": "agent"}, "payload": {"tags": ["reward真实化", "交易时段硬校验", "LLM改写", "dry_run默认值bug", "2026-08-20"], "namespace": "decision"}, "body": "质量债三任务全部完成并 E2E 验证（2026-08-20 21:25）：①reward 真实化——learning.calculateReward 改异步，portfolio_trade SELL 按近 10 笔买入加权成本算真实 P&L（clamp pnl%/10 到 ±1），BUY 中性 0.1，失败回退中性不阻塞；extractTags 附带 pnl_pct 标签；单元测试 4/4（+10%→1，-10%→-1，BUY→0.1，失败→-0.3）。②trading 交易时段硬校验——assertTradingHours（工作日 9:30-11:30/13:00-15:00，周末拒），portfolio_trade 和 algo_execute 双入口硬拒单；E2E 实证 21:18 下单被拒（宪法第 1 条工具层双保险补齐，此前只有提示词层软约束）；已知限制：未接交易日历，节假日按周一到周五判断。③prompt_evolver LLM 改写——llmRewriteSection 接入 ctx.llm.stream（provider/model 可配，默认 deepseek-official/deepseek-v4-flash），modify_principle 类走 LLM 整体重写（护栏：≤6000 字符/禁 {{}}/rules 段 ID 只增不删/不得违宪法），失败回退追加；E2E 实证 method=''llm'' 且输出为高质量整体重写。④验收中抓到的第 4 个 bug：dsh-tools 不注入 schema 默认值，prompt_evolver 不传 dry_run 时 undefined 导致默认预览失效直接应用 candidate——已改 execute 内显式兜底（dry_run 未传=true、auto_apply 未传=false），修复后验证纯预览 applied=false。意外产出：那次误应用成为第一个真实观察期候选 g10（lessons v4，LLM 重写的恐慌市不接飞刀经验，observe_until 2026-08-25），保留观察。检查点链 agent-self/20260820-211735→212341。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:126}', NULL, '''+10'':76B ''-0.3'':83B ''-08'':5A,35B,44B,191B ''-1'':79B ''-10'':78B ''-11'':90B ''-15'':93B ''-20'':6A,36B,45B ''-25'':192B ''/10'':62B ''/20260820-211735'':198B ''/deepseek-v4-flash'':127B ''/rules'':137B ''0.1'':67B,81B ''0.85'':18B ''00'':92B,94B ''1'':64B,77B,108B ''10'':56B ''18'':105B ''2026'':4A,34B,43B,190B ''21'':7A,46B,104B ''212341'':199B ''25'':8A,47B ''30'':89B ''30/13'':91B ''4'':149B ''4/4'':75B ''6000'':134B ''9'':88B ''agent'':20B,26B,196B ''agent