INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('6f510f47-726c-42cf-820e-d1b743894b6e', 'M1 市场感知三工单完成（2026-08-21，方案二盈利引擎第一波）：①M1-1/M1-3 reg', '{"kind": "episode", "scope": "global", "status": "testing", "confidence": 0.85, "source": "agent", "provenance": {"channel": "dsh", "session_kind": "agent"}, "payload": {"tags": ["M1完成", "regime_daily", "mainline_scan", "schedule-2", "盈利引擎", "2026-08-21"], "namespace": "decision"}, "body": "M1 市场感知三工单完成（2026-08-21，方案二盈利引擎第一波）：①M1-1/M1-3 regime_daily——每日 regime（panic/euphoria/risk_on/risk_off/sideways）+情绪时间序列落库 memory（scope=market:regime / market:sentiment），判定依据含恐慌贪婪指数+涨跌家数比+量能比，同日幂等；实测 08-20/08-21 落库 euphoria（fg=100 极端贪婪，数据质量待持续观察），指数K线趋势维度待 M0 补齐（已在 evidence.data_gap 标注）。②M1-2 mainline_scan——主线 Top3 落库（scope=market:mainline），实测 08-21：白银+3.87%/贵金属+2.74%/诊断服务+2.58%；验收中修复：板块接口中文字段映射（板块名称/涨跌幅/总市值）、undefined 字段触发 lossless JSON、损坏记录用后端 deprecate 接口清理、幂等检查忽略 deprecated 记录。③盘后例程升级为 schedule-2（今日 15:30 首次运行）：regime+主线落库 → 对账 → 风险 → 归因 → 蒸馏预览 + candidate 裁决 → 归因总结 → 飞书日报 → 自我续期。g10 lessons candidate 2026-08-25 到期裁决。market 插件现 5 工具。下一步：M4 仓位映射表（纯规则立即可做，regime 已有数据源）/ M2 主线→标的映射 / M6 决策前检索。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:133}', NULL, '''+2.58'':103B ''+2.74'':101B ''+3.87'':99B ''-08'':4A,38B,46B,141B ''-1'':8A,50B ''-2'':35B,86B,121B ''-20'':70B ''-21'':5A,39B,47B,97B ''-25'':142B ''/08-21'':71B ''/m1-3'':9A,51B ''0.85'':18B ''08'':69B,96B ''100'':75B ''15'':123B ''2026'':3A,37B,45B,140B ''30'':124B ''5'':146B ''agent'':20B,26B ''body'':42B ''candidate'':132B,139B ''channel'':22B ''confidence'':17B ''daily'':31B,53B ''decision'':41B ''deprecate'':114B ''deprecated'':117B ''dsh'':23B ''episode'':12B ''euphoria'':73B ''evidence.data'':82B ''fg'':74B ''g10'':137B ''gap'':83B ''global'':14B ''json'':112B ''kind'':11B,25B ''lessons'':138B ''lossless'':111B ''m0'':79B ''m1'':1A,7A,43B,49B,85B ''m1完成'':29B ''m2'':154B ''m4'':14