INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('10cc65ef-f3d7-4777-9cfd-ba8c0b1aa6da', 'Review 专项完成（2026-08-21 上午，用户质疑"有没有好好 review 和测试"后的', '{"kind": "episode", "scope": "global", "status": "testing", "confidence": 0.9, "source": "agent", "provenance": {"channel": "dsh", "session_kind": "agent"}, "payload": {"tags": ["review专项", "单元测试", "故障注入", "金丝雀修复", "2026-08-21"], "namespace": "decision"}, "body": "Review 专项完成（2026-08-21 上午，用户质疑\"有没有好好 review 和测试\"后的诚实整改）：抓到并修复 3 个此前漏网的真 bug——①金丝雀自动还原路径用 git revert，但工作区已被快照还原成 dirty tree，revert 必被拒（此前金丝雀只测过成功路径）；改为还原即新提交（canary-restore），并建立故障注入单元测试实测通过（注入含未注册变量的段 → 验证文件/genome.json 还原 + git 留痕）。②reward 真实化的后端字段假设错误：真实响应是 items 不是 orders，且卖出记录自带 pnlPercent（含费用精确值）——原代码会静默回退中性 0.1 等于没生效；已改为优先用 pnlPercent、回退买入加权成本。③assertTradingHours 此前只测过 21:18 一个点；已改可注入时间并补 10 项边界测试（9:29/9:30、11:30/11:31、12:59/13:00、15:00/15:01、周末、深夜）。建立 tests/core-logic.test.ts 24 项单元测试（genome 护栏/版本模型/规则 ID/文件锁、learning 截断/规则提取/真实奖励、trading 时段边界、金丝雀故障注入），全套 42/42 绿（含 18 项 schema 冒烟）。教训：冒烟测试只能证明\"能构造\"，行为正确性必须有单元测试+故障注入；对其他 agent 交付的代码，E2E 之外还要怀疑字段假设。遗留诚实清单：regime 情绪数据质量未交叉验证（fg=100 存疑待观察）、schedule-2 例程未真实触发过（今天 15:30 首跑）、merge 检查点链会带入其他 agent 提交（流程上 push 前需 git log 审查）、验证门统计严谨性（小样本阈值）仍是 MVP 水平。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:134}', NULL, '''-08'':4A,35B,43B ''-2'':154B ''-21'':5A,36B,44B ''/genome.json'':71B ''0.1'':85B ''0.9'':19B ''00'':106B ''00/15'':108B ''01'':109B ''10'':96B ''100'':151B ''11'':101B ''12'':104B ''15'':107B,157B ''18'':93B,133B ''2026'':3A,34B,42B ''21'':92B ''24'':114B ''29/9'':99B ''3'':52B ''30'':100B,158B ''30/11'':102B ''31'':103B ''42/42'':130B ''59/13'':105B ''9'':98B ''agent'':21B,27B,143B,162B ''asserttradinghours'':90B ''body'':39B ''bug'':54B ''canary'':66B ''canary-restore'':65B ''channel'':23B ''confidence'':18B ''decision'':38B ''dirty'':59B ''dsh'':24B ''e2e'':145B ''episode'':13B ''fg'':150B ''genome'':116B 