INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('8272d9be-2019-496a-80e0-8fdfe1a4ff3a', 'Bug 清理批次完成（2026-08-21 上午）：①regime 数据质量防线落地——后端情绪数据', '{"kind": "episode", "scope": "global", "status": "testing", "confidence": 0.85, "source": "agent", "provenance": {"channel": "dsh", "session_kind": "agent"}, "payload": {"tags": ["bug清理", "regime数据质量", "A-5", "sentiment不可信", "2026-08-21"], "namespace": "decision"}, "body": "Bug 清理批次完成（2026-08-21 上午）：①regime 数据质量防线落地——后端情绪数据实测不可全信：fg=100 极端贪婪与真实盘面（缩量、指数仅 +0.24%、普涨但平淡）矛盾，涨跌家数样本仅 ~325 只非全市场口径，量能比 2.71 与\"缩量\"报道相反。regime_daily 现在：degraded 标记直通、指标矛盾检测（fg 极端但新高新低 neutral/指数5日负收益）、小样本广度降权、极端判定降置信至 0.35 并加警告语。今日记录已重录带标注。⚠️ 建议 M0 基建线修 sentiment 管线：量能比口径、涨跌家数全市场覆盖。②A-5 闭环：self-restart.ts 现在每次重启前自动备份 cordis.patch.yml/package.json 到 state/config-backup-auto/，回滚路径先恢复配置再重拉——profile 配置导致启动失败不再 boot loop（已实证：本次重启日志含 profile configs backed up）。③rollback commit message 去冗余。单元测试 42/42。仓位提示：今日 regime 虽标 euphoria 但可信度低，真实盘面偏\"缩量修复\"，仓位决策以保守为准。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:137}', NULL, '''+0.24'':53B ''-08'':4A,34B,42B ''-21'':5A,35B,43B ''-5'':31B,87B ''/package.json'':93B ''0.35'':76B ''0.85'':17B ''100'':49B ''2.71'':60B ''2026'':3A,33B,41B ''325'':57B ''42/42'':112B ''a'':30B,86B ''agent'':19B,25B ''backed'':105B ''body'':38B ''boot'':99B ''bug'':1A,39B ''bug清理'':28B ''channel'':21B ''commit'':108B ''confidence'':16B ''configs'':104B ''cordis.patch.yml'':92B ''cordis.patch.yml/package.json'':91B ''daily'':65B ''decision'':37B ''degraded'':67B ''dsh'':22B ''episode'':11B ''euphoria'':117B ''fg'':48B,70B ''global'':13B ''kind'':10B,24B ''loop'':100B ''m0'':80B ''message'':109B ''namespace'':36B ''neutral'':72B ''payload'':26B ''profile'':97B,103B ''provenance'':20B ''regime'':7A,45B,64B,115B ''regime数据质量'':29B ''rollback'':107B ''scope'':12B ''self-restart.ts'':89B ''sentiment'':82B ''sentiment不可信'':32B ''session'':23B ''source'