INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('7ced96f1-feab-4c3d-ac77-b20cec9dbc95', '2026-08-21风控审计：发现"换仓后规则补位失效"系统性漏洞——v13于8/19暴跌日换仓买入', '{"kind": "episode", "scope": "global", "status": "active", "confidence": 0.3, "source": "agent", "provenance": {"channel": "terminal", "session_id": "default", "session_kind": "user"}, "payload": {"category": "fact"}, "body": "2026-08-21风控审计：发现\"换仓后规则补位失效\"系统性漏洞——v13于8/19暴跌日换仓买入5只创业板(300017/300333/300558/300720/301520)但0条盯盘规则覆盖，301520盘中-10.5%无告警。已补规则#52-56(pnl_pct -5%/+10%)。教训：任何账户换仓后必须同日完成\"持仓-规则映射审计\"（每只持仓至少1条止损规则），这是v13第二次踩三不管坑(上次是300008补位)。遗留：僵尸规则#6/7/8/10/12/13/14/17/19/28(格力/杭州银行/华能国际，持仓已不存在)待清理；portfolio_analyze对T+1+破止损场景误报正常；risk_controller工具400未修。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:139}', NULL, '''+1'':72B ''+10'':53B ''-08'':2A,34B ''-10.5'':45B ''-21'':3A,35B ''-5'':52B ''-56'':49B ''0.3'':17B ''2026'':1A,33B ''300017/300333/300558/300720/301520'':42B ''301520盘中'':44B ''52'':48B ''6/7/8/10/12/13/14/17/19/28'':64B ''active'':15B ''agent'':19B ''analyze对t'':71B ''body'':32B ''category'':30B ''channel'':21B ''confidence'':16B ''controller工具400未修'':75B ''default'':25B ''episode'':11B ''fact'':31B ''global'':13B ''id'':24B ''kind'':10B,27B ''payload'':29B ''pct'':51B ''pnl'':50B ''portfolio'':70B ''provenance'':20B ''risk'':74B ''scope'':12B ''session'':23B,26B ''source'':18B ''status'':14B ''terminal'':22B ''user'':28B ''v13于8/19'':8A,40B ''上次是300008补位'':61B ''任何账户换仓后必须同日完成'':55B ''但0条盯盘规则覆盖'':43B ''僵尸规则'':63B ''华能国际'':67B ''发现'':5A,37B ''已补规则'':47B ''待清理'':69B ''持仓'':57B ''持仓-规则映射审计'':56B ''持仓已不存在'':68B ''换仓后规则补位失效'':6A,38B ''教训'':54B ''无告警'':46B ''暴跌日换仓买入'':9A ''暴跌日换仓买入5只创业板'':41B ''杭州银行'':66B ''格力'':65B ''每只持仓至少1条止损规则'':59B ''破止损场景误报正常'':73B ''系统性漏洞'':7A,39B ''规则映射审计'':58B ''这是v13第二次踩三不管坑'':60B ''遗留'':62B ''风控审计'':4A,36B', '2026-08-25 21:21:30.64821', '2026-08-25 21:21:30.64821', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('4568bd66-444e-4f82-812a-244fc954c874', '通知链路诊断结论（2026-08-21）：①notification_channels 工具上线（渠', '{"kind": "episode", "scope": "global", "status": "testing", "confidence": 0.8, "source": "agent", "provenance": {"channel": "dsh", "session_kind": "agent"}, "payload": {"tags": ["notification_channels", "Agent OS", "pending堆积", "webhook正常", "2026-08-21"], "namespace": "decision"}, "body": "通知链路诊断结论（2026-08-21）：①notification_channels 工具上线（渠道清单+投递日志+状态统计，webhook 脱敏），验证正常——飞书共 3 个逻辑渠道 alerts/reports/trading，物理上共用同一 webhook（同一群）。②发现 Agent OS 状态异常：投递日志自 08-18 起 8 条全部 pending（08-17 的 2 条是 sent），但 API 调用返回 success 且飞书 webhook 直连测试正常（StatusCode 0）——推断 Agent OS 状态回写损坏（消息可能实际已发出但状态没更新）或投递流程卡住，需用户目验飞书群是否收到【通道测试】确认。③Agent OS 自身 daily-report 定时任务连续 400 报错（\"channel and title are required\"，调度器调自己 /api/v1/notifications/send 缺参数）——这是 Agent OS（Go 遗留服务）自身 bug，应向负责方报告，与本系统的 feishu_notify 调用链无关。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:140}', NULL, '''-08'':3A,34B,41B ''-17'':71B ''-18'':65B ''-21'':4A,35B,42B ''/api/v1/notifications/send'':109B ''0'':84B ''0.8'':16B ''08'':64B,70B ''2'':73B ''2026'':2A,33B,40B ''3'':53B ''400'':101B ''8'':67B ''agent'':18B,24B,29B,60B,86B,94B,112B ''alerts/reports/trading'':55B ''and'':104B ''api'':77B ''are'':106B ''body'':38B ''bug'':117B ''channel'':20B,103B ''channels'':6A,28B,44B ''confidence'':15B ''daily'':98B ''daily-report'':97B ''decision'':37B ''dsh'':21B ''episode'':10B ''feishu'':120B ''global'':12B ''go'':114B ''kind'':9B,23B ''namespace'':36B ''notification'':5A,27B,43B ''notify'':121B ''os'':30B,61B,87B,95B,113B ''payload'':25B ''pending'':69B ''pending堆积'':31B ''provenance'':19B ''report'':99B ''required'':107B ''scope'':11B ''sent'':75B ''session'':22B ''source'':17B ''status'':13B ''statuscode'':83B ''success'':79B ''tags'':26B ''testing'':14B ''title'':105B ''webhook'':49B,57B,81B ''we