INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('070b9979-6672-48a2-b239-7be42db4bc1c', 'Agent OS 通知 bug 根治（2026-08-21，用户指示"修复 OS 的 bug 而不是', '{"kind": "episode", "scope": "global", "status": "testing", "confidence": 0.9, "source": "agent", "provenance": {"channel": "dsh", "session_kind": "agent"}, "payload": {"tags": ["Agent OS修复", "通知断流根治", "handleSend路由", "2026-08-21"], "namespace": "decision"}, "body": "Agent OS 通知 bug 根治（2026-08-21，用户指示\"修复 OS 的 bug 而不是绕过\"）：根因=POST /api/v1/notifications/send 注册的是 notificationHandler.SendNotification（web 仓储版，只 INSERT pending 日志、从不调用 provider、从不更新状态），而真正完整的 NotificationService.Send（provider 实发+日志回写）对应的 handleSend 是定义了但从未注册路由的死代码。修复=一行路由改接 handleSend（agent-os/internal/api/http_server.go，已提交 1d6cab3e）。全链路实证：DSH feishu_notify → Agent OS → 飞书，日志 status=sent + sent_at 回写正常。附带处置：Agent OS 调度器里两个重复且 payload 无效的 daily-report 任务（channel=slack 且无 title，08-18 起每早 400 报错刷错误日志）已 pause——它们的占位文案与 DSH schedule-2 的真实日报功能重复。教训：自检工具（notification_channels）让 3 天断流一眼可见；\"API 返回 success\"不等于\"事情真做了\"——成功响应必须验证到最终状态。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:141}', NULL, '''-08'':7A,38B,49B ''-18'':116B ''-2'':125B ''-21'':8A,39B,50B ''/api/v1/notifications/send'':59B ''/internal/api/http_server.go'':85B ''0.9'':22B ''08'':115B ''1d6cab3e'':87B ''2026'':6A,37B,48B ''3'':132B ''400'':118B ''agent'':1A,24B,30B,33B,43B,83B,92B,102B ''agent-os'':82B ''api'':134B ''at'':99B ''body'':42B ''bug'':4A,13A,46B,55B ''channel'':26B,111B ''channels'':130B ''confidence'':21B ''daily'':108B ''daily-report'':107B ''decision'':41B ''dsh'':27B,89B,123B ''episode'':16B ''feishu'':90B ''global'':18B ''handlesend'':77B,81B ''handlesend路由'':36B ''insert'':65B ''kind'':15B,29B ''namespace'':40B ''notification'':129B ''notificationhandler.sendnotification'':61B ''notificationservice.send'':72B ''notify'':91B ''os'':2A,11A,44B,53B,84B,93B,103B ''os修复'':34B ''pause'':121B ''