INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('f5c421a1-8719-4bba-bbbb-e8aa049a43ab', '方案 C 通知双通道实施完成并双路径实证（2026-08-21 11:30，用户裁决）：feishu', '{"kind": "episode", "scope": "global", "status": "testing", "confidence": 0.85, "source": "agent", "provenance": {"channel": "dsh", "session_kind": "agent"}, "payload": {"tags": ["方案C", "通知双通道", "降级兜底", "多会话冲突", "2026-08-21"], "namespace": "decision"}, "body": "方案 C 通知双通道实施完成并双路径实证（2026-08-21 11:30，用户裁决）：feishu_notify/notification_send 改为 Agent OS API 主路径（真实发送+系统审计记录，路由 bug 已由 1d6cab3e 修复）+ 直发飞书 webhook 降级兜底（Agent OS 失败/全挂时，webhook 来源 cordis.patch.yml 的 feishuWebhooks ''*'' 配置，返回标记 degraded:true + fallback_reason 可审计）。验证：①主路径 delivery=agent_os + Agent OS 日志 status=sent；②杀掉 Agent OS 后兜底 delivery=feishu_direct、webhook_source=config、degraded=true、feishu_code=0；③已恢复 Agent OS（8080 正常）。注意：另一并行会话曾两次提交直发优先方案（5da11c15/6fb22ef7，保留在历史）并至少一次杀掉 Agent OS 进程——其 sendFeishuDirect 已被收编为兜底角色，但若再出现 Agent OS 异常死亡或通知行为变化，需排查会话间冲突。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:142}', NULL, '''-08'':5A,34B,43B ''-21'':6A,35B,44B ''0'':105B ''0.85'':18B ''11'':7A,45B ''1d6cab3e'':60B ''2026'':4A,33B,42B ''30'':8A,46B ''5da11c15/6fb22ef7'':113B ''8080'':109B ''agent'':20B,26B,51B,65B,84B,86B,92B,107B,116B,123B ''api'':53B ''body'':38B ''bug'':58B ''c'':2A,40B ''channel'':22B ''code'':104B ''confidence'':17B ''config'':100B ''cordis.patch.yml'':71B ''decision'':37B ''degraded'':76B,101B ''delivery'':83B,95B ''direct'':97B ''dsh'':23B ''episode'':12B ''fallback'':78B ''feishu'':10A,48B,96B,103B ''feishuwebhooks'':73B ''global'':14B ''kind'':11B,25B ''namespace'':36B ''notify/notification_send'':49B ''os'':52B,66B,85B,87B,93B,108B,117B,124B ''payload'':27B ''provenance'':21B ''reason'':79B ''scope'':13B ''sendfeishudirect'':120B ''sent'':90B ''session'':24B ''source'':19B,99B ''status'':15B,89B ''tags'':28B ''testing'':16B ''true'':77B,102B ''webhook'':6