INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('1d7a756d-ad5a-44f5-8a7f-60c9e65d4bc3', '事故复盘（2026-08-21 11:07 启动失败 dead 事件）：①根因——我和并行 agen', '{"kind": "episode", "scope": "global", "status": "testing", "confidence": 0.9, "source": "agent", "provenance": {"channel": "dsh", "session_kind": "agent"}, "payload": {"tags": ["事故复盘", "启动失败", "合并冲突", "飞书直发", "方案C", "2026-08-21"], "namespace": "decision"}, "body": "事故复盘（2026-08-21 11:07 启动失败 dead 事件）：①根因——我和并行 agent 同时改 notification/src/index.ts（我的 webhook 直发 vs 对方的 Agent OS 主路径），合并冲突标记（<<<<<<<）残留进文件，esbuild 解析失败导致 DSH 启动崩溃；②回滚失败根因——git 索引有未解决冲突（merge 中途态），self_restart 的自动回滚 checkout 被 git 拒绝（you need to resolve your current index first），系统进入 dead；③恢复——人工/对方解决冲突，采用用户裁决的方案 C（Agent OS API 主路径[对方已修复真实发送] + webhook 直发降级兜底），服务 03:25 恢复；④验证——Agent OS 当前仍不可达（8080 无监听），feishu_notify 实测自动降级 webhook 直发成功（feishu_code=0，返回标注 degraded+fallback_reason，透明）。⑤系统教训：多 agent 并发改同一文件 + self_restart 检查点 = 冲突炸弹；self_restart 前置应加 git 冲突检测（有未解决冲突时拒绝重启/回滚换用 git checkout --theirs 或先 stash）；关键文件改前应检查 git status 是否有并发改动。分支 agent-self/20260821-110713（含方案 C commit 90d64047）尚未合并 main，由方案 C 所有者或用户决定合并。飞书链路结论：webhook 直发兜底已验证可靠，日报通道安全。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:143}', NULL, '''-08'':3A,37B,44B ''-21'':4A,38B,45B ''/20260821-110713'':155B ''0'':121B ''0.9'':20B ''03'':105B ''07'':6A,47B ''11'':5A,46B ''2026'':2A,36B,43B ''25'':106B ''8080'':112B ''90d64047'':159B ''agen'':12A ''agent'':22B,28B,53B,61B,97B,109B,129B,153B ''agent-self'':152B ''api'':99B ''body'':41B ''c'':96B,157B,163B ''channel'':24B ''checkout'':78B,143B ''code'':120B ''commit'':158B ''confidence'':19B ''current'':87B ''dead'':8A,49B,91B ''decision'':40B ''degraded'':123B ''dsh'':25B,68B ''episode'':14B ''esbuild'':66B ''fallback'':124B ''feishu'':114B,119B ''first'':89B ''git'':71B,80B,138B,142B,148B ''global'':16B ''index'':88B ''kind'':13B,27B ''main'':161B ''merge'':73B