INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('6206021d-7be9-48da-bcd1-9efe478ca5b2', '双层身份修正上线（2026-08-21，用户指正：每个窗口必须是唯一个体，不是统一名字）：身份=角色', '{"kind": "episode", "scope": "global", "status": "testing", "confidence": 0.8, "source": "agent", "provenance": {"channel": "dsh", "session_kind": "agent"}, "payload": {"tags": ["双层身份", "window_id", "窗口唯一编码", "2026-08-21"], "namespace": "decision"}, "body": "双层身份修正上线（2026-08-21，用户指正：每个窗口必须是唯一个体，不是统一名字）：身份=角色身份（investor/PI 投资顾问·投资脑，每窗口相同）+ 窗口唯一编码（每窗口不同）。实现：①lifecycle 注册 window_id 提示词变量，provider 从 AssembleContext.agent.id 按作用域解析（session-<uuid>→w-<前8位>，定时任务 investor→''investor''，无作用域→''global''，永不返回 undefined——A-3 教训）；②agent:identity 段加「本窗口唯一编码：{{window_id}}」行；③learning 经验记录 context.agent.window=完整 session id。E2E 实证：本会话 session-2c68a436 的变量解析值 w-2c68a436 与会话一致；经验记录 id 147 带 window=session-2c68a436-...。复盘归因时可用窗口编码精确区分\"是谁说的\"。检查点 agent-self/20260821-122632。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:148}', NULL, '''-08'':3A,33B,40B ''-21'':4A,34B,41B ''-3'':74B ''/20260821-122632'':114B ''0.8'':17B ''147'':102B ''2026'':2A,32B,39B ''2c68a436'':94B,98B,107B ''a'':73B ''agent'':19B,25B,76B,112B ''agent-self'':111B ''assemblecontext.agent.id'':61B ''body'':37B ''channel'':21B ''confidence'':16B ''context.agent.window'':85B ''decision'':36B ''dsh'':22B ''e2e'':89B ''episode'':11B ''global'':13B,70B ''id'':30B,57B,81B,88B,101B ''identity'':77B ''investor'':67B,68B ''investor/pi'':47B ''kind'':10B,24B ''learning'':83B ''lifecycle'':54B ''namespace'':35B ''payload'':26B ''provenance'':20B ''provider'':59B ''scope'':12B ''self'':113B ''session'':23B,63B,87B,93B,106B ''session-2c68a436'':92B,105B ''source'':18B ''status'':14B ''tags'':27B ''testing'':15B ''undefined'':72B ''w'':64B,97B ''w-2c68a436'':96B ''window'':29B,56B,80B,104B ''不是统一名字'':7A,44B ''与会话一致'':99B ''从'':60B ''前8位'':65B ''双层身份'':28B ''双层身份修正上线'':1A,38B ''复盘归因时可用窗口编码精确区分'