INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('51933253-f13b-4b6c-ba24-675302916a82', '窗口注册表上线（2026-08-21，落 Agent OS 记忆库——用户裁决：OS 是核心，v2 ', '{"kind": "episode", "scope": "global", "status": "testing", "confidence": 0.85, "source": "agent", "provenance": {"channel": "dsh", "session_kind": "agent"}, "payload": {"tags": ["窗口注册表", "AgentOS", "window_list", "进程树隔离", "2026-08-21"], "namespace": "decision"}, "body": "窗口注册表上线（2026-08-21，落 Agent OS 记忆库——用户裁决：OS 是核心，v2 是业务域）：lifecycle 监听 agent/created 自动登记新窗口（session-uuid→w-前8位编码），window_update 供窗口自报当前任务/状态（exec.agent.id 自识别），window_list 查询所有窗口（每窗口取最新记录，append-only）。存储：OS 记忆库 /api/v1/memory，tag=system:windows。E2E 实证：本窗口 w-2c68a436 自报成功、window_list 可读。关键教训：从 agent 会话内启动的进程是 DSH 进程树的孩子，self_restart 杀 DSH 时会连带杀掉它们（Agent OS 第一次就这么死的）——必须用 detached:true 独立进程组启动外部服务（OS 现 PPID=1 PGID 独立）。OS 启动方式：node spawn detached（/tmp/agent-os.log），长期建议加 launchd 或 start.sh 编排。检查点 agent-self/20260821-130602。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:149}', NULL, '''-08'':3A,37B,44B ''-21'':4A,38B,45B ''/20260821-130602'':134B ''/api/v1/memory'':81B ''/tmp/agent-os.log'':124B ''0.85'':20B ''1'':116B ''2026'':2A,36B,43B ''2c68a436'':90B ''agent'':6A,22B,28B,47B,97B,106B,132B ''agent-self'':131B ''agent/created'':57B ''agentos'':32B ''append'':76B ''append-only'':75B ''body'':41B ''channel'':24B ''confidence'':19B ''decision'':40B ''detached'':110B,123B ''dsh'':25B,99B,104B ''e2e'':85B ''episode'':14B ''exec.agent.id'':69B ''global'':16B ''kind'':13B,27B ''launchd'':126B ''lifecycle'':55B ''list'':34B,72B,93B ''namespace'':39B ''node'':121B ''only'':77B ''os'':7A,10A,48B,51B,79B,107B,113B,119B ''payload'':29B ''pgid'':117B ''ppid'':115B ''provenance'':23B ''restart'':102B ''scope'':15B ''self'':101B,133B ''session'':26B,60B ''session-uuid'':59B ''source'':21B ''spawn'':122B ''start.sh'':128B ''status'':17B ''system'':83B ''tag'':82B ''tags'':30B