INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('775018ef-7e0c-488e-86d1-e917d33e7d49', 'M2-1 主线→标的映射器完成（2026-08-22）：mainline_stocks 工具上线（m', '{"kind": "episode", "scope": "global", "status": "testing", "confidence": 0.8, "source": "agent", "provenance": {"channel": "dsh", "session_kind": "agent"}, "payload": {"tags": ["M2-1", "mainline_stocks", "标的工厂", "2026-08-22"], "namespace": "decision"}, "body": "M2-1 主线→标的映射器完成（2026-08-22）：mainline_stocks 工具上线（market 插件第 6 工具）。功能：不传参读最新落库主线全量映射；单主线映射支持板块精确名 + 404 时子串模糊兜底；输出成分股按市值取龙头 + 入选理由 + 风险标注（ST/亏损/高估值/操纵未检测提示）；落库 scope=market:watchlist 可检索。E2E 验证：白银→兴业银锡/湖南白银/盛达资源；贵金属→山东黄金/中金黄金/赤峰黄金；锂→赣锋锂业/天齐锂业/中矿资源；种植业（粮食安全翻译用例）→海南橡胶/北大荒/隆平高科（亏损标注生效）。数据源：后端 /api/market/sector/{中文板块名}（client 新增 getSectorStocks）。设计分工：概念主线（粮食安全）→板块名（种植业）的翻译是调用方 LLM 职责，工具做板块→个股。注意：成分股数据 PE/市值为截面快照，风险标注不含减持/商誉（数据源缺，M2-2 排雷工单待做）。quantsys-v2-client 改动 file: 硬拷贝需 pnpm install 同步（已做）。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:163}', NULL, '''-08'':6A,36B,46B ''-1'':2A,31B,42B ''-2'':117B ''-22'':7A,37B,47B ''/api/market/sector'':94B ''0.8'':19B ''2026'':5A,35B,45B ''404'':58B ''6'':53B ''agent'':21B,27B ''body'':40B ''channel'':23B ''client'':96B,122B ''confidence'':18B ''decision'':39B ''dsh'':24B ''e2e'':72B ''episode'':13B ''file'':124B ''getsectorstocks'':98B ''global'':15B ''install'':127B ''kind'':12B,26B ''llm'':105B ''m'':11A ''m2'':1A,30B,41B,116B ''mainline'':8A,32B,48B ''market'':51B,69B ''namespace'':38B ''payload'':28B ''pe'':111B ''pnpm'':126B ''provenance'':22B ''quantsys'':120B ''quantsys-v2-client'':119B ''scope'':14B,68B ''session'':25B ''source'':20B ''st'':63B ''status'':16B ''stocks'':9A,33B,49B ''tags'':29B ''testing'':17B ''v2'':121B ''watchlist'':70B ''不传参读最新落库主线全量映射'':56B ''个股'':108B ''中文板块名'':95B ''中矿资源'':85B ''中金黄金'':80B ''主线'':3A,43B ''亏损'':64B ''亏损标注生效'':91B ''入选理由'':61B ''兴业银锡'':75B ''功能'':55B ''北大荒'':89B ''单主线映射支持板块精确名'':57B ''