INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('dac63444-15d1-4c62-9f15-6252edff9b8e', '盘后归因总结（2026-08-25，后端恢复后首个完整例程）：①市场 panic（放量弱市恐慌规则首', '{"kind": "episode", "scope": "global", "status": "testing", "confidence": 0.7, "source": "agent", "provenance": {"channel": "dsh", "session_kind": "agent"}, "payload": {"tags": ["盘后日报", "2026-08-25", "panic", "熔断减仓完成", "g7归因"], "namespace": "decision"}, "body": "盘后归因总结（2026-08-25，后端恢复后首个完整例程）：①市场 panic（放量弱市恐慌规则首次实战命中：fg25+涨跌0.32+量能1.86；数据降级：广度样本仅437只非全市场）。②主线：房产租赁经纪+5.74%/种子+5.47%/通信线缆+5.02%；催化剂：厄尔尼诺+小摩粮食危机警告（种植链涨停潮）、CPO 光纤需求、公募 REITs 企稳。③组合：权益仓位 13.1%（熔断减仓今日达标：SELL 歌尔 700@23.06），回撤 -10.1% 熔断继续，今日 1 笔成交（减仓单）对账正常。④归因：20 条经验按基因组分组——g7 代最好（11 条 avg -0.009 成功率 72.7%）、g6 最差（-0.1）；model_predict 低奖励 -0.04（17 条）建议增加前置校验。⑤后端三故障今日全修复（memory/sectors/orders），公告板根因诊断起效。⑥g10 candidate 今晚 21:19 到期，明日晚盘后例程裁决。⑦trade_verify 勾稽规则再修正：迁移持仓（可见历史无买入腿）净额为负也降级缺腿提示，不再误报异常。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:184}', NULL, '''+5.02'':56B ''+5.47'':54B ''+5.74'':52B ''-0.009'':90B ''-0.04'':99B ''-0.1'':95B ''-08'':3A,29B,39B ''-10.1'':75B ''-25'':4A,30B,40B ''0.7'':16B ''1'':78B ''11'':87B ''13.1'':68B ''17'':100B ''19'':110B ''20'':83B ''2026'':2A,28B,38B ''21'':109B ''23.06'':73B ''700'':72B ''72.7'':92B ''agent'':18B,24B ''avg'':89B ''body'':36B ''candidate'':107B ''channel'':20B ''confidence'':15B ''cpo'':61B ''decision'':35B ''dsh'':21B ''episode'':10B ''fg25'':45B ''g10'':106B ''g6'':93B ''g7'':85B ''g7归因'':33B ''global'':12B ''kind'':9B,23B ''memory/sectors/orders'':104B ''model'':96B ''namespace'':34B ''panic'':7A,31B,43B ''payload'':25B ''predict'':97B ''provenance'':19B ''reits'':64B ''scope'':11B ''sell'':70B ''session'':22B ''source'':17B ''status'':13B ''tags'':26B ''testing'':14B ''trade'':113B ''verify'':114B ''不再误报异常'':119B ''主线'':50B ''今日'':77B ''今晚'':108B ''代最好'':86B ''企稳'':65B ''低奖励'':98B ''催化剂'':57B ''光纤需求'':62B ''公募'':63B 