INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('e2f51c8f-a652-4f39-a5d3-45ad6a39ea13', '审计报告（2026-08-25 晚，审计对象=并行窗口三项交付）：①记忆迁移到 Agent OS——', '{"kind":"episode","scope":"global","status":"testing","confidence":0.9,"source":"agent","provenance":{"channel":"dsh","session_kind":"agent"},"payload":{"namespace":"decision","tags":["审计","回测腿","记忆迁移","g10 promoted","2026-08-25"]},"body":"审计报告（2026-08-25 晚，审计对象=并行窗口三项交付）：①记忆迁移到 Agent OS——管道切换正确但**历史数据没迁移**（OS 里只有当天记录，179 条历史投资记忆不可见，R-008 检索/验证门基线/归因全断）；已由我补齐：从 quantsys-v2 /api/memory/export 导出 179 条 → 转 envelope → 写入 OS，迁移后检索验证通过（今世缘/主线/验收记录均可查）。教训：迁移审计不能只验证写入通路，必须验证历史数据可读。②回测腿——实现逻辑正确（策略类 candidate 全区间回测、宽松门槛只拦明显垃圾、不过则跳过观察期省 5 天），但审计抓到两个集成 bug 均已修：client backtestStrategy 端点错配（/api/indicators/backtest→/api/backtest/run）+ 结果解析字段不匹配（找 backtest_result 嵌套，实际平铺）。E2E 实证：164 烂策略 sharpe=-0.34 被回测腿真拒绝、178 好策略放行。③g10 lessons candidate 今晚 21:19 观察期满自然裁决 promoted（cand_avg 0 vs 基准 -0.3 不劣）——基因组 g14，验证门首次无人干预完整周期 ✅。④signal_track supersede 重构（OS 无 supersede 概念改扫描端去重）逻辑正确。⑤Agent OS 8080 中途宕机一次（21:43 已用 bin/agent-os serve 重启恢复）。"}', 'data', '{global,kind:episode,agent:agent-dh}', NULL, '''-0.3'':126B ''-0.34'':109B ''-008'':57B ''-08'':3A,37B,42B ''-25'':4A,38B,43B ''/api/backtest/run'':97B ''/api/indicators/backtest'':96B ''/api/memory/export'':66B ''0'':123B ''0.9'':18B ''164'':106B ''178'':111B ''179'':54B,68B ''19'':118B ''2026'':2A,36B,41B ''21'':117B,144B ''43'':145B ''5'':88B ''8080'':142B ''agent'':9A,20B,26B,48B,140B ''avg'':122B ''backtest'':100B ''backteststrategy'':94B ''bin/agent-os'':147B ''body'':39B ''bug'':91B ''cand'':121B ''candidate'':84B,115B ''channel'':22B ''client'':93B ''confidence'':17B ''decision'':29B ''dsh'':23B ''e2e'':104B ''envelope'':71B ''episode'':12B ''g10'':34B,113B ''g14'':129B ''global'':14B ''kind'':11B,25B ''lessons'':114B ''namespace'':28B ''os'':10A,49B,52B,73B,135B,141B ''payload'':27B ''promoted'':35B,120B ''proven