INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('4e3e6cdd-e743-4dd1-8944-1f11c568b0f4', '【工程教训 2026-08-26：服务管理插件上线三部曲】quantsys-v2-manager +', '{"kind":"experience","scope":"global","status":"testing","confidence":0.9,"source":"agent","provenance":{"channel":"dsh","session_kind":"agent"},"payload":{"namespace":"experience","tags":["工程教训","并行冲突","插件开发","quantsys-v2-manager","冒烟测试"]},"body":"【工程教训 2026-08-26：服务管理插件上线三部曲】quantsys-v2-manager + agent-os-manager 两插件（各3工具：status/restart/logs）历经三次重启才上线，三个独立故障叠加：①profile node_modules 缺符号链接（CLAUDE.md 明写要手动 ln，我漏了）→ 启动失败+回滚也失败=dead；②排查期间磁盘源码被并行会话的骨架版覆盖（20:55，无工具注册但启动无报错，形成\"假健康\"——服务正常但工具不存在，极难排查）；③我的完整实现有 required:false 违规 schema（dsh-tools DSL 不支持），冒烟测试第一次\"通过\"是因为当时磁盘已是骨架版——门禁测的是错的代码。教训：a) 并行会话同树工作必须 worktree 隔离（CLAUDE.md 铁律被违反的实锤案例）；b) \"服务活着\"≠\"功能正确\"，验证必须到工具调用层；c) 冒烟测试通过后要确认测的是目标代码版本；d) 恢复实现用 git checkout <checkpoint> -- <精确路径>，不批量覆盖。另：w-58f5597c 已定位后端挂死根因=FastAPI 事件循环被同步批量任务阻塞，修复方案6项在 decision 记忆。——w-5b8aac2a"}', 'experience', '{global,kind:experience,agent:agent-dh}', NULL, '''-08'':3A,41B ''-26'':4A,42B ''0.9'':17B ''20'':69B ''2026'':2A,40B ''55'':70B ''58f5597c'':112B ''5b8aac2a'':121B ''a'':91B ''agent'':19B,25B,49B ''agent-os-manager'':48B ''b'':97B ''body'':38B ''c'':101B ''channel'':21B ''checkout'':106B ''claude.md'':61B,95B ''confidence'':16B ''d'':103B ''dead'':67B ''decision'':117B ''dsh'':22B,82B ''dsh-tools'':81B ''dsl'':84B ''experience'':11B,28B ''false'':78B ''fastapi'':114B ''git'':105B ''global'':13B ''kind'':10B,24B ''ln'':63B ''manager'':9A,36B,47B,51B ''modules'':59B ''namespace'':27B ''node'':58B ''os'':50B ''payload'':26B ''profile'':57B ''provenance'':20B ''quantsys'':7A,34B,45B ''quantsys-v2-manager'':6A,33B,44B ''required'':77B ''schema'':80B ''scope'':12B ''session'':23B ''source'':18B ''status'':14B ''status/restart/logs'':54B ''tags'':29B ''testing'':15B ''tools'':83B ''v2'':8A,35B,46B ''w'':111B,120B ''w-58f5597c'':110B ''w-5b8aac2a'':119B ''worktree'':93B ''三个独立故障叠加'':56B ''不批量覆盖'':108B ''不支持'':85B ''两插件'':52B ''事件循环被同步批量任务阻塞'':115B ''修复方案6项在'':116B ''假健康'':73B ''冒烟测试'':37B ''冒烟测试第一次'':86B ''冒烟测试通过后要确认测的是目标代码版本'':102B ''功能正确'':99B ''历经三次重启才上线'':55B ''另'':109B ''各3工具'':53B ''启动失败'':65B ''回滚也失败'':66B ''工程教训'':1A,30B,39B ''已定位后端挂死根因'':113B ''并行会话同树工作必须'':92B ''并行冲突'':31B ''形成'':72B ''恢复实现用'':104B ''我漏了'':64B ''我的完整实现有'':76B ''排查期间磁盘源码被并行会话的骨架版覆盖'':68B ''插件开发'':32B ''教训'':90B ''无工具注册但启动无报错'':71B ''明写要手动'':62B ''是因为当时磁盘已是骨架版'':88B ''服务正常但工具不存在'':74B ''服务活着'':98B ''服务管理插件上线三部曲'':5A,43B ''极难排查'':75B ''精确路径'':107B ''缺符号链接'':60B ''记忆'':118B ''违规'':79B ''通过'':87B ''铁律被违反的实锤案例'':96B ''门禁测的是错的代码'':89B ''隔离'':94B ''验证必须到工具调用层'':100B', '2026-08-26 21:23:21.988862', '2026-08-26 21:23:21.988862', '{}');
