INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('8c4fe8b0-0495-4a00-bfdf-135c37976ff4', '[迁移 agent-ts 经验 2/7] 机构吸筹进攻期持有防御板块浮亏股的换仓决策

