INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('024d20fa-5b1d-41f3-9d56-8b66ddc4bf21', '【Agent OS 守护方案 2026-08-27 12:20】Agent OS (8080) 反复', '{"kind":"episode","scope":"global","status":"testing","confidence":0.9,"source":"agent","provenance":{"channel":"dsh","session_kind":"agent"},"payload":{"namespace":"decision","tags":["agent-os","launchd","守护进程","根因修复"]},"body":"【Agent OS 守护方案 2026-08-27 12:20】Agent OS (8080) 反复死亡的根因与根治：今天发现 Agent OS 两次死亡——一次是昨夜至今晨期间死亡（原因不可考，当时无守护）；一次是我 nohup 手动启动后 9 分钟被 DSH bash 工具会话结束的进程组清理杀掉（优雅关闭，日志实锤）。根治方案：launchd LaunchAgent（~/Library/LaunchAgents/com.pi-investment.agent-os.plist），KeepAlive=true + RunAtLoad=true + ThrottleInterval=10s，进程死亡 10 秒内自动拉起，开机自启，日志落 agent-os/logs/launchd-*.log。配套修复：agent-os-manager 插件配置改正（projectRoot=/Users/yunpeng/pi-investment/agent-os、startCommand=./bin/agent-os serve、healthCheckUrl=/health 而非 /api/v1/health），插件默认值与 cordis.patch.yml 两处同步。agent_os_status 已验证：running+health_ok+PID 80124。注意：今后 agent_os_restart 工具启动的实例不经 launchd，死亡后 launchd 会按 plist 再次拉起（可能与工具启动的实例端口冲突，届时重启工具需先 unload launchd 或改为 launchctl kickstart 方式，待观察）。——w-5b8aac2a"}', 'data', '{global,kind:episode,agent:agent-dh}', NULL, '''-08'':5A,44B ''-27'':6A,45B ''/api/v1/health'':103B ''/bin/agent-os'':98B ''/health'':101B ''/library/launchagents/com.pi-investment.agent-os.plist'':72B ''/logs/launchd-'':87B ''/users/yunpeng/pi-investment/agent-os'':96B ''0.9'':20B ''10'':80B ''10s'':78B ''12'':7A,46B ''20'':8A,47B ''2026'':4A,43B ''5b8aac2a'':139B ''80124'':115B ''8080'':11A,50B ''9'':62B ''agent'':1A,9A,22B,28B,34B,40B,48B,53B,85B,91B,107B,118B ''agent-os'':33B,84B ''agent-os-manager'':90B ''bash'':65B ''body'':39B ''channel'':24B ''confidence'':19B ''cordis.patch.yml'':105B ''decision'':31B ''dsh'':25B,64B ''episode'':14B ''global'':16B ''health'':112B ''healthcheckurl'':100B ''keepalive'':73B ''kickstart'':134B ''kind'':13B,27B ''launchagent'':71B ''launchctl'':133