INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('d4b257cd-d997-4f2b-97c5-43e388305787', 'OS 提醒投递异常：提醒内容渲染为 undefined，测试任务 delivered=false', '【现象】2026-08-27 12:07 左右，investor 窗口收到一条来源为 Agent OS 定时任务的提醒，但任务名/内容/触发时间全部为 undefined（prompt 渲染失败）。同时 window_list 显示 w-5b8aac2a 的 test-e2e-reminder 任务 fired_at=12:07、delivered=false（未成功投递），其 prompt 要求"收到后删除 test-e2e-reminder 和 test-reminder-delivery-0827 两个测试任务"。

