INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('f55b1899-68a7-4e71-bba9-bce56eddd15a', '【工程教训：pnpm file: 依赖快照陷阱 2026-08-27】agent-dh worksp', '{"kind":"experience","scope":"global","status":"testing","confidence":0.9,"source":"agent","provenance":{"channel":"dsh","session_kind":"agent"},"payload":{"namespace":"experience","tags":["工程教训","pnpm","错误处理","quantsys-v2-client","依赖快照"]},"body":"【工程教训：pnpm file: 依赖快照陷阱 2026-08-27】agent-dh workspace 内 quantsys-v2-client 是 file: 依赖，pnpm install 时**复制快照**（node_modules/.pnpm/file+..+quantsys-v2-client/）而非实时链接——改完 client 源码+build 后若不重新 pnpm install，所有插件运行时用的仍是旧快照。这解释了两个历史谜团：①昨天 watch_manage 工具 400 之谜（price_break 修复 21:39 构建成功但工具层用的是 8-26 17:08 的旧快照）；②错误拦截器第一次重启后未生效。铁律：改 quantsys-v2-client 后必须 pnpm build && cd agent-dh && pnpm install && 重启，三步缺一不可。本次还上线了统一错误包装拦截器：所有 HTTP 错误转为结构化中文错误（端点+状态码+后端原因+排查建议），网络错误区分 ECONNREFUSED/超时并给出排查路径；watch_manage 增加入参校验（缺字段直接中文提示，不再直达后端 400）。验证：data_fetch_quote 999999 报\"[quantsys-v2] GET /api/stock/999999/quote → HTTP 404: 无法从数据库获取…检查 URL 路径与参数\"✅；watch_manage create/delete 全通✅。——w-29882338"}', 'experience', '{global,kind:experience,agent:agent-dh}', NULL, '''-08'':6A,46B ''-26'':93B ''-27'':7A,47B ''-29882338'':154B ''/api/stock/999999/quote'':142B ''0.9'':19B ''08'':95B ''17'':94B ''2026'':5A,45B ''21'':89B ''39'':90B ''400'':84B,131B ''404'':144B ''8'':92B ''999999'':136B ''agent'':9A,21B,27B,49B,109B ''agent-dh'':8A,48B,108B ''body'':40B ''break'':87B ''build'':74B,106B ''cd'':107B ''channel'':23B ''client'':38B,56B,69B,72B,103B ''confidence'':18B ''create/delete'':151B ''data'':133B ''dh'':10A,50B,110B ''dsh'':24B ''econnrefused'':124B ''experience'':13B,30B ''fetch'':134B ''file'':3A,43B,58B ''get'':141B ''global'':15B ''http'':117B,143B ''install'':61B,77B,112B ''kind'':12B,26B ''manage'':82B,127B,150B ''modules/.pnpm/file'':65B ''namespace'':29B ''node'':64B ''payload'':28B ''pnpm'':2A,33B,42B,60B,76B,105B,11