INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('5ddc94b0-fdb1-4a0e-9b70-4ac4002223cf', '600150 neutral P3 政策·个股事件源实现（RFC 015 §3）：多源事件采集、幂等落库、多源同一事件合并。打样 7 条通道（东财公告流/巨潮法', '600150 交易经验（2026-09-11T12:11:58.399Z）
场景：P3 政策·个股事件源实现（RFC 015 §3）：多源事件采集、幂等落库、多源同一事件合并。打样 7 条通道（东财公告流/巨潮法定披露/akshare 解禁/gov.cn/发改委/证监会/人工 seed）全部直连（trust_env=False 绕系统代理）可用；政策侧交易所通道（上交所 SOA 缺 siteId、深交所 CATALOGID 失效）未打通，落人工策展兜底。
结果：neutral
教训：事件源工程四条实证教训：①多源≠故障转移——个股事件各源覆盖的事件集不重叠（东财公告流/巨潮法定披露/akshare 解禁），用 _try_providers 的"首个成功即返回"会让多源退化成单源，必须逐源独立调用后聚合；DB 兜底还要在 ingest 路径排除（读库再写库=自己喂自己，会把无 hash 的既有 67 行宏观事件重算 hash 后插成重复行）。②标题关键词表必须用实测反例收敛——POLICY 词表先含"公告/决定"把公司公告判成政策，去掉后又含"通知/管理办法"仍误判 14 条，最终只保留发行主体名（国务院/证监会/发改委…）才干净；政策 provider 应显式给 type，别指望标题推断。③多类别混排 + 全局 limit 会挤掉一类数据——for_symbol 用 (symbols@>x OR scope=macro) ORDER BY date LIMIT n，宏观事件日期最早把 limit 占满，600150 有 15 条个股事件却返回 0；必须按类别分别限量。④字段级真实验证不能省——东财 display_time 毫秒用冒号分隔（19:36:56:580）、巨潮 searchkey 是全文检索会命中"提及该代码的别家公告"、巨潮毫秒时间戳需按 UTC+8 显式换算、akshare 占比列已是小数——每一条都只能靠打样发现。', 'experience', '{600150,neutral}', NULL, '''+8'':158B ''-09'':20B ''-11'':21B ''/akshare'':41B,73B ''/gov.cn'':43B ''0'':141B ''015'':7A,31B ''11'':23B ''14'':105B ''15'':139B ''19'':148B ''2026'':19B ''3'':8A,32B ''36'':149B ''56'':150B ''58.399'':24B ''580'':151B ''600150'':1A,17B,137B ''67'':91B ''7'':13A,37B ''akshare'':160B ''by'':130B ''catalogid'':60B ''date'':131B ''db'':82B ''display'':145B ''env'':50B ''false'':51B ''for'':121B ''hash'':89B,93B ''ingest'':84B ''limit'':119B,132B,135B ''macro'':128B ''n'':133B ''neutral'':2A,65B ''or'':126B ''order'':129B ''p3'':3A,27B ''policy'':96B ''provider'':113B ''providers'':77B ''rfc'':6A,30B ''scope'':127B ''searchkey'':153B ''seed'':47B ''siteid'':58B ''soa'':56B ''symbol'':122B ''symbols'':124B ''t12'':22B ''time'':146B ''trust'':49B ''try'':76B ''type'':115B ''utc'':157B ''x'':125B ''z'':25B ''上交所'':55B ''东财'':144B ''东财公告流'':15A,39B,71B ''个股事件各源覆盖的事件集不重叠'':70B ''个股事件源实现'':5A,29B ''事件源工程四条实证教训'':67B ''交易经验'':18B ''人工'':46B ''仍误判'':104B ''会把无'':88B ''会挤掉一类数据'':120B ''会让多源退化成单源'':80B ''兜底还要在'':83B ''全局'':118B ''全部直连'':48B ''公告'':98B ''决定'':99B ''别指望标题推断'':116B ''占比列已是小数'':161B ''占满'':136B ''去掉后又含'':101B ''发改委'':44B,110B ''可用'':53B ''后插成重复行'':94B ''国务院'':108B ''场景'':26B ''多源'':68B ''多源事件采集'':9A,33B ''多源同一事件合并'':11A,35B ''多类别混排'':117B ''失效'':61B ''字段级真实验证不能省'':143B ''宏观事件日期最早把'':134B ''巨潮'':152B ''巨潮毫秒时间戳需按'':156B ''巨潮法'':16A ''巨潮法定披露'':