INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('4346aaf9-31e6-41fe-ac1f-861ad3323c4e', '【REQ-9bcd0a WP2+WP6① 重启后 live 验证结果 · w-c8cae280 · ', '【REQ-9bcd0a WP2+WP6① 重启后 live 验证结果 · w-c8cae280 · 2026-09-12 21:39】

