INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('aa10e719-fe35-4d91-b52e-6fa4a77c8e2e', '【错误处理改造完整验收 2026-08-27 12:41】E2E 验证通过。改造内容：①quants', '{"kind":"episode","scope":"global","status":"testing","confidence":0.9,"source":"agent","provenance":{"channel":"dsh","session_kind":"agent"},"payload":{"namespace":"decision","tags":["错误处理","拦截器","retry","pnpm","E2E验证"]},"body":"【错误处理改造完整验收 2026-08-27 12:41】E2E 验证通过。改造内容：①quantsys-v2-client 统一错误包装拦截器（原地修改 error.message 保留 response/config/code 给 axiosRetry 判断 5xx，避免 new Error 丢元数据导致 retry 失效）；②watch_manage 入参校验（create 缺 name/symbol/condition 直接中文提示+示例）。技术要点：axios 响应错误拦截器按注册顺序执行，包装器必须先于 axiosRetry 注册（retry 先看到原始 axios 错误带 response.status → 5xx 重试 ✓），但 new Error 会丢 response 导致 retry 误判网络错误 → 改用原地修改 error.message + rethrow 原对象 → retry 正常（500 重试 4 次 ✓）、包装正确（端点+状态+后端原因+排查建议 ✓）。测试覆盖：500（retry 4 次+包装）、404（无 retry+包装）、ECONNREFUSED（网络错误识别）、watch_manage 缺参数（中文校验）全通过 ✅。顺带发现并修复 pnpm file: 依赖快照陷阱（昨天 watch_manage price_break 修复一直未生效的根因）——file: 依赖是拷贝快照（node_modules/.pnpm/file+..+quantsys-v2-client/）非实时链接，改完 client 必须 pnpm install 刷新快照。错误处理改造已合并 agent-self/20260827-122514 → main。——w-29882338"}', 'data', '{global,kind:episode,agent:agent-dh}', NULL, '''-08'':3A,39B ''-27'':4A,40B ''-29882338'':158B ''/20260827-122514'':155B ''0.9'':18B ''12'':5A,41B ''2026'':2A,38B ''4'':102B,112B ''404'':115B ''41'':6A,42B ''500'':100B,110B ''5xx'':58B,84B ''agent'':20B,26B,153B ''agent-self'':152B ''axios'':74B,81B ''axiosretry'':56B,77B ''body'':36B ''break'':134B ''channel'':22B ''client'':49B,143B,146B ''confidence'':17B ''create'':68B ''decision'':29B ''dsh'':23B ''e2e'':7A,43B ''e2e验证'':35B ''econnrefused'':119B ''episode'':12B ''error'':61B,88B ''error.message'':52B,95B ''file'':128B,136B ''global'':14B ''install'':149B ''kind'':11B,25B ''main'':156B ''manage'':66B,122B,132B ''modules/.pnpm/file'':139B ''name/symbol/condition'':70B ''namespace'':28B ''new'':60B,87B ''n