INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('e4f409d3-7474-47fb-a33a-ba7683f8c3ab', '【Agent OS 生命周期根本性修复 2026-08-28 00:19】三个新问题的统一根因=Ag', '{"kind":"episode","scope":"global","status":"testing","confidence":0.9,"source":"agent","provenance":{"channel":"dsh","session_kind":"agent"},"payload":{"namespace":"decision","tags":["agent-os","根本性修复","launchd","serve-guard","生命周期"]},"body":"【Agent OS 生命周期根本性修复 2026-08-28 00:19】三个新问题的统一根因=Agent OS 生命周期管理无唯一权威（手动启动/launchd/插件重启三路并发）。根本性修复四件套：①serve-guard.sh 幂等启动脚本（agent-os/scripts/）——抢端口前先清场杀残留+exec 替换进程，launchd/插件/人工都走它；②launchd plist 改为调 serve-guard.sh；③agent_os_restart 插件改为委派 launchctl kickstart -k（原子重启，不再自己 kill+spawn，消除双实例竞争）；④agent_os_status/quantsys_v2_status 的 pid schema bug 修复（pid null 报\"must be a number\"——DSL 不支持 union type，方案=代码层 pid??0 兜底+文档注释）。全部故障注入实测：SIGKILL→15秒自愈✅、agent_os_restart E2E（kickstart→1秒健康）✅、冒烟 20/20✅。已合并 main。——w-5b8aac2a"}', 'data', '{global,kind:episode,agent:agent-dh}', NULL, '''-08'':5A,45B ''-28'':6A,46B ''/launchd'':54B ''/scripts'':62B ''0'':107B ''0.9'':18B ''00'':7A,47B ''15秒自愈'':112B ''19'':8A,48B ''1秒健康'':118B ''20/20'':120B ''2026'':4A,44B ''5b8aac2a'':125B ''a'':98B ''ag'':10A ''agent'':1A,20B,26B,32B,41B,50B,60B,73B,85B,113B ''agent-os'':31B,59B ''be'':97B ''body'':40B ''bug'':91B ''channel'':22B ''confidence'':17B ''decision'':29B ''dsh'':23B ''dsl'':100B ''e2e'':116B ''episode'':12B ''exec'':64B ''global'':14B ''guard'':38B ''k'':79B ''kickstart'':78B,117B ''kill'':82B ''kind'':11B,25B ''launchctl'':77B ''launchd'':35B,66B,69B ''main'':122B ''must'':96B ''namespace'':28B ''null'':94B ''number'':99B ''os'':2A,33B,42B,51B,61B,74B,86B,114B ''payload'':27B ''pid'':89B,93B,106B ''plist'':70B ''provenance'':21B ''restart'':75B,115B ''schema'':90B ''scope'':13B ''serve'':37B ''serve-guard'':36B ''serve-guard.sh'':57B,72B ''session'':24B ''sigkill'':111B ''source'':19B ''spawn'':83B ''status'':15B ''status