INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('33b043d3-6512-4a8e-bf1c-3e1ed51c1312', '【因子数据停更根本性修复 2026-08-28 00:40】症状：因子数据停在 8-20/8-21（', '{"kind":"episode","scope":"global","status":"testing","confidence":0.9,"source":"agent","provenance":{"channel":"dsh","session_kind":"agent"},"payload":{"namespace":"decision","tags":["因子数据","根本性修复","freshness","数据质量","管道监控"]},"body":"【因子数据停更根本性修复 2026-08-28 00:40】症状：因子数据停在 8-20/8-21（6 天未更新），影响 model_predict/factor_calculate/策略技术面维度。根因：①因子计算管道失效（任务触发但执行失败）；②无失败重试机制；③无数据质量主动告警；④工具层无 freshness 校验 → 陈旧数据静默毒化选股质量。三层根本解决方案：L1-管道自动化（Agent OS scheduler 加失败重试，1h/2h/4h 指数回退）；L2-监控告警（data_quality_check 检测 stale>3天时飞书告警+每日 summary）；L3-防御设计（工具层 freshness 校验，>3天 warning/degraded，>7天拒服）。已实施：✅L3（factor_calculate 加校验，commit d20cef65）；待实施：⚠️补录 8-22~8-27 数据（P0，后端 5 分钟）、⚠️质检告警接入（P0，30 分钟）、⚠️scheduler 重试机制（P1，2-3h）。完整方案文档：agent-dh/docs/FACTOR-FRESHNESS-ROOT-FIX.md。——w-5b8aac2a"}', 'data', '{global,kind:episode,agent:agent-dh}', NULL, '''-08'':3A,40B ''-20'':10A,47B ''-22'':104B ''-28'':4A,41B ''-3'':119B ''/8-21'':11A,48B ''/docs/factor-freshness-root-fix.md'':125B ''0.9'':19B ''00'':5A,42B ''1h/2h/4h'':72B ''2'':118B ''2026'':2A,39B ''30'':113B ''3天'':91B ''3天时飞书告警'':82B ''40'':6A,43B ''5'':109B ''5b8aac2a'':128B ''6'':49B ''7天拒服'':93B ''8'':9A,46B,103B ''agent'':21B,27B,68B,123B ''agent-dh'':122B ''body'':37B ''calculate'':97B ''channel'':23B ''check'':79B ''commit'':99B ''confidence'':18B ''d20cef65'':100B ''data'':77B ''decision'':30B ''dh'':124B ''dsh'':24B ''episode'':13B ''factor'':96B ''freshness'':34B,61B,89B ''global'':15B ''h'':120B ''kind'':12B,26B ''l1'':66B ''l1-管道自动化'':65B ''l2'':75B ''l2-监控告警'':74B ''l3'':86B,95B ''l3-防御设计'':85B ''model'':52B ''namespace'':29B ''os'':69B ''p0'':107B,112B ''p1'':117B ''payload'':28B ''predict/factor_calculate'':53B ''provenance'':22B ''quality'':78B ''scheduler'':70B,115B ''scope'':14B ''session'':25B ''source'':20B ''stale'':81B ''status'':16B ''summary'':84B ''tags'':31B ''testing'':17B ''w'':127B ''w-5b8aac2a'':126B ''warning/degraded'':92B ''~8-27'':105B ''三层根本解决方案'':64B ''任务触发但执行失败'':57B ''分钟'':110B,114B ''加失败重试'':71B ''加校验'':98B ''后端'':108B ''因子数据'':32B ''因子数据停在'':8A,45B ''因子数据停更根本性修复'':1A,38B ''因子计算管道失效'':56B ''天未更新'':50B ''完整方案文档'':121B ''工具层'':88B ''工具层无'':60B ''已实施'':94B ''影响'':51B ''待实施'':101B ''指数回退'':73B ''数据'':106B ''数据质量'':35B ''无失败重试机制'':58B ''无数据质量主动告警'':59B ''校验'':62B,90B ''根因'':55B ''根本性修复'':33B ''检测'':80B ''每日'':83B ''症状'':7A,44B ''监控告警'':76B ''策略技术面维度'':54B ''管道监控'':36B ''管道自动化'':67B ''补录'':102B ''质检告警接入'':111B ''重试机制'':116B ''防御设计'':87B ''陈旧数据静默毒化选股质量'':63B', '2026-08-28 00:36:59.717153', '2026-08-28 00:36:59.717153', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('89901870-5b14-4914-8c8a-73baccdab142', '【根本性修复总结 2026-08-28 00:45】今晚完成两项根本性修复：①因子数据停更（三层方案', '{"kind":"episode","scope":"global","status":"testing","confidence":0.85,"source":"agent","provenance":{"channel":"dsh","session_kind":"agent"},"payload":{"namespace":"decision","tags":["根本性修复","因子freshness","board工具","tonight成果"]},"body":"【根本性修复总结 2026-08-28 00:45】今晚完成两项根本性修复：①因子数据停更（三层方案L3防御层已实施，commit d20cef65）：factor_calculate 加 freshness 校验，>3天 warning+degraded，>7天抛错拒服，防陈旧数据静默毒化选股质量；完整设计文档 agent-dh/docs/FACTOR-FRESHNESS-ROOT-FIX.md，L1管道层（scheduler失败重试）+L2监控层（质检主动告警）待后端配合（30分钟+2-3h）。②board_read 工具修复（commit e03a3410）：memoryClient.search() 拒绝空 query，原代码传空字符串致 ''query is required'' 错误，改为 query:''board'' 后验证通过。遗留问题：board_update（getById not a function）、因子补录（8-22~8-27，P0后端5分钟）、后端事件循环阻塞（P0未实施）、opportunity_scan 500、死窗任务（已清理或无法观测）。——w-3fd99d29"}', 'data', '{global,kind:episode,agent:agent-dh}', NULL, '''+2'':67B ''-08'':3A,37B ''-22'':96B ''-28'':4A,38B ''-3'':68B ''/docs/factor-freshness-root-fix.md'':60B ''0.85'':17B ''00'':5A,39B ''2026'':2A,36B ''30分钟'':66B ''3fd99d29'':108B ''3天'':51B ''45'':6A,40B ''500'':103B ''7天抛错拒服'':54B ''8'':95B ''a'':92B ''agent'':19B,25B,58B ''agent-dh'':57B ''board'':70B,85B,88B ''board工具'':32B ''body'':34B ''calculate'':47B ''channel'':21B ''commit'':44B,73B ''confidence'':16B ''d20cef65'':45B ''decision'':28B ''degraded'':53B ''dh'':59B ''dsh'':22B ''e03a3410'':74B ''episode'':11B ''factor'':46B ''freshness'':49B ''function'':93B ''getbyid'':90B ''global'':13B ''h'':69B ''is'':80B ''kind'':10B,24B ''l1管道层'':61B ''l2监控层'':63B ''memoryclient.search'':75B ''namespace'':27B ''not'':91B ''opportunity'':101B ''p0后端5分钟'':98B ''p0未实施'':100B ''payload'':26B ''provenance'':20B ''query'':77B,79B,84B ''read'':71B ''required'':81B ''scan'':102B ''scheduler失败重试'':62B ''scope'':12B ''session'':23B ''source'':18B ''status'':14B ''t