INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('5e0c784e-6c5e-49f2-8329-e72188284877', '2026-09-12 23:50 发版链路补成四层体检（w-adb088f2）。【为什么】今天两次部', '2026-09-12 23:50 发版链路补成四层体检（w-adb088f2）。【为什么】今天两次部署成功但未生效且全无报错：①3 个包 main 指向 dist、只改 src 未构建；②先重启后构建，进程比产物还老。【L1 依赖层修复】relink-profile.py 原只认 file: 协议，而 :13080 运行 profile 的 23 个 @pi-investment 依赖全是 link: → 每个包被跳过，最后打印「共 0 个包」却仍输出 OK（空检假 OK，我曾被骗）；现支持 file:/link:、检查到 0 个包即判失败、新增 symlink-dangling 状态、默认 profile 改为真实运行那个（DSH_INVESTMENT_PROFILE → DSH_HOME/profiles/investment → ~/.dsh-agent-dh/... → ~/.dsh/...）。实测 live profile 的结论由「0 个包 OK」修正为「已检查 23 个包，均 symlink-ok」。故障注入：空 profile → 退出 1 且明说本脚本对该 profile 没有校验能力；真目录副本 → 检出漂移退出 1。【L3 进程层（新增 deploy-verify.py，核心）】不变量=运行进程启动时间必须晚于所有插件代码文件的最新 mtime（含各包 src 与 dist，覆盖 dist 包与 src 直载包）。实测当前实例即 FAIL：进程 61660 启动 23:36:36 vs 最新代码 23:47:59 → 退出码 1 并提示需重启。该断言是「是否真加载了最新包」的直接判据，一行即可拦住今天两次事故。【L4 留痕】写 profile/state/deploy-manifest.json（ts、git HEAD、进程 pid/启动时间、19 个产物 md5+mtime+bytes、各层结论、result=PASS/PASS_PARTIAL/FAIL）；跳过进程层时禁止宣称已加载最新代码。【脚本接线】新增 --verify-only；完整发版收尾强制四层体检（不过即退出 1，即便服务已起）；--build-only 走 L1/L2（--skip-process）；PROFILE_DIR 修正为真实运行 profile（原值误为主实例 :3080 的 ~/.dsh/profiles/investment）。【当前状态】已提交；运行实例仍是旧的（L3 FAIL），需一次完整发版才能通过四层体检。', 'knowledge', '{发版链路,四层体检,L3进程新鲜度,relink空检,2026-09-12,w-adb088f2}', NULL, '''-09'':2A,13B ''-12'':3A,14B ''/.dsh'':81B ''/.dsh-agent-dh'':80B ''/.dsh/profiles/investment'':188B ''/link'':63B ''0'':54B,65B,86B ''1'':101B,107B,139B,171B ''13080'':40B ''19'':155B ''2026'':1A,12B ''23'':4A,15B,44B,91B,130B,135B ''3'':23B ''3080'':186B ''36'':131B,132B ''47'':136B ''50'':5A,16B ''59'':137B ''61660'':128B ''adb088f2'':9A,20B ''build'':174B ''build-only'':173B ''bytes'':159B ''dangling'':70B ''deploy-verify.py'':111B ''dir'':182B ''dist'':27B,119B,121B ''dsh'':75B,78B ''fail'':126B,193B ''file'':37B,62B ''git'':150B ''head'':151B ''home/profiles/investment'':79B ''investment'':48B,76B ''l1''