INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('011f5ef8-36f1-4317-b167-b7cdf27dde4f', '工具测试纪律（2026-08-30 卡死 6 分钟教训）：DSH 工具执行器是串行队列，Promis', '工具测试纪律（2026-08-30 卡死 6 分钟教训）：DSH 工具执行器是串行队列，Promise.race+setTimeout 是假超时——只停止自己等待、不取消底层调用，超时调用继续占队列导致后续所有调用排队死锁（实测 7 个调用排队 6 分钟从未执行）。修复：①批量测试前先 curl 后端健康检查（quantsys:5001/agentos:8080）；②慢工具（data_fetch_macro timeoutMs=60s、evolution_run、strategy_optimize 等）一律单发、不参与批量并行；③并发≤2，写操作串行；④禁止 Promise.race 假超时，用 DSH 原生超时或接受真实等待；⑤发现工具超时立即停止批量测试先查后端/队列；⑥每个 run_code 程序必须打印进度。详见 FIX_PLAN_TOOL_HANG_20260830.md 与 TOOLS_SMOKE_REPORT_20260830.md。', 'knowledge', '{工具测试,超时,DSH执行器,工程纪律,2026-08-30}', NULL, '''-08'':3A,13B ''-30'':4A,14B ''2'':52B ''2026'':2A,12B ''5001/agentos'':36B ''6'':6A,16B,29B ''60s'':43B ''7'':27B ''8080'':37B ''code'':64B ''curl'':33B ''data'':39B ''dsh'':8A,18B,58B ''evolution'':44B ''fetch'':40B ''fix_plan_tool_hang_20260830.md'':67B ''macro'':41B ''optimize'':47B ''promis'':10A ''promise.race'':20B,55B ''quantsys'':35B ''run'':45B,63B ''settimeout'':21B ''strategy'':46B ''timeoutms'':42B ''tools_smoke_report_20260830.md'':69B ''一律单发'':49B ''不参与批量并行'':50B ''不取消底层调用'':24B ''与'':68B ''个调用排队'':28B ''修复'':31B ''假超时'':56B ''写操作串行'':53B ''分钟从未执行'':30B ''分钟教训'':7A,17B ''卡死'':5A,15B ''原生超时或接受真实等待'':59B ''发现工具超时立即停止批量测试先查后端'':60B ''只停止自己等待'':23B ''后端健康检查'':34B ''实测'':26B ''工具执行器是串行队列'':9A,19B ''工具测试纪律'':1A,11B ''并发'':51B ''慢工具'':38B ''批量测试前先'':32B ''是假超时'':22B ''每个'':62B ''用'':57B ''禁止'':54B ''程序必须打印进度'':65B ''等'':48B ''详见'':66B ''超时调用继续占队列导致后续所有调用排队死锁'':25B ''队列'':61B', '2026-08-30 20:55:12.908801', '2026-08-30 20:55:12.908801', '{}');
