INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('d0a17e9f-d0d3-4ab1-8277-21cfbba093df', '2026-08-31 genome 工具专项验证（w-9bbe3e64）：SDK 已挂载 genom', '2026-08-31 genome 工具专项验证（w-9bbe3e64）：SDK 已挂载 genome_* 6 工具，但仅 genome_read 可用。genome_list/genome_history 绑定层拒绝数字版本（schema 要求 string）；genome_update/genome_promote 先写盘+git commit 后绑定报错（危险副作用）；genome_rollback 双层失败（semver 校验 + 无 history 快照）。根因：重构后 prompt.ts schema 用 semver 字符串，线上插件用整数版本（genome.json version 1/6/7/5）；单测 mock semver 造成 26/26 假通过。线上 genome 已恢复原状（md5 一致、HEAD 28a54c7）。详见 TOOLS_GENOME_VERIFICATION_20260831.md。', 'knowledge', '{genome,工具验证,schema绑定,版本模型不一致,TOOLS_REFACTOR_TRACKER}', NULL, '''-08'':2A,13B ''-31'':3A,14B ''1/6/7/5'':60B ''2026'':1A,12B ''26/26'':65B ''28a54c7'':73B ''6'':23B ''9bbe3e64'':8A,19B ''commit'':39B ''genom'':11A ''genome'':4A,15B,22B,26B,29B,35B,42B,68B ''genome.json'':58B ''git'':38B ''head'':72B ''history'':48B ''list/genome_history'':30B ''md5'':70B ''mock'':62B ''prompt.ts'':52B ''read'':27B ''rollback'':43B ''schema'':32B,53B ''sdk'':9A,20B ''semver'':45B,55B,63B ''string'':34B ''tools_genome_verification_20260831.md'':75B ''update/genome_promote'':36B ''version'':59B ''w'':7A,18B ''w-9bbe3e64'':6A,17B ''一致'':71B ''但仅'':25B ''假通过'':66B ''先写盘'':37B ''单测'':61B ''危险副作用'':41B ''双层失败'':44B ''可用'':28B ''后绑定报错'':40B ''字符串'':56B ''工具'':24B ''工具专项验证'':5A,16B ''已恢复原状'':69B ''已挂载'':10A,21B ''快照'':49B ''无'':47B ''校验'':46B ''根因'':50B ''用'':54B ''线上'':67B ''线上插件用整数版本'':57B ''绑定层拒绝数字版本'':31B ''要求'':33B ''详见'':74B ''造成'':64B ''重构后'':51B', '2026-08-31 00:07:17.20503', '2026-08-31 00:07:17.20503', '{}');
