INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('dbc8ecc7-55b6-41b5-ac8f-211eed8dc2f7', 'DSH 会话加载报 SessionPersistenceCorruptionError 的根因与修复', 'DSH 会话加载报 SessionPersistenceCorruptionError 的根因与修复（2026-08-31 00:58, w-d8c936df）：anchored-tool-bootstrap 插件（~/.dsh-agent-dh/.agent-presets/liangshen/tool-bootstrap.mjs）buildInstructionHint() 构造的 instruction-hint user/message 缺少 id，DSH 加载校验 packages/core/session/src/index.ts assertMessageEventShape 要求 user/message/assistant/message/tool/result 必须有非空 message.id，导致含该提醒的会话从磁盘加载时失败。每次 promotion/compaction 后都会注入一条 → 一个会话多条。修复：① 已给插件补 randomUUID() id（import node:crypto，备份 /tmp/tool-bootstrap.mjs.bak-1788109105），新会话不再产生坏事件；② 已批量修复 28 个损坏会话文件（47 条事件补 id，备份 /tmp/session-repair-backup-1788108955），9bbe3e64/e7ea99c4 等历史会话现在可正常加载；③ 活跃会话 d8c936df/a1484624 的磁盘文件仍含旧坏事件，须在服务停止后用 /tmp/repair_active_sessions.py 补修。经验：DSH 会话是 zstd 压缩 JSONL（~/.dsh-agent-dh/sessions），工具注入的消息必须带 id，修坏文件=解压→给缺失 id 的消息补 id→重新压缩。', 'experience', '{DSH,session,SessionPersistenceCorruptionError,instruction-hint,tool-bootstrap,修复,w-d8c936df}', NULL, '''-08'':10B ''-31'':11B ''/.dsh-agent-dh/.agent-presets/liangshen/tool-bootstrap.mjs'':22B ''/.dsh-agent-dh/sessions'':76B ''/tmp/repair_active_sessions.py'':68B ''/tmp/session-repair-backup-1788108955'':61B ''/tmp/tool-bootstrap.mjs.bak-1788109105'':52B ''00'':12B ''2026'':9B ''28'':55B ''47'':57B ''58'':13B ''9bbe3e64/e7ea99c4'':62B ''anchored'':18B ''anchored-tool-bootstrap'':17B ''assertmessageeventshape'':34B ''bootstrap'':20B ''buildinstructionhint'':23B ''crypto'':50B ''d8c936df'':16B ''d8c936df/a1484624'':65B ''dsh'':1A,5B,31B,71B ''hint'':27B ''id'':30B,47B,59B,78B,82B,84B ''import'':48B ''instruction'':26B ''instruction-hint'':25B ''jsonl'':75B ''message.id'':38B ''node'':49B ''packages/core/session/src/index.ts'':33B ''promotion/compaction'':41B ''randomuuid'':46B ''sessionpersistencecorruptionerror'':3A,7B ''tool'':19B ''user/message'':28B ''user/message/assistant/message/tool/result'':36B ''w'':15B ''w-d8c936df'':14B ''zstd'':73B ''一个会话多条'':43B ''个损坏会话文件'':56B ''会话加载报'':2A,6B ''会话是'':72B ''修坏文件'':79B ''修复'':44B ''加载校验'':32B ''压缩'':74B ''后都会注入一条'':42B ''备份'':51B,60B ''导致含该提醒的会话从磁盘加载时失败'':39B ''工具注入的消息必须带'':77B ''已批量修复'':54B ''已给插件补'':45B ''必须有非空'':37B ''插件'':21B ''新会话不再产生坏事件'':53B ''条事件补'':58B ''构造的'':24B ''每次'':40B ''活跃会话'':64B ''的根因与修复'':4A,8B ''的消息补'':83B ''的磁盘文件仍含旧坏事件'':66B ''等历史会话现在可正常加载'':63B ''经验'':70B ''给缺失'':81B ''缺少'':29B ''补修'':69B ''要求'':35B ''解压'':80B ''重新压缩'':85B ''须在服务停止后用'':67B', '2026-08-31 00:58:54.644632', '2026-08-31 00:58:54.644632', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('16c4fd1e-a0a2-4d67-8882-21ae1c5f6267', 'DSH-SESSION-REPAIR loss 修复 DSH 会话文件（zstd 多帧 JSONL）时，用 zstd CLI 把整个 JSONL 压成单帧，导致', 'DSH-SESSION-REPAIR 交易经验（2026-08-30T17:12:23.806Z）
场景：修复 DSH 会话文件（zstd 多帧 JSONL）时，用 zstd CLI 把整个 JSONL 压成单帧，导致 session.list 返回 500（corrupt: first frame is not exactly one header line），GUI 新窗口看不到历史
结果：loss
盈亏：0%
教训：DSH 会话文件格式：第一帧=header 行独立压缩（解压后必须恰好一行），后续每批事件各一帧（可多行）；文件末尾必须单个 \n。修复流程=解压→补 id→header 单独压一帧+事件压一帧→用 session.list/session.history RPC 真实验证（仅内容级校验不够）。陷阱：split(''\n'') 的尾随空串不是空行，勿当脏数据剔除；修复后必须用 DSH 真实读取路径（RPC）验证，不能只看 JSON 合法。', 'experience', '{DSH-SESSION-REPAIR,loss}', NULL, '''-08'':26B ''-30'':27B ''/session.history'':86B ''0'':64B ''12'':29B ''2026'':25B ''23.806'':30B ''500'':49B ''cli'':15A,42B ''corrupt'':50B ''dsh'':2A,7A,21B,34B,66B,96B ''dsh-session-repair'':1A,20B ''exactly'':55B ''first'':51B ''frame'':52B ''gui'':59B ''header'':57B,69B,80B ''id'':79B ''is'':53B ''json'':101B ''jsonl'':11A,17A,38B,44B ''line'':58B ''loss'':5A,62B ''n'':75B,92B ''not'':54B ''one'':56B ''repair'':4A,23B ''rpc'':87B,98B ''session'':3A,22B ''session.list'':47B,85B ''session.list/session.history'':84B ''split'':91B ''t17'':28B ''z'':31B ''zstd'':9A,14A,36B,41B ''不能只看'':100B ''事件压一帧'':82B ''交易经验'':24B ''仅内容级校验不够'':89B ''会话文件'':8A,35B ''会话文件格式'':67B ''修复'':6A,33B ''修复后必须用'':95B ''修复流程'':76B ''勿当脏数据剔除'':94B ''单独压一帧'':81B ''压成单帧'':18A,45B ''可多行'':73B ''合法'':102B ''后续每批事件各一帧'':72B ''场景'':32B ''多帧'':10A,37B ''导致'':19A,46B ''把整个'':16A,43B ''教训'':65B ''文件末尾必须单个'':74B ''新窗口看不到历史'':60B ''时'':12A,39B ''用'':13A,40B,83B ''的尾随空串不是空行'':93B ''盈亏'':63B ''真实读取路径'':97B ''真实验证'':88B ''第一帧'':68B ''结果'':61B ''行独立压缩'':70B ''补'':78B ''解压'':77B ''解压后必须恰好一行'':71B ''返回'':48B ''陷阱'':90B ''验证'':99B', '2026-08-31 01:12:23.808694', '2026-08-31 01:12:23.808694', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('83f62ced-d86b-4ed0-bde0-f33c72af684c', 'DSH 会话持久化格式（session-persistence-jsonl）：zstd 多帧，第一帧', 'DSH 会话持久化格式（session-persistence-jsonl）：zstd 多帧，第一帧=header JSON 行（解压后恰好一行以 \n 结尾），后续每 append 批次一帧（多行）；文件末尾单个 \n。用 zstd CLI 单帧压缩会触发 ''first frame is not exactly one header line''；事件帧内空行触发 ''complete frame contains a torn JSONL record''。修复标准流程：解压→按行修事件→header 单独 compressZstdFrame + 事件 compressZstdFrame 拼接→RPC 验证 session.list 与 session.history。备份目录 /tmp/session-rewrite-backup-*、/tmp/session-blankline-backup-*。28+8 个损坏会话已修复并通过 RPC 验证（13080 端口 session.list 372 个会话、history 全部可加载）。', 'experience', '{DSH,会话修复,zstd,session-persistence,session.list,经验教训}', NULL, '''+8'':69B ''/tmp/session-blankline-backup-'':67B ''/tmp/session-rewrite-backup-'':66B ''13080'':73B ''28'':68B ''372'':76B ''a'':47B ''append'':26B ''cli'':33B ''complete'':44B ''compresszstdframe'':56B,58B ''contains'':46B ''dsh'':1A,10B ''exactly'':39B ''first'':35B ''frame'':36B,45B ''header'':19B,41B,54B ''history'':78B ''is'':37B ''json'':20B ''jsonl'':6A,15B,49B ''line'':42B ''n'':23B,30B ''not'':38B ''one'':40B ''persistence'':5A,14B ''record'':50B ''rpc'':60B,71B ''session'':4A,13B ''session-persistence-jsonl'':3A,12B ''session.history'':64B ''session.list'':62B,75B ''torn'':48B ''zstd'':7A,16B,32B ''与'':63B ''个会话'':77B ''个损坏会话已修复并通过'':70B ''事件'':57B ''事件帧内空行触发'':43B ''会话持久化格式'':2A,11B ''修复标准流程'':51B ''全部可加载'':79B ''单帧压缩会触发'':34B ''单独'':55B ''后续每'':25B ''备份目录'':65B ''多帧'':8A,17B ''多行'':28B ''批次一帧'':27B ''拼接'':59B ''按行修事件'':53B ''文件末尾单个'':29B ''用'':31B ''端口'':74B ''第一帧'':9A,18B ''结尾'':24B ''行'':21B ''解压'':52B ''解压后恰好一行以'':22B ''验证'':61B,72B', '2026-08-31 01:12:23.819055', '2026-08-31 01:12:23.819055', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('d4eb9f4e-fad0-4f5b-b18a-317efda2358f', 'reminder daily-trade-verify', '{"prompt": "执行每日对账：调用 trade_verify 工具检查当日交易记录，如有异常立即飞书告警（M5-2 例行任务）。对账完成后简要汇报：交易笔数、勾稽结果（正常/异常）。", "window": "w-6807aa37", "task_id": "fa3aa70a-36e2-4713-9f75-034c46efb2c3", "task": "daily-trade-verify", "fired_at": "2026-08-31T16:54:06.565824+08:00", "delivered": false}', 'data', '{office:reminder,office:reminder:w-6807aa37}', NULL, '''+08'':48B ''-08'':43B ''-2'':14B ''-31'':44B ''-9'':31B ''00'':49B ''034c46efb2c3'':34B ''06.565824'':47B ''2026'':42B ''36e2'':29B ''4713'':30B ''54'':46B ''6807aa37'':24B ''at'':41B ''daily'':3A,37B ''daily-trade-verify'':2A,36B ''delivered'':50B ''f75'':33B ''f75-034c46efb2c3'':32B ''fa3aa70a'':28B ''fa3aa70a-36e2'':27B ''false'':51B ''fired'':40B ''id'':26B ''m5'':13B ''prompt'':6B ''reminder'':1A ''t16'':45B ''task'':25B,35B ''trade'':4A,9B,38B ''verify'':5A,10B,39B ''w'':23B ''w-6807aa37'':22B ''window'':21B ''交易笔数'':17B ''例行任务'':15B ''勾稽结果'':18B ''如有异常立即飞书告警'':12B ''对账完成后简要汇报'':16B ''工具检查当日交易记录'':11B ''异常'':20B ''执行每日对账'':7B ''正常'':19B ''调用'':8B', '2026-08-31 16:54:06.568644', '2026-08-31 16:54:06.568644', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('ab5f58db-f20a-48d9-9dd2-9d912c64822e', 'reminder evolution-distill-daily', '{"prompt": "【每日蒸馏 16:00】执行 daily_distill 工具（days=7, auto_apply=false，预览模式生成改进提案，不直接应用）。若提案数>0：将关键提案写入 memory（namespace=decision，importance=0.6）备查；汇总报告：模式数、建议数、最值得关注的模式（如某类操作成功率过低）。注意：auto_apply 保持 false，进化走 candidate→验证门流程，不要直接改正式基因组。", "window": "w-a8a89c6a", "task_id": "0b61dbe3-704f-4377-ae86-36b848c0f5a4", "task": "evolution-distill-daily", "fired_at": "2026-08-31T22:20:16.842144+08:00", "delivered": false}', 'data', '{office:reminder,office:reminder:w-a8a89c6a}', NULL, '''+08'':70B ''-08'':65B ''-31'':66B ''0'':22B ''0.6'':28B ''00'':9B,71B ''0b61dbe3'':51B ''0b61dbe3-704f'':50B ''16'':8B ''16.842144'':69B ''20'':68B ''2026'':64B ''36b848c0f5a4'':56B ''4377'':53B ''7'':15B ''704f'':52B ''a8a89c6a'':47B ''ae86'':55B ''ae86-36b848c0f5a4'':54B ''apply'':17B,37B ''at'':63B ''auto'':16B,36B ''candidate'':41B ''daily'':5A,11B,61B ''days'':14B ''decision'':26B ''delivered'':72B ''distill'':4A,12B,60B ''evolution'':3A,59B ''evolution-distill-daily'':2A,58B ''false'':18B,39B,73B ''fired'':62B ''id'':49B ''importance'':27B ''memory'':24B ''namespace'':25B ''prompt'':6B ''reminder'':1A ''t22'':67B ''task'':48B,57B ''w'':46B ''w-a8a89c6a'':45B ''window'':44B ''不直接应用'':20B ''不要直接改正式基因组'':43B ''保持'':38B ''备查'':29B ''如某类操作成功率过低'':34B ''将关键提案写入'':23B ''工具'':13B ''建议数'':32B ''执行'':10B ''最值得关注的模式'':33B ''模式数'':31B ''每日蒸馏'':7B ''汇总报告'':30B ''注意'':35B ''若提案数'':21B ''进化走'':40B ''预览模式生成改进提案'':19B ''验证门流程'':42B', '2026-08-31 22:20:16.844728', '2026-08-31 22:20:16.844728', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('15ec00e8-f7ab-4574-be0e-52242dda3a76', '定时任务双体系归属（2026-09-02 定型）：OS(public.tasks) 只承载 agen', '定时任务双体系归属（2026-09-02 定型）：OS(public.tasks) 只承载 agent 智能任务并按 agent_line 分两线——profit_engine=盈利引擎系统设计线（盘前/盘中/盘后/M4熔断/M0数据质量/事件日历/止盈提醒 8 个）、autonomy=自主能力体系线（蒸馏/变异/裁决/元学习/学习飞轮周报 5 个）；v2(quant.scheduler_tasks) 承载业务 job 并按 domain 六域打标（data/signal/trading/analysis/report/monitor 共 30 个）。关键教训：判定"OS 任务可否删"要看 v2 原生 job 是否覆盖**告警/主动能力**——v2 307 trade_verify_daily 只自动对账不告警、v2 232 data_quality_check 只检查回填不告警，对应 agent 例行任务（post-market-routine 内嵌对账、data-quality-monitor 脚本告警）才承载了飞书告警层，删 OS 任务前必须核对告警覆盖，否则静默丢功能。纯 DB 加列对显式列读写系统零影响。', 'knowledge', '{scheduler,agent_line,domain,OS,v2,任务治理}', NULL, '''-02'':4A,13B ''-09'':3A,12B ''/m0'':31B ''/m4'':29B ''2026'':2A,11B ''232'':76B ''30'':56B ''307'':70B ''5'':44B ''8'':35B ''agen'':9A ''agent'':18B,20B,82B ''autonomy'':37B ''check'':79B ''daily'':73B ''data'':77B,90B ''data-quality-monitor'':89B ''data/signal/trading/analysis/report/monitor'':54B ''db'':100B ''domain'':52B ''engine'':24B ''job'':50B,65B ''line'':21B ''market'':86B ''monitor'':92B ''os'':6A,15B,60B,96B ''post'':85B ''post-market-routine'':84B ''profit'':23B ''public.tasks'':7A,16B ''quality'':78B,91B ''quant.scheduler'':47B ''routine'':87B ''tasks'':48B ''trade'':71B ''v2'':46B,63B,69B,75B ''verify'':72B ''个'':36B,45B,57B ''主动能力'':68B ''事件日历'':33B ''任务前必须核对告警覆盖'':97B ''任务可否删'':61B ''例行任务'':83B ''元学习'':42B ''六域打标'':53B ''共'':55B ''关键教训'':58B ''内嵌对账'':88B ''分两线'':22B ''删'':95B ''判定'':59B ''加列对显式列读写系统零影响'':101B ''原生'':64B ''变异'':40B ''只承载'':8A,17B ''只检查回填不告警'':80B ''只自动对账不告警'':74B ''否则静默丢功能'':98B ''告警'':67B ''学习飞轮周报'':43B ''定型'':5A,14B ''定时任务双体系归属'':1A,10B ''对应'':81B ''并按'':51B ''才承载了飞书告警层'':94B ''承载业务'':49B ''数据质量'':32B ''是否覆盖'':66B ''智能任务并按'':19B ''止盈提醒'':34B ''熔断'':30B ''盈利引擎系统设计线'':25B ''盘中'':27B ''盘前'':26B ''盘后'':28B ''纯'':99B ''脚本告警'':93B ''自主能力体系线''