INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('d2866788-492a-447a-a6ba-acea89313d75', 'lifecycle self_restart 重构完成（2026-08-30，窗口 w-a0ef8a', 'lifecycle self_restart 重构完成（2026-08-30，窗口 w-a0ef8aca）：重启器收进 packages/lifecycle/src/restarter/restarter.ts（node 内置依赖，构建产物 dist/restarter/restarter.mjs，tsdown 双入口）。scheduleRestart 完整实现：限流(checkRateLimit 先于 acquireLock，拒绝路径不泄漏锁) → 互斥锁 → createWipBranch 检查点 → writePending(含 last_user_message) → bumpCounter → spawn detached 包内重启器(process.execPath + dist/restarter/restarter.mjs，unref)。续跑消息按 dsh-schedule 模式从 session.events 捕获最后一条 user/message 注入（JSON.stringify 转义，防格式污染）。测试全绿：T1 usage、T2 dry-run(锁释放+配置备份)、T3 故障注入(失败 start.sh → 回滚 main + dead)、T4 成功路径(健康检查 ok)。旧 scripts/self-restart.ts 标记 DEPRECATED。经验：测试 spawn 子进程的代码不要在 bash 工具里跑（detached 孤儿进程会拖垮 bash 会话 300s 超时），改用 run_code 内 Node spawn + 文件轮询；tsdown 多入口输出保留目录结构(dist/restarter/restarter.mjs)', 'experience', '{lifecycle,self_restart,restarter,schedule,2026-08-30}', NULL, '''-08'':6A,17B ''-30'':7A,18B ''2026'':5A,16B ''300s'':99B ''a0ef8a'':11A ''a0ef8aca'':22B ''acquirelock'':36B ''bash'':93B,97B ''bumpcounter'':46B ''checkratelimit'':34B ''code'':103B ''createwipbranch'':39B ''dead'':80B ''deprecated'':88B ''detached'':48B,95B ''dist/restarter/restarter.mjs'':28B,51B,110B ''dry'':70B ''dry-run'':69B ''dsh'':55B ''dsh-schedule'':54B ''json.stringify'':62B ''last'':43B ''lifecycle'':1A,12B ''main'':79B ''message'':45B ''node'':25B,105B ''ok'':84B ''packages/lifecycle/src/restarter/restarter.ts'':24B ''process.execpath'':50B ''restart'':3A,14B ''run'':71B,102B ''schedule'':56B ''schedulerestart'':31B ''scripts/self-restart.ts'':86B ''self'':2A,13B ''session.events'':58B ''spawn'':47B,91B,106B ''start.sh'':77B ''t1'':66B ''t2'':68B ''t3'':74B ''t4'':81B ''tsdown'':29B,108B ''unref'':52B ''usage'':67B ''user'':44B ''user/message'':60B ''w'':10A,21B ''w-a0ef8a'':9A ''w-a0ef8aca'':20B ''writepending'':41B 