INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('b1e05ab6-7e1d-4eb5-8f5b-c171278300a2', '2026-08-31 schema 修复：BaseTool.toDSHToolDefinition(', '2026-08-31 schema 修复：BaseTool.toDSHToolDefinition() 生成的 parameters 原为扁平结构（{symbol:{type,...}}，无顶层 type），dsh schemaOf 原样透传给 deepseek API 导致 "Invalid schema for function ... type: null"（报哪个工具取决于并发注册顺序，本次命中 data_fetch_financial）。修复：输出标准 JSON Schema {type:object, properties, required[]}，required 从属性级提升到顶层数组。core-tool/src/BaseTool.ts 已改（tsx 直跑无需构建）；lifecycle/src/index.ts captureLastUserMessage 已加系统块过滤（/<[a-z-]+>/ 前缀），dist 已重建。需重启进程生效。', 'knowledge', '{schema,BaseTool,data_fetch_financial,重启}', NULL, '''-08'':2A,8B ''-31'':3A,9B ''/src/basetool.ts'':50B ''2026'':1A,7B ''a'':58B ''a-z'':57B ''api'':24B ''basetool.todshtooldefinition'':6A,12B ''capturelastusermessage'':55B ''core'':48B ''core-tool'':47B ''data'':34B ''deepseek'':23B ''dist'':61B ''dsh'':20B ''fetch'':35B ''financial'':36B ''for'':28B ''function'':29B ''invalid'':26B ''json'':39B ''lifecycle/src/index.ts'':54B ''null'':31B ''object'':42B ''parameters'':14B ''properties'':43B ''required'':44B,45B ''schema'':4A,10B,27B,40B ''schemaof'':21B ''symbol'':16B ''tool'':49B ''tsx'':52B ''type'':17B,19B,30B,41B ''z'':59B ''从属性级提升到顶层数组'':46B ''修复'':5A,11B,37B ''前缀'':60B ''原为扁平结构'':15B ''原样透传给'':22B ''导致'':25B ''已加系统块过滤'':56B ''已改'':51B ''已重建'':62B ''报哪个工具取决于并发注册顺序'':32B ''无顶层'':18B ''本次命中'':33B ''生成的'':13B ''直跑无需构建'':53B ''输出标准'':38B ''需重启进程生效'':63B', '2026-08-31 02:24:28.391176', '2026-08-31 02:24:28.391176', '{}');
