INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('3b21df20-6ba9-4e60-ab15-0f9450385809', '盯盘推送链路实测（2026-08-31 23:35）：WatchEngine 判定与落库正常（wat', '盯盘推送链路实测（2026-08-31 23:35）：WatchEngine 判定与落库正常（watch_triggers 1410 条，最近 15:21 歌尔 24.25 触发），但通知链路全断——所有触发 notified=false，零条唤醒日志。根因：quantsys-v2 .env 的 AGENT_API_URL=http://127.0.0.1:3002 指向已停运的旧 agent-ts Wake Gateway（start-wake-channel.ts），3002 无进程监听；当前 Agent 在 DSH 13080，且 13080 无 /wake 端点（POST 405）、agent-dh 插件无任何 wake 事件处理实现；WS 广播目标 5003 也无监听。实测 notify() 3 次重试全败连接拒绝，仅落库成功。影响：所有盯盘规则（止损/止盈/突破）触发后用户从未收到推送。修复方向：①agent-dh 新增 wake 接收端点（HTTP + agent.followup 注入）或②把 AGENT_API_URL 指向有 wake 服务的地址 + 补 5003 WS；③.env 配置与实际服务对齐。', 'experience', '{盯盘,watch,通知链路,断链,3002,wake,P0}', NULL, '''-08'':3A,12B ''-31'':4A,13B ''/wake'':61B ''127.0.0.1'':42B ''13080'':57B,59B ''1410'':20B ''15'':23B ''2026'':2A,11B ''21'':24B ''23'':5A,14B ''24.25'':26B ''3'':77B ''3002'':43B,51B ''35'':6A,15B ''405'':64B ''5003'':73B,105B ''agent'':39B,46B,54B,66B,88B,98B ''agent-dh'':65B,87B ''agent-ts'':45B ''agent.followup'':94B ''api'':40B,99B ''dh'':67B,89B ''dsh'':56B ''env'':37B,107B ''false'':31B ''gateway'':49B ''http'':93B ''notified'':30B ''notify'':76B ''post'':63B ''quantsys'':35B ''quantsys-v2'':34B ''start-wake-channel.ts'':50B ''triggers'':19B ''ts'':47B ''url'':41B,100B ''v2'':36B ''wake'':48B,69B,91B,102B ''wat'':9A ''watch'':18B ''watchengine'':7A,16B ''ws'':71B,106B ''且'':58B ''也无监听'':74B ''事件处理实现'':70B ''仅落库成功'':79B ''但通知链路全断'':28B ''修复方向'':86B ''判定与落库正常'':8A,17B ''在'':55B ''实测'':75B ''广播目标'':72B ''当前'':53B ''影响'':80B ''或'':96B ''所有盯盘规则'':81B ''所有触发'':29B ''把'':97B ''指向已停运的旧'':44B ''指向有'':101B ''接收端点'':92B ''插件无任何'':68B ''新增'':90B ''无'':60B ''无进程监听'':52B ''最近'':22B ''服务的地址'':103B ''条'':21B ''根因'':33B ''次重试全败连接拒绝'':78B ''歌尔'':25B ''止损'':82B ''止盈'':83B ''注入'':95B ''的'':38B ''盯盘推送链路实测'':1A,10B ''突破'':84B ''端点'':62B ''补'':104B ''触发'':27B ''触发后用户从未收到推送'':85B ''配置与实际服务对齐