INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('ee73f80c-874a-4c4c-b881-fefef42456e9', 'M3-2 回测矩阵执行（2026-08-31）：5策略×3区间×16股=240回测落库。验收1/2/', 'M3-2 回测矩阵执行（2026-08-31）：5策略×3区间×16股=240回测落库。验收1/2/3通过，验收4未达标（0策略avg Sharpe>1，最高macd 0.825）。根因：计划将2023标为"牛市"但真实为弱市（茅台-0.2%/五粮液-21%/宁德-26%），2024H2标为"熊市"实为924反弹市（宁德+51%）。教训：回测矩阵的市场区间标签必须用真实指数/样本股走势验证，不能凭直觉假设牛熊；做多趋势策略在弱市亏损是正确行为，夏普被弱市拖累≠策略无效。策略平均收益全正（+6.5%~+13%），macd/rsi在震荡/反弹市夏普>1，弱市需规避或反向。', 'knowledge', '{M3-2,回测矩阵,市场区间,夏普,策略评估}', NULL, '''+13'':54B ''+51'':44B ''+6.5'':53B ''-0.2'':35B ''-08'':5A,16B ''-2'':2A,13B ''-21'':37B ''-26'':39B ''-31'':6A,17B ''0.825'':29B ''0策略avg'':25B ''1'':27B,58B ''16股'':9A,20B ''2024h2标为'':40B ''2026'':4A,15B ''240回测落库'':10A,21B ''3区间'':8A,19B ''5策略'':7A,18B ''m3'':1A,12B ''macd/rsi'':55B ''sharpe'':26B ''不能凭直觉假设牛熊'':48B ''五粮液'':36B ''但真实为弱市'':33B ''做多趋势策略在弱市亏损是正确行为'':49B ''反弹市夏普'':57B ''回测矩阵执行'':3A,14B ''回测矩阵的市场区间标签必须用真实指数'':46B ''在震荡'':56B ''夏普被弱市拖累'':50B ''宁德'':38B,43B ''实为924反弹市'':42B ''弱市需规避或反向'':59B ''教训'':45B ''最高macd'':28B ''样本股走势验证'':47B ''根因'':30B ''熊市'':41B ''牛市'':32B ''策略平均收益全正'':52B ''策略无效'':51B ''茅台'':34B ''计划将2023标为'':31B ''通过'':23B ''验收1/2'':11A ''验收1/2/3'':22B ''验收4未达标'':24B', '2026-08-31 23:35:57.826617', '2026-08-31 23:35:57.826617', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('92623ab6-e6e5-4591-b876-88338a942e69', 'BACKTEST-MATRIX neutral M3-2 回测矩阵：5 策略 × 3 区间 × 16 股 = 240 回测。计划预期 3 策略夏普>1，实际 0', 'BACKTEST-MATRIX 交易经验（2026-08-31T15:36:00.929Z）
场景：M3-2 回测矩阵：5 策略 × 3 区间 × 16 股 = 240 回测。计划预期 3 策略夏普>1，实际 0 达标（macd 最高 0.825），但策略平均收益全正（+6.5%~+13%）。
结果：neutral
盈亏：0%
教训：回测矩阵的市场区间标签（牛/熊/震荡）必须用真实指数或样本股走势验证后再定，不能凭日历或直觉假设。M3-2 计划把 2023 标为"牛市"（实际样本股 -0.2%~-26%）、2024H2 标为"熊市"（实际 924 反弹 +9%~+51%），导致验收 4（≥3 策略 avg Sharpe>1）必然失败——做多趋势策略在真弱市亏损是正确行为，用错误标签推导预期值会让"策略无效"误判"计划失败"。', 'experience', '{BACKTEST-MATRIX,neutral}', NULL, '''+13'':57B ''+51'':85B ''+6.5'':56B ''+9'':84B ''-0.2'':76B ''-08'':27B ''-2'':6A,35B,70B ''-26'':77B ''-31'':28B ''0'':21A,50B,61B ''0.825'':54B ''00.929'':31B ''1'':19A,48B,92B ''16'':12A,41B ''2023'':72B ''2024h2'':78B ''2026'':26B ''240'':14A,43B ''3'':10A,17A,39B,46B,88B ''36'':30B ''4'':87B ''5'':8A,37B ''924'':82B ''avg'':90B ''backtest'':2A,23B ''backtest-matrix'':1A,22B ''m3'':5A,34B,69B ''macd'':52B ''matrix'':3A,24B ''neutral'':4A,59B ''sharpe'':91B ''t15'':29B ''z'':32B ''不能凭日历或直觉假设'':68B ''交易经验'':25B ''但策略平均收益全正'':55B ''做多趋势策略在真弱市亏损是正确行为'':94B ''区间'':11A,40B ''反弹'':83B ''回测'':15A,44B ''回测矩阵'':7A,36B ''回测矩阵的市场区间标签'':63B ''场景'':33B ''实际'':20A,49B,81B ''实际样本股'':75B ''导致验收'':86B ''必然失败'':93B ''必须用真实指数或样本股走势验证后再定'':67B ''教训'':62B ''最高'':53B ''标为'':73B,79B ''熊'':65B ''熊市'':80B ''牛'':64B ''牛市'':74B ''用错误标签推导预期值会让'':95B ''盈亏'':60B ''策略'':9A,38B,89B ''策略夏普'':18A,47B ''策略无效'':96B ''结果'':58B ''股'':13A,42B ''计划失败'':98B ''计划把'':71B ''计划预期'':16A,45B ''误判'':97B ''达标'':51B ''震荡'':66B', '2026-08-31 23:36:00.931269', '2026-08-31 23:36:00.931269', '{}');
