INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('f4ae8fa7-0bbe-4570-a729-b25faade939c', '调度监控 P4 第1层执行保障（2026-09-02，commit d2316a4a）：核心发现 A', '调度监控 P4 第1层执行保障（2026-09-02，commit d2316a4a）：核心发现 APScheduler 的 misfire 机制本身就是启动补跑——scheduler.start() 时检查 job store，next_run 已过期且 < misfire_grace_time 的 job 自动补跑一次（coalesce=False 保证每个错过触发都执行、max_instances=1 防并发），无需额外启动补跑代码。配置：24 幂等任务 grace→3600s、4 时点敏感→600s、高频 */5 保持默认。关键教训：①cron 时区判定必须以 apscheduler_jobs.next_run_time 实测排期为准（v2 cron ''0 8'' 排期在北京 08:00 = CST），不能被历史 scheduler_runs 误导（8/26 前是 APScheduler 未启用期旧数据）；②v2 与 Agent OS cron 均按北京时区解读（robfig/cron time.Local=Asia/Shanghai）；③看门狗初版误将 v2 按 UTC 推算已修正为 CST。第1层（misfire 治本）+第3层（看门狗兜底）结合才是"保证任务都执行"的完整闭环。P6 自动补跑白名单待观察稳定后开启。', 'knowledge', '{调度监控,misfire,APScheduler,执行保障,cron时区,RFC011,启动补跑}', NULL, '''-02'':6A,16B ''-09'':5A,15B ''/5'':54B ''0'':65B ''00'':69B ''08'':68B ''1'':42B ''2026'':4A,14B ''24'':46B ''3600s'':49B ''4'':50B ''600s'':52B ''8'':66B ''8/26'':75B ''a'':10A ''agent'':81B ''apscheduler'':20B,77B ''apscheduler_jobs.next'':59B ''asia/shanghai'':87B ''coalesce'':37B ''commit'':7A,17B ''cron'':57B,64B,83B ''cst'':70B,93B ''d2316a4a'':8A,18B ''false'':38B ''grace'':32B,48B ''instances'':41B ''job'':26B,35B ''max'':40B ''misfire'':22B,31B,95B ''next'':28B ''os'':82B ''p4'':2A,12B ''p6'':102B ''robfig/cron'':85B ''run'':29B,60B ''runs'':73B ''scheduler'':72B ''scheduler.start'':24B ''store'':27B ''time'':33B,61B ''time.local'':86B ''utc'':91B ''v2'':63B,79B,89B ''不能被历史'':71B ''与'':80B ''保持默认'':55B ''保证任务都执行'':100B ''保证每个错过触发都执行'':39B ''关键教训'':56B ''前是'':76B ''均按北京时区解读'':84B ''实测排期为准'':62B ''已过期且'':30B ''幂等任务'':47B ''按'':90B ''排期在北京'':67B ''推算已修正为'':92B ''无需额外启动补跑代码'':44B ''时区判定必须以'':58B ''时检查'':25B ''时点敏感'':51B ''未启用期旧数据'':78B ''机制本身就是启动补跑'':23B ''核心发现'':9A,19B ''治本'':96B ''的'':21B,34B ''的完整闭环'':101B ''看门狗兜底'':98B ''看门狗初版误将'':88B ''第1层'':94B ''第1层执行保障'':3A,13B ''第3层'':97B ''结合才是'':99B ''自动