INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('92e7da6e-e5af-4ba5-ba5d-187838c233b7', '工程管理偏好（2026-09-01，用户明确指示，investor w-8366e526）：禁止制造', '工程管理偏好（2026-09-01，用户明确指示，investor w-8366e526）：禁止制造散落在 quantsys-v2/tools/ 的零散分析脚本（如 run_m62_attribution.py），不利于长期管理。分析/计算功能必须做成 quantsys-v2 后端正式 API 端点，或 agent-dh 注册的工具（Tool），保证可维护、可复用、可测试。已有散落脚本（run_m62_attribution.py / run_m64_*.py）应迁移为正式 API 后淘汰删除。后续所有"分析功能"一律先规划 API 端点/工具注册，再实现。', 'knowledge', '{工程规范,用户偏好,API设计,脚本治理}', NULL, '''-01'':4A,14B ''-09'':3A,13B ''/tools'':24B ''2026'':2A,12B ''8366e526'':9A,19B ''agent'':39B ''agent-dh'':38B ''api'':35B,52B,57B ''dh'':40B ''investor'':6A,16B ''m64'':49B ''py'':50B ''quantsys'':22B,32B ''quantsys-v2'':21B,31B ''run'':48B ''run_m62_attribution.py'':27B,47B ''tool'':42B ''v2'':23B,33B ''w'':8A,18B ''w-8366e526'':7A,17B ''一律先规划'':56B ''不利于长期管理'':28B ''保证可维护'':43B ''再实现'':60B ''分析'':29B ''分析功能'':55B ''可复用'':44B ''可测试'':45B ''后淘汰删除'':53B ''后端正式'':34B ''后续所有'':54B ''如'':26B ''工具注册'':59B ''工程管理偏好'':1A,11B ''已有散落脚本'':46B ''应迁移为正式'':51B ''或'':37B ''注册的工具'':41B ''用户明确指示'':5A,15B ''的零散分析脚本'':25B ''禁止制造'':10A ''禁止制造散落在'':20B ''端点'':36B,58B ''计算功能必须做成'':30B', '2026-09-01 01:55:36.16343', '2026-09-01 01:55:36.16343', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('38b2521f-d874-4c98-a4f1-453759eac8a7', 'M7-2 散户恐慌代理指标（2026-09-01，investor w-8366e526）：新增连续', 'M7-2 散户恐慌代理指标（2026-09-01，investor w-8366e526）：新增连续 0-100 恐慌指数替代原离散三档（20/50/80）。五维合成：散户资金流30% + 涨跌家数比25% + 恐慌贪婪指数20% + 量能15% + 波动率10%，缺失维度按剩余权重归一。后端 RetailPanicIndexService + API GET /api/market/perception/panic-index(/series)，Agent 工具 retail_panic_index（competition 插件第4个）。实测：8/28 指数 19.6(贪婪,fg=95 吻合)、8/24 曾 56.6(偏恐慌)。等级阈值：≥70 恐慌/50-70 偏恐慌/30-50 偏贪婪/<30 贪婪。应用方向：恐慌指数≥70 结合 opponent_behavior 找"散户割肉"标的（收割机会）。', 'knowledge', '{M7,M7-2,散户恐慌,panic-index,retail_panic_index}', NULL, '''-01'':6A,17B ''-09'':5A,16B ''-100'':24B ''-2'':2A,13B ''/30-50'':64B ''/50-70'':62B ''/api/market/perception/panic-index'':38B ''/series'':39B ''0'':23B ''19.6'':50B ''20/50/80'':26B ''2026'':4A,15B ''30'':66B ''56.6'':57B ''70'':60B,70B ''8/24'':55B ''8/28'':48B ''8366e526'':10A,21B ''95'':53B ''agent'':40B ''api'':36B ''behavior'':73B ''competition'':45B ''fg'':52B ''get'':37B ''index'':44B ''investor'':7A,18B ''m7'':1A,12B ''opponent'':72B ''panic'':43B ''retail'':42B ''retailpanicindexservice'':35B ''w'':9A,20B ''w-8366e526'':8A,19B ''五维合成'':27B ''偏恐慌'':58B,63B ''偏贪婪'':65B ''后端'':34B ''吻合'':54B ''实测'':47B ''工具'':41B ''应用方向'':68B ''恐慌'':61B ''恐慌指数'':69B ''恐慌指数替代原离散三档'':25B ''恐慌贪婪指数20'':30B ''找'':74B ''指数'':49B ''插件第4个'':46B ''收割机会'':77B ''散户割肉'':75B ''散户恐慌代理指标'':3A,14B ''散户资金流30'':28B ''新增连续'':11A,22B ''曾'':56B ''标的'':76B ''波动率10'':32B ''涨跌家数比25'':29B ''等级阈值'':59B ''结合'':71B ''缺失维度按剩余权重归一'':33B ''贪婪'':51B,67B ''量能15'':31B', '2026-09-01 02:09:13.037127', '2026-09-01 02:09:13.037127', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('62471d2a-5e43-498c-9a1b-5379efa2109d', '临时解决办法审计（2026-09-01，报告 docs/work-logs/2026-09/temp', '临时解决办法审计（2026-09-01，报告 docs/work-logs/2026-09/temp-solutions-audit.md，commit 0282d34a）：发现 4 类 16 处。A 类调度脱离工具层：os-remind-bridge.sh 桥接 15 个 agent 提醒任务（Agent OS cron→shell→OS 信箱→lifecycle 轮询投递），signal-perf-backfill.sh/verify.sh 绕过工具直 curl 后端（verify 还硬编码飞书 webhook）。B 类职责倒挂：25 个数据任务由 Agent OS(Go legacy) 做 cron webhook 到 quantsys-v2，而 v2 自己的 SchedulerService(infrastructure/scheduler/scheduler.py) 生产未启用，2026-08-13 迁移后又注册回 Agent OS 形成双轨。C 类 legacy 依赖：memory/notification/scheduler 等 10 个插件依赖 agent-os-client，而 v2 有 memory_async.py/feishu_service.py 对应功能。D 类：硬编码飞书 webhook 2 处、一次性脚本 18 个、空文件 pack-for-profile.sh。修复优先级：P0 调度职责收口到 v2 + scheduler 插件原生投递；P1 回填工具化 + memory/notification 切 v2 + webhook 清理；P2 脚本清理 + TODO 清理。', 'knowledge', '{临时方案,审计,调度,agent-os-client,SchedulerService,os-remind-bridge,重构}', NULL, '''-01'':4A,10B ''-08'':67B ''-09'':3A,9B ''-13'':68B ''/feishu_service.py'':90B ''/verify.sh'':38B ''0282d34a'':14B ''10'':79B ''15'':24B ''16'':18B ''18'':99B ''2'':96B ''2026'':2A,8B,66B ''25'':47B ''4'':16B ''a'':20B ''agent'':26B,28B,49B,70B,82B ''agent-os-client'':81B ''b'':45B ''c'':73B ''client'':84B ''commit'':13B ''cron'':30B,54B ''curl'':40B ''d'':92B ''docs/work-logs/2026-09/temp'':6A ''docs/work-logs/2026-09/temp-solutions-audit.md'':12B ''go'':51B ''infrastructure/scheduler/scheduler.py'':64B ''legacy'':52B,75B ''lifecycle'':34B ''memory/notification'':111B ''memory/notification/scheduler'':77B ''memory_async.py'':89B ''memory_async.py/feishu_service.py'':88B ''os'':29B,32B,50B,71B,83B ''os-remind-bridge.sh'':22B ''p0'':104B ''p1'':109B ''p2'':116B ''pack-for-profile.sh'':102B ''quantsys'':58B ''quantsys-v2'':57B ''scheduler'':107B ''schedulerservice'':63B ''shell'':31B ''signal-perf-backfill.sh'':37B ''signal-perf-backfill.sh/verify.sh'':36