INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('2b0d33ab-1c5c-44af-857a-74233e6a9b22', 'M7-3 profit 操纵检测实战验证：8/28 涨停池 50 只无一达 3 信号阈值，逐一排查发现信号桩/数据源错误/落库僵尸桩三类问题', 'M7-3 交易经验（2026-08-31T18:40:07.265Z）
