INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('298254d5-6f57-4585-ad0f-9e8ad8218537', 'reminder meta-learning-weekly', '{"prompt": "【Phase 4 元学习-自动启动 周日11:30】裁决（11:00 evolution-gate-adjudicate）完成后自动执行：①检查数据门槛：genome_history 最近是否新增 ≥1 轮完整闭环（candidate→promote/rollback，含本周变异记录）；②门槛满足→执行元学习分析：用 memory_search(namespace=decision) 检索本周蒸馏/变异/裁决记录，产出「哪类变异有效」小结（改提示词 vs 加规则 vs 调参数 vs 改代码的胜率贡献），写入 memory(namespace=analysis, importance=0.7)；③P4-2 跨代比较：用 genome_history 对比各代表现，记录当前最优代与原因；④飞书汇报：本周闭环是否完成、元学习结论、当前基因组版本。若门槛未满足（闭环数据不足），记录 waiting 状态到 memory 并飞书说明，不强行产出。", "window": "w-a8a89c6a", "task_id": "87f24466-2149-47d3-9d47-25a2688bd51e", "task": "meta-learning-weekly", "fired_at": "2026-09-01T02:11:01.021774+08:00", "delivered": false}', 'data', '{office:reminder,office:reminder:w-a8a89c6a}', NULL, '''+08'':103B ''-01'':99B ''-09'':98B ''-2'':58B ''-2149'':84B ''-47'':85B ''0.7'':56B ''00'':16B,104B ''01.021774'':102B ''1'':26B ''11'':15B,101B ''2026'':97B ''25a2688bd51e'':89B ''30'':13B ''4'':8B ''87f24466'':83B ''9d47'':88B ''a8a89c6a'':80B ''adjudicate'':20B ''analysis'':54B ''at'':96B ''candidate'':28B ''d3'':87B ''d3-9d47-25a2688bd51e'':86B ''decision'':37B ''delivered'':105B ''evolution'':18B ''evolution-gate-adjudicate'':17B ''false'':106B ''fired'':95B ''gate'':19B ''genome'':23B,61B ''history'':24B,62B ''id'':82B ''importance'':55B ''learning'':4A,93B ''memory'':34B,52B,74B ''meta'':3A,92B ''meta-learning-weekly'':2A,91B ''namespace'':36B,53B ''p4'':57B ''phase'':7B ''promote/rollback'':29B ''prompt'':6B ''reminder'':1A ''search'':35B ''t02'':100B ''task'':81B,90B ''vs'':45B,47B,49B ''w'':79B ''w-a8a89c6a'':78B ''waiting'':72B ''weekly'':5A,94B ''window'':77B ''不强行产出'':76B ''产出'':41B ''元学习'':10B ''元学习-自动启动'':9B ''元学习结论'':67B ''写入'':51B ''加规则'':46B ''变异'':39B ''含本周变异记录'':30B ''周日11'':12B ''哪类变异有效'':42B ''完成后自动执行'':21B ''对比各代表现'':63B ''小结'':43B ''并飞书说明'':75B ''当前基因组版本'':68B ''执行元学习分析'':