INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('476e8f17-80b7-41aa-8faa-ab2e3a567e60', 'MACD-CANDIDATE neutral M6-4 evolution candidate 参数扩大验证：敏感性测试（2股×3时段混合区间）选出 macd ', 'MACD-CANDIDATE 交易经验（2026-08-31T16:26:46.895Z）
场景：M6-4 evolution candidate 参数扩大验证：敏感性测试（2股×3时段混合区间）选出 macd fast5/slow13/sig3 为最优，16股×2024H1/H2 强势区间扩大验证发现默认参数 Sharpe 1.178 优于 candidate 1.005，拒绝转正
结果：neutral
盈亏：0%
教训：参数敏感性测试若混合不同市场状态区间（弱市+强市），会给出误导性的"最优参数"：macd fast5/slow13/sig3 在 2 股×混合区间测试中 Sharpe 0.137 看似优于默认 -0.045，但在 16 股×强势区间（2024H1/H2）扩大验证中反而不如默认（1.005 vs 1.178）。参数调优必须在同质市场状态下分别验证，且小样本敏感性结论必须经全量扩大验证后才可转正。', 'experience', '{MACD-CANDIDATE,neutral}', NULL, '''-0.045'':67B ''-08'':20B ''-31'':21B ''-4'':6A,28B ''0'':51B ''0.137'':65B ''1.005'':46B,74B ''1.178'':43B,76B ''16'':69B ''16股'':39B ''2'':61B ''2024h1/h2'':40B,72B ''2026'':19B ''26'':23B ''2股'':11A,33B ''3时段混合区间'':12A,34B ''46.895'':24B ''candidate'':3A,8A,17B,30B,45B ''evolution'':7A,29B ''fast5/slow13/sig3'':37B,59B ''m6'':5A,27B ''macd'':2A,14A,16B,36B,58B ''macd-candidate'':1A,15B ''neutral'':4A,49B ''sharpe'':42B,64B ''t16'':22B ''vs'':75B ''z'':25B ''且小样本敏感性结论必须经全量扩大验证后才可转正'':78B ''为最优'':38B ''交易经验'':18B ''优于'':44B ''会给出误导性的'':56B ''但在'':68B ''参数扩大验证'':9A,31B ''参数敏感性测试若混合不同市场状态区间'':53B ''参数调优必须在同质市场状态下分别验证'':77B ''在'':60B ''场景'':26B ''弱市'':54B ''强势区间'':71B ''强势区间扩大验证发现默认参数'':41B ''强市'':55B ''扩大验证中反而不如默认'':73B ''拒绝转正'':47B ''敏感性测试'':10A,32B ''教训'':52B ''最优参数'':57B ''混合区间测试中'':63B ''盈亏'':50B ''看似优于默认'':66B ''结果'':48B ''股'':62B,70B ''选出'':13A,35B', '2026-09-01 00:26:46.8966', '2026-09-01 00:26:46.8966', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('ba70ab61-2538-423f-ac9b-ee3db39578c6', '歌尔 002241 决策（2026-09-01，w-5b8aac2a）：Plan B 分批止盈。依据', '歌尔 002241 决策（2026-09-01，w-5b8aac2a）：Plan B 分批止盈。依据：①FGI=100 极端贪婪+euphoria regime（权益上限30%），情绪工具明确建议"逢高减仓"；②筹码获利盘100%，现价24.25已突破90%成本带上沿23.69，全员浮盈兑现压力大；③组合60日回撤-7.72%逼近-8%熔断线，波动率高；④真实仓第一止盈23.9已击穿、虚拟仓24.4差0.6%。方案：虚拟仓600股@22.52开盘减半300股锁+7.7%，剩300股止损上移22.9博25.8；真实仓500股@22.648建议同步减半250股（23.9已破按规则止盈）。48波段全胜+PE分位59%支持留底仓不卖飞。', 'knowledge', '{002241,歌尔,分批止盈,"Plan B",euphoria}', NULL, '''+7.7'':54B ''-01'':6A,19B ''-09'':5A,18B ''-7.72'':41B ''-8'':43B ''002241'':2A,15B ''100'':28B ''2026'':4A,17B ''22.52'':52B ''22.648'':58B ''23.9'':60B ''48波段全胜'':62B ''5b8aac2a'':9A,22B ''b'':11A,24B ''euphoria'':30B ''fgi'':27B ''pe分位59'':63B ''plan'':10A,23B ''regime'':31B ''w'':8A,21B ''w-5b8aac2a'':7A,20B ''依据'':13A,26B ''全员浮盈兑现压力大'':39B ''决策'':3A,16B ''分批止盈'':12A,25B ''剩300股止损上移22.9'':55B ''博25.8'':56B ''差0.6'':49B ''已击穿'':47B ''已破按规则止盈'':61B ''已突破90'':37B ''建议同步减半250股'':59B ''开盘减半300股锁'':53B ''情绪工具明确建议'':33B ''成本带上沿23.69'':38B ''支持留底仓不卖飞'':64B ''方案'':50B ''权益上限30'':32B ''极端贪婪'':29B ''歌尔'':1A,14B ''波动率高'':45B ''熔断线'':44B ''现价24.25'':36B ''真实仓500股'':57B ''真实仓第一止盈23.9'':46B ''筹码获利盘100'':35B ''组合60日回撤'':40B ''虚拟仓24.4'':48B ''虚拟仓600股'':51B ''逢高减仓'':34B ''逼近'':42B', '2026-09-01 00:31:57.416569', '2026-09-01 00:31:57.416569', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('306837b1-fb00-4025-ad0f-42d93834e178', 'MACD-RISK-CTRL neutral M6-4 回撤控制验证：16股×3时段真实回测对比 macd 默认 vs 个股200MA过滤 vs 沪深300过滤', 'MACD-RISK-CTRL 交易经验（2026-08-31T17:13:27.150Z）
场景：M6-4 回撤控制验证：16股×3时段真实回测对比 macd 默认 vs 个股200MA过滤 vs 沪深300过滤 vs 追踪止损8%
结果：neutral
盈亏：0%
教训：止损与市场状态过滤的适用边界：① 追踪止损（跌破N日高点8%）在趋势市（2024H2）有效改善Sharpe（0.944→1.342）与回撤（-15.8%→-11.9%），但在弱市（2023）被反复扫损恶化（Sharpe 0.024→-0.39）——弱市止损是"割肉在地板"；② 静态大盘200MA过滤会错杀强势个股（2024H1 macd 1.238→-0.121），个股200MA过滤中性（Sharpe略降回撤略降）；③ 最优组合=市场状态过滤（弱市空仓，macd全周期Sharpe 0.825→1.178）+ 仅在非弱市时段启用止损。经验：验证止损/过滤类优化必须分市场状态评估，只看全周期均值会掩盖弱市恶化。', 'experience', '{MACD-RISK-CTRL,neutral}', NULL, '''-0.121'':71B ''-0.39'':64B ''-08'':23B ''-11.9'':58B ''-15.8'':57B ''-31'':24B ''-4'':7A,31B ''0'':46B ''0.024'':63B ''0.825'':78B ''0.944'':54B ''1.178'':79B ''1.238'':70B ''1.342'':55B ''13'':26B ''16股'':9A,33B ''2023'':60B ''2024h1'':68B ''2024h2'':52B ''2026'':22B ''27.150'':27B ''3时段真实回测对比'':10A,34B ''ctrl'':4A,20B ''m6'':6A,30B ''macd'':2A,11A,18B,35B,69B ''macd-risk-ctrl'':1A,17B ''macd全周期sharpe'':77B ''neutral'':5A,44B ''risk'':3A,19B ''sharpe'':62B ''sharpe略降回撤略降'':73B ''t17'':25B ''vs'':13A,15A,37B,39B,41B ''z'':28B ''与回撤'':56B ''个股200ma过滤'':14A,38B ''个股200ma过滤中性'':72B ''交易经验'':21B ''仅在非弱市时段启用止损'':80B ''但在弱市'':59B ''割肉在地板'':66B ''只看全周期均值会掩盖弱市恶化'':84B ''回撤控制验证'':8A,32B ''在趋势市'':51B ''场景'':29B ''市场状态过滤'':75B ''弱市止损是'':65B ''弱市空仓'':76B ''教训'':47B ''最优组合'':74B ''有效改善sharpe'':53B ''止损与市场状态过滤的适用边界'':48B ''沪深300过滤'':16A,40B ''盈亏'':45B ''经验'':81B ''结果'':43B ''被反复扫损恶化'':61B ''跌破n日高点8'':50B ''过滤类优化必须分市场状态评估'':83B ''追踪止损'':49B ''追踪止损8'':42B ''静态大盘200ma过滤会错杀强势个股'':67B ''验证止损'':82B ''默认'':12A,36B', '2026-09-01 01:13:27.15377', '2026-09-01 01:13:27.15377', '{}');
