INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('5b65d70a-ae38-436b-b3cb-2d24aac34b3f', 'reminder evolution-distill-daily', '{"prompt": "【每日蒸馏 16:00】执行 daily_distill 工具（days=7, auto_apply=false，预览模式生成改进提案，不直接应用）。若提案数>0：将关键提案写入 memory（namespace=decision，importance=0.6）备查；汇总报告：模式数、建议数、最值得关注的模式（如某类操作成功率过低）。注意：auto_apply 保持 false，进化走 candidate→验证门流程，不要直接改正式基因组。", "window": "w-a8a89c6a", "task_id": "0b61dbe3-704f-4377-ae86-36b848c0f5a4", "task": "evolution-distill-daily", "fired_at": "2026-09-01T16:00:00.161259+08:00", "delivered": false}', 'data', '{office:reminder,office:reminder:w-a8a89c6a}', NULL, '''+08'':70B ''-01'':66B ''-09'':65B ''0'':22B ''0.6'':28B ''00'':9B,68B,71B ''00.161259'':69B ''0b61dbe3'':51B ''0b61dbe3-704f'':50B ''16'':8B ''2026'':64B ''36b848c0f5a4'':56B ''4377'':53B ''7'':15B ''704f'':52B ''a8a89c6a'':47B ''ae86'':55B ''ae86-36b848c0f5a4'':54B ''apply'':17B,37B ''at'':63B ''auto'':16B,36B ''candidate'':41B ''daily'':5A,11B,61B ''days'':14B ''decision'':26B ''delivered'':72B ''distill'':4A,12B,60B ''evolution'':3A,59B ''evolution-distill-daily'':2A,58B ''false'':18B,39B,73B ''fired'':62B ''id'':49B ''importance'':27B ''memory'':24B ''namespace'':25B ''prompt'':6B ''reminder'':1A ''t16'':67B ''task'':48B,57B ''w'':46B ''w-a8a89c6a'':45B ''window'':44B ''不直接应用'':20B ''不要直接改正式基因组'':43B ''保持'':38B ''备查'':29B ''如某类操作成功率过低'':34B ''将关键提案写入'':23B ''工具'':13B ''建议数'':32B ''执行'':10B ''最值得关注的模式'':33B ''模式数'':31B ''每日蒸馏'':7B ''汇总报告'':30B ''注意'':35B ''若提案数'':21B ''进化走'':40B ''预览模式生成改进提案'':19B ''验证门流程'':42B', '2026-09-01 16:00:00.164073', '2026-09-01 16:00:00.164073', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('e0c53274-e954-4ead-b31c-05a68cfcdf86', 'agent 提醒任务正规化完成（2026-09-01，ADR-002 Phase 2，commits', 'agent 提醒任务正规化完成（2026-09-01，ADR-002 Phase 2，commits 2a92c0db/facd97eb/6a695616）：DSH lifecycle 插件新增 NativeReminderScheduler（cron.ts 轻量 5/6 段解析器 10/10 单测 + native-scheduler.ts 30s tick 直投 followup + lastFired 持久化防重 + misfire 补偿），替代旧三层桥（Agent OS cron → os-remind-bridge.sh → OS 信箱 → 60s 轮询）。14 个 bridge 任务迁移（payload.executor=''dsh-native'' + command=/bin/true），signal-perf-backfill-daily 禁用（功能与 post-market-routine 重复），signal-perf-verify-0903 改 dsh-native。三脚本已删除。E2E 验证：测试任务 19:09 准时触发投递。关键坑：①Agent OS cron 是 6 段（带秒位）②lifecycle 包入口指向 dist，改动需 pnpm build 才生效（项目唯一需构建的包）③UpdateTask API 不接受 command 字段，需直接改 public.tasks 表 ④misfire 补偿首次运行必须以 now 为基线（否则补投历史导致与旧链路重复执行）。', 'knowledge', '{ADR-002,原生调度器,os-remind-bridge退役,NativeReminderScheduler,cron,lifecycle,"Phase 2"}', NULL, '''-002'':7A,17B ''-01'':5A,15B ''-09'':4A,14B ''/bin/true'':59B ''09'':86B ''0903'':76B ''10/10'':30B ''14'':50B ''19'':85B ''2'':9A,19B ''2026'':3A,13B ''2a92c0db/facd97eb/6a695616'':21B ''30s'':33B ''5/6'':28B ''6'':93B ''60s'':48B ''adr'':6A,16B ''agent'':1A,11B,42B,89B ''api'':105B ''backfill'':63B ''bridge'':52B ''build'':101B ''command'':58B,107B ''commits'':10A,20B ''cron'':44B,91B ''cron.ts'':26B ''daily'':64B ''dist'':98B ''dsh'':22B,56B,79B ''dsh-native'':55B,78B ''e2e'':82B ''followup'':36B ''lastfired'':37B ''lifecycle'':23B,96B ''market'':69B ''misfire'':39B,112B ''native'':57B,80B ''native-scheduler.ts'':32B ''nativereminderscheduler'':25B ''now'':114B ''os'':43B,46B,90B ''os-remind-bridge.sh'':45B ''payload.executor'':54B ''perf'':62B,74B ''phase'':8A,18B ''pnpm'':100B ''post'':68B ''post-market-routine'':67B ''public.tasks'':110B ''routine'':70B ''signal'':61B,73B ''signal-perf-backfill-daily'':60B ''signal-perf-verify'':72B ''tick'':34B ''updatetask'':104B ''verify'':75B 