INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('2d2569d4-ab2b-4215-85b2-9e00e3f7b90d', '定时任务类型分流修复（2026-09-01，commit bc8498ec）：用户提出定时任务分两种', '定时任务类型分流修复（2026-09-01，commit bc8498ec）：用户提出定时任务分两种——①纯提醒发飞书（不经LLM）②需LLM处理再发飞书。核查发现三个问题并已修复：(1) 类型1链路断裂：watch_engine触发走agent_url/wake（3002无监听），watch_triggers 1453次触发仅10.5%送达；(2) notify_mode形同虚设：watch_rules表有notify_mode字段（direct=21/agent=12）但WatchNotifier.notify()不读，全部走agent唤醒；(3) 飞书服务无法初始化：feishu_service用get_config()（返回空dict兼容层）取config.external必崩，正确应get_settings()。修复：WatchNotifier按notify_mode分流（direct直发飞书send_alert，agent唤醒，唤醒失败降级直发飞书兜底）；factory注入feishu_service；feishu_service改get_settings+feishu_bot_token用getattr兜底；geer-take-profit-0901补prompt并补发飞书。已重启v2验证direct模式飞书发送成功。教训：get_config()是空配置兼容层，取配置一律用get_settings()；既有notify_mode字段要检查代码是否真读了。', 'knowledge', '{定时任务,notify_mode,watch_engine,feishu_service,get_settings,类型分流,修复}', NULL, '''-01'':4A,11B ''-09'':3A,10B ''0901补prompt并补发飞书'':71B ''1'':19B ''12'':37B ''1453次触发仅10.5'':27B ''2'':29B ''2026'':2A,9B ''21/agent'':36B ''3'':42B ''3002无监听'':24B ''agent唤醒'':57B ''alert'':56B ''bc8498ec'':6A,13B ''bot'':65B ''commit'':5A,12B ''config'':46B,75B ''direct'':35B ''direct直发飞书send'':55B ''engine触发走agent'':22B ''external必崩'':49B ''factory注入feishu'':59B ''feishu'':44B,61B,64B ''geer'':68B ''geer-take-profit-0901补prompt并补发飞书'':67B ''get'':74B ''mode分流'':54B ''mode字段'':34B ''mode字段要检查代码是否真读了'':80B ''mode形同虚设'':31B ''notify'':30B,39B ''profit'':70B ''rules表有notify'':33B ''service'':60B ''service改get'':62B ''service用get'':45B ''settings'':51B,63B,78B ''take'':69B ''token用getattr兜底'':66B ''triggers'':26B ''url/wake'':23B ''watch'':21B,25B,32B ''watchnotifier按notify'':53B ''不经llm'':16B ''不读'':40B ''但watchnotifier'':38B ''修复'':52B ''全部走agent唤醒'':41B ''取config'':48B ''取配置一律用get'':77B ''唤醒失败降级直发飞书兜底'':58B ''定时任务类型分流修复'':1A,8B ''已重启v2验证direct模式飞书发送成功'':72B ''教训'':73B ''既有notify'':79B ''是空配置兼容层'':76B ''核查发现三个问题并已修复'':18B ''正确应get'':50B ''用户提出定时任务分两种'':7A,14B ''类型1链路断裂'':20B ''纯提醒发飞书'':15B ''返回空dict兼容层'':47B ''送达'':28B ''需llm处理再发飞书'':17B ''飞书服务无法初始化'':43B', '2026-09-01 18:35:53.251013', '2026-09-01 18:35:53.251013', '{}');
