INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('e33a5536-7c4d-42a2-84f6-97eaa091bfa0', 'v2 调度健康检查修复（2026-09-01，commit 3195a715）：v2_health_', 'v2 调度健康检查修复（2026-09-01，commit 3195a715）：v2_health_check 首跑告警 24 missed+1 zombie+3 failed 全部闭环，定性为 ADR-002 切换日过渡期现象（上午 v2 以 Agent OS 模式重启无本地调度+Agent OS 侧无任务注册），非实时故障。修复三处：①find_missed_tasks 排除 public.apscheduler_jobs 中 next_run_time 在未来的已排期任务（job id=task_{id} 映射）；②find_high_failure_tasks 排除 error 含孤儿/进程重启 的 run（or_ 处理 NULL error）；③add_task/complete_run 对 cron 保留字 managed_by_agent_* 跳过 parse_cron（webhook 新任务名写库曾因 parse_cron 抛异常被吞、complete_run 残留致 run 卡 running）。验证：webhook 端到端触发 v2_health_check → status ok，summary {zombie:0, missed:0, high_failure:0}。经验：健康检查口径必须区分"调度环境事故"（进程重启/切换日过渡）与"任务逻辑失败"，否则误报淹没真信号。', 'knowledge', '{v2调度,v2_health_check,APScheduler,ADR-002,调度监控,scheduler_repository}', NULL, '''+1'':23B ''+3'':25B ''-002'':30B ''-01'':5A,14B ''-09'':4A,13B ''0'':105B,107B,110B ''2026'':3A,12B ''24'':21B ''3195a715'':7A,16B ''add'':73B ''adr'':29B ''agent'':35B,38B,80B ''by'':79B ''check'':19B,100B ''commit'':6A,15B ''complete'':89B ''cron'':76B,83B,87B ''error'':64B,72B ''failed'':26B ''failure'':61B,109B ''find'':43B,59B ''health'':9A,18B,99B ''high'':60B,108B ''id'':55B,57B ''job'':54B ''jobs'':48B ''managed'':78B ''missed'':22B,44B,106B ''next'':50B ''null'':71B ''ok'':102B ''or'':69B ''os'':36B,39B ''parse'':82B,86B ''public.apscheduler'':47B ''run'':51B,68B,90B,92B ''running'':94B ''status'':101B ''summary'':103B ''task'':56B ''task/complete_run'':74B ''tasks'':45B,62B ''time'':52B ''v2'':1A,8A,10B,17B,33B,98B ''webhook'':84B,96B ''zombie'':24B,104B ''上午'':32B ''与'':116B ''中'':49B ''以'':34B ''任务逻辑失败'':117B ''侧无任务注册'':40B ''保留字'':77B ''修复三处'':42B ''健康检查口径必须区分'':112B ''全部闭环'':27B ''切换日过渡'':115B ''切换日过渡期现象'':31B ''卡'':93B ''否则误报淹没真信号'':118B ''含孤儿'':65B ''在未来的已排期任务'':53B ''处理'':70B ''定性为'':28B ''对'':75B ''抛异常被吞'':88B ''排除'':46B,63B ''新任务名写库曾因