INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('97f7cd1e-35a7-4354-898f-ce8486fb215b', '调度看门狗（scheduler_watchdog，2026-09-02，commit da33643', '调度看门狗（scheduler_watchdog，2026-09-02，commit da336438，RFC 011 第3层）：独立于 v2/Agent OS 的双调度系统监控，launchd com.pi-investment.scheduler-watchdog 每15min运行。核心能力：进程探活+期望vs实际漏执行比对+zombie检测+飞书直发告警+去重（quant.scheduler_watchdog_log）。关键工程教训：①v2 cron 按 UTC 解读、Agent OS cron 按北京时区解读（两系统时区相反，croniter 推算期望时刻必须用各自时区否则错位8h）；②psycopg2 中 LIKE ''task_%'' 的 % 要转义 %%；③任务级补跑策略字段：v2 用现成 compensation_enabled（26 auto_rerun 幂等+8 alert_only 交易信号类），Agent OS 用 metadata.watchdog（2 auto_rerun+15 skip占位），本期只告警不自动补跑（WATCHDOG_AUTO_RERUN=false）。④metadata 脏数据：Agent OS tasks.metadata 是 [null] 数组而非对象，Go 侧 Metadata 是 map，需规范为对象。监控者独立性是核心设计原则——监控不能依赖被监控对象。', 'knowledge', '{调度监控,scheduler_watchdog,RFC011,v2,AgentOS,cron时区,看门狗}', NULL, '''+15'':76B ''+8'':65B ''-02'':6A,14B ''-09'':5A,13B ''011'':18B ''2'':73B ''2026'':4A,12B ''26'':61B ''agent'':43B,69B,85B ''alert'':66B ''auto'':62B,74B,80B ''com.pi-investment.scheduler'':25B ''commit'':7A,15B ''compensation'':59B ''cron'':39B,45B ''croniter'':48B ''da33643'':8A ''da336438'':16B ''enabled'':60B ''false'':82B ''go'':91B ''launchd'':24B ''like'':52B ''log'':36B ''map'':95B ''metadata'':83B,93B ''metadata.watchdog'':72B ''null'':89B ''only'':67B ''os'':22B,44B,70B,86B ''psycopg2'':50B ''quant.scheduler'':34B ''rerun'':63B,75B,81B ''rfc'':17B ''scheduler'':2A,10B ''skip占位'':77B ''task'':53B ''tasks.metadata'':87B ''utc'':41B ''v2'':38B,57B ''v2/agent'':21B ''watchdog'':3A,11B,26B,35B,79B ''zombie检测'':31B ''两系统时区相反'':47B ''中'':51B ''交易信号类'':68B ''任务级补跑策略字段'':56B ''侧'':92B ''关键工程教训'':37B ''去重'':33B ''幂等'':64B ''按'':40B ''按北京时区解读'':46B ''推算期望时刻必须用各自时区否则错位8h'':49B ''数组而非对象'':90B ''是'':88B,94B ''期望vs实际漏执行比对'':30B ''本期只告警不自动补跑'':78B ''核心能力'':28B ''每15min运行'':27B ''独立于'':20B ''用'':71B ''用现成'':58B ''的'':54B ''的双调度系统监控'':23B ''监控不能依赖被监控对象'':98B ''监控者独立性是核心设计原则'':97B ''第3层'':19B ''脏数据'':84B ''要转义'':55B ''解读'':42B ''调度看门狗'':1A,9B ''进程探活'':29B ''需规范为对象'':96B ''飞书直发告警'':32B', '2026-09-02 01:03:27.312214', '2026-09-02 01:03:27.312214', '{}');
