INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('232d7d39-8dce-4ca5-8a06-d6030716437f', 'reminder v2:daily_review delivered', '{"task":"v2:daily_review","task_id":"wake-daily_review","prompt":"【v2 事件·daily_review】由 quantsys-v2 后端唤醒推送（不是定时任务，是事件驱动）。\n事件数据（JSON）：\nv2_event_json: {\"trade_date\":\"2026-09-02\",\"market_style\":null,\"performance\":{\"today_pnl\":0,\"total_value\":105642.52,\"open_positions\":2,\"cumulative_return\":0.0564},\"daily_snapshot\":{\"nav\":1.0564,\"date\":\"2026-09-02\",\"drawdown\":0,\"total_value\":105642.52,\"daily_return\":0.000824},\"today_trades\":[],\"today_pnl\":0,\"signals_executed\":0,\"orders_created\":0,\"instructions\":\"请使用工具链完成盘后复盘：\\n1. portfolio_status → 查看持仓和盈亏\\n2. performance_analyzer → 分析绩效\\n3. rotation_verify → 检查轮动效果\\n4. decision_history → 回顾今日决策\\n5. experience_write → 写入经验\\n6. feishu_notify → 发送复盘报告\"}\n\n处理要求：理解事件内容并采取相应动作（如 watch 触发的 AI 分析版=分析该股信号并组织飞书通知；daily_report=做当日复盘；agent_reminder=执行对应提醒任务）。遵守交易宪法；完成后把结论写入 memory（namespace=decision）。","fired_at":"2026-09-02T22:57:17.046369","delivered":true,"delivered_at":"2026-09-02T14:57:48.120Z","executor":{"mode":"direct","session_id":"investor-session-af023b5a-3d1c-4f0e-9961-642066d1748d"}}', 'data', '{office:delivered,office:reminder:exec,office:reminder:investor-session-af023b5a-3d1c-4f0e-9961-642066d1748d}', NULL, '''-02'':37B,61B,131B,141B ''-09'':36B,60B,130B,140B ''-642066'':158B ''0'':44B,63B,74B,77B,80B ''0.000824'':69B ''0.0564'':53B ''1.0564'':57B ''105642.52'':47B,66B ''17.046369'':134B ''2'':50B ''2026'':35B,59B,129B,139B ''3d1c'':155B ''48.120'':144B ''4f0e'':156B ''57'':133B,143B ''9961'':157B ''af023b5a'':154B ''agent'':119B ''ai'':113B ''analyzer'':89B ''at'':128B,138B ''created'':79B ''cumulative'':51B ''d1748d'':159B ''daily'':3A,8B,14B,19B,54B,67B,116B ''date'':34B,58B ''decision'':96B,126B ''delivered'':5A,135B,137B ''direct'':148B ''drawdown'':62B ''event'':31B ''