INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('0cb5615a-9934-4b99-ac9d-f22b576a3cbb', '歌尔 002241 决策更新（2026-09-03 凌晨，w-5b8aac2a）：开盘减半执行。依据', '歌尔 002241 决策更新（2026-09-03 凌晨，w-5b8aac2a）：开盘减半执行。依据：①主力净流入 9/1 的4.99亿骤降至 9/2 的5585万（-89%），推动力量消失；②缩量27%（61.7→45.3亿）；③9/2冲高24.45破24.4止盈线未站稳回落24.14，动能衰竭；④市场降温 FGI 100→60、涨跌比0.38、regime euphoria→sideways。方案：虚拟仓600股@22.52开盘卖300股（+7.2%锁利），剩300股止损上移23.6（90%筹码带上沿23.69下方）博25.8；真实仓500股@22.648建议同步减半250股，止损22.9博25.5。不清仓理由：主力方向仍净流入、筹码峰值23.2支撑、48波段全胜中期逻辑未破。', 'knowledge', '{002241,歌尔,分批止盈,动能衰减,主力流入骤降}', NULL, '''+7.2'':54B ''-03'':6A,18B ''-09'':5A,17B ''-89'':31B ''002241'':2A,14B ''100'':44B ''2026'':4A,16B ''22.52'':52B ''22.648'':62B ''45.3'':35B ''48波段全胜中期逻辑未破'':70B ''5b8aac2a'':10A,22B ''60'':45B ''61.7'':34B ''9/1'':26B ''9/2'':29B,37B ''90'':57B ''euphoria'':48B ''fgi'':43B ''regime'':47B ''sideways'':49B ''w'':9A,21B ''w-5b8aac2a'':8A,20B ''下方'':59B ''不清仓理由'':66B ''主力净流入'':25B ''主力方向仍净流入'':67B ''亿'':36B ''亿骤降至'':28B ''依据'':12A,24B ''冲高24.45'':38B ''决策更新'':3A,15B ''凌晨'':7A,19B ''剩300股止损上移23.6'':56B ''动能衰竭'':41B ''博25.5'':65B ''博25.8'':60B ''市场降温'':42B ''建议同步减半250股'':63B ''开盘减半执行'':11A,23B ''开盘卖300股'':53B ''推动力量消失'':32B ''支撑'':69B ''方案'':50B ''歌尔'':1A,13B ''止损22.9'':64B ''止盈线未站稳回落24.14'':40B ''涨跌比0.38'':46B ''的4.99'':27B ''的5585万'':30B ''真实仓500股'':61B ''破24.4'':39B ''筹码峰值23.2'':68B ''筹码带上沿23.69'':58B ''缩量27'':33B ''虚拟仓600股'':51B ''锁利'':55B', '2026-09-03 01:45:11.198336', '2026-09-03 01:45:11.198336', '{}');
