INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('3cfb1bdf-afa3-4e4d-b8ed-d5182f9e6480', '2026-09-03 v2 signals_ready 事件处理（investor-session-', '2026-09-03 v2 signals_ready 事件处理（investor-session-b1701be7）：quantsys-v2 signal_execution_daily_fallback 于 07:30 推送 52 条 SELL 信号（strategy 193=VBottom-v2，signal_date 2026-09-03），全部 pending、indicators 空、confidence null、reason 均为模板"策略卖出信号"。处理结论：不执行任何卖出。依据：①我的持仓仅 601288（+3.2%）、002241（+7.2%），portfolio_analyze 双 hold，无止损/止盈触发；②可见 20 条 SELL（中国石油/招商银行/万华化学/宁德时代等）均与持仓无重叠；③策略 193 状态 error、validationStatus=invalid（失效策略仍在出信号，52 只同日全 SELL 属异常批量模式）；④同日日志暴露 v2 后端 bug：signal_repository._signal_to_dict 访问不存在的 signal.volume 属性 → get_latest_signals AttributeError。教训：signals_ready 批量信号须先核对"信号源策略健康度+与持仓重叠度"，不可盲从失效策略的批量 SELL。', 'knowledge', '{signals_ready,v2,SELL信号,2026-09-03,VBottom-v2,strategy193,skip_trade,601288,002241}', NULL, '''+3.2'':61B ''+7.2'':63B ''-03'':3A,13B,46B ''-09'':2A,12B,45B ''002241'':62B ''07'':30B ''193'':38B,80B ''20'':71B ''2026'':1A,11B,44B ''30'':31B ''52'':33B,86B ''601288'':60B ''analyze'':65B ''attributeerror'':102B ''b1701be7'':21B ''bug'':93B ''confidence'':51B ''daily'':27B ''date'':43B ''error'':82B ''execution'':26B ''fallback'':28B ''get'':99B ''hold'':67B ''indicators'':49B ''invalid'':84B ''investor'':9A,19B ''investor-session'':8A ''investor-session-b1701be7'':18B ''latest'':100B ''null'':52B ''pending'':48B ''portfolio'':64B ''quantsys'':23B ''quantsys-v2'':22B ''ready'':6A,16B,105B ''reason'':53B ''repository._signal_to_dict'':95B ''sell'':35B,73B,88B,110B ''session'':10A,20B ''signal'':25B,42B,94B ''signal.volume'':97B ''signals'':5A,15B,101B,104B ''strategy'':37B ''v2'':4A,14B,24B,41B,91B ''validationstatus'':83B ''vbottom'':40B ''vbottom-v2'':39B ''万华化学'':76B ''不可盲从失效策略的批量'':109B ''不执行任何卖出'':57B ''与持仓重叠度'':108B ''中国石油'':74B ''事件处理'':7A,17B ''于'':29B ''依据'':58B ''信号'':36B ''信号源策略健康度'':107B ''全部'':47B ''双'':66B ''只同日全'':87