INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('bc50adfd-0815-4140-bb26-395ca731f9f3', '002241 neutral 歌尔减半止盈执行：盘前挂单未撮合（orchestrator repo=None bug）→ 盘中改立即委托时误把限价保护价当 pr', '002241 交易经验（2026-09-03T02:28:41.838Z）
