INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('e9b45132-d5c6-4fa2-ad13-9bf141426502', '2026-09-03 首批信号5日窗口验证（signal_track, 8/4-9/3共18信号）：', '2026-09-03 首批信号5日窗口验证（signal_track, 8/4-9/3共18信号）：A级6个 5日胜率33.3%/avgReturn+1.94%；B级7个 avgReturn5D -0.07%（胜率口径0，多数为9/3当日新建无窗口）；C级5个无5日数据。⚠️关键发现：18个信号中9个(50%)为test_*测试来源（testSuite/testClient/testDuplicate/testIntegration/testAttribution），严重污染统计口径；真实opportunity_scan漏斗信号5个（000807/000933/002379/000612等）全部为9/3首跑当日新建，5日窗口需9/10后回填。结论：A级33.3%胜率样本过小且含测试样本，不足以判定信号质量；建议后续report增加source过滤或标记test_*为噪声，真实信号质量评估推迟至9/10后首轮完整窗口。', 'knowledge', '{signal_track,信号胜率,5日窗口,测试污染,2026-09-03,验证}', NULL, '''+1.94'':20B ''-0.07'':23B ''-03'':3A,11B ''-09'':2A,10B ''/avgreturn'':19B ''000807/000933/002379/000612'':37B ''18个信号中9个'':29B ''2026'':1A,9B ''50'':30B ''5日窗口需9/10'':41B ''5日胜率33.3'':18B ''8/4-9/3'':7A,15B ''avgreturn5d'':22B ''a级33.3'':44B ''a级6个'':17B ''b级7个'':21B ''c级5个无5日数据'':27B ''scan漏斗信号5个'':36B ''signal'':5A,13B ''testsuite/testclient/testduplicate/testintegration/testattribution'':33B ''track'':6A,14B ''不足以判定信号质量'':46B ''严重污染统计口径'':34B ''为test'':31B ''为噪声'':48B ''全部为9/3'':39B ''共18信号'':8A,16B ''关键发现'':28B ''后回填'':42B ''后首轮完整窗口'':50B ''多数为9/3'':25B ''建议后续report增加source过滤或标记test'':47B ''当日新建无窗口'':26B ''测试来源'':32B ''真实opportunity'':35B ''真实信号质量评估推迟至9/10'':49B ''等'':38B ''结论'':43B ''胜率口径0'':24B ''胜率样本过小且含测试样本'':45B ''首批信号5日窗口验证'':4A,12B ''首跑当日新建'':40B', '2026-09-03 16:05:48.234651', '2026-09-03 16:05:48.234651', '{}');
