INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('64443297-eadc-453b-a8b5-d20bcc534c5d', 'reminder v2:daily_review delivered', '{"task":"v2:daily_review","task_id":"wake-daily_review","prompt":"【v2 事件·daily_review】由 quantsys-v2 后端唤醒推送（不是定时任务，是事件驱动）。\n事件数据（JSON）：\nv2_event_json: {\"trade_date\":\"2026-09-03\",\"market_style\":null,\"performance\":{},\"daily_snapshot\":{},\"today_trades\":[],\"today_pnl\":0,\"signals_executed\":0,\"orders_created\":0,\"instructions\":\"请使用工具链完成盘后复盘：\\n1. portfolio_status → 查看持仓和盈亏\\n2. performance_analyzer → 分析绩效\\n3. rotation_verify → 检查轮动效果\\n4. decision_history → 回顾今日决策\\n5. experience_write → 写入经验\\n6. feishu_notify → 发送复盘报告\"}\n\n处理要求：理解事件内容并采取相应动作（如 watch 触发的 AI 分析版=分析该股信号并组织飞书通知；daily_report=做当日复盘；agent_reminder=执行对应提醒任务）。遵守交易宪法；完成后把结论写入 memory（namespace=decision）。","fired_at":"2026-09-03T16:30:57.671140","delivered":true,"delivered_at":"2026-09-03T08:30:57.696Z","executor":{"mode":"direct","session_id":"investor-session-d4c40f98-32bb-4e0a-97a9-9ce1ed98719d"}}', 'data', '{office:delivered,office:reminder:exec,office:reminder:investor-session-d4c40f98-32bb-4e0a-97a9-9ce1ed98719d}', NULL, '''-03'':37B,105B,115B ''-09'':36B,104B,114B ''0'':48B,51B,54B ''2026'':35B,103B,113B ''30'':107B,117B ''32bb'':129B ''4e0a'':130B ''57.671140'':108B ''57.696'':118B ''97a9'':131B ''9ce1ed98719d'':132B ''agent'':93B ''ai'':87B ''analyzer'':63B ''at'':102B,112B ''created'':53B ''d4c40f98'':128B ''daily'':3A,8B,14B,19B,42B,90B ''date'':34B ''decision'':70B,100B ''delivered'':5A,109B,111B ''direct'':122B ''event'':31B ''executed'':50B ''executor'':120B ''experience'':74B ''feishu'':78B ''fired'':101B ''history'':71B ''id'':11B,124B ''instructions'':55B ''investor'':126B ''investor-session-d4c40f98-32bb-4e0a-97a9-9ce1ed98719d'':125B ''json'':29B,32B ''market'':38B ''memory'':98B ''mode'':121B ''n'':81B ''n1'':57B ''n2'':61B ''n3'':65B ''n4'':69B ''n5'':73B ''n6'':77B 