INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('2aa53fe2-b69a-4c8b-8d65-0c4e31d5c7c0', 'reminder evolution-distill-daily delivered', '{"task":"evolution-distill-daily","task_id":"0b61dbe3-704f-4377-ae86-36b848c0f5a4","prompt":"【每日蒸馏 16:00】执行 daily_distill 工具（days=7, auto_apply=false，预览模式生成改进提案，不直接应用）。若提案数>0：将关键提案写入 memory（namespace=decision，importance=0.6）备查；汇总报告：模式数、建议数、最值得关注的模式（如某类操作成功率过低）。注意：auto_apply 保持 false，进化走 candidate→验证门流程，不要直接改正式基因组。\n\n【汇报要求】完成后必须飞书简报（channel=reports, urgency=normal）：任务名+关键结果摘要（1-3行）；发现异常则 urgency=high 发 alerts 群。（简报内容：模式数、建议数、最值得关注的模式）","window":"w-a8a89c6a","fired_at":"2026-09-03T15:00:12.184Z","delivered":true,"delivered_at":"2026-09-03T15:00:12.196Z","executor":{"mode":"direct","session_id":"investor-session-7fd14606-3c2d-4ec2-ada9-ba04e51de3ec"}}', 'data', '{office:delivered,office:reminder:exec,office:reminder:investor-session-7fd14606-3c2d-4ec2-ada9-ba04e51de3ec}', NULL, '''-03'':90B,101B ''-09'':89B,100B ''-3'':70B ''0'':37B ''0.6'':43B ''00'':24B,92B,103B ''0b61dbe3'':15B ''0b61dbe3-704f'':14B ''1'':69B ''12.184'':93B ''12.196'':104B ''16'':23B ''2026'':88B,99B ''36b848c0f5a4'':20B ''3c2d'':115B ''4377'':17B ''4ec2'':116B ''7'':30B ''704f'':16B ''7fd14606'':114B ''a8a89c6a'':85B ''ada9'':117B ''ae86'':19B ''ae86-36b848c0f5a4'':18B ''alerts'':76B ''apply'':32B,52B ''at'':87B,98B ''auto'':31B,51B ''ba04e51de3ec'':118B ''candidate'':56B ''channel'':63B ''daily'':5A,11B,26B ''days'':29B ''decision'':41B ''delivered'':6A,95B,97B ''direct'':108B ''distill'':4A,10B,27B ''evolution'':3A,9B ''evolution-distill-daily'':2A,8B ''executor'':106B ''false'':33B,54B ''fired'':86B ''high'':74B ''id'':13B,110B ''importance'':42B ''investor'':112B ''investor-session-7fd14606-3c2d-4ec2-ada9-ba04e51de3ec'':111B ''memory'':39B ''mode'':107B ''n'':59B,60B ''namespace'':40B ''normal'':66B ''prompt'':21B ''reminder'':1A ''reports'':64B ''session'':109B,113B ''t15'':91B