INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('9166fe48-fd85-4c55-b3bf-cae3b58ea495', '【工程教训·字段口径】portfolio_analyze 假止盈根因：后端 profit_total', '【工程教训·字段口径】portfolio_analyze 假止盈根因：后端 profit_total_rate 是小数比率(0.0073)，client ×100 成百分数 profitLossPct=0.73，工具再叠加 |pnl|≤1.5 的 ×100 启发式→73 触发假 take_profit。教训：上游已做过单位换算的字段不得再二次换算；小百分比(0~1.5%)的 pnl 是常态(刚建仓/蓝筹)，×100 启发式会把 0.73% 误判为 73%。已在 PortfolioAnalyzeTool 移除启发式，直接消费 client 已换算的 profitLossPct。相关工具：portfolio_analyze/position_list。', 'experience', '{portfolio_analyze,pnl,口径,假止盈,w-9f07cb6a}', NULL, '''0'':38B ''0.0073'':19B ''0.73'':24B,47B ''1.5'':27B ''100'':21B,29B,45B ''73'':31B,49B ''analyze'':4A,12B ''analyze/position_list'':59B ''client'':20B,54B ''pnl'':26B,41B ''portfolio'':3A,11B,58B ''portfolioanalyzetool'':51B ''profit'':7A,15B,34B ''profitlosspct'':23B,56B ''rate'':17B ''take'':33B ''total'':8A,16B ''~1.5'':39B ''上游已做过单位换算的字段不得再二次换算'':36B ''假止盈根因'':5A,13B ''刚建仓'':43B ''后端'':6A,14B ''启发式'':30B ''启发式会把'':46B ''字段口径'':2A,10B ''小百分比'':37B ''工具再叠加'':25B ''工程教训'':1A,9B ''已在'':50B ''已换算的'':55B ''成百分数'':22B ''教训'':35B ''是小数比率'':18B ''是常态'':42B ''的'':28B,40B ''直接消费'':53B ''相关工具'':57B ''移除启发式'':52B ''蓝筹'':44B ''触发假'':32B ''误判为'':48B', '2026-09-03 20:34:58.86222', '2026-09-03 20:34:58.86222', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('18c86073-951f-4c36-ac04-4e9826ae0f96', '【工程教训·契约对齐】m4 熔断与 risk_metrics 曾恒 0/不触发：工具只读 snake', '【工程教训·契约对齐】m4 熔断与 risk_metrics 曾恒 0/不触发：工具只读 snake_case max_drawdown，后端实测返回 camelCase maxDrawdown(-0.0772 小数比率)；且内部阈值是百分数 -8，即使读到 -0.12(-12%) 也因 -0.12<-8 为假永不触发。双坑：字段名假设(snake/camel) + 单位口径(小数/百分数)。修复：读 camelCase + |v|≤1 时 ×100 转百分数，口径统一到 -7.72% vs 阈值 -8%。同类问题还有 risk_metrics 读 annualizedVolatility(后端 annualVolatility)、var_95 未 ×100。教训：字段名与单位必须以真实调用(curl/在线)为准，禁止凭印象写映射；%契约字段统一 |v|≤1→×100 规范换算。', 'experience', '{M4CircuitBreakerTool,risk_metrics,camelCase,小数百分数,回撤,w-9f07cb6a}', NULL, '''-0.0772'':29B ''-0.12'':34B,37B ''-12'':35B ''-7.72'':55B ''-8'':32B,38B,58B ''0'':8A,19B ''1'':50B,78B ''100'':52B,69B,79B ''95'':67B ''annualizedvolatility'':63B ''annualvolatility'':65B ''camelcase'':27B,48B ''case'':23B ''curl'':72B ''drawdown'':25B ''m4'':3A,14B ''max'':24B ''maxdrawdown'':28B ''metrics'':6A,17B,61B ''risk'':5A,16B,60B ''snake'':11A,22B ''snake/camel'':42B ''v'':49B,77B ''var'':66B ''vs'':56B ''不触发'':9A,20B ''且内部阈值是百分数'':31B ''为假永不触发'':39B ''为准'':74B ''也因'':36B ''修复'':46B ''单位口径'':43B ''即使读到'':33B ''双坑'':40B ''口径统一到'':54B ''同类问题还有'':59B ''后端'':64B ''后端实测返回'':26B ''在线'':73B ''契约字段统一'':76B ''契约对齐'':2A,13B ''字段名与单位必须以真实调用'':71B ''字段名假设'':41B ''小数'':44B ''小数比率'':30B ''工具只读'':10A,21B ''工程教训'':1A,12B ''教训'':70B ''时'':51B ''曾恒'':7A,18B ''未'':68B ''熔断与'':4A,15B ''百分数'':45B ''禁止凭印象写映射'':75B ''规范换算'':80B ''读'':47B,62B ''转百分数'':53B ''阈值'':57B', '2026-09-03 20:34:58.864894', '2026-09-03 20:34:58.864894', '{}');
