INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('d9670adb-3bb1-476e-aacf-a85e23e3225d', '【数据质量检查任务免 agent 改造完成（2026-09-05, w-4918ed49）】Q1 定', '【数据质量检查任务免 agent 改造完成（2026-09-05, w-4918ed49）】Q1 定案：免 agent（选项1），pilot 任务 data-quality-monitor-daily（id 1f92afc5-49ce-45e2-96fa-1b28454b18c0）。做法：Agent OS scheduler command 路径直跑 wrapper（/Users/yunpeng/pi-investment/agent-dh/scripts/data-quality-monitor-daily.sh，export PATH 补 node + cd agent-dh + exec tsx），告警改为 POST /api/v1/notifications/send 直发飞书 alerts/reports 渠道。关键事实：①原任务 webhook_url→:13080 需 agent 消化，投递不可观测且 script 在 agent-dh env 根本无法运行（@pi-investment 客户端包缺失）；②原脚本''写 memory(kind=alert/category=notification)=自动飞书''设计从未闭环——agent-os memory POST 只落库不触发通知、category 白名单仅 knowledge/experience/decision/data（传 notification 会 400）；正确告警路径是 notifications/send；③PUT /scheduler/tasks/{id} 不支持改 command（匿名 struct 无 Command 字段），需直改 DB tasks 表+重启 agent-os；④command 直跑时 launchd PATH 无 node，wrapper 内必须显式补 PATH。端到端验证：手动 trigger×3，launchd 日志 Task execution succeeded、run.output 捕获脚本 stdout（0 问题 exit 0、duration 16.4s），cron 已排周一 16:05。推广候选评估：仅确定性纯检查+自主告警任务适合同模式；event-calendar-check 可脚本化但其余 routine/进化任务含 LLM 决策仍需 agent。', 'knowledge', '{data-quality,scheduler,免agent改造,agent-os,q1,w-4918ed49}', NULL, '''-05'':6A,17B ''-09'':5A,16B ''/api/v1/notifications/send'':60B ''/scheduler/tasks'':108B ''/users/yunpeng/pi-investment/agent-dh/scripts/data-quality-monitor-daily.sh'':47B ''0'':146B,149B ''05'':156B ''13080'':68B ''16'':155B ''16.4'':151B ''1b28454b18c0'':39B ''1f92afc5'':35B ''1f92afc5-49ce-45e2-96fa-1b28454b18c0'':34B ''2026'':4A,15B ''3'':137B ''400'':104B ''45e2'':37B ''4918ed49'':9A,20B ''49ce'':36B ''96fa'':38B ''agent'':2A,13B,24B,41B,54B,70B,76B,93B,123B,169B ''agent-dh'':53B,75B ''agent-os'':92B,122B ''alert/category'':88B ''alerts/reports'':62B ''calendar'':162B ''category'':98B ''cd'':52B ''check'':163B ''command'':44B,111B,115B,125B ''cron'':153B ''daily'':3