INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('e7c9eb3e-1d12-4097-9323-e13954c9b962', '【event-calendar-check 免 agent 改造完成（2026-09-05, w-4', '【event-calendar-check 免 agent 改造完成（2026-09-05, w-4918ed49）】data-quality pilot 后推广第二例。任务 e8fdcbf3-c234-4795-83bc-0597b399d354（每日 16:45）由 dsh-webhook→agent 改为 command 直跑：/Users/yunpeng/pi-investment/agent-dh/scripts/event-calendar-check.sh→tsx→event-calendar-check.ts。逻辑：GET /api/events/upcoming?days=2（v2, quant.event_calendar 表, 67条预置全 pending）→ 仅 status=pending 且 importance>=2 推送（>=3→alerts/high、==2→reports/normal，POST /notifications/send）→ 推送成功后 PATCH {status:notified, meta:{notified_at}}。幂等关键：list_upcoming 返回 pending+notified（repo status 元组含 notified），必须只推 pending 防重复——脚本跳过已通知。E2E：插入测试事件实发 reports→notification_logs status=sent→PATCH 生效→第二轮 skipped(已通知) 幂等通过→清理；重启 agent-os 后 trigger HTTP200 run.output 捕获脚本 stdout（无事件路径）。经验：任务原 agent prompt 的''写 memory 总结''环节在 command 化后取消——免 agent 后无窗口消化，通知日志即留痕。', 'knowledge', '{event-calendar,免agent改造,scheduler,q1,w-4918ed49}', NULL, '''-05'':10A,22B ''-09'':9A,21B ''-4'':12A ''-83'':36B ''/api/events/upcoming'':56B ''/notifications/send'':77B ''/users/yunpeng/pi-investment/agent-dh/scripts/event-calendar-check.sh'':51B ''0597b399d354'':39B ''16'':41B ''2'':58B,70B,74B ''2026'':8A,20B ''3'':72B ''45'':42B ''4795'':35B ''4918ed49'':25B ''67条预置全'':63B ''agent'':6A,18B,47B,115B,126B,136B ''agent-os'':114B ''alerts/high'':73B ''at'':84B ''bc'':38B ''bc-0597b399d354'':37B ''c234'':34B ''calendar'':3A,15B,61B ''check'':4A,16B ''command'':49B,133B ''data'':27B ''data-quality'':26B ''days'':57B ''dsh'':45B ''dsh-webhook'':44B ''e2e'':99B ''e8fdcbf3'':33B ''e8fdcbf3-c234'':32B ''event'':2A,14B ''event-calendar-check'':1A,13B ''event-calendar-check.ts'':53B ''get'':55B ''http200'':119B ''importance'':69B ''list'':86B ''logs'':103B ''memory'':130B ''meta'':82B ''notification'':102B ''notified'':81B,83B,90B,94B ''os'':1