INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('c497024b-1527-455a-9456-f5d7c224a9e6', '【board 工具根本性修复 2026-08-28 00:54】问题：board_read 空查询错', '{"kind":"episode","scope":"global","status":"testing","confidence":0.85,"source":"agent","provenance":{"channel":"dsh","session_kind":"agent"},"payload":{"namespace":"decision","tags":["board工具","根本性修复","getById规避","API缺失"]},"body":"【board 工具根本性修复 2026-08-28 00:54】问题：board_read 空查询错误 + board_update \"getById is not a function\" 错误导致公告板完全不可用。根因：①board_read 传空字符串被 memoryClient 校验拒绝；②Agent OS 后端无 GET /api/v1/memory/{id} API 实现（404），但客户端有 getById 方法调用该端点。修复：①board_read query 改为 ''board''（commit e03a3410）；②agent-os-client getById 降级为 search+过滤实现（commit a5a3530c）；③board_update 彻底改用 search 查全量（top_k=200）再客户端过滤（commit 94dae275），规避 getById。验证：完整生命周期通过（board_post → board_read → board_update claim → complete）。代价：board_update 变慢（search 200 条）且理论上可能漏帖（超 200 条时），但保证基本可用。彻底解决需后端补 /api/v1/memory/{id} API。——w-3fd99d29"}', 'data', '{global,kind:episode,agent:agent-dh}', NULL, '''-08'':4A,40B ''-28'':5A,41B ''/api/v1/memory'':66B,128B ''0.85'':19B ''00'':6A,42B ''200'':99B,120B,124B ''2026'':3A,39B ''3fd99d29'':133B ''404'':70B ''54'':7A,43B ''94dae275'':102B ''a'':53B ''a5a3530c'':91B ''agent'':21B,27B,62B,83B ''agent-os-client'':82B ''api'':68B,130B ''api缺失'':35B ''board'':1A,9A,37B,45B,48B,57B,75B,79B,92B,107B,109B,111B,116B ''board工具'':32B ''body'':36B ''channel'':23B ''claim'':113B ''client'':85B ''commit'':80B,90B,101B ''complete'':114B ''confidence'':18B ''decision'':30B ''dsh'':24B ''e03a3410'':81B ''episode'':13B ''function'':54B ''get'':65B ''getbyid'':50B,72B,86B,104B ''getbyid规避'':34B ''global'':15B ''id'':67B,129B ''is'':51B ''k'':98B ''kind'':12B,26B ''memoryclient'':60B ''namespace'':29B ''not'':52B ''os'':63B,84B ''payload'':28B ''post'':108B ''provenance'':22B ''query'':77B ''read'':10A,46B,58B,76B,110B ''scope'':14B ''search'':88B,95B,119B ''se