INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('0f980577-4d42-42e5-8430-83f9656c74a4', '本轮任务总结（2026-08-22 晚）：①M4 仓位映射表——由并行窗口实现 regime_pos', '{"kind": "episode", "scope": "global", "status": "testing", "confidence": 0.8, "source": "agent", "provenance": {"channel": "dsh", "session_kind": "agent"}, "payload": {"tags": ["M4", "R-008", "熔断演练", "g12", "2026-08-22"], "namespace": "decision"}, "body": "本轮任务总结（2026-08-22 晚）：①M4 仓位映射表——由并行窗口实现 regime_position_limit（regime→仓位上限：恐慌100/偏多80/震荡60/偏空40/狂热30%，数据降级收紧震荡档），我 E2E 验收通过且真实触发熔断：组合 60 日最大回撤 -10.39% < -8%，circuit_breaker triggered（当前仓位 28.2% 合规但需减半）。应对已执行：飞书高优告警（alerts 群）+ schedule-4 周一 09:35 减仓演练提醒（含 R-002/R-008 流程）+ RFC 004 M4 验收所需演练记录将在演练后落库。②M6 决策前强制检索——R-008 已入基因组（rules v5，g12）：portfolio_trade 前必须 memory_search 该标的+场景的历史教训并在 reason 注明检索结论。③mainline_scan 超时放宽 30s→90s、regime_daily→60s（板块接口冷启动 15s+ 实测超时两次）。④基因组当前 g12（constitution 锁 / principles v5 / rules v5 含 R-001~R-008 / lessons v4 candidate g10 观察中 08-25 到期）。⑤工具总数 109——并行窗口上线了办公室多窗口协作系统（board_post/hire_window/window_message/office_roster 等）。⑥遗留告警：trade_verify 后端路由 404 仍待基建线修复。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:158}', NULL, '''-001'':130B ''-002'':85B ''-008'':31B,95B ''-08'':3A,35B,42B ''-10.39'':65B ''-22'':4A,36B,43B ''-25'':138B ''-4'':78B ''-8'':66B ''/r-008'':86B ''0.8'':18B ''004'':89B ''08'':137B ''09'':80B ''109'':141B ''15s'':118B ''2026'':2A,34B,41B ''28.2'':71B ''30s'':112B ''35'':81B ''404'':150B ''60'':63B ''60s'':116B ''90s'':113B ''agent'':20B,26B ''alerts'':75B ''board'':143B ''body'':39B ''breaker'':68B ''candidate'':134B ''channel'':22B ''circuit'':67B ''confidence'':17B ''constitution'':122B ''daily'':115B ''decision'':38B ''dsh'':23B ''e2e'':60B ''episode'':12B ''g10'':135B ''g12'':33B,99B,121B ''global'':14B ''kind'':11B,25B ''lessons'':132B ''limit'':50B ''m4'':6A,29B,45B,90B ''m6'':92B ''mainline'':109B ''memory'':103B ''namespace