INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('779e7cb9-e8c3-42b5-a8ea-4466eb7b8561', '办公室交流层上线（2026-08-21/22，四工具 E2E 全过）：window_message（', '{"kind": "episode", "scope": "global", "status": "testing", "confidence": 0.85, "source": "agent", "provenance": {"channel": "dsh", "session_kind": "agent"}, "payload": {"tags": ["办公室交流层", "window_message", "公告板", "离线信箱", "2026-08-21"], "namespace": "decision"}, "body": "办公室交流层上线（2026-08-21/22，四工具 E2E 全过）：window_message（点对点：在线 followup 直投 delivered=true / 离线写 OS 信箱 queued_offline，窗口上线时 deliverOfflineInbox 自动补投——w-09ee1306 离线消息已入信箱待补投）、board_post/board_read（公告板，OS 记忆库 tag=office:board）、inbox_check（收信）。实测修正：OS 搜索是文本匹配 title/content + tag 仅过滤，公告板内容加 marker=''office-board-post'' 锚点词保证可检索。职责切分（用户裁决）：数据（信箱/公告板/档案）在 OS，动作（寻址/投递/收信）在 DH lifecycle。完整图景：点对点讨论→公告板沉淀（传闻区）→验证门→基因组本能（真理区）。检查点 agent-self/20260822-011252。注意：inbox_check 目前会连同自己发出的消息一起返回（轻微过宽，可当\"我的消息\"视图用，后续可收紧）。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:152}', NULL, '''-08'':3A,35B,42B ''-21'':4A,36B,43B ''/20260822-011252'':118B ''/22'':5A,44B ''0.85'':18B ''09ee1306'':66B ''2026'':2A,34B,41B ''agent'':20B,26B,116B ''agent-self'':115B ''board'':68B,75B,89B ''body'':39B ''channel'':22B ''check'':77B,121B ''confidence'':17B ''decision'':38B ''delivered'':54B ''deliverofflineinbox'':62B ''dh'':105B ''dsh'':23B ''e2e'':7A,46B ''episode'':12B ''followup'':52B ''global'':14B ''inbox'':76B,120B ''kind'':11B,25B ''lifecycle'':106B ''marker'':86B ''message'':10A,31B,49B ''namespace'':37B ''office'':74B,88B ''office-board-post'':87B ''offline'':60B ''os'':57B,71B,80B,99B ''payload'':27B ''post'':90B ''post/board_read'':69B ''provenance'':21B ''queued'':59B ''scope'':13B ''self'':117B ''session'':24B ''source'':19B ''status'':15B ''tag'':73B,83B ''tags'':28B ''testing'':16B ''title/content'':82B ''true'':55B ''w'':65B ''w-09ee1306'':64B ''window'':9A,30B,48B ''仅过滤'':84B ''传闻区'':11