INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('0423444f-5c42-449d-9fc8-47e6ba11089f', 'quantsys-v2 数据源网络勘察（2026-09-05, w-36aee70c）：82.pus', 'quantsys-v2 数据源网络勘察（2026-09-05, w-36aee70c）：82.push2.eastmoney.com 在本机网络（macOS 系统代理 127.0.0.1:7897 verge GeoIP(cn)→DIRECT 直连）不可达——IPv6(240e:e1...) TLS 握手被断、IPv4(47.112.165.11) 不通，akshare stock_zh_a_spot_em 每次重试 5-6s 后失败（ProxyError/RemoteDisconnected）。修复：get_market_overview 主源改用 ak.stock_market_activity_legu（legulegu.com 独立域，0.1s 可用，直接给全市场上涨/下跌/平盘/停牌），spot_em 保留兜底。其他可达直连域：datacenter-web.eastmoney.com、hq.sinajs.cn、qt.gtimg.cn、legulegu.com。教训：a) akshare 的 stock_zh_a_spot_em 依赖 82.push2 域，该域被 clash 规则强制直连且本网络直连不通——凡是走该域的接口都会慢失败 5-6s；b) 涨跌家数类数据优先用 legu 接口而非全市场 spot 拉取。提交 ca0672bd。同批提交 95946ee8（lookback 300→420，momentum_52w_high 需 250 交易日）。', 'knowledge', '{数据源,82.push2,legu,get_market_overview,网络勘察,2026-09-05}', NULL, '''-05'':7A,18B ''-09'':6A,17B ''-6'':50B,98B ''0.1'':65B ''127.0.0.1'':26B ''2026'':5A,16B ''240e'':35B ''250'':117B ''300'':111B ''36aee70c'':10A,21B ''420'':112B ''47.112.165.11'':40B ''5'':49B,97B ''52w'':114B ''7897'':27B ''82'':90B ''82.pus'':11A ''82.push2.eastmoney.com'':22B ''95946ee8'':109B ''a'':45B,81B,86B ''activity'':61B ''ak.stock'':59B ''akshare'':42B,82B ''b'':100B ''ca0672bd'':107B ''clash'':94B ''cn'':30B ''datacenter-web.eastmoney.com'':76B ''direct'':31B ''e1'':36B ''em'':47B,73B,88B ''geoip'':29B ''get'':55B ''high'':115B ''hq.sinajs.cn'':77B ''ipv4'':39B ''ipv6'':34B ''legu'':62B,102B ''legulegu.com'':63B,79B ''lookback'':110B ''macos'':24B ''market'':56B,60B ''momentum'':113B ''overview'':57B ''proxyerror/remotedisconnected'':53B ''push2'':91B ''qt.gtimg.cn'':78B ''quantsys'':2A,13B ''quantsys-v2'':1A,12B ''s'':51B,66B,99B ''spot'':46B,72B,87B,104B ''stock'':43B,84B ''tls'':37B ''v2'':3A,14B ''verge'':28B ''w'':9A,20B ''w-36aee70c'':8A,19B ''zh'':44B,85B ''下跌'':69B ''不可达'':33B ''不通'':41B ''主源改用'':58B ''交易日'':11