INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('22754ce8-259f-45d9-8bd4-a3d64b3be74c', '002007 neutral T+1 结转只覆盖 agent_virtual 导致 agent_brain 华兰可卖恒 0', '002007 交易经验（2026-09-04T19:49:38.077Z）
