INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('a1b14919-deb6-4e03-a2b8-fa9343df423a', '[需人工审查] benchmark 近30日收益与净值曲线严重矛盾 (2026-08-15)', '{"kind": "episode", "scope": "global", "status": "testing", "confidence": 0.8, "source": "agent", "provenance": {"channel": "daily_review", "session_id": "daily_review:2026-08-15", "session_kind": "cron"}, "payload": {"category": "data_quality"}, "body": "agent_virtual 账户 benchmark 块报告 近30日账户收益 +27.16% vs 沪深300 -3.64%（超额+30.80%，alpha 2.50，sharpe 3.33），但 /api/simulation/performance 净值曲线显示累计仅 +3.5%（峰值 08-12 +4.30%，最大回撤 0.95%），两者相差 7.6 倍，明显矛盾。同时 evolution_leaderboard 的 upCapture 2.19 因 72.5% 高现金仓位 + 9涨9跌小样本，噪声大，fitness 2.33 需谨慎解读，不建议据此对外宣称策略超额。需检查：① benchmark 的 account_return_1m 计算口径（疑似错用 invested_capital 或错配净值快照起点）；② capture ratio 对高现金仓位的处理。"}', 'data', '{global,kind:episode,migration:quantsys-v2,orig_id:73}', NULL, '''+27.16'':42B ''+3.5'':55B ''+30.80'':47B ''+4.30'':59B ''-08'':5A,26B ''-12'':58B ''-15'':6A,27B ''-3.64'':45B ''/api/simulation/performance'':53B ''0.8'':14B ''0.95'':61B ''08'':57B ''1m'':86B ''2.19'':71B ''2.33'':78B ''2.50'':49B ''2026'':4A,25B ''3.33'':51B ''7.6'':63B ''72.5'':73B ''9涨9跌小样本'':75B ''account'':84B ''agent'':16B,36B ''alpha'':48B ''benchmark'':2A,39B,82B ''body'':35B ''capital'':90B ''capture'':92B ''category'':32B ''channel'':18B ''confidence'':13B ''cron'':30B ''daily'':19B,23B ''data'':33B ''episode'':8B ''evolution'':67B ''fitness'':77B ''global'':10B ''id'':22B ''invested'':89B ''kind'':7B,29B ''leaderboard'':68B ''payload'':31B ''provenance'':17B ''quality'':34B ''ratio'':93B ''return'':85B ''review'':20B,24B ''scope'':9B ''session'':21B,28B ''sharpe'':50B ''source'':15B ''status'':11B ''testing'':12B ''upcapture'':70B ''virtual'':37B ''vs'':43B ''不建议据此对外宣称策略超额'':80B ''两者相差'':62B ''但'':52B ''倍'':64B ''净值曲线显示累计仅'':54B ''同时'':66B ''噪声大'':76B ''因'':72B ''块报告'':40B ''对高现金仓位的处理'':94B ''峰值'':56B ''或错配净值快照起点'':91B ''