INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('96676acf-a093-42ab-aed0-88499f3688f0', '盯盘与调度分类纪律（2026-09-06，w-d1e6cebf 用户反馈）：价格条件触发类监控（如"', '盯盘与调度分类纪律（2026-09-06，w-d1e6cebf 用户反馈）：价格条件触发类监控（如"歌尔≥24.4 止盈"、"XX 止跌企稳观察"）应使用 watch_manage 创建盯盘规则（price_break/change_pct 等条件），不应做成 scheduler 定时任务。定时任务用于时间驱动的例行流程（盘前例程/盘后复盘/周报等），盯盘规则用于价格/量能条件触发的实时响应。已删除 geer-take-profit-0901（每日 9:35 检查价格）作为反例。', 'knowledge', '{调度规范,watch_manage,scheduler_manage,geer,002241}', NULL, '''-06'':4A,14B ''-09'':3A,13B ''0901'':47B ''2026'':2A,12B ''24.4'':22B ''35'':50B ''9'':49B ''break/change_pct'':31B ''d1e6cebf'':7A,17B ''geer'':44B ''geer-take-profit'':43B ''manage'':28B ''price'':30B ''profit'':46B ''scheduler'':34B ''take'':45B ''w'':6A,16B ''w-d1e6cebf'':5A,15B ''watch'':27B ''xx'':24B ''不应做成'':33B ''价格条件触发类监控'':9A,19B ''作为反例'':52B ''创建盯盘规则'':29B ''周报等'':39B ''如'':10A,20B ''定时任务'':35B ''定时任务用于时间驱动的例行流程'':36B ''已删除'':42B ''应使用'':26B ''检查价格'':51B ''歌尔'':21B ''止盈'':23B ''止跌企稳观察'':25B ''每日'':48B ''用户反馈'':8A,18B ''盘前例程'':37B ''盘后复盘'':38B ''盯盘与调度分类纪律'':1A,11B ''盯盘规则用于价格'':40B ''等条件'':32B ''量能条件触发的实时响应'':41B', '2026-09-06 14:25:37.514886', '2026-09-06 14:25:37.514886', '{}');
