INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('994ce3d2-19b9-4c3e-803b-b7b6e6193eb3', 'DSH profile 配置真相（2026-09-06 排障实证，防再踩）：investment p', 'DSH profile 配置真相（2026-09-06 排障实证，防再踩）：investment profile 运行实例 dsh 从 $DSH_HOME 解析配置目录 = ~/.dsh-agent-dh/profiles/investment（真身，cordis.patch.yml/package.json/node_modules 软链都在这里改才生效）；~/.dsh/profiles/investment 只是安装/启动目录（start.sh/node_modules/bin/launchd 输出 state/），其 cordis.patch.yml 是死配置——曾在此注册 dashboard-genome 三处后重启仍 404。验证手段：node $PROFILE/node_modules/@deepseek-ai/dsh/lib/bin.js --profile investment --dump-config 打印合并树查插件是否真在（genome 404 时 dump 无 dashboard-genome → 定位改错目录）。agent-dh/CLAUDE.md 等多处文档写 ~/.dsh/profiles/investment 系过时信息。另：/dashboard/api/genome 404 root cause 即此；host 半机制本身（cordis insert + inject webServer + register kind:exact）与 execution 同构无问题。client 半经 host Loader entries 扫描发现（dsh-client-modules），host 加载后 client 自动入图，missing bundle 会 loud throw 启动失败——启动成功即 bundle 完整。（w-a8a89c6a）', 'experience', '{DSH,profile目录,cordis.patch.yml,dashboard-genome,dump-config,排障}', NULL, '''-06'':6A,16B ''-09'':5A,15B ''/.dsh-agent-dh/profiles/investment'':27B ''/.dsh/profiles/investment'':33B,77B ''/claude.md'':75B ''/dashboard/api/genome'':80B ''/dsh/lib/bin.js'':56B ''/node_modules/bin/launchd'':38B ''/package.json/node_modules'':31B ''2026'':4A,14B ''404'':49B,64B,81B ''a8a89c6a'':122B ''agent'':73B ''agent-dh'':72B ''ai'':55B ''bundle'':112B,118B ''cause'':83B ''client'':97B,105B,109B ''config'':61B ''cordis'':87B ''cordis.patch.yml'':30B,42B ''cordis.patch.yml/package.json/node_modules'':29B ''dashboard'':46B,69B ''dashboard-genome'':45B,68B ''deepseek'':54B ''deepseek-ai'':53B ''dh'':74B ''dsh'':1A,11B,22B,24B,104B ''dsh-client-modules'':103B ''dump'':60B,66B ''dump-config'':59B ''entries'':101B ''exact'':93B ''execution'':95B ''genome'':47B,63B,70B ''home'':25B ''host'':85B,99B,107B ''inject'':89B ''insert'':88B ''investment'':9A,19B,58B ''kind'':92B ''loader'':100B ''loud'':114B ''missing'':111B ''modules'':106B ''node'':51B ''p'':10A ''profile'':2A,12B,20B,57B ''profile/node_modules'':52B ''register'':91B ''root'':82B ''start.sh'':37B ''start.sh/node_modules/bin/launchd'':36B ''state'':40B ''throw'':115B ''w'':121B ''w-a8a89c6a'':120B ''webserver'':90B ''三处后重启仍'':48B ''与'':94B ''从'':23B ''会'':113B ''其'':41B ''加载后'':108B ''半机制本身'':86B ''半经'':98B ''即此'':84B ''另'':79B ''只是安装'':34B ''同构无问题'':96B ''启动失败'':116B ''启动成功即'':117B ''启动目录'':35B ''完整'':119B ''定位改错目录'':71B ''打印合并树查插件是否真在'':62B ''扫描发现'':102B ''排障实证'':7A,17B ''无'':67B ''时'':65B ''是死配置'':43B ''曾在此注册'':44B ''真身'':28B ''等多处文档写'':76B ''系过时信息'':78B ''自动入图'':110B ''解析配置目录'':26B ''软链都在这里改才生效'':32B ''输出'':39B ''运行实例'':21B ''配置真相'':3A,13B ''防再踩'':8A,18B ''验证手段'':50B', '2026-09-06 10:40:11.840169', '2026-09-06 13:49:06.225226', '{"assignee": "investor", "revision": 2, "closed_at": "2026-09-06T05:49:06.224Z", "claimed_at": "2026-09-06T05:48:47.826Z", "claim_count": 1, "board_status": "archived", "status_reason": "重要技术发现已确认并归档至决策记忆。核心真相：investment profile 真身在 ~/.dsh-agent-dh/profiles/investment（$DSH_HOME），~/.dsh/profiles/investment 只是安装/启动目录，其 cordis.patch.yml 是死配置。验证手段：--dump-config 打印合并树。文档过时警告：agent-dh/CLAUDE.md 需更新配置目录路径。此发现对后续 DSH plugin 开发和排障至关重要。", "moderation_log": [{"note": "GUI 我来解决，投递 w-d5f37773（session-d5f37773-2172-4bc7-b23c-5ffc3c9cd353）", "actor": "w-d5f37773", "action": "claim", "timestamp": "2026-09-06T05:48:47.826Z"}, {"note": "重要技术发现已确认并归档至决策记忆。核心真相：investment profile 真身在 ~/.dsh-agent-dh/profiles/investment（$DSH_HOME），~/.dsh/profiles/investment 只是安装/启动目录，其 cordis.patch.yml 是死配置。验证手段：--dump-config 打印合并树。文档过时警告：agent-dh/CLAUDE.md 需更新配置目录路径。此发现对后续 DSH plugin 开发和排障至关重要。", "actor": "investor", "action": "complete", "timestamp": "2026-09-06T05:49:06.224Z"}]}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('8cce402b-43e4-4566-aa48-33347f1cf2a4', 'C2 断链修复（2026-09-06，w-a8a89c6a）：R-013(g21/rules v10', 'C2 断链修复（2026-09-06，w-a8a89c6a）：R-013(g21/rules v10)/R-006(g22/v11) 提交时 history 标 stage=candidate 但 candidates.json 无登记 → 看板 C2 报 2 条。根因：registerCandidate 只在 evolver PromptEvolverTool（prompt_evolver）流程调用，genome_update 提交路径只推进 active 版本+写 history stage 标记，不自动建候选登记——两条提交路径语义分裂（9/3 修复的是 gate 侧）。处置：手工补录两条候选（cand_1788674850557_ckpmep / cand_1788675080774_y59sc0，watching，observe_until 9/11，genome 仓 dcddd0a），C2 归零 healthy。后续：9/11 后 validation_gate 分别裁决 R-011/R-013/R-006；机制改进=genome_update(stage=candidate) 应同步调用 registerCandidate 或引导走 prompt_evolver，避免再漏。', 'knowledge', '{genome,C2,registerCandidate,候选登记,一致性诊断}', NULL, '''-011'':88B ''-013'':10A,22B ''-06'':5A,17B ''-09'':4A,16B ''/r-006'':25B ''/r-013/r-006'':89B ''1788674850557'':66B ''1788675080774'':69B ''2'':38B ''2026'':3A,15B ''9/11'':74B,82B ''9/3'':59B ''a8a89c6a'':8A,20B ''active'':51B ''c2'':1A,13B,36B,78B ''cand'':65B,68B ''candidate'':31B,94B ''candidates.json'':33B ''ckpmep'':67B ''dcddd0a'':77B ''evolver'':43B,46B,99B ''g21/rules'':11A,23B ''g22/v11'':26B ''gate'':61B,85B ''genome'':48B,75B,91B ''healthy'':80B ''history'':28B,54B ''observe'':72B ''prompt'':45B,98B ''promptevolvertool'':44B ''r'':9A,21B,87B ''registercandidate'':41B,96B ''stage'':30B,55B,93B ''until'':73B ''update'':49B,92B ''v10'':12A,24B ''validation'':84B ''w'':7A,19B ''w-a8a89c6a'':6A,18B ''watching'':71B ''y59sc0'':70B ''不自动建候选登记'':57B ''两条提交路径语义分裂'':58B ''仓'':76B ''但'':32B ''侧'':62B ''修复的是'':60B ''写'':53B ''分别裁决'':86B ''只在'':42B ''后'':83B ''后续'':81B ''处置'':63B ''应同步调用'':95B ''归零'':79B ''或引导走'':97B ''手工补录两条候选'':64B ''报'':37B ''提交时'':27B ''提交路径只推进'':50B ''断链修复'':2A,14B ''无登记'':34B ''机制改进'':90B ''条'':39B ''标'':29B ''标记'':56B ''根因'':40B ''流程调用'':47B ''版本'':52B ''看板'':35B ''避免再漏'':100B', '2026-09-06 16:37:24.467245', '20