INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('fe1eae12-88b7-4896-aea1-cff21af4d4d7', 'agent-self WIP 生命周期修复完成（2026-09-06，w-856b64ef）：lif', 'agent-self WIP 生命周期修复完成（2026-09-06，w-856b64ef）：lifecycle 收尾三机制断点修复已 ff 合并进 main @92f884da，feat/lifecycle-wip-finalize 分支与 worktree 已清理。修复要点：①scheduleRestart wip-on-wip 用 commitOnCurrent 续提交复用当前分支为 checkpoint 不再建链；②git.ts 新增 finalizeMerge 策略化收尾（already-merged/already-cherried/ff-merged/3-way merged/conflict 抛错保留 wip），替代脆弱 mergeFfOnly，等价并入或可 3-way 合并的 wip 绝不静默滞留；③resolveTrunkBase 三步链根溯源 + cleanupWipChain 整链清理已并入残留、保留未并入内容（144904 在 feat/genome-explain-execution 绝不删）；④setupStrandedWipWatchdog 启动时若停在 agent-self/* 且无 pending 则提醒 investor 根收尾。测试 30/30 绿（git 14 + finalize 6 + cron 10）。⚠️ 运行中 DSH profile(:13080) 仍加载旧构建，需用户知情下重启后才生效。留痕：docs/work-logs/2026-09/wip-lifecycle-finalize-fix-20260906.md', 'knowledge', '{lifecycle,agent-self,wip,self_finalize,w-856b64ef,2026-09-06}', NULL, '''-06'':8A,20B ''-09'':7A,19B ''/already-cherried/ff-merged/3-way'':52B ''10'':91B ''13080'':95B ''14'':87B ''144904'':69B ''2026'':6A,18B ''3'':59B ''30/30'':84B ''6'':89B ''856b64ef'':11A,23B ''92f884da'':29B ''agent'':2A,14B,76B ''agent-self'':1A,13B,75B ''already'':50B ''already-merged'':49B ''checkpoint'':43B ''cleanupwipchain'':66B ''commitoncurrent'':41B ''cron'':90B ''docs/work-logs/2026-09/wip-lifecycle-finalize-fix-20260906.md'':99B ''dsh'':93B ''feat/genome-explain-execution'':71B ''feat/lifecycle-wip-finalize'':30B ''ff'':26B ''finalize'':88B ''finalizemerge'':47B ''git'':86B ''git.ts'':45B ''investor'':81B ''lif'':12A ''lifecycle'':24B ''main'':28B ''merged'':51B ''merged/conflict'':53B ''mergeffonly'':57B ''on'':38B ''pending'':79B ''profile'':94B ''resolvetrunkbase'':64B ''schedulerestart'':35B ''self'':3A,15B,77B ''setupstrandedwipwatchdog'':73B ''w'':10A,22B ''w-856b64ef'':9A,21B ''way'':60B ''wip'':4A,16B,37B,39B,55B,62B ''wip-on-wip'':36B ''worktree'':32B 