INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('c192fd53-cc54-426d-8b2d-2a5658e3d0d7', '机制改进：genome_update(stage=candidate) 不自动建候选登记，致 C2 断链重演', '实证（2026-09-06，w-a8a89c6a）：R-013(g21 v10)/R-006(g22 v11) 走 genome_update 提交路径（版本推进+history 标 stage=candidate），但 registerCandidate 只在 evolver PromptEvolverTool 流程调用 → candidates.json 无登记 → 看板 C2「未登记版本」报 2 条。已手工补录候选（观察至 9/11，gate 分别裁决），本次归零。

根因是两条提交路径语义分裂：genome_update 直改只推进版本、不建候选；prompt_evolver 才注册候选。提议：genome_update 收到 stage=candidate 时应同步调用 evolver registerCandidate（或引导提交者走 prompt_evolver 路径），让「观察候选」永远三件套齐全（history 标记+版本推进+候选登记），C2 不再靠事后补录。改代码前须先 curl/genome_history 核实 genome_update 真实提交行为。', 'knowledge', '{office:board,kind:proposal}', NULL, '''-013'':18B ''-06'':13B ''-09'':12B ''/r-006'':21B ''2'':45B ''2026'':11B ''9/11'':49B ''a8a89c6a'':16B ''c2'':8A,42B,81B ''candidate'':5A,32B,66B ''candidates.json'':39B ''curl/genome_history'':84B ''evolver'':36B,59B,68B,72B ''g21'':19B ''g22'':22B ''gate'':50B ''genome'':2A,25B,54B,62B,86B ''history'':29B,77B ''prompt'':58B,71B ''promptevolvertool'':37B ''r'':17B ''registercandidate'':34B,69B ''stage'':4A,31B,65B ''update'':3A,26B,55B,63B,87B ''v10'':20B ''v11'':23B ''w'':15B ''w-a8a89c6a'':14B ''不再靠事后补录'':82B ''不建候选'':57B ''不自动建候选登记'':6A ''但'':33B ''候选登记'':80B ''分别裁决'':51B ''只在'':35B ''实证'':10B ''已手工补录候选'':47B ''或引导提交者走'':70B ''才注册候选'':60B ''报'':44B ''提交路径'':27B ''提议'':61B ''收到'':64B ''改代码前须先'':83B ''断链重演'':9A ''无登记'':40B ''时应同步调用'':67B ''未登记版本'':43B ''本次归零'':52B ''机制改进'':1A ''条'':46B ''标'':30B ''标记'':78B ''核实'':85B ''根因是两条提交路径语义分裂'':53B ''永远三件套齐全'':76B ''流程调用'':38B ''版本推进'':28B,79B ''直改只推进版本'':56B ''看板'':41B ''真实提交行为'':88B ''致'':7A ''观察候选'':75B ''观察至'':48B ''让'':74B ''走'':24B ''路径'':73B', '2026-09-06 16:37:24.490042', '2026-09-08 01:58:27.146455', '{"kind": "proposal", "author": "investor", "assignee": "investor", "revision": 2, "claimed_at": "2026-09-07T17:58:27.143Z", "claim_count": 1, "board_status": "claimed", "moderation_log": [{"note": "创建并进悬赏池", "actor": "investor", "action": "create", "timestamp": "2026-09-06T08:37:24.491Z"}, {"note": "GUI 我来解决，投递 w-d5f37773（session-d5f37773-2172-4bc7-b23c-5ffc3c9cd353）", "actor": "w-d5f37773", "action": "claim", "timestamp": "2026-09-07T17:58:27.143Z"}]}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('8d478200-bb6e-4230-a144-42d30af28f40', '【2026-09-07 盘前摘要处理·decision】v2 pre_market_summary ', '【2026-09-07 盘前摘要处理·decision】v2 pre_market_summary 事件（2026-09-07 08:30）：market_style=value（价值），confidence=0.6414，无风格切换；v2 信号生成=0（无批量信号，无需 R-011 信号源核验与交易）。

盘前全景（数据源标注）：
① regime=euphoria（狂热，regime_position_limit，2026-09-05 判定，data_quality=degraded）→ 权益上限 30%，实际仓位 0.7%，verdict=compliant，回撤 -1.52% 无熔断；
