INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('3c101d77-8267-49c4-964f-3a0950593cfc', '公告板误捞根因与修复（2026-09-08，w-08c8233b）：用户反馈公告板发帖频繁且解决后不', '公告板误捞根因与修复（2026-09-08，w-08c8233b）：用户反馈公告板发帖频繁且解决后不改状态。根因=Agent OS memory 语义搜索 tag 过滤不严格，memory_write 写的普通复盘/交付记录（无 office:board 标签、无 metadata）被 board_read/bulletin 聚合捞进公告板，且两处代码缺 board_status 时默认 open → 显示为无人认领的悬赏帖永不关闭。这类帖 board_update 无法操作（无 metadata 引发 PATCH revision 409 + 无作者/认领人权限拒绝），只能用 DELETE /api/v1/memory/{id} 软删。处置：软删 4 条误捞帖（51acd5e0/2d1d183d/5d31abdb/3ce8e121，memory 本体保留）；代码修复=board_read（lifecycle/board-tools.ts）与 bulletin-aggregation.ts 增加真帖子过滤（office:board 标签或已有 board_status 才纳入），冒烟测试 19/19 通过，待 DSH 重启生效。纪律：纯记录只走 memory_write，board_post 仅用于悬赏/协作类真帖子。', 'knowledge', '{公告板,board_read,误捞,office:board,根因修复}', NULL, '''-08'':4A,12B ''-09'':3A,11B ''/api/v1/memory'':58B ''08c8233b'':7A,15B ''19/19'':82B ''2026'':2A,10B ''4'':63B ''409'':53B ''51acd5e0/2d1d183d/5d31abdb/3ce8e121'':65B ''agent'':18B ''board'':30B,35B,39B,45B,69B,76B,78B,91B ''bulletin-aggregation.ts'':73B ''delete'':57B ''dsh'':85B ''id'':59B ''lifecycle/board-tools.ts'':71B ''memory'':20B,24B,66B,89B ''metadata'':33B,49B ''office'':29B,75B ''open'':42B ''os'':19B ''patch'':51B ''post'':92B ''read'':70B ''read/bulletin'':36B ''revision'':52B ''status'':40B,79B ''tag'':22B ''update'':46B ''w'':6A,14B ''w-08c8233b'':5A,13B ''write'':25B,90B ''与'':72B ''且两处代码缺'':38B ''交付记录'':27B ''仅用于悬赏'':93B ''代码修复'':68B ''公告板误捞根因与修复'':1A,9B ''冒烟测试'':81B ''写的普通复盘'':26B ''协作类真帖子'':94B ''只能用'':56B ''增加真帖子过滤'':74B ''处置'':61B ''引发'':50B ''待'':84B ''才纳入'':80B ''无'':28B,32B,48B ''无作者'':54B ''无法操作'':47B ''时默认'':41B ''显示为无人认领的悬赏帖永不关闭'':43B ''本体保留'':67B ''条误捞帖'':64B ''标签'':31B ''标签或已有'':77B ''根因'':17B ''用户反馈公告板发帖频繁且解决后不'':8A ''用户反馈公告板发帖频繁且解决后不改状态'':16B ''纪律'':87B ''纯记录只走'':88B ''聚合捞进公告板'':37B ''被'':34B ''认领人权限拒绝'':55B ''语义搜索'':21B ''软删'':60B,62B ''过滤不严格'':23B ''这类帖'':44B ''通过'':83B ''重启生效'':86B', '20