INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('287b960d-5777-417e-91a9-91cb090be15d', 'R-014 公告板发帖先确认（2026-09-08 用户指令，genome rules v12/g2', 'R-014 公告板发帖先确认（2026-09-08 用户指令，genome rules v12/g23，w-08c8233b 落实）：board_post 前必须先向用户确认是否需要发帖；公告板只承载悬赏/跨窗口协作/需他人行动的帖（needs_action=true），纯记录/复盘/交付说明走 memory_write/decision_audit；memory_write 标签禁带 office:board；board_update 状态流转不需确认但 note 必填。', 'knowledge', '{R-014,公告板,发帖纪律,用户指令}', NULL, '''-014'':2A,12B ''-08'':6A,16B ''-09'':5A,15B ''08c8233b'':23B ''2026'':4A,14B ''action'':32B ''board'':25B,43B,44B ''genome'':8A,18B ''memory'':37B,39B ''needs'':31B ''note'':47B ''office'':42B ''post'':26B ''r'':1A,11B ''rules'':9A,19B ''true'':33B ''update'':45B ''v12/g2'':10A ''v12/g23'':20B ''w'':22B ''w-08c8233b'':21B ''write'':40B ''write/decision_audit'':38B ''交付说明走'':36B ''公告板发帖先确认'':3A,13B ''公告板只承载悬赏'':28B ''前必须先向用户确认是否需要发帖'':27B ''复盘'':35B ''必填'':48B ''标签禁带'':41B ''状态流转不需确认但'':46B ''用户指令'':7A,17B ''纯记录'':34B ''落实'':24B ''跨窗口协作'':29B ''需他人行动的帖'':30B', '2026-09-07 22:58:22.556922', '2026-09-07 22:58:22.556922', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('8adca5ba-8178-4318-9d4e-24167f81796e', 'reminder agent-brain-morning-analysis delivered', '{"task":"agent-brain-morning-analysis","task_id":"3cd18227-03e3-4da4-b66a-1d58b9b7e68f","prompt":"你是 investor（PI 投资顾问·投资脑）。本任务是账户 agent_brain 的专属例行，只能作用于该账户。\n硬纪律：①全部账户查询/交易工具必须显式传 account_name=\"agent_brain\"（工具默认 agent_virtual，禁止作用错账户）；\n②交易宪法：仅 9:30-11:30/13:00-15:00 A股交易日可买卖、T+1（当日买次日卖）、买入 100 股整数倍、单股≤总资产 20%、单行业≤40%、现金≥10%、止损铁律（蓝筹-8%/成长-10%/题材-12%）；\n③买入前 regime_position_limit（R-006 档位映射，degraded 收紧到震荡档）+ risk_controller 算仓位；④信号 R-009 A/B/C 分级，C 级只观察不下单；\n⑤决策前 memory_search(namespace=experience) 检索历史教训（R-008）并在 reason 注明；⑥引用数据必须标注来源工具+数据时点（R-013，db 缓存不得冒充实时价）；\n⑦无信号/无动作时空仓等待是正确决策（宪法 6），不强求交易。\n\n【本任务】agent_brain 盘前晨间分析（09:00 开盘前完成）：\n1) regime_position_limit(account_name=\"agent_brain\")：记录 regime/权益仓位上限/余量/compliant 判定；circuit_breaker 触发立即 feishu_notify(alerts, high)。\n2) event_calendar_check(upcoming, days=2) 未来事件 + market_alert(high) 评估对持仓影响。\n3) account_info + position_list(account_name=\"agent_brain\") 核对总资产/现金/持仓；portfolio_analyze 找已触止损/止盈线的持仓，列入今日处置预案（实际执行须在交易时段）。\n4) sector_analysis/mainline_scan 简要扫描今日主线（控制在 2-3 工具）。\n任务完成后 feishu_notify 主动汇报（标题见下），内容含：核心数据（标注来源工具+时点）、决策动作、下一步；urgency/channel 按说明。一般性留痕写 memory_write(namespace=decision/analysis)，交易决策另 decision_audit(record)。\n【汇报要求】feishu_notify(channel=reports, urgency=normal) 标题【agent_brain 晨间简报】，内容：regime 与权益上限、持仓健康（止损距离）、今日事件/告警要点、计划动作。","window":"w-a8a89c6a","fired_at":"2026-09-08T01:00:00Z","delivered":true,"delivered_at":"2026-09-08T01:00:00.197Z","executor":{"mode":"direct","session_id":"investor-session-6ee0030a-aeb7-4e9b-9ad8-4ccd470ffc0b"}}', 'data', '{office:delivered,office:reminder:exec,office:reminder:investor-session-6ee0030a-aeb7-4e9b-9ad8-4ccd470ffc0b}', NULL, '''+1'':56B ''-006'':81B ''-008'':103B ''-009'':90B ''-013'':110B ''-08'':237B,247B ''-09'':236B,246B ''-10