INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('23fd12db-e37d-45eb-87df-e8e2ad7eb1a9', 'solve-kit 公用包使用说明（2026-09-08，w-752decf5）：位置 agent-', 'solve-kit 公用包使用说明（2026-09-08，w-752decf5）：位置 agent-dh/packages/solve-kit；host 侧 import { createSolveHandler }（deps.resolveAgent(sessionId?,exactOnly?)，opts{panel,panelFull,plugin}）注册 POST 路由，投递消息带 source:{kind:''plugin''} 与 from_session 窗口码可溯源；client 侧 import { createSolveKit, injectSolveStyles }，createSolveKit(deps{endpoint,prefix,candidates(),current(),resolveSnapshot(kind:''task''|''error'',identity)→{kind,snap}|null})；按钮注入前缀样式 {pf}-solve，弹层 {pf}-solvepop；快照板型（task）：name/src/scheduleExpr/nextRunAt/lastRun{status,triggeredAt,finishedAt,err}/todayTriggered/todaySuccess/fetchedAt(GMT+8)/error——Agent OS SchedulerTask(lastStatus/lastAt 字符串) 必须归一化。消费方注意事项：pages 依赖用绝对 symlink（pnpm install 被 genome dsh-llm 坏版本阻断）；client bundle 由 tsdown 内联 kit（exports ./client import 指向 src 源码）；host 改动需 self_restart 生效。', 'knowledge', '{solve-kit,architecture,execution,holdings,client,2026-09-08,w-752decf5}', NULL, '''+8'':84B ''-08'':7A,19B ''-09'':6A,18B ''/client'':111B ''/error'':85B ''/packages/solve-kit'':27B ''/todaytriggered/todaysuccess/fetchedat'':82B ''2026'':5A,17B ''752decf5'':10A,22B ''agent'':12A,25B,86B ''agent-dh'':24B ''bundle'':105B ''candidates'':59B ''client'':50B,104B ''createsolvehandler'':31B ''createsolvekit'':53B,55B ''current'':60B ''deps'':56B ''deps.resolveagent'':32B ''dh'':26B ''dsh'':101B ''dsh-llm'':100B ''endpoint'':57B ''err'':81B ''error'':64B ''exactonly'':34B ''exports'':110B ''finishedat'':80B ''from'':47B ''genome'':99B ''gmt'':83B ''host'':28B,116B ''identity'':65B ''import'':30B,52B,112B ''injectsolvestyles'':54B ''install'':97B ''kind'':44B,62B,66B ''kit'':3A,15B,109B ''laststatus/lastat'':89B ''llm'':102B ''name/src/scheduleexpr/nextrunat/lastrun'':77B ''null'':68B ''opts'':35B ''os'':87B ''pages'':93B ''panel'':36B ''panel