INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('4bc3c4a9-5f05-43c0-9f41-d15c50c9dce3', '2026-09-08 13:01 agent_virtual 账户回撤熔断激活：60日最大回撤 -1', '2026-09-08 13:01 agent_virtual 账户回撤熔断激活：60日最大回撤 -10.64%（m4_circuit_breaker_check + regime_position_limit 双重确认），R-007 要求减仓一半+禁止新开仓。已卖出 601288 农业银行 100股@6.76（订单38，DEC-20260908130147-19a8d2c1）。待办：600887 伊利股份 900股（成本26.75）+ 300677 英科医疗 100股（成本53.49）为 2026-09-08 当日买入，T+1 不可卖，**2026-09-09 开盘后必须继续减仓**至权益仓位 ~14%（约还需卖出 1.4-1.5 万元市值），期间禁止新开仓。解除条件：60日回撤回到 -8% 以内。另一账户 agent_brain 熔断未触发（-5.17%）勿混淆。', 'knowledge', '{熔断,circuit_breaker,agent_virtual,R-007,减仓待办,601288,600887,300677}', NULL, '''+1'':58B ''-007'':30B ''-08'':3A,13B,55B ''-09'':2A,12B,54B,61B,62B ''-1'':10A ''-1.5'':68B ''-10.64'':20B ''-19'':41B ''-20260908130147'':40B ''-5.17'':79B ''-8'':73B ''01'':5A,15B ''1.4'':67B ''100股'':36B,50B ''13'':4A,14B ''14'':65B ''2026'':1A,11B,53B,60B ''300677'':48B ''6.76'':37B ''600887'':44B ''601288'':34B ''60日回撤回到'':72B ''60日最大回撤'':9A,19B ''900股'':46B ''a8d2c1'':42B ''agent'':6A,16B,76B ''brain'':77B ''breaker'':23B ''check'':24B ''circuit'':22B ''dec'':39B ''limit'':27B ''m4'':21B ''position'':26B ''r'':29B ''regime'':25B ''t'':57B ''virtual'':7A,17B ''万元市值'':69B ''不可卖'':59B ''为'':52B ''以内'':74B ''伊利股份'':45B ''农业银行'':35B ''勿混淆'':80B ''双重确认'':28B ''另一账户'':75B ''已卖出'':33B ''开盘后必须继续减仓'':63B ''当日买入'':56B ''待办'':43B ''成本26.75'':47B ''成本53.49'':51B ''期间禁止新开仓'':70B ''熔断未触发'':78B ''禁止新开仓'':32B ''约还需卖出'':66B ''至权益仓位'':64B ''英科医疗'':49B ''要求减仓一半'':31B ''解除条件'':71B ''订单38'':38B ''账户回撤熔断激活'':8A,18B', '2026-09-08 13:01:55.398172', '2026-09-08 13:01:55.398172', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('a9add089-4d85-4dcb-8146-7698fb34c60f', 'reminder agent-brain-realtime-check delivered', '{"task":"agent-brain-realtime-check","task_id":"974fa7b6-ce78-451b-a3da-c1cb314f6180","prompt":"你是 investor（PI 投资顾问·投资脑）。本任务是账户 agent_brain 的专属例行，只能作用于该账户。\n硬纪律：①全部账户查询/交易工具必须显式传 account_name=\"agent_brain\"（工具默认 agent_virtual，禁止作用错账户）；\n②交易宪法：仅 9:30-11:30/13:00-15:00 A股交易日可买卖、T+1（当日买次日卖）、买入 100 股整数倍、单股≤总资产 20%、单行业≤40%、现金≥10%、止损铁律（蓝筹-8%/成长-10%/题材-12%）；\n③买入前 regime_position_limit（R-006 档位映射，degraded 收紧到震荡档）+ risk_controller 算仓位；④信号 R-009 A/B/C 分级，C 级只观察不下单；\n⑤决策前 memory_search(namespace=experience) 检索历史教训（R-008）并在 reason 注明；⑥引用数据必须标注来源工具+数据时点（R-013，db 缓存不得冒充实时价）；\n⑦无信号/无动作时空仓等待是正确决策（宪法 6），不强求交易。\n\n【本任务】agent_brain 盘中快速检查（交易时段内）：\n1) market_alert(level=high) 看新告警；regime_position_limit 复核仓位余量（快速，异常才深查）。\n2) position_list + portfolio_analyze(account_name=\"agent_brain\")：逐只盈亏与止损/止盈距离；触发止损线的按宪法立即卖出（止损不手软、不补仓）；触发止盈预案的按预案执行或说明理由。\n3) 出现 A/B 级买入信号（≥2 维共振+基本面无雷+符合仓位余量）才可建仓，C 级或矛盾只记录观察（signal_track record），不委托。\n4) 仅做必要处置不刷屏；常规检查无动作时静默结束（正确决策），每次执行结束若有交易写 decision_audit(record, reason 引规则ID)。\n【汇报要求】仅当有实际交易/新告警/异常时 feishu_notify(channel=alerts, urgency=high) 标题【agent_brain 盘中处置】；常规无异常不发通知避免打扰。","window":"w-a8a89c6a","fired_at":"2026-09-08T05:30:00Z","delivered":true,"delivered_at":"2026-09-08T05:30:00.059Z","executor":{"mode":"direct","session_id":"investor-session-20ead2c7-8c2d-4528-a1c8-7f4e5a72c6f9"}}', 'data', '{office:delivered,office:reminder:exec,office:reminder:investor-session-20ead2c7-8c2d-4528-a1c8-7f4e5a72c6f9}', NULL, '''+1'':56B ''-006'':81B ''-008'':103B ''-009'':90B ''-013'':110B ''-08'':202B,212B ''-09'':201B,211B ''-10'':72B ''-11'':49B ''-12'':74B ''-15'':52B ''-8'':70B ''00'':51B,53B ''00.059'':215B ''00z'':205B ''10'':67B ''100'':59B ''2'':157B ''20'':63B ''2026'':200B,210B ''20ead2c7'':225B ''30'':48B,204B,214B ''30/13'':50B ''40'':65