INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('0304a0fd-e11b-4663-9bab-cead7179f56a', 'reminder intraday-surge-scan-pm delivered', '{"task":"intraday-surge-scan-pm","task_id":"a3e404a9-cc8c-4352-b472-48684d5b796c","prompt":"【午后异动扫描 13:45】目的：看午后资金转向、捕捉上午漏掉的启动、为次日预案备料；无真信号不打扰。执行：1) data_fetch_market_sentiment 看情绪/涨跌家数是否延续上午；2) sector_analysis(days=1)看板块涨幅榜 vs 上午(memory/上午速报)对比→午后新启动/加强板块；3) limit_up_pool(今日)看炸板/新增涨停，午后封板股=资金态度；4) 若上午已发过速报→验证该板块午后是否延续(回踩/加强)，加强则更新signal_track，证伪则记录修正教训(experience_write级别低,memory即可)；5) 对新启动板块重复上午的验证流程(成分→2-3龙头→三维→分级→落库)；6) 次日预案：对A/B级候选标注''明日触发价位+确认条件''(上破哪、需什么量能/资金确认)，写 memory_write(analysis) 供盘前例程9:25取用；7) 输出：有新增A/B级或持仓午后急变→feishu_notify(normal,reports)；否则memory一句即止；8) 纪律同上午：数据带来源时点(R-013)、euphoria不追高、候选必落signal_track、持仓股异动优先high告警(600036/601600/000807/002007/002463/600026等)。","window":"w-5b8aac2a","fired_at":"2026-09-08T05:45:00Z","delivered":true,"delivered_at":"2026-09-08T05:45:00.045Z","executor":{"mode":"direct","session_id":"investor-session-20ead2c7-8c2d-4528-a1c8-7f4e5a72c6f9"}}', 'data', '{office:delivered,office:reminder:exec,office:reminder:investor-session-20ead2c7-8c2d-4528-a1c8-7f4e5a72c6f9}', NULL, '''-013'':112B ''-08'':127B,137B ''-09'':126B,136B ''-3'':77B ''/b'':85B,101B ''00.045'':140B ''00z'':130B ''1'':33B,44B ''13'':25B ''2'':40B,76B ''2026'':125B,135B ''20ead2c7'':150B ''25取用'':97B ''3'':53B ''4'':62B ''4352'':19B ''45'':26B,129B,139B ''4528'':152B ''48684d5b796c'':22B ''5'':73B ''5b8aac2a'':122B ''6'':82B ''600036/601600/000807/002007/002463/600026'':117B ''7'':98B ''7f4e5a72c6f9'':155B ''8'':108B ''8c2d'':151B ''a1c8'':154B ''a1c8-7f4e5a72c6f9'':153B ''a3e404a9'':17B ''a3e404a9-cc8c'':16B ''analysis'':42B,95B ''at'':124B,134B ''b472'':21B ''b472-48684d5b796c'':20B ''cc8c'':18B ''data'':34B ''days'':43B ''delivered'':7A,131B,133B ''direct'':144B ''euphoria不追高'':113B ''executor'':142B ''experience'':70B ''feishu'':103B ''fetch'