INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('e7413633-abda-41c1-b677-187cff78af8a', 'reminder afternoon-open-check-live delivered', '{"task":"afternoon-open-check-live","task_id":"028504f3-75f2-4bca-a679-746bba1eee9d","prompt":"【盘中开盘检查 13:00】执行：1) regime_position_limit 确认当前 regime 与仓位余量；2) account_info + position_list 查账户状态；3) market_alert 查市场告警；4) 如有异常立即处理或通知。这是每日例行检查，regime 变化或有告警时必须响应。\n\n【汇报要求】完成后必须飞书简报（channel=reports, urgency=normal）：任务名+关键结果摘要（1-3行）；发现异常则 urgency=high 发 alerts 群。（简报内容：regime、仓位余量、账户状态、告警数）","window":"w-29882338","fired_at":"2026-09-10T05:00:00Z","delivered":true,"delivered_at":"2026-09-10T05:00:00.060Z","executor":{"mode":"direct","session_id":"session-706fa9da-5eba-4224-9a90-eb30747bba7c"}}', 'data', '{office:delivered,office:reminder:exec,office:reminder:w-706fa9da}', NULL, '''-09'':79B,89B ''-10'':80B,90B ''-29882338'':75B ''-3'':60B ''-9'':105B ''00'':25B,82B,92B ''00.060'':93B ''00z'':83B ''028504f3'':17B ''028504f3-75f2-4bca-a679-746bba1eee9d'':16B ''1'':27B,59B ''13'':24B ''2'':34B ''2026'':78B,88B ''3'':40B ''4'':44B ''4224'':104B ''4bca'':19B ''5eba'':103B ''706fa9da'':102B ''746bba1eee9d'':21B ''75f2'':18B ''a679'':20B ''a90'':107B ''a90-eb30747bba7c'':106B ''account'':35B ''afternoon'':3A,10B ''afternoon-open-check-live'':2A,9B ''alert'':42B ''alerts'':66B ''at'':77B,87B ''channel'':53B ''check'':5A,12B ''delivered'':7A,84B,86B ''direct'':97B ''eb30747bba7c'':108B ''executor'':95B ''fired'':76B ''high'':64B ''id'':15B,99B ''info'':36B ''limit'':30B ''list'':38B ''live'':6A,13B ''market'':41B ''mode'':96B ''n'':49B,50B ''normal'':56B ''open'':4A,11B ''position'':29B,37B ''prompt'':22B ''regime'':28B,32B,47B,69B ''reminder'':1A ''reports'':54B ''session'':98B,101B ''session-706fa9da-5eba'':100B ''t05'':81B,91B ''task'':8B,14B ''true'':85B ''urgency'':55B,63B ''w'':74B ''window'':73B ''z'':94B ''与仓位余量'':33B ''仓位余量'':70B ''任务名'':57B ''关键结果摘要'':58B '