INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('7c24f7c3-5209-4b7d-8ccd-bb07980cf5f7', '工程复盘（2026-09-08 dsh-pmboard rename 全链错误归因，主复盘）：
最终', '工程复盘（2026-09-08 dsh-pmboard rename 全链错误归因，主复盘）：
最终状态：项目看板已实现（侧栏按钮 + host 路由 200）。本 agent（投资 profile）在这条工作线的全部错误与归因：

【错误 A｜浅改名沿用带病蓝本】rename requirement→dsh-pmboard 时沿用蓝本(97ee9987)的 exports 形态（exports[''./client''] 直指裸 tsdown cjs 产物）。蓝本自身缺 __ModuleLoader__ 注册包装层，照搬即继承该 bug。应在改名前对照同目录健康插件（holdings/execution/bulletin 都有 scripts/wrap-client.mjs + exports 指 lib/client.js）确认"正确形态长什么样"，而不是照抄旧包结构。
【错误 B｜最小闭环验证口径错】把"vitest 30/30 + tsdown build OK + smoke host 路由 200"当作改名安全证据。实际这三者都不经过 web shell 的 client 加载路径（浏览器 __ModuleLoader__.load）。host 路由 200 ≠ 侧栏按钮出现。页面插件的验收必须覆盖浏览器端 client 注册成功（无 "failed to import loader entry" + 按钮渲染）。
【错误 C｜自杀式重启 + 28 分钟空窗】见另一条记录（7140bbff）。
【经验 A 正例】部分验证做对了：改名后与 main 对照 smoke 一致（区分既有 console.assert 问题与 rename 引入问题）、软链绝对路径、端口兜底诊断——这些值得保留。

正确修复（另一 agent 完成，main 5cc56d5b）：build:client 追加 wrap 步骤 + exports 改 ./lib/client.js。', 'experience', '{工程,dsh-pmboard,rename,复盘,__ModuleLoader__,RFC014,错误归因}', NULL, '''-08'':4A,15B ''-09'':3A,14B ''/client'':47B ''/lib/client.js'':141B ''200'':27B,79B,92B ''2026'':2A,13B ''28'':107B ''30/30'':72B ''5cc56d5b'':133B ''7140bbff'':110B ''97ee9987'':42B ''a'':34B,112B ''agent'':29B,130B ''b'':68B ''bug'':56B ''build'':74B,134B ''c'':105B ''cjs'':50B ''client'':85B,95B,135B ''console.assert'':121B ''dsh'':6A,17B,39B ''dsh-pmboard'':5A,16B,38B ''entry'':102B ''exports'':44B,46B,61B,139B ''failed'':98B ''holdings/execution/bulletin'':58B ''host'':25B,77B,90B ''import'':100B ''lib/client.js'':63B ''load'':89B ''loader'':101B ''main'':116B,132B ''moduleloader'':53B,88B ''ok'':75B ''pmboard'':7A,18B,40B ''profile'':31B ''rename'':8A,19B,36B,123B ''requirement'':37B ''scripts/wrap-client.mjs'':60B ''shell'':83B ''smoke'':76B,118B ''to'':99B ''tsdown'':49B,73B ''vitest'':71B ''web'':82B ''wrap'':137B ''一致'':119B ''主复盘'':10A,21B ''产物'':51B ''侧栏按钮'':24B ''侧栏按钮出现'':93B ''全链错误归因'':9A,20B ''分钟空窗'':108B ''加载路径'':86B ''区分既有'':120B ''另一'':129B ''在这条工作线的全部错误与归因'':32B ''完成'':131B ''实际这三者都不经过'':81B ''对照'':117B ''工程复盘'':1A,12B ''应在改名前对照同目录健康插件'':57B ''引入问题'':124B ''当作改名安全证据'':80B ''形态'':45B ''把'':70B ''投资'':30B ''指'':62B ''按钮渲染'':103B ''改'':140B ''改名后与'':115B ''无'':97B ''时沿用蓝本'':41B ''最小闭环验证口径错'':69B ''最终'':11A ''最终状态'':22B ''本'':28B ''正例'':113B ''正确修复'':128B ''正确形态长什么样'':65B ''步骤'':138B ''注册包装层'':54B ''注册成功'':96B ''浅改名沿用带病蓝本'':35B ''浏览器'':87B ''照搬即继承该'':55B ''的'':43B,84B ''直指裸'':48B ''确认'':64B ''端口兜底诊断'':126B ''经验'':111B ''而不是照抄旧包结构'':66B ''自杀式重启'':106B ''蓝本自身缺'':52B ''见另一条记录'':109B ''路由'':26B,78B,91B ''软链绝对路径'':125B ''这些值得保留'':127B ''追加'':136B ''部分验证做对了'':114B ''都有'':59B ''错误'':33B,67B,104B ''问题与'':122B ''页面插件的验收必须覆盖浏览器端'':94B ''项目看板已实现'':23B', '2026-09-08 20:40:49.69824', '2026-09-08 20:40:49.69824', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('f826fb93-0be6-4ce7-b482-5d1ec0e28911', '工程记录（2026-09-08 dsh-pmboard M3 看板 GUI 完成）：
【交付】RFC', '工程记录（2026-09-08 dsh-pmboard M3 看板 GUI 完成）：
【交付】RFC 014 M3 看板 GUI，commit d6d91dd2 已推送 origin/main。
- client 数据层 api.ts（fetch 8s 超时 + SSE 订阅）+ types.ts（host 协议投影）
- view.ts 纯渲染：6 列泳道（draft/reviewing/decomposing/implementing/accepting/done）+ 需求卡片（进度条 n/m、分类/阻塞/暂停/ready chip、会话跳转 chip）；归档/取消走底部归档条
- 需求详情：任务 DAG 分层图（拓扑深度 L0/L1/…）、任务六列、人工闸门提示带（reviewing→decomposing→implementing→accepting→done→archived 各态按钮）、评论表单
- 任务详情：属性 kv、执行记录（outcome 着色/证据 code/会话跳转）、评论
- 待归类区：triage 确认（按建议动作 bind_req/create_req）/改绑（select 开放需求）/拒绝
- session-jump.ts：照抄 dsh-taskboard（opened/archived/missing/unavailable 四分，惰性服务解析 + refresh 重试）
- board-mount 重写：page-kit createBoardShell 生命周期（20s 轮询 + SSE 实时 + pauseOnHidden）+ data-action 事件委派
- styles：dsh-pm- 前缀全套，激活隐藏规则对齐 taskboard（html[data-dsh-pm-active] 隐藏中心列其他子元素）

【验证】vitest 52/52（reqboard 30 + client-view 22）；tsdown+wrap-client 产物含 __ModuleLoader__ 注册头；smoke 与 main 对照一致；host 路由 200。

【待人工验收】GUI 侧栏「项目看板」→ 打开看板 → 泳道/详情/DAG/待归类/会话跳转（RFC 014 M3 验收项）。当前 :13080 实例 20:36 启动早于 M3 commit（21:20），需重启加载新 client bundle。', 'experience', '{工程,dsh-pmboard,M3,看板GUI,RFC014,泳道,DAG,待归类,会话跳转}', NULL, '''-08'':4A,17B ''-09'':3A,16B ''/dag'':171B ''/ready'':57B ''014'':27B,175B ''13080'':179B ''20'':181B,187B ''200'':163B ''2026'':2A,15B ''20s'':118B ''21'':186B ''22'':149B ''30'':145B ''36'':182B ''52/52'':143B ''6'':48B ''8s'':39B ''accepting'':74B ''action'':125B ''active'':139B ''api.ts'':37B ''archived'':76B ''bind'':93B ''board'':110B ''board-mount'':109B ''bundle'':190B ''chip'':58B,60B ''client'':35B,147B,153B,189B ''client-view'':146B ''code'':86B ''commit'':31B,185B ''createboardshell'':116B ''d6d91dd2'':32B ''dag'':65B ''data'':124B,136B ''data-action'':123B ''data-dsh-pm-active'':135B ''decomposing'':72B ''done'':75B ''draft/reviewing/decomposing/implementing/accepting/done'':50B ''dsh'':6A,19B,102B,129B,137B ''dsh-pm'':128B ''dsh-pmboard'':5A,18B ''dsh-taskboard'':101B ''fetch'':38B ''gui'':10A,23B,30B,165B ''host'':44B,161B ''html'':134B ''implementing'':73B ''kit'':115B ''kv'':81B ''l0/l1'':68B ''m3'':8A,21B,28B,176B,184B ''main'':159B ''moduleloader'':155B ''mount'':111B ''n/m'':53B ''opened/archived/missing/unavailable'':104B ''origin/main'':34B ''outcome'':83B ''page'':114B ''page-kit'':113B ''pauseonhidden'':122B ''pm'':130B,138B ''pmboard'':7A,20B ''refresh'':107B ''req/create_req'':94B ''reqboard'':144B ''reviewing'':71B ''rfc'':13A,26B,174B ''select'':96B ''session-jump.ts'':99B ''smoke'':157B ''sse'':41B,120B ''styles'':127B ''taskboard'':103B,133B ''triage'':90B ''tsdown'':150B ''types.ts'':43B ''view'':148B ''view.ts'':46B ''vitest'':142B ''wrap'':152B ''wrap-client'':151B ''与'':158B ''事件委派'':126B ''交付'':12A,25B ''产物含'':154B ''人工闸门提示带'':70B ''任务'':64B ''任务六列'':69B ''任务详情'':79B ''会话跳转'':59B,87B,173B ''侧栏'':166B ''分层图'':66B ''分类'':54B ''列泳道'':49B ''前缀全套'':131B ''协议投影'':45B ''取消走底部归档条'':62B ''各态按钮'':77B ''启动早于'':183B ''四分'':105B ''完成'':11A,24B ''