INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('7d689e86-0977-4b31-9226-dd03f2be8b6d', 'quantsys-v2 P1-2（E-201）与 P1-3（E-203）完成（2026-09-09，', 'quantsys-v2 P1-2（E-201）与 P1-3（E-203）完成（2026-09-09，w-5b8aac2a）：
