INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('835ee84d-a48d-4b51-b9ca-f2195e745385', 'reminder evolution-distill-daily delivered', '{"task":"evolution-distill-daily","task_id":"0b61dbe3-704f-4377-ae86-36b848c0f5a4","prompt":"【技能指引】本任务属 engine-heal-evolve 覆盖场景（决策系统自进化流水线）：执行前先调用 skill 工具（name=engine-heal-evolve）加载 SOP，按其流程纪律完成（信号源/对象健康核验→取证→单主题修补→验证→汇报）。本 prompt 的具体动作要求为任务主体，skill 提供流程纪律与禁止清单，二者冲突时以本 prompt 为准。\n【每日蒸馏 16:00】执行 daily_distill 工具（days=7, auto_apply=false，预览模式生成改进提案，不直接应用）。若提案数>0：将关键提案写入 memory（namespace=decision，importance=0.6）备查；汇总报告：模式数、建议数、最值得关注的模式（如某类操作成功率过低）。注意：auto_apply 保持 false，进化走 candidate→验证门流程，不要直接改正式基因组。\n\n【汇报要求】完成后必须飞书简报（channel=reports, urgency=normal）：任务名+关键结果摘要（1-3行）；发现异常则 urgency=high 发 alerts 群。（简报内容：模式数、建议数、最值得关注的模式）","window":"w-a8a89c6a","fired_at":"2026-09-09T15:00:00Z","delivered":true,"delivered_at":"2026-09-09T15:00:00.026Z","executor":{"mode":"direct","session_id":"session-d5f37773-2172-4bc7-b23c-5ffc3c9cd353"}}', 'data', '{office:delivered,office:reminder:exec,office:reminder:w-d5f37773}', NULL, '''-09'':123B,124B,133B,134B ''-3'':104B ''-4'':148B ''0'':71B ''0.6'':77B ''00'':58B,126B,136B ''00.026'':137B ''00z'':127B ''0b61dbe3'':15B ''0b61dbe3-704f'':14B ''1'':103B ''16'':57B ''2026'':122B,132B ''2172'':147B ''36b848c0f5a4'':20B ''4377'':17B ''5ffc3c9cd353'':152B ''7'':64B ''704f'':16B ''a8a89c6a'':119B ''ae86'':19B ''ae86-36b848c0f5a4'':18B ''alerts'':110B ''apply'':66B,86B ''at'':121B,131B ''auto'':65B,85B ''b23c'':151B ''bc7'':150B ''bc7-b23c-5ffc3c9cd353'':149B ''candidate'':90B ''channel'':97B ''d5f37773'':146B ''daily'':5A,11B,60B ''days'':63B ''decision'':75B ''delivered'':6A,128B,130B ''direct'':141B ''distill'':4A,10B,61B ''engine'':25B,35B ''engine-heal-evolve'':24B,34B ''evolution'':3A,9B ''evolution-distill-daily'':2A,8B ''evolve'':27B,37B ''executor'':139B ''false'':67B,88B ''fired'':120B ''heal'':26B,36B ''high'':108B ''id'