INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('dbcbdfd9-182f-4250-b0b1-434a0cbdfe2e', 'DH 技能库移植（2026-09-10，w-5b8aac2a）：从 agent-ts/skills ', 'DH 技能库移植（2026-09-10，w-5b8aac2a）：从 agent-ts/skills 迁移改造 5 个技能到 DH 体系（agent-dh/skills + ~/.dsh-agent-dh/skills 双写，无软链）：①risk-manager 风险管理 SOP——阈值与交易宪法同源（单股≤20%/行业≤40%/现金≥10%、止损-8/-10/-12%），补 ATR 止损/金字塔加仓/该扛vs该砍判断；②quant-strategy 量化策略 SOP——融入 R-011 信号源健康核验（error/invalid 策略输出不可信），strategy_list→execute→三件套解读；③market-analysis 市场分析 SOP——保留美林时钟 A 股版行业配置，仓位建议一律改走 regime_position_limit（R-006），不自拟仓位表；④stock-screener 选股 SOP——适配 DH screening(criteria JSON 区间数组) 形态（实测无质量分字段），改两步式：筛选名单→逐只 data_fetch_financial/pe_percentile/factor_calculate/stock_intel 验证打分+一票否决；⑤portfolio-review 持仓复盘 SOP——portfolio_analyze 速查→五问复盘清单→调仓裁决，健康阈值替换为宪法口径（TS 旧版 15% 线已废弃）。不移植的：candlestick-analysis（依赖 TS 特有后端形态数据结构）、portfolio（纯查看无 SOP 价值）、portfolio-entry（手动录入用户持仓语义与 DH 自营虚拟仓错位）、evolution（TS 归因进化 vs DH 参数进化机制不同，DH 已有 daily_distill/validation_gate 链）。维护纪律：改 agent-dh/skills 源后必须同步 ~/.dsh-agent-dh/skills 才生效。', 'knowledge', '{skills,技能移植,risk-manager,quant-strategy,market-analysis,stock-screener,portfolio-review,agent-ts迁移}', NULL, '''-006'':88B ''-011'':67B ''-09'':4A,17B ''-10'':5A,18B,53B ''-12'':54B ''-8'':52B ''/.dsh-agent-dh/skills'':36B,161B ''/skills'':13A,26B,35B,159B ''10'':50B ''15'':124B ''20'':46B ''2026'':3A,16B ''40'':48B ''5'':28B ''5b8aac2a'':8A,21B ''a'':81B ''agent'':11A,24B,33B,157B ''agent-dh'':32B,156B ''agent-ts'':10A,23B ''analysis'':77B,129B ''analyze'':117B ''atr'':56B ''candlestick'':128B ''candlestick-analysis'':127B ''criteria'':98B ''daily'':151B ''data'':106B ''dh'':1A,14B,30B,34B,96B,141B,147B,149B,158B ''distill/validation_gate'':152B ''entry'':139B ''error/invalid'':69B ''evolution'':143B ''execute'':73B ''fetch'':107B ''financial/pe_percentile/factor_calculate/stock_intel'':108B ''json'':99B ''limit'':86B ''list'':72B ''manager'':41B ''market'':76B ''m