INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('94f5acae-cdd2-4819-ab56-1697f05f9355', '2026-09-11（周五）投资机会咨询结论（w-5b8aac2a，数据截至 2026-09-09 ', '2026-09-11（周五）投资机会咨询结论（w-5b8aac2a，数据截至 2026-09-09 收盘/09-10 02:49）：裁决=明日无新开仓机会。决定性约束=M4 熔断激活中（60日回撤 -10.09%，9/9 18:49 核验，阈值 -8%，R-007 强制减仓一半+禁新开仓直到回撤修复至 >=-8%）；regime=euphoria 但 data_quality=degraded。市场面佐证：情绪 65 偏贪婪但量能萎缩（vol_ratio 0.56-0.76）、涨跌家数 1:1 分歧、涨停 48 家最高 5 板（集中在农化/农产品加工/一般零售/通信设备等低价题材，无强主线）、散户恐慌指数 48.3 但散户资金净流出 45.9 亿。持仓 2 只（伊利 -1.1%、英科 +0.6%）均未触止损。待办：若明日回撤未修复，9:30-11:30 执行熔断减仓一半（权益 27.8%→约13.9%）。', 'knowledge', '{2026-09-11,熔断,机会扫描,circuit_breaker,无新开仓}', NULL, '''+0.6'':86B ''-0.76'':60B ''-007'':43B ''-09'':2A,11A,12A,14B,23B,24B ''-1.1'':84B ''-10.09'':35B ''-11'':3A,15B,92B ''-8'':41B,46B ''/09-10'':26B ''0.56'':59B ''02'':27B ''1'':62B,63B ''18'':37B ''2'':81B ''2026'':1A,10A,13B,22B ''27.8'':96B ''30'':91B,93B ''45.9'':78B ''48'':66B ''48.3'':76B ''49'':28B,38B ''5'':68B ''5b8aac2a'':8A,20B ''60日回撤'':34B ''65'':55B ''9'':90B ''9/9'':36B ''data'':50B ''degraded'':52B ''euphoria'':48B ''m4'':32B ''quality'':51B ''r'':42B ''ratio'':58B ''regime'':47B ''vol'':57B ''w'':7A,19B ''w-5b8aac2a'':6A,18B ''一般零售'':72B ''亿'':79B ''伊利'':83B ''但'':49B ''但散户资金净流出'':77B ''偏贪婪但量能萎缩'':56B ''农产品加工'':71B ''决定性约束'':31B ''分歧'':64B ''只'':82B ''周五'':4A,16B ''均未触止损'':87B ''家最高'':67B ''市场面佐证'':53B ''强制减仓一半'':44B ''待办'':88B ''情绪'':54B ''执行熔断减仓一半'':94B ''投资机会咨询结论'':5A,17B ''持仓'':80B ''收盘'':25B ''散户恐慌指数'':75B ''数据截至'':9A,21B ''无强主线'':74B ''明日无新开仓机会'':30B ''权益'':95B ''板'':69B ''核验'':39B ''涨停'':65B ''涨跌家数'':61B ''熔断激活中'':33B ''禁新开仓直到回撤修复至'':45B ''约13.9'':97B ''若明日回撤未修复'':89B ''英科'':85B ''裁决'':29B ''通信设备等低价题材'':73B ''阈值'':40B ''集中在农化'':70B', '2026-09-10 02:50:57.602733', '2026-09-10 02:50:57.602733', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('d2dcdfd8-ffe1-475b-94b4-e71e6101fc2c', 'reminder agent-brain-realtime-check delivered', '{"task":"agent-brain-realtime-check","task_id":"974fa7b6-ce78-451b-a3da-c1cb314f6180","prompt":"你是 investor（PI 投资顾问·投资脑）。本任务是账户 agent_brain 的专属例行，只能作用于该账户。\n硬纪律：①全部账户查询/交易工具必须显式传 account_name=\"agent_brain\"（工具默认 agent_virtual，禁止作用错账户）；\n②交易宪法：仅 9:30-11:30/13:00-15:00 A股交易日可买卖、T+1（当日买次日卖）、买入 100 股整数倍、单股≤总资产 20%、单行业≤40%、现金≥10%、止损铁律（蓝筹-8%/成长-10%/题材-12%）；\n③买入前 regime_position_limit（R-006 档位映射，degraded 收紧到震荡档）+ risk_controller 算仓位；④信号 R-009 A/B/C 分级，C 级只观察不下单；\n⑤决策前 memory_search(namespace=experience) 检索历史教训（R-008）并在 reason 注明；⑥引用数据必须标注来源工具+数据时点（R-013，db 缓存不得冒充实时价）；\n⑦无信号/无动作时空仓等待是正确决策（宪法 6），不强求交易。\n\n【本任务】agent_brain 盘中快速检查（交易时段内）：\n1) market_alert(level=high) 看新告警；regime_position_limit 复核仓位余量（快速，异常才深查）。\n2) position_list + portfolio_analyze(account_name=\"agent_brain\")：逐只盈亏与止损/止盈距离；触发止损线的按宪法立即卖出（止损不手软、不补仓）；触发止盈预案的按预案执行或说明理由。\n3) 出现 A/B 级买入信号（≥2 维共振+基本面无雷+符合仓位余量）才可建仓，C 级或矛盾只记录观察（signal_track record），不委托。\n4) 仅做必要处置不刷屏；常规检查无动作时静默结束（正确决策），每次执行结束若有交易写 decision_audit(record, reason 引规则ID)。\n【汇报要求】仅当有实际交易/新告警/异常时 feishu_notify(channel=alerts, urgency=high) 标题【agent_brain 盘中处置】；常规无异常不发通知避免打扰。","window":"w-a8a89c6a","fired_at":"2026-09-10T01:00:00Z","delivered":true,"delivered_at":"2026-09-10T01:00:00.230Z","executor":{"mode":"direct","session_id":"session-706fa9da-5eba-4224-9a90-eb30747bba7c"}}', 'data', '{office:delivered,office:reminder:exec,office:reminder:w-706fa9da}', NULL, '''+1'':56B ''-006'':81B ''-008'':103B ''-009'':90B ''-013'':110B ''-09'':201B,211B ''-10'':72B,202B,212B ''-11'':49B ''-12'':74B ''-15'':52B ''-8'':70B ''-9'':227B ''00'':51B,53B,204B,214B ''00.230'':215B ''00z'':205B ''10'':67B ''100'':59B ''2'':157B ''20'':63B ''2026'':200B,210B ''30'':48B ''30/13'':50B ''40'':65B ''4224'':226B ''451b'':19B ''5eba'':225B ''6'':117B ''706fa9da''