INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('cb12fefc-96c5-48dd-b72d-e30fbc47f21b', '修复：/api/stock/{symbol}/quote?source=db 一律 404（REQ-', '修复：/api/stock/{symbol}/quote?source=db 一律 404（REQ-b7f4de，commit 66436e01）。根因：stock_async.py::_get_db_quote 按 dict 消费 get_latest_daily_kline() 返回值，实际返回 polars DataFrame（单行），`if latest and latest.get(...)` 布尔判断抛 "truth value of a DataFrame is ambiguous"（polars 提示用 is_empty()），异常被吞 → db 源一律 404「无法从数据库获取」。同函数第二处错位：get_by_symbol() 返回 ORM Stock 对象（非 dict），stock.get(''name'') 抛 ''Stock'' has no attribute ''get''。同根因残留：signals_async.backtest_signal `latest[''close''] if latest else 0` 对 DataFrame 布尔判断+Series 非标量，DB 有 K 线的标的必 500。教训：repository 层方法返回契约（polars DataFrame/ORM 对象）必须逐一核对调用方消费方式；DataFrame 判空用 is_empty()、取值用 to_dicts()[0]；ORM 对象用 hasattr(name) 兼容两种形态。修复后验证：002470/600519/600865 source=db 均 200，999999（真无缓存）正确 404，backtest-signal 200。', 'knowledge', '{REQ-b7f4de,bugfix,quote,polars,契约对齐,002470}', NULL, '''/api/stock'':2A,11B ''/quote'':4A,13B ''0'':87B,112B ''002470/600519/600865'':119B ''200'':123B,131B ''404'':8A,17B,59B,127B ''500'':97B ''66436e01'':22B ''999999'':124B ''a'':48B ''ambiguous'':51B ''and'':42B ''attribute'':77B ''b7f4de'':20B ''backtest'':129B ''backtest-signal'':128B ''by'':63B ''close'':83B ''commit'':21B ''daily'':33B ''dataframe'':38B,49B,89B,105B ''dataframe/orm'':102B ''db'':6A,15B,26B,57B,93B,121B ''dict'':29B,70B ''dicts'':111B ''else'':86B ''empty'':55B,108B ''get'':25B,31B,62B,78B ''has'':75B ''hasattr'':115B ''if'':40B,84B ''is'':50B,54B,107B ''k'':95B ''kline'':34B ''latest'':32B,41B,82B,85B ''latest.get'':43B ''name'':72B,116B ''no'':76B ''of'':47B ''orm'':66B,113B ''polars'':37B,52B,101B ''quote'':27B ''repository'':99B ''req'':9A,19B ''req-b7f4de'':18B ''series'':91B ''signal'':81B,130B ''signals_async.backtest'':80B ''source'':5A,14B,120B ''stock'':67B,74B ''stock.get'':71B ''stock_async.py'':24B ''symbol'':3A,12B,64B ''to'':110B ''truth'':45B ''value'':46B ''一律'':7A,16B ''修复'':1A,10B ''修复后验证'':118B ''兼容两种形态'':117B ''判空用'':106B ''单行'':39B ''取值用'':109B ''同函数第二处错位'':61B ''同根因残留'':79B ''均'':122B ''实际返回'':36B ''对'':88B ''对象'':68B,103B ''对象用'':114B ''层方法返回契约'':100B ''布尔判断'':90B ''布尔判断抛'':44B ''异常被吞'':56B ''必须逐一核对调用方消费方式'':104B ''抛'':73B ''按'':28B ''提示用'':53B ''教训'':98B ''无法从数据库获取'':60B ''有'':94B ''根因'':23B ''正确'':126B ''消费'':30B ''源一律'':58B ''真无缓存'':125B ''线的标的必'':96B ''返回'':65B ''返回值'':35B ''非'':69B ''非标量'':92B', '2026-09-10 03:02:37.910244', '2026-09-10 03:02:37.910244', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('69059a7d-8770-4bbf-9a6a-9ca05c243504', '2026-09-10 盘前市场观察（w-5b8aac2a）：①熔断仍激活（60日回撤 -10.09%', '2026-09-10 盘前市场观察（w-5b8aac2a）：①熔断仍激活（60日回撤 -10.09%，m4_circuit_breaker_check 2026-09-09 19:07）→ 禁止新开仓，今日无可执行买入机会；②情绪 65 贪婪但数据降级面广：北向不可用（交易所停止披露）、板块资金 fund_flow 源不可用、龙虎榜未接入、风格检测无主导（分化<0.3pp）；③涨停池 09-09 共 48 家情绪平稳、最高 5 连板（百大集团 600865 5板@15.11），农化链（金正大 002470 3板@2.78、泸天化、中粮科技 2板）+ 零售链（百大、中百集团 3板）是游资主导的连板主线，封单厚度一般；④散户端：恐慌指数 48.3 偏贪婪、散户资金净流出 45.9 亿、量能萎缩（vol_ratio 0.56）——存量博弈特征，连板题材追高风险高；⑤持仓 600887 伊利（-1.11% review）+ 300677 英科医疗（+0.56% hold）无触发止损，熔断下维持。等待信号：熔断解除（回撤 ≥-8%）+ 数据源恢复 + 主线风格明确后才有可执行机会。纪律：不追连板高位，等待量能企稳。', 'knowledge', '{2026-09-10,盘前,市场观察,熔断,涨停池,农化链}', NULL, '''+0.56'':93B ''-09'':2A,12B,26B,27B,48B ''-1.11'':89B ''-10'':3A,13B ''-10.09'':10A,20B ''-8'':100B ''0.3'':44B ''0.56'':83B ''002470'':61B ''07'':29B ''09'':47B ''15.11'':58B ''19'':28B ''2.78'':63B ''2026'':1A,11B,25B ''2板'':66B ''300677'':91B ''3板'':62B,70B ''45.9'':78B ''48'':50B ''48.3'':75B ''5'':53B ''5b8aac2a'':7A,17B ''5板'':57B ''600865'':56B ''600887'':87B ''60日回撤'':9A,19B ''65'':33B ''breaker'':23B ''check'':24B ''circuit'':22B ''flow'':39B ''fund'':38B ''hold'':94B ''m4'':21B ''pp'':45B ''ratio'':82B ''review'':90B ''vol'':81B ''w'':6A,16B ''w-5b8aac2a'':5A,15B ''不追连板高位'':104B ''中百集团'':69B ''中粮科技'':65B ''主线风格明确后才有可执行机会'':102B ''交易所停止披露'':36B ''亿'':79B ''今日无可执行买入机会'':31B ''伊利'':88B ''偏贪婪'':76B ''共'':49B ''农化链'':59B ''分化'':43B ''北向不可用'':35B ''回撤'':99B ''存量博弈特征'':84B ''家情绪平稳'':51B ''封单厚度一般'':72B ''恐慌指数'':74B ''情绪'':32B ''持仓'':86B ''散户端'':73B ''散户资金净流出'':77B ''数据源恢复'':101B ''无触发止损'':95B ''是游资主导的连板主线'':71B ''最高'':52B ''板块资金'':37B ''泸天化'':64B ''涨停池'':46B ''源不可用'':40B ''熔断下维持'':96B ''熔断仍激活'':8A,18B ''熔断解除'':98B ''百大'':68B ''百大集团'':55B ''盘前市场观察'':4A,14B ''禁止新开仓'':30B ''等待信号'':97B ''等待量能企稳'':105B ''纪律'':103B ''英科医疗'':92B ''贪婪但数据降级面广'':34B ''连板'':54B ''连板题材追高风险高'':85B ''量能萎缩'':80B ''