INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('5fa53c05-8c3c-4abc-bd14-b1d1c77c1e96', '2026-09-10 fund_flow 板块资金流修复（w-5b8aac2a）：根因=后端 /ap', '2026-09-10 fund_flow 板块资金流修复（w-5b8aac2a）：根因=后端 /api/market/sector-flow 返回 {success,data:{data_type,data:{records:[90条]}}} 三层嵌套，FundFlowTool.extractRows 只识别 d.data 数组/d.records 数组，漏 d.data.data.records → 空 → 误报「数据源暂不可用」。后端 curl 200 正常，纯工具解析层错位（与 quote db 404 同病）。修复：extractRows 增加嵌套 records 识别 + 板块 render 显示涨跌幅/净额/领涨股。契约测试 6/6（真实响应形状）。经验：数据源「不可用」报错先 curl 直连后端验证——工具层误报 vs 真源失效要区分；后端返回结构变更/复杂嵌套时，工具 extract 层必须与真实响应对齐并落契约测试。profile node_modules 中 file: 依赖可能是实体拷贝而非软链，agent-dh 改码后需同步 profile 副本 + 重启 DSH 才生效。', 'experience', '{fund_flow,板块资金流,契约错位,2026-09-10,工具修复}', NULL, '''-09'':2A,14B ''-10'':3A,15B ''/ap'':12A ''/api/market/sector-flow'':24B ''/d.records'':38B ''200'':47B ''2026'':1A,13B ''404'':53B ''5b8aac2a'':9A,21B ''6/6'':66B ''90条'':32B ''agent'':89B ''agent-dh'':88B ''curl'':46B,72B ''d.data'':36B ''d.data.data.records'':41B ''data'':27B,28B,30B ''db'':52B ''dh'':90B ''dsh'':95B ''extract'':80B ''extractrows'':56B ''file'':86B ''flow'':5A,17B ''fund'':4A,16B ''fundflowtool.extractrows'':34B ''modules'':84B ''node'':83B ''profile'':82B,92B ''quote'':51B ''records'':31B,58B ''render'':61B ''success'':26B ''type'':29B ''vs'':75B ''w'':8A,20B ''w-5b8aac2a'':7A,19B ''三层嵌套'':33B ''不可用'':70B ''与'':50B ''中'':85B ''依赖可能是实体拷贝而非软链'':87B ''修复'':55B ''净额'':63B ''副本'':93B ''只识别'':35B ''同病'':54B ''后端'':11A,23B,45B ''后端返回结构变更'':77B ''增加嵌套'':57B ''复杂嵌套时'':78B ''契约测试'':65B ''层必须与真实响应对齐并落契约测试'':81B ''工具'':79B ''工具层误报'':74B ''才生效'':96B ''报错先'':71B ''改码后需同步'':91B ''数据源'':69B ''数据源暂不可用'':44B ''数组'':37B,39B ''显示涨跌幅'':62B ''板块'':60B ''板块资金流修复'':6A,18B ''根因'':10A,22B ''正常'':48B ''漏'':40B ''直连后端验证'':73B ''真实响应形状'':67B ''真源失效要区分'':76B ''空'':42B ''纯工具解析层错位'':49B ''经验'':68B ''识别'':59B ''误报'':43B ''返回'':25B ''重启'':94B ''领涨股'':64B', '2026-09-10 03:18:40.783382', '2026-09-10 03:18:40.783382', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('0a97093d-7af1-49b5-8f6a-d3016e3c6c2b', 'reminder v2:pre_market_summary delivered', '{"task":"v2:pre_market_summary","task_id":"wake-pre_market_summary","prompt":"【v2 事件·pre_market_summary】由 quantsys-v2 后端唤醒推送（不是定时任务，是事件驱动）。\n事件数据（JSON）：\nv2_event_json: {\"date\":\"2026-09-10\",\"market_style\":{\"action\":\"market_style_update\",\"status\":\"success\",\"current_style\":\"unknown\",\"confidence\":0,\"style_changes\":[],\"timestamp\":\"2026-09-10T08:30:00.493595\"},\"signals_generated\":0}\n\n处理要求：理解事件内容并采取相应动作（如 watch 触发的 AI 分析版=分析该股信号并组织飞书通知；daily_report=做当日复盘；agent_reminder=执行对应提醒任务）。遵守交易宪法；完成后把结论写入 memory（namespace=decision）。","fired_at":"2026-09-10T08:30:00.635986","delivered":true,"delivered_at":"2026-09-10T00:30:00.658Z","executor":{"mode":"direct","session_id":"session-706fa9da-5eba-4224-9a90-eb30747bba7c"}}', 'data', '{office:delivered,office:reminder:exec,office:reminder:w-706fa9da}', NULL, '''-09'':39B,58B,89B,99B ''-10'':40B,59B,90B,100B ''-9'':115B ''0'':53B,65B ''00.493595'':62B ''00.635986'':93B ''00.658'':103B ''2026'':38B,57B,88B,98B ''30'':61B,92B,102B ''4224'':114B ''5eba'':113B ''706fa9da'':112B ''a90'':117B ''a90-eb30747bba7c'':116B ''action'':43B ''agent'':78B ''ai'':72B ''at'':87B,97B ''changes'':55B ''confidence'':52B ''current'':49B ''daily'':75B ''date'':37B ''decision'':85B ''delivered'':6A,94B,96B ''direct'':107B ''eb30747bba7c'':118B ''event'':35B ''executor'':105B ''fired'':86B ''generated'':64B ''id'':13B,109B ''json'':33B,36B ''market'':4A,10B,17B,23B,41B,44B ''memory'':83B ''mode'':106B ''n'':66B ''namespace'':84B ''nv2'':34B ''n事件数据'':32B ''n处理要求'':67B ''pre'':3A,9B,16B,22B ''prompt'':19B ''quantsys'':27B ''quantsys-v2'':26B ''reminder'':1A,79B ''report'':76B ''session'':108B,111B ''session-706fa9da-5eba'':110B ''signals'':63B ''status'':47B ''style'':42B,45B,50B,54B ''success'':48B ''summary'':5A,11B,18B,24B ''t00'':101B ''t08'':60B,91B ''task'':7B,12B ''timestamp'':56B ''true'':95B ''unknown'':51B ''update'':46B ''v2'':2A,8B,20B,28B ''wake'':15B ''wake-pre'':14B ''watch'':70B ''z'':104B ''不是定时任务'':30B ''事件'':21B ''做当日复盘'':77B ''分析版'':73B ''分析该股信号并组织飞书通知'':74B ''后端唤醒推送'':29B ''如'':69B ''完成后把结论写入'':82B ''执行对应提醒任务'':80B ''是事件驱动'':31B ''理解事件内容并采取相应动作'':68B ''由'':25B ''触发的'':71B ''遵守交易宪法'':81B', '2026-09-10 08:30:00.664966', '2026-09-10 08:30:00.664966', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('4350865c-094b-4d0d-b8fb-38fa188be46e', 'reminder agent-brain-morning-analysis delivered', '{"task":"agent-brain-morning-analysis","task_id":"3cd18227-03e3-4da4-b66a-1d58b9b7e68f","prompt":"你是 investor（PI 投资顾问·投资脑）。本任务是账户 agent_brain 的专属例行，只能作用于该账户。\n硬纪律：①全部账户查询/交易工具必须显式传 account_name=\"agent_brain\"（工具默认 agent_virtual，禁止作用错账户）；\n②交易宪法：仅 9:30-11:30/13:00-15:00 A股交易日可买卖、T+1（当日买次日卖）、买入 100 股整数倍、单股≤总资产 20%、单行业≤40%、现金≥10%、止损铁律（蓝筹-8%/成长-10%/题材-12%）；\n③买入前 regime_position_limit（R-006 档位映射，degraded 收紧到震荡档）+ risk_controller 算仓位；④信号 R-009 A/B/C 分级，C 级只观察不下单；\n⑤决策前 memory_search(namespace=experience) 检索历史教训（R-008）并在 reason 注明；⑥引用数据必须标注来源工具+数据时点（R-013，db 缓存不得冒充实时价）；\n⑦无信号/无动作时空仓等待是正确决策（宪法 6），不强求交易。\n\n【本任务】agent_brain 盘前晨间分析（09:00 开盘前完成）：\n1) regime_position_limit(account_name=\"agent_brain\")：记录 regime/权益仓位上限/余量/compliant 判定；circuit_breaker 触发立即 feishu_notify(alerts, high)。\n2) event_calendar_check(upcoming, days=2) 未来事件 + market_alert(high) 评估对持仓影响。\n3) account_info + position_list(account_name=\"agent_brain\") 核对总资产/现金/持仓；portfolio_analyze 找已触止损/止盈线的持仓，列入今日处置预案（实际执行须在交易时段）。\n4) sector_analysis/mainline_scan 简要扫描今日主线（控制在 2-3 工具）。\n任务完成后 feishu_notify 主动汇报（标题见下），内容含：核心数据（标注来源工具+时点）、决策动作、下一步；urgency/channel 按说明。一般性留痕写 memory_write(namespace=decision/analysis)，交易决策另 decision_audit(record)。\n【汇报要求】feishu_notify(channel=reports, urgency=normal) 标题【agent_brain 晨间简报】，内容：regime 与权益上限、持仓健康（止损距离）、今日事件/告警要点、计划动作。","window":"w-a8a89c6a","fired_at":"2026-09-10T01:00:00Z","delivered":true,"delivered_at":"2026-09-10T01:00:00.240Z","executor":{"mode":"direct","session_id":"session-706fa9da-5eba-4224-9a90-eb30747bba7c"}}', 'data', '{office:delivered,office:reminder:exec,office:reminder:w-706fa9da}', NULL, '''+1'':56B ''-006'':81B ''-008'':103B ''-009'':90B ''-013'':110B ''-09'':236B,246B ''-10'':72B,237B,247B ''-11'':49B ''-12'':74B ''-15'':52B ''-3'':185B ''-8'