INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('5fd25c66-7366-4eb2-8116-ebb269ab4cb1', 'reminder pre-market-routine delivered', '{"task":"pre-market-routine","task_id":"7cdbe487-6358-4d95-9292-ef269f341bb2","prompt":"【盘前例程 9:25】①用 position_list 确认持仓与可卖数量 ②用 data_fetch_quote(realtime) 获取持仓股票集合竞价情况 ③用 regime_position_limit 确认今日仓位上限与余量 ④用 market_alert(level=high) 查看系统告警 ⑤用 data_fetch_market_sentiment 判断市场情绪 ⑥检索昨日盘中扫描(10:15/13:45)写的次日预案：memory_search(query=\"盘中扫描 次日预案 触发价位\", namespace=analysis, top_k=5)——若有 A/B 级候选及触发价位，列为今日观察重点并核对竞价是否触及 ⑦检查观察清单（若有前日记录的重点关注标的，拉行情）⑧向用户飞书推送早盘要点（持仓状态+市场情绪+昨日预案候选触发情况+当日观察重点+风险提示）。","window":"w-5b8aac2a","fired_at":"2026-09-10T01:25:00Z","delivered":true,"delivered_at":"2026-09-10T01:25:00.052Z","executor":{"mode":"direct","session_id":"session-706fa9da-5eba-4224-9a90-eb30747bba7c"}}', 'data', '{office:delivered,office:reminder:exec,office:reminder:w-706fa9da}', NULL, '''-09'':87B,97B ''-10'':88B,98B ''-4'':16B ''-6358'':15B ''-9'':113B ''-9292'':18B ''00.052'':101B ''00z'':91B ''10'':52B ''15/13'':53B ''2026'':86B,96B ''25'':23B,90B,100B ''4224'':112B ''45'':54B ''5'':66B ''5b8aac2a'':83B ''5eba'':111B ''706fa9da'':110B ''7cdbe487'':14B ''9'':22B ''a/b'':68B ''a90'':115B ''a90-eb30747bba7c'':114B ''alert'':41B ''analysis'':63B ''at'':85B,95B ''d95'':17B ''data'':29B,46B ''delivered'':6A,92B,94B ''direct'':105B ''eb30747bba7c'':116B ''ef269f341bb2'':19B ''executor'':103B ''fetch'':30B,47B ''fired'':84B ''high'':43B ''id'':13B,107B ''k'':65B ''level'':42B ''limit'':37B ''list'':26B ''market'':4A,10B,40B,48B ''memory'':56B ''mode'':104B ''namespace'':62B ''position'':25B,36B ''pre'':3A,9B ''pre-market-routine'':2A,8B ''prompt'':20B ''query'':58B ''quote'':31B ''realtime'':32B ''regime'':35B ''reminder'':1A ''routine'':5A,11B ''search'':57B ''sentiment'':49B ''session'':106B,109B ''session-706fa9da-5eba'':108B ''t01'':89B,99B ''task'':7B,12B ''top'':64B ''true