INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('a79969b6-c94d-46e9-a010-b5f3c317fbcb', 'REQ-6018bd 持仓看板名称列修复（w-32b8195a）：根因=holdings host ', 'REQ-6018bd 持仓看板名称列修复（w-32b8195a）：根因=holdings host 调已弃用 /api/portfolio/positions（DB快照 name恒空）+ 两份硬编码静态字典兜底（28只/60只）追不上动态新持仓 → 新买入标的名称列恒显示裸代码。修复=改调 /api/simulation/accounts/{account}（真名+实时价）+ 交易记录经 /api/stocks/search 补名 + client displayName 优先真名。教训：页面插件与 quantsys-v2-client 对同一后端端点的迁移要同步——client 8/31 已弃用旧端点，页面插件滞后 10 天。dashboard-holdings 部署目录已改软链到仓库（旧目录备份 dashboard-holdings.bak-20260910）。', 'knowledge', '{REQ-6018bd,dashboard-holdings,名称列,端点迁移}', NULL, '''-20260910'':61B ''/api/portfolio/positions'':22B ''/api/simulation/accounts'':32B ''/api/stocks/search'':37B ''10'':53B ''28只/60'':26B ''32b8195a'':7A,17B ''6018bd'':3A,13B ''8/31'':50B ''account'':33B ''client'':39B,47B,49B ''dashboard'':56B ''dashboard-holdings'':55B ''dashboard-holdings.bak'':60B ''db快照'':23B ''displayname'':40B ''holdings'':9A,19B,57B ''host'':10A,20B ''name恒空'':24B ''quantsys'':45B ''quantsys-v2-client'':44B ''req'':2A,12B ''req-6018bd'':1A,11B ''v2'':46B ''w'':6A,16B ''w-32b8195a'':5A,15B ''两份硬编码静态字典兜底'':25B ''交易记录经'':36B ''优先真名'':41B ''修复'':30B ''只'':27B ''天'':54B ''实时价'':35B ''对同一后端端点的迁移要同步'':48B ''已弃用旧端点'':51B ''持仓看板名称列修复'':4A,14B ''改调'':31B ''教训'':42B ''新买入标的名称列恒显示裸代码'':29B ''旧目录备份'':59B ''根因'':8A,18B ''真名'':34B ''补名'':38B ''调已弃用'':21B ''追不上动态新持仓'':28B ''部署目录已改软链到仓库'':58B ''页面插件与'':43B ''页面插件滞后'':52B', '2026-09-10 10:48:29.936309', '2026-09-10 10:48:29.936309', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('b4cd51d2-0a41-4b33-ae8b-52efc756b79e', 'reminder agent-brain-realtime-check delivered', '{"task":"agent-brain-realtime-check","task_id":"974fa7b6-ce78-451b-a3da-c1cb314f6180","prompt":"你是 investor（PI 投资顾问·投资脑）。本任务是账户 agent_brain 的专属例行，只能作用于该账户。\n硬纪律：①全部账户查询/交易工具必须显式传 account_name=\"agent_brain\"（工具默认 agent_virtual，禁止作用错账户）；\n②交易宪法：仅 9:30-11:30/13:00-15:00 A股交易日可买卖、T+1（当日买次日卖）、买入 100 股整数倍、单股≤总资产 20%、单行业≤40%、现金≥10%、止损铁律（蓝筹-8%/成长-10%/题材-12%）；\n③买入前 regime_position_limit（R-006 档位映射，degraded 收紧到震荡档）+ risk_controller 算仓位；④信号 R-009 A/B/C 分级，C 级只观察不下单；\n⑤决策前 memory_search(namespace=experience) 检索历史教训（R-008）并在 reason 注明；⑥引用数据必须标注来源工具+数据时点（R-013，db 缓存不得冒充实时价）；\n⑦无信号/无动作时空仓等待是正确决策（宪法 6），不强求交易。\n\n【本任务】agent_brain 盘中快速检查（交易时段内）：\n1) market_alert(level=high) 看新告警；regime_position_limit 复核仓位余量（快速，异常才深查）。\n2) position_list + portfolio_analyze(account_name=\"agent_brain\")：逐只盈亏与止损/止盈距离；触发止损线的按宪法立即卖出（止损不手软、不补仓）；触发止盈预案的按预案执行或说明理由。\n3) 出现 A/B 级买入信号（≥2 维共振+基本面无雷+符合仓位余量）才可建仓，C 级或矛盾只记录观察（signal_track record），不委托。\n4) 仅做必要处置不刷屏；常规检查无动作时静默结束（正确决策），每次执行结束若有交易写 decision_audit(record, reason 引规则ID)。\n【汇报要求】仅当有实际交易/新告警/异常时 feishu_notify(channel=alerts, urgency=high) 标题【agent_brain 盘中处置】；常规无异常不发通知避免打扰。","window":"w-a8a89c6a","fired_at":"2026-09-10T04:00:00Z","delivered":true,"delivered_at":"2026-09-10T04:00:00.049Z","executor":{"mode":"direct","session_id":"session-706fa9da-5eba-4224-9a90-eb30747bba7c"}}', 'data', '{office:delivered,office:reminder:exec,office:reminder:w-706fa9da}', NULL, '''+1'':56B ''-006'':81B ''-008'':103B ''-009'':90B ''-013'':110B ''-09'':201B,211B ''-10'':72B,202B,212B ''-11'':49B ''-12'':74B ''-15'':52B ''-8'':70B ''-9'':227B ''00'':51B,53B,204B,214B ''00.049'':215B ''00z'':205B ''10'':67B ''100'':59B ''2'':157B ''20'':63B ''2026'':200B,210B ''30'':48B ''30/13'':50B ''40'':65B ''4224'':226B ''451b'':19B ''5eba'':225B ''6'':117B ''706fa9da''