INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('9be6f4b6-effa-4f42-9a67-e4d8fb2190f4', 'REQ-6018bd 第二层后端除根（w-32b8195a，commit 79677419）：/ap', 'REQ-6018bd 第二层后端除根（w-32b8195a，commit 79677419）：/api/portfolio/positions 的 name 硬编码空串（orders_async.py）已改为批量 IN 联查 stocks 表补真名；/api/portfolio/positions|summary 加 RFC 8594 Deprecation 头+successor 链接+告警日志（全部消费方已迁至 /api/simulation/accounts/{account}）；/api/simulation/trades 路由层联查填充 name（SimulationTrade.to_dict 无 name 列）；看板 host 交易行已有真名时跳过 search 补名。经验：修假数据陷阱要除根到后端 handler，光修消费方会留定时炸弹。', 'knowledge', '{REQ-6018bd,quantsys-v2,deprecation,名称联查}', NULL, '''/ap'':10A ''/api/portfolio/positions'':20B,30B ''/api/simulation/accounts'':41B ''/api/simulation/trades'':43B ''32b8195a'':7A,17B ''6018bd'':3A,13B ''79677419'':9A,19B ''8594'':34B ''account'':42B ''commit'':8A,18B ''deprecation'':35B ''dict'':47B ''handler'':58B ''host'':52B ''in'':26B ''name'':22B,45B,49B ''orders_async.py'':24B ''req'':2A,12B ''req-6018bd'':1A,11B ''rfc'':33B ''search'':54B ''simulationtrade.to'':46B ''stocks'':28B ''successor'':37B ''summary'':31B ''w'':6A,16B ''w-32b8195a'':5A,15B ''交易行已有真名时跳过'':53B ''修假数据陷阱要除根到后端'':57B ''光修消费方会留定时炸弹'':59B ''全部消费方已迁至'':40B ''列'':50B ''加'':32B ''告警日志'':39B ''头'':36B ''已改为批量'':25B ''无'':48B ''的'':21B ''看板'':51B ''硬编码空串'':23B ''第二层后端除根'':4A,14B ''经验'':56B ''联查'':27B ''补名'':55B ''表补真名'':29B ''路由层联查填充'':44B ''链接'':38B', '2026-09-10 13:51:04.912627', '2026-09-10 13:51:04.912627', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('a8c6507d-5bd1-41c3-a408-af44014307ee', 'reminder agent-brain-realtime-check delivered', '{"task":"agent-brain-realtime-check","task_id":"974fa7b6-ce78-451b-a3da-c1cb314f6180","prompt":"你是 investor（PI 投资顾问·投资脑）。本任务是账户 agent_brain 的专属例行，只能作用于该账户。\n硬纪律：①全部账户查询/交易工具必须显式传 account_name=\"agent_brain\"（工具默认 agent_virtual，禁止作用错账户）；\n②交易宪法：仅 9:30-11:30/13:00-15:00 A股交易日可买卖、T+1（当日买次日卖）、买入 100 股整数倍、单股≤总资产 20%、单行业≤40%、现金≥10%、止损铁律（蓝筹-8%/成长-10%/题材-12%）；\n③买入前 regime_position_limit（R-006 档位映射，degraded 收紧到震荡档）+ risk_controller 算仓位；④信号 R-009 A/B/C 分级，C 级只观察不下单；\n⑤决策前 memory_search(namespace=experience) 检索历史教训（R-008）并在 reason 注明；⑥引用数据必须标注来源工具+数据时点（R-013，db 缓存不得冒充实时价）；\n⑦无信号/无动作时空仓等待是正确决策（宪法 6），不强求交易。\n\n【本任务】agent_brain 盘中快速检查（交易时段内）：\n1) market_alert(level=high) 看新告警；regime_position_limit 复核仓位余量（快速，异常才深查）。\n2) position_list + portfolio_analyze(account_name=\"agent_brain\")：逐只盈亏与止损/止盈距离；触发止损线的按宪法立即卖出（止损不手软、不补仓）；触发止盈预案的按预案执行或说明理由。\n3) 出现 A/B 级买入信号（≥2 维共振+基本面无雷+符合仓位余量）才可建仓，C 级或矛盾只记录观察（signal_track record），不委托。\n4) 仅做必要处置不刷屏；常规检查无动作时静默结束（正确决策），每次执行结束若有交易写 decision_audit(record, reason 引规则ID)。\n【汇报要求】仅当有实际交易/新告警/异常时 feishu_notify(channel=alerts, urgency=high) 标题【agent_brain 盘中处置】；常规无异常不发通知避免打扰。","window":"w-a8a89c6a","fired_at":"2026-09-10T06:00:00Z","delivered":true,"delivered_at":"2026-09-10T06:00:00.047Z","executor":{"mode":"direct","session_id":"session-ac92e536-f709-466d-a5dd-aead9e70f6f7"}}', 'data', '{office:delivered,office:reminder:exec,office:reminder:w-ac92e536}', NULL, '''+1'':56B ''-006'':81B ''-008'':103B ''-009'':90B ''-013'':110B ''-09'':201B,211B ''-10'':72B,202B,212B ''-11'':49B ''-12'':74B ''-15'':52B ''-8'':70B ''00'':51B,53B,204B,214B ''00.047'':215B ''00z'':205B ''10'':67B ''100'':59B ''2'':157B ''20'':63B ''2026'':200B,210B ''30'':48B ''30/13'':50B ''40'':65B ''451b'':19B ''466d'':226B ''6'':117B ''9'':47B ''974fa7b6'':17B ''974fa7b6-