INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('73874981-183c-45cc-8649-893f057a364a', '601600 neutral 突破买入9.93后设置止损：若按9.85止损容错仅0.8%，而中铝日均波动2~3%（日均波幅为经验估计，非精确回测），止损线贴在噪', '601600 交易经验（2026-09-10T12:45:52.367Z）
