INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('be88ee90-275e-449e-bea0-fcc5ff429a21', '2026-09-10 因子批处理 insufficient-data 错误族影响评估（w-8f2c4', '2026-09-10 因子批处理 insufficient-data 错误族影响评估（w-8f2c4cc5）：错误事件 6b8359d4/569a8798/993ea1af（+macd 三件套 e38063ab/06a8190e/b36988f4、atr14/rsi14）同源=因子计算对短K线序列抛 InsufficientDataError → 8 个指标报错。当轮 factor_compute（trace b3ec2235，2026-09-10T12:30:34Z 起）扫描 5525 只标的，仅 42 只触发（141 次指标失败）：39 只 92xxxx 北交所次新（21 根K线<MACD 26）、810014（5根）、810011（12根）、000001（13根）。影响结论：对持仓/盯盘零影响（300677/600887 各 29 因子齐全含 macd/rsi，quant.factor_values 2026-09-10）；因子缺失有优雅降级（丢弃该指标+warning，批处理继续）。真正暴露的问题：①000001 平安银行 quant.daily_klines 有 15 个月空洞（2025-05-30→2026-08-24，近420日仅13根，API 却报 klineDays=500），该股在 pool 35「全市场候选池_v1」内但 MACD/RSI/BOLL/ATR 全缺；②非股票品种（810014/810011 定转）进入因子 universe，过滤只排指数代码；③92xxxx 次新应前置按K线根数过滤而非抛错；④事件指纹=整条消息 SHA1，一处故障裂成 N 条事件（该族 10 事件/170 次），盖住真实告警。', 'knowledge', '{factor_compute,insufficient_data,000001,平安银行,kline_gap,error_events,w-8f2c4cc5}', NULL, '''-05'':94B ''-08'':97B ''-09'':2A,13B,40B,79B ''-10'':3A,14B,41B,80B ''-24'':98B ''-30'':95B ''/170'':129B ''000001'':66B,86B ''10'':127B ''12根'':65B ''13根'':67B ''141'':52B ''15'':91B ''2025'':93B ''2026'':1A,12B,39B,78B,96B ''21'':58B ''26'':61B ''29'':73B ''30'':43B ''300677/600887'':71B ''34z'':44B ''35'':106B ''39'':54B ''42'':50B ''500'':103B ''5525'':47B ''5根'':63B ''6b8359d4/569a8798/993ea1af'':24B ''8'':32B ''810011'':64B ''810014'':62B ''810014/810011'':113B ''8f2c4'':11A ''8f2c4cc5'':22B ''92xxxx'':56B,118B ''api'':100B ''atr14/rsi14'':28B ''b3ec2235'':38B ''compute'':36B ''data'':7A,18B ''e38063ab/06a8190e/b36988f4'':27B ''factor'':35B ''insufficient'':6A,17B ''insufficient-data'':5A,16B ''insufficientdataerror'':31B ''klinedays'':102B ''klines'':89B ''macd'':25B,60B ''macd/rsi'':75B ''macd/rsi/boll/atr'':110B ''n'':124B ''pool'':105B ''quant.daily'':88B ''quant.factor'':76B ''sha1'':122B ''t12'':42B ''trace'':37B