INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('be7fba28-19c8-4f5f-a371-865990e18b99', '2026-09-10 全市场K线静默冻结6个交易日复盘（w-23c70356）：kline_upda', '2026-09-10 全市场K线静默冻结6个交易日复盘（w-23c70356）：kline_update_job.py 的 batch/priority 查询自 2026-09-02 起存在三处独立 SQL 缺陷（daily_klines.updated_at 列不存在；SELECT DISTINCT 配 ORDER BY trade_date 违反 PG 规则；UNION ALL 外层 ORDER BY priority 列不在输出），任何一处都足以让同步失败。叠加两个放大器：①update_gem_klines 的 except 返回 status=error 而不抛，evening_pipeline 照常 return，宿主记 success 并发"✅ 每日任务完成"——故障被成功回执掩盖 5 个交易日；②新鲜度门用全表 max(trade_date)，agent 零星取数把 max 顶到当天即判"全市场新鲜"跳过同步（09-10 实际覆盖率仅 0.87%）。修复：三处 SQL + kline_sync.status==error 时 raise + 按活跃股覆盖率(5290只)判新鲜度。通用教训：链路健康判据必须按"业务对象覆盖率"而非全局 max/min；失败必须上抛，禁止用 success 回执掩盖；同一事实的巡检结论与完成回执不能互相矛盾。', 'experience', '{kline,daily_klines,数据链路,静默失败,freshness_guard,SQL缺陷,2026-09-10}', NULL, '''-02'':23B ''-09'':2A,11B,22B ''-10'':3A,12B,80B ''0.87'':82B ''09'':79B ''2026'':1A,10B,21B ''23c70356'':7A,16B ''5'':67B ''5290只'':91B ''agent'':73B ''all'':41B ''at'':28B ''batch/priority'':19B ''by'':34B,44B ''daily_klines.updated'':27B ''date'':36B,72B ''distinct'':31B ''error'':56B,87B ''evening'':58B ''except'':53B ''gem'':50B ''kline'':8A ''kline_sync.status'':86B ''kline_update_job.py'':17B ''klines'':51B ''max'':70B,75B ''max/min'':97B ''order'':33B,43B ''pg'':38B ''pipeline'':59B ''priority'':45B ''raise'':89B ''return'':61B ''select'':30B ''sql'':25B,85B ''status'':55B ''success'':63B,100B ''trade'':35B,71B ''union'':40B ''upda'':9A ''update'':49B ''w'':6A,15B ''w-23c70356'':5A,14B ''三处'':84B ''业务对象覆盖率'':95B ''个交易日'':68B ''任何一处都足以让同步失败'':47B ''修复'':83B ''全市场k线静默冻结6个交易日复盘'':4A,13B ''全市场新鲜'':77B ''列不在输出'':46B ''列不存在'':29B ''判新鲜度'':92B ''叠加两个放大器'':48B ''同一事实的巡检结论与完成回执不能互相矛盾'':102B ''回执掩盖'':101B ''外层'':42B ''失败必须上抛'':98B ''实际覆盖率仅'':81B ''宿主记'':62B ''并发'':64B ''按活跃股覆盖率'':90B ''故障被成功回执掩盖'':66B ''新鲜度门用全表'':69B ''时'':88B ''查询自'':20B ''每日任务完成'':65B ''照常'':60B ''的'':18B,52B ''