INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('ba95201f-8425-49f6-917b-14bc1d97abaa', '2026-09-10 lifecycle bug 修复验收（w-50fc8c52，commit 57', '2026-09-10 lifecycle bug 修复验收（w-50fc8c52，commit 57b0f00b + 工作日志 2b6f36b3）：self_finalize(exit) 原实现"清 pending 却不回干线"，与 boot-recovery I3"HEAD 在 agent-self/* 且无 pending/pendingDone → 判为崩溃滞留 → checkout 回干线"语义矛盾（同一状态两种相反定义），导致按设计退出被下次启动误判，把只存在于 wip 提交上的文件从磁盘静默抹掉且无人告知（13:31 现场：agent-self/20260910-210017 → main，5 个 execution 看板文件消失）。修复：①exit 退出前归档 wip 独有内容到 wip/rescued-* + 以未提交形态取回工作区 + 回干线 + 收掉已归档的检查点分支（新增 exit-finalize.ts，顺序不可交换：先归档→再 checkout→再回填）②boot I3 切回干线前先 rescueWip 归档并主动向根 agent 播报（announceWipRescue；崩溃路径刻意只归档+告知、不擅自回填工作区）③修正 SelfFinalizeTool 文案。活体验收（2026-09-10 21:51 真实 exit，用户授权）：归档分支 wip/rescued-agent-self-20260910-214727-0910-2151 hash 与检查点 ad2f5159 完全一致、5 个文件以 " M" 形态回到工作区且与归档分支逐文件 diff 为空、HEAD=main、检查点分支已收、boot-recovery-audit.jsonl 无新增（新 boot 的 I3 空动作，这正是修复目标）、新 PID 89353 拉活；os-outbox 有完整 exitFinalize 审计（error=null）。单测 lifecycle 64/64、插件 schema 冒烟 19/19、tsdown --dts 构建通过。', 'knowledge', '{lifecycle,self_finalize,boot-recovery,bug-修复,w-50fc8c52}', NULL, '''-09'':2A,13B,97B ''-10'':3A,14B,98B ''/20260910-210017'':59B ''13'':53B ''19/19'':145B ''2026'':1A,12B,96B ''21'':99B ''2b6f36b3'':24B ''31'':54B ''5'':61B,110B ''50fc8c52'':9A,20B ''51'':100B ''57'':11A ''57b0f00b'':22B ''64/64'':141B ''89353'':129B ''ad2f5159'':108B ''agent'':40B,57B,86B ''agent-self'':39B,56B ''announcewiprescue'':88B ''boot'':34B,81B,122B ''boot-recovery'':33B ''boot-recovery-audit.jsonl'':119B ''bug'':5A,16B ''checkout'':45B,79B ''commit'':10A,21B ''diff'':114B ''dts'':147B ''error'':137B ''execution'':63B ''exit'':27B,66B,102B ''exit-finalize.ts'':75B ''exitfinalize'':135B ''finalize'':26B ''hash'':106B ''head'':37B,116B ''i3'':36B,82B,124B ''lifecycle'':4A,15B,140B ''m'':112B ''main'':60B,117B ''null'':138B ''os'':132B ''os-outbox'':131B ''outbox'':133B ''pending'':30B ''pending/pendingdone'':43B ''pid'':128B ''recovery'':35B ''rescuewip'':84B ''schema'':143B ''self'':25B,41B,58B ''selffinalizetool'':93B ''tsdown'':146B ''w'':8A,19B ''w-50fc8c52'':7A,18B ''wip'':51B,68B ''wip/rescued-'':70B ''wip/rescued-agent-self-20260910-214727-0910-2151'':105B ''不擅自回填工作区'':91B ''与'':32B ''与检查点'':107B ''且无'':42B ''个'':62B ''个文件以'':111B ''为空'':115B ''以未提交形态取回工作区'':71B ''修复'':65B ''修复验收'':6A,17B ''修正'':92B ''先归档'':77B ''再'':78B ''再回填'':80B ''冒烟'':144B ''切回干线前先'':83B ''判为崩溃滞留'':44B ''单测'':139B ''却不回干线'':31B ''原实现'':28B ''同一状态两种相反定义'':48B ''告知'':90B ''回干线'':46B,72B ''在'':38B ''完全一致'':109B ''审计'':136B ''导致按设计退出被下次启动误判'':49B ''崩溃路径刻意只归档'':89B ''工作日志'':23B ''归档分支'':104B ''归档并主动向根'':85B ''形态回到工作区且与归档分支逐文件'':113B ''把只存在于'':50B ''拉活'':130B ''提交上的文件从磁盘静默抹掉且无人告知'':52B ''插件'':142B ''播报'':87B ''收掉已归档的检查点分支'':73B ''文案'':94B ''新'':121B,127B ''新增'':74B ''无新增'':120B ''有完整'':134B ''构建通过'':148B ''检查点分支已收'':118B ''活体验收'':95B ''清'':29B ''独有内容到'':69B ''现场'':55B ''用户授权'':103B ''的'':123B ''看板文件消失'':64B ''真实'':101B ''空动作'':125B ''语义矛盾'':47B ''这正是修复目标'':126B ''退出前归档'':67B ''顺序不可交换'':76B', '2026-09-10 21:59:15.37555', '2026-09-10 21:59:15.37555', '{}');
