INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('c47ec249-793c-4172-89f3-a0ce7512de98', '000001 neutral 数据链路静默故障：定时任务报 success 但全市场K线冻结6个交易日', '000001 交易经验（2026-09-10T13:58:10.227Z）
