INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('e0022176-699e-4578-81b6-7728cf5d6c01', '[数据完整性 2026-09-10, w-8f2c4cc5] quant.daily_klines.', '[数据完整性 2026-09-10, w-8f2c4cc5] quant.daily_klines.volume 存在系统性 ×100 单位错误（误把"手"当"股"写入），非全表而集中在若干导入批次。判别口径：内证 (amount/volume)/close 只看数量级（复权会让该比值偏离 1，不能当 VWAP 用），比值>5 → volume×100；amount=0 的行无法自证，须用相邻自洽行参照分类并抽检外部源，盲改会引入新错（实证 93 行 div100 候选抽检 6/6 全是假阳性）。修复：三轮共 2,102,873 行（金额内证 1,980,894 + 邻行参照 36,547 + 按标的新浪重取 63,937）。K线覆盖缺口同期修复：全窗口对账补 1,286 只 31,595 根（sina-gapfill），全市场完整率 4,763→5,256。残留：119 只普通股 + 31 只 ST 有 6-37 日缺口（新浪源亦无数据/停牌），531,769 行 amount=0 无法内部自证。', 'knowledge', '{数据质量,daily_klines,volume,单位错误,K线缺口,000001,sina,2026-09-10}', NULL, '''-09'':3A,12B ''-10'':4A,13B ''-37'':93B ''/close'':30B ''0'':42B,101B ''1'':33B,60B,71B ''100'':19B,40B ''102'':56B ''119'':86B ''2'':55B ''2026'':2A,11B ''256'':84B ''286'':72B ''31'':74B,88B ''36'':64B ''4'':81B ''5'':38B,83B ''531'':97B ''547'':65B ''595'':75B ''6'':92B ''6/6'':51B ''63'':67B ''763'':82B ''769'':98B ''873'':57B ''894'':62B ''8f2c4cc5'':7A,16B ''93'':47B ''937'':68B ''980'':61B ''amount'':41B,100B ''amount/volume'':29B ''div100'':49B ''gapfill'':79B ''klines'':9A ''k线覆盖缺口同期修复'':69B ''quant.daily'':8A ''quant.daily_klines.volume'':17B ''sina'':78B ''sina-gapfill'':77B ''st'':90B ''volume'':39B ''vwap'':35B ''w'':6A,15B ''w-8f2c4cc5'':5A,14B ''三轮共'':54B ''不能当'':34B ''修复'':53B ''候选抽检'':50B ''停牌'':96B ''全市场完整率'':80B ''全是假阳性'':52B ''全窗口对账补'':70B ''内证'':28B ''写入'':25B ''判别口径'':27B ''单位错误'':20B ''只'':73B,89B ''只普通股'':87B ''只看数量级'':31B ''复权会让该比值偏离'':32B ''存在系统性'':18B ''实证'':46B ''当'':23B ''手'':22B ''按标的新浪重取'':66B ''数据完整性'':1A,10B ''新浪源亦无数据'':95B ''无法内部自证'':102B ''日缺口'':94B ''有'':91B ''根'':76B ''残留'':85B ''比值'':37B ''用'':36B ''的行无法自证'':43B ''盲改会引入新错'':45B ''股'':24B ''行'':48B,58B,99B ''误把'':21B ''邻行参照'':63B ''金额内证'':59B ''非全表而集中在若干导入批次'':26B ''须用相邻自洽行参照分类并抽检外部源'':44B', '2026-09-10 22:11:24.419788', '2