INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('9e233e77-2d96-47b3-9da5-8a5c9e583a16', '000001 neutral K线历史窗口(2025-06~2026-08)缺失 300 根日K，daily_jobs 的尾部追赶只补最新一日，缺口长期伪装成"', '000001 交易经验（2026-09-10T14:11:24.423Z）
场景：K线历史窗口(2025-06~2026-08)缺失 300 根日K，daily_jobs 的尾部追赶只补最新一日，缺口长期伪装成"数据正常"
结果：neutral
盈亏：0%
教训：数据新鲜度检查只看 max(trade_date) 会漏掉"有最新一根、答案中间empty"的内部空洞——必须用交易日历做逐标的连续性对账（missing = 日历日 - 该标的在日历日上的 bar 数），而不是只看尾部时间戳。发现缺口后按重叠日价格比做复权口径校正再补行，否则原始价与复权价混排会制造新的价格断层。', 'experience', '{000001,neutral}', NULL, '''-06'':5A,26B ''-09'':17B ''-10'':18B ''0'':39B ''000001'':1A,14B ''11'':20B ''2025'':4A,25B ''2026'':16B ''24.423'':21B ''300'':8A,29B ''bar'':53B ''daily'':10A,31B ''date'':44B ''jobs'':11A,32B ''k线历史窗口'':3A,24B ''max'':42B ''missing'':50B ''neutral'':2A,37B ''t14'':19B ''trade'':43B ''z'':22B ''~2026-08'':6A,27B ''交易经验'':15B ''会漏掉'':45B ''发现缺口后按重叠日价格比做复权口径校正再补行'':56B ''否则原始价与复权价混排会制造新的价格断层'':57B ''场景'':23B ''必须用交易日历做逐标的连续性对账'':49B ''教训'':40B ''数'':54B ''数据新鲜度检查只看'':41B ''数据正常'':35B ''日历日'':51B ''有最新一根'':46B ''根日k'':9A,30B ''的内部空洞'':48B ''的尾部追赶只补最新一日'':12A,33B ''盈亏'':38B ''答案中间empty'':47B ''结果'':36B ''缺口长期伪装成'':13A,34B ''缺失'':7A,28B ''而不是只看尾部时间戳'':55B ''该标的在日历日上的'':52B', '2026-09-10 22:11:24.42483', '2026-09-10 22:11:24.42483', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('0ac77ef5-2afc-47b5-b92f-dd68cb60c0db', '600887 neutral volume 列存在 ×100 单位错误，技术面/量能因子(volume_ma5/volume_ratio)与回测全部被污染，但价', '600887 交易经验（2026-09-10T14:11:24.427Z）
