INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('893264e0-a96d-4094-a68b-ae5b66c4e475', '300677 neutral 2026-09-10 市场极度恐慌（涨941/跌4478，新低142>新高26，量能0.65×）下持有英科医疗，浮盈+4%，既不止', '300677 交易经验（2026-09-10T14:18:24.928Z）
场景：2026-09-10 市场极度恐慌（涨941/跌4478，新低142>新高26，量能0.65×）下持有英科医疗，浮盈+4%，既不止盈也不加仓
结果：neutral
盈亏：4%
教训：恐慌未止（新低扩张+量能萎缩）时不因个别持仓浮盈而加仓，也不因大盘弱而砍正常浮盈仓；低仓位本身就是最好的对策——等下跌减速或结构信号再动，别用仓位去猜底。', 'experience', '{300677,neutral}', NULL, '''+4'':14A,37B ''-09'':4A,19B,27B ''-10'':5A,20B,28B ''18'':22B ''2026'':3A,18B,26B ''24.928'':23B ''300677'':1A,16B ''4'':42B ''neutral'':2A,40B ''t14'':21B ''z'':24B ''下持有英科医疗'':12A,35B ''也不因大盘弱而砍正常浮盈仓'':48B ''交易经验'':17B ''低仓位本身就是最好的对策'':49B ''别用仓位去猜底'':51B ''场景'':25B ''市场极度恐慌'':6A,29B ''恐慌未止'':44B ''教训'':43B ''新低142'':9A,32B ''新低扩张'':45B ''新高26'':10A,33B ''既不止'':15A ''既不止盈也不加仓'':38B ''时不因个别持仓浮盈而加仓'':47B ''浮盈'':13A,36B ''涨941'':7A,30B ''盈亏'':41B ''等下跌减速或结构信号再动'':50B ''结果'':39B ''跌4478'':8A,31B ''量能0.65'':11A,34B ''量能萎缩'':46B', '2026-09-10 22:18:24.930914', '2026-09-10 22:18:24.930914', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('a66e9a4c-85b1-4ccc-992a-1b81c38a551f', '2026-09-10 全市场K线冻结修复的下游恢复（w-23c70356）：K线补齐后必须按顺序补 ', '2026-09-10 全市场K线冻结修复的下游恢复（w-23c70356）：K线补齐后必须按顺序补 factor 与 chip，否则下游仍停在旧日期。①factor：handle_factor_compute 只对每只票"最新K线日"算因子，K线补到 09-10 后重跑才落 09-10（46→5257 只）；在进程外调用必须先 register_all_services()，否则报 Service not registered: IStockRepository。②chip：chip_distribution 按 pending K线逐只增量重放，2 分钟覆盖 5499 只。③恢复链判据：kline 覆盖率、factor 最新日 symbol 数、chip last_trade_date 三者同时达标才算恢复完成。数据来源：psql quant_investment（2026-09-10 22:12）。', 'experience', '{kline,factor,chip_distribution,data-recovery,REQ-e5a251,w-23c70356}', NULL, '''-09'':2A,10B,73B ''-10'':3A,11B,30B,33B,74B ''09'':29B,32B ''12'':76B ''2'':52B ''2026'':1A,9B,72B ''22'':75B ''23c70356'':7A,15B ''46'':34B ''5257'':35B ''5499'':54B ''all'':39B ''chip'':19B,46B,47B,63B ''compute'':24B ''date'':66B ''distribution'':48B ''factor'':17B,21B,23B,59B ''handle'':22B ''investment'':71B ''istockrepository'':45B ''kline'':57B ''k线补到'':28B ''k线补齐后必须按顺序补'':8A,16B ''k线逐只增量重放'':51B ''last'':64B ''not'':43B ''pending'':50B ''psql'':69B ''quant'':70B ''register'':38B ''registered'':44B ''service'':42B ''services'':40B ''symbol'':61B ''trade'':65B ''w'':6A,14B ''w-23c70356'':5A,13B ''三者同时达标才算恢复完成'':67B ''与'':18B ''全市场k线冻结修复的下游恢复'':4A,12B ''分钟覆盖'':53B ''只'':36B,55B ''只对每只票'':25B ''后重跑才落'':31B ''否则下游仍停在旧日期'':20B ''否则报'':41B ''在进程外调用必须先'':37B ''恢复链判据'':56B ''按'':49B ''数'':62B ''数据来源'':68B ''最新k线日'':26B ''最新日'':60B ''算因子'':27B ''覆盖率'':58B', '2026-09-10 22:13:17.928307', '2026-09-10 22:13:17.928307', '{}');
