INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('404d436b-61e3-46a2-8659-5e84b94e9705', '数据源成交量口径实证（2026-09-10，w-23c70356，腾讯行情 web.ifzq.gti', '数据源成交量口径实证（2026-09-10，w-23c70356，腾讯行情 web.ifzq.gtimg.cn 逐行比对）：主板/创业板接口返回单位为"手"（DB 股 = 源×100，57 行全一致）；科创板 688 返回单位为"股"（DB = 源，688 抽样 15 只×4 日 = 60 行全一致，比值恒为 1.00）。做跨源对账必须按板块区分换算，否则会误判 100 倍差异。另发现库内上游缺陷：2026-07~08 科创板共 411 行 volume>1e9 股（不可能量级）、499 行 amount>500 亿/日、合计约 66.6 万亿，例如 688008 澜起科技 2026-08-27 volume=6,726,883,400、amount=14,881 亿（source NULL），与"688 volume 被放大 100 倍"特征一致；另有指数伪行（399001/399300 等 34 行，source=calc-amt，单日可达 949 万亿）使全市场日成交额被放大（2026-09-10 全表 68.46 万亿 vs 真实约 2.4 万亿）。上述缺陷均非本次修复产生（我的标签行 0 行超标），待用户决策是否修复。', 'experience', '{科创板,volume_unit,腾讯行情,数据源口径,w-23c70356}', NULL, '''-07'':51B ''-08'':73B ''-09'':3A,12B,107B ''-10'':4A,13B,108B ''-27'':74B ''0'':118B ''1.00'':44B ''100'':26B,47B,90B ''14'':81B ''15'':37B ''1e9'':57B ''2.4'':114B ''2026'':2A,11B,50B,72B,106B ''23c70356'':7A,16B ''34'':96B ''399001/399300'':94B ''4'':39B ''400'':79B ''411'':54B ''499'':60B ''500'':63B ''57'':27B ''6'':76B ''60'':41B ''66.6'':67B ''68.46'':110B ''688'':30B,35B,87B ''688008'':70B ''726'':77B ''881'':82B ''883'':78B ''949'':103B ''amount'':62B,80B ''amt'':101B ''calc'':100B ''calc-amt'':99B ''db'':23B,33B ''null'':85B ''source'':84B,98B ''volume'':56B,75B,88B ''vs'':112B ''w'':6A,15B ''w-23c70356'':5A,14B ''web.ifzq.gti'':9A ''web.ifzq.gtimg.cn'':18B ''~08'':52B ''万亿'':68B,104B,111B,115B ''上述缺陷均非本次修复产生'':116B ''不可能量级'':59B ''与'':86B ''主板'':20B ''亿'':64B,83B ''使全市场日成交额被放大'':105B ''例如'':69B ''倍'':91B ''倍差异'':48B ''做跨源对账必须按板块区分换算'':45B ''全表'':109B ''创业板接口返回单位为'':21B ''单日可达'':102B ''另发现库内上游缺陷'':49B ''另有指数伪行'':93B ''只'':38B ''合计约'':66B ''否则会误判'':46B ''待用户决策是否修复'':120B ''我的标签行'':117B ''手'':22B ''抽样'':36B ''数据源成交量口径实证'':1A,10B ''日'':40B,65B ''比值恒为'':43B ''源'':25B,34B ''澜起科技'':71B ''特征一致'':92B ''真实约'':113B ''科创板'':29B ''科创板共'':53B ''等'':95B ''股'':24B,32B,5