INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('1cdf6f7b-11db-4765-af45-55ac0fca3232', '000001 neutral 修复"报错被 except 吞掉、功能静默消失"类缺陷（2026-09-10，一天内连中 4 处：交易日历 NameError、日', '000001 交易经验（2026-09-10T15:06:07.932Z）
场景：修复"报错被 except 吞掉、功能静默消失"类缺陷（2026-09-10，一天内连中 4 处：交易日历 NameError、日历接口空窗口、enrich 的 ds.factor=None、main.py 相对导入 ImportError）
结果：neutral
盈亏：0%
教训：静默降级三招识别法（agent 自查纪律）：
①【脚本模式 vs 模块模式】Python 入口若是 python path/main.py（__package__=''''），任何 from .x import y 必抛 "attempted relative import with no known parent package"；临时进程用 import 模块方式复现会全部"通过"——这正是本缺陷藏了这么久的原因。凡批量路由/插件注册，一律用绝对导入（项目根在 sys.path）。
②【裸名调用】函数体里出现未导入的名字（get_data_provider_manager）→ NameError 被 except Exception 吞；这类"名字不存在"必须先做 import 审查或用 ruff/pyflakes 静态扫。
③【依赖注错/漏注】ServiceFactory 漏参 → 依赖恒为 None → 下游 ''NoneType'' has no attribute 又被吞。判定口径：抓到 warning 级"Failed to ... {e}"必须先问"这个 except 吞掉的后果是什么"，再看数据是否真的产出了。
验收纪律：改完必须做"重启后线上实测"（HTTP 404→200、字段恒 0→非 0），只在临时进程里 pass 不算修复。', 'experience', '{000001,neutral}', NULL, '''-09'':10A,21B,35B ''-10'':11A,22B,36B ''0'':53B,139B,141B ''000001'':1A,18B ''06'':24B ''07.932'':25B ''200'':137B ''2026'':9A,20B,34B ''4'':13A,38B ''404'':136B ''agent'':56B ''attempted'':72B ''attribute'':118B ''data'':93B ''ds.factor'':45B ''e'':126B ''enrich'':43B ''except'':5A,30B,98B,129B ''exception'':99B ''failed'':124B ''from'':67B ''get'':92B ''has'':116B ''http'':135B ''import'':69B,74B,81B,104B ''importerror'':49B ''known'':77B ''main.py'':47B ''manager'':95B ''nameerror'':16A,41B,96B ''neutral'':2A,51B ''no'':76B,117B ''none'':46B,113B ''nonetype'':115B ''package'':65B,79B ''parent'':78B ''pass'':143B ''path/main.py'':64B ''provider'':94B ''python'':61B,63B ''relative'':73B ''ruff/pyflakes'':106B ''servicefactory'':110B ''sys.path'':89B ''t15'':23B ''to'':125B ''vs'':59B ''warning'':122B ''with'':75B ''x'':68B ''y'':70B ''z'':26B ''一天内连中'':12A,37B ''一律用绝对导入'':87B ''下游'':114B ''不算修复'':144B ''临时进程用'':80B ''交易日历'':15A,40B ''交易经验'':19B ''任何'':66B ''依赖恒为'':112B ''依赖注错'':108B ''修复'':3A,28B ''入口若是'':62B ''再看数据是否真的产出了'':131B ''凡批量路由'':85B ''函数体里出现未导入的名字'':91B ''判定口径'':120B ''功能静默消失'':7A,32B ''又被吞'':119B ''只在临时进程里'':142B ''名字不存在'':102B ''吞'':100B ''吞掉'':6A,31B ''吞掉的后果是什么'':130B ''场景'':27B ''处'':14A,39B ''字段恒'':138B ''审查或用'':105B ''必抛'':71B ''必须先做'':103B ''必须先问'':127B ''抓到'':121B ''报错被'':4A,29B ''插件注册'':86B ''改完必须做'':133B ''教训'':54B ''日'':17A ''日历接口空窗口'':42B ''模块方式复现会全部'':82B ''模块模式'':60B ''漏参'':111B ''漏注'':109B ''的'':44B ''盈亏'':52B ''相对导入'':48B ''类缺陷'':8A,33B ''级'':123B ''结果'':50B ''脚本模式'':58B ''自查纪律'':57B ''被'':97B ''裸名调用'':90B ''这个'':128B ''这正是本缺陷藏了这么久的原因'':84B ''这类'':101B ''通过'':83B ''重启后线上实测'':134B ''静态扫'':107B ''静默降级三招识别法'':55B ''非'':140B ''项目根在'':88B ''验收纪律'':132B', '2026-09-10 23:06:07.933964', '2026-09-10 23:06:07.933964', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('487af16f-6ba3-4581-a3b3-ac28e8827078', '错误事件 363337b4（决策打分完成裸 dict 行）根因与修复闭环（2026-09-10，in', '错误事件 363337b4（决策打分完成裸 dict 行）根因与修复闭环（2026-09-10，investor/w-8f2c4cc5）：根因=v2 用 logger.info 输出 Python dict 字面量任务汇总行（含 ''errors'': 0），非 JSON 文本行被 Agent OS 采集器 error 子串正则误采为 error 级；scanned=0 是 pending_days=30 窗口内无待打分决策的正常空跑（psql 实测 pending 且>30d = 0）。同源事件 cbad5b65（踏空捕获完成）一并处置，全库 241 条事件仅此 2 条属该形态。修复=①采集器 classifyLogLine 判定前剥离零值错误计数（error_event_worker.go zeroErrorMetricRe + 回归用例）②源头 decision_score_service / missed_opportunity_service 分档：空跑 debug、有产出 info、真失败 error(errors=N)。提交 0b4e473a（agent-os）、a7c2e2e4（quantsys-v2）。验证=故障注入：重启后重放旧行未被采集（occurrence 恒 19、last_seen 恒 23:06:41），errors=3 对照行正常入事件 55ab27d8。连带事实：Agent OS 采集器已判 resolved/ignored 的事件若同指纹复现会自动复开 open（error_event_repository.Upsert）——故日志中残留的历史行在修复前重启会反复复开，修复后不再命中。数据来源：Agent OS API /api/v1/scheduler/error-events（2026-09-10 23:16 实测）、v2 日志 logs/launchd-stdout.log、psql quant_investment。', 'knowledge', '{agent-os,error-event,363337b4,日志误采,采集器,decision_score_service,missed_opportunity_service,w-8f2c4cc5}', NULL, '''-09'':8A,18B,128B ''-10'':9A,19B,129B ''/api/v1/scheduler/error-events'':126B ''0'':31B,43B,54B ''06'':106B ''0b4e473a'':88B ''16'':131B ''19'':101B ''2'':62B ''2026'':7A,17B,127B ''23'':105B,130B ''241'':60B ''3'':109B ''30'':47B ''30d'':53B ''363337b4'':2A,12B ''41'':107B ''55ab27d8'':111B ''a7c2e2e4'':92B ''agent'':35B,90B,113B,123B ''agent-os'':89B ''api'':125B ''cbad5b65'':56B ''classifylogline'':66B ''days'':46B ''debug'':80B ''decision'':72B ''dict'':4A,14B,27B ''error'':38B,40B,84B ''error_event_repository.upsert'':119B ''error_event_worker.go'':68B ''errors'':30B,85B,108B ''in'':10A ''info'':82B ''investment'':138B ''investor/w-8f2c4cc5'':20B ''json'':33B ''last'':102B ''logger.info'':24B ''logs/launchd-stdout.log'':135B ''missed'':75B ''n'':86B ''occurrence'':99B ''open'':118B '