INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('ab2d4756-81c9-4eb5-a61e-2b0e996cd73f', 'AGENT-OS neutral 应用日志用 logger.info 打印 Python dict 字面量任务汇总行（含 "errors": 0），被下游基于子', 'AGENT-OS 交易经验（2026-09-10T15:17:32.486Z）
场景：应用日志用 logger.info 打印 Python dict 字面量任务汇总行（含 "errors": 0），被下游基于子串匹配的日志采集器判为 error 级事件，一天误报 19 次，看板堆满假告警
结果：neutral
盈亏：0%
教训：非结构化日志行里出现"错误"字样的键名（errors/failed/exceptions）即使值为 0，也会被子串匹配式采集器当成错误——① 源头：汇总行输出结构化字段，别把 dict 直接 f-string 进文本，且按结果分档日志级别（真失败 error / 有产出 info / 空跑 debug）；② 采集器：判定前剥离零值错误计数再匹配子串，并保留正控用例（errors=3 必须仍被采集）——只做"减少误报"的放宽会静默丢掉真错误；③ 验证必须故障注入：重启后用"负控（旧行重放不被采集）+ 正控（errors=3 正常入事件）"同一轮扫描对照，单测通过≠线上生效；④ 采集器 Upsert 对 resolved/ignored 同指纹事件会自动复开 open——历史日志里的误报行不清理，每次重启都会复开，别急着 resolve 就收工。实证：2026-09-10 事件 363337b4/cbad5b65，修复提交 0b4e473a/a7c2e2e4。', 'experience', '{AGENT-OS,neutral}', NULL, '''-09'':20B,104B ''-10'':21B,105B ''0'':13A,35B,46B,53B ''0b4e473a/a7c2e2e4'':109B ''17'':23B ''19'':40B ''2026'':19B,103B ''3'':75B,86B ''32.486'':24B ''363337b4/cbad5b65'':107B ''agent'':2A,16B ''agent-os'':1A,15B ''debug'':70B ''dict'':9A,31B,58B ''error'':37B,66B ''errors'':12A,34B,74B,85B ''errors/failed/exceptions'':51B ''f'':61B ''f-string'':60B ''info'':68B ''logger.info'':6A,28B ''neutral'':4A,44B ''open'':96B ''os'':3A,17B ''python'':8A,30B ''resolve'':100B ''resolved/ignored'':94B ''string'':62B ''t15'':22B ''upsert'':92B ''z'':25B ''一天误报'':39B ''且按结果分档日志级别'':64B ''也会被子串匹配式采集器当成错误'':54B ''事件'':106B ''交易经验'':18B ''修复提交'':108B ''减少误报'':78B ''判定前剥离零值错误计数再匹配子串'':72B ''别急着'':99B ''别把'':57B ''单测通过'':89B ''即使值为'':52B ''历史日志里的误报行不清理'':97B ''只做'':77B ''同一轮扫描对照'':88B ''同指纹事件会自动复开'':95B ''含'':11A,33B ''场景'':26B ''字样的键名'':50B ''字面量任务汇总行'':10A,32B ''实证'':102B ''对'':93B ''就收工'':101B ''并保留正控用例'':73B ''应用日志用'':5A,27B ''必须仍被采集'':76B ''打印'':7A,29B ''教训'':47B ''旧行重放不被采集'':83B ''有产出'':67B ''次'':41B ''正常入事件'':87B ''正控'':84B ''每次重启都会复开'':98B ''汇总行输出结构化字段'':56B ''源头'':55B ''的放宽会静默丢掉真错误'':79B ''盈亏'':45B ''直接'':59B ''看板堆满假告警'':42B ''真失败'':65B ''空跑'':69B ''级事件'':38B ''线上生效'':90B ''结果'':43B ''被下游基于子'':14A ''被下游基于子串匹配的日志采集器判为'':36B ''负控'':82B ''进文本'':63B ''采集器'':71B,91B ''重启后用'':81B ''错误'':49B ''非结构化日志行里出现'':48B ''验证必须故障注入'':80B', '2026-09-10 23:17:32.488112', '2026-09-10 23:17:32.488112', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('49a2afa0-9a2b-4fe5-8b26-04b296a43ca4', '科创板K线成交量量纲缺陷根因与修复（2026-09-10，w-23c70356，commit 5ef', '科创板K线成交量量纲缺陷根因与修复（2026-09-10，w-23c70356，commit 5efeaad2）：腾讯 K 线接口 /appstock/app/kline/kline 的成交量，科创板(688/689)返回「股」、其余板块返回「手」；providers/kline/tencent.py 曾无条件 ×100，导致 2026-07-24~08-31 共 2,110 行科创板 volume/amount 放大 100 倍（08-14~08-27 连续 10 个交易日每天固定 196 只、占当日科创板 32.2%），月度成交额虚增 91.41 万亿元，且 VWAP 自洽校验完全无感。已改为按板块判定（688/689 不乘 100）+ 6 条单测锁契约（故障注入验证：旧行为 4/6 失败）。自检盲区教训：「当日额/量 vs 自身近期中位数」（时序自比）在缺陷连续多日时会因参考窗口被自身污染而失效——必须配「同日同板块截面自比」：r=volume/avg_volume 对板内中位数 ×20 实测召回 99.1%、误报 0.28%（绝对 avg_volume 判据误报 6.0% 不可用）。数据来源：quant.daily_klines + quant.stocks.avg_volume + 备份表 quant.bak_starvol_vol_w23c70356（2026-09-10 23:0x 核验）。', 'knowledge', '{kline,volume,量纲,tencent,科创板,688,data-integrity,w-23c70356}', NULL, '''-07'':35B ''-09'':3A,12B,106B ''-10'':4A,13B,107B ''-14'':47B ''-24'':36B ''/appstock/app/kline/kline'':22B ''0.28'':88B ''08'':46B ''0x'':109B ''10'':50B ''100'':32B,44B,65B ''110'':40B ''196'':52B ''2'':39B ''20'':84B ''2026'':2A,11B,34B,105B ''23'':108B ''23c70356'':7A,16B ''32.2'':55B ''4/6'':70B ''5ef'':9A ''5efeaad2'':18B ''6'':66B ''6.0'':93B ''688/689'':25B,63B ''91.41'':57B ''99.1'':86B ''avg'':90B ''commit'':8A,17B ''k'':20B ''klines'':97B ''providers/kline/tencent.py'':30B ''quant.bak'':101B ''quant.daily'':96B ''quant.stocks.avg'':98B ''r'':81B ''starvol'':102B ''vol'':103B ''volume'':91B,99B ''volume/amount'':42B ''volume/avg_volume'':82B ''vs'':75B ''vwap'':60B ''w'':6A,15B ''w-23c70356'':5A,14B ''w23c70356'':104B ''~08-27'':48B ''~08-31'':37B ''万亿元'':58B ''不乘'':64B ''不可用'':94B ''且'':59B ''个交易日每天固定'':51B ''倍'':45B ''共'':38B ''其余板块返回'':28B ''判据误报'':92B ''占当日科创板'':54B ''只'':53B ''同日同板块截面自比'':80B ''在缺陷连续多日时会因参考窗口被自身污染而失效'':78B ''备份表'':100B ''失败'':71B ''实测召回'':85B ''对板内中位数'':83B ''导致'':33B ''已改为按板块判定'':62B ''当日额'':73B ''必须配'':79B ''手'':29B ''放大'':