INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('637ed0b7-84c4-43a0-999f-220512569b43', '【经验｜2026-09-10｜investor/w-8f2c4cc5】工程教训三条：①声明式依赖必须', '【经验｜2026-09-10｜investor/w-8f2c4cc5】工程教训三条：①声明式依赖必须与运行环境/代码实际用法互校——asyncpg 未声明导致整层异步 ORM 在运行时才炸，sqlalchemy pin 写 <2.0 而代码用 2.0 的 async_sessionmaker，重建环境必挂；判据="venv 里装了什么 + 代码 import 了什么 + pyproject 写了什么"三者必须一致。②"基类吞异常返回空集"是比报错更危险的静默降级：接口回 success:true + count=0，让上层误判"没有数据"；修法=仓储层不做兜底，异常上抛由路由转 success:false（本仓 AsyncBaseORMRepository.list_all/find_by_condition 仍待改）。③改 ORM 模型字段前先用 psql 打 d 核真实列名/类型，再改模型——Position 的 cost_price vs cost_basis、id 的 uuid vs BigInteger 都是"照文档写代码"的产物。④修复顺序影响线上一致性：先改仓储后改路由会造成"新仓储+旧路由"混合态（本次/API 短暂 500 级报错），同一次改动应一并提交并立即重启收敛。', 'experience', '{工程纪律,依赖声明,静默降级,ORM漂移,f00fd8fe,w-8f2c4cc5}', NULL, '''-09'':3A,10B ''-10'':4A,11B ''/api'':87B ''0'':45B ''2.0'':23B,25B ''2026'':2A,9B ''500'':89B ''all/find_by_condition'':55B ''async'':27B ''asyncbaseormrepository.list'':54B ''asyncpg'':16B ''basis'':72B ''biginteger'':77B ''cost'':68B,71B ''count'':44B ''d'':62B ''false'':52B ''id'':73B ''import'':34B ''investor/w-8f2c4cc5'':5A,12B ''orm'':18B,58B ''pin'':21B ''position'':66B ''price'':69B ''psql'':60B ''pyproject'':36B ''sessionmaker'':28B ''sqlalchemy'':20B ''success'':42B,51B ''true'':43B ''uuid'':75B ''venv'':31B ''vs'':70B,76B ''三者必须一致'':38B ''了什么'':35B ''仍待改'':56B ''仓储层不做兜底'':49B ''代码'':33B ''代码实际用法互校'':15B ''修复顺序影响线上一致性'':81B ''修法'':48B ''先改仓储后改路由会造成'':82B ''再改模型'':65B ''写'':22B ''写了什么'':37B ''判据'':30B ''同一次改动应一并提交并立即重启收敛'':91B ''在运行时才炸'':19B ''基类吞异常返回空集'':39B ''声明式依赖必须'':7A ''声明式依赖必须与运行环境'':14B ''工程教训三条'':6A,13B ''异常上抛由路由转'':50B ''打'':61B ''接口回'':41B ''改'':57B ''新仓储'':83B ''旧路由'':84B ''是比报错更危险的静默降级'':40B ''未声明导致整层异步'':17B ''本仓'':53B ''本次'':86B ''核真实列名'':63B ''模型字段前先用'':59B ''没有数据'':47B ''混合态'':85B ''照文档写代码'':79B ''的'':26B,67B,74B ''的产物'':80B ''短暂'':88B ''类型'':64B ''级报错'':90B ''经验'':1A,8B ''而代码用'':24B ''让上层误判'':46B ''都是'':7