INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('33956728-61bd-4d74-be16-0fe51cc59f8a', '000000 profit 非个股（错误看板工程）：批量清理 229 条 open/processing 错误事件，按「根因→动作→证据」分桶处置', '000000 交易经验（2026-09-10T16:06:03.809Z）
场景：非个股（错误看板工程）：批量清理 229 条 open/processing 错误事件，按「根因→动作→证据」分桶处置
结果：profit
盈亏：0%
教训：批量清理错误看板三条纪律：①先分桶再动手，同族一条结论覆盖 N 条，避免 229 次重复推理；②关闭前必须能指出「哪一行代码/哪个 commit/哪条 SQL 证据」——修不动的（会话泄漏、FK 冲突、500）一律留在 open 并上报，用 ignore 掩盖真实缺陷是最贵的错误；③过滤模式补测要覆盖「实测漏过的那一条」：本轮 venv 路径碎片因字符类缺 "/" 二次漏收，说明只按推理写模式会漏掉真实数据形状，必须从数据库取原文回灌成用例。', 'experience', '{000000,profit}', NULL, '''-09'':18B ''-10'':19B ''0'':40B ''000000'':1A,15B ''03.809'':22B ''06'':21B ''2026'':17B ''229'':6A,28B,48B ''500'':61B ''commit'':53B ''fk'':59B ''ignore'':66B ''n'':45B ''open'':63B ''open/processing'':8A,30B ''profit'':2A,38B ''sql'':55B ''t16'':20B ''venv'':71B ''z'':23B ''一律留在'':62B ''二次漏收'':73B ''交易经验'':16B ''会话泄漏'':58B ''修不动的'':57B ''先分桶再动手'':43B ''关闭前必须能指出'':50B ''冲突'':60B ''分桶处置'':14A,36B ''动作'':12A,34B ''同族一条结论覆盖'':44B ''哪一行代码'':51B ''哪个'':52B ''哪条'':54B ''场景'':24B ''实测漏过的那一条'':69B ''并上报'':64B ''必须从数据库取原文回灌成用例'':75B ''批量清理'':5A,27B ''批量清理错误看板三条纪律'':42B ''按'':10A,32B ''掩盖真实缺陷是最贵的错误'':67B ''教训'':41B ''本轮'':70B ''条'':7A,29B,46B ''根因'':11A,33B ''次重复推理'':49B ''用'':65B ''盈亏'':39B ''结果'':37B ''证据'':13A,35B,56B ''说明只按推理写模式会漏掉真实数据形状'':74B ''路径碎片因字符类缺'':72B ''过滤模式补测要覆盖'':68B ''避免'':47B ''错误事件'':9A,31B ''错误看板工程'':4A,26B ''非个股'':3A,25B', '2026-09-11 00:06:03.815144', '2026-09-11 00:06:03.815144', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('06f42508-8915-42e2-9376-e20dd407f0a3', '任务 232 每日数据质量检查加固（2026-09-11，w-23c70356）：根因=参数键漂移（', '任务 232 每日数据质量检查加固（2026-09-11，w-23c70356）：根因=参数键漂移（配置 days/stock_limit vs 实现 check_days/symbols_limit → 配置静默失效）+ 回填阶段无墙钟预算 + 无单次额度 + 失败率 100% 仍跑 retry_failed(5) 放大 + 共享 Session 空闲事务被 PG 杀掉后毒化 run 记账（InFailedSqlTransaction）。耗时构成实测：全市场 5689 只 × 30 天检查仅约 78s，回填 50 只耗时 822.86s（16.5s/只，夜间数据源全灭）；即耗时方差全在回填。修复要点：作业边界参数归一 + effective_params 记录；max_runtime_sec=1800 墙钟预算（检查阶段 deadline 预留 120s）；回填额度 min(50, 剩余预算/20s) 且按缺失天数降序；失败率 ≥80% 熔断跳过重试；回填前释放挂起事务 + 告警查询前回滚重试一次；结果集新增 timed_out/budget_limited/check_truncated/backfill_degraded 诚实标记。验证：13 项单测 + 143 项相关回归通过；全市场真实跑 901.2s 完成（此前 9.7~116 分钟、失败 2.8 小时）；孤儿 run 启动回收故障注入实测通过（合成 running 记录被置 failed）。教训：定时任务"配置了不等于生效"——必须把生效参数写进运行结果；"成功但耗时长"的任务优先查预算与失败重试放大，而不是查重复调度（本次经核验 apscheduler_jobs 仅 1 行 task_232，不存在重复）。', 'experience', '{232,data_quality_check,scheduler,quantsys-v2,定时任务,参数漂移,超时预算,w-23c70356}', NULL, '''-09'':5A,16B ''-11'':6A,17B ''/20s'':82B ''1'':127B ''100'':33B ''120s'':77B ''13'':94B ''143'':96B ''16.5'':59B ''1800'':72B ''2.8'':107B ''2026'':4A,15B ''232'':2A,13B,130B ''23c70356'':9A,20B ''30'':51B ''5'':37B ''50'':55B,80B ''5689'':49B ''78s'':53B ''80'':85B ''822.86'':57B ''9.7'':103B ''901.2'':99B ''apscheduler'':124B ''check'':27B ''days/stock_limit'':24B ''days/symbols_limit'':28B ''deadline'':75B ''effective'':66B ''failed'':36B,115B ''infailedsqltransaction'':46B ''jobs'':125B ''max'':69B ''min'':79B ''out/budget_limited/check_truncated/backfill_degraded'':91B ''params'':67B ''pg'':42B ''retry'':35B ''run'':44B,110B ''running'':113B ''runtime'':70B ''s'':58B,60B,100B ''sec'':71B ''session'':40B ''task'':129B ''timed'':90B ''vs'':25B ''w'':8A,19B ''w-23c70356'':7A,18B ''~116'':104B ''不存在重复'':131B ''且按缺失天数降序'':83B ''仅'':126B ''仍跑'':34B ''任务'':1A,12B ''作业边界参数归一'':65B ''修复要点'':64B ''全市场'':48B ''全市场真实