INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('70a14e13-fb87-4b28-ac54-348f8bc7de3a', '2026-09-11 v2 通知链路 DDD 对接审计与修复（窗口 w-23c70356，提交 23', '2026-09-11 v2 通知链路 DDD 对接审计与修复（窗口 w-23c70356，提交 2321fd3e）。核心教训：(1) 「策略写对了 ≠ 生效」——NotificationPolicy 里 agent 优先/feishu 降级写得清清楚楚，但 facade 有 9 处 preferred_channels=[feishu] 会让 select_channels() 第一步短路，任何「优先级配置」都要检查调用方有没有绕过它；(2) 沉默的契约漂移：AgentChannel 调 {url}/wake 是旧 wake-channel 契约、AGENT_OS_URL 默认 3002，而 Agent OS 实际在 8080 且入口是 POST /api/v1/notifications/send，v2 全仓 0 处调用真接口——实测 send() 恒失败并静默降级飞书，链路「看起来在工作」；(3) 判断某个渠道是否真在用，看渠道健康（healthcheck agent=False）+ 抓一次真实投递的 channel= 日志，而不是读配置；(4) 迁移半途的桥接层（legacy_adapters 写好但 0 引用）+ 旧服务裸 POST webhook 是铁律违反的常见残留。修复方法：复用 DDD 门面与策略、必要时改基础设施渠道实现、把旧入口收敛成桥接壳并删除裸通道。验证范式：真实投递看 channel + 服务端落库（OS public.notification_logs）+ 故障注入看降级。', 'experience', '{通知架构,NotificationFacade,AgentOS,契约漂移,策略短路,w-23c70356,2026-09-11}', NULL, '''-09'':2A,15B ''-11'':3A,16B ''/api/v1/notifications/send'':75B ''/feishu'':35B ''/wake'':57B ''0'':78B,100B ''1'':28B ''2'':52B ''2026'':1A,14B ''23'':13A ''2321fd3e'':26B ''23c70356'':11A,24B ''3'':85B ''3002'':67B ''4'':95B ''8080'':72B ''9'':40B ''adapters'':98B ''agent'':33B,63B,69B,89B ''agentchannel'':54B ''channel'':61B,92B,114B ''channels'':43B,47B ''ddd'':6A,19B,108B ''facade'':38B ''false'':90B ''feishu'':44B ''healthcheck'':88B ''legacy'':97B ''logs'':118B ''notificationpolicy'':31B ''os'':64B,70B,116B ''post'':74B,103B ''preferred'':42B ''public.notification'':117B ''select'':46B ''send'':81B ''url'':56B,65B ''v2'':4A,17B,76B ''w'':10A,23B ''w-23c70356'':9A,22B ''wake'':60B ''wake-channel'':59B ''webhook'':104B ''且入口是'':73B ''任何'':49B ''优先'':34B ''优先级配置'':50B ''会让'':45B ''但'':37B ''修复方法'':106B ''全仓'':77B ''写好但'':99B ''判断某个渠道是否真在用'':86B ''处'':41B ''处调用真接口'':79B ''复用'':107B ''契约'':62B ''实测'':80B ''实际在'':71B ''对接审计与修复'':7A,20B ''引用'':101B ''必要时改基础设施渠道实现'':110B ''恒失败并静默降级飞书'':82B ''把旧入口收敛成桥接壳并删