INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('3c3a3e2d-617c-4ca3-8379-6ab16c41223b', '2026-09-11 M4 熔断存量行误触发并已解除（agent_virtual）：quant.po', '2026-09-11 M4 熔断存量行误触发并已解除（agent_virtual）：quant.portfolio_circuit_breaker 原 active=t/triggered_drawdown=-10.71（源自 2026-09-10 K 线冻结期错误回撤），会经 account_trading_service.breaker_active_fn 硬拦截新开仓。独立复核不支持触发——quant.simulation_equity_snapshot（agent_virtual，55 条，2026-06-22..2026-09-10）直算最大回撤 -1.83%（谷底 2026-08-07）；risk_metrics 60 日 -6.7%；regime_position_limit triggered=false/verdict=compliant。已 POST /api/risk/circuit-breaker active=false 并写入证据 note（investor / w-8f2c4cc5）。遗留缺陷：risk_metrics 的最大回撤与其名义数据源（账户净值序列）相差 4.9 个百分点，口径未对齐，不可直接用于熔断/仓位决策。', 'knowledge', '{风控,熔断,M4,agent_virtual,risk_metrics,数据口径}', NULL, '''-06'':43B ''-07'':53B ''-08'':52B ''-09'':2A,10B,25B,46B ''-1.83'':49B ''-10'':26B,47B ''-10.71'':22B ''-11'':3A,11B ''-22'':44B ''-6.7'':58B ''/api/risk/circuit-breaker'':67B ''2026'':1A,9B,24B,42B,45B,51B ''4.9'':82B ''55'':40B ''60'':56B ''8f2c4cc5'':75B ''account_trading_service.breaker'':30B ''active'':20B,31B,68B ''agent'':6A,14B,38B ''breaker'':18B ''circuit'':17B ''compliant'':64B ''equity'':36B ''false'':69B ''false/verdict'':63B ''fn'':32B ''investor'':72B ''k'':27B ''limit'':61B ''m4'':4A,12B ''metrics'':55B,78B ''note'':71B ''position'':60B ''post'':66B ''quant.po'':8A ''quant.portfolio'':16B ''quant.simulation'':35B ''regime'':59B ''risk'':54B,77B ''snapshot'':37B ''t/triggered_drawdown'':21B ''triggered'':62B ''virtual'':7A,15B,39B ''w'':74B ''w-8f2c4cc5'':73B ''不可直接用于熔断'':85B ''个百分点'':83B ''仓位决策'':86B ''会经'':29B ''原'':19B ''口径未对齐'':84B ''已'':65B ''并写入证据'':70B ''日'':57B ''条'':41B ''源自'':23B ''熔断存量行误触发并已解除'':5A,13B ''独立复核不支持触发'':34B ''的最大回撤与其名义数据源'':79B ''直算最大回撤'':48B ''相差'':81B ''硬拦截新开仓'':33B ''线冻结期错误回撤'':28B ''谷底'':50B ''账户净值序列'':80B ''遗留缺陷'':76B', '2026-09-11 01:06:35.023165', '2026-09-11 01:06:35.023165', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('2de3d9ad-4036-4025-a1df-3a67d5145ee8', '2026-09-11 个股融资融券数据源修复（quantsys-v2，提交 28546727）：Ak', '2026-09-11 个股融资融券数据源修复（quantsys-v2，提交 28546727）：AkShareMarginSource 原以 symbol= 调用 ak.stock_margin_detail_sse，而 akshare 1.18.81 该接口签名为 (date: str) 按日期取全市场明细，必然 TypeError（board 事件 3cef6bef），个股两融数据长期取不到并静默降级到 SimulatedMarginSource 随机数。修复：按代码前缀路由市场（6→sse / 0、3→szse / 4、8→bse）+ 逐交易日回溯跳周末 + 按证券代码过滤 + 日期倒序输出 + 沪市无融券余额列时 has_margin_balance=false 如实标注 + 空返回不重试/连续 3 日真故障才报错。证据：tests/test_margin_data_source.py 17 passed；600887 取到 5 条 2026-09-09..09-03（sse），300677 取到 5 条（szse）；GET /api/stock/600887/margin?days=5 返回 source=akshare、首行融资余额 245446.3005 万元。', 'knowledge', '{融资融券,akshare,quantsys-v2,数据源,静默降级}', NULL, '''-03'':78B ''-09'':2A,12B,75B,76B ''-11'':3A,13B ''/api/stock/600887/margin'':86B ''0'':47B ''09'':77B ''1.18.81'':30B ''17'':68B ''2026'':1A,11B,74B ''245446.3005'':93B ''28546727'':9A,19B ''3'':48B,64B ''300677'':80B ''3cef6bef'':39B ''4'':50B ''5'':72B,82B,88B ''6'':45B ''600887'':70B ''8'':51B ''ak'':10A ''ak.stock'':24B ''akshare'':29B,91B ''aksharemarginsource'':20B ''balance'':59B ''board'':37B ''bse'':52B ''date'':32B ''days'':87B ''detail'':26B ''false'':60B ''get'':85B ''has'':57B ''margin'':25B,58B ''passed'':69B ''quantsys'':6A,16B ''quantsys-v2'':5A,15B ''simulatedmarginsource'':41B ''source'':90B ''sse'':27B,46B,79B ''str'':33B ''symbol'':22B ''szse'':49B,84B ''tests/test_margin_data_source.py'':67B ''typeerror'':36B ''v2'':7A,17B ''万元'':94B ''个股两融数据长期取不到并静默降级到'':40B ''个股融资融券数据源修复'':4A,14B ''事件'':38B ''修复'':43B ''原以'':21B ''取到'':71B,81B ''如实标注'':61B ''必然'':35B ''按代码前缀路由市场'':44B ''按日期取全市场明细'':34B ''按证券代码过滤'':54B ''提交'':8A,18B ''日期倒序输出'':55B ''日真故障才报错'':65B ''条'':73B,83B ''沪市无融券余额列时'':56B ''空返回不重试'':62B ''而'':28B ''证据'':66B ''该接口签名为'':31B ''调用'':23B ''返回'':89B ''连续'':63B ''逐交易日回溯跳周末'':53B ''随机数'':42B ''首行融资余额'':92B', '2026-09-11 01:06