INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('c17ff078-e0d0-421a-a3b0-b52c5bd200b3', '2026-09-11 账户风控口径统一（提交 716c053c，迁移 c13c17b6）：simul', '2026-09-11 账户风控口径统一（提交 716c053c，迁移 c13c17b6）：simulation_equity_snapshot.daily_return 长期基准错位——写入方用 get_equity_snapshots(limit=1) 取最近一条当基准，而该条常是当日 09:31 的早盘残缺估值（2026-07-27 记 +24.08%，真实 +0.72%）；/api/risk/metrics 账户模式又用「持仓等权+忽略现金」的 K 线代理口径，现金 87% 的账户被高估（-6.7% vs 净值 -1.83%）；RiskMetricsService 还把年化无风险利率当单期传入 empyrical（annual_return +26.6% 与 sharpe -78.7 自相矛盾）。现统一：写入端按上一交易日有效快照计算 daily_return（无基准写 NULL；|r|>15% 告警；账户首笔 deposit 视为成立资金不计入流入）、读取端以账户净值为唯一真源并返回 returnsSource、年化 rf 换算为 (1+rf)^(1/252)-1。风控阈值类决策今后一律以净值口径为准，其他口径仅作参考。', 'knowledge', '{风控,净值口径,daily_return,risk_metrics,M4熔断,agent_virtual}', NULL, '''+0.72'':38B ''+24.08'':36B ''+26.6'':58B ''-07'':33B ''-09'':2A,11B ''-1'':83B ''-1.83'':52B ''-11'':3A,12B ''-27'':34B ''-6.7'':49B ''-78.7'':61B ''/api/risk/metrics'':39B ''09'':29B ''1'':26B,80B ''1/252'':82B ''15'':70B ''2026'':1A,10B,32B ''31'':30B ''716c053c'':6A,15B ''87'':47B ''annual'':56B ''c13c17b6'':8A,17B ''daily'':65B ''deposit'':73B ''empyrical'':55B ''equity'':23B ''get'':22B ''k'':44B ''limit'':25B ''null'':68B ''r'':69B ''return'':19B,57B,66B ''returnssource'':76B ''rf'':78B,81B ''riskmetricsservice'':53B ''sharpe'':60B ''simul'':9A ''simulation_equity_snapshot.daily'':18B ''snapshots'':24B ''vs'':50B ''与'':59B ''其他口径仅作参考'':85B ''写入方用'':21B ''写入端按上一交易日有效快照计算'':64B ''净值'':51B ''取最近一条当基准'':27B ''告警'':71B ''年化'':77B ''忽略现金'':42B ''持仓等权'':41B ''换算为'':79B ''提交'':5A,14B ''无基准写'':67B ''现统一'':63B ''现金'':46B ''的'':43B ''的早盘残缺估值'':31B ''的账户被高估'':48B ''真实'':37B ''线代理口径'':45B ''而该条常是当日'':28B ''自相矛盾'':62B ''视为成立资金不计入流入'':74B ''记'':35B ''读取端以账户净值为唯一真源并返回'':75B ''账户模式又用'':40B ''账户风控口径统一'':4A,13B ''账户首笔'':72B ''迁移'':7A,16B ''还把年化无风险利率当单期传入'':54B ''长期基准错位'':20B ''风控阈值类决策今后一律以净值口径为准'':84B', '2026-09-11 01:21:10.155504', '2026-09-11 01:21:10.155504', 