INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('98755d7e-8009-4b00-828a-4701dca9e94c', '【更正 2026-09-11，w-c8cae280】此前记录的『信号分级反常：A 级 2 个、5 日', '【更正 2026-09-11，w-c8cae280】此前记录的『信号分级反常：A 级 2 个、5 日胜率 0%、平均 -28.87%（B 66.7%、C 100%）』结论**作废**——它是假数据造成的假结论。查明：quant.signal_tracking 16 条中 4 条 600519 记录为测试/自检写入，价格与日期均不可对账：08-22 price 1800.00（reason 明写『测试历史信号』，且 08-22 为周六无K线）、08-27 price 1850.50（真实收盘 1292.30，偏离 +43.2%）、08-30 price 1292.30（周日）、09-05 price 1420.00（周六）。因 return_5d = price_5d/entry_price-1，统计出的『A 级亏 28.87%』实际测的是记录价格的错误幅度，与信号表现无关。处置：4 条备份至 quant.signal_tracking_invalid_backup_20260911 后自账本删除；清理后账本 12 条 = B 4 个（5日均 +2.57%）+ C 8 个（+2.23%）+ **A 级 0 样本**（如实，不再有虚假 A 级）。对 R-009 的结论：**A 级样本为 0，此前『A 级不得放大仓位』的临时限制依据消失，但也无任何证据支持或反对 R-009**——需等真实 A 级样本积累后重新评估。根因护栏（已上线并实例验证 4/4）：signal_track(record) 写入前与当日真实K线对账，①日期无K线→拒绝 ②返回K线 trade_date≠请求日期→拒绝 ③|price/close-1|>15%→拒绝 ④取数失败→fail-closed 拒绝。红线教训：**我两次把『校验失败』当成『通道故障』fail-open 放行，且单测 mock（返回空数组）与真实 client（抛错）不一致导致假通过**——这是本 REQ 内第三次栽在『mock 通过≠线上成立』（前两次：additionalProperties:false 静默吞字段、sector_analysis 窗口参数被忽略）。凡护栏类代码，必须用真实后端跑正向/反向用例，且默认 fail-closed。', 'experience', '{更正,signal_track,假数据,fail-closed,mock陷阱,R-009,w-c8cae280}', NULL, '''+2.23'':112B ''+2.57'':108B ''+43.2'':70B ''-009'':123B,134B ''-05'':77B ''-09'':3A,18B ''-11'':4A,19B ''-22'':53B,61B ''-27'':64B ''-28.87'':33B ''-30'':72B ''0'':31B,115B,127B ''08'':52B,60B,63B,71B ''09'':76B ''100'':37B ''12'':102B ''1292.30'':68B,74B ''1420.00'':79B ''15'':153B ''16'':44B ''1800.00'':55B ''1850.50'':66B ''2'':12A,27B ''2026'':2A,17B ''20260911'':99B ''28.87'':89B ''4'':46B,93B,105B ''4/4'':140B ''5'':14A,29B ''5d'':83B ''5d/entry_price-1'':85B ''5日均'':107B ''600519'':48B ''66.7'':35B ''8'':110B ''a'':10A,25B,87B,113B,119B,125B,129B,136B ''additionalproperties'':183B ''analysis'':187B ''b'':34B,104B ''backup'':98B ''c'':36B,109B ''c8cae280'':7A,22B ''client'':173B ''closed'':158B,195B ''date'':149B 