INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('4df7943e-dfff-418b-a729-a2c9c146baba', '2026-09-11 决策留痕（w-c8cae280）：应检查点归属他人的情况，用户裁决『保持现状、', '2026-09-11 决策留痕（w-c8cae280）：应检查点归属他人的情况，用户裁决『保持现状、由该窗口自行合并』。我据此**刻意未调用 self_finalize**（merge 会把另一窗口未提交的 pages/execution 看板改动推上 main；rollback/exit 会把其文件移出工作区——两者都属改动他人工作）。当前状态：HEAD 停在 agent-self/20260911-014729（含其看板路由+分页测试改动），我的全部修复已在 main（b2173f0a 等），双方互不干扰；其内容另存于分支 rescue/pages-execution-20260911 与 tag rescued-wip-20260911。已知代价（如实记录）：HEAD 留在 agent-self/* 时，下一次重启的 boot-recovery 可能按既有规则『强行回干线』并把那份未提交内容移出工作区——但因已提交为 c0ed9174 且有具名归档 ref，不会丢失。待该窗口自行处理或用户后续指示。', 'knowledge', '{跨窗口,wip检查点,未finalize,w-c8cae280}', NULL, '''-09'':2A,12B ''-11'':3A,13B ''/20260911-014729'':40B ''2026'':1A,11B ''20260911'':55B ''agent'':38B,61B ''agent-self'':37B,60B ''b2173f0a'':45B ''boot'':66B ''boot-recovery'':65B ''c0ed9174'':72B ''c8cae280'':7A,17B ''finalize'':25B ''head'':35B,58B ''main'':30B,44B ''merge'':26B ''pages/execution'':28B ''recovery'':67B ''ref'':74B ''rescue/pages-execution-20260911'':49B ''rescued'':53B ''rescued-wip'':52B ''rollback/exit'':31B ''self'':24B,39B,62B ''tag'':51B ''w'':6A,16B ''w-c8cae280'':5A,15B ''wip'':54B ''下一次重启的'':64B ''不会丢失'':75B ''与'':50B ''且有具名归档'':73B ''两者都属改动他人工作'':33B ''会把其文件移出工作区'':32B ''会把另一窗口未提交的'':27B ''但因已提交为'':71B ''保持现状'':10A,20B ''停在'':36B ''其内容另存于分支'':48B ''决策留痕'':4A,14B ''分页测试改动'':42B ''刻意未调用'':23B ''双方互不干扰'':47B ''可能按既有规则'':68B ''含其看板路由'':41B ''如实记录'':57B ''已知代价'':56B ''并把那份未提交内容移出工作区'':70B ''应检查点归属他人的情况'':8A,18B ''强行回干线'':69B ''当前状态'':34B ''待该窗口自行处理或用户后续指示'':76B ''我据此'':22B ''我的全部修复已在'':43B ''时'':63B ''用户裁决'':9A,19B ''由该窗口自行合并'':21B ''留在'':59B ''看板改动推上'':29B ''等'':46B', '2026-09-11 01:49:07.853592', '2026-09-11 01:49:07.853592', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('c253cc88-479c-4fc3-8dd2-6e4ae5b3aa74', '2026-09-11 看板噪音治理三则（w-8f2c4cc5）：①同一异常跨通道指纹统一——stru', '2026-09-11 看板噪音治理三则（w-8f2c4cc5）：①同一异常跨通道指纹统一——structlog JSON 通道取语义键文本（event/message/msg/error/exception/detail 顺序拼接），纯文本通道剥离 logger 模块前缀 ^[a-z_][a-z0-9_]*(?:\.[a-z0-9_]+)+:\s+，worker 改用 FingerprintOfWithDetail 让栈帧参与指纹；双端向量表重生成并双向断言（Go internal/repository/error_event_crosslang_test.go 与 Python tests/test_error_reporting_fingerprint.py）。生产实测：同一异常两通道注入 → 单条事件 occurrence_count=2（修复前分裂为 f5341905+9e7070cc）。②K线链路语义分级（提交 5fa75178）：区间仅含周末直接短路返回，其余按「有源正常但为空 → WARNING」/「全源抛异常 → ERROR」区分，只有后者才产生看板事件。③看板错误事件列表兼容 limit/offset 别名并回显 paging.via（此前静默回落默认分页，曾导致「分页失效」的错误结论）。', 'knowledge', '{看板,错误事件,指纹,跨语言,噪音治理,K线链路}', NULL, '''+9e7070'':56B ''-09'':2A,11B ''-11'':3A,12B ''2'':53B ''2026'':1A,10B ''5fa75178'':60B ''8f2c4cc5'':7A,16B ''9'':32B,36B ''a'':27B,30B,34B ''a-z'':26B ''a-z0'':29B,33B ''cc'':57B ''count'':52B ''error'':66B ''event/message/msg/error/exception/detail'':21B ''f5341905'':55B ''fingerprintofwithdetail'':40B ''go'':43B ''internal/repository/error_event_crosslang_test.go'':44B ''json'':19B ''k线链路语义分级'':58B ''limit/offset'':70B ''logger'':24B ''occurrence'':51B ''paging.via'':72B ''python'':46B ''s'':37B ''stru'':9A ''structlog'':18B ''tests/test_error_reporting_fingerprint.py'':47B ''w'':6A,15B ''w-8f2c4cc5'':5A,14B ''warning'':64B ''worker'':38B ''z'':28B ''z0'':31B,35B ''与'':45B ''修复前分裂为'':54B ''全源抛异常'':65B ''其余按'':62B ''分页失效'':75B ''别名并回显'':71B ''区分'':67B ''区间仅含周末直接短路返回'':61B ''单条事件'':50B ''双端向量表重生成并双向断言'':42B ''只有后者才产生看板事件'':68B ''同一异常两通道注入'':49B ''同一异常跨通道指纹统一'':8A,17B ''提交'':59B ''改用'':39B ''曾导致'':74B ''有源正常但为空'':63B ''模块前缀'':25B ''此前静默回落默认分页'':73B ''生产实测'':48B ''的错误结论'':76B ''看板噪音治理三则'':4A,13B ''看板错误事件列表兼容'':69B ''纯文本通道剥离'':23B ''让栈帧参与指纹'':41B ''通道取语义键文本'':20B ''顺序拼接'':22B', '2026-09-11 01:58:55.540934', '2026-09-11 01:58:55.540934', '{}'