INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('44180eca-c4bd-48f9-ac2d-24e3a22cd257', '600519 neutral 数据链路把「无数据」当成「数据源故障」上报：查询非交易日（周日）K线，本地库空 + 新浪过滤后空 + 财东网络异常，链路口径统一按', '600519 交易经验（2026-09-10T17:58:55.549Z）
场景：数据链路把「无数据」当成「数据源故障」上报：查询非交易日（周日）K线，本地库空 + 新浪过滤后空 + 财东网络异常，链路口径统一按 ERROR 汇总
结果：neutral
盈亏：0%
教训：failover 链路的终局日志必须区分三种结局——成功、正常空、真故障；只有后者才是告警。判断依据是「是否有源正常返回但为空」。另：请求区间若不含交易日，应在链路入口短路，既不浪费外部请求，也避免把网络抖动放大成故障事件。', 'experience', '{600519,neutral}', NULL, '''-09'':18B ''-10'':19B ''0'':42B ''2026'':17B ''55.549'':22B ''58'':21B ''600519'':1A,15B ''error'':37B ''failover'':44B ''k线'':10A,32B ''neutral'':2A,40B ''t17'':20B ''z'':23B ''上报'':7A,29B ''也避免把网络抖动放大成故障事件'':56B ''交易经验'':16B ''判断依据是'':50B ''另'':52B ''只有后者才是告警'':49B ''周日'':9A,31B ''场景'':24B ''应在链路入口短路'':54B ''当成'':5A,27B ''成功'':46B ''教训'':43B ''数据源故障'':6A,28B ''数据链路把'':3A,25B ''新浪过滤后空'':12A,34B ''无数据'':4A,26B ''既不浪费外部请求'':55B ''是否有源正常返回但为空'':51B ''本地库空'':11A,33B ''查询非交易日'':8A,30B ''正常空'':47B ''汇总'':38B ''盈亏'':41B ''真故障'':48B ''结果'':39B ''请求区间若不含交易日'':53B ''财东网络异常'':13A,35B ''链路口径统一按'':14A,36B ''链路的终局日志必须区分三种结局'':45B', '2026-09-11 01:58:55.550125', '2026-09-11 01:58:55.550125', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('fff03c70-591a-48c8-be8d-58fcb8b1ed66', '2026-09-11 01:50-02:10（w-f4aa1f6a）用户批准的四项收口全部落地（提交', '2026-09-11 01:50-02:10（w-f4aa1f6a）用户批准的四项收口全部落地（提交 6a95aa76）：
①熔断输入可信度闸门（agent-dh M4CircuitBreakerTool + drawdownTrust.ts）：触发前用净值序列 total_value 峰谷**独立复算**回撤，与判定读数比对（容差 1.0pp）+ 样本≥20 点；复核不过只报 needs_review 且**不下任何单**（osMemory 留痕）。驱动事故：09-10 08:30 依据 -10.71% 真实卖出 600887，而该数源自净值快照收益口径错误（修正后 -1.83%，同期总盈亏 +1.13%）。
②业绩归因改按交易日对齐（attributionAlignment.ts）：原 length-based 尾部对齐在任一侧缺交易日时错位（agent_virtual 59 交易日仅 55 快照）；现于净值序列自己的日期对上取基准收益，缺端点如实降级；ok 拆为 complete/sufficient。
③fund-flow 响应 days 口径修复：days=请求窗口回显、returnedRows、dateRange（经 api_response 转驼峰）。线上：days=5 → returnedRows=30、dateRange=[''2026-07-30'',''2026-09-09'']、source=stale_cache。
④DSH 堆看门狗 AUTO_RESTART=1（6GB 阈值）——实例 RSS 实测 5 秒内 3.67→4.31GB，泄漏很快，自动重启同时会激活 ①②（agent-dh TS 改动需 DSH 重启生效）。
顺带发现（待跟进）：/api/simulation/performance 自带 data.max_drawdown=0.43 与风险口径 -1.83% 符号/量纲均不一致，读该字段做风控决策会得到反向信号。
