INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('a6624efc-daaa-4189-87a9-b18b9f7a68c1', '2026-09-11 分支问题处置（w-c8cae280）：实例工作区漂到 lifecycle 检查', '2026-09-11 分支问题处置（w-c8cae280）：实例工作区漂到 lifecycle 检查点分支 agent-self/20260911-014729 上，且另一窗口(w-f4aa1f6a)持续在该分支提交（c0ed9174 看板改动、6a95aa76 fund-flow/attribution/breaker 三处收口，后者把我的 P3 净值缺口探测一并提交了），导致 main 落后 2 个提交。处置方式（不动共享工作区、不打断他人）：①在隔离 worktree (/tmp/main-merge) 里对 main 做 --ff-only 快进合并 agent-self/20260911-014729 → main 到 6a95aa76；②再在隔离 worktree 里补提交我的测试断言（仅 tool-health-check.live.test.ts 两行）→ main 到 089e29a7；③全程未切换共享工作区分支、未触碰他人未提交文件（agent-os/internal/worker/notification_retry_worker.go、scripts/postrestart-verify.sh）。验证：合并后全量 404 passed / 2 failed，2 个失败为既有陈旧用例（RetailPanicIndexTool 期望 panic_index=null 但 b6397c8b 已改省略键；signal-track 期望 timeoutMs=30000 实际 10000），**合并未引入新失败**；main 已含 probeNavCoverage(P3)。关键经验：**共享工作区多窗口并发提交时，绝不在共享 index 里 git add -A**——我的 P3 改动正是被他人 commit 扫走的；需要更新主线时应走隔离 worktree + ff-only 合并，既不改共享工作区也不抢 index。残余状态：agent-self 落后 main 1 个提交（差异仅测试断言），实例重启时既有 boot-recovery 会『强行回干线』，因内容已全部进 main，该动作现在是安全的、不会丢东西。', 'experience', '{分支治理,多窗口并发,worktree,ff-only,w-c8cae280}', NULL, '''-09'':2A,12B ''-11'':3A,13B ''/20260911-014729'':24B,63B ''/attribution/breaker'':37B ''/internal/worker/notification_retry_worker.go'':82B ''/tmp/main-merge'':52B ''089e29'':75B ''1'':140B ''10000'':107B ''2'':45B,88B,90B ''2026'':1A,11B ''30000'':105B ''404'':86B ''6a95aa76'':33B,66B ''a'':120B ''a7'':76B ''add'':119B ''agent'':22B,61B,80B,136B ''agent-os'':79B ''agent-self'':21B,60B,135B ''b6397c8b'':98B ''boot'':145B ''boot-recovery'':144B ''c0ed9174'':31B ''c8cae280'':7A,17B ''commit'':124B ''f4aa1f6a'':29B ''failed'':89B ''ff'':57B,129B ''ff-only'':56B,128B ''flow'':36B ''fund'':35B ''fund-flow'':34B ''git'':118B ''index'':95B,116B,133B ''lifecycle'':9A,19B ''main'':43B,54B,64B,73B,109B,139B,150B ''null'':96B ''only'':58B,130B ''os'':81B ''p3'':40B,112B,122B ''panic'':94B ''passed'':87B ''probenavcoverage'':111B ''recovery'':146B ''retailpanicindextool'':92B ''scripts/postrestart-verify.sh'':83B ''self'':23B,62B,137B ''signal'':101B ''signal-track'':100B ''timeoutms'':104B ''tool-health-check.live.test.ts'':71B ''track'':102B ''w'':6A,16B,28B ''w-c8cae280'':5A,15B ''w-f4aa1f6a'':27B ''worktree'':51B,68B,127B ''三处收口'':38B ''上'':25B ''不会丢东西'':152B ''不动共享工作区'':48B ''不打断他人'':49B ''且另一窗口'':26B ''两行'':72B ''个失败为既有陈旧用例'':91B ''个提交'':46B,141B ''仅'':70B ''会'':147B ''但'':97B ''做'':55B ''全程未切换共享工作区分支'':77B ''共享工作区多窗口并发提交时'':114B ''关键经验'':113B ''再在隔离'':67B ''净值缺口探测一并提交了'':41B ''分支问题处置'':4A,14B ''到'':65B,74B ''合并'':131B ''合并后全量'':85B ''合并未引入新失败'':108B ''后者把我的'':39B ''因内容已全部进'':149B ''在隔离'':50B ''处置方式'':47B ''实例工作区漂到'':8A,18B ''实例重启时既有'':143B ''实际'':106B ''导致'':42B ''差异仅测试断言'':142B ''已含'':110B ''已改省略键'':99B ''强行回干线'':148B ''快进合并'':59B ''我的'':121B ''扫走的'':125B ''持续在该分支提交'':30B ''改动正是被他人'':123B ''既不改共享工作区也不抢'':132B ''期望'':93B,103B ''未触碰他人未提交文件'':78B ''检查'':10A ''检查点分支'':20B ''残余状态'':134B ''看板改动'':32B ''绝不在共享'':115B ''落后'':44B,138B ''该动作现在是安全的'':151B ''里'':117B ''里对'':53B ''里补提交我的测试断言'':69B ''需要更新主线时应走隔离'':126B ''验证'':84B', '2026-09-11 02:03:00.354876', '2026-09-11 02:03:00.354876', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('96e564b4-81a1-4f7f-815b-5cbf94edeb3a', '2026-09-11 账户最大回撤口径统一（提交 e020a76b）：simulation_acco', '2026-09-11 账户最大回撤口径统一（提交 e020a76b）：simulation_account.max_drawdown 此前由 paper_trading_engine.take_daily_snapshot 写「当日回撤」且取正号（实测 agent_virtual=+0.0043），而快照 drawdown 与 risk_metrics 是「负号峰谷最大回撤」（-1.83%）→ 读该字段处（quantsys_v2_status.balance）显示无意义值。现统一：repo.recompute_account_max_drawdown 以净值序列为唯一真源（峰谷口径、<=0、残缺行不参与、同步 peak_value），upsert 提交后自动调用；引擎当日回撤改负号且账户表改写峰谷最大回撤；daily_snapshot_service 两处不再自算 daily_return（交 repo，含成立资金剔除与无基准写 NULL）。历史校正 5 账户（agent_virtual 0.0043→-0.0183、v13 -0.4746→-0.1097、v14 -0.7145→-0.3975 等），脚本幂等。', 'knowledge', '{风控,最大回撤,口径统一,simulation_account,daily_return}', NULL, '''+0.0043'':27B ''-0.0183'':70B ''-0.1097'':73B ''-0.3975'':76B ''-0.4746'':72B ''-0.7145'':75B ''-09'':2A,10B ''-1.83'':35B ''-11'':3A,11B ''0'':46B ''0.0043'':69B ''2026'':1A,9B ''5'':65B ''acco'':8A ''account'':41B ''agent'':25B,67B ''daily'':19B,54B,58B ''drawdown'':16B,29B,43B ''e020a76b'':6A,14B ''max'':42B ''metrics'':32B ''null'':63B ''paper_trading_engine.take'':18B ''peak'':49B ''quantsys_v2_status.balance'':37B ''repo'':61B ''repo.recompute'':40B ''return'':59B ''risk'':31B ''service'':56B ''simulation'':7A ''simulation_account.max'':15B ''snapshot'':20B,55B ''upsert'':51B ''v13'':71B ''v14'':74B ''value'':50B ''virtual'':26B,68B ''与'':30B ''且取正号'':23B ''两处不再自算'':57B ''交'':60B ''以净值序列为唯一真源'':44B ''写'':21B ''历史校正'':64B ''同步'':48B ''含成立资金剔除与无基准写'':62B ''实测'':24B ''峰谷口径'':45B ''引擎当日回撤改负号且账户表改写峰谷最大回撤'':53B ''当日回撤'':22B ''提交'':5A,13B ''提交后自动调用'':52B ''是'':33B ''显示无意义值'':38B ''此前由'':17B ''残缺行不参与'':47B ''现统一'':39B ''等'':77B ''而快照'':28B ''脚本幂等'':78B ''读该字段处'':36B ''负号峰谷最大回撤'':34B ''账户'':66B ''账户最大回撤口径统一'':4A,12B', '2026-09-11 02:38:16.616994', '2026-09-11 02:38:16.616994', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('03a63649-7b82-4cdb-a547-86878c7db86f', '600887 neutral 同一指标被多处写入且符号相反：账户表 max_drawdown=+0.43%（当日、正号），快照与 risk_metrics 为 ', '600887 交易经验（2026-09-10T18:38:16.630Z）
