INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('edd00665-a5e7-4c7a-8fdd-2d84cb8cbf81', '2026-09-11 后端记忆检索修复（REQ-342799 P2 续，w-c8cae280，com', '2026-09-11 后端记忆检索修复（REQ-342799 P2 续，w-c8cae280，commit edf3ecd9）：【两个实现都只支持整串匹配】①HTTP /api/v1/memory/search 走的是 memory_web_repository.Search（不是 memory_repository.SearchBM25）——SQL 为 `title ILIKE $1 OR content ILIKE $1`，$1 = ''%整串查询%''；②memory_repository.SearchBM25 用 PostgreSQL FTS + ''english'' 配置（中文不分词），且 plainto_tsquery 把多词 AND 起来。二者共同导致『业绩归因』命中、『业绩归因 超额 beta alpha』0 命中、中文长句 0 命中。【修复】新增 splitQueryTerms/cjkQueryTerms/escapeLike（中英停用词 + LIKE 元字符转义 + 长中文句 4/3 字 n-gram，最多 12 个），两处均改为『按词/n-gram OR 子串匹配 + 按命中词数排序』；SearchBM25 保留 FTS 优先、零命中回退 OR。【构建坑】agent-os 由 launchd 跑**预编译二进制** bin/agent-os（scripts/serve-guard.sh），改源码后必须 `go build -o bin/agent-os ./cmd/agent-os` 再重启，否则 agent_os_restart 只是重启旧二进制（我第一次就踩了：重启后仍 0 命中）。已备份旧二进制 bin/agent-os.bak-wc41-20260911。【验证·真实服务】多词查询命中（返回 01:41 归因记忆）；含已知短语的长句命中；单关键词不变；不存在主题仍 0（正确行为）。【另一项排查】对 14 个只读工具做闭 schema 契约扫描，仅 risk_barra_decomposition『失败』且那是我自己设计的显式失败 → 说明 additionalProperties:false 这一类已被收敛，kline_daily_sync 是唯一漏网（已修）。', 'experience', '{后端修复,记忆检索,分词,agent-os,构建陷阱,w-c8cae280}', NULL, '''-09'':2A,14B ''-11'':3A,15B ''-342799'':6A,18B ''/api/v1/memory/search'':28B ''/cmd/agent-os'':113B ''/n-gram'':88B ''0'':66B,69B,122B,136B ''01'':130B ''1'':38B,42B,43B ''12'':84B ''14'':140B ''2026'':1A,13B ''4/3'':78B ''41'':131B ''additionalproperties'':151B ''agent'':100B,116B ''agent-os'':99B ''alpha'':65B ''and'':57B ''barra'':146B ''beta'':64B ''bin/agent-os'':106B,112B ''bin/agent-os.bak-wc41-20260911'':125B ''build'':110B ''c8cae280'':11A,23B ''com'':12A ''commit'':24B ''content'':40B ''daily'':155B ''decomposition'':147B ''edf3ecd9'':25B ''english'':50B ''false'':152B ''fts'':49B,94B ''go'':109B ''gram'':82B ''http'':27B ''ilike'':37B,41B ''kline'':154B ''launchd'':103B ''like'':75B ''memory'':32B,45B ''memory_web_repository.search'':30B ''n'':81B ''n-gram'':80B ''o'':111B ''or'':39B,89B,97B ''os'':101B,117B ''p2'':7A,19B ''plainto'':54B ''postgresql'':48B ''repository.searchbm25'':33B,46B ''req'':5A,17B ''restart'':118B ''risk'':145B ''schema'':142B ''scripts/serve-guard.sh'':107B ''searchbm25'':92B ''splitqueryterms/cjkqueryterms/escapelike'':73B ''sql'':34B ''sync'':156B ''title'':36B ''tsquery'':55B ''w'':10A,22B ''w-c8cae280'':9A,21B ''不存在主题仍'':135B ''不是'':31B ''且'':53B ''且那是我自己设计的显式失败'':149B ''业绩归因'':60B,62B ''两个实现都只支持整串匹配'':26B ''两处均改为'':86B ''个'':85B ''个只读工具做闭'':141B ''中文不分词'':52B ''中文长句'':68B ''中英停用词'':74B ''为'':35B ''二者共同导致'':59B ''仅'':144B ''优先'':95B ''保留'':93B ''修复'':71B ''元字符转义'':76B ''再重启'':114B ''单关键词不变'':134B ''另一项排查'':138B ''只是重启旧二进制'':119B ''后端记忆检索修复'':4A,16B ''否则'':115B ''含已知短语的长句命中'':133B ''命中'':61B,67B,70B,123B ''多词查询命中'':128B ''失败'':148B ''契约扫描'':143B ''子串匹配'':90B ''字'':79B ''对'':139B ''已修'':158B ''已备份旧二进制'':124B ''归因记忆'':132B ''我第一次就踩了'':120B ''把多词'':56B ''按命中词数排序'':91B ''按词'':87B ''改源码后必须'':108B ''整串查询'':44B ''新增'':72B ''是唯一漏网'':157B ''最多'':83B ''构建坑'':98B ''正确行为'':137B ''用'':47B ''由'':102B ''真实服务'':127B ''续'':8A,20B ''说明'':150B ''走的是'':29B ''起来'':58B ''超额'':63B ''跑'':104B ''返回'':129B ''这一类已被收敛'':153B ''配置'':51B ''重启后仍'':121B ''长中文句'':77B ''零命中回退'':96B ''预编译二进制'':105B ''验证'':126B', '2026-09-11 02:39:31.99971', '2026-09-11 02:39:31.99971', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('392c095a-d31a-4945-8e9d-10f99fcd5c5b', '【更正 · agent_virtual 归因 · 2026-09-11 02:45（来源 risk_', '【更正 · agent_virtual 归因 · 2026-09-11 02:45（来源 risk_metrics(days=60) 2026-09-11 02:44；R-013）】
先前 01:41 那份归因（超额 +7.67%，基准 -2.49%）**基于冻结的基准，数值作废**。
根因：quant.daily_klines 的 CSI300(000300) 只到 2026-08-27（304 行），而同期 000001/000905/个股均到 09-10
——基准掉了 9 个交易日，旧的长度对齐又把它错位拼接，于是"拿停在两周前的基准比出 2.5 个月窗口"。
已回补：000300 补到 09-10（304→314 行，08-27→09-10 无缺口），399001/399006 补到 09-10。
独立校验：000300 收盘 5059.658(06-22) → 4548.39(09-10) = -10.10%，与工具输出一致。
修正后同一口径（date-aligned，净值交易日 60、有效对数 57、区间 2026-06-22→2026-09-10）：
  组合 +5.2% | 基准 -10.1% | 超额 +15.3% | beta -0.0093 | alpha(年化) 21.72% | IR 2.81 | 最大回撤 -1.83%
保守解读不变：beta≈0（现金占比 87%）→ 超额主要来自低仓位结构，非选股能力；年化 alpha 在短样本+高现金下被放大。
遗留：①上证50(000016) 仍停在 09-03，同步通道对它无效；②净值序列含非交易日（08-08 周六）→ 57/59 对，对齐已如实标注。
机制教训：与基准比较的任何指标都必须先校验**基准序列的新鲜度**（本例基准比组合晚停 9 个交易日，且旧代码按长度对齐会把错位伪装成正常结果）。', 'knowledge', '{业绩归因,基准口径,000300,数据冻结,更正,REQ-342799}', NULL, '''+15.3'':116B ''+5.2'':112B ''+7.67'':38B ''-0.0093'':118B ''-013'':32B ''-03'':142B ''-06'':106B ''-08'':51B,146B ''-09'':6A,17B,27B,109B ''-1.83'':125B ''-10'':59B,72B,79B,84B,93B,110B ''-10.1'':114B ''-10.10'':94B ''-11'':7A,18B,28B ''-2.49'':40B ''-22'':90B,107B ''-27'':52B,77B ''0'':128B ''000001/000905'':56B ''000016'':139B ''000300'':48B,69B,86B ''01'':34B ''02'':8A,19B,29B ''06'':89B ''08'':76B,145B ''09'':58B,71B,78B,83B,92B,141B ''2.5'':66B ''2.81'':123B ''2026'':5A,16B,26B,50B,105B,108B ''21.72'':121B ''304'':53B,73B ''314'':74B ''399001/399006'':81B ''41'':35B ''44'':30B ''45'':9A,20B ''4548.39'':91B ''5059.658'':88B ''57'':103B ''57/59'':148B ''60'':25B,101B ''87'':130B ''9'':61B,155B ''agent'':2A,13B ''aligned'':99B ''alpha'':119B,134B ''beta'':117B,127B ''csi300'':47B ''date'':98B ''date-aligned'':97B ''days'':24B ''ir'':122B ''klines'':45B ''metrics'':23B ''quant.daily'':44B ''r'':31B ''risk'':11A,22B ''virtual'':3A,14B ''上证50'':138B ''与基准比较的任何指标都必须先校验'':152B ''与工具输出一致'':95B ''且旧代码按长度对齐会把错位伪装成正常结果'':157B ''个交易日'':62B,156B ''个月窗口'':67B ''个股均到'':57B ''于是'':64B ''仍停在'':140B ''保守解读不变'':126B ''修正后同一口径'':96B ''先前'':33B ''净值交易日'':100B ''净值序列含非交易日'':144B ''区间'':104B ''只到'':49B ''同步通道对它无效'':143B ''周六'':147B ''在短样本'':135B ''基于冻结的基准'':41B ''基准'':39B,113B ''基准序列的新鲜度'':153B ''基准掉了'':60B ''对'':149B ''对齐已如实标注'':150B ''已回补'':68B ''年化'':120B,133B ''归因'':4A,15B ''拿停在两周前的基准比出'':65B ''收盘'':87B ''数值作废'':42B ''无缺口'':80B ''旧的长度对齐又把它错位拼接'':63B ''更正'':1A,12B ''最大回撤'':124B ''有效对数'':102B ''本例基准比组合晚停'':154B ''机制教训'':151B ''来源'':10A,21B ''根因'':43B ''独立校验'':85B ''现金占比'':129B ''的'':46B ''组合'':111B ''而同期'':55B ''行'':54B,75B ''补到'':70B,82B ''超额'':37B,115B ''超额主要来自低仓位结构'':131B ''遗留'':137B ''那份归因'':36B ''非选股能力'':132B ''高现金下被放大'':136B', '2026-09-11 02:40:40.340526', '2026-09-11 02:40:40.340526', '{}');
