INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('6e293961-53d7-472a-9fab-598237887b8d', '2026-09-11 修复「机会→盯盘规则」空条件死规则（REQ-342799，w-c8cae280', '2026-09-11 修复「机会→盯盘规则」空条件死规则（REQ-342799，w-c8cae280）：【现象】watch_rules 中 13 条 conditions=[] 永不触发（10 条仍 enabled），created_by=opportunity_scan。【根因】①价格来源不存在——opportunity_scan 载荷无任何价格字段，而 _extract_current_price 只找 score_breakdown.technical.details.latest_price 与 reasons 里『当前价 X』，均不存在 → current_price 恒 None → entry_price 恒 None；②无条件下仍 create_rule → 每条自动规则一出生就是死的。**额外危害**：死规则还会命中『已存在启用规则』去重分支，阻塞该标的后续正常规则创建（601138 就是如此）。【修复】新增 _latest_close_from_db（载荷无价时回落日K线库取最新收盘，实测 601138 → 63.91），并在无条件下显式不建规则（返回 None + warning，调用处记 skipped）。【验证】本地：无K线→None+警告、有K线→建出 price_break 62.63（63.91×0.98）条件；线上真实 POST /api/signals/scan(auto_create_rules=true)：新规则 #137 条件 62.63，空条件规则数不再增长（13→13，enabled 10→0）。【存量清理】停用 10 条死规则（保留 trace 未删除）、删除测试残留 #136。【方法论】这是本 REQ 内第 N 次『功能看似在工作、实际产出无效物』——与信号账本被测试数据污染同源：**没有条件就不该创建对象**，与『宁可显式失败，不产假数据』同一纪律。', 'experience', '{盯盘规则,假监控,opportunity_scan,REQ-342799,w-c8cae280}', NULL, '''-09'':2A,14B ''-11'':3A,15B ''-342799'':9A,21B ''/api/signals/scan'':108B ''0'':122B ''0.98'':104B ''10'':33B,121B,125B ''13'':29B,118B,119B ''136'':131B ''137'':114B ''2026'':1A,13B ''601138'':75B,85B ''62.63'':102B,116B ''63.91'':86B,103B ''auto'':109B ''break'':101B ''by'':37B ''c8cae280'':12A,24B ''close'':80B ''conditions'':31B ''create'':67B,110B ''created'':36B ''current'':47B,58B ''db'':82B ''enabled'':35B,120B ''entry'':62B ''extract'':46B ''from'':81B ''latest'':79B ''n'':136B ''none'':61B,65B,89B,96B ''opportunity'':38B,42B ''post'':107B ''price'':48B,51B,59B,63B,100B ''reasons'':53B ''req'':8A,20B,134B ''rule'':68B ''rules'':27B,111B ''scan'':39B,43B ''score_breakdown.technical.details.latest'':50B ''skipped'':92B ''trace'':128B ''true'':112B ''w'':11A,23B ''w-c8cae280'':10A,22B ''warning'':90B ''watch'':26B ''x'':56B ''不产假数据'':144B ''与'':52B,142B ''与信号账本被测试数据污染同源'':140B ''中'':28B ''价格来源不存在'':41B ''保留'':127B ''修复'':4A,16B,77B ''停用'':124B ''内第'':135B ''删除测试残留'':130B ''功能看似在工作'':138B ''去重分支'':73B ''只找'':49B ''同一纪律'':145B ''均不存在'':57B ''存量清理'':123B ''宁可显式失败'':143B ''实测'':84B ''实际产出无效物'':139B ''就是如此'':76B ''已存在启用规则'':72B ''并在无条件下显式不建规则'':87B ''建出'':99B ''当前价'':55B ''恒'':60B,64B ''新增'':78B ''新规则'':113B ''方法论'':132B ''无k线'':95B ''无条件下仍'':66B ''有k线'':98B ''未删除'':129B ''本地'':94B ''机会'':5A,17B ''条'':30B ''条仍'':34B ''条件'':105B,115B ''条死规则'':126B ''根因'':40B ''次'':137B ''死规则还会命中'':71B ''每条自动规则一出生就是死的'':69B ''永不触发'':32B ''没有条件就不该创建对象'':141B ''现象'':25B ''盯盘规则'':6A,18B ''空条件死规则'':7A,19B ''空条件规则数不再增长'':117B ''线上真实'':106B ''而'':45B ''警告'':97B ''调用处记'':91B ''载荷无价时回落日k线库取最新收盘'':83B ''载荷无任何价格字段'':44B ''返回'':88B ''这是本'':133B ''里'':54B ''阻塞该标的后续正常规则创建'':74B ''额外危害'':70B ''验证'':93B', '2026-09-11 02:44:05.178841', '2026-09-11 02:44:05.178841', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('6c8a8842-05ec-44cf-bc07-a8f4197689ca', '2026-09-11 接管 K线 provider 事件处置结论（提交 c0a84aad）：①8 条', '2026-09-11 接管 K线 provider 事件处置结论（提交 c0a84aad）：①8 条 K线 provider 事件已由 w-f4aa1f6a 于 02:42 闭环（腾讯 data 形状假设 + akshare_broker signal 线程限制），我复核其修复并实测生效——TencentKlineProvider.get_klines(000001)→8 行；v2 02:43 重启后 02:31 批次未复发。②我另修一个独立缺陷：collector 把 "Traceback (most recent call last):" 当锚点，导致不同异常塌缩为同一条事件（62a2ae6f 累计 96 次、detail 只有栈头），且一次 traceback 产 2 条事件；现栈头并入 preamble、异常行作唯一锚点，孤儿栈块由 flushOrphanTraceback 兜底（带栈帧，指纹含栈不互相合并）。线上探针验证：3 行栈块→仅 1 条事件。③残留：AkshareBroker.get_history 不识别指数（000300 走股票接口→双失败异常），影响面限于回测/手工路径；指数 K 线实际走 /api/stock/{symbol}/klines 正常（200/8 行）。', 'knowledge', '{看板,K线,provider,traceback,collector,接管}', NULL, '''-09'':2A,13B ''-11'':3A,14B ''/api/stock'':100B ''/klines'':102B ''000001'':43B ''000300'':92B ''02'':30B,47B,50B ''1'':86B ''2'':72B ''200/8'':104B ''2026'':1A,12B ''3'':83B ''31'':51B ''42'':31B ''43'':48B ''62a2ae6f'':63B ''8'':10A,21B,44B ''96'':65B ''akshare'':36B ''aksharebroker.get'':89B ''broker'':37B ''c0a84aad'':9A,20B ''call'':59B ''collector'':54B ''data'':34B ''detail'':67B ''f4aa1f6a'':28B ''flushorphantraceback'':78B ''history'':90B ''k'':98B ''klines'':42B ''k线'':5A,16B,23B ''last'':60B ''most'':57B ''preamble'':75B ''provider'':6A,17B,24B ''recent'':58B ''signal'':38B ''symbol'':101B ''tencentklineprovider.get'':41B ''traceback'':56B,70B ''v2'':46B ''w'':27B ''w-f4aa1f6a'':26B ''不识别指数'':91B ''且一次'':69B ''事件处置结论'':7A,18B ''事件已由'':25B ''于'':29B ''产'':71B ''仅'':85B ''兜底'':79B ''双失败异常'':94B ''只有栈头'':68B ''孤儿栈块由'':77B ''导致不同异常塌缩为同一条事件'':62B ''带栈帧'':80B ''异常行作唯一锚点'':76B ''当锚点'':61B ''形状假设'':35B ''影响面限于回测'':95B ''我另修一个独立缺陷'':53B ''我复核其修复并实测生效'':40B ''手工路径'':96B ''批次未复发'':52B ''把'':55B ''指数'':97B ''指纹含栈不互相合并'':81B ''接管'':4A,15B ''提交'':8A,19B ''条'':11A,22B ''条事件'':73B,87B ''次'':66B ''正常'':103B ''残留'':88B ''现栈头并入'':74B ''累计'':