INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('6cc7c5f5-5bcd-4dc9-88e3-0fc4f8376a42', '【需求看板 w-1cee2467 2026-09-11】两个缺口的根因与修复。根因①状态不动：pro', '【需求看板 w-1cee2467 2026-09-11】两个缺口的根因与修复。根因①状态不动：protocol.SYSTEM_REQ_TRANSITIONS 只白名单 implementing>accepting 且代码零实现；需求建卡后无任何自动/工具入口能推进（agent 工具仅 create/status）；看板详情页 draft 无按钮；台账实证：11 条需求全部 draft（~/.dsh-agent-dh/dsh-reqboard.json 快照，2026-09-11 03:1x），每条 sourceSessionId 互不相同（分属 11 个并行窗口，delegationDepth=0），即"每窗口各建一条、谁都不推进"。根因②窗口关联不可见：host 落库写 sourceSessionId，但 client/types.ts 未声明、view.ts 只渲染 task.executions 的会话（无任务时什么都不显示）。修复：新增 host/rollup.ts（R0 启动对账 draft→reviewing、R1 绑定窗口人类消息→reviewing、R2 全任务done→accepting），SYSTEM_REQ_TRANSITIONS 扩为 {draft>reviewing, implementing>accepting}，人工闸门（确认方案/确认拆分/验收通过/归档）全部保留；路由在任务 create/move/update 同一笔 mutate 内派生推进（原子、单 revision）；新增 reqboard_move 工具（窗口推进自己绑定的需求，人工闸门/越权代码级拒绝）；client 卡片+详情渲染「窗口 w-xxxxxxxx」chip 可跳转会话，draft 补「提交评审」、reviewing 补「退回立项」。验证：pmboard 121 单测通过（含路由级集成：HTTP 全链路任务全完成→自动 accepting，done 仍需人点返回 human_gate 403）；真实台账副本 dry-run 11 条 draft 全部推进 reviewing（revision 243）。生效：client 刷新页面；host 需重启 13080。', 'knowledge', '{reqboard,dsh-pmboard,BUG,状态机,rollup,窗口关联,w-1cee2467,REQ-b02e99}', NULL, '''-09'':6A,17B,44B ''-11'':7A,18B,45B ''/.dsh-agent-dh/dsh-reqboard.json'':41B ''0'':55B ''03'':46B ''11'':38B,52B,147B ''121'':131B ''13080'':159B ''1cee2467'':4A,15B ''1x'':47B ''2026'':5A,16B,43B ''243'':153B ''403'':142B ''accepting'':27B,84B,92B,137B ''agent'':31B ''chip'':121B ''client'':114B,155B ''client/types.ts'':65B ''create/move/update'':100B ''create/status'':33B ''delegationdepth'':54B ''done'':138B ''draft'':35B,40B,77B,89B,123B,149B ''dry'':145B ''dry-run'':144B ''gate'':141B ''host'':61B,157B ''host/rollup.ts'':74B ''http'':134B ''human'':140B ''implementing'':26B,91B ''move'':109B ''mutate'':102B ''pmboard'':130B ''pro'':11A ''protocol.system'':22B ''r0'':75B ''r1'':79B ''r2'':82B ''req'':23B,86B ''reqboa