INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('e204b57b-220e-41ff-9ee1-bbfd0ec74fde', '【盘前决策 · 2026-09-11 08:31（事件 v2:pre_market_summary，', '【盘前决策 · 2026-09-11 08:31（事件 v2:pre_market_summary，触发 08:30:54；R-013 数据来源均已标注）】
