INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('f1cc4897-c820-4a07-851d-a47b5d981132', '2026-09-11（w-f4aa1f6a）"走 ORM 就没连接池问题"是误判：实测 v2 DB ', '2026-09-11（w-f4aa1f6a）"走 ORM 就没连接池问题"是误判：实测 v2 DB 连接池健康度 100%（事件 ed7d2f6a）的泄漏源是 model_train_auto 任务路径——_check_train_needed → ml_model_repository.get_by_type_version 取的是线程本地 scoped session，任务线程不调 close_session() 就一直占用连接，session_guard 看门狗实测 age_seconds=311（事件 a6780ec3，今日 14 次）。对照实验证明：仅走 repo 读一次，线程会话注册表仍持有同一 session（连接被占=True）；_check_train_needed 修复后注册表被清空（False=已释放）。修复：新增 _release_thread_session() 并在取数后调用（get_by_type_version 返回 plain dict，无惰性加载，释放安全），提交 003bc9ad。残留风险：4 处 psycopg2 直连绕过连接池（weekly_report_service/attribution_service/signal_test_log/signal_tracking_repository）。口径：ORM 只统一取连接入口，会话/事务生命周期仍归调用方。', 'experience', '{连接池,ORM,"idle in transaction",session_guard,model_train_auto}', NULL, '''-09'':2A,15B ''-11'':3A,16B ''003bc9ad'':91B ''100'':28B ''14'':59B ''2026'':1A,14B ''311'':55B ''4'':93B ''a6780ec3'':57B ''age'':53B ''auto'':34B ''by'':40B,82B ''check'':36B,69B ''close'':47B ''db'':13A,26B ''dict'':87B ''ed7d2f6a'':30B ''f4aa1f6a'':6A,19B ''false'':73B ''get'':81B ''guard'':51B ''ml_model_repository.get'':39B ''model'':32B ''needed'':38B,71B ''orm'':8A,21B,101B ''plain'':86B ''psycopg2'':95B ''release'':77B ''repo'':63B ''report'':98B ''scoped'':44B ''seconds'':54B ''service/attribution_service/signal_test_log/signal_tracking_repository'':99B ''session'':45B,48B,50B,66B,79B ''thread'':78B ''train'':33B,37B,70B ''true'':68B ''type'':41B,83B ''v2'':12A,25B ''version'':42B,84B ''w'':5A,18B ''w-f4aa1f6a'':4A,17B ''weekly'':97B ''事件'':29B,56B ''事务生命周期仍归调用方'':104B ''仅走'':62B ''今日'':58B ''任务线程不调'':46B ''任务路径'':35B ''会话'':103B ''修复'':75B ''修复后注册表被清空'':72B ''取的是线程本地'':43B ''口径'':100B ''只统一取连接入口'':102B ''处'':94B ''实测'':11A,24B ''对照实验证明'':61B ''就一直占用连接'':49B ''就没连接池问题'':9A,22B ''已释放'':74B ''并在取数后调用'':80B ''提交'':90B ''新增'':76B ''无惰性加载'':88B ''是误判'':10A,23B ''次'':60B ''残留风险'':92B ''的泄漏源是'':31B ''直连绕过连接池'':96B ''看门狗实测'':52B ''线程会话注册表仍持有同一'':65B ''读一次'':64B ''走'':7A,20B ''返回'':85B ''连接池健康度'':27B ''连接被占'':67B ''释放安全'':89B', '2026-09-11 12:30:23.655013', '2026-09-11 12:30:23.655013', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('bd8cbd81-7c4e-4b7c-900d-ddadf38b4bec', '2026-09-11 盯盘规则误判复盘与修复（w-c8cae280）：【误判】我依据 watch_l', '2026-09-11 盯盘规则误判复盘与修复（w-c8cae280）：【误判】我依据 watch_list 返回的 53 条规则 triggered_count 全 0，判断『盯盘引擎失效/33 条启用规则 0 触发/持仓无保护』并上报用户。【真相】跨源核验（GET /api/watch/triggers + watch_triggers 表）显示引擎完全正常：当日 40+ 次真实触发、notified=true，规则 #135（600150 price<39.25）在 09:31:52/09:37:49/09:42:56/09:48:16 触发 4 次。【根因】后端 /api/watch/rules 响应不含 triggered_count 字段（实测 16 个键无此键），WatchListTool.ts 用 `r?.triggered_count ?? r?.triggerCount ?? 0` 静默兜底为 0 → 把『字段缺失』伪装成『值为 0』。与既有教训『静默回退把没生效伪装成在工作』同源（此处是反向：把有生效伪装成没生效）。【教训】①任何『计数/状态』字段在使用前必须核验后端是否真的返回该键，禁止默认值兜底——默认值应显式标注不可用（null+说明）而非伪造数值；②工具层字段契约必须与后端响应键逐一比对（本次同批还修了 name/condition 恒 undefined、pnl_pct 渲染 undefined）；③『N 条规则 0 触发』这种全零统计本身就是可疑信号，应按跨源交叉验证处理（本次正是靠 watch_triggers 表推翻了结论）。【修复】client 新增 listWatchTriggers()；watch_list 统计真实触发次数并加 triggered_count_scope 标注窗口；查询失败置 null+说明不回落 0；pnl_pct 渲染读 ps.pct。【验证】真实后端端到端：#135=4、#105=10、#119=25、#21=15 等 20 条规则计数与 watch_triggers 逐一对账一致，undefined 渲染 0 处。', 'experience', '{盯盘引擎,静默兜底,假数据,工具契约,R-013,w-c8cae280,REQ-342799}', NULL, '''-09'':2A,13B ''-11'':3A,14B ''/33'':32B ''/api/watch/rules'':71B ''/api/watch/triggers'':41B ''0'':29B,34B,86B,88B,93B,120B,142B,165B ''09'':57B ''10'':152B ''105'':151B ''119'':153B ''135'':52B,149B ''15'':156B ''16'':65B,77B ''20'':158B ''2026'':1A,12B ''21'':155B ''25'':154B ''31'':58B ''37'':60B ''39.25'':55B ''4'':67B,150B ''40'':47B ''42'':62B ''48'':64B ''49/09'':61B ''52/09'':59B ''53'':24B ''56/09'':63B ''600150'':53B ''c8cae280'':7A,18B ''client'':129B ''count'':27B,74B,83B,136B ''get'':40B ''l'':11A ''list'':22B,133B ''listwatchtriggers'':131B ''n'':118B ''name/condition'':111B ''notified'':49B ''null'':106B,140B ''pct'':115B,144B ''pnl'':114B,143B ''price'':54B ''ps.pct'':146B ''r'':81B,84B ''scope'':137B ''triggercount'':85B ''triggered'':26B,73B,82B,135B ''triggers'':43B,126B,161B ''true'':50B ''undefined'':113B,117B,163B ''w'':6A,17B ''w-c8cae280'':5A,16B ''watch'':10A,21B,42B,125B,132B,160B ''watchlisttool.ts'':79B ''与既有教训'':94B ''个键无此键'':78B ''任何'':100B ''伪装成'':91B ''修复'':128B ''值为'':92B ''全'':28B ''判断'':30B ''同源'':96B ''后端'':70B ''响应不含'':72B ''在'':56B ''处'':166B ''字段'':75B ''字段在使用前必须核验后端是否真的返回该键'':103B ''字段缺失'':90B ''实测'':76B ''工具层字段契约必须与后端响应键逐一比对'':109B ''并上报用户'':37B ''应按跨源交叉验证处理'':123B ''当日'':46B ''恒'':112B ''我依据'':9A,20B ''把'':89B ''把有生效伪装成没生效'':98B ''持仓无保护'':36B ''教训'':99B ''新增'':130B ''显示引擎完全正常'':45B ''本次同批还修了'':110B ''本次正是靠'':124B ''条启用规则'':33B ''条规则'':25B,119B ''条规则计数与'':159B ''查询失败置'':139B ''标注窗口'':138B ''根因'':69B ''次'':68B ''次真实触发'':48B ''此处是反向'':97B ''渲染'':116B,164B ''渲染读'':145B ''状态'':102B ''用'':80B ''盯盘引擎失效'':31B ''盯盘规则误判复盘与修复'':4A,15B ''真实后端端到端'':148B ''真相'':38B ''禁止默认值兜底'':104B ''等'':157B ''统计真实触发次数并加'':134B ''而非伪造数值'':108B ''表'':44B ''表推翻了结论'':127B ''规则'':51B ''触发'':35B,66B,121B ''计数'':101B ''误判'':8A,19B ''说明'':107B ''说明不回落'':141B ''跨源核验'':39B ''返回的'':23B ''这种全零统计本身就是可疑信号'':122B ''逐一对账一致'':162B ''静默兜底为'':87B ''静默回退把没生效伪装成在工作'':95B ''验证'':147B ''默认值应显式标注不可用'':105B', '2026-09-11 12:48:52.123909', '2026-09-11 12:48:52.123909', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('3ecfb356-ed2f-4e5b-a88d-abc58a464e98', '2026-09-11（w-f4aa1f6a 步2）交易日判断收口 TradingDayGuard：交', '2026-09-11（w-f4aa1f6a 步2）交易日判断收口 TradingDayGuard：交易日判断此前散落 6+ 处、各自实现不同，同源三处伤——① 2026-08-08（周六）5 个账户被写入净值快照（agent_virtual/user_main/v13/v14/v15，02:00:09 写入），污染净值/回撤/熔断/归因口径（假熔断 -10.71% 那类事故的温床）；② quant.trading_calendar 建表后长期 **0 行**（无人写入），而 data_pipeline_service.load_trading_calendar_from_db 是 TimeAlignmentStage 的日历注入器 → 管道一直用空日历对齐且静默返回 set()；③ 2026-08-12 事故：以"当天日K是否落库"为唯一判据 → 06:30/14:30 调度永远判非交易日 → v13/v14 调仓从不执行却记 success。修复：新增 application/services/trading_day_guard.py（唯一实现=已被实战修正的 judge_trading_day 纯函数 + daily_klines 两条索引查询 0.2ms + 60s TTL 缓存 + 显式返回判定来源 source 与 degraded 标记；数据源不可用保守判非交易日）；收敛 7 处（daily_orchestrator tick/恢复检查、watch_engine 主循环、verification_job、kline_update_job stale 基准日、simulation_trader 三处、data_pipeline_service 空表回退+ERROR 留痕）；快照表加 chk_snapshot_no_weekend（周末行必须 is_synthetic）；5 条周末行标记 is_synthetic=true（保留审计痕迹、排除统计口径）；tools/refresh_trading_calendar.py 灌入日历 7718 交易日×3 交易所=23154 行（PK 由 (trade_date) 修为 (trade_date,exchange)，空表时自动改）。验证：新增 tests/test_trading_day_guard.py 14 例全绿；受影响测试 98 passed；load_trading_calendar_from_db 由空集→7718 天。提交 e6de5bad。教训：判断类逻辑必须单入口 + 必须能回答"凭什么这么判"（来源与降级可见），否则同一状态被多处赋相反含义（参见 w-50fc8c52 的生命周期教训）。', 'experience', '{交易日,TradingDayGuard,合成快照,trading_calendar,步2}', NULL, '''-08'':26B,27B,62B ''-09'':2A,12B ''-10.71'':42B ''-11'':3A,13B ''-12'':63B ''0'':47B ''0.2'':87B ''00'':34B ''02'':33B ''06'':68B ''09'':35B ''14'':159B ''2026'':1A,11B,25B,61B ''23154'':145B ''3'':143B ''30'':70B ''30/14'':69B ''5'':29B,132B ''50fc8c52'':183B ''6'':21B ''60s'':89B ''7'':99B ''7718'':141B,170B ''98'':162B ''agent'':31B ''application/services/trading_day_guard.py'':77B ''calendar'':45B,53B,166B ''chk'':125B ''daily'':84B,101B ''data'':118B ''data_pipeline_service.load'':51B ''date'':150B,153B ''day'':82B ''db'':55B,168B ''degraded'':95B ''e6de5bad'':173B ''engine'':106B ''error'':122B ''exchange'':154B ''f4aa1f6a'':6A,16B ''from'':54B,167B ''is'':130B,134B ''job'':109B,112B ''judge'':80B ''kline'':110B ''klines'':85B ''load'':164B ''ms'':88B ''no'':127B ''orchestrator'':102B ''passed'':163B ''pipeline'':119B ''pk'':147B ''quant.trading'':44B ''service'':120B ''set'':60B ''simulation'':115B ''snapshot'':126B ''source'':93B ''stale'':113B ''success'':74B ''synthetic'':131B,135B ''tests/test_trading_day_guard.py'':158B ''tick'':103B ''timealignmentstage'':57B ''tools/refresh_trading_calendar.py'':139B ''trade'':149B,152B ''trader'':116B ''trading'':52B,81B,165B ''tradingdayguard'':9A,19B ''true'':136B ''ttl'':90B ''update'':111B ''v13/v14'':72B ''verification'':108B ''virtual/user_main/v13/v14/v15'':32B ''w'':5A,15B,182B ''w-50fc8c52'':181B ''w-f4aa1f6a'':4A,14B ''watch'':105B ''weekend'':128B ''三处'':117B ''与'':94B ''两条索引查询'':86B ''个账户被写入净值快照'':30B ''为唯一判据'':67B ''主循环'':107B ''事故'':64B ''交'':10A ''交易所'':144B ''交易日'':142B ''交易日判断收口'':8A,18B ''交易日判断此前散落'':20B ''以'':65B ''例全绿'':160B ''保留审计痕迹'':137B ''修为'':151B ''修复'':75B ''假熔断'':41B ''写入'':36B ''凭什么这么判'':177B ''判断类逻辑必须单入口'':175B ''参见'':180B ''受影响测试'':161B ''各自实现不同'':23B ''同源三处伤'':24B ''否则同一状态被多处赋相反含义'':179B ''周六'':28B ''周末行必须'':129B ''唯一实现'':78B ''回撤'':38B ''基准日'':114B ''处'':22B,100B ''天'':171B ''已被实战修正的'':79B ''建表后长期'':46B ''归因口径'':40B ''当天日k是否落库'':66B ''必须能回答'':176B ''快照表加'':124B ''恢复检查'':104B ''排除统计口径'':138B ''提交'':172B ''收敛'':98B ''教训'':174B ''数据源不可用保守判非交易日'':97B ''新增'':76B,157B ''无人写入'':49B ''是'':56B ''显式返回判定来源'':92B ''条周末行标记'':133B ''来源与降级可见'':178B ''标记'':96B ''步2'':7A,17B ''污染净值'':37B ''灌入日历'':140B ''熔断'':39B ''由'':148B ''由空集'':169B ''留痕'':123B ''的日历注入器'':58B ''的生命周期教训'':184B ''空表回退'':121B ''空表时自动改'':155B ''管道一直用空日历对齐且静默返回'':59B ''纯函数'':83B ''缓存'':91B ''而'':50B ''行'':48B,146B ''调仓从不执行却记'':73B ''调度永远判非交易日'':71B ''那类事故的温床'':43B ''验证'':156B', '2026-09-11 12:58:46.742663', '2026-09-11 12:58:46.742663', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('0b8139fd-342c-4768-a0b3-291f5f7ecccd', '2026-09-11（w-f4aa1f6a 步3/步4）两项数据地基改造：① 步3 契约驱动监控：新', '2026-09-11（w-f4aa1f6a 步3/步4）两项数据地基改造：① 步3 契约驱动监控：新增 quant.data_contracts（11 条种子契约覆盖 daily_klines/index_daily/simulation_equity_snapshot/trading_calendar 等）+ tools/check_data_contracts.py（统一校验器，退出码 0/1/2，违约按 fingerprint 前缀 data-contract: upsert 进 error_events，全绿不刷屏）+ 32 测试。关键口径：market_latest 需设"完整性门槛"（默认 ≥500 行/日），否则盘中残留（2026-09-11 仅 18 行）会让所有数据集当天误判滞后；daily_klines 另走 expected_trading_day（墙钟+日历锚定）才能抓"K线自己冻住"的整体失明。② 步4 daily_klines 命名空间显式化：加 market varchar(8)（PG14 常量默认=免重写，465万行零停机）+ 回填 SH 187.9万/SZ 261.9万/BJ 15.7万（北交所新代码段 92xxxx 不匹配 ^[48]，首轮漏 156,892 行）+ 触发器自动推导（兜底 UNKNOWN 而非 RAISE，避免误伤测试夹具）+ 复合唯一索引 uq_daily_klines_symbol_market_date（CONCURRENTLY）。**未换主键**：勘查发现 daily_klines.symbol 已有外键指向 quant.stocks.symbol（外部键约束住符号空间），且换主键会打断 7 处 ON CONFLICT (symbol, trade_date) 原始 SQL → 保留原主键。坑：ORM 加字段后测试库 quant_test 旧 schema 会让 kline 测试报 UndefinedColumn（需对 quant_test 同跑迁移）；psycopg2 经 SQLAlchemy exec_driver_sql 下 DDL 时 % 会被当占位符（改原生 DBAPI 游标）；shell 里 $$ 会被展开成 PID（写 heredoc 文件）。提交 d58e8176/a84dfabc/dce3308b/bf913931/261be86a。', 'experience', '{数据契约,daily_klines,market,步3,步4}', NULL, '''-09'':2A,14B,60B ''-11'':3A,15B,61B ''/bj'':96B ''/sz'':93B ''0/1/2'':35B ''11'':27B ''15.7'':97B ''156'':104B ''18'':63B ''187.9'':91B ''2026'':1A,13B,59B ''261.9'':94B ''32'':47B ''465万行零停机'':88B ''48'':102B ''500'':55B ''7'':128B ''8'':84B ''892'':105B ''92xxxx'':100B ''concurrently'':120B ''conflict'':131B ''contract'':41B ''contracts'':26B ''d58e8176/a84dfabc/dce3308b/bf913931/261be86a'':174B ''daily'':29B,66B,78B,115B ''daily_klines.symbol'':123B ''data'':40B ''data-contract'':39B ''date'':119B,134B ''day'':71B ''dbapi'':164B ''ddl'':160B ''driver'':157B ''error'':44B ''events'':45B ''exec'':156B ''expected'':69B ''f4aa1f6a'':6A,18B ''fingerprint'':37B ''heredoc'':171B ''kline'':146B ''klines'':67B,79B,116B ''klines/index_daily/simulation_equity_snapshot/trading_calendar'':30B ''k线自己冻住'':75B ''latest'':51B ''market'':50B,82B,118B ''on'':130B ''orm'':139B ''pg14'':85B ''pid'':169B ''psycopg2'':153B ''quant'':141B,150B ''quant.data'':25B ''quant.stocks.symbol'':125B ''raise'':111B ''schema'':144B ''sh'':90B ''shell'':166B ''sql'':136B,158B ''sqlalchemy'':155B ''symbol'':117B,132B ''test'':142B,151B ''tools/check_data_contracts.py'':32B ''trade'':133B ''trading'':70B ''undefinedcolumn'':148B ''unknown'':109B ''upsert'':42B ''uq'':114B ''varchar'':83B ''w'':5A,17B ''w-f4aa1f6a'':4A,16B ''万'':92B,95B,98B ''下'':159B ''不匹配'':101B ''且换主键会打断'':127B ''两项数据地基改造'':9A,21B ''仅'':62B ''会被展开成'':168B ''会被当占位符'':162B ''会让'':145B ''会让所有数据集当天误判滞后'':65B ''保留原主键'':137B ''免重写'':87B ''兜底'':108B ''全绿不刷屏'':46B ''关键口径'':49B ''写'':170B ''前缀'':38B ''加'':81B ''加字段后测试库'':140B ''勘查发现'':122B ''北交所新代码段'':99B ''原始'':135B ''另走'':68B ''同跑迁移'':152B ''否则盘中残留'':58B ''命名空间显式化'':80B ''回填'':89B ''坑'':138B ''墙钟'':72B ''处'':129B ''复合唯一索引'':113B ''外部键约束住符号空间'':126B ''契约驱动监控'':11A,23B ''完整性门槛'':53B ''已有外键指向'':124B ''常量默认'':86B ''才能抓'':74B ''提交'':173B ''改原生'':163B ''文件'':172B ''新'':12A ''新增'':24B ''日'':57B ''日历锚定'':73B ''旧'':143B ''时'':161B ''未换主键'':121B ''条种子契约覆盖'':28B ''步3'':7A,10A,19B,22B ''步4'':8A,20B,77B ''测试'':48B ''测试报'':147B ''游标'':165B ''的整体失明'':76B ''等'':31B ''经'':154B ''统一校验器'':33B ''而非'':110B ''行'':56B,64B,106B ''触发器自动推导'':107B ''进'':43B ''违约按'':36B ''退出码'':34B ''避免误伤测试夹具'':112B ''里'':167B ''需对'':149B ''需设'':52B ''首轮漏'':103B ''默认'':54B', '2026-09-11 12:58:46.747197', '2026-09-11 12:58:46.747197', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('7ddfa4b9-2e11-4e18-8008-0b3ae51bbdf4', 'reminder agent-brain-realtime-check delivered', '{"task":"agent-brain-realtime-check","task_id":"974fa7b6-ce78-451b-a3da-c1cb314f6180","prompt":"你是 investor（PI 投资顾问·投资脑）。本任务是账户 agent_brain 的专属例行，只能作用于该账户。\n硬纪律：①全部账户查询/交易工具必须显式传 account_name=\"agent_brain\"（工具默认 agent_virtual，禁止作用错账户）；\n②交易宪法：仅 9:30-11:30/13:00-15:00 A股交易日可买卖、T+1（当日买次日卖）、买入 100 股整数倍、单股≤总资产 20%、单行业≤40%、现金≥10%、止损铁律（蓝筹-8%/成长-10%/题材-12%）；\n③买入前 regime_position_limit（R-006 档位映射，degraded 收紧到震荡档）+ risk_controller 算仓位；④信号 R-009 A/B/C 分级，C 级只观察不下单；\n⑤决策前 memory_search(namespace=experience) 检索历史教训（R-008）并在 reason 注明；⑥引用数据必须标注来源工具+数据时点（R-013，db 缓存不得冒充实时价）；\n⑦无信号/无动作时空仓等待是正确决策（宪法 6），不强求交易。\n\n【本任务】agent_brain 盘中快速检查（交易时段内）：\n1) market_alert(level=high) 看新告警；regime_position_limit 复核仓位余量（快速，异常才深查）。\n2) position_list + portfolio_analyze(account_name=\"agent_brain\")：逐只盈亏与止损/止盈距离；触发止损线的按宪法立即卖出（止损不手软、不补仓）；触发止盈预案的按预案执行或说明理由。\n3) 出现 A/B 级买入信号（≥2 维共振+基本面无雷+符合仓位余量）才可建仓，C 级或矛盾只记录观察（signal_track record），不委托。\n4) 仅做必要处置不刷屏；常规检查无动作时静默结束（正确决策），每次执行结束若有交易写 decision_audit(record, reason 引规则ID)。\n【汇报要求】仅当有实际交易/新告警/异常时 feishu_notify(channel=alerts, urgency=high) 标题【agent_brain 盘中处置】；常规无异常不发通知避免打扰。","window":"w-a8a89c6a","fired_at":"2026-09-11T05:00:00Z","delivered":true,"delivered_at":"2026-09-11T05:00:00.100Z","executor":{"mode":"direct","session_id":"session-8f2c4cc5-7000-4283-a08a-79dd68fcbd7d"}}', 'data', '{office:delivered,office:reminder:exec,office:reminder:w-8f2c4cc5}', NULL, '''+1'':56B ''-006'':81B ''-008'':103B ''-009'':90B ''-013'':110B ''-09'':201B,211B ''-10'':72B ''-11'':49B,202B,212B ''-12'':74B ''-15'':52B ''-4283'':226B ''-8'':70B ''00'':51B,53B,204B,214B ''00.100'':215B ''00z'':205B ''10'':67B ''100'':59B ''2'':157B ''20'':63B ''2026'':200B,210B ''30'':48B ''30/13'':50B ''40'':65B ''451b'':19B ''6'':117B ''7000'':225B ''79dd68fcbd7d'':229B '