INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('d170bb74-d019-4755-af59-aa2cd319796c', '600150 neutral 2026-09-11 盘前依据公告识别『青岛北海造船货轮火灾事故』事件风险，判定高位+突发利空不可追；当日盘中 -2.08%、最低', '600150 交易经验（2026-09-11T05:04:06.229Z）
