INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('ea6720c2-efa0-4fac-9017-0d762e943634', '2026-09-11（w-f4aa1f6a）DB 连接池被打满的真正根因：同步 job handle', '2026-09-11（w-f4aa1f6a）DB 连接池被打满的真正根因：同步 job handler 经 run_in_threadpool 执行在**线程池线程**里，而 close_session() 只清"当前线程"的 scoped 注册表 → 线程池线程长期存活，每个线程读一次 ORM 就把会话永久挂住。证据链：session_guard 实测告警 25 次、thread_name 多为 ThreadPoolExecutor-108_6 / -216_5 / -217_1，age_seconds 300-346；agent-os 侧事件 ed7d2f6a 记录池健康度 100%。修法：api/internal/scheduler_webhook.py 新增 _run_sync_handler_with_session_release()，在**执行线程内部**的 finally 里 close_session()（关键：从事件循环调 close_session() 清的是 asyncio 线程的注册表，无效）。对照实验（真实 DB 同线程）：直接执行=会话保持 True（连接被占）→ 经 wrapper=False（已释放）。回归测试 3 例含"handler 抛异常也必须释放"。提交 d84683fd。教训：会话泄漏排查必须看**线程归属**——同一份代码在事件循环线程与线程池线程里的生命周期完全不同；两个定点补丁（_check_train_needed、model_train_auto）都没打中，因为漏的是"线程池线程从来没被清理"这一层。', 'experience', '{连接池,线程池,session_guard,run_in_threadpool,根因}', NULL, '''-09'':2A,13B ''-108'':52B ''-11'':3A,14B ''-216'':54B ''-217'':56B ''-346'':61B ''1'':57B ''100'':68B ''2026'':1A,12B ''25'':46B ''3'':106B ''300'':60B ''5'':55B ''6'':53B ''age'':58B ''agent'':63B ''agent-os'':62B ''api/internal/scheduler_webhook.py'':70B ''asyncio'':90B ''auto'':122B ''check'':117B ''close'':31B,83B,87B ''d84683fd'':111B ''db'':7A,18B,95B ''ed7d2f6a'':66B ''f4aa1f6a'':6A,17B ''false'':103B ''finally'':81B ''guard'':44B ''handle'':11A ''handler'':22B,74B,108B ''in'':25B ''job'':10A,21B ''model'':120B ''name'':49B ''needed'':119B ''orm'':40B ''os'':64B ''release'':77B ''run'':24B,72B ''scoped'':36B ''seconds'':59B ''session'':32B,43B,76B,84B,88B ''sync'':73B ''thread'':48B ''threadpool'':26B ''threadpoolexecutor'':51B ''train'':118B,121B ''true'':99B ''w'':5A,16B ''w-f4aa1f6a'':4A,15B ''with'':75B ''wrapper'':102B ''两个定点补丁'':116B ''从事件循环调'':86B ''会话保持'':98B ''会话泄漏排查必须看'':113B ''例含'':107B ''侧事件'':65B ''修法'':69B ''关键'':85B ''只清'':33B ''同一份代码在事件循环线程与线程池线程里的生命周期完全不同'':115B ''同步'':9A,20B ''同线程'':96B ''回归测试'':105B ''因为漏的是'':124B ''在'':78B ''多为'':50B ''实测告警'':45B ''对照实验'':93B ''就把会话永久挂住'':41B ''已释放'':104B ''当前线程'':34B ''执行在'':27B ''执行线程内部'':79B ''抛异常也必须释放'':109B ''提交'':110B ''教训'':112B ''新增'':71B ''无效'':92B ''次'':47B ''每个线程读一次'':39B ''注册表'':37B ''清的是'':89B ''的'':35B,80B ''直接执行'':97B ''真实'':94B ''线程归属'':114B ''线程池线程'':28B ''线程池线程从来没被清理'':125B ''线程池线程长期存活'':38B ''线程的注册表'':91B ''经'':23B,101B ''而'':30B ''记录池健康度'':67B ''证据链'':42B ''这一层'':126B ''连接池被打满的真正根因'':8A,19B ''连接被占'':100B ''都没打中'':123B ''里'':29B,82B', '2026-09-11 13:37:49.615981', '2026-09-11 13:37:49.615981', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('86100404-171e-47c9-bc21-fe9e7bd387dd', '2026-09-11（w-f4aa1f6a）两个 agent-os 侧修复与一次自造事故：① 投递可', '2026-09-11（w-f4aa1f6a）两个 agent-os 侧修复与一次自造事故：① 投递可靠性——webhook 投递只有内存重试（MaxRetries=2，连接失败递增退避≈90s），DSH 长时间不可达即丢任务。新增 task_delivery_backlog 表 + TaskDeliveryRetryWorker（60s 巡检、指数退避 30s→30m、最多 10 次、跨重启不丢；只对 IsConnectionFailure 入队）。端到端实测：死端口任务 → 积压行 pending(attempts=1) → 接收端恢复后自动补投 delivered(attempts=2) 且接收端真实收到报文；残留已清。提交 8deb6bbd。② 任务加载 NULL 容错——我用 SQL 插入测试任务时省略 command/schedule（NULL），导致 agent-os **整个起不来**（failed to load tasks: cannot scan NULL into *string）。已将 task_repository 全部 5 处查询的可空列 COALESCE。负向验证：库里保留 NULL 行时服务 health=200、任务列表接口 200（修复前启动即崩/接口 500）。教训：往生产库插测试数据必须走与代码一致的写入路径（或补齐全部 NOT NULL 语义字段）；同时暴露"单条脏数据能打崩调度器启动"这一设计脆弱点。', 'experience', '{投递可靠性,task_delivery_backlog,NULL容错,自造事故}', NULL, '''-09'':2A,14B ''-11'':3A,15B ''1'':56B ''10'':45B ''2'':28B,60B ''200'':99B,101B ''2026'':1A,13B ''30m'':43B ''30s'':42B ''5'':91B ''500'':104B ''60s'':39B ''8deb6bbd'':64B ''90s'':30B ''agent'':9A,21B,75B ''agent-os'':8A,20B,74B ''attempts'':55B,59B ''backlog'':36B ''cannot'':82B ''coalesce'':93B ''command/schedule'':71B ''delivered'':58B ''delivery'':35B ''dsh'':31B ''f4aa1f6a'':6A,18B ''failed'':78B ''health'':98B ''into'':85B ''isconnectionfailure'':49B ''load'':80B ''maxretries'':27B ''not'':108B ''null'':66B,72B,84B,96B,109B ''os'':10A,22B,76B ''pending'':54B ''repository'':89B ''scan'':83B ''sql'':69B ''string'':86B ''task'':34B,88B ''taskdeliveryretryworker'':38B ''tasks'':81B ''to'':79B ''w'':5A,17B ''w-f4aa1f6a'':4A,16B ''webhook'':25B ''且接收端真实收到报文'':61B ''两个'':7A,19B ''任务列表接口'':100B ''任务加载'':65B ''侧修复与一次自造事故'':11A,23B ''修复前启动即崩'':102B ''入队'':50B ''全部'':90B ''单条脏数据能打崩调度器启动'':112B ''只对'':48B ''同时暴露'':111B ''处查询的可空列'':92B ''容错'':67B ''导致'':73B ''巡检'':40B ''已将'':87B ''库里保留'':95B ''往生产库插测试数据必须走与代码一致的写入路径'':106B ''我用'':68B ''或补齐全部'':107B ''投递只有内存重试'':26B ''投递可'':12A ''投递可靠性'':24B ''指数退避'':41B ''接口'':103B ''接收端恢复后自动补投'':57B ''提交'':63B ''插入测试任务时省略'':70B ''教训'':105B ''整个起不来'':77B ''新增'':33B ''最多'':44B ''次'':46B ''死端口任务'':52B ''残留已清'':62B ''积压行'':53B ''端到端实测'':51B ''行时服务'':97B ''表'':37B ''语义字段'':110B ''负向验证'':94B ''跨重启不丢'':47B ''这一设计脆弱点'':113B ''连接失败递增退避'':29B ''长时间不可达即丢任务'':32B', '2026-09-11 13:37:49.634484', '2026-09-11 13:37:49.634484', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('377abce5-a018-4398-82f3-e6fa91d0787a', '2026-09-11 删除遗留调度表 scheduler_task_configs（w-f436d4', '2026-09-11 删除遗留调度表 scheduler_task_configs（w-f436d4ea，commit 见下）：用户确认「没用就删」。实证安全后执行——该表 12 行全 disabled、运行时无任何 SELECT/ORM 读取、无外键、2026-08-13 迁移已完成且失传任务已在新系统重建。处置：先归档到 quant.scheduler_task_configs_archive_20260911（11 行可恢复）再 DROP TABLE。删除后验证：live scheduler_tasks 完好（31 任务）、fund_flow_update(308) next_run_at=2026-09-11 15:30+08:00（时区修复生效）、后端 health 200。同时更正 4 个 job 文件指向已删表的过期 docstring。注意：覆盖了 2026-08-13 迁移脚本当年「表保留不删、回滚可 flip」的决定——已归档所以仍可回滚。【关键操作纪律】共享生产库的删除=先实证无运行时依赖+无外键，再归档，最后删，删后立即验证 live 系统完好。', 'knowledge', '{w-f436d4ea,scheduler,删表,scheduler_task_configs,归档}', NULL, '''+08'':69B ''-08'':35B,84B ''-09'':2A,12B,65B ''-11'':3A,13B,66B ''-13'':36B,85B ''00'':70B ''11'':45B ''12'':27B ''15'':67B ''200'':74B ''2026'':1A,11B,34B,64B,83B ''20260911'':44B ''30'':68B ''308'':60B ''31'':55B ''4'':76B ''archive'':43B ''at'':63B ''commit'':21B ''configs'':7A,17B,42B ''disabled'':29B ''docstring'':80B ''drop'':48B ''f436d4'':10A ''f436d4ea'':20B ''flip'':89B ''flow'':58B ''fund'':57B ''health'':73B ''job'':78B ''live'':51B,99B ''next'':61B ''quant.scheduler'':40B ''run'':62B ''scheduler'':5A,15B,52B ''select/orm'':31B ''table'':49B ''task'':6A,16B,41B ''tasks'':53B ''update'':59B ''w'':9A,19B ''w-f436d4'':8A ''w-f436d4ea'':18B ''个'':77B ''任务'':56B ''先实证无运行时依赖'':94B ''先归档到'':39B ''共享生产库的删除'':93B ''关键操作纪律'':92B ''再'':47B ''再归档'':96B ''删后立即验证'':98B ''删除后验证'':50B ''删除遗留调度表'':4A,14B ''同时更正'':75B ''后端'':72B ''回滚可'':88B ''处置'':38B ''完好'':54B ''实证安全后执行'':25B ''已归档所以仍可回滚'':91B ''文件指向已删表的过期'':79B ''无外键'':33B,95B ''时区修复生效'':71B ''最后删'':97B ''没用就删'':24B ''注意'':81B ''用户确认'':23B ''的决定'':90B ''系统完好'':100B ''行全'':28B ''行可恢复'':46B ''表保留不删'':87B ''覆盖了'':82B ''见下'':22B ''该表'':26B ''读取'':32B ''迁移已完成且失传任务已在新系统重建'':37B ''迁移脚本当年'':86B ''运行时无任何'':30B', '2026-09-11 13:49:30.182688', '2