INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('4f6ed5b1-bf94-40f9-bbcb-46250a87ddac', '2026-09-11 调度时区与双注册根治（w-f436d4ea，commit 74dadd2e）：', '2026-09-11 调度时区与双注册根治（w-f436d4ea，commit 74dadd2e）：【next_run_at +8h】根因=infrastructure/scheduler/scheduler.py 的 next_run_time() 用 datetime.now(timezone.utc) 在 UTC 下匹配 cron，但 cron 全是北京时间语义（A 股 9:30/15:00），且生产真实派发器是 APSchedulerService(timezone=''Asia/Shanghai'')（main.py:180 启动）——所以 next_run_at 比北京时间晚 8h（真实 15:30 显示 23:30）。安全性判定：scheduler.py 的旧 UTC 轮询 run_due_tasks 未在生产启动，next_run_time 只喂显示列，改时区不影响实际触发。修复=next_run_time 改用 ZoneInfo(''Asia/Shanghai'')，实测 ''30 15 * * 1-5'' → 15:30 CST+0800；PUT 重算后 task 308 next_run_at=2026-09-11T15:30:00+08:00（原 23:30）。存量行在各自下次运行/更新时自愈。【双调度注册】scheduler_task_configs 表 12 行全部 is_enabled=false、运行时无任何 SELECT/ORM 读取（属 2026-08 迁移后的遗留），权威在 quant.scheduler_tasks（APScheduler 派发）。处置=给该表加 COMMENT ON TABLE 标注 LEGACY 并指向 scheduler_tasks（不动数据、不删表——历史上直接禁用此表曾致任务失传）。注意：scheduler_task_configs 里 fund_flow_update 的 cron 本来就是 30 15（15:30），与我刚改的 live 值一致，互为印证。', 'knowledge', '{w-f436d4ea,scheduler,时区,next_run_at,双注册,cron}', NULL, '''+08'':106B ''+0800'':92B ''+8'':22B ''-08'':128B ''-09'':2A,11B,101B ''-11'':3A,12B,102B ''-5'':88B ''00'':44B,105B,107B ''1'':87B ''12'':118B ''15'':58B,86B,89B,160B,161B ''2026'':1A,10B,100B,127B ''23'':61B,109B ''30'':59B,62B,85B,90B,104B,110B,159B,162B ''30/15'':43B ''308'':96B ''74dadd2e'':9A,18B ''8h'':56B ''9'':42B ''a'':40B ''apscheduler'':133B ''apschedulerservice'':46B ''asia/shanghai'':48B,83B ''at'':21B,54B,99B ''comment'':137B ''commit'':8A,17B ''configs'':116B,151B ''cron'':36B,38B,157B ''cst'':91B ''datetime.now'':31B ''due'':69B ''enabled'':121B ''f436d4ea'':7A,16B ''false'':122B ''flow'':154B ''fund'':153B ''h'':23B ''infrastructure/scheduler/scheduler.py'':25B ''is'':120B ''legacy'':141B ''live'':164B ''main.py:180'':49B ''next'':19B,27B,52B,72B,78B,97B ''on'':138B ''put'':93B ''quant.scheduler'':131B ''run'':20B,28B,53B,68B,73B,79B,98B ''scheduler'':114B,143B,149B ''scheduler.py'':64B ''select/orm'':124B ''t15'':103B ''table'':139B ''task'':95B,115B,150B ''tasks'':70B,132B,144B ''time'':29B,74B,80B ''timezone'':47B ''timezone.utc'':32B ''update'':155B ''utc'':34B,66B ''w'':6A,15B ''w-f436d4ea'':5A,14B ''zoneinfo'':82B ''下匹配'':35B ''不删表'':146B ''不动数据'':145B ''与我刚改的'':163B ''且生产真实派发器是'':45B ''互为印证'':166B ''但'':37B ''修复'':77B ''值一致'':165B ''全是北京时间语义'':39B ''历史上直接禁用此表曾致任务失传'':147B ''原'':108B ''双调度注册'':113B ''只喂显示列'':75B ''启动'':50B ''在'':33B ''处置'':135B ''存量行在各自下次运行'':111B ''安全性判定'':63B ''实测'':84B ''属'':126B ''并指向'':142B ''所以'':51B ''改时区不影响实际触发'':76B ''改用'':81B ''显示'':60B ''更新时自愈'':112B ''未在生产启动'':71B ''本来就是'':158B ''权威在'':130B ''标注'':140B ''根因'':24B ''比北京时间晚'':55B ''注意'':148B ''派发'':134B ''用'':30B ''的'':26B,156B ''的旧'':65B ''真实'':57B ''给该表加'':136B ''股'':41B ''行全部'':119B ''表'':117B ''读取'':125B ''调度时区与双注册根治'':4A,13B ''轮询'':67B ''迁移后的遗留'':129B ''运行时无任何'':123B ''里'':152B ''重算后'':94B', '2026-09-11 13:40:51.197356', '2026-09-11 13:40:51.197356', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('9c159f1a-e737-43a4-a6d8-44bb40f47fd3', 'reminder intraday-surge-scan-pm delivered', '{"task":"intraday-surge-scan-pm","task_id":"a3e404a9-cc8c-4352-b472-48684d5b796c","prompt":"【午后异动扫描 13:45】目的：看午后资金转向、捕捉上午漏掉的启动、为次日预案备料；无真信号不打扰。执行：1) data_fetch_market_sentiment 看情绪/涨跌家数是否延续上午；2) sector_analysis(days=1)看板块涨幅榜 vs 上午(memory/上午速报)对比→午后新启动/加强板块；3) limit_up_pool(今日)看炸板/新增涨停，午后封板股=资金态度；4) 若上午已发过速报→验证该板块午后是否延续(回踩/加强)，加强则更新signal_track，证伪则记录修正教训(experience_write级别低,memory即可)；5) 对新启动板块重复上午的验证流程(成分→2-3龙头→三维→分级→落库)；6) 次日预案：对A/B级候选标注''明日触发价位+确认条件''(上破哪、需什么量能/资金确认)，写 memory_write(analysis) 供盘前例程9:25取用；7) 输出：有新增A/B级或持仓午后急变→feishu_notify(normal,reports)；否则memory一句即止；8) 纪律同上午：数据带来源时点(R-013)、euphoria不追高、候选必落signal_track、持仓股异动优先high告警(600036/601600/000807/002007/002463/600026等)。","window":"w-5b8aac2a","fired_at":"2026-09-11T05:45:00Z","delivered":true,"delivered_at":"2026-09-11T05:45:00.110Z","executor":{"mode":"direct","session_id":"session-8f2c4cc5-7000-4283-a08a-79dd68fcbd7d"}}', 'data', '{office:delivered,office:reminder:exec,office:reminder:w-8f2c4cc5}', NULL, '''-013'':112B ''-09'':126B,136B ''-11'':127B,137B ''-3'':77B ''-4283'':151B ''/b'':85B,101B ''00.110'':140B ''00z'':130B ''1'':33B,44B ''13'':25B ''2'':40B,76B ''2026'':125B,135B ''25取用'':97B ''3'':53B ''4'':62B ''4352'':19B ''45'':26B,129B,139B ''48684d5b796c'':22B ''5'':73B ''5b8aac2a'':122B ''6'':82B ''600036/601600/000807/002007/002463/600026'':117B ''7'':98B ''7000'':150B ''79dd68fcbd7d'':154B ''8'':108B ''8f2c4cc5'':149B ''a08a'':153B ''a08a-79dd68fcbd7d'':152B ''a3e404a9'':17B ''a3e404a9-cc8c'':16B ''analysis'':42B,95B ''at'':124B,134B ''b472'':21B ''b472-48684d5b796c'':20B ''cc8c'':18B ''data'':34B ''days'':43B ''delivered'':7A,131B,133B ''direct'':144B ''euphoria不追高'':113B ''executor'':142B ''experience'':70B ''feishu'':103B ''fetch'':35B ''fired'':123B ''id'':15B,146B ''intraday'':3