INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('14d71d98-d2e5-48e4-ab6a-e73d715a1f06', '000300 neutral 2026-09-11 盘后复盘：账户风险指标可算，但基准（沪深300）数据滞后到 09-10 而组合已到 09-11，工具如实标注', '000300 交易经验（2026-09-11T08:31:11.491Z）
