INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('5c071e27-fcc8-4dc9-8343-4a8651a50e32', '2026-09-11 盯盘闭环 P4+P7 交付（REQ-f08def，RFC 014 v3 §3.', '2026-09-11 盯盘闭环 P4+P7 交付（REQ-f08def，RFC 014 v3 §3.3/§13，w-c8cae280）【P4 介入记账】新增 quant.watch_interventions 表 + intervention_ledger.py：每次 escalated 落一条（规则/标的/意图/类型/结果/触发id/成本/审计id）；每日预算计数改为从库读取（引擎每 tick 刷新一次）——修掉『计数在进程内存→重启清零→预算形同虚设』（实测 escalated 冲到 18 vs 预算 8）；提供 summary_today() 算单位唤醒产出。【P7 元触发复核】新增 meta_review_service.py（引擎 loop 内每日一次）：四类元触发 burst(一直响)/idle(一直不响)/stage(阶段滞留)/expiry(快到期)，命中即落 meta_review 触发（复用 watch_triggers 流转→进未处置清单→被摘要唤醒带走）并更新 last_reviewed_at/review_due_at；复核周期按意图：持仓类3天/等买7天/观察14天。真实扫描 21 条启用规则生成 9 条复核项（规则129 601600 单日21次触发=频次超限、规则105 600737 16次、规则58 002007 静默16天）。【两处自身缺陷】①**ORM 与迁移不同步**：migration 加列但 WatchRule ORM 未声明 → intent/scope/价值账本对 ORM 不可见、update_fields 不落库（#120 改 entry 看似成功库里仍旧值）；且第一次补列时锚点 agent_response 在 WatchTrigger 里也有→插错类（Float 未导入直接 NameError）。教训：ORM 必须与迁移同步声明；补列脚本必须做锚点唯一性断言 ②ledger.summary_today 的 SQL 被三引号包成字符串→语法错。【验证】84 passed/0 failed（含 6 个元触发新测试）；测试库需补打三个迁移（此前只打生产，ORM 补列后测试库报缺列）。剩余 P5 成交联动 / P6 市场级盯盘 / P8 飞书设计。', 'experience', '{盯盘闭环,P4,P7,元触发,介入记账,ORM与迁移不同步,w-c8cae280}', NULL, '''-09'':2A,16B ''-11'':3A,17B ''/expiry'':84B ''/idle'':80B ''/stage'':82B ''002007'':117B ''014'':12A,26B ''120'':134B ''13'':29B ''16次'':115B ''18'':62B ''2026'':1A,15B ''21'':105B ''3'':14A ''3.3'':28B ''6'':163B ''600737'':114B ''601600'':110B ''8'':65B ''84'':159B ''9'':107B ''agent'':139B ''at/review_due_at'':99B ''burst'':78B ''c8cae280'':32B ''entry'':136B ''escalated'':41B,60B ''f08def'':10A,24B ''failed'':161B ''fields'':132B ''float'':145B ''intent/scope'':127B ''intervention_ledger.py'':39B ''interventions'':37B ''last'':97B ''ledger.summary'':152B ''loop'':75B ''meta'':87B ''meta_review_service.py'':73B ''migration'':122B ''nameerror'':147B ''orm'':120B,125B,129B,149B,167B ''p4'':5A,19B,33B ''p5'':170B ''p6'':172B ''p