INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('85b59101-d344-4f52-aebf-e20b535356c9', '2026-09-11 并发提交事故复盘（w-f436d4ea，连环两次错误）：【错1】cc42c38', '2026-09-11 并发提交事故复盘（w-f436d4ea，连环两次错误）：【错1】cc42c38b 提交 RFC 文档时，误带入其他窗口已 stage 在索引中的删除（watch-digest-gate.sh / watch-hygiene-audit.py）。根因：只执行了 add 自己的文件 + commit，未校验索引里是否已有他人 staged 改动。【错2】发现后立刻还原，但没先看是否有更新的提交——595d6e0c（w-c8cae280，与我第二次提交相隔<1分钟）已明确说明该删除是其重构的一部分（脚本→引擎内置 digest_service.py；卫生审计与 _job_watch_rule_health 重复），即删除是正确的，我反而复活了对方刻意移除的文件，再补一次 945f2b8c 重新删除才回到正确终态。【教训】① 提交前必须核对 staged 内容（git diff --cached --name-only），出现非本任务改动即停手；② 并发写同一仓库时，同分钟内的提交是信息盲区——纠正他人改动前必须 git log --since 看最新提交是否已说明意图，不能只看自己 commit 的 diff；③ 过度纠正也是一种破坏：先取证再动手。提交序列：87521c74(我的RFC) → cc42c38b(误带删除) → 595d6e0c(对方重构并说明删除) → 9d068245(我误还原) → 945f2b8c(重新删除，终态正确)。', 'experience', '{w-f436d4ea,并发提交,git纪律,事故复盘,过度纠正,staged}', NULL, '''-09'':2A,12B ''-11'':3A,13B ''1分钟'':45B ''2026'':1A,11B ''595d6e0c'':40B,90B ''87521c74'':86B ''945f2b8c'':59B,94B ''9d068245'':92B ''add'':31B ''c8cae280'':43B ''cached'':67B ''cc42c38'':10A ''cc42c38b'':20B,88B ''commit'':33B,80B ''diff'':66B,82B ''digest_service.py'':49B ''f436d4ea'':7A,17B ''git'':65B,75B ''health'':54B ''job'':51B ''log'':76B ''name'':69B ''name-only'':68B ''only'':70B ''rfc'':22B ''rule'':53B ''since'':77B ''stage'':25B ''staged'':35B,63B ''w'':6A,16B,42B ''w-c8cae280'':41B ''w-f436d4ea'':5A,15B ''watch'':52B ''watch-digest-gate.sh'':27B ''watch-hygiene-audit.py'':28B ''不能只看自己'':79B ''与我第二次提交相隔'':44B ''但没先看是否有更新的提交'':39B ''先取证再动手'':84B ''内容'':64B ''再补一次'':58B ''出现非本任务改动即停手'':71B ''卫生审计与'':50B ''即删除是正确的'':56B ''发现后立刻还原'':38B ''只执行了'':30B ''同分钟内的提交是信息盲区'':73B ''在索引中的删除'':26B ''对方重构并说明删除'':91B ''已明确说明该删除是其重构的一部分'':46B ''并发写同一仓库时'':72B ''并发提交事故复盘'':4A,14B ''引擎内置'':48B ''我反而复活了对方刻意移除的文件'':57B ''我的rfc'':87B ''我误还原'':93B ''提交'':21B ''提交前必须核对'':62B ''提交序列'':85B ''改动'':36B ''教训'':61B ''文档时'':23B ''未校验索引里是否已有他人'':34B ''根因'':29B ''的'':81B ''看最新提交是否已说明意图'':78B ''纠正他人改动前必须'':74B ''终态正确'':96B ''脚本'':47B ''自己的文件'':32B ''误带入其他窗口已'':24B ''误带删除'':89B ''过度纠正也是一种破坏'':83B ''连环两次错误'':8A,18B ''重复'':55B ''重新删除'':95B ''重新删除才回到正确终态'':60B ''错1'':9A,19B ''错2'':37B', '2026-09-11 18:48:42.837646', '2026-09-11 18:48:42.837646', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('11155895-a471-4211-ac61-5f08e5a90472', '2026-09-11 晚间（w-f4aa1f6a）两组修复：① 用户报错"K线/因子新鲜度巡检 错误', '2026-09-11 晚间（w-f4aa1f6a）两组修复：① 用户报错"K线/因子新鲜度巡检 错误: name ''kline_latest'' is not defined"——根因是 2026-09-10 把 K 线判据从"全局 max(trade_date)"改为"按标的覆盖度巡检"时，_job_freshness_guard 两处 return 遗留 str(kline_latest)（变量已不存在）。隐蔽性极强：**只在"数据新鲜"这条正常分支崩**，滞后（异常）分支不受影响，所以每天 17:20 正常态必抛而长期无人发现（错误事件 7460c6b7/ddea89ea）。修法：改报覆盖度事实 kline_coverage/kline_stale/kline_oldest_stale，并同步 _summarize_result 摘要键；新增 tests/test_freshness_guard.py 4 例覆盖三条分支（fresh/fresh_but_job_failed/stale）并断言废弃键不再出现。提交 ab312d2c。顺带发现覆盖度分母含 353 个退市/停牌化石代码（19 只滞后标的全是 1997-2003 年的琼民源A/PT粤金曼/ST九州），当前 5262/5281=99.64% 仍 >98% 阈值，但分母不卫生会让阈值失真。② 我自己引入的回归：上午给 daily_klines 加 CHECK 禁止指数行时只审了读路径，漏了 data_backfiller 的**写路径**（指数分支取指数数据却共用 daily_klines 保存）→ 当晚 18:40 补齐任务写 399300 触发 CheckViolation 整批失败（事件 bbb56df6/b376f70d 等 5 条）。修法：backfill_symbol 入口跳过指数（回报 skipped=true/success=true 且不发起取数），新增 5 例测试锁定契约。提交 ef0dadeb。教训：改数据模型（禁止某类行）必须同时审计所有写入点。另：采集器会把"重试进行中"的日志行入账，且对同一指纹一律重开 resolved 事件（不比较时间戳），属待改进的噪声源。', 'experience', '{新鲜度巡检,kline_latest,指数写入,CheckViolation,回归}', NULL, '''-09'':2A,14B,33B ''-10'':34B ''-11'':3A,15B ''-2003'':91B ''/pt'':93B ''/st'':95B ''17'':63B ''18'':121B ''19'':88B ''1997'':90B ''20'':64B ''2026'':1A,13B,32B ''353'':85B ''399300'':124B ''4'':78B ''40'':122B ''5'':131B,143B ''5262/5281'':98B ''7460c6b7/ddea89ea'':67B ''98'':101B ''99.64'':99B ''ab312d2c'':83B ''backfill'':134B ''backfiller'':113B ''bbb56df6/b376f70d'':129B ''check'':109B ''checkviolation'':126B ''coverage/kline_stale/kline_oldest_stale'':71B ''daily'':106B,117B ''data'':112B ''date'':41B ''defined'':30B ''ef0dadeb'':146B ''f4aa1f6a'':7A,19B ''fresh/fresh_but_job_failed/stale'':80B ''freshness'':46B ''guard'':47B ''is'':28B ''job'':45B ''k'':36B ''kline'':26B,52B,70B ''klines'':107B,118B ''k线'':10A,22B ''latest'':27B,53B ''max'':