INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('bace12c9-7c88-41d7-874a-67a11536af63', '2026-09-11 修复「空结果被计为 provider 故障」缺陷（commit 07a1fd9', '2026-09-11 修复「空结果被计为 provider 故障」缺陷（commit 07a1fd94，w-f436d4ea）：【缺陷】adapters/outbound/datasources/manager.py 的 _try_providers：provider 返回 None/校验不通过时与真故障走同一条 _record_failure（原 283-285 行），把『该查询无数据』误计为『provider 故障』。【实测后果】东财 F10 主营构成遇 1 只无数据标的（如 601989 中国重工）即记连续失败，健康分被零失败的同花顺反超 → 东财被降权 → 链成员归位回退弱证据源，造船链 by_main_business 7→2。【修复】拆分语义：provider 自报 last_error/异常/超时 → _record_failure（影响连续失败·熔断·排序）；返回空但无错 → 新增 _record_empty（单独 empty 计数，**不计失败/连续失败/熔断/排序**）；provider_errors 文案改诚实标注『返回空数据（非故障：该查询无数据，不计入健康分）』（同时落实 RFC 015 §1.5.5）。【验证】语义：5 次空结果 → empty=5/failure=0/consec=0；再 1 次真故障 → failure=1/consec=1（互不污染）。端到端：601989 东财 empty=1/fail=0/consec=0 且降级同花顺如实；600176/600150 仍由东财首位服务(success=2)。回归 p2-chain-tools + tradability-gate LIVE 18/18。【影响面】不限产业链——所有 provider 类型（quote/kline/dividend/minute_kline/sector…）只要某查询合法无数据，都不再被无谓降权。这是系统性改进，不是局部补丁。【设计纪律】不在 failure 侧补偿『系统性空』的降权；若未来需要应按 empty 比例另设阈值，绝不能与 failure 混计。', 'experience', '{缺陷修复,provider健康分,空结果语义,动态降权,多源,w-f436d4ea}', NULL, '''-09'':2A,12B ''-11'':3A,13B ''-285'':37B ''0'':105B,119B ''0/consec'':104B,118B ''015'':96B ''07a1fd9'':10A ''07a1fd94'':20B ''1'':48B,107B,111B ''1.5.5'':97B ''1/consec'':110B ''1/fail'':117B ''18/18'':134B ''2'':62B,124B ''2026'':1A,11B ''283'':36B ''5'':100B ''5/failure'':103B ''600176/600150'':121B ''601989'':51B,114B ''7'':61B ''adapters/outbound/datasources/manager.py'':25B ''business'':60B ''by'':58B ''chain'':128B ''commit'':9A,19B ''empty'':79B,81B,102B,116B,152B ''error'':68B ''errors'':88B ''f10'':46B ''f436d4ea'':23B ''failure'':34B,72B,109B,147B,155B ''gate'':132B ''last'':67B ''live'':133B ''main'':59B ''none'':31B ''p2'':127B ''p2-chain-tools'':126B ''provider'':6A,16B,29B,42B,65B,87B,138B ''providers'':28B ''quote/kline/dividend/minute_kline/sector'':140B ''record'':33B,71B,78B ''rfc'':95B ''success'':123B ''tools'':129B ''tradability'':131B ''tradability-gate'':130B ''try'':27B ''w'':22B ''w-f436d4ea'':21B ''不在'':146B ''不是局部补丁'':144B ''不计入健康分'':93B ''不计失败'':83B ''不限产业链'':136B ''且降级同花顺如实'':120B ''东财'':45B,115B ''东财被降权'':55B ''中国重工'':52B ''主营构成遇'':47B ''互不污染'':112B ''仍由东财首位服务'':122B ''侧补偿'':148B ''修复'':4A,14B,63B ''健康分被零失败的同花顺反超'':54B ''再'':106B ''单独'':80B ''即记连续失败'':53B ''原'':35B ''只无数据标的'':49B ''只要某查询合法无数据'':141B ''同时落实'':94B ''回归'':125B ''如'':50B ''实测后果'':44B ''异常'':69B ''影响连续失败'':73B ''影响面'':135B ''所有'':137B ''把'':39B ''拆分语义'':64B ''排序'':75B,86B ''故障'':7A,17B,43B ''文案改诚实标注'':89B ''新增'':77B ''校验不通过时与真故障走同一条'':32B ''次真故障'':108B ''次空结果'':101B ''比例另设阈值'':153B ''混计'':156B ''熔断'':74B,85B ''的'':26B ''的降权'':150B ''空结果被计为'':5A,15B ''端到端'':113B ''类型'':139B ''系统性空'':149B ''绝不能与'':154B ''缺陷'':8A,18B,24B ''自报'':66B ''若未来需要应按'':151B ''行'':38B ''计数'':82B ''设计纪律'':145B ''该查询无数据'':40B,92B ''语义'':99B ''误计为'':41B ''超时'':70B ''返回'':30B ''返回空但无错'':76B ''返回空数据'':90B ''这是系统性改进'':143B ''连续失败'':84B ''造船链'':57B ''都不再被无谓降权'':142B ''链成员归位回退弱证据源'':56B ''非故障'':91B ''验证'':98B', '2026-09-11 19:39:23.387854', '2026-09-11 19:39:23.387854', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('86e08272-db12-4a78-99e2-adc71f5f7dfa', '【需求看板 w-1cee2467 2026-09-11 收尾】卡面按钮迭代 + 上线实况证据。①用户', '【需求看板 w-1cee2467 2026-09-11 收尾】卡面按钮迭代 + 上线实况证据。①用户反馈「按钮应该在泳道图上，按钮太深了」→ 状态推进按钮从详情页搬到泳道卡面：cardActions() 按状态给下一步人工操作（draft 提交评审/取消、reviewing 确认方案/退回、decomposing 确认拆分、implementing 提交验收、accepting 验收通过、done 归档），按钮自带 data-id；board-mount 的 move-req 原先只从详情态取 reqId（卡面按钮点不动），已改为读 data-id 并按来源记推进依据。②上线实况（~/.dsh-agent-dh/dsh-reqboard.json，2026-09-11 19:44 读取，revision 247）：实例 11:37 重启后启动对账真实执行——11 条历史 draft 需求全部推进 reviewing，每条一条 system 留痕「[自动推进] draft → reviewing：启动对账…」；另两条新需求（REQ-f08def 盯盘处置状态机、REQ-733c5e 数据接口契约修复）带 agent 留痕「[窗口推进] draft → reviewing」，即其他窗口已自发使用新增的 reqboard_move 工具回报进展。结论：自动推进链路与窗口回报工具均已线上生效。提交：c238241a + merge 5d72db2f。', 'knowledge', '{reqboard,dsh-pmboard,UI,泳道卡面,上线验证,reqboard_move,w-1cee2467}', NULL, '''-09'':6A,17B,64B ''-11'':7A,18B,65B ''/.dsh-agent-dh/dsh-reqboard.json'':62B ''11'':72B,75B ''19'':66B ''1cee2467'':4A,15B ''2026'':5A,16B,63B ''247'':70B ''37'':73B ''44'':67B ''5d72db2f'':111B ''733c5e'':94B ''accepting'':38B ''agent'':97B ''board'':47B ''board-mount'':46B ''c238241a'':109B ''cardactions'':26B ''data'':44B,58B ''data-id'':43B,57B ''decomposing'':34B ''done'':40B ''draft'':28B,77B,84B,100B ''f08def'':90B ''id'':45B,59B ''implementing'':36B ''merge'':110B ''mount'':48B ''move'':51B,104B ''move-req'':50B ''req'':52B,89B,93B ''req-733c5e'':92B ''req-f08def'':88B ''reqboard'':103B ''reqid'':54B ''reviewing'':31B,79B,85B,101B ''revision'':69B ''system'':81B ''w'':3A,14B ''w-1cee2467'':2A,13B ''上线实况'':61B ''上线实况证据'':10A,21B ''卡面按钮点不动'':55B ''卡面按钮迭代'':9A,20B ''即其他窗口已自发使用新增的'':102B ''原先只从详情态取'':53B ''取消'':30B ''另两条新需求'':87B ''启动对账'':86B ''实例'':71B ''工具回报进展'':105B ''已改为读'':56B ''带'':96B ''并按来源记推进依据'':60B ''归档'':41B ''按状态给下一步人工操作'':27B ''按钮太深了'':24B ''按钮应该在泳道图上'':23B ''按钮自带'':42B ''提交'':108B ''提交评审'':29B ''提交验收'':37B ''收尾'':8A,19B ''数据接口契约修复'':95B ''条历史'':76B ''每条一条'':80B ''状态推进按钮从详情页搬到泳道卡面'':25B ''用户'':11A ''用户反馈'':22B ''留痕'':82B,98B ''的'':49B ''盯盘处置状态机'':91B ''确认拆分'':35B ''确认方案'':32B ''窗口推进'':99B ''结论'':106B ''自动推进'':83B ''自动推进链路与窗口回报工具均已线上生效'':107B ''读取'':68B ''退回'':33B ''重启后启动对账真实执行'':74B ''需求全部推进'':78B ''需求看板'':1A,12B ''验收通过'':39B', '2026-09-11 19:45:04.984273', '2026-09-11 19:45:04.984273', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('0bb378d8-a8e9-42cd-948c-2322fbf4d20e', '【需求看板 2026-09-11 二次迭代（用户两次反馈）】①视觉：卡面按钮此前自造 .dsh-pm', '【需求看板 2026-09-11 二次迭代（用户两次反馈）】①视觉：卡面按钮此前自造 .dsh-pm-card-btn 与全站不一致（用户："按钮太丑了，和整体风格不一致"）→ 删除自造样式，改用全站 .dsh-pm-btn 体系（页头/详情页同款配色圆角），仅加 .dsh-pm-btn.sm 紧凑变体；卡面与详情页文案不再自称"人工闸门"。②闸门：用户："agent 自己不能推进吗，还需要用户手动推进" → HUMAN_ONLY_REQ_TRANSITIONS 收缩为仅「取消需求 / 归档」（*→canceled、*→archived）；在途步骤 agent 可自行推进；SYSTEM_REQ_TRANSITIONS 扩为派生链四条（draft>reviewing、reviewing>decomposing、decomposing>implementing、implementing>accepting）；rollup 新增任务驱动链 R3/R4（reviewing+有任务→decomposing；decomposing+任务开工→implementing；implementing+全完成→accepting，一次调用内收敛且同一需求只上报一次）；新增 capture.boundSectionText 给绑定窗口注入"推进纪律"段（此前 bound 窗口 section 为空，窗口不知道自己名下有需求、也不知道可推进——这是"必须人点"的深层原因）；reqboard_status 增 next_actions；reqboard_move 描述改口径。RFC 014 §3 已补 2026-09-11 修订说明。验证：134 单测（含路由级集成、真实台账渲染确认按钮类名统一）。提交 33516e5a + merge f79f69c7。注意：host 半改动需重启 13080 生效；client 刷新页面即可。', 'knowledge', '{reqboard,dsh-pmboard,UI一致性,闸门收缩,agent自推进,boundSectionText,w-1cee2467}', NULL, '''-09'':3A,14B,113B ''-11'':4A,15B,114B ''014'':109B ''13080'':129B ''134'':117B ''2026'':2A,13B,112B ''3'':110B ''33516e5'':122B ''a'':123B ''accepting'':71B,83B ''actions'':104B ''agent'':45B,58B ''archived'':56B ''bound'':91B ''btn'':24B,34B ''canceled'':55B ''capture.boundsectiontext'':86B ''card'':23B ''client'':131B ''decomposing'':67B,68B,77B,78B ''draft'':64B ''dsh'':10A,21B,32B ''dsh-pm'':9A ''dsh-pm-btn'':31B ''dsh-pm-btn.sm'':39B ''dsh-pm-card-btn'':20B ''f79f69c7'':125B ''host'':127B ''human'':48B ''implementing'':69B,70B,80B,81B ''merge'':124B ''move'':106B ''next'':103B ''only'':49B ''pm'':11A,22B,33B ''r3/r4'':74B ''req'':50B,61B ''reqboard'':100B,105B ''reviewing'':65B,66B,75B ''rfc'':108B ''rollup'':72B ''section'':93B ''status'':101B ''system'':60B ''transitions'':51B,62B ''一次调用内收敛且同一需求只上报一次'':84B ''与全站不一致'':25B ''为空'':94B ''也不知道可推