INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('e7b8bda8-dacd-403c-b9f0-350969f05584', '工程纪律：改实现的『缝』会静默打掉测试隔离，而且可能以『通过』的形式掩盖。2026-09-11 实证', '工程纪律：改实现的『缝』会静默打掉测试隔离，而且可能以『通过』的形式掩盖。2026-09-11 实证：eastmoney_delay_concept 的 19 个契约测试以 monkeypatch.setattr(mod,''requests'',stub) 实现离线；把 provider 从模块级 requests.get 改成 _shared_session().get 后该缝失效，且模块级 _SHARED_SESSION 缓存里可能已有真实 Session → 测试开始真打上游，部分用例因真拿到数据而『通过』。全量从 12 failed 突增到 28 failed 才暴露。判据：测试耗时（0.29s → 秒级）与失败数突变。纪律：换 seam 必须同时①把桩装到新缝②清空该缝的模块级缓存状态③审所有依赖旧缝的测试；测试文件里写明『离线保证依赖哪个实现细节』，否则改实现时无人知道要同步改。', 'experience', '{工程纪律,测试隔离,seam,monkeypatch,静默假通过}', NULL, '''-09'':9A,20B ''-11'':10A,21B ''0.29'':60B ''12'':52B ''19'':27B ''2026'':8A,19B ''28'':55B ''concept'':25B ''delay'':24B ''eastmoney'':23B ''failed'':53B,56B ''get'':41B ''mod'':30B ''monkeypatch.setattr'':29B ''provider'':35B ''requests'':31B ''requests.get'':37B ''s'':61B ''seam'':66B ''session'':40B,45B,47B ''shared'':39B,44B ''stub'':32B ''与失败数突变'':63B ''且模块级'':43B ''个契约测试以'':28B ''从模块级'':36B ''会静默打掉测试隔离'':4A,15B ''全量从'':51B ''判据'':58B ''后该缝失效'':42B ''否则改实现时无人知道要同步改'':73B ''实现离线'':33B ''实证'':11A,22B ''审所有依赖旧缝的测试'':70B ''工程纪律'':1A,12B ''必须同时'':67B ''才暴露'':57B ''把'':34B ''把桩装到新缝'':68B ''换'':65B ''改实现的'':2A,13B ''改成'':38B ''测试开始真打上游'':48B ''测试文件里写明'':71B ''测试耗时'':59B ''清空该缝的模块级缓存状态'':69B ''的'':26B ''的形式掩盖'':7A,18B ''离线保证依赖哪个实现细节'':72B ''秒级'':62B ''突增到'':54B ''纪律'':64B ''缓存里可能已有真实'':46B ''缝'':3A,14B ''而且可能以'':5A,16B ''通过'':6A,17B,50B ''部分用例因真拿到数据而'':49B', '2026-09-11 22:46:30.198021', '2026-09-11 22:46:30.198021', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('4c6e7fe7-2e92-4d0d-aead-b705c2c3b6b8', '工程纪律：head 截断的 grep 不能证明『不存在』。2026-09-11 我连续两次就『ext', '工程纪律：head 截断的 grep 不能证明『不存在』。2026-09-11 我连续两次就『external_id 是否在 P3 链路丢失』给出相反的错误断言，根因都是拿 `grep -rln ... | head` 被 .pyc 条目占满的截断输出当成全量事实。决定性判据是逐目标 `for f in ...; do grep -q PATTERN $f || echo MISSING: $f; done`（本次一跑即定案：7 个 provider 全都有 external_id）。纪律：凡要断言『某处没有 X』，必须用不截断的判据（逐文件判定 / --files-without-match / wc -l 对比总数），并在结论里写明用的是哪种判据。', 'experience', '{工程纪律,grep,head截断,证伪,judgement}', NULL, '''-09'':8A,19B ''-11'':9A,20B ''2026'':7A,18B ''7'':49B ''do'':39B ''done'':47B ''echo'':44B ''ext'':11A ''external'':22B,53B ''f'':37B,43B,46B ''files'':62B ''files-without-match'':61B ''for'':36B ''grep'':4A,15B,29B,40B ''head'':2A,13B,31B ''id'':23B,54B ''in'':38B ''l'':66B ''match'':64B ''missing'':45B ''p3'':25B ''pattern'':42B ''provider'':51B ''pyc'':33B ''q'':41B ''rln'':30B ''wc'':65B ''without'':63B ''x'':58B ''不存在'':6A,17B ''不能证明'':5A,16B ''个'':50B ''全都有'':52B ''决定性判据是逐目标'':35B ''凡要断言'':56B ''对比总数'':67B ''工程纪律'':1A,12B ''并在结论里写明用的是哪种判据'':68B ''必须用不截断的判据'':59B ''我连续两次就'':10A,21B ''截断的'':3A,14B ''是否在'':24B ''本次一跑即定案'':48B ''条目占满的截断输出当成全量事实'':34B ''某处没有'':57B ''根因都是拿'':28B ''纪律'':55B ''给出相反的错误断言'':27B ''被'':32B ''逐文件判定'':60B ''链路丢失'':26B', '2026-09-11 22:46:30.22224', '2026-09-11 22:46:30.22224', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('258ba6f1-9805-40a2-9899-dc9206af00b0', 'REQ-cf627b 待办（已用库内实据定性，2026-09-11）：quant.event_cal', 'REQ-cf627b 待办（已用库内实据定性，2026-09-11）：quant.event_calendar 共 514 行，其中 P3 三源 418 行的 meta.external_id **键存在但值全空**（key_nonempty=0）；上游唯一 ID 仅东财 217 行可从 meta.raw.art_code 恢复，巨潮 195 / akshare 6 / gov 24 / csrc 5 共 230 行无任何可恢复上游 ID。根因：external_id 在 provider→仓储之间被丢弃（meta 键仍写入、值为空；raw 走另一通道故存活），属领域层丢字段。影响面小（当前无消费者；evidence_hash 447 全 distinct 承担去重），故未随本轮修。修法：在 domain/events 模型与 ingest 映射中贯通该字段，随下次 domain 改动一并做。', 'knowledge', '{REQ-cf627b,external_id,event_calendar,待办,领域层丢字段}', NULL, '''-09'':7A,17B ''-11'':8A,18B ''0'':34B ''195'':44B ''2026'':6A,16B ''217'':38B ''230'':52B ''24'':48B ''418'':27B ''447'':71B ''5'':50B ''514'':22B ''6'':46B ''akshare'':45B ''cal'':10A ''calendar'':20B ''cf627b'':3A,13B ''code'':41B ''csrc'':49B ''distinct'':73B ''domain'':83B ''domain/events'':78B ''evidence'':69B ''external'':56B ''gov'':47B ''hash'':70B ''id'':30B,36B,54B,57B ''ingest'':80B ''key'':32B ''meta'':61B ''meta.external'':29B ''meta.raw.art'':40B ''nonempty'':33B ''p3'':25B ''provider'':59B ''quant.event'':9A,19B ''raw'':64B ''req'':2A,12B ''req-cf627b'':1A,11B ''三源'':26B ''上游唯一'':35B ''仅东财'':37B ''仓储之间被丢弃'':60B ''修法'':76B ''值为空'':63B ''全'':72B ''共'':21B,51B ''其中'':24B ''在'':58B,77B ''属领域层丢字段'':66B ''巨潮'':43B ''已用库内实据定性'':5A,15B ''当前无消费者'':68B ''影响面小'':67B ''待办'':4A,14B ''恢复'':42B ''承担去重'':74B ''改动一并做'':84B ''故未随本轮修'':75B ''映射中贯通该字段'':81B ''根因'':55B ''模型与'':79B ''行'':23B ''行可从'':39B ''行无任何可恢复上游'':53B ''行的'':28B ''走另一通道故存活'':65B ''键仍写入'':62B ''键存在但值全空'':31B ''随下次'':82B', '2026-09-11 22:46:30.22715', '2026-09-11 22:46:30.22715', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('2df7998d-b452-4dac-b3fd-b4d3d3ca9893', '2026-09-14（周一）盘前计划（w-f436d4ea，基于 2026-09-11 收盘数据）：', '2026-09-14（周一）盘前计划（w-f436d4ea，基于 2026-09-11 收盘数据）：结论=**零交易、不接飞刀**。依据：①情绪分 20/极度恐惧、涨跌家数比 0.18（涨5跌28）、量能比 0.77 缩量、新高0/新低1（data_fetch_market_sentiment，2026-09-11）→ 三条企稳条件（下跌减速/量能企稳/结构信号）**全部不满足**，符合经验教训「恐慌市不接飞刀」；②regime=risk_off 且 data_quality=degraded，仓位上限 40%（R-006 取最严值），当前 12.8%、余量 27.2%（regime_position_limit，2026-09-11）。**有空间≠该用**。③主线 Top2：船舶制造+2.61%、玻璃行业+0.84%（mainline_scan days=5，2026-09-11）为弱势市相对强势，但仅一日强度不构成结构信号。观察位（未完成四维验证→C级只观察）：600176 中国巨石 44.66(+2.76%，玻纤链上游、主营构成硬证据电子纱/电子布占营收24.3%，东财F10 报告期2026-03-31)；600150 中国船舶 39.75(−2.62%，当日有北海造船厂火灾事故公告 importance=2)；601989 中国重工 5.10。入场触发条件（盘前人工核验，盯盘引擎不支持市场级指标）：涨跌家数比≥0.8 且量能比≥1.0，或新低归零且指数连续2日不创新低；板块需保持5日强度Top3且不破前低。持仓：600887 伊利股份 26.66/成本26.75(−0.34%)持，止损规则 pnl<-8%(24.61) 已挂；300677 英科医疗 55.00/成本53.49(+2.82%)持，止损 pnl<-10% 已挂。', 'knowledge', '{2026-09-14,盘前计划,零交易,恐慌市,不接飞刀}', NULL, '''+0.84'':85B ''+2.61'':83B ''+2.76'':101B ''+2.82'':144B ''-006'':66B ''-03'':107B ''-09'':2A,11A,15B,24B,47B,76B,91B ''-10'':148B ''-11'':12A,25B,48B,77B,92B ''-14'':3A,16B ''-31'':108B ''-8'':137B ''0.18'':35B ''0.34'':133B ''0.77'':38B ''0.8'':123B ''1.0'':125B ''12.8'':69B ''2'':115B ''2.62'':112B ''20'':32B ''2026'':1A,10A,14B,23B,46B,75B,90B ''24.61'':138B ''26.66'':131B ''27.2'':71B ''300677'':140B ''39.75'':111B ''40'':64B ''44.66'':100B ''5'':89B ''5.10'':118B ''55.00'':142B ''600150'':109B ''600176'':98B ''600887'':129B ''601989'':116B ''c级只观察'':97B ''data'':42B,60B ''days'':88B ''degraded'':62B ''f436d4ea'':8A,21B ''fetch'':43B ''importance'':114B ''limit'':74B ''mainline'':86B ''market'':44B ''off'':58B ''pnl'':136B,147B ''position'':73B ''quality'':61B ''r'':65B ''regime'':56B,72B ''risk'':57B ''scan'':87B ''sentiment'':45B ''top2'':81B ''w'':7A,20B ''w-f436d4ea'':6A,19B ''三条企稳条件'':49B ''下跌减速'':50B ''不接飞刀'':29