INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('02f32b09-1354-4695-966f-c2ea09a9cdeb', '两个新发现的工具缺陷（2026-09-11，w-f436d4ea，记录待修）：①**fund_flo', '两个新发现的工具缺陷（2026-09-11，w-f436d4ea，记录待修）：①**fund_flow 自身数据不自洽**：600176 的 2026-09-10 行 closePrice=41.82，但同行 changePct=+2.7612%、且 09-11 行 closePrice=44.66（+2.76%）反推前收应为 43.46 —— 41.82 与 43.46 差 3.9%，同一响应内自相矛盾（chip_analysis/pe_percentile 的 09-10 收盘均为 43.46）。用该序列做『主力资金 vs 涨跌』对齐分析会得出错误结论。②**stock_events 对无个股事件的标的不做区分**：stock_events(600176,60d) 返回 24 条**全部 scope=macro 的宏观政策**（国务院/LPR/PMI），individual_events=[]，而同一工具查 600150 能返回 27 条含 cninfo 个股公告。调用方无法区分『该股确实无事件』与『该股无覆盖』——正是本轮一直在修的空结果语义问题；对『买入前排雷（解禁/减持/定增）』这一声明用途是失效的。临时降级办法：用 stock_intel（akshare 源）替代，实测可返回公告与新闻。', 'knowledge', '{工具缺陷,fund_flow,stock_events,空结果语义,排雷失效}', NULL, '''+2.76'':39B ''+2.7612'':32B ''-09'':3A,13B,25B ''-10'':26B,52B ''-11'':4A,14B,35B ''/lpr/pmi'':75B ''09'':34B,51B ''2026'':2A,12B,24B ''24'':68B ''27'':81B ''3.9'':46B ''41.82'':29B,42B ''43.46'':41B,44B,54B ''44.66'':38B ''600150'':79B ''600176'':22B,65B ''60d'':66B ''akshare'':100B ''analysis/pe_percentile'':49B ''changepct'':31B ''chip'':48B ''closeprice'':28B,37B ''cninfo'':83B ''events'':61B,64B,77B ''f436d4ea'':7A,17B ''flo'':10A ''flow'':20B ''fund'':9A,19B ''individual'':76B ''intel'':99B ''macro'':72B ''scope'':71B ''stock'':60B,63B,98B ''vs'':57B ''w'':6A,16B ''w-f436d4ea'':5A,15B ''与'':43B,87B ''且'':33B ''两个新发现的工具缺陷'':1A,11B ''个股公告'':84B ''临时降级办法'':96B ''主力资金'':56B ''买入前排雷'':91B ''但同行'':30B ''全部'':70B ''减持'':93B ''反推前收应为'':40B ''同一响应内自相矛盾'':47B ''国务院'':74B ''定增'':94B ''实测可返回公告与新闻'':103B ''对'':90B ''对无个股事件的标的不做区分'':62B ''对齐分析会得出错误结论'':59B ''差'':45B ''收盘均为'':53B ''替代'':102B ''条'':69B ''条含'':82B ''正是本轮一直在修的空结果语义问题'':89B ''涨跌'':58B ''源'':101B ''用'':97B ''用该序列做'':55B ''的'':23B,50B ''的宏观政策'':73B ''而同一工具查'':78B ''能返回'':80B ''自身数据不自洽'':21B ''行'':27B,36B ''解禁'':92B ''记录待修'':8A,18B ''该股无覆盖'':88B ''该股确实无事件'':86B ''调用方无法区分'':85B 