INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('07fc5246-d53b-43cf-bfb7-c1da660a594e', 'SYSTEM loss 策略评估体系（回测口径 / universe 选择 / 均线择时）', 'SYSTEM 交易经验（2026-09-13T04:29:07.148Z）
