INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('8b8beac5-ec9a-45d4-b0cb-73a9887b251e', '盯盘通知噪声的真正来源（2026-09-11 第三轮，w-f436d4ea，用触发记录实证）：不是『', '盯盘通知噪声的真正来源（2026-09-11 第三轮，w-f436d4ea，用触发记录实证）：不是『被包含条件各自触发』，而是**条件缺 cooldown_sec 时按 DEFAULT_COOLDOWN_SEC=300 反复重报**。证据：quant.watch_triggers 显示 #119 的同一条 ''price<25.5'' 条件在 2026-09-10 09:53/09:58/10:05/10:10/10:22/10:24/10:37/10:39/10:44/10:47 每约 5 分钟触发一次；engine.py:507 用 cond.get(''cooldown_sec'', 300)，引擎轮询 60s。已为 9 条启用规则（#119/#120/#92/#129/#89/#105/#121/#99/#57）共 13 条缺失条件补 cooldown_sec=1800。**降噪正解是补冷却，不是删条件**（删条件改变语义且有误删风险）。排查口径：`enabled=true AND conditions 中任一条无 cooldown_sec AND 触发数高`。', 'experience', '{盯盘规则,cooldown,通知噪声,实证归因,别乱删}', NULL, '''-09'':3A,13B,42B ''-10'':43B ''-11'':4A,14B ''05/10'':47B ''09'':44B ''10/10'':48B ''105'':74B ''119'':36B,69B ''120'':70B ''121'':75B ''129'':72B ''13'':79B ''1800'':83B ''2026'':2A,12B,41B ''22/10'':49B ''24/10'':50B ''25.5'':39B ''300'':30B,63B ''37/10'':51B ''39/10'':52B ''44/10'':53B ''47'':54B ''5'':56B ''53/09'':45B ''57'':77B ''58/10'':46B ''60s'':65B ''89'':73B ''9'':67B ''92'':71B ''99'':76B ''and'':90B,95B ''cond.get'':60B ''conditions'':91B ''cooldown'':24B,28B,61B,81B,93B ''default'':27B ''enabled'':88B ''engine.py:507'':58B ''f436d4ea'':8A,18B ''price'':38B ''quant.watch'':33B ''sec'':25B,29B,62B,82B,94B ''triggers'':34B ''true'':89B ''w'':7A,17B ''w-f436d4ea'':6A,16B ''不是'':10A,20B ''不是删条件'':85B ''中任一条无'':92B ''共'':78B ''分钟触发一次'':57B ''删条件改变语义且有误删风险'':86B ''反复重报'':31B ''已为'':66B ''引擎轮询'':64B ''排查口径'':87B ''时按'':26B ''显示'':35B ''条件在'':40B ''条件缺'':23B ''条启用规则'':68B ''条缺失条件补'':80B ''每约'':55B ''用'':59B ''用触发记录实证'':9A,19B ''的同一条'':37B ''盯盘通知噪声的真正来源'':1A,11B ''第三轮'':5A,15B ''而是'':22B ''被包含条件各自触发'':21B ''触发数高'':96B ''证据'':32B ''降噪正解是补冷却'':84B', '2026-09-11 23:17:17.41963', '2026-09-11 23:17:17.41963', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('71d75a6f-638c-4e58-b18d-daf6ace7ff63', '资金流存量污染标记已完成（2026-09-11，w-f436d4ea，commit cadaf6f8', '资金流存量污染标记已完成（2026-09-11，w-f436d4ea，commit cadaf6f8）：quant.stock_fund_flow 加 quality_flag VARCHAR(32) 列（NULL=干净，''close_mismatch_vs_kline''=已标记坏行），回填 14,314 行 + 索引，迁移脚本 infrastructure/persistence/migrations/20260911_fund_flow_quality_flag.py（幂等可重跑）。消费者规避：WHERE quality_flag IS NULL，或 anti-join quant.stock_fund_flow_suspect。**未删除任何行**；备份 quant.stock_fund_flow_backup_20260911（81,335 行，仅数据）。⚠️ 关键陷阱已修并有锁：batch_upsert 的 ON CONFLICT DO UPDATE 原先枚举全部表列，加列后会把重新写入的坏行标记**擦成 NULL**（把已知污染伪装成干净数据）；已把 quality_flag 排除出更新集，3 例回归锁 + **故障注入实测**（去掉排除项→2例失败，还原→通过）。', 'knowledge', '{fund_flow,quality_flag,迁移,upsert陷阱,故障注入,已完成}', NULL, '''-09'':3A,12B ''-11'':4A,13B ''14'':36B ''2026'':2A,11B ''20260911'':63B ''2例失败'':89B ''3'':85B ''314'':37B ''32'':26B ''335'':65B ''81'':64B ''anti'':51B ''anti-join'':50B ''backup'':62B ''batch'':69B ''cadaf6f8'':9A,18B ''close'':30B ''commit'':8A,17B ''conflict'':73B ''do'':74B ''f436d4ea'':7A,16B ''flag'':24B,46B,83B ''flow'':21B,55B,61B ''fund'':20B,54B,60B ''infrastructure/persistence/migrations/20260911_fund_flow_quality_flag.py'':41B ''is'':47B ''join'':52B ''kline'':33B ''mismatch'':31B ''null'':28B,48B,79B ''on'':72B ''quality'':23B,45B,82B ''quant.stock'':19B,53B,59B ''suspect'':56B ''update'':75B ''upsert'':70B ''varchar'':25B ''vs'':32B ''w'':6A,15B ''w-f436d4ea'':5A,14B ''where'':44B ''仅数据'':67B ''例回归锁'':86B ''关键陷阱已修并有锁'':68B ''列'':27B ''加'':22B ''加列后会把重新写入的坏行标记'':77B ''原先枚举全部表列'':76B ''去掉排除项'':88B ''回填'':35B ''备份'':58B ''已把'':81B ''已标记坏行'':34B ''幂等可重跑'':42B ''干净'':29B ''或'':49B ''把已知污染伪装成干净数据'':80B ''排除出更新集'':84B ''擦成'':78B ''故障注入实测'':87B ''未删除任何行'':57B ''消费者规避'':43B ''的'':71B ''索引'':39B ''行'':38B,66B ''资金流存量污染标记已完成'':1A,10B ''迁移脚本'':40B ''还原'':90B ''通过'':91B', '2026-09-11 23:27:46.310627', '2026-09-11 23:27:46.310627'