INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('108a05dd-3a4d-4cdc-bcc6-3ab29264271a', '第③步结论：玻纤·电子布·PCB链 与 造船·航运链 **16 只候选全部处于自身近3年 PE 高分', '第③步结论：玻纤·电子布·PCB链 与 造船·航运链 **16 只候选全部处于自身近3年 PE 高分位**（pe_percentile，最低 胜宏科技 66.76%，其余 ≥71.91%，13 只 ≥82%），无一只落进「好价格候选」(<40%)——**两链整体估值高位**，故链内找不到可升级到 R-009 B 级的标的。全市场筛选（pe∈[0,20] 且 roe≥15，sort_by=roe）另得低估值高ROE名单：山西汾酒 600809(pe11.91/roe15.02)、云铝股份 000807(16.46/21.89)、株冶集团 600961(16.13/39.52)、神火股份 000933(17.14/18.41)、宝丰能源 600989(19.45/18.61)、卫星化学 002648(17.62/17.28)、分众传媒 002027(16.48/20.44)、亿联网络 300628(15.63/15.11) 等——但**均不在当日主线**（玻璃/船舶制造/传媒娱乐），且市场处极度恐慌（情绪20、涨跌家数比0.18、量能0.77），经验教训「恐慌市不接飞刀」的三条企稳条件全不满足。故结论=**周一维持零交易**，非「找不到」而是「找到但条件不满足」，正确动作是等而非降格买入（宪法第6条零交易合法）。数据缺口：601989 中国重工 pe_percentile 接口报错。', 'knowledge', '{候选筛选,估值分位,零交易,不接飞刀,结论}', NULL, '''-009'':41B ''/15.11'':85B ''/17.28'':77B ''/18.41'':69B ''/18.61'':73B ''/20.44'':81B ''/21.89'':61B ''/39.52'':65B ''0'':46B ''000807'':59B ''000933'':67B ''002027'':79B ''002648'':75B ''13'':32B ''15'':50B ''15.63'':84B ''16'':9A,21B ''16.13'':64B ''16.46'':60B ''16.48'':80B ''17.14'':68B ''17.62'':76B ''19.45'':72B ''20'':47B ''300628'':83B ''40'':37B ''600809'':56B ''600961'':63B ''600989'':71B ''601989'':108B ''66.76'':29B ''71.91'':31B ''82'':34B ''b'':42B ''by'':52B ''pcb链'':5A,17B ''pe'':11A,23B,25B,45B,110B ''pe11.91/roe15.02'':57B ''percentile'':26B,111B ''r'':40B ''roe'':49B,53B ''sort'':51B ''与'':6A,18B ''且'':48B ''且市场处极度恐慌'':92B ''两链整体估值高位'':38B ''中国重工'':109B ''云铝股份'':58B ''亿联网络'':82B ''传媒娱乐'':91B ''但'':87B ''全市场筛选'':44B ''其余'':30B ''分众传媒'':78B ''卫星化学'':74B ''另得低估值高roe名单'':54B ''只'':33B ''只候选全部处于自身近3年'':10A,22B ''周一维持零交易'':100B ''均不在当日主线'':88B ''好价格候选'':36B ''宝丰能源'':70B ''宪法第6条零交易合法'':106B ''山西汾酒'':55B ''恐慌市不接飞刀'':97B ''情绪20'':93B ''找不到'':102B ''找到但条件不满足'':104B ''接口报错'':112B ''故结论'':99B ''故链内找不到可升级到'':39B ''数据缺口'':107B ''无一只落进'':35B ''最低'':27B ''株冶集团'':62B ''正确动作是等而非降格买入'':105B ''步结论'':2A,14B ''涨跌家数比0.18'':94B ''玻璃'':89B ''玻纤'':3A,15B ''电子布'':4A,16B ''的三条企稳条件全不满足'':98B ''神火股份'':66B ''第'':1A,13B ''等'':86B ''级的标的'':43B ''经验教训'':96B ''而是'':103B ''胜宏科技'':28B ''航运链'':8A,20B ''船舶制造'':90B ''造船'':7A,19B ''量能0.77'':95B ''非'':101B ''高分'':12A ''高分位'':24B', '2026-09-11 23:15:04.688555', '2026-09-11 23:15:04.688555', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('f81fca85-feb1-48e7-bc0e-a9595bc90c4a', '2026-09-11 全链估值漏斗结论（w-f436d4ea）：对 8 条策展产业链约 75 只成员', '2026-09-11 全链估值漏斗结论（w-f436d4ea）：对 8 条策展产业链约 75 只成员跑 PE 近3年分位，**估值高低在链之间极度分化**——①玻纤·电子布·PCB链 + 造船·航运链 共 16 只**全部 >66% 分位**（最低胜宏科技66.76%，13只≥82%），链整体处历史高位；②**军工·航空链独有 4 只 <20% 分位**：中简科技300777(8.21%)、中直股份600038(9.18%)、中航高科600862(17.25%)、中航光电002179(19.15%)；③新能源车链长城汽车601633 PE18.11 **分位0%**（历史最低）；④化工链华鲁恒升600426(9.6%)、锂电当升科技300073(22.67%)。排雷（已 ingest 个股事件后）：军工4只全部无风险类命中；长城汽车/华鲁恒升仅轻微解禁(≤0.22%)；**当升科技 2027-01 解禁占流通市值 7.47% 属实质冲击**。已建池『低估·军工航空候选池』收录军工4只。⚠️ 但市场未企稳（情绪20/涨跌比0.18/量能0.77），按『恐慌市不接飞刀』与 R-009（仅估值+排雷≈1.5维），**仍维持零交易，只观察**。', 'knowledge', '{估值漏斗,军工航空链,低估候选,排雷,零交易,2026-09-11}', NULL, '''-009'':91B ''-01'':75B ''-09'':2A,14B ''-11'':3A,15B ''0.22'':72B ''1.5'':94B ''13只'':40B ''16'':34B ''17.25'':54B ''19.15'':56B ''20'':47B ''2026'':1A,13B ''2027'':74B ''22.67'':64B ''4'':45B ''66'':37B ''7.47'':77B ''75'':11A,23B ''8'':9A,21B ''8.21'':50B ''82'':41B ''9.18'':52B ''9.6'':62B ''f436d4ea'':7A,19B ''ingest'':67B ''pcb链'':30B ''pe'':25B ''pe18.11'':58B ''r'':90B ''w'':6A,18B ''w-f436d4ea'':5A,17B ''与'':89B ''个股事件后'':68B ''中直股份600038'':51B ''中简科技300777'':49B ''中航光电002179'':55B ''中航高科600862'':53B ''仅估值'':92B ''仍维持零交易'':96B ''估值高低在链之间极度分化'':27B ''但市场未企稳'':83B ''低估'':80B ''全部'':36B ''全链估值漏斗结论'':4A,16B ''共'':33B ''军工'':43B ''军工4只全部无风险类命中'':69B ''军工航空候选池'':81B ''分位'':38B,48B ''分位0'':59B ''化工链华鲁恒升600426'':61B ''华鲁恒升仅轻微解禁'':71B ''历史最低'':60B ''只'':35B,46B ''只成员'':12A ''只成员跑'':24B ''只观察'':97B ''对'':8A,20B ''属实质冲击'':78B ''已'':66B ''已建池'':79B ''当升科技'':73B ''恐慌市不接飞刀'':88B ''情绪20'':84B ''按'':87B ''排雷'':65B,93B ''收录军工4只'':82B ''新能源车链长城汽车601633'':57B ''最低胜宏科技66.76'':39B ''条策展产业链约'':10A,22B ''涨跌比0.18'':85B ''玻纤'':28B ''电子布'':29B ''维'':95B ''航空链独有'':44B ''航运链'':32B ''解禁占流通市值'':76B ''近3年分位'':26B ''造船'':31B ''量能0.77'':86B ''链整体处历史高位'':42B ''锂电当升科技300073'':63B ''长城汽车'':70