INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('c63461bb-5013-4431-aee4-61e7921798d4', '【重要】quant.stock_fund_flow 历史数据系统性污染（2026-09-11 实测，', '【重要】quant.stock_fund_flow 历史数据系统性污染（2026-09-11 实测，w-f436d4ea，**未清理**）：与权威 K 线 quant.daily_klines 做同 symbol+date 比对——可比对 60,211 行中**14,314 行（23.8%）收盘价偏差 >0.5%**；另有 21,124 行的日期在 K 线中根本不存在（非交易日/未落 K 线）。典型形态：绝大多数标的的 **2026-09-10 行**同时出错（300777 偏 2.34%、600862 1.44%、002179 0.52%、600176 3.77%），与『有人用 --date 2026-09-10 在 09-11 盘中跑全市场回补，把盘中价记成 09-10 收盘』的诊断一致——即**09-10 全市场资金流数据不可信**，且其 mainNetInflow 也是当时盘中快照而非当日全天净额。**根因已修**（fund_flow_update_job 加两道闸门：非交易日不落库 + 抽样比对 K 线一致性，commit adaec83c），但**存量坏行仍在库**，任何用 fund_flow 做『资金流 vs 涨跌』对齐的分析都会被带偏。清理建议（需人工批准，勿擅自动生产数据）：①先备份表；②坏行可用 `JOIN daily_klines ON symbol+trade_date WHERE 偏差>0.5%` 精确定位（14,314 行）；③非交易日行按交易日历定位（21,124 行含未同步 K 线的正常行，需先剔除该部分再判）；④删除或加质量标记列二选一，建议先标记后观察。', 'knowledge', '{数据质量,fund_flow,系统性污染,待清理,需人工批准}', NULL, '''-09'':7A,16B,55B,72B ''-10'':56B,73B,80B,85B ''-11'':8A,17B,76B ''0.5'':41B,126B ''0.52'':65B ''002179'':64B ''09'':75B,79B,84B ''1.44'':63B ''124'':44B,133B ''14'':36B,128B ''2.34'':61B ''2026'':6A,15B,54B,71B ''21'':43B,132B ''211'':34B ''23.8'':39B ''3.77'':67B ''300777'':59B ''314'':37B,129B ''60'':33B ''600176'':66B ''600862'':62B ''adaec83c'':101B ''commit'':100B ''daily'':118B ''date'':30B,70B,123B ''f436d4ea'':21B ''flow'':4A,13B,92B,106B ''fund'':3A,12B,91B,105B ''job'':94B ''join'':117B ''k'':24B,46B,50B,98B,135B ''klines'':27B,119B ''mainnetinflow'':88B ''on'':120B ''quant.daily'':26B ''quant.stock'':2A,11B ''symbol'':29B,121B ''trade'':122B ''update'':93B ''vs'':109B ''w'':20B ''w-f436d4ea'':19B ''where'':124B ''与'':68B ''与权威'':23B ''且其'':87B ''也是当时盘中快照而非当日全天净额'':89B ''任何用'':104B ''但'':102B ''偏'':60B ''偏差'':125B ''做'':107B ''做同'':28B ''先备份表'':115B ''全市场资金流数据不可信'':86B ''典型形态'':52B ''删除或加质量标记列二选一'':138B ''加两道闸门'':95B ''勿擅自动生产数据'':114B ''即'':83B ''历史数据系统性污染'':5A,14B ''另有'':42B ''可比对'':32B ''同时出错'':58B ''在'':74B ''坏行可用'':116B ''存量坏行仍在库'':103B ''实测'':9A,18B ''对齐的分析都会被带偏'':111B ''建议先标记后观察'':139B ''把盘中价记成'':78B ''抽样比对'':97B ''收盘'':81B ''收盘价偏差'':40B ''有人用'':69B ''未清理'':22B ''未落'':49B ''根因已修'':90B ''比对'':31B ''涨跌'':110B ''清理建议'':112B ''的诊断一致'':82B ''盘中跑全市场回补'':77B ''精确定位'':127B ''线'':25B,51B ''线一致性'':99B ''线中根本不存在'':47B ''线的正常行'':136B ''绝大多数标的的'':53B ''行'':38B,57B,130B ''行中'':35B ''行含未同步'':134B ''行的日期在'':45B ''资金流'':108B ''重要'':1A,10B ''需人工批准'':113B ''需先剔除该部分再判'':137B ''非交易日'':48B ''非交易日不落库'':96B ''非交易日行按交易日历定位'':131B', '2026-09-11 23:19:52.873033', '2026-09-11 23:19:52.873033', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('7798f0fa-7b81-4217-9da4-ba97ec1031e3', 'quant.stock_fund_flow 污染是**两次批量事故**而非一次（2026-09-11', 'quant.stock_fund_flow 污染是**两次批量事故**而非一次（2026-09-11 圈定，w-f436d4ea）：建证据表 quant.stock_fund_flow_suspect（14,314 行，字段 symbol/trade_date/flow_close/kline_close/deviation_pct/flow_change_pct/main_net_inflow/source/reason/flagged_at）。按日期：**2026-09-10 = 5,233 行**、**2026-09-01 = 4,471 行**（两次都近乎全市场），另有 2026-07-28(215)、09-03(174)、09-09(167) 等长尾。偏差分档：<1% 3,152、1-3% 6,186、3-5% 3,521、**≥5% 1,455**。受影响标的 **5,436 只**（≈全市场）。已备份 quant.stock_fund_flow_backup_20260911（81,335 行，**仅数据，索引/约束未备份，恢复需重建**）。**未删除任何行**。消费者规避写法：`SELECT ... FROM quant.stock_fund_flow f WHERE NOT EXISTS (SELECT 1 FROM quant.stock_fund_flow_suspect s WHERE s.symbol=f.symbol AND s.trade_date=f.trade_date)`。根因已修（adaec83c 两道闸门：非交易日不落库 + 抽样比对K线一致性），**新增污染不会再发生**。下一步建议：如需消费者默认看不到坏行，可加表内布尔列（需 migration 脚本 + ORM 字段，按本仓约定 migration 是 `--apply` 式独立脚本）。', 'knowledge', '{数据质量,fund_flow,两次事故,证据表,备份,未删除}', NULL, '''-01'':42B ''-03'':53B ''-07'':49B ''-09'':8A,17B,35B,41B,56B ''-10'':36B ''-11'':9A,18B ''-28'':50B ''-3'':64B ''-5'':68B ''09'':52B,55B ''1'':60B,63B,72B,104B ''14'':28B ''152'':62B ''167'':57B ''174'':54B ''186'':66B ''2026'':7A,16B,34B,40B,48B ''20260911'':84B ''215'':51B ''233'':38B ''3'':61B,67B,69B ''314'':29B ''335'':86B ''4'':43B ''436'':76B ''455'':73B ''471'':44B ''5'':37B,71B,75B ''521'':70B ''6'':65B ''81'':85B ''adaec83c'':120B ''and'':114B ''apply'':136B ''backup'':83B ''date'':116B,118B ''exists'':102B ''f'':99B ''f.symbol'':113B ''f.trade'':117B ''f436d4ea'':22B ''flow'':3A,12B,26B,82B,98B,108B ''from'':95B,105B ''fund'':2A,11B,25B,81B,97B,107B ''migration'':129B,134B ''not'':101B ''orm'':131B ''quant.stock'':1A,10B,24B,80B,96B,106B ''s'':110B ''s.symbol'':112B ''s.trade'':115B ''select'':94B,103B ''suspect'':27B,109B ''symbol/trade_date/flow_close/kline_close/deviation_pct/flow_change_pct/main_net_inflow/source/reason/flagged_at'':32B ''w'':21B ''w-f436d4ea'':20B ''where'':100B,111B ''下一步建议'':125B ''两次批量事故'':5A,14B ''两次都近乎全市场'':46B ''两道闸门'':121B ''仅数据'':88B ''偏差分档'':59B ''全市场'':78B ''受影响标的'':74B ''另有'':47B ''只'':77B ''可加表内布尔列'':127B ''圈定'':19B ''如需消费者默认看不到坏行'':126B ''字段'':31B,132B ''已备份'':79B ''建证据表'':23B ''式独立脚本'':137B ''恢复需重建'':91B ''抽样比对k线一致性'':123B ''按日期'':33B ''按本仓约定'':133B ''新增污染不会再发生'':124B ''是'':135B ''未删除任何行'':92B ''根因已修'':119B ''污染是'':4A,13B ''消费者规避写法'':93B ''等长尾'':58B ''索引'':89B ''约束未备份'':90B ''而非一次'':6A,15B ''脚本'':130B ''行'':30B,39B,45B,87B ''需'':128B ''非交易日不落库'':122B', '2026-09-11 23:20:47.309034', '2026-09-11 23:20:47.309034', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('3f59591d-7c8b-47dd-a25b-2fe40265cc9b', '工程纪律（2026-09-11，w-f436d4ea，亲历）：**打印『完成』不等于已提交**。我在', '工程纪律（2026-09-11，w-f436d4ea，亲历）：**打印『完成』不等于已提交**。我在 `with eng.begin() as c:` 事务里执行 `CREATE TABLE ... AS SELECT` 并立刻 `print(''备份完成: 行数='', n)`，之后同一脚本因 `round()` 报错抛异常 → 整个事务回滚 → **备份表被静默丢弃，而日志上赫然写着『备份完成 81335 行』**。我随后回头独立验证才发现该表根本不存在。纪律：①任何写操作的成功判定必须来自**提交之后、独立连接**的读回验证（本次用 `E.dispose_engine()` 后重连确认），不能采信事务内的可见性；②把多个写操作放在同一事务里时，后一步失败会连带回滚前一步的『成功』——备份、DDL 这类操作应各自独立提交；③这与本日其他几次教训同族：拿『当时的可见性/截断的视图/展示层的渲染』当事实。', 'experience', '{工程纪律,事务,回滚,假成功,独立验证,备份}', NULL, '''-09'':3A,15B ''-11'':4A,16B ''2026'':2A,14B ''81335'':46B ''as'':27B,32B ''c'':28B ''create'':30B ''ddl'':63B ''e.dispose'':55B ''eng.begin'':26B ''engine'':56B ''f436d4ea'':7A,19B ''n'':38B ''print'':35B ''round'':40B ''select'':33B ''table'':31B ''w'':6A,18B ''w-f436d4ea'':5A,17B ''with'':25B ''不等于已提交'':11A,23B ''不能采信事务内的可见性'':58B ''之后同一脚本因'':39B ''事务里执行'':29B ''亲历'':8A,20B ''任何写操作的成功判定必须来自'':50B ''后一步失败会连带回滚前一步的'':60B ''后重连确认'':57B ''备份'':62B ''备份完成'':36B,45B ''备份表被静默丢弃'':43B ''完成'':10A,22B ''展示层的渲染'':69B ''工程纪律'':1A,13B ''并立刻'':34B ''当事实'':70B ''当时的可见性'':67B ''成功'':61B ''我在'':12A,24B ''我随后回头独立验证才发现该表根本不存在'':48B ''截断的视图'':68B ''打印'':9A,21B ''把多个写操作放在同一事务里时'':59B ''报错抛异常'':41B ''拿'':66B ''提交之后'':51B ''整个事务回滚'':42B ''本次用'':54B ''独立连接'':52B ''的读回验证'':53B ''纪律'':49B ''而日志上赫然写着'':44B ''行'':47B ''行数'':37B ''这与本日其他几次教训同族'':65B ''这类操作应各自独立提交'':64B', '2026-09-11 23:20:59.427299', '2026-09-11 23:20:59.427299', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('f0606056-2da7-4b6c-b2da-97de7fbe9716', '工程纪律（2026-09-11，w-f436d4ea）——**回归命令的范围本身就是一条易错的隐含假', '工程纪律（2026-09-11，w-f436d4ea）——**回归命令的范围本身就是一条易错的隐含假设**：我一整天用 `pytest tests/domain tests/adapters/outbound/datasources tests/application` 作为回归口径，并据此反复报告『12 failed / N passed』；直到核对提交信息里的数字对不上（我写 1003、实际 999）才发现——**该命令漏掉了 `tests/adapters/outbound/repositories` 整个目录**，而我今天新加的 7 个测试（test_fund_flow_quality_flag 3 例、test_orphan_run_task_sync 4 例）正好都在那里。它们单跑全绿，但从未进入我一直在跑的回归。正确口径：`pytest tests/domain tests/adapters tests/application tests/infrastructure` → **18 failed / 1088 passed**（18 = 12 domain + 3 infrastructure/config + 3 test_simulation_*_repository，全为存量）。教训：①报『测试通过』时必须同时说明**跑的是哪个范围**，范围本身就是结论的一部分；②新增测试后要核对**总数变化是否与新增数一致**（999→1003 才会暴露漏收集），这是最廉价的漏收集探测器；③宁可跑更宽的目录，不要用窄口径换来好看的通过率。', 'experience', '{工程纪律,测试范围,漏收集,回归口径,数字对账}', NULL, '''-09'':3A,11B ''-11'':4A,12B ''1003'':30B,86B ''1088'':65B ''12'':24B,68B ''18'':63B,67B ''2026'':2A,10B ''3'':45B,70B,72B ''4'':52B ''7'':38B ''999'':32B,85B ''domain'':69B ''f436d4ea'':7A,15B ''failed'':25B,64B ''flag'':44B ''flow'':42B ''fund'':41B ''infrastructure/config'':71B ''n'':26B ''orphan'':48B ''passed'':27B,66B ''pytest'':18B,58B ''quality'':43B ''repository'':75B ''run'':49B ''simulation'':74B ''sync'':51B ''task'':50B ''test'':40B,47B,73B ''tests/adapters'':60B ''tests/adapters/outbound/datasources'':20B ''tests/adapters/outbound/repositories'':35B ''tests/application'':21B,61B ''tests/domain'':19B,59B ''tests/infrastructure'':62B ''w'':6A,14B ''w-f436d4ea'':5A,13B ''不要用窄口径换来好看的通过率'':90B ''个测试'':39B ''但从未进入我一直在跑的回归'':56B ''作为回归口径'':22B ''例'':46B,53B ''全为存量'':76B ''回归命令的范围本身就是一条易错的隐含假'':8A ''回归命令的范围本身就是一条易错的隐含假设'':16B ''宁可跑更宽的目录'':89B ''它们单跑全绿'':55B ''实际'':31B ''工程纪律'':1A,9B ''并据此反复报告'':23B ''总数变化是否与新增数一致'':84B ''我一整天用'':17B ''我写'':29B ''才会暴露漏收集'':87B ''才发现'':33B ''报'':78B ''教训'':77B ''整个目录'':36B ''新增测试后要核对'':83B ''时必须同时说明'':80B ''正好都在那里'':54B ''正确口径'':57B ''测试通过'':79B ''直到核对提交信息里的数字对不上'':28B ''而我今天新加的'':37B ''范围本身就是结论的一部分'':82B ''该命令漏掉了'':34B ''跑的是哪个范围'':81B ''这是最廉价的漏收集探测器'':88B', '2026-09-11 23:38:20.492417', '2026-09-11 23:38:20.492417', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('ed2046e7-5cd6-4253-b757-5fe8e11cc0b8', 'reminder evolution-weekly-variant delivered', '{"task":"evolution-weekly-variant","task_id":"73c1127a-8733-4ce5-ba39-e56d2f2fb10d","prompt":"【技能指引】本任务属 engine-heal-evolve 覆盖场景（决策系统自进化流水线）：执行前先调用 skill 工具（name=engine-heal-evolve）加载 SOP，按其流程纪律完成（信号源/对象健康核验→取证→单主题修补→验证→汇报）。本 prompt 的具体动作要求为任务主体，skill 提供流程纪律与禁止清单，二者冲突时以本 prompt 为准。\n【周度进化-变异 周六10:00】执行 prompt_evolver 工具：从近7天 daily_distill 沉淀的决策记忆（memory_search namespace=decision, query=进化提案）中挑选1-2条高置信度建议，以 candidate 观察版（dry_run=false, observe_days=5）应用进化。要求：①只改一个主题（可归因）；②宪法段（constitution）禁止改动；③每轮变异前先 memory_search 检索历史教训；④完成后用 genome_history 确认版本变化并汇报：改动段落、版本号、观察期到期日。\n\n【汇报要求】完成后必须飞书简报（channel=reports, urgency=normal）：任务名+关键结果摘要（1-3行）；发现异常则 urgency=high 发 alerts 群。（简报内容：应用了哪条建议、改了哪段、观察期安排）","window":"w-a8a89c6a","fired_at":"2026-09-12T02:00:00Z","delivered":true,"delivered_at":"2026-09-12T02:00:00.207Z","executor":{"mode":"direct","session_id":"session-c8cae280-b2a4-4a2c-abc3-536d6263416e"}}', 'data', '{office:delivered,office:reminder:exec,office:reminder:w-c8cae280}', NULL, '''-09'':135B,145B ''-12'':136B,146B ''-3'':116B ''-4'':16B ''-8733'':15B ''00'':60B,138B,148B ''00.207'':149B ''00z'':139B ''1'':115B ''2026'':134B,144B ''2条高置信度建议'':77B ''4a2c'':160B ''5'':86B ''536d6263416e'':162B ''73c1127a'':14B ''a8a89c6a'':131B ''abc3'':161B ''alerts'':122B ''at'':133B,143B ''b2a4'':159B ''ba39'':19B ''c8cae280'':158B ''candidate'':79B ''ce5'':18B ''ce5-ba39-e56d2f2fb10d'':17B ''channel'':109B ''constitution'':92B ''daily'':66B ''days'':85B ''decision'':72B ''delivered'':6A,140B,142B ''direct'':153B ''distill'':67B ''dry'':81B ''e56d2f2fb10d'':20B ''engine'':25B,35B ''engine-heal-evolve'':24B,34B ''evolution'':3A,9B ''evolution-weekly-variant'':2A,8B ''evolve'':27B,37B ''evolver'':63B ''executor'':151B ''false'':83B ''fired'':132B ''genome'':99B ''heal''