INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('2f0e2cb1-581d-4ebb-ad04-c2c0419ce4ca', '【工具健康异常 · 账户类接口超时 · w-c8cae280 · 2026-09-12 22:07】', '【工具健康异常 · 账户类接口超时 · w-c8cae280 · 2026-09-12 22:07】现象：account_info(10s)、position_list(10s) 连续超时，portfolio_analyze 30s 超时。定位（curl 实测单次采样）：**GET /api/simulation/accounts/agent_virtual → HTTP 200 但耗时 16.31s**；对照端点均正常：/api/agent/positions 0.015s、/api/positions 0.13s、/api/evolution/decision-scores 0.010s、/api/scheduler/tasks 0.018s。即**服务未挂、只是账户端点慢**（16.3s 超过工具 10s/30s 超时阈值 → 工具层表现为『超时』而非『数据错误』）。影响：所有窗口的持仓/账户类工具在慢时段不可用，且**失败形态是超时**——容易被误读为『没有持仓』或『账户异常』，R-013 意义上不可作为决策依据。建议：①account_info/position_list 的 timeoutMs 是否可提到 20s 以上（或后端加缓存/降级）；②账户端点为何 16s（疑似行情刷新同步路径）需单独排查。佐证：同一会话更早（21:02）同样调用 account_info 是正常的，说明为时段性/负载相关。', 'knowledge', '{工具健康,账户接口,性能异常,2026-09-12}', NULL, '''-013'':78B ''-09'':7A,17B ''-12'':8A,18B ''/api/agent/positions'':44B ''/api/evolution/decision-scores'':50B ''/api/positions'':47B ''/api/scheduler/tasks'':53B ''/api/simulation/accounts/agent_virtual'':37B ''0.010'':51B ''0.015'':45B ''0.018'':54B ''0.13'':48B ''02'':97B ''07'':10A,20B ''10s'':24B,27B ''10s/30s'':62B ''16.3'':59B ''16.31'':41B ''16s'':91B ''200'':39B ''2026'':6A,16B ''20s'':86B ''21'':96B ''22'':9A,19B ''30s'':31B ''account'':22B,81B,99B ''analyze'':30B ''c8cae280'':5A,15B ''curl'':34B ''get'':36B ''http'':38B ''info'':23B,100B ''info/position_list'':82B ''list'':26B ''portfolio'':29B ''position'':25B ''r'':77B ''s'':42B,46B,49B,52B,55B,60B ''timeoutms'':84B ''w'':4A,14B ''w-c8cae280'':3A,13B ''且'':71B ''以上'':87B ''但耗时'':40B ''佐证'':94B ''即'':56B ''只是账户端点慢'':58B ''同一会话更早'':95B ''同样调用'':98B ''失败形态是超时'':72B ''定位'':33B ''实测单次采样'':35B ''容易被误读为'':73B ''对照端点均正常'':43B ''工具健康异常'':1A,11B ''工具层表现为'':64B ''建议'':80B ''影响'':68B ''意义上不可作为决策依据'':79B ''或'':75B ''或后端加缓存'':88B ''所有窗口的持仓'':69B ''数据错误'':67B ''是否可提到'':85B ''是正常的'':101B ''服务未挂'':57B ''没有持仓'':74B ''现象'':21B ''疑似行情刷新同步路径'':9