INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('7142380b-10ed-437a-988b-ab8292d5f30a', 'SYSTEM loss 横截面动量策略 + 候选池 universe 回测', 'SYSTEM 交易经验（2026-09-13T04:53:46.292Z）
