INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('f817f786-e4bc-49bf-8abe-a8ce3a81da56', '2026-09-12 23:39-23:50 发版链路加固（w-adb088f2，commit 30', '2026-09-12 23:39-23:50 发版链路加固（w-adb088f2，commit 304d9e03）。【问题一：9 个包根本构建不出来】实测全仓 **19 个包** main 指向 ./dist/index.mjs（原脚本硬编码只构建 2 个 client，注释断言『其余包 tsx 直载 TS』与事实不符）。其中 9 个包（competition/data-manager/evolution/factor/market/memory/notification/risk/trading）在 tsdown --dts 阶段报 **TS2742**（static Config 推断类型需引用 .pnpm/@deepseek-ai+schemastery 内部路径、不可移植）→ 这些包 dist 永远无法重建、源码改动再多也上不了线。修法=给 static Config 加显式类型注解 : any（仅类型层）。【问题二：tsdown 失败会先清空 dist（真实事故）】首次 --build-only 时 competition 构建失败，其 dist/index.mjs 被清空 → 若此时重启该插件会直接消失。我当场诊断（产物缺失+报错 TS2742）→ 修注解 → 重建恢复（49213 bytes）→ 给脚本加『逐包构建前备份 dist、失败即还原』，并在未修注解时用全量构建复验：7 个失败包的 dist **全部从备份还原、零损坏、服务保持原状**。【问题三：脚本改为自动判定】新增 scripts/dist-packages.py（list / verify：按 main 字段判定 + 产物存在 + 不比 src 陈旧），restart-with-build.sh 改为构建全部 dist 包并做**产物严格校验**（不通过拒绝发版），新增 --check / --build-only 两个模式。【结果】--build-only 全量重建 → **19/19 产物校验通过**；故障注入（touch src）→ verify 退出码 1；测试 178/178 通过。【副作用（需知悉）】全量重建后，其他窗口已提交但此前因 dist 陈旧无法生效的改动（data-manager/intelligence/risk 等，含 REQ-9bcd0a 的 decision_scores 等）现在也具备上线条件——**下一次重启会一并生效**。【纪律】他人 quantsys-v2 工作区改动未触碰（status 显示其 barra 小样本工作仍在进行）。', 'knowledge', '{构建阻断,TS2742,发版脚本,dist备份,2026-09-12,w-adb088f2}', NULL, '''-09'':2A,15B ''-12'':3A,16B ''-23'':6A,19B ''/dist/index.mjs'':35B ''/intelligence/risk'':161B ''1'':148B ''178/178'':150B ''19'':31B ''19/19'':141B ''2'':37B ''2026'':1A,14B ''23'':4A,17B ''30'':13A ''304d9e03'':26B ''39'':5A,18B ''49213'':98B ''50'':7A,20B ''7'':105B ''9'':28B,47B ''9bcd0a'':166B ''adb088f2'':11A,24B ''ai'':61B ''any'':74B ''barra'':181B ''build'':83B,133B,138B ''build-only'':82B,132B,137B ''bytes'':99B ''check'':131B ''client'':39B ''commit'':12A,25B ''competition'':86B ''competition/data-manager/evolution/factor/market/memory/notification/risk/trading'':49B ''config'':56B,72B ''data'':159B ''data-manager'':158B ''decision'':168B ''deepseek'':60B ''deepseek-ai'':59B ''dist'':66B,79B,102B,107B,126B,156B ''dist/index.mjs'':89B ''dts'':52B ''list'':115B ''main'':33B,118B ''manager'':160B ''only'':84B,134B,139B ''pnpm'':58B ''quantsys'':176B ''quantsys-v2'':175B ''req'':165B ''req-9bcd0a'':164B ''restart-with-build.sh'':124B ''schemastery'':62B ''scores'':169B ''scripts/dist-packages.py'':114B ''src'':122B,145B ''static'':55B,71B ''status'':179B ''touch'':144B ''ts'':44B ''ts2742'':54B,95B ''tsdown'':51B,77B ''tsx'':42B ''v2'':177B ''verify'':116B,146B ''w'':10A,23B ''w-adb088f2'':9A,22B ''下一次重启会一并生效'':172B ''不可移植'':64B ''不比'':121B ''不通过拒绝发版'':129B ''与事实不符'':45B ''两个模式'':135B ''个'':38B ''个包'':32B,48B ''个包根本构建不出来'':29B ''个失败包的'':106B ''产物严格校验'':128B ''产物存在'':120B ''产物校验通过'':142B ''产物缺失'':93B ''仅类型层'':75B ''他人'':174B ''修法'':69B ''修注解'':96B ''全部从备份还原'':108B ''全量重建'':140B ''全量重建后'':154B ''其'':88B ''其中'':46B ''其他窗口已提交但此前因'':155B ''其余包'':41B ''内部路径'':63B ''副作用'':152B ''加显式类型注解'':73B ''包并做'':127B ''原脚本硬编码只构建'':36B ''发版链路加固'':8A,21B ''含'':163B ''在'':50B ''失败会先清空'':78B ''失败即还原'':103B ''字段判定'':119B ''实测全仓'':30B ''小样本工作仍在进行'':182B ''工作区改动未触碰'':178B ''并在未修注解时用全量构建复验'':104B ''我当场诊断'':92B ''报错'':94B ''指向'':34B ''按'':117B ''推断类型需引用'':57B ''改为构建全部'':125B ''故障注入'':143B ''新增'':113B,130B ''时'':85B ''显示其'':180B ''服务保持原状'':110B ''构建失败'':87B ''永远无法重建'':67B ''注释断言'':40B ''测试'':149B ''源码改动再多也上不了线'':68B ''现在也具备上线条件'':171B ''的'':167B ''直载'':43B ''真实事故'':80B ''等'':162B,170B ''纪律'':173B ''结果'':136B ''给'':70B ''给脚本加'':100B ''脚本改为自动判定'':112B ''若此时重启该插件会直接消失'':91B ''被清空'':90B ''这些包'':65B ''退出码'':147B ''逐包构建前备份'':101B ''通过'':151B ''重建恢复'':97B ''问题一'':27B ''问题三'':111B ''问题二'':76B ''阶段报'':53B ''陈旧'':123B ''陈旧无法生效的改动'':157B ''零损坏'':109B ''需知悉'':153B ''首次'':81B', '2026-09-12 23:41:13.610454', '2026-09-12 23:41:13.610454', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('7efcd42f-2b45-46ce-a645-82ddbc58bf4a', '2026-09-12 TS2742 构建阻断根因查明（w-adb088f2）。【结论：依赖重复导致类', '2026-09-12 TS2742 构建阻断根因查明（w-adb088f2）。【结论：依赖重复导致类型身份不可移植】证据链：①@deepseek-ai/dsh-tools@0.1.2-rc.1 声明 schemastery 依赖区间为 ^3.18.2；而工作区 19 个包全部声明 ^3.18.1。②pnpm 未去重：store 里同时存在 node_modules/.pnpm/@deepseek-ai+schemastery@3.18.1 与 @3.18.2（两者目录创建时间均为 2026-09-12 19:22:17，同一次安装）。③解析方向相反：各包自己的链接指向 3.18.1；而 @deepseek-ai/dsh-tools@0.1.2-rc.1 的链接指向 3.18.2。④报错文本指名的正是 .pnpm/@deepseek-ai+schemastery@3.18.2/node_modules/@deepseek-ai/schemastery。【机制】包的 static Config 类型是经 Service/defineTool 类型面推断出来的，该类型身份的宿主是 3.18.2 那份拷贝；tsdown --dts 生成 index.d.mts 时必须点名该类型，而唯一点名方式是非可移植的 pnpm store 路径 → TS2742。是否触发取决于该包导出面是否必须点名（故 19 个包里 9 个失败、10 个通过——失败组与通过组的 Config schema 文本完全相同，已实测对比 data-manager/factor（失败）与 strategy/investment（通过），schema 一字不差，证明差异不在源码）。【为什么长期潜伏】运行时 tsx 直接剥类型执行，插件加载与功能一切正常；只有构建炸，且 dist 陈旧不影响运行 → 无任何运行时报错，属静默失效。实证：8 个包的 dist 停留在 09-12 16:30（早于 19:22 的双版本安装），此后构建即失败；只要没人构建就没人发现，而那些包的源码改动永远上不了线。【已用修法（叶子级 workaround）】给 static Config 加显式类型注解 any（避免生成需点名的推断类型）；commit 304d9e03 修了 9 个包（competition/data-manager/evolution/factor/market/memory/notification/risk/trading）。【根治建议（未执行）】在根 package.json 的 pnpm.overrides 里把 @deepseek-ai/schemastery 钉到单一版本（如 3.18.2，可同时满足 ^3.18.1 与 ^3.18.2）后重装 → 单一拷贝 → TS2742 消失；现状 overrides 只钉了 @deepseek-ai/dsh-* 与 @deepseek-ai/cordis，漏了 schemastery。因 pnpm install 会影响全部包与并行窗口，故未擅自执行，需用户决定时机。', 'knowledge', '{TS2742,根因,"schemastery 双版本",构建阻断,"pnpm overrides",2026-09-12,w-adb088f2}', NULL, '''-09'':2A,12B,51B ''-12'':3A,13B,52B,142B ''/cordis'':200B ''/dsh-'':195B ''/dsh-tools'':25B,64B ''/factor'':117B ''/node_modules'':76B ''/schemastery'':80B,177B ''0.1.2'':26B,65B ''09'':141B ''10'':107B ''16'':143B ''17'':55B ''19'':33B,53B,103B,146B ''2026'':1A,11B,50B ''22'':54B,147B ''3.18.1'':35B,46B,59B,182B ''3.18.2'':31B,48B,68B,75B,89B,180B,184B ''30'':144B ''304d9e03'':162B ''8'':137B ''9'':105B,164B ''adb088f2'':8A,18B ''ai'':24B,44B,63B,73B,79B,176B,194B,199B ''any'':159B ''commit'':161B ''competition/data-manager/evolution/factor/market/memory/notification/risk/trading'':166B ''config'':84B,110B,157B ''data'':115B ''data-manager'':114B ''deepseek'':23B,43B,62B,72B,78B,175B,193B,198B ''deepseek-ai'':22B,42B,61B,71B,77B,174B,192B,197B ''dist'':132B,139B ''dts'':92B ''index.d.mts'':94B ''install'':205B ''manager'':116B ''modules/.pnpm'':41B ''node'':40B ''overrides'':190B ''package.json'':170B ''pnpm'':36B,70B,97B,204B ''pnpm.overrides'':172B ''rc.1'':27B,66B ''schema'':111B,122B ''schemastery'':29B,45B,74B,202B ''service/definetool'':86B ''static'':83B,156B ''store'':38B,98B ''strategy/investment'':120B ''ts2742'':4A,14B,100B,187B ''tsdown'':91B ''tsx'':127B ''w'':7A,17B ''w-adb088f2'':6A,16B ''workaround'':154B ''一字不差'':123B ''与'':47B,119B,183B,196B ''且'':131B ''两者目录创建时间均为'':49B ''个包'':165B ''个包全部声明'':34B ''个包的'':138B ''个包里'':104B ''个失败'':106B ''个通过'':108B ''为什么长期潜伏'':125B ''会影响全部包与并行窗口'':206B ''依赖区间为'':30B ''依赖重复导致类'':10A ''依赖重复导致类型身份不可移植'':20B ''修了'':163B ''停留在'':140B ''加显式类型注解'':158B ''包的'':82B ''单一拷贝'':186B ''只有构建炸'':130B ''只要没人构建就没人发现'':150B ''只钉了'':191B ''可同时满足'':181B ''叶子级'':153B ''各包自己的链接指向'':58B ''同一次安装'':56B ''后重装'':185B ''因'':203B ''在根'':169B ''声明'':28B ''失败'':118B ''失败组与通过组的'':109B ''如'':179B ''实证'':136B ''属静默失效'':135B ''已实测对比'':113B ''已用修法'':152B ''报错文本指名的正是'':69B ''插件加载与功能一切正常'':129B ''故'':102B ''故未擅自执行'':207B ''文本完全相同'':112B ''无任何运行时报错'':134B ''早于'':145B ''时必须点名该类型'':95B ''是否触发取决于该包导出面是否必须点名'':101B ''未去重'':37B ''未执行'':168B ''机制'':81B ''构建阻断根因查明'':5A,15B ''根治建议'':167B ''此后构建即失败'':149B ''消失'':188B ''漏了'':201B ''现状'':189B ''生成'':93B ''的'':171B ''的双版本安装'':148B ''的链接指向'':67B ''直接剥类型执行'':128B ''类型是经'':85B ''类型面推断出来的'':87B ''结论'':9A,19B ''给'':155B ''而'':60B ''而唯一点名方式是非可移植的'':96B ''而工作区'':32B ''而那些包的源码改动永远上不了线'':151B ''解析方向相反'':57B ''证据链'':21B ''证明差异不在源码'':124B ''该类型身份的宿主是'':88B ''路径'':99B ''运行时'':126B ''通过'':121B ''避免生成需点名的推断类型'':160B ''那份拷贝'':90B ''里同时存在'':39B ''里把'':173B ''钉到单一版本'':178B ''陈旧不影响运行'':133B ''需用户决定时机'':208B', '2026-09-12 23:43:01.182307', '2026-09-12 23:43:01.182307', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('6c5b92f2-4103-415c-92e9-05bb4d62c78d', '【工程教训·同一表达式两套语义】2026-09-12（w-c8cae280）定理：跨组件共享的 cr', '【工程教训·同一表达式两套语义】2026-09-12（w-c8cae280）定理：跨组件共享的 cron 字符串，若两端星期编号约定不同，会整体错位一天且几乎无法自证。APScheduler 的 CronTrigger.from_crontab 用 0=周一…6=周日，而 croniter/robfig-cron/人工习惯用标准 cron 0=周日…6=周六 → 本仓 23/23 个带 DOW 的 v2 任务错位：''30 22 * * 1-5'' 实跑周二~周六（周一一整天无日线流水），''0 1 * * 0'' 实跑周一。三条通用纪律：①共享语法必须在边界处显式翻译并写清两套编号（本次=新增 cron_compat.build_cron_trigger 作为唯一翻译点）②判断''任务是否漏跑''不能用''有没有未来排期''——漏跑后排期本就会推到下个周期，必须用 misfire 宽限期判定 ③启动期对账要注意库/存储的可见性：APScheduler 未 start 时 get_jobs() 只看本次会话 pending job，看不到 jobstore 历史 job（导致禁用任务残留 15 天）。附带教训：初判''漏跑''是错的，靠 apscheduler_jobs 的 epoch 与 last_run 的星期做交叉验证才推翻——诊断必须落到执行器的真实排期上。', 'experience', '{scheduler,cron,DOW,APScheduler,看门狗,静默缺陷,w-c8cae280}', NULL, '''-09'':4A,15B ''-12'':5A,16B ''-5'':53B ''0'':31B,39B,57B,59B ''1'':52B,58B ''15'':93B ''2026'':3A,14B ''22'':51B ''23/23'':44B ''30'':50B ''6'':33B,41B ''apscheduler'':26B,79B,100B ''c8cae280'':8A,19B ''cr'':11A ''cron'':22B,38B,66B ''cron_compat.build'':65B ''croniter/robfig-cron'':36B ''crontab'':29B ''crontrigger.from'':28B ''dow'':46B ''epoch'':103B ''get'':83B ''job'':87B,91B ''jobs'':84B,101B ''jobstore'':89B ''last'':105B ''misfire'':75B ''pending'':86B ''run'':106B ''start'':81B ''trigger'':67B ''v2'':48B ''w'':7A,18B ''w-c8cae280'':6A,17B ''三条通用纪律'':61B ''不能用'':71B ''与'':104B ''个带'':45B ''人工习惯用标准'':37B ''任务是否漏跑'':70B ''任务错位'':49B ''会整体错位一天且几乎无法自证'':25B ''作为唯一翻译点'':68B ''共享语法必须在边界处显式翻译并写清两套编号'':62B ''初判'':96B ''判断'':69B ''历史'':90B ''只看本次会话'':85B ''同一表达式两套语义'':2A,13B ''启动期对账要注意库'':77B ''周一'':32B ''周一一整天无日线流水'':56B ''周六'':42B,55B ''周日'':34B,40B ''天'':94B ''字符串'':23B ''存储的可见性'':78B ''定理'':9A,20B ''实跑周一'':60B ''实跑周二'':54B ''宽限期判定'':76B ''导致禁用任务残留'':92B ''工程教训'':1A,12B ''必须用'':74B ''新增'':64B ''时'':82B ''是错的'':98B ''有没有未来排期'':72B ''未'':80B ''本仓'':43B ''本次'':63B ''漏跑'':97B ''漏跑后排期本就会推到下个周期'':73B ''用'':30B ''的'':27B,47B,102B ''的星期做交叉验证才推翻'':107B ''看不到'':88B ''而'':35B ''若两端星期编号约定不同'':24B ''诊断必须落到执行器的真实排期上'':108B ''跨组件共享的'':10A,21B ''附带教训'':95B ''靠'':99B', '2026-09-13 00:33:58.699932', '2026-09-13 00:33:58.699932', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('9729b170-8dd2-4e01-87f8-498b7c818fa0', '【2026-09-12 调度体系修复·验收】①DOW 口径统一：新增 quantsys-v2/inf', '【2026-09-12 调度体系修复·验收】①DOW 口径统一：新增 quantsys-v2/infrastructure/scheduler/cron_compat.py，重启后 apscheduler_jobs 与 croniter 23/23 一致（每日数据更新 Mon 22:30、周度财务更新 Sat 18:30、v13 周报 Sun 01:00）；测试 tests/infrastructure/test_cron_dow_convention.py 8 例通过。②启动对账时序：start() 在 scheduler.start() 之后再对账 + enable/disable 立即 reload；故障注入验证（直连 DB 启用 250 → reload → 直连 DB 禁用 → 重启）日志 🧹 摘除 task_250，job 28→27。③看门狗：豁免改为 misfire 宽限期判定 + 新增未打标检测，干跑即报出 2 项此前不可见的真漏跑（09-12 02:00 / 18:30 两个周六槽位）。④写入路径：agent_line 放开 NOT NULL/DEFAULT（备份 /tmp/tasks_agentline_20260913-003247，27 行），Go Create/Update/DTO + scheduler_manage 入参支持；E2E 带值 201/other、不带值 201/NULL、PUT 改 account 通过。⑤补跑：253 success、238 success。提交 c249d163。数据来源：DB 直查 + API 实测 + 日志（2026-09-12 23:00-00:40）。', 'knowledge', '{scheduler,DOW,对账,agent_line,REQ-9bcd0a}', NULL, '''-00'':131B ''-09'':2A,14B,127B ''-12'':3A,15B,83B,128B ''/inf'':12A ''/infrastructure/scheduler/cron_compat.py'':24B ''/tmp/tasks_agentline_20260913-003247'':96B ''00'':44B,85B,130B ''01'':43B ''02'':84B ''09'':82B ''18'':38B,86B ''2'':80B ''201/null'':108B ''201/other'':106B ''2026'':1A,13B,126B ''22'':34B ''23'':129B ''23/23'':30B ''238'':116B ''250'':61B,70B ''253'':114B ''27'':73B,97B ''28'':72B ''30'':35B,39B,87B ''40'':132B ''8'':47B ''account'':111B ''agent'':90B ''api'':123B ''apscheduler'':26B ''c249d163'':119B ''create/update/dto'':100B ''croniter'':29B ''db'':59B,64B,121B ''dow'':6A,18B ''e2e'':104B ''enable/disable'':54B ''go'':99B ''job'':71B ''jobs'':27B ''line'':91B ''manage'':102B ''misfire'':76B ''mon'':33B ''not'':93B ''null/default'':94B ''put'':109B ''quantsys'':10A,22B ''quantsys-v2'':9A,21B ''reload'':56B,62B ''sat'':37B ''scheduler'':101B ''scheduler.start'':52B ''start'':50B ''success'':115B,117B ''sun'':42B ''task'':69B ''tests/infrastructur