INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('970f74c1-9d4b-4973-9399-dcffec39ffe4', '【工程教训·空结果不得当有效结果（调度器版）】2026-09-13（w-c8cae280）我改名任务', '【工程教训·空结果不得当有效结果（调度器版）】2026-09-13（w-c8cae280）我改名任务后调 POST /api/scheduler/reload，返回 success 且日志打「✅ Tasks reloaded」，实际把 public.apscheduler_jobs 里 27 个 job 全部清空、调度静默停摆。根因链：reload_tasks() 先 remove_all_jobs() 再靠 load_tasks_from_db() 重建，而 repo.list_tasks 对读库异常**静默 return []** → 0 条重载 + 报成功。护栏（三层 + 3 例回归测）：①列表空但 count>0 → 判读取异常，return None 中止（不加载不对账）②reconcile 拒绝空 desired_ids ③reload 去掉 remove_all_jobs 改纯增量对账 ④repo 异常必须 logger.error(exc_info=True) 不许静默吞。通用纪律：任何『先清空再重建』的 reload/同步逻辑，必须在清空前先验证新集合非空且可信；repo 层不得把异常伪装成空集。', 'experience', '{scheduler,APScheduler,jobstore,空结果,静默失败,事故,w-c8cae280}', NULL, '''-09'':5A,15B ''-13'':6A,16B ''/api/scheduler/reload'':22B ''0'':56B,65B ''2026'':4A,14B ''27'':32B ''3'':61B ''all'':42B,78B ''c8cae280'':9A,19B ''count'':64B ''db'':48B ''desired'':73B ''exc'':84B ''from'':47B ''ids'':74B ''info'':85B ''job'':34B ''jobs'':30B,43B,79B ''load'':45B ''logger.error'':83B ''none'':68B ''post'':21B ''public.apscheduler'':29B ''reconcile'':71B ''reload'':38B,75B,92B ''reloaded'':27B ''remove'':41B,77B ''repo'':81B,95B ''repo.list'':51B ''return'':55B,67B ''success'':24B ''tasks'':26B,39B,46B,52B ''true'':86B ''w'':8A,18B ''w-c8cae280'':7A,17B ''三层'':60B ''不加载不对账'':70B ''不许静默吞'':87B ''且日志打'':25B ''个'':33B ''中止'':69B ''任何'':89B ''例回归测'':62B ''先'':40B ''先清空再重建'':90B ''全部清空'':35B ''再靠'':44B ''列表空但'':63B ''判读取异常'':66B ''去掉'':76B ''同步逻辑'':93B ''实际把'':28B ''对读库异常'':53B ''层不得把异常伪装成空集'':96B ''工程教训'':1A,11B ''异常必须'':82B ''必须在清空前先验证新集合非空且可信'':94B ''我改名任务'':10A ''我改名任务后调'':20B ''护栏'':59B ''报成功'':58B ''拒绝空'':72B ''改纯增量对账'':80B ''条重载'':57B ''根因链'':37B ''的'':91B ''空结果不得当有效结果'':2A,12B ''而'':50B ''调度器版'':3A,13B ''调度静默停摆'':36B ''返回'':23B ''通用纪律'':88B ''里'':31B ''重建'':49B ''静默'':54B', '2026-09-13 01:07:30.95644', '2026-09-13 01:07:30.95644', '{}'