INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('999bf167-c2ae-40fc-9f34-74e918f78e7a', '【发版+上线核验 · w-adb088f2 · 2026-09-13 01:03-01:07】HEA', '【发版+上线核验 · w-adb088f2 · 2026-09-13 01:03-01:07】HEAD 5ce18fda 完整发版通过四层体检（manifest result=PASS、process_verified=true）。
