INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('92ebbcfd-bdda-47f8-bc3d-0578c5447bdb', '【工程教训·有字段≠有能力】2026-09-13（w-c8cae280）用户问「定时任务是否都能按业', '【工程教训·有字段≠有能力】2026-09-13（w-c8cae280）用户问「定时任务是否都能按业务规则补跑」→ 审计发现：明明有 compensation_enabled / compensation_check_after / compensation_max_attempts 三个字段、有 AUTO_RERUN 开关、有 trigger API，但①两个参数是死字段（创建时写进 params 的 _compensation_* 后全仓无读取方）②自动补跑只有一个布尔位条件，无窗口、无覆盖判定、无次数落地、无时段感知、无留痕③OS 侧 metadata.watchdog 全 NULL → 27 个任务全部只告警。教训：评估「某能力是否实现」必须沿数据流走到底——字段存在、开关存在、API 存在，都不等于能力存在；要看最后一个消费者有没有，以及判定条件是否覆盖业务约束（时间窗/重复/次数/时段）。本次补齐：7 条判定的规则引擎（含 superseded 覆盖判定）+ 留痕表 scheduler_catchup_log + 按业务含义分级授权（交易敏感 3h / 盘后 12h / 周度 48h / 有交易副作用不授权），以 10 单测 + 真实数据 + 执行路径 E2E 验证。', 'experience', '{scheduler,补跑,业务规则,watchdog,死字段,w-c8cae280}', NULL, '''-09'':5A,16B ''-13'':6A,17B ''10'':95B ''12h'':90B ''2026'':4A,15B ''27'':59B ''3h'':88B ''48h'':92B ''7'':77B ''after'':29B ''api'':40B,67B ''attempts'':32B ''auto'':35B ''c8cae280'':9A,20B ''catchup'':84B ''check'':28B ''compensation'':25B,27B,30B,46B ''e2e'':99B ''enabled'':26B ''log'':85B ''max'':31B ''metadata.watchdog'':56B ''null'':58B ''os'':54B ''params'':44B ''rerun'':36B ''scheduler'':83B ''superseded'':80B ''trigger'':39B ''w'':8A,19B ''w-c8cae280'':7A,18B ''三个字段'':33B ''两个参数是死字段'':42B ''个任务全部只告警'':60B ''交易敏感'':87B ''以'':94B ''以及判定条件是否覆盖业务约束'':71B ''但'':41B ''侧'':55B ''全'':57B ''创建时写进'':43B ''单测'':96B ''后全仓无读取方'':47B ''含'':79B ''周度'':91B ''字段存在'':65B ''存在'':68B ''定时任务是否都能按业'':11A ''定时任务是否都能按业务规则补跑'':22B ''审计发现'':23B ''工程教训'':1A,12B ''开关'':37B ''开关存在'':66B ''必须沿数据流走到底'':64B ''执行路径'':98B ''按业务含义分级授权'':86B ''教训'':61B ''无时段感知'':52B ''无次数落地'':51B ''无留痕'':53B ''无窗口'':49B ''无覆盖判定'':50B ''时段'':75B ''时间窗'':72B ''明明有'':24B ''有'':34B,38B ''有交易副作用不授权'':93B ''有字段'':2A,13B ''有能力'':3A,14B ''本次补齐'':76B ''条判定的规则引擎'':78B ''某能力是否实现'':63B ''次数'':74B ''用户问'':10A,21B ''留痕表'':82B ''的'':45B ''盘后'':89B ''真实数据'':97B ''自动补跑只有一个布尔位条件'':48B ''要看最后一个消费