INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('8956dc22-d2e3-4b92-b785-4a70c8c4c127', '【会话启动缺口审计 + 已补】2026-09-13（w-c8cae280）：用户问「Greeting', '【会话启动缺口审计 + 已补】2026-09-13（w-c8cae280）：用户问「Greeting and session start 还缺少什么内容，影响超额利润」——''Greeting and session start'' 是 DSH 会话标题（由会话启动标记生成）。审计事实：会话启动只加载静态层（身份 + 基因组 constitution g31/principles v6/rules/lessons + 2× CLAUDE.md 工作区指令 + 技能目录 + 运行时快照），**无任何实时投资事实注入**；记忆召回注入率 7%（8254/121497，压制 100% 为 empty-result，即库里确实没有）。缺五类事实（按 alpha 影响排序）：①我的业绩先验（decision_scores 27 条、买入 20 日平均超额 -10.24%、18/27 big_loss、最差 -44.41%；归因显示 +7.67% 超额来自不参与而非选股）②账户与风险额度（现金 87%、仓位 12.8%、regime risk_off+degraded 上限 40%、熔断 -1.83%）③时间与可交易性（今天周六，会话开始不知道不能下单）④市场与催化剂（情绪/主线/事件日历/持仓解禁财报）⑤未闭环（公告板 open 含别人评审请求、逾期未评估决策、看门狗未闭环、3 条 09-10/09-11 过期未裁决 candidate）。已补：新建 agent-dh/skills/session-briefing/SKILL.md（技能加载实测 provider=filesystem 指向仓库）+ 基因组规则 R-018（rules v18→19 / g32，candidate，仅增无删，benchmark 结构复核通过），提交 35d94493。待定：是否加聚合工具 session_briefing（减少 8-10 次调用）与是否做成 systemPrompt 段落（启动即带，代价是每次组装拉实时数据）。另发现漂移风险：~/.dsh-agent-dh/skills/* 是 agent-dh/skills/* 的手工副本（当前内容一致），有再次漂移的系统性风险。', 'knowledge', '{session-start,briefing,超额利润,缺口,R-018,w-c8cae280}', NULL, '''+7.67'':76B ''-018'':124B ''-09'':4A,14B ''-1.83'':90B ''-10'':108B,141B ''-10.24'':69B ''-13'':5A,15B ''-44.41'':74B ''/.dsh-agent-dh/skills'':149B ''/09-11'':109B ''/skills'':154B ''/skills/session-briefing/skill.md'':117B ''09'':107B ''100'':51B ''12.8'':82B ''18/27'':70B ''19'':127B ''2'':41B ''20'':67B ''2026'':3A,13B ''27'':64B ''3'':105B ''35d94493'':134B ''40'':88B ''7'':48B ''8'':140B ''8254/121497'':49B ''87'':80B ''agent'':115B,152B ''agent-dh'':114B,151B ''alpha'':59B ''and'':21B,27B ''benchmark'':131B ''big'':71B ''briefing'':138B ''c8cae280'':8A,18B ''candidate'':111B,129B ''claude.md'':42B ''constitution'':38B ''decision'':62B ''degraded'':86B ''dh'':116B,153B ''dsh'':31B ''empty'':54B ''empty-result'':53B ''filesystem'':120B '