INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('1969bec5-85ee-44cf-8e3e-5db1144cd2a4', '【错误事件 8006b7ea 处置 · w-32314d00】发送时效性告警失败: Logger._', '【错误事件 8006b7ea 处置 · w-32314d00】发送时效性告警失败: Logger._log() got an unexpected keyword argument ''symbol''。根因=logger 类型不匹配：infrastructure/jobs/financial_timeliness_check_job._send_timeliness_alert 用 structlog 风格（symbol=/expected_date=/message=）调用**标准库** logging.getLogger 的 logger（标准库只认 exc_info/stack_info/stacklevel/extra）→ 必抛 TypeError 且被同函数 except 吞掉 → 告警正文从未落日志，只留症状级 error（09-12/09-13 各一次）。历史链条：09-10 system_logs UndefinedColumn(2 条) → 09-11 KeyError ''symbol''(bd03ca47) → 09-12/13 TypeError（本事件）——**打地鼠**：09-11 把 check_result[''symbol''] 改成 .get() 只把失败点从取值挪到调用本身，没验证调用是否合法。修复：①改标准库合法 %s 惰性格式化（告警正文确保落日志）②except 加 exc_info=True ③全仓 AST 扫描同类缺陷（仅此 1 处真阳性；logging/config.py 4 处是 structlog 假阳性）④新增 tests/test_financial_timeliness_alert.py 4 条（含 stdlib logger 禁非法 kwargs 的静态护栏）。验证：线上 POST /api/scheduler/tasks/318/trigger（run_id=3680）日志出现完整告警正文、新增错误串 0 次（修复前日志第 171028/211937 行）；pytest 4 passed；handler 为运行期惰性 import 故无需重启。附带发现：财报数据实际超期 6 天（预期报告期 2026-06-30，quant.balance_sheets 最新 report_date 2026-03-31），告警本该 09-10 送达却因链路坏了无人看见；且该告警目前只写日志未投递（建议接 NotificationFacade，需人工确认）。教训=①异常被业务层吞掉时 scheduler_tasks.last_status 仍记 success（"任务成功但功能失败"）；②修异常取值前必须先证伪"调用本身合法"。', 'knowledge', '{error-event,8006b7ea,logging,stdlib-vs-structlog,financial_timeliness,w-32314d00}', NULL, '''-03'':148B ''-06'':140B ''-10'':55B,152B ''-11'':62B,73B ''-12'':50B,67B ''-30'':141B ''-31'':149B ''/09-13'':51B ''/13'':68B ''/api/scheduler/tasks/318/trigger'':116B ''/expected_date'':31B ''/message'':32B ''0'':122B ''09'':49B,54B,61B,66B,72B,151B ''1'':96B ''171028/211937'':125B ''2'':59B ''2026'':139B,147B ''32314d00'':6A,14B ''3680'':119B ''4'':99B,105B,128B ''6'':136B ''8006b7ea'':2A,10B ''an'':18B ''argument'':21B ''ast'':93B ''bd03ca47'':65B ''check'':75B ''date'':146B ''error'':48B ''exc'':39B,89B ''except'':44B,87B ''get'':79B ''got'':17B ''handler'':130B ''id'':118B ''import'':132B ''info'':90B ''info/stack_info/stacklevel/extra'':40B ''infrastructure/jobs/financial_timeliness_check_job._send_timeliness_alert'':26B ''keyerror'':63B ''keyword'':20B ''kwargs'':111B ''logger'':24B,37B,109B ''logger._'':8A ''logger._log'':16B ''logging.getlogger'':35B ''logging/config.py'':98B ''logs'':57B ''notificationfacade'':156B ''passed'':129B ''post'':115B ''pytest'':127B ''quant.balance'':142B ''report'':145B ''result'':76B ''run'':117B ''s'':84B ''scheduler_tasks.last'':160B ''sheets'':143B ''status'':161B ''stdlib'':108B ''structlog'':28B,101B ''success'':163B ''symbol'':22B,30B,64B,77B ''system'':56B ''tests/test_financial_timeliness_alert.py'':104B ''true'':91B ''typeerror'':42B,69B ''undefinedcolumn'':58B ''unexpected'':19B ''w'':5A,13B ''w-32314d00'':4A,12B ''且被同函数'':43B ''且该告警目前只写日志未投递'':154B ''为运行期惰性'':131B ''仅此'':95B ''仍记'':162B ''任务成功但功能失败'':164B ''修复'':82B ''修复前日志第'':124B ''修异常取值前必须先证伪'':165B ''假阳性'':102B ''全仓'':92B ''加'':88B ''历史链条'':53B ''发送时效性告警失败'':7A,15B ''只把失败点从取值挪到调用本身'':80B ''只留症状级'':47B ''各一次'':52B ''吞掉'':45B ''含'':107B ''告警本该'':150B ''告警正文从未落日志'':46B ''告警正文确保落日志'':86B ''处是'':100B ''处真阳性'':97B ''处置'':3A,11B ''天'':137B ''建议接'':155B ''异常被业务层吞掉时'':159B ''必抛'':41B ''惰性格式化'':85B ''打地鼠'':71B ''扫描同类缺陷'':94B ''把'':74B ''改成'':78B ''改标准库合法'':83B ''故无需重启'':133B ''教训'':158B ''新增'':103B ''新增错误串'':121B ''日志出现完整告警正文'':120B ''最新'':144B ''本事件'':70B ''条'':60B,106B ''标准库'':34B ''标准库只认'':38B ''根因'':23B ''次'':123B ''没验证调用是否合法'':81B ''用'':27B ''的'':36B ''的静态护栏'':112B ''禁非法'':110B ''类型不匹配'':25B ''线上'':114B ''行'':126B ''调用'':33B ''调用本身合法'':166B ''财报数据实际超期'':135B ''送达却因链路坏了无人看见'':153B ''错误事件'':1A,9B ''附带发现'':134B ''需人工确认'':157B ''预期报告期'':138B ''风格'':29B ''验证'':113B', '2026-09-13 11:25:33.017097', '2026-09-13 11:25:33.017097', '{}');
