INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('c420ff58-4f30-42c2-9d15-51ce01d0b9e6', '【假成功治理 · 2026-09-13 w-32314d00】『跑成功但功能失败』的根因：三个执行入', '【假成功治理 · 2026-09-13 w-32314d00】『跑成功但功能失败』的根因：三个执行入口里只有两个做了结果契约校验——job_executor（APScheduler 定时，2026-09-10 修）与 scheduler_webhook 共用 classify_job_result；scheduler.py::run_task（手动触发）与 daily_jobs_bootstrap::_run_job（进程内宿主）只看有没有抛异常。审计实证：inprocess_job_runs 近 30 天 6 条 success 的结果带失败标记（evening_pipeline 09-03/04/07/08/09 五天 kline_sync SQL 报错、financial_statements 09-05 success=false）+ 1 条 running 卡 12h；scheduler_runs 近 14 天 7 条（task 323/301 regime_daily 属性错、258 list_pools、232 datetime 未定义）。修复：新增 find_result_failure（classify 的嵌套下钻版：最多 2 层、只下钻含 success/status 的 dict、skipped=True 不算失败）作为口径唯一来源，接入 run_task 与 _run_job；新增 _reap_orphan_runs 在宿主启动时把 running>5min 的行判死（孤儿 running 原本永久隐形：is_due 只查当天、failure_watch 只看 failed）；财报时效性告警未送达改为 raise AlertDeliveryError。验证：pytest 39 passed（含 15 条新护栏）+ 调度相关子集 239 passed；线上 kickstart 重启后日志 inprocess_job_orphans_reaped count=1，卡 12h 的 financial_statements 09-12 行被收尾为 failed 并生成错误事件 c0e69791。教训：『无异常即成功』是假成功工厂；多执行入口必须共用同一失败判定口径且要能下钻嵌套；状态机必须给 running 配超时收尾，否则失败会以『永远 running』形式隐形。', 'knowledge', '{false-success,scheduler,result-contract,orphan-running,w-32314d00}', NULL, '''-03'':62B ''-05'':72B ''-09'':3A,13B,26B ''-10'':27B ''-12'':168B ''-13'':4A,14B ''/04/07/08/09'':63B ''09'':61B,71B,167B ''1'':75B,161B ''12h'':79B,163B ''14'':83B ''15'':148B ''2'':106B ''2026'':2A,12B,25B ''232'':95B ''239'':151B ''258'':92B ''30'':53B ''323/301'':88B ''32314d00'':7A,17B ''39'':145B ''5min'':128B ''6'':55B ''7'':85B ''alertdeliveryerror'':142B ''apscheduler'':23B ''bootstrap'':43B ''c0e69791'':172B ''classify'':33B,103B ''count'':160B ''daily'':41B,90B ''datetime'':96B ''dict'':111B ''due'':134B ''evening'':59B ''executor'':22B ''failed'':139B,170B ''failure'':102B,136B ''false'':74B ''financial'':69B,165B ''find'':100B ''inprocess'':49B,156