INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('f12e40f8-1220-42fe-b1c5-7de811ec8aff', 'SYSTEM loss 回测工程的静默失真（pandas dtype）', 'SYSTEM 交易经验（2026-09-13T04:53:46.303Z）
场景：回测工程的静默失真（pandas dtype）
结果：loss
教训：pandas 读 CSV 时把股票代码 "000858" 推断为整数 858（丢前导零）→ 目标标的（str）与价格矩阵列名（int）不匹配 → 每一笔买入都被 `if s in open_.columns else nan` 静默跳过 → 回测显示"零交易、净值恒为 1"，看起来像"策略不交易"而非 bug。凡是"回测没成交/没信号"的现象，先查**代码/列名的类型与格式一致性**（dtype={"symbol": str} + zfill(6)），再怀疑策略逻辑。', 'experience', '{SYSTEM,loss}', NULL, '''-09'':9B ''-13'':10B ''000858'':26B ''1'':47B ''2026'':8B ''46.303'':13B ''53'':12B ''6'':63B ''858'':28B ''bug'':51B ''columns'':40B ''csv'':24B ''dtype'':5A,18B,59B ''else'':41B ''if'':36B ''in'':38B ''int'':33B ''loss'':2A,20B ''nan'':42B ''open'':39B ''pandas'':4A,17B,22B ''s'':37B ''str'':31B,61B ''symbol'':60B ''system'':1A,6B ''t04'':11B ''z'':14B ''zfill'':62B ''不匹配'':34B ''与价格矩阵列名'':32B ''丢前导零'':29B ''交易经验'':7B ''代码'':57B ''先查'':56B ''再怀疑策略逻辑'':64B ''净值恒为'':46B ''凡是'':52B ''列名的类型与格式一致性'':58B ''回测工程的静默失真'':3A,16B ''回测显示'':44B ''回测没成交'':53B ''场景'':15B ''推断为整数'':27B ''教训'':21B ''时把股票代码'':25B ''每一笔买入都被'':35B ''没信号'':54B ''的现象'':55B ''目标标的'':30B ''看起来像'':48B ''策略不交易'':49B ''结果'':19B ''而非'':50B ''读'':23B ''零交易'':45B ''静默跳过'':43B', '2026-09-13 12:53:46.303919', '2026-09-13 12:53:46.303919', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('7efe5c4f-c8e2-4f6b-a7e2-f6cd786dac3a', 'SYSTEM loss 策略 vs 同池等权基准的超额（今日全部候选）', 'SYSTEM 交易经验（2026-09-13T05:09:23.288Z）
场景：策略 vs 同池等权基准的超额（今日全部候选）
结果：loss
教训：补上"相对同池等权买入持有"的超额维度后，今天测过的所有**选择型**叠层超额全为负（全窗口）：动量 mom60 -13.4pp、短线反转 ret5 -4.8pp、盈利收益率高 -21.9pp、ROE 高 -33.1pp。而基准本身不弱：诚实池 291 只等权 +7.6%/年（Sharpe 0.40）、基本面池 377 只等权 **+16.9%/年（Sharpe 0.79，DD -32%）**。结论：**在这一窗口，alpha 来自"广度+等权持有"而非择时/选股信号**——选择型叠层多数在减分。下一步应把"等权持有流动性宽基"当作要被超越的基线（core），再寻找**风控型叠层**（波动目标、回撤控制、分批建仓）而不是继续做选择型叠层。样本仅 4.3 年且逢大熊后反弹，不可外推（R-016）。', 'experience', '{SYSTEM,loss}', NULL, '''+16.9'':57B ''+7.6'':50B ''-016'':87B ''-09'':10B ''-13'':11B ''-13.4'':33B ''-21.9'':40B ''-32'':62B ''-33.1'':44B ''-4.8'':37B ''0.40'':53B ''0.79'':60B ''09'':13B ''2026'':9B ''23.288'':14B ''291'':48B ''377'':55B ''4.3'':83B ''alpha'':65B ''core'':75B ''dd'':61B ''loss'':2A,22B ''mom60'':32B ''pp'':34B,38B,41B,45B ''r'':86B ''ret5'':36B ''roe'':42B ''sharpe'':52B,59B ''system'':1A,7B ''t05'':12B ''vs'':4A,18B ''z'':15B ''下一步应把'':72B ''不可外推'':85B ''交易经验'':8B ''今天测过的所有'':27B ''今日全部候选'':6A,20B ''全窗口'':30B ''再寻找'':76B ''分批建仓'':80B ''动量'':31B ''叠层超额全为负'':29B ''只等权'':49B,56B ''同池等权基准的超额'':5A,19B ''回撤控制'':79B ''在这一窗口'':64B ''场景'':16B ''基本面池'':54B ''年'':51B,58B ''年且逢大熊后反弹'':84B ''广度'':67B ''当作要被超越的基线'':74B ''教训'':23B ''来自'':66B ''样本仅'':82B ''波动目标'':78B ''的超额维度后'':26B ''盈利收益率高'':39B ''相对同池等权买入持有'':25B ''短线反转'':35B ''等权持有'':68B ''等权持有流动性宽基'':73B ''策略'':3A,17B ''结果'':21B ''结论'':63B ''而不是继续做选择型叠层'':81B ''而基准本身不弱'':46B ''而非择时'':69B ''补上'':24B ''诚实池'':47B ''选择型'':28B ''选择型叠层多数在减分'':71B ''选股信号'':70B ''风控型叠层'':77B ''高'':43B', '2026-09-13 13:09:23.29032', '2026-09-13 13:09:23.29032', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('1b8e6b8d-4651-455c-91df-3f402b948d66', '【事件 d9adc934 处置 · 2026-09-13 w-32314d00】财报抓取失败（All', '【事件 d9adc934 处置 · 2026-09-13 w-32314d00】财报抓取失败（All providers failed）263 次。读数纠正：日志里 263 条 "XXX: 财报抓取失败" 实际覆盖 **186 只不同标的**（003021 只失败 1 次）——采集器按数字归一化指纹聚合、msg 取首行，卡片易被误读成"某只票连败 263 次"。根因=环境（2026-09-12 20:03~09-13 00:28 财报源链 sina_web/eastmoney/akshare-financial 整体不可用）+ 代码缺口（job 无探活门控、对全宇宙 367 只逐只硬试 → 无效请求 + 263 条噪声日志，还可能加重源侧 WAF）。动作=①补探活门控 _probe_financial_sources（参考标的 600519/000001，全失败即快速失败 probe_failed=true，对齐 kline 任务 2026-09-02 的 _probe_kline_sources 教训）；②逐只失败日志改一条聚合汇总（数量+样例+首个原因）。证据=①源已自愈：003021/600519/000001/688322/000983 全部 OK；②健康路径不受影响：--symbols 003021 600519 →success=True updated=2 rows=135；③tests/test_financial_probe_gate.py 4 passed。通用教训=「源整体不可用」必须与「单标的异常」区分：前者要探活门控快速失败，否则 N 次无效请求既无收获又会被采集器聚成巨型噪声事件；日志应聚合、错误事件才不会淹没真信号。', 'knowledge', '{error-event,d9adc934,financial-statements,probe-gate,log-noise,w-32314d00}', NULL, '''-02'':88B ''-09'':5A,16B,50B,87B ''-12'':51B ''-13'':6A,17B ''00'':55B ''003021'':36B,105B ''003021/600519/000001/688322/000983'':100B ''03'':53B ''1'':38B ''135'':112B ''186'':34B ''2'':110B ''20'':52B ''2026'':4A,15B,49B,86B ''263'':25B,29B,45B,68B ''28'':56B ''32314d00'':9A,20B ''367'':65B ''4'':114B ''600519'':106B ''600519/000001'':78B ''all'':11A,22B ''d9adc934'':2A,13B ''failed'':24B,81B ''financial'':75B ''job'':62B ''kline'':84B,91B ''msg'':41B ''n'':123B ''ok'':102B ''passed'':115B ''probe'':74B,80B,90B ''providers'':23B ''rows'':111B ''sina'':58B ''sources'':76B,92B ''success'':107B ''symbols'':104B ''tests/test_financial_probe_gate.py'':113B ''true'':82B,108B ''updated'':109B ''w'':8A,19B ''w-32314d00'':7A,18B ''waf'':71B ''web/eastmoney/akshare-financial'':59B ''xxx'':31B ''~09-13'':54B ''事件'':1A,12B ''代码缺口'':61B ''任务'':85B ''健康路径不受影响'':103B ''全失败即快速失败'':79B ''全部'':101B ''前者要探活门控快速失败'':121B ''动作'':72B ''区分''