INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('b28c363c-ed19-4dc5-8254-fcc97ee42f72', '2026-09-13（w-a9ec14d7）"智能执行看板能不能看见我建的任务"核查结论：
**看得', '2026-09-13（w-a9ec14d7）"智能执行看板能不能看见我建的任务"核查结论：
**看得见**——dashboard-execution 的 /dashboard/api/board 合并两个源：v2 /api/scheduler/tasks（35 条，v2 内部 job，无 agent_line 字段）
与 Agent OS /api/v1/scheduler/tasks（31 条，行存 public.tasks，有 agent_line）。看板返回 59 个任务，今日新增的四个改动全在内。

两个可观测性要点（写下来避免以后再踩）：
① **新建 Agent OS 任务必须打 agent_line**（profit_engine/autonomy/account/other）：看板按它分业务线，
   调度看门狗会把未打标的列为"待补标"；我这次建 strategy-loop-weekly 时漏了，30 个启用任务里唯一未打标，已补 profit_engine。
② **"在任务列表可见" ≠ "在今日时间轴出现"**：时间轴由当天的运行/排期构成，周度任务（周日 20:30 / 周一 06:00）
   在跑之前不会出现在今日时间轴，这不是故障。
③ v2 内部 job（quant.scheduler_tasks）与 Agent OS 任务（public.tasks）是**两个存储**，看板分别展示；
   看板还会过滤"指向 v2 webhook(:5001) 的任务"以防双计——所以同一件事不要两边都建。', 'knowledge', '{智能执行看板,agent_line,任务可观测性,2026-09-13}', NULL, '''-09'':2A,11B ''-13'':3A,12B ''/api/scheduler/tasks'':26B ''/api/v1/scheduler/tasks'':39B ''/dashboard/api/board'':23B ''00'':85B ''06'':84B ''20'':81B ''2026'':1A,10B ''30'':70B,82B ''31'':40B ''35'':27B ''5001'':105B ''59'':48B ''a9ec14d7'':6A,15B ''agent'':33B,37B,45B,54B,57B,94B ''dashboard'':20B ''dashboard-execution'':19B ''engine'':74B ''engine/autonomy/account/other'':60B ''execution'':21B ''job'':31B,90B ''line'':34B,46B,58B ''loop'':67B ''os'':38B,55B,95B ''profit'':59B,73B ''public.tasks'':43B,97B ''quant.scheduler'':91B ''strategy'':66B ''strategy-loop-weekly'':65B ''tasks'':92B ''v2'':25B,29B,88B,103B ''w'':5A,14B ''w-a9ec14d7'':4A,13B ''webhook'':104B ''weekly'':68B ''与'':36B,93B ''两个可观测性要点'':51B ''两个存储'':99B ''个任务'':49B ''个启用任务里唯一未打标'':71B ''今日新增的四个改动全在内'':50B ''以防双计'':107B ''任务'':96B ''任务必须打'':56B ''内部'':30B,89B ''写下来避免以后再踩'':52B ''合并两个源'':24B ''周一'':83B ''周度任务'':79B ''周日'':80B ''在今日时间轴出现'':76B ''在任务列表可见'':75B ''在跑之前不会出现在今日时间轴'':86B ''字段'':35B ''已补'':72B ''待补标'':63B ''我这次建'':64B ''所以同一件事不要两边都建'':108B ''指向'':102B ''排期构成'':78B ''新建'':53B ''无'':32B ''时漏了'':69B ''时间轴由当天的运行'':77B ''是'':98B ''智能执行看板能不能看见我建的任务'':7A,16B ''有'':44B ''条'':28B,41B ''核查结论'':8A,17B ''的'':22B ''的任务'':106B ''看得'':9A ''看得见'':18B ''看板分别展示'':100B ''看板按它分业务线'':61B ''看板返回'':47B ''看板还会过滤'':101B ''行存'':42B ''调度看门狗会把未打标的列为'':62B ''这不是故障'':87B', '2026-09-13 16:43:41.041615', '2026-09-13 16:43:41.041615', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('a1067a97-25cd-43ae-a5eb-cf088402f7a2', '2026-09-13 项目看板（reqboard）补齐三个「看起来有其实没有」的缺口（窗口 w-1c', '2026-09-13 项目看板（reqboard）补齐三个「看起来有其实没有」的缺口（窗口 w-1cee2467）：①状态事件时间线——此前需求/任务只有 createdAt/updatedAt，「评审/拆分/实施/验收/归档各在何时、每段停留多久」台账里不存在；现新增 StatusEvent{status,at,by,reason,inferred} + statusHistory（schemaVersion 3），全部转移点写入，老记录加载时由 createdAt+评论留痕反推回填并标 inferred（UI 显「回填」）。②真拆分 reqboard_decompose——此前 decomposing 只是状态名，实测台账 tasks 恒 0 条、无任何把需求变任务的代码路径；现一次调用落库整批任务 DAG（批次 key→真实 id、无环/悬空校验，失败整笔回滚），rollup 自动推进 reviewing→decomposing→implementing→accepting。③任务页+甘特图——新增跨需求任务总览页（分组里程碑条+甘特图+任务清单）与详情页甘特图（按状态分段着色、叠里程碑竖线、耗时来自 executions 真实记录）。配套 reqboard_task_move + 任务闸门与需求同口径（仅取消/复活留给人）：原 in_review>done 仅人可点→任务卡停验收→需求进不了验收=看板再次静止。验证：153 单测通过/12 文件；真实台账渲染实跑（15 卡、REQ-b02e99 时间线 7 行、甘特空态指引）。生效：client 刷新即可，host 半需重启 13080。', 'knowledge', '{reqboard,dsh-pmboard,RFC014,时间线,甘特图,w-1cee2467}', NULL, '''-09'':2A,14B ''-13'':3A,15B ''/12'':111B ''0'':63B ''13080'':128B ''15'':114B ''153'':109B ''1c'':12A ''1cee2467'':24B ''2026'':1A,13B ''3'':45B ''7'':120B ''accepting'':80B ''at'':39B ''b02e99'':118B ''by'':40B ''client'':124B ''createdat'':48B ''createdat/updatedat'':28B ''dag'':67B ''decompose'':56B ''decomposing'':58B,78B ''done'':103B ''executions'':91B ''host'':126B ''id'':71B ''implementing'':79B ''in'':101B ''inferred'':42B,50B ''key'':69B ''move'':96B ''reason'':41B ''req'':117B ''req-b02e99'':116B ''reqboard'':5A,17B,55B,94B ''review'':102B ''reviewing'':77B ''rollup'':75B ''schemaversion'':44B ''status'':38B ''statusevent'':37B ''statushistory'':43B ''task'':95B ''tasks'':61B ''ui'':51B ''w'':11A,23B ''w-1c'':10A ''w-1cee2467'':22B ''与详情页甘特图'':87B ''仅人可点'':104B ''仅取消'':98B ''任务卡停验收'':105B ''任务只有'':27B ''任务清单'':86B ''任务闸门与需求同口径'':97B ''任务页'':81B ''全部转移点写入'':46B ''分组里程碑条'':84B ''刷新即可'':125B ''半需重启'':127B ''单测通过'':110B ''卡'':115B ''原'':100B ''叠里程碑竖线'':89B ''只是状态名''