INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('09467b27-0a44-4018-91a5-35302d5e0df6', '2026-09-13 项目看板计划模式（plan mode）落地（窗口 w-1cee2467，用户要', '2026-09-13 项目看板计划模式（plan mode）落地（窗口 w-1cee2467，用户要求「superpowers 的 plan 模式版本」）：闸门从"每个中间状态都要人点"改为"只在计划上闸一次"。①PlanRecord 挂需求：path（工作区计划文档 docs/requirements/REQ-xxx/plan.md）+ summary（人读这段决定批不批）+ tasks 任务表（key/title/phase/side/depends_on/acceptance）；②新工具 reqboard_plan_submit 提交计划 → 泳道卡面「计划待批」；③人工裁决路由 POST /req/plan/approve | /req/plan/reject（退回必须给理由）+ 看板计划卡按钮；④HARD GATE 代码级：未批准时 reqboard_decompose 直接拒绝 REQBOARD_PLAN_NOT_APPROVED；⑤批了 A 不能落库 B：落库内容以批准计划为准，key 不一致 → REQBOARD_PLAN_MISMATCH；⑥重新提交作废旧批准。粒度写在计划里 = 人批的是拆分方案本身，decompose 只是落库。skill：agent-dh/skills/reqboard-plan/SKILL.md（三类路径 Spike/Bounded/Architectural + HARD GATE + 计划文档结构 + 任务 right-sizing + bite-sized TDD + 执行纪律 + 停止条件 + 反模式）。验证：167 单测/13 文件，批准走真 HTTP 全链路。生效：client 刷新，host 需重启 13080；skill 已可在会话内直接加载（实测 provider=filesystem）。', 'knowledge', '{reqboard,plan-mode,superpowers,dsh-pmboard,w-1cee2467}', NULL, '''-09'':2A,14B ''-13'':3A,15B ''/13'':106B ''/req/plan/approve'':52B ''/req/plan/reject'':53B ''/skills/reqboard-plan/skill.md'':86B ''13080'':116B ''167'':104B ''1cee2467'':11A,23B ''2026'':1A,13B ''a'':68B ''agent'':84B ''agent-dh'':83B ''approved'':66B ''b'':70B ''bite'':97B ''bite-sized'':96B ''client'':112B ''decompose'':61B,80B ''dh'':85B ''docs/requirements/req-xxx/plan.md'':37B ''filesystem'':121B ''gate'':57B,90B ''hard'':56B,89B ''host'':114B ''http'':109B ''key'':72B ''key/title/phase/side/depends_on/acceptance'':42B ''mismatch'':76B ''mode'':6A,18B ''not'':65B ''path'':35B ''plan'':5A,17B,27B,45B,64B,75B ''planrecord'':33B ''post'':51B ''provider'':120B ''reqboard'':44B,60B,63B,74B ''right'':94B ''right-sizing'':93B ''sized'':98B ''sizing'':95B ''skill'':82B,117B ''spike/bounded/architectural'':88B ''submit'':46B ''summary'':38B ''superpowers'':25B ''tasks'':40B ''tdd'':99B ''w''