INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('6098338a-60c6-4fbc-be87-da763f0bdadc', '【工程教训·外键删除动作缺失会让「删聚合」变成 500】2026-09-13 事件 fc47fb7d', '【工程教训·外键删除动作缺失会让「删聚合」变成 500】2026-09-13 事件 fc47fb7d：DELETE /api/pools/54 → 500，结构日志真实异常是 pool_change_log_pool_id_fkey 外键挡住删除（当时该外键无 ON DELETE 动作），路由落通用 except → 500 并被采集为 error 事件（4 次是同一 trace 2 秒内重试，不是 4 个独立故障）。两条通用纪律：①**修一个外键不够，必须扫全同类**——审计「引用 quant.stock_pools 的全部外键」时发现另两个（pool_health_history / pool_game_metrics）仍是 NO ACTION，一旦有行就会再次 500；按 R-020 分类处置：审计类 → ON DELETE SET NULL（配冗余身份字段 pool_name 保住可读性），派生时间序列 → ON DELETE CASCADE（孤儿行无法归属）。②**失败面要收窄**：路由应对 IntegrityError 显式返回 409 + 约束名与指引，而不是落通用 except 的 500——500 会被错误事件系统当成服务故障，掩盖「数据依赖」这一可执行信息。验证方式：临时池 + 三张依赖表各写 1 行 → DELETE 应 200 且派生行随池清除、审计行存活置空；并用单测钉住 409/404 分支。', 'experience', '{错误事件,fc47fb7d,外键,R-020,数据卫生,pools,w-a72695c7}', NULL, '''-020'':72B ''-09'':7A,17B ''-13'':8A,18B ''/api/pools/54'':22B ''1'':106B ''2'':45B ''200'':110B ''2026'':6A,16B ''4'':42B,48B ''409'':92B ''409/404'':114B ''500'':5A,15B,23B,38B,69B,97B,98B ''action'':67B ''cascade'':86B ''change'':26B ''delete'':21B,34B,76B,85B,108B ''error'':40B ''except'':37B,95B ''fc47fb7d'':10A,20B ''fkey'':30B ''game'':63B ''health'':60B ''history'':61B ''id'':29B ''integrityerror'':90B ''log'':27B ''metrics'':64B ''name'':81B ''no'':66B ''null'':78B ''on'':33B,75B,84B ''pool'':25B,28B,59B,62B,80B ''pools'':56B ''quant.stock'':55B ''r'':71B ''set'':77B ''trace'':44B ''一旦有行就会再次'':68B ''三张依赖表各写'':105B ''不是'':47B ''且派生行随池清除'':111B ''两条通用纪律'':50B ''个独立故障'':49B ''临时池'':104B ''事件'':9A,19B,41B ''仍是'':65B ''会被错误事件系统当成服务故障'':99B ''保住可读性'':82B ''修一个外键不够'':51B ''分支'':115B ''分类处置'':73B ''删聚合'':3A,13B ''动作'':35B ''变成'':4A,14B ''外键删除动作缺失会让'':2A,12B ''外键挡住删除'':31B ''失败面要收窄'':88B ''孤儿行无法归属'':87B ''审计'':53B ''审计类'':74B ''审计行存活置空'':112B ''工程教训'':1A,11B ''并用单测钉住'':113B ''并被采集为'':39B ''应'':109B ''引用'':54B ''当时该外键无'':32B ''必须扫全同类'':52B ''按'':70B ''掩盖'':100B ''数据依赖'':101B ''时发现另两个'':58B ''显式返回'':91B ''次是同一'':43B ''派生时间序列'':83B ''的'':96B ''的全部外键'':57B ''秒内重试'':46B ''约束名与指引'':93B ''结构日志真实异常是'':24B ''而不是落通用'':94B ''行'':107B ''路由应对'':89B ''路由落通用'':36B ''这一可执行信息'':102B ''配冗余身份字段'':79B ''验证方式'':103B', '2026-09-13 18:54:42.994769', '2026-09-13 18:54:42.994769', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('17767cf0-f493-4444-8774-a437e6937e54', '双线执行看板「未归类 11 个」根因（2026-09-13 18:56 实测，w-a1402b8c ', '双线执行看板「未归类 11 个」根因（2026-09-13 18:56 实测，w-a1402b8c / REQ-eeb38c）：11 个未归类任务全部来自 quantsys-v2 引擎侧（GET :5001/api/scheduler/tasks，40 个任务，agentLine 字段不存在）。agent-dh 侧分类唯一实现 = packages/pages/execution/src/shared/line-classify.ts，优先级「字段→名单→other+unclassified」；OS 侧 25 个任务都带 agent_line（fieldTagged=25），v2 侧恒不命中字段，只能靠硬编码任务名名单兜底，名单漏收即落 other 并触发告警。名单里 equity_snapshot_daily 只收了连字符版 equity-snapshot-daily（同一功能两个调度器各一行）。归类口径：能对上 OS 孪生任务的以孪生 agent_line 为准（equity_snapshot_daily→engine、strategy_loop_weekly→engine、data_hygiene_probe→autonomy），数据地基类（事件入库/披露日历/分钟线/产业链）归 engine，session-probe（OS 托管探针，disabled）归已知其它。计划落 docs/requirements/REQ-eeb38c/plan.md。另发现 v2 与 OS 存在同功能双行（equity/strategy_loop/data_hygiene，v2 侧均 enabled、时刻差 15 分钟），疑似重复调度，未在本需求内处理。', 'knowledge', '{看板,line-classify,未归类,REQ-eeb38c,调度}', NULL, '''-09'':7A,21B ''-13'':8A,22B ''11'':3A,17B,32B ''15'':123B ''18'':9A,23B ''2026'':6A,20B ''25'':56B,61B ''40'':40B ''5001/api/scheduler/tasks'':39B ''56'':10A,24B ''a1402b8c'':14A,28B ''agent'':45B,58B,82B ''agent-dh'':44B ''agentline'':42B ''autonomy'':96B ''daily'':71B,76B,87B ''data'':93B ''dh'':46B ''disabled'':109B ''docs/requirements/req-eeb38c/plan.md'':112B ''eeb38c'':31B ''enabled'':121B ''engine'':88B,92B,103B ''equity'':69B,74B,85B ''equity-snapshot-daily'':73B ''equity/strategy_loop/data_hygiene'':118B ''fieldtagged'':60B ''get'':38B ''hygiene'':94B ''line'':59B,83B ''loop'':90B ''os'':54B,80B,107B,116B ''other'':52B,66B ''packages/pages/execution/src/shared/line-classify.ts'':48B ''probe'':95B,106B ''quantsys'':35B ''quantsys-v2'':34B ''req'':30B ''req-eeb38c'':29B ''session'':105B ''session-probe'':104B ''snapshot'':70B,75B,86B ''strategy'':89B ''unclassified'':53B ''v2'':36B,62B,114B,119B ''w'':13A,27B ''w-a1402b8c'':12A,26B ''weekly'':91B ''与'':11