INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('4e54f8bd-0eb9-4245-88f4-c502d0c8575b', 'B8 完成（2026-09-13 w-a9ec14d7）：core 建仓计划加 DSH 工具入口。三', 'B8 完成（2026-09-13 w-a9ec14d7）：core 建仓计划加 DSH 工具入口。三条可复用教训：①【产物要自描述，别让消费方反推】——core_plan.json 原先只有 generated_at（生成时刻）没有 data_date（行情时点），周末重跑或行情未同步时生成时刻是新的、行情却是旧的，只看生成时刻发现不了；core 持仓也只在打印时算一遍手数就丢，导致消费方要求的「与当前持仓的差额」根本无从算起。②【同一份数据不能有两套 key 词汇表】——/api/core-plan 刻意不用 api_response()（它会递归驼峰化），否则计划自身的 generated_at/weight_pct_of_core 在文件里是蛇形、在接口里是驼峰，读文件的任务与走接口的调用方看到的结构不一致；这与 self_finalize/boot-recovery 的「同一状态两种定义」是同一类事故面。③【读不到要分情形给原因】——计划缺失/无法解析/账户不匹配都返回 available=false + unavailable_reason 且按成功返回，包装成工具错误只会让模型看到「调用失败」而丢掉原因。另：源码绿灯 != dist 可用，本次新增 tests/plugin-dist.smoke.test.ts 按包声明的 main 构造插件（与 DSH 加载路径一致）覆盖 15 个 dist-main 包，补上这一层。', 'experience', '{B8,core_plan,DSH工具,dist冒烟,自描述产物,w-a9ec14d7}', NULL, '''-09'':4A,17B ''-13'':5A,18B ''/api/core-plan'':49B ''15'':91B ''2026'':3A,16B ''a9ec14d7'':8A,21B ''api'':51B ''at'':32B ''at/weight_pct_of_core'':56B ''available'':70B ''b8'':1A,14B ''core'':9A,22B,41B ''core_plan.json'':29B ''data'':35B ''date'':36B ''dist'':80B,94B ''dist-main'':93B ''dsh'':11A,24B,88B ''false'':71B ''finalize/boot-recovery'':62B ''generated'':31B,55B ''key'':47B ''main'':85B,95B ''reason'':73B ''response'':52B ''self'':61B ''tests/plugin-dist.smoke.test.ts'':83B ''unavailable'':72B ''w'':7A,20B ''w-a9ec14d7'':6A,19B ''三'':13A ''三条可复用教训'':26B ''与'':87B ''与当前持仓的差额'':44B ''且按成功返回'':74B ''个'':92B ''产物要自描述'':27B ''别让消费方反推'':28B ''刻意不用'':50B ''加载路径一致'':89B ''包'':96B ''包装成工具错误只会让模型看到'':75B ''原先只有'':30B ''另'':78B ''只看生成时刻发现不了'':40B ''可用'':81B ''同一份数据不能有两套'':46B ''同一状态两种定义'':64B ''否则计划自身的'':54B ''周末重跑或行情未同步时生成时刻是新的'':38B ''在接口里是驼峰'':58B ''在文件里是蛇形'':57B ''它会递归驼峰化'':53B ''完成'':2A,15B ''导致消费方要求的'':43B ''工具入口'':12A,25B ''建仓计划加'':10A,23B ''持仓也只在打印时算一遍手数就丢'':42B ''按包声明的'':84B ''无法解析'':68B ''是同一类事故面'':65B ''本次新增'':82B ''构造插件'':86B ''根本无从算起'':45B ''没有''