INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('ad7972f1-3d82-46e5-9fab-f61259ca9a2c', '【待办·B8 未闭环项】core_plan DSH 工具已构建进 dist 但**尚未在运行实例生效', '【待办·B8 未闭环项】core_plan DSH 工具已构建进 dist 但**尚未在运行实例生效**（DSH 进程仍持有旧模块，需一次重启）。用户 2026-09-13 裁定：等 agent-dh/docs/requirements/REQ-24e15d/ 由所属窗口提交后再重启——因为 lifecycle 检查点会 git add -A -- agent-dh/ 并提交到 wip 分支，会把他人未提交产物卷进来（rollback 路径的 reset --hard 还可能把它从工作区删掉）。重启后须做：调 core_plan 工具确认出现在工具列表且返回 agent_brain 的计划+新鲜度+差额。判断"REQ-24e15d 是否已提交"：git status --porcelain -- agent-dh/docs 为空即可。', 'knowledge', '{B8,待重启,core_plan,REQ-24e15d,w-a9ec14d7}', NULL, '''-09'':26B ''-13'':27B ''/docs'':74B ''/docs/requirements/req-24e15d'':33B ''2026'':25B ''24e15d'':66B ''a'':40B ''add'':39B ''agent'':31B,42B,58B,72B ''agent-dh'':30B,41B,71B ''b8'':2A,12B ''brain'':59B ''core'':4A,14B,55B ''dh'':32B,43B,73B ''dist'':8A,18B ''dsh'':6A,16B,21B ''git'':38B,68B ''hard'':51B ''lifecycle'':36B ''plan'':5A,15B,56B ''porcelain'':70B ''req'':65B ''req-24e15d'':64B ''reset'':50B ''rollback'':48B ''status'':69B ''wip'':45B ''为空即可'':75B ''会把他人未提交产物卷进来'':47B ''但'':9A,19B ''分支'':46B ''判断'':63B ''因为'':35B ''尚未在运行实例生效'':10A,20B ''工具已构建进'':7A,17B ''工具确认出现在工具列表且返回'':57B ''差额'':62B ''并提交到'':44B ''待办'':1A,11B ''新鲜度'':61B ''是否已提交'':67B ''未闭环项'':3A,13B ''检查点会'':37B ''用户'':24B ''由所属窗口提交后再重启'':34B ''的计划'':60B ''等'':29B ''裁定'':28B ''调'':54B ''路径的'':49B ''还可能把它从工作区删掉'':52B ''进程仍持有旧模块'':22B ''重启后须做'':53B ''需一次重启'':23B', '2026-09-13 20:18:08.159958', '2026-09-13 20:18:08.159958', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('f20ce2b5-9ee4-4a65-a0d4-a27cadc92d4b', 'REQ-eeb38c 实施记录（2026-09-13，w-a1402b8c）：看板「未归类 11 个', 'REQ-eeb38c 实施记录（2026-09-13，w-a1402b8c）：看板「未归类 11 个」已修 —— agent-dh/packages/pages/execution/src/shared/line-classify.ts 补录 9 个 engine（ingest_events_daily/_policy/_history、ingest_disclosure_calendar、minute_kline_sync、industry_chain_refresh、equity_snapshot_daily、core_plan_generate、strategy_loop_weekly）+ 1 个 autonomy（data_hygiene_probe）+ 新增 OTHER_KEYS 收 session-probe（已知其它）。归类依据：与 OS 侧孪生任务 agent_line 对齐（equity-snapshot-daily=profit_engine / strategy-loop-weekly=profit_engine / data-hygiene-weekly=autonomy），无孪生者按 RFC 015 数据地基归 engine。验证：vitest line-classify.test.ts 15 passed（+3 新用例）；用 tsx 直接对线上任务清单（v2 40 + os 31）跑 computeTaskCoverage → unclassified=[]（修复前 11 个）；lib/client.* 重建并 grep 命中新名字；提交 8bede40a（仅含本次 4 个文件）。部署：host 半在 DSH 进程内加载，需重启 :13080（launchctl kickstart -k gui/uid/com.pi-investment.dsh）后看板才对账清零。数据来源与时点：GET :13080/dashboard/api/board 与 :5001/api/scheduler/tasks，2026-09-13 18:56-19:15。', 'knowledge', '{REQ-eeb38c,line-classify,看板,部署,w-a1402b8c}', NULL, '''+3'':107B ''-09'':6A,20B,149B ''-13'':7A,21B,150B ''-19'':153B ''/packages/pages/execution/src/shared/line-classify.ts'':33B ''015'':99B ''1'':59B ''11'':13A,27B,120B ''13080'':137B ''13080/dashboard/api/board'':145B ''15'':105B,154B ''18'':151B ''2026'':5A,19B,148B ''31'':115B ''4'':129B ''40'':113B ''5001/api/scheduler/tasks'':147B ''56'':152B ''8bede40a'':127B ''9'':35B ''a1402b8c'':10A,24B ''agent'':31B,77B ''agent-dh'':30B ''autonomy'':61B,96B ''calendar'':43B ''chain'':48B ''computetaskcoverage'':117B ''core'':53B ''daily'':52B,83B ''daily/_policy/_history'':40B ''data'':62B,93B ''data-hygiene-weekly'':92B ''dh'':32B ''disclosure'':42B ''dsh'':134B ''eeb38c'':3A,17B ''engine'':37B,85B,91B,101B ''equity'':50B,81B ''equity-snapshot-daily'':80B ''events'':39B ''generate'':55B ''get'':144