INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('c7664718-57a5-4c37-8ee7-60feb958983c', '2026-09-13（w-a9ec14d7）B 组技术债：B10 已完成（提交 7be7b025），', '2026-09-13（w-a9ec14d7）B 组技术债：B10 已完成（提交 7be7b025），B7/B8/B9 未做。

【B10 数据契约登记面 + 登记面自检】
问题：R-020 要求"派生表须登记、悬空引用须可探测"，但**没人会去数库里有多少张表没登记** ——
实测 quant schema **136 张表而契约只登记 6 张**，治理面窄到探测形同摆设。
改动：①契约 6 → 23 张（补齐决策路径上的表：stocks/trading_calendar/index_daily/minute_klines/
income_statements/balance_sheets/factor_values/chip_metrics/chip_distribution_state/signals/
agent_decisions/watch_rules/watch_triggers/simulation_equity_snapshot/market_regime/scheduler_tasks/stock_pools），
每张声明 owner/kind/上游/TTL/删除策略/软引用检查；②新增 check_registry_coverage()，
把"登记面本身"（表总数/已登记/未登记/备份残留）纳入每周探测。

【真跑立刻抓到的真问题（探测器第一次有牙齿）】
· **[FAIL] quant.signals：18401/18401 行 strategy_id 指向已删策略** —— 悬空引用。
  这和我今天清理 89 个策略是同一类事故（strategy_stock_matching 800 行孤儿的同型）。
  处置方案已写进契约：保留 signal 行（信号是历史事实、被 signal_tracking 消费）、
  把悬空 strategy_id 置 NULL 并在 indicators 保留原 id 文本；**不物理删除**。
  标 ref_disposition_status=pending_user_confirmation —— 涉及 1.8 万行历史，需用户确认后执行。
· [登记面] quant 表 136 张 / 已登记 22 张 / 未登记 114 张；**备份或临时残留 27 张（4,306,603 行）**。
  4 百万行无人负责的备份表（bak_*/tmp_*/*_backup_*/*_suspect），应逐个判"留档 or 清掉"。

【方法论】治理面的"面"本身要能被度量：只登记 6/136 张时，探测的绿灯是假的（它只覆盖了 4%）。
把覆盖率当成一级指标摆出来，比事后补登记有效 —— 这与"数据悄悄变空"是同一类问题的两面：
一面是数据变空（覆盖率检查），一面是治理面变窄（登记率检查）。', 'knowledge', '{数据契约,R-020,悬空引用,登记面,B组技术债,2026-09-13}', NULL, '''-020'':32B ''-09'':2A,14B ''-13'':3A,15B ''/tmp_'':144B ''/ttl'':60B ''1.8'':120B ''114'':132B ''136'':41B,126B ''18401/18401'':78B ''2026'':1A,13B ''22'':129B ''23'':49B ''27'':135B ''306'':138B ''4'':137B,141B,160B ''6'':43B,48B ''6/136'':156B ''603'':139B ''7be7b025'':12A,24B ''800'':90B ''89'':85B ''a9ec14d7'':6A,18B ''agent'':55B ''b'':7A,19B ''b10'':9A,21B,27B ''b7/b8/b9'':25B ''backup'':145B ''bak'':143B ''check'':64B ''confirmation'':118B ''coverage'':66B ''decisions/watch_rules/watch_triggers/simulation_equity_snapshot/market_regime/scheduler_tasks/stock_pools'':56B ''disposition'':114B ''fail'':76B ''id'':81B,103B,109B ''income'':53B ''indicators'':107B ''matching'':89B ''null'':105B ''or'':149B ''owner/kind'':58B ''pending'':116B ''quant'':39B,124B ''quant.signals'':77B ''r'':31B ''ref'':113B ''registry'':65B ''schema'':40B ''signal'':94B,98B ''statements/balance_sheets/factor_values/chip_metrics/chip_distribution_state/signals'':54B ''status'':115B ''stock'':88B ''stocks/trading_calendar/index_daily/minute_klines'':52B ''strategy'':80B,87B,102B ''suspect'':146B ''tracking'':99B ''user'':117B ''w'':5A,17B ''w-a9ec14d7'':4A,16B ''一面是数据变空'':166B ''一面是治理面变窄'':168B ''万行历史'':121B ''上游'':59B ''不物理删除'':111B ''个策略是同一类事故'':86B ''但'':36B ''保留'':93B ''保留原'':108B ''信号是历史事实'':96B ''删除策略'':61B ''只登记'':155B ''处置方案已写进契约'':92B ''备份或临时残留'':134B ''备份残留'':72B ''契约'':47B ''它只覆盖了'':159B ''实测'':38B ''已完成'':10A,22B ''已登记'':70B,128B ''并在'':106B ''应逐个判'':147B ''张'':44B,50B,127B,130B,133B,136B ''张时'':157B ''张表而契约只登记'':42B ''悬空引用'':83B ''悬空引用须可探测'':35B ''把'':67B ''把悬空'':101B ''把覆盖率当成一级指标摆出来'':161B ''指向已删策略'':82B ''探测器第一次有牙齿'':75B ''探测的绿灯是假的'':158B ''提交'':11A,23B ''改动'':46B ''数据契约登记面'':28B ''数据悄悄变空'':164B ''文本'':110B ''新增'':63B ''方法论'':151B ''是同一类问题的两面'':165B ''未做'':26B ''未登记'':71B,131B ''本身要能被度量'':154B ''标'':112B ''每张声明'':57B ''比事后补登记有效'':162B ''没人会去数库里有多少张表没登记'':37B ''治理面的'':152B ''治理面窄到探测形同摆设'':45B ''派生表须登记'':34B ''消费'':100B ''涉及'':119B ''清掉'':150B ''留档'':148B ''登记率检查'':169B ''登记面'':123B ''登记面本身'':68B ''登记面自检'':29B ''百万行无人负责的备份表'':142B ''真跑立刻抓到的真问题'':74B ''纳入每周探测'':73B ''组技术债'':8A,20B ''置'':104B ''行'':79B,95B,140B ''行孤儿的同型'':91B ''补齐决策路径上的表'':51B ''表'':125B ''表总数'':69B ''被'':97B ''要求'':33B ''覆盖率检查'':167B ''软引用检查'':62B ''这与'':163B ''这和我今天清理'':84B ''问题'':30B ''需用户确认后执行'':122B ''面'':153B', '2026-09-13 19:14:03.805235', '2026-09-13 19:14:03.805235', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('b2107421-c3f2-452f-8be7-2afd61b535e5', 'B7 core_plan_service 去 subprocess psql 收口到 engine（', 'B7 core_plan_service 去 subprocess psql 收口到 engine（2026-09-13，w-a9ec14d7）：stdout 逐字节一致、JSON 除时间戳外仅 2 处末位差，且均已查证非移植引入。教训一：**等价性验证必须在同一条查询上比**——我一度以为移植改动了数值，实际是 px 聚合查询走 Parallel Seq Scan→Partial HashAggregate→Gather Merge，同一查询连跑 8 次出现 4 种不同末位组合，该值本来就不可重现；要比对"未变更基线"就先证明基线在你比的那个精度上是可重现的。教训二：**pandas read_csv 的浮点解析不是正确舍入**——psql 文本 1950778427.7948718 经 pd.read_csv 变 1950778427.794872（差 1 ULP），而 float(text)/engine 二进制精确；"psql 文本+read_csv"这条链会静默丢末位精度，别当无损通道。教训三：**重启前后同接口返回值可能不同**——/api/market/sectors 重启前 49 个行业且全负、重启后 496 个行业，疑似降级特征；A/B 比对时第三方实时接口字段的差异必须单独归因。教训四：验证"新代码已生效"必须重启进程（Python 模块已缓存），只触发任务会跑旧代码。', 'experience', '{B7,core_plan,engine,psql,等价性验证,并行聚合,pandas,w-a9ec14d7}', NULL, '''-09'':20B ''-13'':21B ''/api/market/sectors'':83B ''/engine'':73B ''1'':68B ''1950778427.7948718'':61B ''1950778427.794872'':66B ''2'':29B ''2026'':19B ''4'':48B ''49'':85B ''496'':88B ''8'':46B ''a/b'':91B ''a9ec14d7'':24B ''b7'':1A,10B ''core'':2A,11B ''csv'':57B,64B,78B ''engine'':9A,18B ''float'':71B ''gather'':43B ''hashaggregate'':42B ''json'':27B ''merge'':44B ''pandas'':55B ''parallel'':38B ''partial'':41B ''pd.read'':63B ''plan'':3A,12B ''psql'':7A,16B,59B,75B ''px'':36B ''python'':97B ''read'':56B,77B ''scan'':40B ''seq'':39B ''service'':4A,13B ''stdout'':25B ''subprocess'':6A,15B ''text'':72B ''ulp'':69B ''w'':23B ''w-a9ec14d7'':22B ''且均已查证非移植引入'':31B ''个行业'':89B ''个行业且全负'':86B ''二进制精确'':74B ''别当无损通道'':80B ''去'':5A,14B ''变'':65B ''只触发任务会跑旧代码'':99B ''同一查询连跑'':45B ''处末位差'':30B ''实际是'':35B ''就先证明基线在你比的那个精度上是可重现的'':53B ''差'':67B ''必须重启进程'':96B ''我一度以为移植改动了数值'':34B ''收口到'':8A,17B ''教训一'':32B ''教训三'':81B ''教训二'':54B ''教训四'':93B ''文本'':60B,76B ''新代码已生效'':95B ''未变更基线'':52B ''模块已缓存'':98B ''次出现'':47B ''比对时第三方实时接口字段的差异必须单独归因'':92B ''疑似降级特征'':90B ''的浮点解析不是正确舍入'':58B ''种不同末位组合'':49B ''等价性验证必须在同一条查询上比'':33B ''经'':62B ''而'':70B ''聚合查询走'':37B ''要比对'':51B ''该值本来就不可重现'':50B ''这条链会静默丢末位精度'':79B ''逐字节一致'':26B ''重启前'':84B ''重启前后同接口返回值可能不同'':82B ''重启后'':87B ''除时间戳外仅'':28B ''验证'':94B', '2026-09-13 19:29:05.552791', '2026-09-13 19:29:05.552791', '{}');
