INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('6bf6ae79-691d-4b75-886b-2808716de278', '2026-09-13 深夜 core_plan 加固交付（w-c8cae280）：①补 36+17 ', '2026-09-13 深夜 core_plan 加固交付（w-c8cae280）：①补 36+17 个单测，抓到并修复"静默少投"缺陷（apply_weight_cap 在 标的数×上限<100% 时静默丢弃权重，3 只×15% → 权重和仅 45%，会只投一半的钱且无报错；现改为显式报错 + 把持仓下限自动抬到 ceil(100/cap)）；②抽出模块级纯函数 apply_weight_cap/refill_core/enforce_core_constraints 使不变量可单测；③新增三段产物字段：risk_lens（年化波动/夏普/日VaR/CVaR/平均相关/有效注数/β/α，生成时算一次）、execution_plan（4 批分批名单，禁止把机械差额一次打满）、delta.limit_check（宪法第3条静态复检：单股≤20%/行业≤40%/现金≥10%）；④自查修掉两个真缺陷：kline_history 走 engine 返回 datetime.date 而 psql 路径是 Timestamp（导致透镜 AttributeError + 基准 join 静默 0 行）、var95_amount 误按账户总资产折算（−10623 vs 正确的 −1717，差 6 倍且方向性误导）；⑤明确有效注数（特征值口径，不含权重）与名义注数（1/Σw²）不可直接比大小。提交 a12a320b、4d5ad55f。v2 已重启（pid 93608），API 实测返回 execution_plan/risk_lens/limit_check 全通过。**待办**：:13080 已排定延迟重启以绑定 DSH core_plan 工具（进程 19:16:15 早于 dist 构建 20:13:23）——重启后需刷新页面，并验证 tools.core_plan 可调用。', 'knowledge', '{core_plan,静默少投,公式透镜,limit_check,重启绑定,2026-09-13}', NULL, '''+17'':13A,26B ''-09'':2A,15B ''-13'':3A,16B ''/cvar'':60B ''0'':96B ''1'':112B ''10'':79B ''100'':37B ''100/cap'':48B ''10623'':101B ''13'':142B ''13080'':128B ''15'':41B,137B ''16'':136B ''1717'':104B ''19'':135B ''20'':75B,141B ''2026'':1A,14B ''23'':143B ''3'':39B ''36'':12A,25B ''4'':68B ''40'':77B ''45'':43B ''4d5ad55f'':117B ''6'':106B ''93608'':121B ''a12a320b'':116B ''amount'':99B ''api'':122B ''apply'':31B,50B ''attributeerror'':92B ''c8cae280'':10A,23B ''cap'':33B ''cap/refill_core/enforce_core_constraints'':52B ''ceil'':47B ''check'':72B ''core'':5A,18B,131B ''datetime.date'':86B ''delta.limit'':71B ''dist'':139B ''dsh'':130B ''engine'':84B ''execution'':66B,124B ''history'':82B ''join'':94B ''kline'':81B ''lens'':56B ''pid'':120B ''plan'':6A,19B,67B,132B,147B ''plan/risk_lens/limit_check'':125B ''psql'':88B ''risk'':55B ''timestamp'':90B ''tools.core'':146B ''v2'':118B ''var95'':98B ''vs'':102B ''w'':9A,22B ''w-c8cae280'':8A,21B ''weight'':32B,51B ''α'':64B ''β'':63B ''σw'':113B ''上限'':36B ''不可直接比大小'':114B ''不含权重'':110B ''与名义注数'':111B ''个单测'':27B ''会只投一半的钱且无报错'':44B ''使不变量可单测'':53B ''倍且方向性误导'':107B ''全通过'':126B ''加固交付'':7A,20B ''单股'':74B ''只'':40B ''可调用'':148B ''在'':34B ''基准'':93B ''夏普'':58B ''实测返回'':123B ''宪法第3条静态复检'':73B ''导致透镜'':91B ''工具'':133B ''差'':105B ''已排定延迟重启以绑定'':129B ''已重启'':119B ''平均相关'':61B ''年化波动'':57B ''并验证'':145B ''待办'':127B ''批分批名单'':69B ''把持仓下限自动抬到'':46B ''抓到并修复'':28B ''抽出模块级纯函数'':49B ''提交'':115B ''新增三段产物字段'':54B ''日var'':59B ''早于'':138B ''时静默丢弃权重'':38B ''明确有效注数'':108B ''有效注数'':62B ''权重和仅'':42B ''构建'':140B ''标的数'':35B ''正确的'':103B ''深夜'':4A,17B ''特征值口径'':109B ''现改为显式报错'':45B ''现金'':78B ''生成时算一次'':65B ''禁止把机械差额一次打满'':70B ''缺陷'':30B ''而'':87B ''自查修掉两个真缺陷'':80B ''行'':97B ''行业'':76B ''补'':11A,24B ''误按账户总资产折算'':100B ''走'':83B ''路径是'':89B ''返回'':85B ''进程'':134B ''重启后需刷新页面'':144B ''静默'':95B ''静默少投'':29B', '2026-09-13 23:49:50.898098', '2026-09-13 23:49:50.898098', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('9b3d9026-73d9-4526-b7ad-a3492df3dff1', '2026-09-13 深夜线上缺陷（w-c8cae280 抓到并修复）：DSH 工具 core_pl', '2026-09-13 深夜线上缺陷（w-c8cae280 抓到并修复）：DSH 工具 core_plan 的 output schema **比线上数据更严** → 工具在 happy path 上不可用。实测报错：unavailable_reason must be a string / freshness.stale_reason must be a string / delta.rows[17].target_shares must be a number。根因：后端在正常情形下返回 null（计划可用→unavailable_reason=null；计划新鲜→stale_reason=null；held_only 行→target_shares/delta_shares=null），而 schema 声明为 string/number。修法：按 dsh-tools json-schema.js 实测规则（type 数组不支持；type 与 oneOf 不能并存；oneOf 旁允许 description，不允许 properties/items/enum）改为 oneOf:[{type:X},{type:null}]。**关键教训**：该 schema 此前只被"构造即编译 19 个 schema"的冒烟测试覆盖（源码级绿灯），直到把 :13080 重启、工具真正绑定后才第一次执行——再次证明"源码级测试不能证明线上行为"；且这是"schema 契约必须与线上数据模型对齐"的老坑新形态（不是 mock 与线上脱节，而是 schema 与真实 null 语义脱节）。另注：绑定还依赖进程重启（investment 的 package.main 指向 dist，进程 19:16:15 早于 dist 构建 20:13/23:51）。', 'experience', '{dsh-tool,schema-契约,null-语义,源码级绿灯陷阱,core_plan,2026-09-13}', NULL, '''-09'':2A,14B ''-13'':3A,15B ''13/23'':142B ''13080'':110B ''15'':137B ''16'':136B ''17'':47B ''19'':104B,135B ''20'':141B ''2026'':1A,13B ''51'':143B ''a'':38B,44B,52B ''be'':37B,43B,51B ''c8cae280'':7A,19B ''core'':11A,23B ''delta.rows'':46B ''description'':90B ''dist'':133B,139B ''dsh'':9A,21B,78B ''dsh-tools'':77B ''freshness.stale'':40B ''happy'':30B ''held'':65B ''investment'':129B ''json-schema.js'':80B ''mock'':120B ''must'':36B,42B,50B ''null'':56B,60B,64B,70B,98B,125B ''number'':53B ''oneof'':86B,88B,94B ''only'':66B ''output'':26B ''package.main'':131B ''path'':31B ''pl'':12A ''plan'':24B ''properties/items/enum'':92B ''reason'':35B,41B,59B,63B ''schema'':27B,72B,101B,106B,116B,123B ''shares'':49B ''shares/delta_shares'':69B ''stale'':62B ''string'':39B,45B ''string/number'':74B ''target'':48B,68B ''tools'':79B ''type'':82B,84B,95B,97B ''unavailable'':34B,58B ''w'':6A,18B ''w-c8cae28