INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('749f3209-4d25-405f-8ebe-e56987d085bc', 'REQ-24e15d 批次 B1（w-32314d00，2026-09-14）完成：jobs 层 6', 'REQ-24e15d 批次 B1（w-32314d00，2026-09-14）完成：jobs 层 6 文件 15 处裸 SQL 清零 + 删死代码 kline_priority_sync（3 处）。两条通用教训：①【指标自身会骗人】扫描器 cursor_execute 原口径写死 `\bcursor\.execute\(`，只认变量名恰好叫 cursor 的调用，漏计 `cur.execute(...)`/`conn.execute(...)` 两类同义写法 → 基线偏低约 40%，验收看着绿实际没改完。凡「用正则量化代码质量」，必须先验证正则覆盖了所有同义写法，并区分「待办桶」与「人工复核桶」（session.execute(<标识符>) 无法用正则判定，本仓 43/48 是 stmt=select(...) 属正常）。②【分表后旧读路径会静默返回 0】指数自 2026-09-11 与个股分表（指数在 quant.index_daily、键带市场后缀如 399006.SZ；daily_klines 里 399 族 0 行），而 verification_job/weekly_report_job/risk_check_job 三处仍读 quant.daily_klines 取指数价 → 「基准收益」长期恒为 0.0、超额收益被系统性高估。修法不是简单换表名，而是收敛成仓储的指数口径方法并在取数为空时 logger.error，严禁把「没取到」静默当成「收益为 0」。', 'experience', '{REQ-24e15d,裸SQL迁ORM,扫描器口径,指数分表,静默返回0,w-32314d00}', NULL, '''-09'':10A,25B,80B ''-11'':81B ''-14'':11A,26B ''0'':77B,93B,113B ''0.0'':104B ''15'':32B ''2026'':9A,24B,79B ''24e15d'':3A,18B ''3'':40B ''32314d00'':8A,23B ''399'':91B ''399006.sz'':87B ''40'':58B ''43/48'':71B ''6'':15A,30B ''b1'':5A,20B ''bcursor'':48B ''conn.execute'':55B ''cur.execute'':54B ''cursor'':45B,51B ''daily'':85B,88B ''execute'':46B,49B ''job/weekly_report_job/risk_check_job'':97B ''jobs'':13A,28B ''kline'':37B ''klines'':89B,100B ''logger.error'':108B ''priority'':38B ''quant.daily'':99B ''quant.index'':84B ''req'':2A,17B ''req-24e15d'':1A,16B ''select'':74B ''session.execute'':67B ''sql'':34B ''stmt'':73B ''sync'':39B ''verification'':96B ''w'':7A,22B ''w-32314d00'':6A,21B ''三处仍读'':98B ''与'':65B ''与个股分表'':82B ''两条通用教训'':42B ''两类同义写法'':56B ''严禁把'':109B ''人工复核桶'':66B ''修法不是简单换表名'':106B ''凡'':60B ''分表后旧读路径会静默返回'':76B ''删死代码'':36B ''原口径写死'':47B ''取指数价'':101B ''只认变量名恰好叫'':50B ''基准收益'':102B ''基线偏低约'':57B ''处'':41B ''处裸'':33B ''完成'':12A,27B ''层'':14A,29B ''属正常'':75B ''并区分'':63B ''待办桶'':64B ''必须先验证正则覆盖了所有同义写法'':62B ''扫描器'':44B ''批次'':4A,19B ''指数在'':83B ''指数自'':78B ''指标自身会骗人'':43B ''收益为'':112B ''文件'':31B ''族'':92B ''无法用正则判定'':69B ''是'':72B ''本仓'':70B ''标识符'':68B ''没取到'':110B ''清零'':35B ''漏计'':53B ''用正则量化代码质量'':61B ''的调用'':52B ''而'':95B ''而是收敛成仓储的指数口径方法并在取数为空时'':107B ''行'':94B ''超额收益被系统性高估'':105B ''里'':90B ''键带市场后缀如'':86B ''长期恒为'':103B ''静默当成'':111B ''验收看着绿实际没改完'':59B', '2026-09-14 00:11:35.447284', '2026-09-14 00:11:35.447284', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('c5d3fb00-c503-45c2-a665-73560fe3ed2a', '2026-09-14 凌晨（w-c8cae280）三件事的结论：①.date() 类：用户点名的 2', '2026-09-14 凌晨（w-c8cae280）三件事的结论：①.date() 类：用户点名的 2 处**都是误报**（signal_test_log._to_date 分支顺序正确、rotation 只在 datetime 分支调用），但发现全库有 **4 份各自实现的 _as_date**（无共享家→守卫漂移），已建 domain/common/dates.py 收口，并修 3 处真隐患（rotation 对 date 静默落空、market_session.current/next_boundary_at 裸调 at.date()、factor_analysis 的 coverage 键）。②5 个既存失败测试：3 个背后是真缺陷（exit-plan 把 Stock 对象当 dict → 500；StockCodeValidator 的 kline_repo 为 None → data-health 500；stock_fund_flow.quality_flag 有列无迁移 → 测试库漂移致资金流 5 用例全红），3 个是测试腐烂（fixture 同日复制60份<min_klines 120、stock mock 用 dict 而契约是 ORM 对象、OLLAMA_BASE_URL 早已失效致降级路径长期假绿、mock 缺 lesson 参数）。③写工具实调**抓到最严重的一个**：algo_execute 是**假执行器**——后端 /api/orders/algo-execute 只生成 TWAP/VWAP 切片计划，不接交易服务、不过 trade_guard、零成交（实测现金 0 变动）；且 quantity=150 非整手也放行。已补整手校验 + wrap 标注 executed=false + 描述改计划语义。**事故**：修 algo 时我在 prompt.ts 写入多行字符串字面量 → 构建失败 → **trading/dist 被清空**（20 分钟窗口内若重启则全部 trading 工具消失）；已修复并恢复 dist。教训复现：构建失败会清空 dist，必须构建后校验产物存在。', 'experience', '{假执行器,dist清空,测试腐烂,schema漂移,日期归一,2026-09-14}', NULL, '''-09'':2A,14B ''-14'':3A,15B ''/api/orders/algo-execute'':119B ''/next_boundary_at'':54B ''0'':129B ''120'':96B ''150'':133B ''2'':12A,24B ''20'':150B ''2026'':1A,13B ''3'':46B,64B,90B ''4'':36B ''5'':62B,88B ''500'':73B,83B ''algo'':114B,143B ''analysis'':58B ''as'':38B ''at.date'':56B ''base'':105B ''c8cae280'':7A,19B ''coverage'':60B ''data'':81B ''data-health'':80B ''date'':9A,21B,39B,50B ''datetime'':33B ''dict'':72B,100B ''dist'':155B,158B ''domain/common/dates.py'':43B ''execute'':115B ''executed'':138B ''exit'':67B ''exit-plan'':66B ''factor'':57B ''false'':139B ''fixture'':92B ''flag'':85B ''guard'':126B ''health'':82B ''kline'':76B ''klines'':95B ''lesson'':110B ''log._to_date'':29B ''market_session.current'':53B ''market_session.current/next_boundary_at'':52B ''