INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('188f3ad7-cc9b-4317-b1a1-9b9fb1386ccc', '【2026-09-13 数据质量告警根因】回填失败率 64.0%(32/50) 是口径缺陷：分母=本', '【2026-09-13 数据质量告警根因】回填失败率 64.0%(32/50) 是口径缺陷：分母=本次尝试回填的前50只问题股(服务层明细上限)，其中37只为退市股(is_delisted=true，32只失败+5只"成功")，在市股失败0只。成因：quant.stocks 混装5533在市+324退市+指数行，扫描/缺口检测/回填全链路不过滤 is_delisted，退市股整窗全缺被排到最前，吃掉74%回填预算。当晚akshare连接被重置为加重因素非根因。被掩盖的两处真缺陷：①2026-09-11仅5271行K线(vs前日5505)，268只在市股缺当日(252只ST中仅13只有)，源从sina翻转为tencent，属同步漏采；②回填写入跨标的串号污染——16行source=NULL中12行内容是别的股票行情(000488/000504/000595/000632/000668/000669/000677 七只在市股中招)，且 000606顺利退 自2026-09-01起每日写入000610的行情(source=baostock)，机制疑为baostock全局结果集串号+_convert_klines不校验记录归属。来源：launchd-stdout.log行239880-241740、SQLAlchemy查daily_klines/stocks、data_fetch_quote实时(2026-09-14 00:30-00:32)。详见 docs/work-logs/2026-09/data-quality-backfill-alert-rootcause.md', 'knowledge', '{数据质量,回填失败率,退市股污染,daily_klines,跨标的串号,2026-09-11缺口,w-d8d9aafb}', NULL, '''+324'':34B ''+5'':27B ''-00'':86B ''-01'':65B ''-09'':2A,12B,48B,64B,82B ''-11'':49B ''-13'':3A,13B ''-14'':83B ''-241740'':75B ''00'':84B ''000488/000504/000595/000632/000668/000669/000677'':59B ''000606顺利退'':62B ''16行source'':57B ''2026'':1A,11B,47B,81B ''252只st中仅13只有'':53B ''268只在市股缺当日'':52B ''30'':85B ''32'':87B ''32/50'':7A,17B ''32只失败'':26B ''64.0'':6A,16B ''baostock'':68B ''convert'':70B ''data'':78B ''delisted'':24B,41B ''docs/work-logs/2026-09/data-quality-backfill-alert-rootcause.md'':89B ''fetch'':79B ''is'':23B,40B ''klines/stocks'':77B ''klines不校验记录归属'':71B ''launchd-stdout.log'':73B ''null中12行内容是别的股票行情'':58B ''quant.stocks'':32B ''quote实时'':80B ''source'':67B ''sqlalchemy查daily'':76B ''true'':25B ''vs前日5505'':51B ''七只在市股中招'':60B ''且'':61B ''仅5271行k线'':50B ''其中37只为退市股'':22B ''分母'':9A,19B ''只'':28B ''吃掉74'':43B ''回填全链路不过滤'':39B ''回填写入跨标的串号污染'':56B ''回填失败率'':5A,15B ''回填预算'':44B ''在市股失败0只'':30B ''属同步漏采'':55B ''当晚akshare连接被重置为加重因素非根因'':45B ''成功'':29B ''成因'':31B ''扫描