INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('0dc37f6a-8f29-4e0d-991e-a23d7b42dd1a', '2026-09-14（w-c8cae280）"陈旧方法批量对齐"的实战结论：**先做全库候选搜索，再', '2026-09-14（w-c8cae280）"陈旧方法批量对齐"的实战结论：**先做全库候选搜索，再看 "Did you mean"**。教训实例：我上一轮只看 Python 的 "Did you mean"（字符串相似度提示）就把 get_factors 判成"能力缺口"，实际全库有 get_factors_by_symbol(symbol, start, end, factor_names=None)，与测试的 get_factors(symbol, date) 是**同一能力**（差别只在单日 vs 区间），已对齐 5 处调用。而 get_factor_history→get_factor_time_series 是真重命名（2 passed），但**返回类型也变了**（dict→FactorValue 实体），断言须从成员判断改为属性访问。对齐后失败性质从 AttributeError 变为**契约差异**：现实现不做入参校验（DID NOT RAISE ValueError）、未来日期返回 [] 而测试期望 None → 说明"能对齐的是方法名与取数口径，对不齐的是入参校验与边界语义"。四个真缺口（get_signal_count_by_date 按日序列 / get_all_strategy_configs 配置对象+过滤 / get_executions_by_symbol / get_executions_by_status）生产调用数均为 0，属"能力回退 vs 测试陈旧"的分叉，需归属口径；硬改测试=掩盖回退，故停手待口径。提交 c5e97f9a、本次对齐。', 'experience', '{批量对齐,DidYouMean不可信,全库候选搜索,契约差异,能力回退,2026-09-14}', NULL, '''-09'':2A,12B ''-14'':3A,13B ''0'':115B ''2'':70B ''2026'':1A,11B ''5'':59B ''all'':101B ''attributeerror'':79B ''by'':40B,97B,108B,112B ''c5e97f9a'':126B ''c8cae280'':6A,16B ''configs'':103B ''count'':96B ''date'':52B,98B ''dict'':74B ''did'':21B,28B,83B ''end'':44B ''executions'':107B,111B ''factor'':45B,63B,66B ''factors'':34B,39B,50B ''factorvalue'':75B ''get'':33B,38B,49B,62B,65B,94B,100B,106B,110B ''history'':64B ''mean'':23B,30B ''names'':46B ''none'':47B,89B ''not'':84B ''passed'':71B ''python'':26B ''raise'':85B ''series'':68B ''signal'':95B ''start'':43B ''status'':113B ''strategy'':102B ''symbol'':41B,42B,51B,109B ''time'':67B ''valueerror'':86B ''vs'':56B,118B ''w'':5A,15B ''w-c8cae280'':4A,14B ''you'':22B,29B ''与测试的'':48B ''但'':72B ''先做全库候选搜索'':9A,19B ''再'':10A ''再看'':20B ''判成'':35B ''区间'':57B ''变为'':80B ''同一能力'':54B ''四个真缺口'':93B ''处调用'':60B ''契约差异'':81B ''字符串相似度提示'':31B ''实体'':76B ''实际全库有'':37B ''对不齐的是入参校验与边界语义'':92B ''对齐后失败性质从'':78B ''就把'':32B ''属'':116B ''差别只在单日'':55B ''已对齐'':58B ''我上一轮只看'':25B ''按日序列'':99B ''掩盖回退'':123B ''提交'':125B ''故停手待口径'':124B ''教训实例'':24B ''断言须从成员判断改为属性访问'':77B ''是'':53B ''是真重命名'':69B ''未来日期返回'':87B ''本次对齐'':127B ''测试陈旧'':119B ''现实现不做入参校验'':82B ''生产调用数均为'':114B ''的'':27B ''的分叉'':120B ''的实战结论'':8A,18B ''硬改测试'':122B ''而'':61B ''而测试期望'':88B ''能力回退'':117B ''能力缺口'':36B ''能对齐的是方法名与取数口径'':91B ''说明'':90B ''过滤'':105B ''返回类型也变了'':73B ''配置对象'':104B ''陈旧方法批量对齐'':7A,17B ''需归属口径'':121B', '2026-09-14 01:06:57.353432', '2026-09-14 01:06:57.353432', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('5e403a75-17eb-49fb-8f05-baef0de714cd', '2026-09-14（w-c8cae280）"该删的删、该补的补"批次执行（用户授权后）：4 个仓库', '2026-09-14（w-c8cae280）"该删的删、该补的补"批次执行（用户授权后）：4 个仓库测试文件 63 红 → 47 红（另带据删除 6 例，约清 22 项）。**补**3 处生产代码：①SignalExecutionRepository.get_executions_by_status（含 STATUSES 校验）——**同时修掉真缺陷**：GET /api/executions 声明 status 却从未使用（静默 no-op 过滤），已接线；②get_pending_executions 补 limit；③get_factors_by_symbol 补入参校验（此前完全无校验，坏输入静默以空结果"成功"）。**改**2 处测试到现契约（实测后改）：get_factors 返回 dict→List[FactorValue]、无数据 []；get_signal_count_by_date（区间序列，各层均不存在）改为验证真实存在的单日原语 count_signals_by_date。**删**6 例并原位留痕：BacktestRepository 的 get_all_strategy_configs 三例（能力现在 strategy_repository.list_strategies，且不含 is_active）、SignalExecution 的 get_executions_by_symbol 三例（**实测该表无 symbol 列**，按标的查需 join，仓库已有 by_signal 且生产调用 0）、以及 mock 旧裸 cursor 的 count_by_date_with_data。**原则沉淀**：面对"方法不存在"，先按(生产调用数 vs 测试调用数)判归属，再核对**方法名/参数形态/返回类型**三件事（本轮 get_factors 与 get_factor_history 各踩一次），最后才决定删/补/改。', 'experience', '{该删的删该补的补,静默no-op过滤,STATUSES校验,能力边界,2026-09-14}', NULL, '''-09'':2A,14B ''-14'':3A,15B ''/api/executions'':47B ''0'':125B ''2'':71B ''2026'':1A,13B ''22'':33B ''3'':36B ''4'':11A,23B ''47'':27B ''6'':30B,94B ''63'':25B ''active'':108B ''all'':99B ''backtestrepository'':96B ''by'':40B,64B,84B,91B,113B,122B,132B ''c8cae280'':6A,18B ''configs'':101B ''count'':83B,89B,131B ''cursor'':129B ''data'':135B ''date'':85B,92B,133B ''dict'':77B ''executions'':39B,59B,112B ''factor'':154B ''factors'':63B,75B,151B ''factorvalue'':79B ''get'':46B,57B,62B,74B,81B,98B,111B,150B,153B ''history'':155B ''is'':107B ''join'':120B ''limit'':61B ''list'':78B ''mock'':127B ''no'':53B ''no-op'':52B ''op'':54B ''pending'':58B ''signal'':82B,123B ''signalexecution'':109B ''signalexecutionrepository.get'':38B ''signals'':90B ''status'':41B,49B ''statuses'':43B ''strategies'':105B ''strategy'':100B ''strategy_repository.list'':104B ''symbol'':65B,114B,117B ''vs'':141B ''w'':5A,17B ''w-c8cae280'':4A,16B ''with'':134B ''三件事'':148B ''三例'':102B,115B ''与'':152B ''且不含'':106B ''且生产调用'':124B ''个仓库'':12A ''个仓库测试文件'':24B ''仓库已有'':121B ''以及'':126B ''例'':31B ''例并原位留痕'':95B ''先按'':139B ''再核对'':144B ''列'':118B ''删'':93B ''判归属'':143B ''区间序列'':86B ''却从未使用'':50B ''原则沉淀'':136B ''参数形态'':146B ''另带据删除'':29B ''各层均不存在'':87B ''各踩一次'':156B ''同时修掉真缺陷'':45B ''含'':42B ''坏输入静默以空结果'':68B ''声明'':48B ''处测试到现契约'':72B ''处生产代码'':37B ''实测后改'':73B ''实测该表无'':116B ''已接线'':56B ''成功'':69B ''批次执行'':9A,21B ''按标的查需'':119B ''改'':70B,159B ''改为验证真实存在的单日原语'':88B ''方法不存在'':138B ''方法名'':145B ''无数据'':80B ''旧裸'':128B ''最后才决定删'':157B ''本轮'':149B ''校验'':44B ''此前完全无校验'':67B ''测试调用数'':142B ''生产调用数'':140B ''用户授权后'':10A,22B ''的'':97B,110B,130B ''红'':26B,28B ''约清'':32B ''能力现在'':103B ''补'':35B,60B,158B ''补入参校验'':66B ''该删的删'':7A,19B ''该补的补'':8A,20B ''过滤'':55B ''返回'':76B ''返回类型'':147B ''静默'':51B ''面对'':137B ''项'':34B', '2026-09-14 01:09:43.228902', '2026-09-14 01:09:43.228902', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('2f6c6f51-eba5-4a21-b1d3-cc17514ca9ae', '2026-09-14（w-c8cae280）**线上问题修复（第 5、6 个线上端点缺陷）**：①P', '2026-09-14（w-c8cae280）**线上问题修复（第 5、6 个线上端点缺陷）**：①POST /api/executions 必然 500——路由把 payload(dict) 原样传给仓库 create_execution(signal_id, execution_date, execution_price, quantity, commission=0.0, status)，实测 TypeError: missing 3 required positional arguments；②PUT /api/executions/{id}/close 必然 500——仓库要 4 个参数（含 pnl），路由只传 3 个，实测 TypeError: missing 1 required positional argument: pnl；③GET /api/executions 的 offset 被静默忽略（分页是假的，status 参数上一轮已修）。修法：路由按真实签名解包+显式校验（缺字段 400 而非 500）；close 的 pnl 优先取请求体、否则由已存记录推算 (平仓价-执行价)×数量（**不在路由里凭空写 0，否则盈亏统计静默失真**）；get_all_executions 补 offset 形参并接线。新增 tests/test_executions_routes_regression.py（6 passed）作为回归守卫——这两个缺陷"测试红着、线上 500 着"共存很久，没有守卫下次重构仍只会以 500 暴露。**已重启 v2（pid 86821）并实测上线**：空体 POST→400、非法 status→400、status+offset→200、关闭不存在→404（修复前均为 500/静默无效）。提交 a308213f。**同类模式（值得作为巡检项）**：路由声明的参数被静默忽略、路由调用形态与仓库签名不一致——今晚已发现 6 处线上端点缺陷（signals/history、stock/exit-plan、stock/data-health、executions POST、executions close、executions status/offset），建议加一道"路由-仓库签名一致性"守卫。', 'experience', '{线上500,路由-仓库签名不一致,静默忽略参数,回归守卫,2026-09-14}', NULL, '''-09'':2A,14B ''-14'':3A,15B ''/api/executions'':25B,52B,74B ''/close'':54B ''0'':98B ''0.0'':42B ''1'':68B ''200'':133B ''2026'':1A,13B ''3'':47B,63B ''4'':58B ''400'':85B,127B,130B ''404'':135B ''5'':9A,21B ''500'':27B,56B,87B,114B,118B,137B ''6'':10A,22B,108B,146B ''86821'':123B ''a308213f'':140B ''all'':101B ''argument'':71B ''arguments'':50B ''c8cae280'':6A,18B ''close'':88B,154B ''commission'':41B ''create'':32B ''date'':37B ''dict'':30B ''execution'':33B,36B,38B ''executions'':102B,151B,153B,155B ''get'':73B,100B ''id'':35B,53B ''missing'':46B,67B ''offset'':76B,104B,132B ''p'':12A ''passed'':109B ''payload'':29B ''pid'':122B ''pnl'':61B,72B,90B ''positional'':49B,70B ''post'':24B,126B,152B ''price'':39B ''put'':51B ''quantity'':40B ''required'':48B,69B ''signal'':34B ''signals/history'':148B ''status'':43B,79B,129B,131B ''status/offset'':156B ''stock/data-health'':150B ''stock/exit-plan'':149B ''tests/test_executions_routes_regression.py'':107B ''typeerror'':45B,66B ''v2'':121B ''w'':5A,17B ''w-c8cae280'':4A,16B ''不在路由里凭空写'':97B ''个'':64B ''个参数'':59B ''个线上端点缺陷'':11A,23B ''今晚已发现'':145B ''仓库签名一致性'':160B ''仓库要'':57B ''优先取请求体'':91B ''作为回归守卫'':110B ''修复前均为'':136B ''修法'':81B ''值得作为巡检项'':142B ''共存很久'':116B ''关闭不存在'':134B ''分页是假的'':78B ''原样传给仓库'':31B ''参数上一轮已修'':80B ''同类模式'':141B ''否则由已存记录推算'':92B ''否则盈亏统计静默失真'':99B ''含'':60B ''处线上端点缺陷'':147B ''守卫'':161B ''实测'':44B,65B ''已重启'':120B ''平仓价'':94B ''平仓价-执行价'':93B ''并实测上线'':124B ''建议加一道'':157B ''形参并接线'':105B ''必然'':26B,55B ''执行价'':95B ''提交'':139B ''数量'':96B ''新增'':106B ''显式校验'':83B ''暴露'':119B ''没有守卫下次重构仍只会以'':117B ''测试红着'':112B ''的'':75B,89B ''着'':115B ''空体'':125B ''第'':8A,20B ''线上'':113B ''线上问题修复'':7A,19B ''缺字段'':84B ''而非'':86B ''补'':103B ''被静默忽略'':77B ''路由'':159B ''路由-仓库签名一致性'':158B ''路由只传'':62B ''路由声明的参数被静默忽略'':143B ''路由把'':28B ''路由按真实签名解包'':82B ''路由调用形态与仓库签名不一致'':144B ''这两个缺陷'':111B ''静默无效'':138B ''非法'':128B', '2026-09-14 01:23:06.524436', '2026-09-14 01:23:06.524436', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('3a47ce54-2aa0-41f1-b6ba-b0493d693c91', 'REQ-24e15d B4-c1 (2026-09-14, w-32314d00) 三条可复用硬教训', 'REQ-24e15d B4-c1 (2026-09-14, w-32314d00) 三条可复用硬教训: (1) 裸 SQL 迁 ORM 前必须先核对真库 schema, 不能照 SQL 文本翻译。 portfolio_repository 的 15 个站点里有 6 个对着已归档的 quant.orders 写 SQL (2026-08-25 归档为 orders_archived), 迁移它只会换异常类型不修行为, 属伪造进度。 (2) ORM 模型可能与真库约束正面冲突: quant.trades 的 DB CHECK trades_action_check 强制小写 buy/sell (36 行存量全小写), 而 models/trade.py 原先用大写 @validates 写 BUY 直接 CheckViolation, 机械迁移 record_trade 会把能用的代码改成炸的。 判定口诀: 迁移前先跑 information_schema 核对列与约束, 再对每种写入各试一次真库往返。 (3) 静默缺陷特征 = 不抛异常、字段齐全、只有数值错: get_trade_stats 因大写过滤把 36 笔 交易统计成 0 买 0 卖 (fee 却是对的), 只有拿真库数据对独立口径才发现。', 'experience', '{REQ-24e15d,ORM迁移,裸SQL,静默缺陷,quant.trades,quant.orders,真库核对}', NULL, '''-08'':48B ''-09'':8A,21B ''-14'':9A,22B ''-25'':49B ''0'':99B,101B ''1'':27B ''15'':40B ''2'':55B ''2026'':7A,20B,47B ''24e15d'':3A,16B ''3'':87B ''32314d00'':12A,25B ''36'':67B,96B ''6'':42B ''action'':63B ''archived'':52B ''b4'':5A,18B ''b4-c1'':4A,17B ''buy'':74B ''buy/sell'':66B ''c1'':6A,19B ''check'':61B,64B ''checkviolation'':76B ''db'':60B ''fee'':103B ''get'':92B ''information'':83B ''models/trade.py'':70B ''orders'':51B ''orm'':31B,56B ''portfolio'':37B ''quant.orders'':44B ''quant.trades'':58B ''record'':78B ''repository'':38B ''req'':2A,15B ''req-24e15d'':1A,14B ''schema'':33B,84B ''sql'':29B,35B,46B ''stats'':94B ''trade'':79B,93B ''trades'':62B ''validates'':72B ''w'':11A,24B ''w-32314d00'':10A,23B ''三条可复用硬教训'':13A,26B ''不抛异常'':89B ''不能照'':34B ''个对着已归档的'':43B ''个站点里有'':41B ''买'':100B ''交易统计成'':98B ''会把能用的代码改成炸的'':80B ''再对每种写入各试一次真库往返'':86B ''写'':45B,73B ''判定口诀'':81B ''前必须先核对真库'':32B ''卖'':102B ''却是对的'':104B ''原先用大写'':71B ''只有拿真库数据对独立口径才发现'':105B ''只有数值错'':91B ''因大写过滤把'':95B ''字段齐全'':90B ''属伪造进度'':54B ''强制小写'':65B ''归档为'':50B ''文本翻译'':36B ''机械迁移'':77B ''核对列与约束'':85B ''模型可能与真库约束正面冲突'':57B ''的'':39B,59B ''直接'':75B ''笔'':97B ''而'':69B ''行存量全小写'':68B ''裸'':28B ''迁'':30B ''迁移前先跑'':82B ''迁移它只会换异常类型不修行为'':53B ''静默缺陷特征'':88B', '2026-09-14 01:51:09.836295', '2026-09-14 01:51:09.836295', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('663622b8-b550-4477-af46-3d450025afaf', '2026-09-13 项目看板验收与归档落地（窗口 w-1cee2467，用户要求「验收 有人工审核', '2026-09-13 项目看板验收与归档落地（窗口 w-1cee2467，用户要求「验收 有人工审核 / 归档 要有项目文档设计，文档如何合并，不同问题如何记录文档」）。①验收人工审核：accepting>done 收回为人工闸门（agent 可提交材料但过不了），新工具 reqboard_verify_submit(summary+evidence 可复核证据)，无材料时人也不能过（证据闸），退回返工必须写意见并回 implementing，结论写进 verification + 评论 + 时间线；看板有验收区与「待人工审核」chip。②归档=存底+合并：新工具 reqboard_archive_submit(dir/docs[]/merged_into[]/index_entry)，ARCHIVE_DOC_RULES 按需求类型校验必填文档与合法合并去向（feature→architecture|guides；bug→known-issues+retro；doc→docs/；refactor→architecture|work-logs+retro；spike→research+retro；chore→work-logs），需求目录形状亦校验（docs/requirements/REQ-xxxxxx）；人点 POST /req/archive 才进 archived。规范文档 agent-dh/docs/architecture/requirement-archive.md，模板 agent-dh/docs/requirements/_template/*（requirement/plan/verification/retro/known-issue/research），归档索引 agent-dh/docs/requirements/INDEX.md，新建 known-issues/ 与 research/。184 单测/14 文件。生效：client 刷新，host 重启 13080。', 'knowledge', '{reqboard,验收,归档,文档规范,w-1cee2467}', NULL, '''-09'':2A,13B ''-13'':3A,14B ''/14'':119B ''/docs/architecture/requirement-archive.md'':99B ''/docs/requirements/_template'':104B ''/docs/requirements/index.md'':110B ''/index_entry'':60B ''/merged_into'':59B ''/req/archive'':92B ''13080'':126B ''184'':117B ''1cee2467'':8A,19B ''2026'':1A,12B ''accepting'':28B ''agent'':31B,97B,102B,108B ''agent-dh'':96B,101B,107B ''architecture'':66B,76B ''archive'':56B,61B ''archived'':94B ''bug'':68B ''chip'':50B ''chore'':84B ''client'':122B ''dh'':98B,103B,109B ''dir/docs'':58B ''doc'':62B,73B ''docs'':74B ''docs/requirements/req-xxxxxx'':89B ''done'':29B ''evidence'':38B ''feature'':65B ''guides'':67B ''host'':124B ''implementing'':43B ''issues'':71B,114B ''known'':70B,113B ''known-issues'':69B,112B ''logs'':79B,87B ''post'':91B ''refactor'':75B ''reqboard'':34B,55B ''requirement/plan/verification/retr