INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('fbc6df43-abec-44d2-a23c-3a7c014d4264', '2026-09-13 文档金字塔与项目说明书落地（窗口 w-1cee2467，用户要求「归档后应该是', '2026-09-13 文档金字塔与项目说明书落地（窗口 w-1cee2467，用户要求「归档后应该是金字塔模型一样，是项目的一个说明书，agent 可以通过这个更了解项目」）。四层：L0 入口 CLAUDE.md（指向说明书）→ L1 docs/architecture/project-manual.md（项目是什么/三层架构表/术语表含指针/怎么跑/去哪找细节/怎么维护+最近更新表）→ L2 领域篇（architecture|guides|adr|rfcs|strategy-research）→ L3 证据档案（requirements/REQ-xxxxxx、work-logs）。生长规则代码级：归档时 L3 必写+L2 至少一篇；feature/refactor/spike 必须申报 manual_updates(path/section/summary)，缺失直接拒绝归档；bug/doc/chore 写 manual_note 说明无认知变化；L1 每次变更在「最近更新」表追加一行。落地文件：docs/architecture/project-manual.md（新建）、根 CLAUDE.md 顶部「项目认知入口」、docs/README.md 顶部指说明书、docs/DOCUMENT-MANAGEMENT-PLAN.md 新增「文档金字塔与项目说明书」章、agent-dh/docs/architecture/requirement-archive.md §0.5、ArchiveRecord.manualUpdates/manualNote + ARCHIVE_DOC_RULES.requireManual + assertArchiveMaterials 校验 + 看板归档区展示 + skill/提示段同步。187 单测全绿。判据：读完 L1 就该知道项目是什么、有哪些关键认知。遗留：L1 目前是骨架+可核实内容，需后续归档逐步补密；L1 与代码一致性巡检未做；host 半未重启。', 'knowledge', '{文档金字塔,项目说明书,reqboard,归档,w-1cee2467}', NULL, '''-09'':2A,12B ''-13'':3A,13B ''/docs/architecture/requirement-archive.md'':90B ''/manualnote'':94B ''0.5'':91B ''187'':101B ''1cee2467'':8A,18B ''2026'':1A,11B ''adr'':42B ''agent'':22B,88B ''agent-dh'':87B ''architecture'':40B ''archive_doc_rules.requiremanual'':95B ''archiverecord.manualupdates'':93B ''archiverecord.manualupdates/manualnote'':92B ''assertarchivematerials'':96B ''bug/doc/chore'':65B ''claude.md'':27B,78B ''dh'':89B ''docs/architecture/project-manual.md'':30B,75B ''docs/document-management-plan.md'':83B ''docs/readme.md'':81B ''feature/refactor/spike'':59B ''guides'':41B ''host'':115B ''l0'':25B ''l1'':29B,70B,105B,109B,113B ''l2'':38B,57B ''l3'':47B,55B ''logs'':52B ''manual'':61B,67B ''note'':68B ''path/section/summary'':63B ''requirements/req-xxxxxx'':49B ''research'':46B ''rfcs'':43B ''skill'':99B ''strategy'':45B ''s