INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('e42e5cd9-a4b8-4dd0-8ee4-f04fdb2d83f6', '2026-09-14（w-f0d1f4f1, REQ-c90f01）清掉 v2 侧 5 条 Agen', '2026-09-14（w-f0d1f4f1, REQ-c90f01）清掉 v2 侧 5 条 Agent OS 镜像行（323 market_perception_daily / 324 signal_generate_sell / 325 market_style_update / 326 signal_perf_backfill_daily / 327 v2_health_check，DELETE :5001/api/scheduler/tasks/{id} 软删）。关键结论（推翻我先前判断）：软删是持久的——get_task_by_name 只按名字查、不筛软删，webhook 下次投递复用同一行 id；add_task 对同名软删行走"复活"而非新建；runs 仍挂同 task_id，健康检查（missed 本就排除 managed_by_agent_%、high_failure 按 task join runs）不受影响。核验：v2 可见任务 40→34、看板任务 65→60（other 线 3→0）、scheduleExpr 以 managed_by_agent_ 开头的行 0 条。副作用：market_perception_daily/signal_generate_sell/v2_health_check 无 v2 孪生、真身被 v2_internal 规则排除 → 暂从看板消失（待 t2 收窄排除规则）。台账 docs/requirements/REQ-c90f01/cleanup-ledger.md。', 'experience', '{scheduler,镜像行,软删除,v2_health_check,REQ-c90f01,看板,get_task_by_name}', NULL, '''-09'':2A,17B ''-14'':3A,18B ''0'':103B,110B ''2026'':1A,16B ''3'':102B ''323'':33B ''324'':37B ''325'':41B ''326'':45B ''327'':50B ''34'':96B ''40'':95B ''5'':13A,28B ''5001/api/scheduler/tasks'':55B ''60'':99B ''65'':98B ''add'':70B ''agen'':15A ''agent'':30B,84B,108B ''backfill'':48B ''by'':63B,83B,107B ''c90f01'':9A,24B ''check'':53B ''daily'':36B,49B ''daily/signal_generate_sell/v2_health_check'':115B ''delete'':54B ''docs/requirements/req-c90f01/cleanup-ledger.md'':128B ''f0d1f4f1'':6A,21B ''failure'':86B ''generate'':39B ''get'':61B ''health'':52B ''high'':85B ''id'':56B,69B,78B ''internal'':121B ''join'':89B ''managed'':82B,106B ''market'':34B,42B,113B ''missed'':80B ''name'':64B ''os'':31B ''other'':100B ''perception'':35B,114B ''perf'':47B ''req'':8A,23B ''req-c90f01'':7A,22B ''runs'':75B,90B ''scheduleexpr'':104B ''sell'':40B ''signal'':38B,46B ''style'':43B ''t2'':125B ''task'':62B,71B,77B,88B ''update'':44B ''v2'':11A,26B,51B,93B,117B,120B ''w'':5A,20B ''w-f0d1f4f1'':4A,19B ''webhook'':67B ''下次投递复用同一行'':68B ''不受影响'':91B ''不筛软删'':66B ''仍挂同'':76B ''以'':105B ''侧'':12A,27B ''健康检查'':79B ''关键结论'':58B ''副作用'':112B ''只按名字查'':65B ''可见任务'':94B ''台账'':127B ''复活'':73B ''孪生'':118B ''对同名软删行走'':72B ''开头的行'':109B ''待'':124B ''按'':87B ''推翻我先前判断'':59B ''收窄排除规则'':126B ''无'':116B ''暂从看板消失'':123B ''本就排除'':81B ''条'':14A,29B,111B ''核验'':92B ''清掉'':10A,25B ''看板任务'':97B ''真身被'':119B ''线'':101B ''而非新建'':74B ''规则排除'':122B ''软删'':57B ''软删是持久的'':60B ''镜像行'':32B', '2026-09-14 02:05:26.623942', '2026-09-14 02:05:26.623942', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('5502ba9e-ad35-412b-b412-928b43795b43', 'REQ-24e15d B4-c3（w-32314d00，2026-09-14，commit 3ec5', 'REQ-24e15d B4-c3（w-32314d00，2026-09-14，commit 3ec509f8）：四仓储 33 处裸 SQL 落 ORM。经验一——ORM 迁移必须用『真实库新旧逐值比对』而非代码审查：本批比对抓到两个只有跑起来才暴露的 bug，① SQLAlchemy 的 over(rows=(4,0)) 语义是负=PRECEDING/正=FOLLOWING，写正数会渲染成 ''ROWS BETWEEN 4 FOLLOWING AND CURRENT ROW'' 被 PG 拒绝（WindowingError），该错误潜伏在 regime 回填路径上；② func.nullif(x,0) 被 SQLAlchemy 硬编码返回类型 Numeric()，把除法渲染成 numeric 运算，末位与旧 double precision SQL 不一致（0.9767216403301303 vs …268），须在 Python 侧实现 NULLIF 语义。经验二——同名文件里的『ORM Repository』可能根本没有 ORM：strategy_performance_repository 全程 db_cursor+裸 SQL 且无模型，chip/risk 的 db 属性用 session.connection().connection 开后门。经验三——测试通过 ≠ 被测代码执行过：risk 的 3 个写入用例因旧 raw SQL 缺可选字段即 KeyError，长期靠 pytest.skip 兜底成『跳过』，迁移后首次真正跑通（32passed/3skipped → 35passed/0skipped）。经验四——提取 HEAD 旧实现做基线时，若新旧都定义 ORM 模型会撞 ''Table already defined''，需分进程 dump JSON 再比。', 'experience', '{REQ-24e15d,ORM迁移,quantsys-v2,SQLAlchemy,验证方法,w-32314d00}', NULL, '''-09'':11A,25B ''-14'':12A,26B ''0'':47B,69B ''0.9767216403301303'':82B ''2026'':10A,24B ''24e15d'':3A,17B ''268'':84B ''3'':117B ''32314d00'':9A,23B ''32passed/3skipped'':128B ''33'':30B ''35passed/0skipped'':129B ''3ec5'':14A ''3ec509f8'':28B ''4'':46B,55B ''already'':138B ''and'':57B ''b4'':5A,19B ''b4-c3'':4A,18B ''between'':54B ''bug'':41B ''c3'':6A,20B ''chip/risk'':105B ''commit'':13A,27B ''connection'':110B ''current'':58B ''cursor'':101B ''db'':100B,107B ''defined'':139B ''double'':78B ''dump'':141B ''following'':51B,56B ''func.nullif'':67B ''head'':132B ''json'':142B ''keyerror'':122B ''nullif'':88B ''numeric'':73B,75B ''orm'':34B,36B,92B,95B,135B ''over'':44B ''performance'':97B ''pg'':61B ''preceding'':49B ''precision'':79B ''pytest.skip'':124B ''python'':86B ''raw'':119B ''regime'':65B ''repository'':93B,98B ''req'':2A,16B ''req-24e15d'':1A,15B ''risk'':115B ''row'':59B ''rows'':45B,53B ''session.connection'':109B ''sql'':32B,80B,103B,120B ''sqlalchemy'':42B,71B ''strategy'':96B ''table'':137B ''vs'':83B ''w'':8A,22B ''w-32314d00'':7A,21B ''windowingerror'':63B ''x'':68B ''不一致'':81B ''且无模型'':104B ''个写入用例因旧'':118B ''侧实现'':87B ''兜底成'':125B ''全程'':99B ''再比'':143B ''写正数会渲染成'':52B ''可能根本没有'':94B ''同名文件里的'':91B ''四仓储'':29B ''回填路径上'':66B ''处裸'':31B ''属性用'':108B ''开后门'':111B ''把除法渲染成'':74B ''拒绝'':62B ''提取'':131B ''旧实现做基线时'':133B ''末位与旧'':77B ''本批比对抓到两个只有跑起来才暴露的'':40B ''模型会撞'':136B ''正'':50B ''测试通过'':113B ''的'':43B,106B,116B ''真实库新旧逐值比对'':38B ''硬编码返回类型'':72B ''经验一'':35B ''经验三'':112B ''经验二'':90B ''经验四'':130B ''缺可选字段即'':121B ''而非代码审查'':39B ''若新旧都定义'':134B ''落'':33B ''被'':60B,70B ''被测代码执行过'':114B ''裸'':102B ''该错误潜伏在'':64B ''语义'':89B ''语义是负'':48B ''跳过'':126B ''迁移后首次真正跑通'':127B ''迁移必须用'':37B ''运算'':76B ''长期靠'':123B ''需分进程'':140B ''须在'':85B', '2026-09-14 02:34:07.739342', '2026-09-14 02:34:07.739342', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('f9faa8ce-e0c7-4ca1-a5ac-dcab873933f5', '2026-09-13 docs 按 wiki 方式维护（窗口 w-1cee2467，用户要求「按照w', '2026-09-13 docs 按 wiki 方式维护（窗口 w-1cee2467，用户要求「按照wiki方式设计」）。设计：页面 = front-matter(id/title/type/status/updated/owners/tags) + 正文 + 「相关页面」双向链接；金字塔（认知高度：L1 说明书/L2 领域篇/L3 档案）与 wiki（页面连接）是两条正交的轴，一起用——向上提炼认知、横向互链。status: stub = 待写页（已被引用但未写）→ 作为后续需求候选，与 reqboard 立项打通。落地：①页面模型写进 docs/DOCUMENT-MANAGEMENT-PLAN.md；②docs/README.md 改造成 wiki 首页（从哪开始/按类型页面索引/最近改动/待写页/约定）；③project-manual、requirement-archive、rfc-014 加 front-matter；④新增巡检探针 agent-dh/scripts/wiki_probe.py：死链/孤儿页/待写页/缺 front-matter，分层报告（wiki 页计入失败，无 front-matter 的历史页只计数，避免"全是历史问题→没人看"），退出码 1=有问题，可挂定时任务；⑤skill 与绑定窗口提示段同步。实测：wiki 页 4 个、死链 0、孤儿 0、front-matter 完整、276 个历史页待迁；探针立刻抓出我前一天写的 project-manual 里两个指向不存在文件的链接（game-theory-framework/agent-autonomy 实体本就缺失）→ 登记进首页待写页。遗留：历史页迁移是长期工作；探针未挂定时；归档工具侧未做"合并是否真发生"的 fs 校验（插件进程 cwd 非仓库根，硬做会静默降级，宁可放在探针里做）。', 'knowledge', '{wiki,文档规范,reqboard,探针,w-1cee2467}', NULL, '''-014'':78B ''-09'':2A,15B ''-13'':3A,16B ''/agent-autonomy'':136B ''/l2'':40B ''/l3'':42B ''/scripts/wiki_probe.py'':87B ''0'':118B,120B ''1'':107B ''1cee2467'':11A,24B ''2026'':1A,14B ''276'':125B ''4'':115B ''agent'':85B ''agent-dh'':84B ''archive'':76B ''cwd'':148B ''dh'':86B ''docs'':4A,17B ''docs/document-management-plan.md'':61B ''docs/readme.md'':62B ''framework'':135B ''front'':30B,81B,93B,100B,122B ''front-matter'':29B,80B,92B,99B,121B ''fs'':145B ''game'':133B ''game-theory-framework'':132B ''id/title/type/status/updated/owners/tags'':32B ''l1'':38B ''manual'':73B,130B ''matter'':31B,82B,94B,101B,123B ''project'':72B,129B ''project-manual'':71B,128B ''reqboard'':57B ''requirement'':75B ''requirement-archive'':74B ''rfc'':77B ''skill'':110B ''status'':51B ''stub'':52B ''theory'':134B ''w'':10A,23B ''w-1cee2467'':9A,22B ''wiki'':6A,19B,45B,64B,96B,113B ''一起用'':48B ''与'':44B,56B ''与绑定窗口提示段同步'