INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('e8a25786-1cf9-49b6-99ce-8b7029785212', '2026-09-13 agent-dh 归档 wiki 批次推进（窗口 w-1cee2467，用户「', '2026-09-13 agent-dh 归档 wiki 批次推进（窗口 w-1cee2467，用户「继续」）。B1：guides/reqboard-workflow.md（全流程表+各阶段硬要求+13 个错误码处置）、guides/troubleshooting.md（症状→根因→处置五类：服务端口/插件工具/数据信号/文档 wiki/协作环境，依据 5 起真实事故）、guides/routine-checks.md（10 项巡检+命令+判据+频率，原则"探针绿不打扰"）。B2 起：architecture/plugin-model.md（插件=Service、装载链路、dist/src 与页面插件两半分工表、注册三步、四个真坑）、architecture/identity-and-agents-json.md（agents.json 结构与 rules 纪律声明、instance.account 为账户唯一事实源、账户边界表、窗口与会话 session-uuid↔w-xxxxxxxx、R-019 依据）；去重：卷 3 的 protocols/tool-contract.md 与 standards/tool-development.md 同概念 → 收敛为指针。当前 wiki 21 页、死链 0、孤儿 0、待写页 0、历史待迁 291。教训：探针输出被 `| tail` 掩盖退出码 → 一次死链随提交溜进 main，已修（提交前应显式看 probe 退出码）。剩余：卷 3 工具审计页、卷 4 账户交易页、卷 5 数据契约页、卷 6 记忆、卷 7 页面插件契约、卷 10 附录 + 历史页 front-matter 迁移。', 'knowledge', '{wiki,agent-dh,B1,B2,w-1cee2467}', NULL, '''+13'':34B ''-019'':83B ''-09'':2A,16B ''-13'':3A,17B ''0'':99B,101B,103B ''10'':50B,133B ''1cee2467'':13A,27B ''2026'':1A,15B ''21'':96B ''291'':105B ''3'':87B,118B ''4'':121B ''5'':47B,124B ''6'':127B ''7'':130B ''agent'':5A,19B ''agent-dh'':4A,18B ''agents.json'':68B ''architecture/identity-and-agents-json.md'':67B ''architecture/plugin-model.md'':59B ''b1'':30B ''b2'':57B ''dh'':6A,20B ''dist/src'':63B ''front'':137B ''front-matter'':136B ''guides/reqboard-workflow.md'':31B ''guides/routine-checks.md'':49B ''guides/troubleshooting.md'':36B ''instance.account'':72B ''main'':111B ''matter'':138B ''probe'':114B ''protocols/tool-contract.md'':89B ''r'':82B ''rules'':70B ''service'':61B ''session'':77B ''session-uuid'':76B ''standards/tool-development.md'':91B ''tail'':108B ''uuid'':78B ''w'':12A,26B,80B ''w-1cee2467'':11A,25B ''w-xxxxxxxx'':79B ''wiki'':8A,22B,44B,95B ''xxxxxxxx'':81B ''一次死链随提交溜进'':110B ''与'':90B ''与页面插件两半分工表'':64B ''个错误码处置'':35B ''为账户唯一事实源'':73B ''依据'':46B,84