INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('3c04cfc1-77ea-4d2f-88ca-bbda0cf6ab60', 'REQ-a458a6 修订（2026-09-14 04:01，w-4db568de）：门控阈值由首版', 'REQ-a458a6 修订（2026-09-14 04:01，w-4db568de）：门控阈值由首版 6.0 天改为 6.5 天。原因：首版依据是「每周 cron 检查一次」，但 t2 之后唯一入口是**日检查**（03:30），节律随之改变——按时间轴推演：阈值 6.0 → 训练于 03:00 时 6.02 天即重训（偏早）、训练于 03:30 时 7.00 天；阈值 7.0 → 训练于 03:30 时 8.00 天（偏晚、每次漂一天）；阈值 6.5 → 两个时点都稳定 7.0 天。已抽出纯函数 _age_needs_retrain(age_days) 并新增 test_daily_cadence_is_seven_days_for_both_training_times 钉住节律。线上复核 runs 3709 reason「仍有效 (age=0.0d < 6.5d, acc=0.5975)」。教训：**阈值必须与「检查频率」一起设计**——同一个数值在周检查与日检查下节律不同；改调度拓扑（这里是把周 cron 收敛成日任务）时必须重算阈值。', 'experience', '{REQ-a458a6,门控阈值,节律}', NULL, '''-09'':6A,19B ''-14'':7A,20B ''0.0'':98B ''0.5975'':103B ''00'':48B ''01'':9A,22B ''03'':40B,47B,54B,62B ''04'':8A,21B ''2026'':5A,18B ''30'':41B,55B,63B ''3709'':94B ''4db568de'':12A,25B ''6.0'':27B,45B ''6.02'':50B ''6.5'':29B,70B,100B ''7.0'':60B,72B ''7.00'':57B ''8.00'':65B ''a458a6'':3A,16B ''acc'':102B ''age'':75B,78B,97B ''both'':88B ''cadence'':83B ''cron'':34B,111B ''d'':99B,101B ''daily'':82B ''days'':79B,86B ''for'':87B ''is'':84B ''needs'':76B ''reason'':95B ''req'':2A,15B ''req-a458a6'':1A,14B ''retrain'':77B ''runs'':93B ''seven'':85B ''t2'':37B ''test'':81B ''times'':90B ''training'':89B ''w'':11A,24B ''w-4db568de'':10A,23B ''一起设计'':107B ''两个时点都稳定'':71B ''之后唯一入口是'':38B ''仍有效'':96B ''但'':36B ''修订'':4A,17B ''偏早'':52B ''偏晚'':67B ''原因'':31B ''同一个数值在周检查与日检查下节律不同'':108B ''天'':30B,58B,66B,73B ''天即重训'':51B ''天改为'':28B ''已抽出纯函数'':74B ''并新增'':80B ''按时间轴推演'':43B ''收敛成日任务'':112B ''改调度拓扑'':109B ''教训'':104B ''日检查'':39B ''时'':49B,56B,64B ''时必须重算阈值'':113B ''检查一次'':35B ''检查频率'':106B ''每周'':33B ''每次漂一天'':68B ''线上复核'':92B ''节律随之改变'':42B ''训练于'':46B,53B,61B ''这里是把周'':110B ''钉住节律'':91B ''门控阈值由首版'':13A,26B ''阈值'':44B,59B,69B ''阈值必须与'':105B ''首版依据是'':32B', '2026-09-14 04:02:17.492215', '2026-09-14 04:02:17.492215', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('027d72e9-f423-4471-ae30-e2310e5ee891', '基准巡检静默失效（2026-09-14，w-4db568de，并入 REQ-a458a6 t7）：s', '基准巡检静默失效（2026-09-14，w-4db568de，并入 REQ-a458a6 t7）：scripts/benchmark-freshness-check.sh 的「新鲜度」一项从未生效——`[ "$BENCH_LAST" < "$REF_LAST" ]` 在 bash 单括号里 `<` 是**输入重定向**（stderr 可见 `line 37: 2026-09-11: No such file or directory`），比较不成立、FAIL 永远为空。实证：09-13 08:40 日志 `OK: 000300.SH 最新=2026-09-10（市场最新=2026-09-11）` —— 基准已滞后一个交易日仍报 OK，正是该脚本要抓的「归因/相对收益失真」场景。修法：滞后比较改由 python3（`lag()`，ISO 串字典序）；新增**每次运行都跑的自检**（`lag(旧,新)` 必须给出 1/0），自检不通过同样投错误事件；参照标的提成 `${REF:-600519}`。验收：正常 exit 0 且 stderr 干净；故障注入（lag→echo 0）→ `FAIL: 巡检自检未通过` + error-event HTTP=201 + exit 1。commit ef04ca34。可复用教训：**bash 单括号 `[ a < b ]` 不是比较**（是重定向），字符串/数值比较要么用 `[[ ]]` 要么交给 python；凡是「巡检/门控」类代码，都应自带一条「我还能判出坏情况吗」的自检，否则坏了只会表现为永远绿灯。同类：模型门控 floor 天数 + `>7` 的自我抵消（REQ-a458a6 t1）。', 'experience', '{REQ-a458a6,benchmark,巡检,静默失效,bash陷阱}', NULL, '''-09'':3A,16B,44B,64B,68B ''-10'':65B ''-11'':45B,69B ''-13'':56B ''-14'':4A,17B ''-600519'':92B ''0'':96B,103B ''000300.sh'':61B ''08'':57B ''09'':55B ''1'':112B ''1/0'':88B ''201'':110B ''2026'':2A,15B,43B,63B,67B ''37'':42B ''40'':58B ''4db568de'':7A,20B ''7'':138B ''a'':118B ''a458a6'':11A,24B,142B ''b'':119B ''bash'':35B,116B ''bench'':30B ''commit'':113B ''directory'':50B ''echo'':102B ''ef04ca34'':114B ''error'':107B ''error-event'':106B ''event'':108B ''exit'':95B,111B ''fail'':52B,104B ''file'':48B ''floor'':136B ''http'':109B ''iso'':80B ''lag'':79B,84B,101B ''last'':31B,33B ''line'':41B ''no'':46B ''ok'':60B,71B ''or'':49B ''python'':125B ''python3'':78B ''ref'':32B,91B ''req'':10A,23B,141B ''req-a458a6'':9A,22B,140B ''s'':13A ''scripts/benchmark-freshness-check.sh'':26B ''stderr'':39B,98B ''such'':47B ''t1'':143B ''t7'':12A,25B ''w'':6A,19B ''w-4db568de'':5A,18B ''一项从未生效'':29B ''不是比较'':120B ''且'':97B ''串字典序'':81B ''修法'':76B ''凡是'':126B ''单括号'':117B ''单括号