INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('fe91dea1-77fa-4971-8e70-2d782a6b12c7', '【盘后业绩归因 2026-09-16 18:40】账户 agent_brain（投资脑自营盘，事实源', '【盘后业绩归因 2026-09-16 18:40】账户 agent_brain（投资脑自营盘，事实源 agents.json instance.account / account_list 默认账户）

