INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('a2cd0f9a-243f-4593-b871-bcae372806d6', '【方法论·两半改造耦合陷阱｜w-32314d00｜2026-09-14】计划把一次改造拆成「①只读→', '【方法论·两半改造耦合陷阱｜w-32314d00｜2026-09-14】计划把一次改造拆成「①只读→②幂等键→③路由」三步时，必须核验**中间态是否自洽**：某两步若互为前提，单独落地任一半都会**引入新缺陷**而非只是收益减半。实例：daily_review_notified 由全局布尔改 per-account（②）与逐账户投递（③）互相绑定——只做③→第一个账户置位后其余账户永远收不到唤醒；只做②→单次投递被放大成 N 次（即 2026-09-08 刚修掉的重复推送）。正确处置：把这类步骤合并为一次原子交付，或先把形态改到位但**保持行为等价**并用测试把等价性钉死（此处 test_review_invokes_notifier_once_not_per_account：3 只账户→notify 仍只调 1 次）。自查问题：这个中间态上线后，行为是变好、不变、还是变坏？答不出''不变''就不要单独发。', 'experience', '{方法论,重构,幂等,灰度,w-32314d00}', NULL, '''-08'':49B ''-09'':7A,17B,48B ''-14'':8A,18B ''1'':69B ''2026'':6A,16B,47B ''3'':65B ''32314d00'':5A,15B ''account'':37B,64B ''daily'':31B ''invokes'':59B ''n'':44B ''not'':62B ''notified'':33B ''notifier'':60B ''notify'':67B ''once'':61B ''per'':36B,63B ''per-account'':35B ''review'':32B,58B ''test'':57B ''w'':4A,14B ''w-32314d00'':3A,13B ''三步时'':23B ''不变'':74B,77B ''与逐账户投递'':38B ''两半改造耦合陷阱'':2A,12B ''中间态是否自洽'':25B ''互相绑定'':39B ''仍只调'':68B ''保持行为等价'':54B ''刚修掉的重复推送'':50B ''单次投递被放大成'':43B ''单独落地任一半都会'':27B ''即'':46B ''只做'':40B,42B ''只读'':10A,20B ''只账户'':66B ''实例'':30B ''就不要单独发'':78B ''幂等键'':21B ''并用测试把等价性钉死'':55B ''引入新缺陷'':28B ''必须核验'':24B ''或先把形态改到位但'':53B ''把这类步骤合并为一次原子交付'':52B ''方法论'':1A,11B ''某两步若互为前提'':26B ''次'':45B,70B ''正确处置'':51B ''此处'':56B ''由全局布尔改'':34B ''第一个账户置位后其余账户永远收不到唤醒'':41B ''答不出'':76B ''而非只是收益减半'':29B ''自查问题'':71B ''行为是变好'':73B ''计划把一次改造拆成'':9A,19B ''路由'':22B ''还是变坏'':75B ''这个中间态上线后'':72B', '2026-09-14 12:56:13.528262', '2026-09-14 12:56:13.528262', '{}');
