INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('2c40a246-cbb1-48db-8e78-9f23e08f6de7', '【构建安全】wrap-client.mjs 逐行注入 \t\t 缩进事故（2026-09-16）：浏', '【构建安全】wrap-client.mjs 逐行注入 \t\t 缩进事故（2026-09-16）：浏览器版 client.js 由 wrap-client.mjs 从 client.cjs 逐行加缩进生成，注入的 tab 污染了 bundle 内 marked 库的多行模板字符串 → 列表 3 空格续行被误判为 code block（渲染成 pre 灰底块）。症状：会话框弹窗 markdown 排版错乱。排查要点：client.cjs 正常而 client.js 异常 = wrap 层问题；从浏览器实际加载的 bundle 里提取函数直接跑是实锤手段。根治：wrap 只做首尾拼接、正文零改动；预防：verify-client-build.mjs 加 WRAP_SENTINEL 哨兵检测（已故障注入验证有效）。同期修复 5 个同款包（bulletin/execution/genome/holdings/web-liveness）。教训泛化：禁止用字符串逐行变换处理代码产物。', 'experience', '{wrap-client,marked,构建安全,dsh-pmboard,sentinel}', NULL, '''-09'':8A,18B ''-16'':9A,19B ''2026'':7A,17B ''3'':35B ''5'':68B ''block'':38B ''bulletin/execution/genome/holdings/web-liveness'':70B ''bundle'':30B,54B ''client.cjs'':25B,47B ''client.js'':21B,49B ''code'':37B ''markdown'':44B ''marked'':32B ''pre'':40B ''sentinel'':64B ''t'':4A,5A,14B,15B ''tab'':28B ''verify-client-build.mjs'':61B ''wrap'':51B,57B,63B ''wrap-client.mjs'':2A,12B,23B ''个同款包'':69B ''从'':24B ''从浏览器实际加载的'':53B ''会话框弹窗'':43B ''内'':31B ''列表'':34B ''加'':62B ''只做首尾拼接'':58B ''同期修复'':67B ''哨兵检测'':65B ''层问题'':52B ''已故障注入验证有效'':66B ''库的多行模板字符串'':33B ''异常'':50B ''排查要点'':46B ''排版错乱'':45B ''教训泛化'':71B ''构建安全'':1A,11B ''根治'':56B ''正常而'':48B ''正文零改动'':59B ''污染了'':29B ''注入的'':27B ''浏'':10A ''浏览器版'':20B ''渲染成'':39B ''灰底块'':41B ''由'':22B ''症状'':42B ''禁止用字符串逐行变换处理代码产物'':72B ''空格续行被误判为'':36B ''缩进事故'':6A,16B ''逐行加缩进生成'':26B ''逐行注入'':3A,13B ''里提取函数直接跑是实锤手段'':55B ''预防'':60B', '2026-09-16 22:03:31.257473', '2026-09-16 22:03:31.257473', '{}');
