INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('9bd11d4e-883e-4b8d-ab0d-c4b7e76b8fd7', '【审计纪律·已实证】复盘/审计 agent_brain 交易合规时，**必须同时核两项**：①宪法硬', '【审计纪律·已实证】复盘/审计 agent_brain 交易合规时，**必须同时核两项**：①宪法硬约束（仓位/现金/整数倍/T+1/止损）②**授权状态**（用户是否放行建仓、是否处于 PLAN_ONLY）。反例（2026-09-13 18:00 本窗口）：17 笔盘前买单全部通过宪法硬约束复核，但当轮用户已收回建仓权（09-13 15:26 起 PLAN_ONLY），我漏核授权维度并给出「合规复核通过」——结论方向性错误。另一条同源教训（多窗口并行）：下单权必须有单一闸门，旁路窗口可绕过用户裁定直接挂真实单，且账户页/常规巡检不显示（market_open 盘前单不计入 trade_monitor.pending_count）。', 'experience', '{授权核对,PLAN_ONLY,多窗口,合规核对,教训}', NULL, '''+1'':23B ''-09'':32B ''-13'':33B,41B ''/t'':22B ''00'':35B ''09'':40B ''15'':42B ''17'':37B ''18'':34B ''2026'':31B ''26'':43B ''agent'':5A,14B ''brain'':6A,15B ''count'':60B ''market'':56B ''only'':29B,46B ''open'':57B ''plan'':28B,45B ''trade_monitor.pending'':59B ''下单权必须有单一闸门'':52B ''且账户页'':54B ''交易合规时'':7A,16B ''仓位'':19B ''但当轮用户已收回建仓权'':39B ''反例'':30B ''另一条同源教训'':50B ''合规复核通过'':48B ''复盘'':3A,12B ''多窗口并行'':51B ''审计'':4A,13B ''审计纪律'':1A,10B ''宪法硬'':9A ''宪法硬约束'':18B ''已实证'':2A,11B ''常规巡检不显示'':55B ''必须同时核两项'':8A,17B ''我漏核授权维度并给出'':47B ''授权状态'':25B ''整数倍'':21B ''旁路窗口可绕过用户裁定直接挂真实单'':53B ''是否处于'':27B ''本窗口'':36B ''止损'':24B ''现金'':20B ''用户是否放行建仓'':26B ''盘前单不计入'':58B ''笔盘前买单全部通过宪法硬约束复核'':38B ''结论方向性错误'':49B ''起'':44B', '2026-09-14 22:21:05.180295', '2026-09-14 22:21:05.180295', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('f32fd300-a304-434f-b1d6-19afc1c31421', '【launchd 托管缓存事故根因】2026-09-14（w-40abbc91）：launchd 托', '【launchd 托管缓存事故根因】2026-09-14（w-40abbc91）：launchd 托管的 agent-dh 实例配置陈旧——根因是 profile 双副本分裂 + start.sh 静默保留机制。①plist 写死 DSH_PROFILE=investment，手工启动默认 agent-dh，两个 profile 目录各有 cordis.patch.yml 副本；②start.sh _ensure_from "存在即保留、永不刷新"，profiles/investment/cordis.patch.yml 滞后仓库 config/cordis.yml 达 28 小时无告警；③launchd 自身不重读 plist（kickstart 不加载 plist 变更，须 bootout+bootstrap）。处置：用户决定暂不恢复 launchd 托管——plist 已改名 .disabled 防登录自启；start.sh 已加副本/源不一致大声告警（cmp -s 检测）。遗留：.dsh-data/profiles/investment 旧副本（9-13）仍在，任何人以 DSH_PROFILE=investment 启动都会加载陈旧配置；恢复托管前须先统一 profile 名（推荐删掉 plist 的 DSH_PROFILE、归档 investment 目录）。当前实例：手工 pid、profile=agent-dh、DSH 0.1.5-rc.1、无 KeepAlive 保护。', 'knowledge', '{launchd,profile,cordis.patch.yml,缓存,start.sh,w-40abbc91}', NULL, '''-09'':4A,14B ''-13'':86B ''-14'':5A,15B ''/profiles/investment'':83B ''0.1.5'':112B ''2026'':3A,13B ''28'':53B ''40abbc91'':8A,18B ''9'':85B ''agent'':22B,37B,109B ''agent-dh'':21B,36B,108B ''bootout'':63B ''bootstrap'':64B ''cmp'':76B ''config/cordis.yml'':51B ''cordis.patch.yml'':42B ''data'':82B ''dh'':23B,38B,110B ''disabled'':71B ''dsh'':32B,81B,89B,99B,111B ''dsh-data'':80B ''ensure'':45B ''from'':46B ''investment'':34B,91B,102B ''keepalive'':115B ''kickstart'':58B ''launchd'':1A,9A,11B,19B,55B,67B ''pid'':106B ''plist'':30B,57B,60B,69B,97B ''profile'':26B,33B,40B,90B,94B,100B,107B ''profiles/investment/cordis.patch.yml'':49B ''rc.1'':113B ''s'':77B ''start.sh'':28B,44B,73B ''w'':7A,17B ''w-40abbc91'':6A,16B ''不加载'':59B ''两个'':39B ''仍在'':87B ''任何人以'':88B ''保护'':116B ''写死'':31B ''副本'':43B ''双副本分裂'':27B ''变更'':61B ''名'':95B ''启动都会加载陈旧配置'':92B ''处置'':65B ''存在即保留'':47B ''实例配置陈旧'':24B ''小时无告警'':54B ''已加副本'':74B ''已改名'':70B ''归档'':101B ''当前实例'':104B ''恢复托管前须先统一'':93B ''手工'':105B ''手工启动默认'':35B ''托'':10A ''托管'':68B ''托管的'':20B ''托管缓存事故根因'':2A,12B ''推荐删掉'':96B ''无'':114B ''旧副本'':84B ''根因是'':25B ''检测'':78B ''永不刷新'':48B ''源不一致大声告警'':75B ''滞后仓库'':50B ''用户决定暂不恢复'':66B ''的'':98B ''目录'':103B ''目录各有'':41B ''自身不重读'':56B ''达'':52B ''遗留'':79B ''防登录自启'':72B ''静默保留机制'':29B ''须'':62B', '2026-09-14 22:35:19.742838', '2026-09-14 22:35:19.742838', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('9ee36df0-6773-4692-8c21-4d5621da17d9', '【launchd 托管恢复·profile 统一】2026-09-14（w-40abbc91）遗留问', '【launchd 托管恢复·profile 统一】2026-09-14（w-40abbc91）遗留问题处置完成：①陈旧的 .dsh-data/profiles/investment/（9-13 配置副本+符号链接）整体归档至 .dsh-data/archive/profiles-investment-stale-20260914/，profiles/ 下只剩 agent-dh；②plist 移除 DSH_PROFILE=investment（plutil -lint OK），托管与手工统一回落 start.sh 缺省 profile=agent-dh，从此加载同一份 cordis.patch.yml；③launchd 作业已 bootstrap（bootstrap 后需 kill 手工实例 6845 让托管接管，KeepAlive 在端口释放后 10s 内拉起）。观察项：launchd plist 的 PATH 解析到 /Users/yunpeng/.local/bin/node=v22.23.2（.hermes），而手工实例是 homebrew node v25.6.1——两个 Node 大版本并存，若出现行为差异先查此处。恢复后验证方式：launchctl print gui/501/com.pi-investment.dsh 看 state/pid，lsof -ti:13080 -sTCP:LISTEN 看监听进程。', 'knowledge', '{launchd,profile,agent-dh,归档,node版本,w-40abbc91}', NULL, '''-09'':6A,17B ''-13'':29B ''-14'':7A,18B ''/archive/profiles-investment-stale-20260914'':36B ''/profiles/investment'':27B ''/users/yunpeng/.local/bin/node'':78B ''10s'':70B ''13080'':97B ''2026'':5A,16B ''40abbc91'':10A,21B ''6845'':66B ''9'':28B ''agent'':40B,55B ''agent-dh'':39B,54B ''bootstrap'':61B,62B ''cordis.patch.yml'':58B ''data'':26B,35B ''dh'':41B,56B ''dsh'':25B,34B,44B ''dsh-data'':24B,33B ''gui/501/com.pi-investment.dsh'':92B ''hermes'':80B ''homebrew'':82B ''investment'':46B ''keepalive'':68B ''kill'':64B ''launchctl'':90B ''launchd'':1A,12B,59B,73B ''lint'':48B ''listen'':99B ''lsof'':95B ''node'':83B,86B ''ok'':49B ''path'':76B ''plist'':42B,74B ''plutil'':47B ''print'':91B ''profile'':3A,14B,45B,53B ''profiles'':37B ''start.sh'':51B ''state/pid'':94B ''stcp'':98B ''ti'':96B ''v22.23.2'':79B ''v25.6.1'':84B ''w'':9A,20B ''w-40abbc91'':8A,19B ''下只剩'':38B ''两个'':85B ''从此加载同一份'':57B ''作业已'':60B ''内拉起'':71B ''后需'':63B ''在端口释放后'':69B ''大版本并存'':87B ''恢复后验证方式'':89B ''手工实例'':65B ''托管与手工统一回落'':50B ''托管恢复'':2A,13B ''整体归档至'':32B ''的'':75B ''看'':93B ''看监听进