INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('f18de941-64e2-4d48-8a4f-5e76893be6af', '【盯盘故障·已修】quantsys-v2 三个处置类盯盘端点曾整体 500（2026-09-11 引', '【盯盘故障·已修】quantsys-v2 三个处置类盯盘端点曾整体 500（2026-09-11 引入 89a42a99，持续 3 天）：GET /api/watch/triggers/{stats,unresolved,digest} 函数体 import 了不存在的 application.services.watch_engine.disposition，正确路径为 domain.watch.services.disposition。修复 cc66ede1（worktree fix/watch-disposition-import，3 文件 +29/-4）。根因不止一行 import：路由层无任何测试覆盖，领域层测试全绿而线上接口全废。已补回归守护测试 + 故障注入验证（回退则 3 项失败）。全量扫描 2421 条 import 确认无同类隐患。生产复现证据：curl 三个端点均 HTTP 500，/api/watch/rules 为 200。', 'experience', '{watch,quantsys-v2,API-500,import-path,test-coverage,cc66ede1}', NULL, '''+29'':44B ''-09'':9A,20B ''-11'':10A,21B ''-4'':45B ''/api/watch/rules'':65B ''/api/watch/triggers'':28B ''200'':67B ''2026'':8A,19B ''2421'':56B ''3'':25B,42B,53B ''500'':7A,18B,64B ''89a42a99'':23B ''application.services.watch_engine.disposition'':35B ''cc66ede1'':39B ''curl'':61B ''digest'':31B ''domain.watch.services.disposition'':37B ''fix/watch-disposition-import'':41B ''get'':27B ''http'':63B ''import'':33B,47B,58B ''quantsys'':4A,15B ''quantsys-v2'':3A,14B ''stats'':29B ''unresolved'':30B ''v2'':5A,16B ''worktree'':40B ''三个处置类盯盘端点曾整体'':6A,17B ''三个端点均'':62B ''为'':66B ''了不存在的'':34B ''修复'':38B ''全量扫描'':55B ''函数体'':32B ''回退则'':52B ''天'':26B ''已修'':2A,13B ''已补回归守护测试'':50B ''引'':11A ''引入'':22B ''持续'':24B ''故障注入验证'':51B ''文件'':43B ''条'':57B ''根因不止一行'':46B ''正确路径为'':36B ''生产复现证据'':60B ''盯盘故障'':1A,12B ''确认无同类隐患'':59B ''路由层无任何测试覆盖'':48B ''项失败'':54B ''领域层测试全绿而线上接口全废'':49B', '2026-09-14 23:11:00.657515', '2026-09-14 23:11:00.657515', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('825360c5-0336-43e6-8177-0a1155c2b3e0', '【方法论教训】排查"某功能有问题"时，正确顺序是①复现真实接口/现象 ②定位根因 ③才读代码推断。本', '【方法论教训】排查"某功能有问题"时，正确顺序是①复现真实接口/现象 ②定位根因 ③才读代码推断。本次先读代码得出"并发统计恒返回0导致年化损失10-20万"的结论，后续实测发现：该函数确实恒返回0，但全库83次真实共振的标的都没开共振开关、开了开关的标的从未共振 → 实际影响≈0；而真正造成用户体感的三个端点500，是靠 curl 复现才发现的。另一教训：不得编造未经实测的收益数字（我一度给出"+43.5-75.5万/年、年化+30-50%"，无任何回测依据，违反宪法第5条与R-013）。数据结论必须标来源与时点。', 'experience', '{方法论,数据驱动,R-013,禁止编造,复现优先}', NULL, '''+30'':43B ''+43.5'':38B ''-013'':47B ''-50'':44B ''-75.5'':39B ''0'':30B ''20万'':23B ''curl'':33B ''万'':40B ''不得编造未经实测的收益数字'':36B ''但全库83次真实共振的标的都没开共振开关'':27B ''另一教训'':35B ''后续实测发现'':25B ''复现才发现的'':34B ''复现真实接口'':6A,16B ''定位根因'':8A,18B ''实际影响'':29B ''年'':41B ''年化'':42B ''并发统计恒返回0导致年化损失10'':22B ''并发统计恒返回0导致年化损失10-20万'':21B ''开了开关的标的从未共振'':28B ''我一度给出'':37B ''才读代码推断'':9A,19B ''排查'':2A,12B ''数据结论必须标来源与时点'':48B ''方法论教训'':1A,11B ''无任何回测依据'':45B ''时'':4A,14B ''是靠'':32B ''本'':10A ''本次先读代码得出'':20B ''某功能有问题'':3A,13B ''正确顺序是'':5A,15B ''现象'':7A,17B ''的结论'':24B ''而真正造成用户体感的三个端点500'':31B ''该函数确实恒返回0'':26B ''违反宪法第5条与r'':46B', '2026-09-14 23:11:00.662581', '2026-09-14 23:11:00.662581', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('5c8e218b-a6fe-40ad-b5e6-a28f0868a218', '2026-09-15 盘前研判（w-b1cb22c6）：隔夜美股(9/14收盘)risk-off——', '2026-09-15 盘前研判（w-b1cb22c6）：隔夜美股(9/14收盘)risk-off——道指-0.29%(52421)、纳指-0.56%、标普-0.48%，VIX+8%报17.10；费半-6%(英伟达-3.4%/博通AMD-4%+/英特尔-5%)，存储(SK海力士-7%+/美光-5%)，光通信(康宁Coherent-12%/Lumentum-10%)，金融(美银-5%)；10Y美债盘中破5%(2023年来首次)，油价WTI+1.34%报101美元。驱动：Anthropic/Musk/Altman集体呼吁放缓AI研发→算力资本开支降温预期+美联储本周(9/16)FOMC加息预期。对A股传导：半导体/存储/光模块CPO/算力/英伟达链/消费电子承压不接飞刀；相对独立=石油石化(油价+超跌)、高股息红利电力、中概(金龙+0.36%)。A股内部：regime震荡(上限60%)、当前仓位2.9%、5日板块仅玻璃+1.0%/电力+1.1%红、新高新低比0.21偏空。持仓002007华兰生物-1.54%未暴露在外盘重灾区。结论：零交易合法，轻仓观望，等10:00经济数据+FOMC落地+企稳信号。', 'knowledge', '{盘前研判,美股,risk-off,FOMC,2026-09-15}', NULL, '''+0.36'':83B ''+1.0'':89B ''+1.1'':91B ''+1.34'':60B ''+8'':35B ''-0.29'':28B ''-0.48'':33B ''-0.56'':31B ''-09'':2A,15B ''-1.54'':96B ''-12'':52B ''-15'':3A,16B ''-3.4'':40B ''-4'':42B ''-5'':44B,49B,56B ''-6'':38B ''-7'':47B ''/lumentum-10'':53B ''00经济数据'':102B ''10y美债盘中破5'':57B ''2023年来首次'':58B ''2026'':1A,14B ''52421'':29B ''5日板块仅玻璃'':88B ''9/14'':9A,22B ''9/16'':67B ''anthropic/musk/altman'':63B ''a股内部'':84B ''b1cb22c6'':7A,20B ''fomc加息预期'':68B ''fomc落地'':103B ''off'':13A,26B ''regime震荡'':85B ''risk'':12A,25B ''risk-off'':11A,24B ''sk海力士'':46B ''vix'':34B ''w'':6A,19B ''w-b1cb22c6'':5A,18B ''上限60'':86B ''中概'':81B ''企稳信号'':104B ''偏空'':94B ''光模块cpo'':72B ''光通信'':50B ''半导体'':70B ''博通amd'':41B ''存储'':45B,71B ''对a股传导'':69B ''康宁coherent'':51B ''当前仓位2.9'':87B ''报101美元'':61B ''报17.10'':36B ''持仓002007华兰生物'':95B ''收盘'':10A,23B ''新高新低比0.21'':93B ''未暴露在外盘重灾区'':97B ''标普'':32B ''油价'':78B ''油价wti'':59B ''消费电子承压不接飞刀'':75B ''电力'':90B ''盘前研判'':4A,17B ''相对独立'':76B ''石油石化'':77B ''等10'':101B ''算力'':73B ''算力资本开支降温预期'':65B ''红'':92B ''纳指'':30B ''结论'':98B ''美光'':48B ''美联储本周'':66B ''美银'':55B ''英伟达'':39B ''英伟达链'':74B ''英特尔'':43B ''费半'':37B ''超跌'':79B ''轻仓观望'':100B ''道指'':27B ''金融'':54B ''金龙'':82B ''隔夜美股'':8A,