INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('86eaa398-ffcf-449a-a550-c93a2b626ea1', '项目看板（dsh-pmboard）列表/泳道双视图"丢失"根因与恢复（REQ-283168，w-1d', '项目看板（dsh-pmboard）列表/泳道双视图"丢失"根因与恢复（REQ-283168，w-1dd6aa57）：双视图完整实现在 git stash@{0}（注释"暂存主工作区更改以便合并 feat/pmboard-node-diff"）——合并 feat/pmboard-node-diff 后 stash 未 pop 回来，实现被遗留在 stash 里；后续 P0/P1/P2 节点内容差异化提交（5e2c6ed1/86aae7f6/41feb8f5）覆盖了列表视图代码，只在 board-mount.ts 留下悬空引用 buildBoard(state, now, boardView, listOpts(), archivedSids())。恢复方案：从 stash@{0} 提取 buildListView/视图切换(switch-view)/排序分页(list-sort/list-size)/归档会话置灰(NO_ARCHIVED/sessionChipHtml)，合并回 view.ts/board-mount.ts/styles.ts，pnpm build:client 重建通过。教训：①git stash 暂存后必须 pop/apply，否则实现静默丢失；②git log --all 只覆盖当前 refs，查"代码丢了"必须再加 git stash list + git reflog + git fsck --lost-found；③改动 lib/client.js 后必须重启服务（launchctl kickstart）才生效。', 'experience', '{pmboard,dsh-pmboard,git-stash,双视图,代码丢失,bug修复}', NULL, '''-283168'':10A,23B ''/board-mount.ts/styles.ts'':80B ''/list-size'':73B ''0'':30B,62B ''1d'':13A ''1dd6aa57'':26B ''5e2'':47B ''all'':93B ''archived/sessionchiphtml'':76B ''archivedsids'':58B ''board-mount.ts'':51B ''boardview'':56B ''build'':82B ''buildboard'':53B ''buildlistview'':64B ''c6ed1/86aae7f6/41feb8f5'':48B ''client'':83B ''dsh'':3A,16B ''dsh-pmboard'':2A,15B ''feat/pmboard-node-diff'':33B,35B ''found'':108B ''fsck'':105B ''git'':28B,86B,91B,99B,102B,104B ''kickstart'':113B ''launchctl'':112B ''lib/client.js'':110B ''list'':71B,101B ''list-sort'':70B ''listopts'':57B ''log'':92B ''lost'':107B ''lost-found'':106B ''no'':75B ''now'':55B ''p0/p1/p2'':45B ''pmboard'':4A,17B ''pnpm'':81B ''pop'':39B ''pop/apply'':89B ''reflog'':103B ''refs'':95B ''req'':9A,22B ''sort'':72B ''stash'':29B,37B,42B,61B,87B,100B ''state'':54B ''switch'':67B ''switch-view'':66B ''view'':68B ''view.ts'':79B ''view.ts/board-mount.ts/styles.ts'':78B ''w'':12A,25B ''w-1d'':11A ''w-1dd6aa57'':24B ''丢失'':7A,20B ''从'':60B ''代码