INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('31bd73ca-e097-4d89-9c7e-5027b78cc28c', '【工程纪律·跨进程契约的形状】REQ-9494f9（2026-09-21，w-f8006463）：s', '【工程纪律·跨进程契约的形状】REQ-9494f9（2026-09-21，w-f8006463）：solve-kit 的 buildNudgeMessage 曾返回纯字符串并直接喂给 agent.followup——followup 要的是 UserMessage 信封 {id,role,content,source}。字符串没有 id/source，造成两级故障：① 第二次入箱被 inbox 去重拒绝（message "undefined" is already pending）；② session-controller 的 Host 级 control stream 建基线遍历全部 session 读 message.source.kind 抛 TypeError → 所有浏览器窗口控制流一起失败。教训：同一包内「一份信封、一份字符串」两种形状并存是必然出事的信号；坏形状会写进持久化 event log，重启不恢复；修法=改回信封（与同文件 buildSolveMessage 逐字段同形）+ 回归测试先红后绿 + 反例断言防双重身退化成恒真。', 'experience', '{solve-kit,followup,agent-inbox,control-stream,形状纪律,REQ-9494f9}', NULL, '''-09'':7A,19B ''-21'':8A,20B ''2026'':6A,18B ''9494f9'':5A,17B ''agent.followup'':30B ''already'':48B ''buildnudgemessage'':28B ''buildsolvemessage'':77B ''content'':37B ''control'':56B ''controller'':52B ''event'':71B ''f8006463'':11A,23B ''followup'':31B ''host'':54B ''id'':35B ''id/source'':40B ''inbox'':43B ''is'':47B ''kit'':26B ''log'':72B ''message'':45B ''message.source.kind'':61B ''pending'':49B ''req'':4A,16B ''req-9494f9'':3A,15B ''role'':36B ''s'':12A ''session'':51B,59B ''session-controller'':50B ''solve'':25B ''solve-kit'':24B ''source'':38B ''stream'':57B ''typeerror'':63B ''undefined'':46B ''usermessage'':33B ''w'':10A,22B ''w-f8006463'':9A,21B ''一份信封'':67B ''一份字符串'':68B ''与同文件'':76B ''两种形状并存是必然出事的信号'':69B ''信封'':34B ''修法'':74B ''去重拒绝'':44B ''反例断言防双重身退化成恒真'':80B ''同一包内'':66B ''回归测试先红后绿'':79B ''坏形状会写进持久化'':70B ''字符串没有'':39B ''工程纪律'':1A,13B ''建基线遍历全部'':58B ''所有浏览器窗口控制流一起失败'':64B ''抛'':62B ''改回信封'':75B ''教训'':65B ''曾返回纯字符串并直接喂给'':29B ''的'':27B,53B ''第二次入箱被'':42B ''级'':55B ''要的是'':32B ''读'':60B ''跨进程契约的形状'':2A,14B ''逐字段同形'':78B ''造成两级故障'':41B ''重启不恢复'':73B', '2026-09-21 02:51:31.293185', '2026-09-21 02:51:31.293185', '{}');
