INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('ac6b6b3b-af12-4f4a-9aa6-ee47320e6aff', '【能力边缺陷·2026-09-16 定位】操纵检测（manipulation_detector）返回', '【能力边缺陷·2026-09-16 定位】操纵检测（manipulation_detector）返回『0 活跃操纵』是假阴性，不是市场事实。
