INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('f01b8ad6-5034-461e-b4a4-90f8f6e34847', '【弹框可用性·实测缺陷 w-41e7e4cd 2026-09-17】DSH 客户端 dsh-clie', '【弹框可用性·实测缺陷 w-41e7e4cd 2026-09-17】DSH 客户端 dsh-client-ui-user-questions 的提问卡片限高 max-height:min(60vh,520px)，且「问题详情与选项共享同一个内部滚动区」（其 README 原文）。若把长文（≥1000 字多段）塞进 ask_user_question 的 question 字段，选项会被挤到滚动区下方/视口之外，用户表现为「不能选择」并取消，工具层只报 the user cancelled ask_user_question——看起来像用户拒绝，实际是内容过长不可点。修法（纪律）：弹框只放选择题干与短选项标签，正文放对话消息里；题干≤200 字、选项 label≤40 字。同一纪律适用于自研 reqboard_accept_sheet 的逐项弹框（5 项/批，每项含验收标准，须防超长）。', 'experience', '{ask_user_question,弹框,UI缺陷,dsh-client-ui-user-questions,w-41e7e4cd}', NULL, '''-09'':7A,20B ''-17'':8A,21B ''1000'':43B ''200'':71B ''2026'':6A,19B ''40'':75B ''41e7e4cd'':5A,18B ''5'':82B ''520px'':36B ''60vh'':35B ''accept'':79B ''ask'':46B,61B ''cancelled'':60B ''clie'':13A ''client'':26B ''dsh'':9A,12A,22B,25B ''dsh-clie'':11A ''dsh-client-ui-user-questions'':24B ''height'':33B ''label'':74B ''max'':32B ''max-height'':31B ''min'':34B ''question'':48B,50B,63B ''questions'':29B ''readme'':40B ''reqboard'':78B ''sheet'':80B ''the'':58B ''ui'':27B ''user'':28B,47B,59B,62B ''w'':4A,17B ''w-41e7e4cd'':3A,16B ''不能选择'':55B ''且'':37B ''修法'':66B ''其'':39B ''原文'':41B ''同一纪律适用于自研'':77B ''塞进'':45B ''字'':72B,76B ''字多段'':44B ''字段'':51B ''实测缺陷'':2A,15B ''实际是内容过长不可点'':65B ''客户端'':10A,23B ''工具层只报'':57B ''并取消'':56B ''弹框只放选择题干与短选项标签'':68B ''弹框可用性'':1A,14B ''批'':84B ''正文放对话消息里'':69B ''每项含验收标准'':85B ''用户表现为'':54B ''的'':49B ''的提问卡片限高'':30B ''的逐项弹框'':81B ''看起来像用户拒绝'':64B ''纪律'':67B ''若把长文'':42B ''视口之外'':53B ''选项'':73B ''选项会被挤到滚动区下方'':52B ''问题详情与选项共享同一个内部滚动区'':38B ''项'':83B ''须防超长'':86B ''题干'':70B', '2026-09-17 19:23:05.688725', '2026-09-17 19:23:05.688725', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('c5a1cd3f-a1a4-4d5f-a45c-ec946af18d4c', '【REQ-2e9473 交付后缺陷 #3 · w-41e7e4cd 2026-09-17】reqbo', '【REQ-2e9473 交付后缺陷 #3 · w-41e7e4cd 2026-09-17】reqboard_decompose 的幂等守卫把"状态=decomposing"直接当成"已拆过"就拒绝，但 reqboard_ask_confirm(target=plan) 批准计划会**自动**把 planning→decomposing —— 于是正常路径必然先到 decomposing 再调 decompose，被自己的守卫拒死，且台账里 0 个任务。等于**所有新需求都无法拆分**，整条审批流水线自锁（本需求 REQ-47939a 首次使用即触发）。根因：状态守卫与"幽灵任务"防线职责重叠，而状态是**自动推进的产物**、不是"已拆分"的证据。正解：幽灵任务的唯一判据是"该需求已有未取消任务"（防线②已经覆盖）；状态守卫只应区分"是否已**越过**拆分"（implementing/accepting）。教训（可推广）：**当某个状态会被系统自动推进放到 X 时，任何"看到 X 就拒绝"的守卫都要重新审一遍——它挡住的可能正是系统自己刚推过来的正常流。** 已修 + 回归用例（decompose-tools.test.ts 28/28）+ 合并 main。', 'experience', '{REQ-2e9473,decompose,幂等守卫,状态机自动推进,自锁,回归测试,w-41e7e4cd}', NULL, '''-09'':10A,22B ''-17'':11A,23B ''0'':49B ''2026'':9A,21B ''28/28'':92B ''2e9473'':3A,15B ''3'':5A,17B ''41e7e4cd'':8A,20B ''47939a'':57B ''ask'':34B ''confirm'':35B ''decompose'':25B,46B ''decompose-tools.test.ts'':91B ''decomposing'':28B,42B,44B ''implementing/accepting'':77B ''main'':94B ''plan'':37B ''planning'':41B ''req'':2A,14B,56B ''req-2e9473'':1A,13B ''req-47939a'':55B ''reqbo'':12A ''reqboard'':24B,33B ''target'':36B ''w'':7A,19B ''w-41e7e4cd'':6A,18B ''x'':81B,85B ''不是'':65B ''且台账里'':48B ''个任务'':50B ''于是正常路径必然先到'':43B ''交付后缺陷'':4A,16B ''任何'':83B ''但'':32B ''再调'':45B ''可推广'':79B ''合并'':93B ''回归用例'':90B ''它挡住的可能正是系统自己刚推过来的正常流'':88B ''就拒绝'':31B,86B ''已修'':89B ''已拆分'':66B ''已拆过'':30B ''已经覆盖'':72B ''幽灵任务'':61B ''幽灵任务的唯一判据是'':69B ''当某个状态会被系统自动推进放到'':80B ''所有新需求都无法拆分'':52B ''批准计划会'':38B ''把'':40B ''拆分'':76B ''教训'':78B ''整条审批流水线自锁'':53B ''时'':82B ''是否已'':74B ''本需求'':54B ''根因'':59B ''正解'':68B ''状态'':27B ''状态守卫与'':60B ''状态守卫只应区分'':73B ''的守卫都要重新审一遍'':87B ''的幂等守卫把'':26B ''的证据'':67B ''直接当成'':29B ''看到'':84B ''等于'':51B ''而状态是'':63B ''自动'':39B ''自动推进的产物'':64B ''被自己的守卫拒死'':47B ''该需求已有未取消任务'':70B ''越过'':75B ''防线'':71B ''防线职责重叠'':62B ''首次使用即触发'