INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('26af5029-261e-4804-a537-76f9f9dda56c', '【REQ-47939a t10 前置 · w-41e7e4cd 2026-09-17】已冻结 v4 ', '【REQ-47939a t10 前置 · w-41e7e4cd 2026-09-17】已冻结 v4 台账样本到 packages/pages/dsh-pmboard/tests/fixtures/ledger-v4-sample.json（= 当时 .dsh-data/dsh-reqboard.json 的副本）。为什么现在冻：t10（账本 v4→v5 迁移）的测试需要**稳定可复现**的输入，而运行中的台账每个需求推进都会变（本需求自己就在推进），晚冻就等于没有基准。设计文档 design/migration.md §1 里记的"34 需求/84 任务"是冻结点，实际样本数字见 fixtures 与迁移报告，两者不一致时以样本为准（文档数字是当日实测快照，不是约束）。', 'knowledge', '{REQ-47939a,t10,迁移,fixture,v4台账,w-41e7e4cd}', NULL, '''-09'':10A,23B ''-17'':11A,24B ''/84'':53B ''/dsh-reqboard.json'':33B ''1'':49B ''2026'':9A,22B ''34'':51B ''41e7e4cd'':8A,21B ''47939a'':3A,16B ''data'':32B ''design/migration.md'':48B ''dsh'':31B ''dsh-data'':30B ''fixtures'':57B ''packages/pages/dsh-pmboard/tests/fixtures/ledger-v4-sample.json'':28B ''req'':2A,15B ''req-47939a'':1A,14B ''t10'':4A,17B,36B ''v4'':13A,26B,38B ''v5'':39B ''w'':7A,20B ''w-41e7e4cd'':6A,19B ''不是约束'':61B ''与迁移报告'':58B ''两者不一致时以样本为准'':59B ''为什么现在冻'':35B ''任务'':54B ''前置'':5A,18B ''台账样本到'':27B ''实际样本数字见'':56B ''已冻结'':12A,25B ''当时'':29B ''文档数字是当日实测快照'':60B ''是冻结点'':55B ''晚冻就等于没有基准'':46B ''本需求自己就在推进'':45B ''的副本'':34B ''的测试需要'':41B ''的输入'':43B ''稳定可复现'':42B ''而运行中的台账每个需求推进都会变'':44B ''设计文档'':47B ''账本'':37B ''迁移'':40B ''里记的'':50B ''需求'':52B', '2026-09-17 19:48:53.982338', '2026-09-17 19:48:53.982338', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('e082b8a2-0142-455c-9de9-b5641858a75f', '【REQ-47939a D-7 · 用户裁定 2026-09-17 · w-41e7e4cd】验收单', '【REQ-47939a D-7 · 用户裁定 2026-09-17 · w-41e7e4cd】验收单返工续版语义修复：原实现 buildSheet 只带上一版 **failed** 项，**pending（未裁决）项被静默丢弃**（只留 sheetHistory）。极端路径：v1 = failed + pending → 打回返工 → v2 只含 failed → 修好后 v2 全过 → isAllPassed 成立 → 需求归档，而那些 pending 项**从未被裁决过**——"逐项验收"这道人工门形同虚设。修法：carried = prevItems.filter(failed || pending)，顺序沿用上一版；同时**保住**另一条既有语义"上一版无 failed → 重新生成全新验收单（不进入续版）"并加守卫用例。用户选"本轮顺带修"（另两选项：只登记不改 / 认为现状正确改文档口径）。教训（可推广）：**"只带失败项"这类续版语义要问一句——没被处理过的项去哪了？凡是"上一版存在但新一版不出现"的字段，都要确认它是"已完成"还是"被丢弃"。**', 'experience', '{REQ-47939a,验收单,续版,pending丢失,人工门,D-7,w-41e7e4cd}', NULL, '''-09'':8A,21B ''-17'':9A,22B ''-7'':5A,18B ''2026'':7A,20B ''41e7e4cd'':12A,25B ''47939a'':3A,16B ''buildsheet'':28B ''carried'':58B ''d'':4A,17B ''failed'':30B,39B,44B,60B,67B ''isallpassed'':48B ''pending'':32B,40B,52B,61B ''previtems.filter'':59B ''req'':2A,15B ''req-47939a'':1A,14B ''sheethistory'':36B ''v1'':38B ''v2'':42B,46B ''w'':11A,24B ''w-41e7e4cd'':10A,23B ''上一版存在但新一版不出现'':82B ''上一版无'':66B ''不进入续版'':69B ''从未被裁决过'':54B ''保住'':64B ''修好后'':45B ''修法'':57B ''全过'':47B ''凡是'':81B ''原实现'':27B ''另一条既有语义'':65B ''另两选项'':73B ''只含'':43B ''只带上一版'':29B ''只带失败项'':78B ''只留'':35B ''只登记不改'':74B ''可推广'':77B ''同时'':63B ''已完成'':85B ''并加守卫用例'':70B ''成立'':49B ''打回返工'':41B ''教训'':76B ''未裁决'':33B ''本轮顺带修'':72B ''极端路径'':37B ''没被处理过的项去哪了'':80B ''用户裁定'':6A,19B ''用户选'':71B ''的字段'':83B ''而那些'':51B ''被丢弃'':87B ''认为现状正确改文档口径'':75B ''还是'':86B ''这类续版语义要问一句'':79B ''这道人工门形同虚设'':56B ''逐项验收'':55B ''都要确认它是'':84B ''重新生成全新验收单'':68B ''需求归档'':50B ''项'':31B,53B ''项被静默丢弃'':34B ''顺序沿用上一版'':62B ''验收单'':13A ''验收单返工续版语义修复'':26B', '2026-09-17 20:05:50.331625', '2026-09-17 20:05:50.331625', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('c8624640-9bc9-4370-9ac4-18021900a725', '【REQ-47939a D-8 · w-41e7e4cd 2026-09-17】t10 迁移脚本形态', '【REQ-47939a D-8 · w-41e7e4cd 2026-09-17】t10 迁移脚本形态裁定：卡面写"纯 .mjs 不依赖 tsx"，但同一份卡要求"statusHistory 补齐复用 backfill 算法"——两者不可兼得（backfill/parseTransitionTarget 是 TS 实现，纯 mjs 只能重抄 = 第二套时间线语义）。裁定用 .ts + node --import tsx/esm，直接 import 运行时同一实现；"不依赖 tsx"按其目的（停机也能跑）作废、不按字面执行。可推广的教训：**验收标准里出现"复用 X 实现"与"不依赖 X 的运行环境"这类组合时，先验证它们能否同时成立**——否则开工时只有两条错路：重写一份（语义分叉）或违反卡面（偷偷绕开）。', 'experience', '{REQ-47939a,t10,迁移,卡面矛盾,backfill,tsx,D-8}', NULL, '''-09'':10A,23B ''-17'':11A,24B ''-8'':5A,18B ''2026'':9A,22B ''41e7e4cd'':8A,21B ''47939a'':3A,16B ''backfill'':35B ''backfill/parsetransitiontarget'':38B ''d'':4A,17B ''import'':49B,52B ''mjs'':29B,43B ''node'':48B ''req'':2A,15B ''req-47939a'':1A,14B ''statushistory'':33B ''t10'':12A,25B ''ts'':40B,47B ''tsx'':31B,55B ''tsx/esm'':50B ''w'':7A,20B ''w-41e7e4cd'':6A,19B ''x'':63B,67B ''不依赖'':30B,54B,66B ''不按字面执行'':59B ''与'':65B ''两者不可兼得'':37B ''但同一份卡要求'':32B ''作废'':58B ''停机也能跑'':57B ''偷偷绕开'':75B ''先验证它们能否同时成立'':70B ''卡面写'':27B ''只能重抄'':44B ''可推广的教训'':60B ''否则开工时只有两条错路'':71B ''复用'':62B ''实现'':41B,64B ''或违反卡面'':74B ''按其目的'':56B ''是'':39B ''的运行环境'':68B ''直接'':51B ''第二套时间线语义'':45B ''算法'':36B ''纯'':28B,42B ''补齐复用'':34B ''裁定用'':46B ''语义分叉'':73B ''迁移脚本形态'':13A ''迁移脚本形态裁定'':26B ''运行时同一实现'':53B ''这类组合时'':69B ''重写一份'':72B ''验收标准里出现'':61B', '2026-09-17 20:08:53.289228', '2026-09-17 20:08:53.289228', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('fa0cde18-79bd-4e94-90e5-ef409c85e186', '【第 5 次"门禁失效而假绿" · REQ-47939a t7 复核 · w-41e7e4cd 20', '【第 5 次"门禁失效而假绿" · REQ-47939a t7 复核 · w-41e7e4cd 2026-09-17】层边界门禁只匹配 `===`，于是 `src/http/` 里 8 处 `status !== ''accepting''`、25 处 `statusIs(x, ''accepting'')` 全部漏过——门禁绿灯只是因为它没看。教训升级版：① **门禁要覆盖算子的所有形态**（`===`/`!==`/`==`/`!=`），只写 `===` 等于只查了一半；② 更要命的是"绕过形态"——把 `statusIs(x, ''accepting'')` 这类**通用比较器**放进 domain，只是搬走了运算符、规则仍留在适配层，门禁若不查"实参里的字面量"就会继续假绿；③ 最终口径应是最简单粗暴的那条：**适配层不得出现任何独立的状态名字面量**（名单从 domain 表动态取，手抄名单会漂移——我的第一版探针就漏了 `in_progress`）；④ 修完必须**故障注入**：注入原洞形态能变红，才算真修。同类前四次：契约扫描器漏条件展开字段、契约测试只测拒绝路径、层边界扫描器无命中下限断言、memory 召回注入率 7%。', 'experience', '{门禁,假绿,层边界,状态机械,故障注入,REQ-47939a,w-41e7e4cd}', NULL, '''-09'':27B ''-17'':28B ''20'':13A ''2026'':26B ''25'':37B ''41e7e4cd'':12A,25B ''47939a'':7A,20B ''5'':2A,15B ''7'':82B ''8'':33B ''accepting'':36B,41B,53B ''domain'':57B,66B ''in'':70B ''memory'':80B ''progress'':71B ''req'':6A,19B ''req-47939a'':5A,18B ''src/http'':31B ''status'':35B ''statusis'':39B,51B ''t7'':8A,21B ''w'':11A,24B ''w-41e7e4cd'':10A,23B ''x'':40B,52B ''于是'':30B ''修完必须'':72B ''全部漏过'':42B ''只写'':46B ''只是搬走了运算符'':58B ''召回注入率'':81B ''同类前四次'':76B ''名单从'':65B ''处'':34B,38B ''复核'':9A,22B ''契约扫描器漏条件展开字段'':77B ''契约测试只测拒绝路径'':78B ''实参里的字面量'':61B ''就会继续假绿'':62B ''层边界扫描器无命中下限断言'':79B ''层边界门禁只匹配'':29B ''我的第一版探针就漏了'':69B ''手抄名单会漂移'':68B ''才算真修'':75B ''把'':50B ''放进'':56B ''故障注入'':73B ''教训升级版'':44B ''更要命的是'':48B ''最终口径应是最简单粗暴的那条'':63B ''次'':3A,16B ''注入原洞形态能变红'':74B ''第'':1A,14B ''等于只查了一半'':47B ''绕过形态'':49B ''表动态取'':67B ''规则仍留在适配层'':59B ''这类'':54B ''适配层不得出现任何独立的状态名字面量'':64B ''通用比较器'':55B ''里'':32B ''门禁失效而假绿'':4A,17B ''门禁绿灯只是因为它没看'':43B ''门禁若不查'':60B ''门禁要覆盖算子的所有形态'':45B', '2026-09-17 20:26:24.059107', '2026-09-17 20:26:24.059107', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('646ae53a-9407-4349-b522-184582ffb6bf', '【教训 · REQ-47939a 收尾 · w-41e7e4cd 2026-09-17】我在自修复重', '【教训 · REQ-47939a 收尾 · w-41e7e4cd 2026-09-17】我在自修复重启理由里写下了一句**未经验证的成功声明**："真实台账已执行 v4→v5 迁移（--apply 白名单外 0 条 + --verify 通过）"——实际命令以 ERR_MODULE_NOT_FOUND 失败（从仓库根执行时 tsx/esm 解析不到；正确做法：cd agent-dh + 包内相对路径）。危险两层：① 后来者读到会以为台账已是 v5 而跳过迁移；② 掩盖了真实机制——新代码 load() 用常量重建内存 schemaVersion=5，于是"不迁移 + 任意写盘"会产出**自称 v5 却含 v4 内容**的台账，比不迁移更糟。可推广纪律：**持久留痕（重启理由/任务汇报/验收材料）里的"已完成"必须是刚亲手跑过的命令输出，不能是意图或预期。**', 'experience', '{诚实留痕,自述不可信,迁移,tsx解析,重启理由,REQ-47939a,w-41e7e4cd}', NULL, '''-09'':10A,22B ''-17'':11A,23B ''0'':32B ''2026'':9A,21B ''41e7e4cd'':8A,20B ''47939a'':4A,16B ''5'':60B ''agent'':48B ''agent-dh'':47B ''apply'':30B ''cd'':46B ''dh'':49B ''err'':37B ''found'':40B ''load'':57B ''module'':38B ''not'':39B ''req'':3A,15B ''req-47939a'':2A,14B ''schemaversion'':59B ''tsx/esm'':43B ''v4'':27B,68B ''v5'':28B,53B,66B ''verify'':34B ''w'':7A,19B ''w-41e7e4cd'':6A,18B ''不能是意图或预期'':80B ''不迁移'':62B ''于是'':61B ''从仓库根执行时'':42B ''任务汇报'':75B ''任意写盘'':63B ''会产出'':64B ''内容'':69B ''包内相对路径'':50B ''危险两层'':51B ''却含'':67B ''可推广纪律'':72B ''后来者读到会以为台账已是'':52B ''失败'':41B ''实际命令以'':36B ''已完成'':78B ''必须是刚亲手跑过的命令输出'':79B ''我在自修复重'':12A ''我在自修复重启理由里写下了一句'':24B ''持久留痕'':73B ''掩盖了真实机制'':55B ''收尾'':5A,17B ''教训'':1A,13B ''新代码'':56B ''未经验证的成功声明'':25B ''条'':33B ''正确做法'':45B ''比不迁移更糟'':71B ''用常量重建内存'':58B ''白名单外'':31B ''的台账'':70B ''真实台账已执行'':26B ''而跳过迁移'':54B ''自称'':65B ''解析不到'':44B ''迁移'':29B ''通过'':35B ''里的'':77B ''重启理由'':74B ''验收材料'':76B', '2026-09-17 20:56:13.691435', '2026-09-17 20:56:13.691435', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('8efd734f-cdfe-48dc-8b1a-2e245dcbcac4', '【两条仓库卫生发现 · REQ-47939a 收尾 · w-41e7e4cd 2026-09-17】', '【两条仓库卫生发现 · REQ-47939a 收尾 · w-41e7e4cd 2026-09-17】① **测试残留被提交进仓**：agent-dh/packages/pages/dsh-pmboard/docs/requirements/ 下有 **3144 个已跟踪文件**（REQ-abc123/REQ-w7test/REQ-00ea6c… 的 decomposition.md 与 tasks/*.md），是测试用例以包目录为 cwd 跑时写出的产物（测试写相对路径 docs/requirements/REQ-xxx）——它们既不是交付物也不该进版本库，且会污染 grep/"谁引用了谁"的判定（我自己就被它骗过一次假引用）。建议后续独立小卡：让相关测试在临时目录里跑或把该路径 gitignore + 清理已提交部分；**不要**在没有独立任务时顺手删（我先误删了 3144 个并已 git checkout 全部还原，净改动 0）。② **持久留痕里的状态断言必须来自刚跑过的命令**：我在一次自修复重启理由里写了"台账已迁移并 verify 通过"，而那条命令其实因 ERR_MODULE_NOT_FOUND 失败——这类未经验证的"已完成"会骗过后来者（详见 verification.md 的诚实纠正段）。', 'experience', '{仓库卫生,测试残留,git跟踪,留痕纪律,REQ-47939a,w-41e7e4cd}', NULL, '''-09'':10A,21B ''-17'':11A,22B ''/packages/pages/dsh-pmboard/docs/requirements'':27B ''/req-w7test/req-00ea6c'':34B ''0'':64B ''2026'':9A,20B ''3144'':29B,58B ''41e7e4cd'':8A,19B ''47939a'':4A,15B ''abc123'':33B ''agent'':25B ''agent-dh'':24B ''checkout'':61B ''cwd'':41B ''decomposition.md'':36B ''dh'':26B ''docs/requirements/req-xxx'':44B ''err'':71B ''found'':74B ''git'':60B ''gitignore'':53B ''grep'':47B ''md'':39B ''module'':72B ''not'':73B ''req'':3A,14B,32B ''req-47939a'':2A,13B ''req-abc123'':31B ''tasks'':38B ''verification.md'':80B ''verify'':68B ''w'':7A,18B ''w-41e7e4cd'':6A,17B ''下有'':28B ''不要'':55B ''与'':37B ''且会污染'':46B ''两条仓库卫生发现'':1A,12B ''个已跟踪文件'':30B ''个并已'':59B ''会骗过后来者'':78B ''全部还原'':62B ''净改动'':63B ''台账已迁移并'':67B ''在没有独立任务时顺手删'':56B ''失败'':75B ''它们既不是交付物也不该进版本库'':45B ''已完成'':77B ''建议后续独立小卡'':51B ''我先误删了'':57B ''我在一次自修复重启理由里写了'':66B ''我自己就被它骗过一次假引用'':50B ''持久留痕里的状态断言必须来自刚跑过的命令'':65B ''收尾'':5A,16B ''是测试用例以包目录为'':40B ''测试写相对路径'':43B ''测试残留被提交进仓'':23B ''清理已提交部分'':54B ''的'':35B ''的判定'':49B ''的诚实纠正段'':81B ''而那条命令其实因'':70B ''让相关测试在临时目录里跑或把该路径'':52B ''详见'':79B ''谁引用了谁'':48B ''跑时写出的产物'':42B ''这类未经验证的'':76B ''通过'':69B', '2026-09-17 20:57:14.216811', '2026-09-17 20:57:14.216811', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('ca748442-b192-4ebc-a39d-d4ceb82f8bd8', '【重大教训 · REQ-47939a · w-41e7e4cd 2026-09-17】用户观测"会话', '【重大教训 · REQ-47939a · w-41e7e4cd 2026-09-17】用户观测"会话框流程节点不展示"，根因是我自己的重构：src/http/routers/stages.ts 引用了两个**不存在的符号**——OPEN_STATUSES（状态集合被搬去 application/internal/window.ts 并改名 OPEN_REQ_STATUSES）与 TASK_ORDER（从未定义）→ GET /session/:id/progress 运行时 ReferenceError → HTTP 500。**为什么没被拦住（三个门都漏）**：① 该接口**零测试覆盖**（重构盲区）；② **没有类型检查门禁**——tsx 剥类型、vitest 不跑 tsc、本包还没有 tsconfig.json，所以"引用不存在的名字"这种 TS2304 能一路到线上（实测 host 侧 150 个真错误：91 参数类型 / 47 可能 undefined / 5 属性不存在；另有约 1000 个搬迁遗留的未用 import）；③ 我把注意力放在"既有测试全绿"上，而既有测试不覆盖这个接口。纪律：**"既有测试全绿"不等于"没坏"；重构后必须补 (a) tsc 类型门禁、(b) 被改动路径的接口级冒烟**。已修：把"进行中"判据与任务状态展示顺序单点进 domain（isOpenRequirement / TASK_STATUS_ORDER），补 tests/session-progress.test.ts（该测试立刻又抓出第二个同类符号 TASK_ORDER），host 侧 TS2304 归零，真机接口验证 200。', 'experience', '{回归,类型门禁缺失,TS2304,零覆盖接口,重构盲区,REQ-47939a,w-41e7e4cd}', NULL, '''-09'':9A,21B ''-17'':10A,22B ''/session'':42B ''1000'':79B ''150'':69B ''200'':115B ''2026'':8A,20B ''41e7e4cd'':7A,19B ''47'':73B ''47939a'':4A,16B ''5'':76B ''500'':47B ''91'':71B ''a'':91B ''application/internal/window.ts'':32B ''b'':94B ''domain'':100B ''get'':41B ''host'':67B,110B ''http'':46B ''id/progress'':43B ''import'':81B ''isopenrequirement'':101B ''open'':29B,34B ''order'':39B,104B,109B ''referenceerror'':45B ''req'':3A,15B,35B ''req-47939a'':2A,14B ''src/http/routers/stages.ts'':26B ''status'':103B ''statuses'':30B,36B ''task'':38B,102B,108B ''tests/session-progress.test.ts'':106B ''ts2304'':64B,112B ''tsc'':58B,92B ''tsconfig.json'':60B ''tsx'':54B ''undefined'':75B ''vitest'':56B ''w'':6A,18B ''w-41e7e4cd'':5A,17B ''三个门都漏'':49B ''上'':84B ''不存在的符号'':28B ''不等于'':88B ''不跑'':57B ''与'':37B ''个搬迁遗留的未用'':80B ''个真错误'':70B ''为什么没被拦住'':48B ''从未定义'':40B ''会话'':12A ''会话框流程节点不展示'':24B ''侧'':68B,111B ''判据与任务状态展示顺序单点进'':99B ''剥类型'':55B ''参数类型'':72B ''另有约'':78B ''可能'':74B ''实测'':66B ''属性不存在'':77B ''已修'':96B ''并改名'':33B ''引用不存在的名字'':62B ''引用了两个'':27B ''归零'':113B ''我把注意力放在'':82B ''所以'':61B ''把'':97B ''既有测试全绿'':83B,87B ''本包还没有'':59B ''根因是我自己的重构'':25B ''没坏'':89B ''没有类型检查门禁'':53B ''状态集合被搬去'':31B ''用户观测'':11A,23B ''真机接口验证'':114B ''类型门禁'':93B ''纪律'':86B ''而既有测试不覆盖这个接口'':85B ''能一路到线上'':65B ''补'':105B ''被改动路径的接口级冒烟'':95B ''该接口'':50B ''该测试立刻又抓出第二个同类符号'':107B ''运行时'':44B ''这种'':63B ''进行中'':98B ''重大教训'':1A,13B ''重构后必须补'':90B ''重构盲区'':52B ''零测试覆盖'':51B', '2026-09-17 21:11:54.156093', '2026-09-17 21:11:54.156093', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('bcddce00-51ec-4cc2-8408-4eed680f3dfa', '【v2 事件处置 · pool_changed · 2026-09-17 23:00:04（inve', '【v2 事件处置 · pool_changed · 2026-09-17 23:00:04（investor-session-79b53b68-8e09-456e-9e49-9eff5ca44cef）】

【事件】quantsys-v2 推送 pool_changed（trade_date=2026-09-17，事件内 account=**agent_virtual**）：
- pool 35「全市场候选池_v1」(dynamic)：+9（002049/002074/002371/300454/300661/600031/601899/688012/688256），−9（002600/002916/300223/600741/600803/688041/688065/688617/689009）
- pool 27「通杀型策略候选池」：+7（001965/300285/300454/300661/300750/601127/603296），−7（002466/002600/002648/300037/600741/688120/688795）

【结论：机械换血 → 零动作（不交易、不通知、不建 watch）】依据四条：
1. **R-012 明文**：动态规则池（pool 35 pool_type=dynamic）成员换血属**正常**，不打扰用户；pool_list 确认 pool 35「全市场候选池_v1」last_refreshed_at=2026-09-17 23:00:00，即本次事件就是该池的例行 refresh 产物。
2. **无持仓交集**：agent_brain 唯一持仓 002007 华兰生物（1100 股，可卖 1100，成本 13.27 现价 12.75，−3.95%；position_list 2026-09-17T23:03）**不在**任一 pool 的增删名单中；两池被移除的 16 只标的也**均非本账户持仓** ⇒ 无止损/减仓触发、无需调仓。
3. **账户边界（R-019）**：事件 account=agent_virtual = agent-ts（fin-agent）的账户，agent-dh **只读不写**；该池变动**不是**我的交易信号源，不得据此在 agent_brain 下单。account_list 复核（2026-09-17T23:03）：agent_virtual 独立在册（type=agent，累计收益 +4.58%，2 持仓），默认账户仍是 agent_brain（工具层 DEFAULT_AGENT_ACCOUNT）。
