INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('46d1194e-c2ed-465c-83ab-42c800902043', '600887 neutral 2026-09-18 08:47 为 600887 伊利股份挂条件触发型 A 级信号规则 #191（price<25.5 进买区，', '600887 交易经验（2026-09-18T10:31:45.613Z）
