INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('170bd19a-edb1-4a8d-be75-5852af20eb36', '601888 neutral v2 watch_triggered 事件自带"A级候选·13战全胜/30战30胜"标签（源自 swing_points ZigZ', '601888 交易经验（2026-09-18T08:52:28.283Z）
