INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('44e65050-d003-4a50-bc35-64c26009a00f', '002080 neutral 09-17 14:00 预案对玻纤链 002080 设唯一可介入形态"回踩 55.88 缩量企稳"；09-18 竞价以涨停 64.', '002080 交易经验（2026-09-18T08:52:28.304Z）
