INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('57dac24f-40e3-4b50-9d18-22345600d005', 'reqboard 任务结单的两个真实门槛（2026-09-18 实测，REQ-d3e61a T-1）', 'reqboard 任务结单的两个真实门槛（2026-09-18 实测，REQ-d3e61a T-1）：①【路径约定】dsh-pmboard 的 DocRepository 相对路径以 agent-dh/ 为工作区根（证据：support.ts 用 docs.stat("packages/pages/<pkg>/lib/client.js")），不是 repo 根。task_report 的 files_changed 写 "agent-dh/docs/..." 会带错前缀 → done 凭证门判定"改动文件不存在" → REQBOARD_NO_EVIDENCE 拒绝结单；正确写法是 "docs/..."。②【凭证门双路】DoneEvidenceSpec：弱信号=开工以来有 edit/write/bash/run_code 工具痕迹（reqboard_* 台账动作不算）；强信号=声明文件真实存在且 mtime ≥ 开工时间。两路都不过即拒（25ms 速通拦截）。规避：先 reqboard_task_move(to=in_progress) 认领，再干活（真改文件），最后 report + 逐级推进 testing→in_review→done。', 'experience', '{reqboard,done凭证门,REQBOARD_NO_EVIDENCE,路径约定,dsh-pmboard}', NULL, '''-09'':4A,15B ''-1'':11A,22B ''-18'':5A,16B ''/docs'':52B ''/lib/client.js'':39B ''2026'':3A,14B ''25ms'':76B ''agent'':31B,50B ''agent-dh'':30B,49B ''changed'':47B ''d3e61a'':9A,20B ''dh'':32B,51B ''docrepository'':28B ''docs'':62B ''docs.stat'':37B ''done'':54B,95B ''doneevidencespec'':64B ''dsh'':25B ''dsh-pmboard'':24B ''edit/write/bash/run_code'':67B ''evidence'':59B ''files'':46B ''in'':84B,93B ''move'':82B ''mtime'':73B ''no'':58B ''packages/pages'':38B ''pmboard'':26B ''progress'':85B ''repo'':41B ''report'':44B,90B ''req'':8A,19B ''req-d3e61a'':7A,18B ''reqboard'':1A,12B,57B,69B,80B ''review'':94B ''support.ts'':35B ''t'':10A,21B ''task'':43B,81B ''testing'':92B ''to'':83B ''不是'':40B ''两路都不过即拒'':75B ''为工作区根'':33B ''任务结单的两个真实门槛'':2A,13B ''会带错前缀'':53B ''先'':79B ''再干活'':87B ''写'':48B ''凭证门判定'':55B ''凭证门双路'':63B ''台账动作不算'':70B ''声明文件真实存在且'':72B ''实测'':6A,17B ''工具痕迹'':68B ''开工以来有'':66B ''开工时间'':74B ''弱信号'':65B ''强信号'':71B ''拒绝结单'':60B ''改动文件不存在'':56B ''最后'':89B ''根'':42B ''正确写法是'':61B ''用'':36B ''的'':27B,45B ''相对路径以'':29B ''真改文件'':88B ''规避'':78B ''认领'':86B ''证据'':34B ''路径约定'':23B ''逐级推进'':91B ''速通拦截'':77B', '2026-09-18 21:33:26.117577', 