INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('76433634-f2e3-4bed-831e-57ab146cdd11', 'REQ-d3e61a neutral reqboard 任务 T-1（doc 相位）完工后结单：先 report 再 task_move(to=done)', 'REQ-d3e61a 交易经验（2026-09-18T13:33:26.120Z）
