INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('0cf8946e-be7a-4ed4-90d2-0cd40750dab8', '2026-09-18 实测：agent-dh 的 dsh-pmboard 包处于**多窗口共享脏树*', '2026-09-18 实测：agent-dh 的 dsh-pmboard 包处于**多窗口共享脏树**状态（542 个未提交改动 = 507 未跟踪 + 34 修改；当前分支被切回 main @ a3a3b296）。另一窗口在改 MoveRequirement.ts / MoveTask.ts / ReportTask.ts / ports.ts / support.ts / protocol.ts / index.ts（即门禁调用点与协议层），但**未碰 artifact-gates.ts / router.ts**。结论：纯新增文件（零 import）可在共享树安全开工；全量测试中的失败须逐条归因——判据是"全仓有无文件引用我的模块"+"tsc 错误是否落在我的文件"，不要用"总数变多"当结论。', 'experience', '{多窗口协作,脏工作树,dsh-pmboard,失败归因,REQ-d3e61a}', NULL, '''-09'':2A,15B ''-18'':3A,16B ''2026'':1A,14B ''34'':32B ''507'':30B ''542'':28B ''a3a3b296'':36B ''agent'':6A,19B ''agent-dh'':5A,18B ''artifact-gates.ts'':48B ''dh'':7A,20B ''dsh'':10A,23B ''dsh-pmboard'':9A,22B ''import'':53B ''index.ts'':44B ''main'':35B ''moverequirement.ts'':38B ''movetask.ts'':39B ''pmboard'':11A,24B ''ports.ts'':41B ''protocol.ts'':43B ''reporttask.ts'':40B ''router.ts'':49B ''support.ts'':42B ''tsc'':58B ''不要用'':60B ''个未提交改动'':29B ''但'':46B ''修改'':33B ''全仓有无文件引用我的模块'':57B ''全量测试中的失败须逐条归因'':55B ''判据是'':56B ''包处于'':12A,25B ''即门禁调用点与协议层'':45B ''另一窗口在改'':37B ''可在共享树安全开工'':54B ''多窗口共享脏树'':13A,26B ''实测'':4A,17B ''当前分支被切回'':34B ''当结论'':62B ''总数变多'':61B ''未碰'':47B ''未跟踪'':31B ''状态'':27B ''的'':8A,21B ''纯新增文件'':51B ''结论'':50B ''错误是否落在我的文件'':59B ''零'':52B', '2026-09-18 21:39:03.064365', '2026-09-18 21:39:03.064365', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('92c772fd-705d-4d40-96fe-8a0f6b54ad10', 'dsh-pmboard 域层（src/domain/**）有硬门禁：**禁止字符串拼接**（+ 号）', 'dsh-pmboard 域层（src/domain/**）有硬门禁：**禁止字符串拼接**（+ 号），消息必须走 fmt() 抽象（src/domain/text/fmt.ts，模板 {name} + vars）。tests/message-hygiene.test.ts 要求 domain 层拼接数为 0，新增 domain 文件时若用 + 拼串会立刻变红（2026-09-18 实测：difficulty-inference.ts 6 处被点名）。另：该文件还含棘轮约束「application/adapters/tools/http/client/shared 不得超过基线只降不升」，基线为一固定表。写 domain 层代码第一件事：import { fmt } from ''../text/fmt.js''（相对 domain/text）。', 'experience', '{dsh-pmboard,domain层,fmt,message-hygiene,门禁,REQ-d3e61a}', NULL, '''-09'':34B ''-18'':35B ''/text/fmt.js'':51B ''0'':28B ''2026'':33B ''6'':38B ''application/adapters/tools/http/client/shared'':42B ''difficulty-inference.ts'':37B ''domain'':26B,30B,46B ''domain/text'':53B ''dsh'':2A,10B ''dsh-pmboard'':1A,9B ''fmt'':18B,49B ''from'':50B ''import'':48B ''name'':22B ''pmboard'':3A,11B ''src/domain'':5A,13B ''src/domain/text/fmt.ts'':20B ''tests/message-hygiene.test.ts'':24B ''vars'':23B ''不得超过基线只降不升'':43B ''写'':45B ''另'':40B ''号'':8A,16B ''域层'':4A,12B ''基线为一固定表'':44B ''处被点名'':39B ''实测'':36B ''层代码第一件事'':47B ''层拼接数为'':27B ''抽象'':19B ''拼串会立刻变红'':32B ''文件时若用'':31B ''新增'':29B ''有硬门禁'':6A,14B ''模板'':21B ''消息必须走'':17B ''相对'':52B ''禁止字符串拼接'':7A,15B ''要求'':25B ''该文件还含棘轮约束'':41B', '2026-09-18 21:51:02.167116', '2026-09-18 21:51:02.167116', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('0aa69934-c025-4cc7-99d0-3949b80504d3', '硬门禁设计的铁律（2026-09-18 实测，REQ-d3e61a T-9 三轮回退的结论）：**没', '硬门禁设计的铁律（2026-09-18 实测，REQ-d3e61a T-9 三轮回退的结论）：**没有"修复通道"的硬门禁会锁死流水线**。T-9 想在验收期硬拦"验收项没写怎么验"，遇到三堵墙：① 10 个既有测试文件直接种占位 acceptance（"验收标准 1"）绕过计划校验；② 部分夹具的弱 acceptance（"单测绿"/"截图可见"）过了计划期锚点却不可操作 → 被硬拦；③ **断言本身锁死了夹具文本**（decompose-tools.test.ts:180 `expect(...).toEqual([''单测绿'', ''截图可见''])`）→ 改夹具必然改断言 = 改测试迁就实现。且任务 acceptance 落库后**没有修订通道**（decompose 有幂等守卫，无法重拆）。结论：加严门禁前必须先确认 ① 存量豁免语义 ② 被拦对象有无修复路径 ③ 既有测试是否把被测文本写进了断言。三者缺一，硬门禁就会从"质量闸门"变成"流程死锁"。', 'experience', '{门禁设计,硬拦风险,死锁,存量豁免,REQ-d3e61a,T-9}', NULL, '''-09'':3A,15B ''-18'':4A,16B ''-9'':10A,22B,28B ''1'':36B ''10'':32B ''2026'':2A,14B ''acceptance'':34B,39B,53B ''d3e61a'':8A,20B ''decompose'':56B ''decompose-tools.test.ts:180'':45B ''expect'':46B ''req'':7A,19B ''req-d3e61a'':6A,18B ''t'':9A,21B,27B ''toequal'':47B ''三者缺一'':64B ''三轮回退的结论'':11A,23B ''且任务'':52B ''个既有测试文件直接种占位'':33B ''修复通道'':25B ''加严门禁前必须先确认'':60B ''单测绿'':40B,48B ''变成'':67B ''存量豁免语义'':61B ''实测'':5A,17B ''想在验收期硬拦'':29B ''截图可见'':41B,49B ''改夹具必然改断言'':50B ''改测试迁就实现'':51B ''断言本身锁死了夹具文本'':44B ''无法重拆'':58B ''既有测试是否把被测文本写进了断言'':63B ''有幂等守卫'':57B ''没'':12A ''没有'':24B ''没有修订通道'':55B ''流程死锁'':68B ''的硬门禁会锁死流水线'':26B ''硬门禁就会从'':65B ''硬门禁设计的铁律'':1A,13B ''结论'':59B ''绕过计划校验'':37B ''落库后'':54B ''被拦对象有无修复路径'':62B ''被硬拦'':43B ''质量闸门'':66B ''过了计划期锚点却不可操作'':42B ''遇到三堵墙'':31B ''部分夹具的弱'':38B ''验收标准'':35B ''验收项没写怎么验'':30B', '2026-09-18 22:21:32.469772', '2026-09-18 22:21:32.469772', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('32787fac-3a27-427f-b229-828550c00301', '「修订通道」是硬门禁的前置条件（2026-09-18，REQ-d3e61a T-9 实证）：任务 a', '「修订通道」是硬门禁的前置条件（2026-09-18，REQ-d3e61a T-9 实证）：任务 acceptance 落库后原本无修订路径（decompose 有幂等守卫不可重拆）→ 硬拦"验收项不可操作"会把需求锁死在验收前。已在**不碰被占文件**的前提下补出通道：给既有 reqboard_task_move 薄壳加可选 acceptance 参数 + 新增 AmendTaskAcceptance use-case（薄壳与 use-case 都空闲；MoveTask.ts/ReportTask.ts/src/index.ts 被占，故不走新工具注册）。要点：① 修订文本仍须过计划期门槛，否则等于把弱标准换成更弱；② 台账与卡文档要同步（人读真相不能落后）；③ 不传参数必须零行为变更。但通道**不能**解除测试夹具的阻塞——那 3 个测试经 decompose/plan_submit 登记了 artifacts（非存量），且断言镜像了弱 acceptance 文本，改门禁必须连测试一起改。', 'experience', '{reqboard,修订通道,硬门禁前置,REQ-d3e61a,T-9}', NULL, '''-09'':4A,17B ''-18'':5A,18B ''-9'':10A,23B ''/reporttask.ts/src/index.ts'':55B ''2026'':3A,16B ''3'':68B ''a'':13A ''acceptance'':26B,41B,75B ''amendtaskacceptance'':44B ''artifacts'':72B ''case'':47B,51B ''d3e61a'':8A,21B ''decompose'':28B ''decompose/plan_submit'':70B ''move'':39B ''movetask.ts'':54B ''movetask.ts/reporttask.ts/src/index.ts'':53B ''req'':7A,20B ''req-d3e61a'':6A,19B ''reqboard'':37B ''t'':9A,22B ''task'':38B ''use'':46B,50B ''use-case'':45B,49B ''不传参数必须零行为变更'':63B ''不碰被占文件'':34B ''不能'':65B ''且断言镜像了弱'':74B ''个测试经'':69B ''人读真相不能落后'':62B ''任务'':12A,25B ''会把需求锁死在验收前'':32B ''但通道'':64B ''修订文本仍须过计划期门槛'':59B ''修订通道'':1A,14B ''参数'':42B ''台账与卡文档要同步'':61B ''否则等于把弱标准换成更弱'':60B ''实证'':11A,24B ''已在'':33B ''改门禁必须连测试一起改'':77B ''故不走新工具注册'':57B ''文本'':76B ''新增'':43B ''是硬门禁的前置条件'':2A,15B ''有幂等守卫不可重拆'':29B ''登记了'':71B ''的前提下补出通道'':35B ''硬拦'':30B ''给既有'':36B ''落库后原本无修订路径'':27B ''薄壳与'':48B ''薄壳加可选'':40B ''被占'':56B ''要点'':58B ''解除测试夹具的阻塞'':66B ''那'':67B ''都空闲'':52B ''非存量'':73B ''验收项不可操作'':31B', '2026-09-18 22:26:17.880173', '2026-09-18 22:26:17.880173', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('c07c7fbe-6891-4fe3-a238-ccb967ee1ec0', 'reqboard 构建新鲜度门（REQBOARD_STALE_BUILD）误报模式与安全处置（202', 'reqboard 构建新鲜度门（REQBOARD_STALE_BUILD）误报模式与安全处置（2026-09-18 实测，REQ-d3e61a T-2）：DoneEvidenceSpec.ts 用 packages/pages/<pkg>/src/** 全部文件的最新 mtime 对比 lib/client.js——**纯服务端改动也会触发**。误报判据：① 我改的文件在 src/client/ 下引用数为 0；② src/client/** 最新 mtime ≤ 产物 mtime（说明客户端上次已构建）。安全处置三步：先 cp -p 备份 lib/client.js|cjs 到 /tmp → npm run build:client（看 exit code 与 [verify-client] OK）→ diff -q 与备份对比，一致即内容中性、可放行。务必先备份：构建失败可能清空 lib/，会直接弄坏 :13080 的看板页。', 'experience', '{reqboard,REQBOARD_STALE_BUILD,构建新鲜度,误报,dsh-pmboard,安全处置}', NULL, '''-09'':15B ''-18'':16B ''-2'':22B ''/src'':26B ''/tmp'':51B ''0'':36B ''13080'':73B ''202'':7A ''2026'':14B ''build'':5A,12B,54B ''cjs'':49B ''client'':55B,62B ''code'':58B ''cp'':45B ''d3e61a'':20B ''diff'':64B ''doneevidencespec.ts'':23B ''exit'':57B ''lib'':71B ''lib/client.js'':30B,48B ''mtime'':28B,39B,41B ''npm'':52B ''ok'':63B ''p'':46B ''packages/pages'':25B ''q'':65B ''req'':19B ''req-d3e61a'':18B ''reqboard'':1A,3A,8B,10B ''run'':53B ''src/client'':34B,37B ''stale'':4A,11B ''t'':21B ''verify'':61B ''verify-client'':60B ''一致即内容中性'':67B ''下引用数为'':35B ''与'':59B ''与备份对比'':66B ''产物'':40B ''会直接弄坏'':72B ''先'':44B ''全部文件的最新'':27B ''到'':50B ''务必先备份'':69B ''可放行'':68B ''备份'':47B ''安全处置三步'':43B ''实测'':17B ''对比'':29B ''我改的文件在'':33B ''最新'':38B ''构建失败可能清空'':70B ''构建新鲜度门'':2A,9B ''用'':24B ''的看板页'':74B ''看'':56B ''纯服务端改动也会触发'':31B ''误报判据'':32B ''误报模式与安全处置'':6A,13B ''说明客户端上次已构建'':42B', '2026-09-18 21:39:50.53245', '2026-09-18 21:39:50.53245', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('5e0b995e-99e5-4c89-b8b9-c78e7bdab578', 'dsh-pmboard 提示词分片体系的三条实操纪律（2026-09-18，REQ-d3e61a T', 'dsh-pmboard 提示词分片体系的三条实操纪律（2026-09-18，REQ-d3e61a T-10）：① 分片是**构建期内联**——改 fragments/*.md 后必须重跑 node scripts/inline-prompt-fragments.mjs 生成 generated/fragments.ts，否则源/产物同步门禁（prompt-gates 第6条）变红。② 新增 <stage>/<difficulty>/overrides.md 前必须确认路由可达：生成器 typeRouteShells 原先硬编码"仅 heavy 挂 overrides"，新加 light/overrides 会变成孤岛，被 prompt-gates 门禁 4「每个分片至少被一条路由命中」精确报红；已泛化为任意难度。③ 改注入文本会导致 tests/prompt-baseline.test.ts（六节点×2难度逐字基线）失败——这是**有意的棘轮**：合规做法是重跑 node scripts/dump-stage-prompts.mjs 更新 tests/fixtures/stage-prompts-baseline-p1.json，并**先 diff 确认只有预期键变化**（"diff 即变更留痕"），绝不改测试去迁就。', 'experience', '{dsh-pmboard,提示词分片,generated/fragments,prompt-baseline,门禁,REQ-d3e61a}', NULL, '''-09'':6A,17B ''-10'':23B ''-18'':7A,18B ''/overrides.md'':42B ''2026'':5A,16B ''2难度逐字基线'':66B ''4'':59B ''d3e61a'':10A,21B ''diff'':77B,79B ''dsh'':2A,13B ''dsh-pmboard'':1A,12B ''fragments'':27B ''gates'':38B,57B ''generated/fragments.ts'':33B ''heavy'':48B ''light/overrides'':52B ''md'':28B ''node'':30B,71B ''overrides'':50B ''pmboard'':3A,14B ''prompt'':37B,56B ''prompt-gates'':36B,55B ''req'':9A,20B ''req-d3e61a'':8A,19B ''scripts/dump-stage-prompts.mjs'':72B ''scripts/inline-prompt-fragments.mjs'':31B ''t'':11A,22B ''tests/fixtures/stage-prompts-baseline-p1.json'':74B ''tests/prompt-baseline.test.ts'':64B ''typerouteshells'':45B ''产物同步门禁'':35B ''仅'':47B ''会变成孤岛'':53B ''先'':76B ''六节点'':65B ''分片是'':24B ''前必须确认路由可达'':43B ''即变更留痕'':80B ''原先硬编码'':46B ''变红'':40B ''合规做法是重跑'':70B ''后必须重跑'':29B ''否则源'':34B ''失败'':67B ''已泛化为任意难度'':62B ''并'':75B ''挂'':49B ''提示词分片体系的三条实操纪律'':4A,15B ''改'':26B ''改注入文本会导致'':63B ''新加'':51B ''新增'':41B ''更新'':73B ''有意的棘轮'':69B ''构建期内联'':25B ''每个分片至少被一条路由命中'':60B ''生成'':32B ''生成器'':44B ''确认只有预期键变化'':78B ''第6条'':39B ''精确报红'':61B ''绝不改测试去迁就'':81B ''被'':54B ''这是'':68B ''门禁'':58B', '2026-09-18 21:43:46.165597', '2026-09-18 21:43:46.165597', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('a97d8125-2d41-402b-8d1b-919cd7aef559', 'JS/TS 高频自坑（本会话连踩两次）：RegExp.prototype.exec 与 String', 'JS/TS 高频自坑（本会话连踩两次）：RegExp.prototype.exec 与 String.match **无匹配时返回 null**，不是 undefined。写 `if (m === undefined) return` 会永远为假 → 后续取 m[1] 抛 "Cannot read properties of null"。纪律：exec/match 的结果一律判 `=== null`，或写 `if (!m) return`。另：正则前瞻窗口（看紧随 N 行）必须**在撞到下一条定义行时截断**，否则相邻条目的标记会互相污染（实测：FR-7 的「本轮不做」误染 FR-4）。', 'experience', '{TypeScript,RegExp,exec-null,边界,REQ-d3e61a}', NULL, '''-4'':55B ''-7'':50B ''1'':25B ''cannot'':27B ''exec/match'':33B ''fr'':49B,54B ''if'':18B,37B ''js/ts'':1A,7B ''m'':19B,24B,38B ''n'':43B ''null'':14B,31B,35B ''of'':30B ''properties'':29B ''read'':28B ''regexp.prototype.exec'':4A,10B ''return'':21B,39B ''string'':6A ''string.match'':12B ''undefined'':16B,20B ''不是'':15B ''与'':5A,11B ''会永远为假'':22B ''写'':17B ''另'':40B ''后续取'':23B ''否则相邻条目的标记会互相污染'':47B ''在撞到下一条定义行时截断'':46B ''实测'':48B ''必须'':45B ''或写'':36B ''抛'':26B ''无匹配时返回'':13B ''本会话连踩两次'':3A,9B ''本轮不做'':52B ''正则前瞻窗口'':41B ''的'':51B ''的结果一律判'':34B ''看紧随'':42B ''纪律'':32B ''行'':44B ''误染'':53B ''高频自坑'':2A,8B', '2026-09-18 21:54:39.434392', '2026-09-18 21:54:39.434392', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('e108f569-3bfe-4dd3-b4ee-177a97c48552', 'reqboard 流水线**状态推进纪律**（2026-09-18 踩坑，REQ-d3e61a）：①', 'reqboard 流水线**状态推进纪律**（2026-09-18 踩坑，REQ-d3e61a）：① 拆分落库（reqboard_decompose）后需求**不会自动**进入 implementing——`decomposing → implementing` 是一道**人工确认闸门**（kind=decomposition），必须调 reqboard_ask_confirm(target=artifact, kind=decomposition)；不发起确认，需求就一直卡在 decomposing，**任务做完了台账上还显示在拆分**（本次 6 个任务 done 后才发现）。② 每个里程碑都要同步**两处**状态：台账（reqboard_status/reqboard_move）与**需求文档 front-matter 的 status 字段**——后者极易过期（本次停在 brainstorming 穿过 planning/decomposing 两个阶段无人发现）。③ 任务全部 done 后由系统自动推进 accepting；implementing → accepting 前须 reqboard_submit(kind=verification)。', 'experience', '{reqboard,状态推进,人工闸门,decomposition,流程纪律,REQ-d3e61a}', NULL, '''-09'':5A,15B ''-18'':6A,16B ''2026'':4A,14B ''6'':47B ''accepting'':74B,76B ''artifact'':39B ''ask'':36B ''brainstorming'':67B ''confirm'':37B ''d3e61a'':10A,20B ''decompose'':23B ''decomposing'':28B,44B ''decomposition'':33B,41B ''done'':49B,72B ''front'':60B ''front-matter'':59B ''implementing'':27B,29B,75B ''kind'':32B,40B,80B ''matter'':61B ''planning/decomposing'':69B ''req'':9A,19B ''req-d3e61a'':8A,18B ''reqboard'':1A,11B,22B,35B,55B,78B ''status'':63B ''status/reqboard_move'':56B ''submit'':79B ''target'':38B ''verification'':81B ''不会自动'':25B ''不发起确认'':42B ''与'':57B ''两个阶段无人发现'':70B ''两处'':52B ''个任务'':48B ''人工确认闸门'':31B ''任务做完了台账上还显示在拆分'':45B ''任务全部'':71B ''前须'':77B ''台账'':54B ''后才发现'':50B ''后由系统自动推进'':73B ''后者极易过期'':65B ''后需求'':24B ''字段'':64B ''必须调'':34B ''拆分落库'':21B ''是一道'':30B ''本次'':46B ''本次停在'':66B ''每个里程碑都要同步'':51B ''流水线'':2A,12B ''状态'':53B ''状态推进纪律'':3A,13B ''的'':62B ''穿过'':68B ''踩坑'':7A,17B ''进入'':26B ''需求就一直卡在'':43B ''需求文档'':58B', '2026-09-18 21:58:40.25773', '2026-09-18 21:58:40.25773', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('81441794-7950-4c23-aec8-0b3456e43f34', 'dsh-pmboard 两条硬门禁（2026-09-18，REQ-d3e61a T-4 实测）：① ', 'dsh-pmboard 两条硬门禁（2026-09-18，REQ-d3e61a T-4 实测）：① **output-contract 门禁**——给 use-case 的 return 加新字段，必须同时在对应工具的 output schema（如 src/tools/SubmitTool/SubmitTool.ts 的 properties）里声明，否则 tests/output-contract.test.ts「所有 return 分支键均已声明」变红。加返回值字段的两步走：改 return + 改 schema，缺一不可。② **工具 schema 与线上数据模型必须对齐**——tsc/单测通过不代表契约齐（本次 NumberedItem 漏了 kind 字段，被 tsc 抓到）。另：编号串联门禁采用分级——悬空（引用不存在的编号）硬拦，孤儿（根编号无下游）只标红不拦，避免把过程中的中间状态锁死。', 'experience', '{dsh-pmboard,output-contract,schema契约,编号串联,REQ-d3e61a}', NULL, '''-09'':6A,19B ''-18'':7A,20B ''-4'':12A,25B ''2026'':5A,18B ''case'':34B ''contract'':29B ''d3e61a'':10A,23B ''dsh'':2A,15B ''dsh-pmboard'':1A,14B ''kind'':66B ''numbereditem'':64B ''output'':28B,39B ''output-contract'':27B ''pmboard'':3A,16B ''properties'':44B ''req'':9A,22B ''req-d3e61a'':8A,21B ''return'':36B,49B,54B ''schema'':40B,56B,59B ''src/tools/submittool/submittool.ts'':42B ''t'':11A,24B ''tests/output-contract.test.ts'':47B ''tsc'':61B,69B ''use'':33B ''use-case'':32B ''与线上数据模型必须对齐'':60B ''两条硬门禁'':4A,17B ''分支键均已声明'':50B ''加新字段'':37B ''加返回值字段的两步走'':52B ''单测通过不代表契约齐'':62B ''变红'':51B ''另'':71B ''只标红不拦'':78B ''否则'':46B ''如'':41B ''字段'':67B ''孤儿'':76B ''实测'':13A,26B ''工具'':58B ''引用不存在的编号'':74B ''必须同时在对应工具的'':38B ''悬空'':73B ''所有'':48B ''抓到'':70B ''改'':53B,55B ''本次'':63B ''根编号无下游'':77B ''漏了'':65B ''的'':35B,43B ''硬拦'':75B ''给'':31B ''编号串联门禁采用分级'':72B ''缺一不可'':57B ''被'':68B ''避免把过程中的中间状态锁死'':79B ''里声明'':45B ''门禁'':30B', '2026-09-18 22:03:16.785691', '2026-09-18 22:03:16.785691', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('8c2fc1b9-26c1-4845-99c3-c09533e56123', 'REQ-b63a7d 诊断（2026-09-18，w-e7129862）：reqboard 文档 4', 'REQ-b63a7d 诊断（2026-09-18，w-e7129862）：reqboard 文档 403 与 token/鉴权无关。GET /dashboard/api/reqboard/file?path=agent-dh/docs/architecture/documentation-standard.md 返回 403 是 packages/pages/dsh-pmboard/src/http/routers/artifacts.ts 的 docs-only 白名单守卫（先判白名单后读文件）；同端点无 token、改用 docs/architecture/documentation-standard.md 请求为 200。根因=登记端 src/application/use-cases/ReportTask.ts:134-143 把 files_changed 原样上浮为 task_output 产物，与文件接口可服务范围两端不一致；实测 DSH 实例 cwd=/Users/yunpeng/pi-investment/agent-dh。台账 .dsh-data/dsh-reqboard.json 扫描出 142 条非合规路径，4 形态：工作区名前缀 agent-dh/...、绝对路径、跨仓 quantsys-v2/...、伪 brace-glob {a,b}。关键认知：REQ-2e9473 t12「改动文件上浮」引入源码类产物，而唯一能读文件的接口只认 docs/ → 全量源码类产物都会被判缺失+报错，不是单条脏数据。附带发现（另立项）：MoveRequirement.ts:56 用未过滤的 ARTIFACT_CONFIRM_GATES，与分类感知的 confirmGateKindFor() 不同源 → bug 分类声明免需求分析门却仍被要求 kind=requirement 确认。', 'knowledge', '{REQ-b63a7d,reqboard,dsh-pmboard,403,artifact-path,文件路径口径}', NULL, '''-09'':6A,19B ''-143'':57B ''-18'':7A,20B ''/dashboard/api/reqboard/file'':31B ''/docs/architecture/documentation-standard.md'':36B ''/dsh-reqboard.json'':75B ''/users/yunpeng/pi-investment/agent-dh'':70B ''134'':56B ''142'':77B ''200'':52B ''2026'':5A,18B ''2e9473'':99B ''4'':13A,79B ''403'':26B,38B ''a'':94B ''agent'':34B,83B ''agent-dh'':33B,82B ''artifact'':112B ''b'':95B ''b63a7d'':3A,16B ''brace'':92B ''brace-glob'':91B ''bug'':118B ''changed'':60B ''confirm'':113B ''confirmgatekindfor'':116B ''cwd'':69B ''data'':74B ''dh'':35B,84B ''docs'':43B,104B ''docs-only'':42B ''docs/architecture/documentation-standard.md'':50B ''dsh'':67B,73B ''dsh-data'':72B ''e7129862'':10A,23B ''files'':59B ''gates'':114B ''get'':30B ''glob'':93B ''kind'':120B ''moverequirement.ts:56'':110B ''only'':44B ''output'':63B ''packages/pages/dsh-pmboard/src/http/routers/artifacts.ts'':40B '