INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('7287bdb7-2161-4c2d-ae4c-f99f11f4c4bb', '【每日蒸馏 2026-09-18 16:00 · evolution-distill-daily（0', '【每日蒸馏 2026-09-18 16:00 · evolution-distill-daily（0b61dbe3）· investor (investor-session-00d85da9-9691-4903-a466-c430a073b7ac)】

