INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('5dc64e62-5e3b-4823-9a64-99783a8d7c64', '2026-09-19（w-e1fc9bb5）运维教训：**「延迟重启自己」不能靠本进程的子进程派发*', '2026-09-19（w-e1fc9bb5）运维教训：**「延迟重启自己」不能靠本进程的子进程派发**。
现场：需要重启 :13080 让新代码生效，用 `nohup bash -c "sleep 25; launchctl kickstart -k gui/$(id -u)/com.pi-investment.dsh" &` 调度——命令返回了、看起来"已调度"，但 25s 后进程还是老的（`ps lstart` 未变、日志文件为空）：子进程随命令结束被回收，launchctl 从未被调用。同一写法第一次（23:51）侥幸生效，第二次静默失效——**静默失效比失败更贵**（我以为重启过了）。
可靠做法：交给独立 supervisor 派发——`launchctl submit -l <label> -- /bin/bash -c "sleep 25; launchctl kickstart -k gui/$(id -u)/<job>"`，并用 `launchctl print gui/$(id -u)/<label>` 确认 `state = running`（本次已按此执行，任务里自带 `launchctl remove` 自清）。
判据（怎么确认真重启了）：`ps -o lstart= -p $(lsof -ti:13080 -sTCP:LISTEN)` 的启动时间必须变新 + 线上行为证据（本次=`GET /dashboard/api/reqboard/requirements/REQ-d3e61a/marks` 的 `by` 从计划键 `T-3` 变成台账 id `t-5042c7`、state 从 received 变 done）。', 'experience', '{重启,launchctl,运维,:13080,w-e1fc9bb5}', NULL, '''-09'':2A,11B ''-19'':3A,12B ''-3'':108B ''/bin/bash'':64B ''/com.pi-investment.dsh'':35B ''/dashboard/api/reqboard/requirements/req-d3e61a/marks'':103B ''13080'':21B,96B ''2026'':1A,10B ''23'':51B ''25'':28B,67B ''25s'':41B ''5042c7'':113B ''51'':52B ''bash'':25B ''by'':105B ''c'':26B,65B ''done'':118B ''e1fc9bb5'':6A,15B ''get'':102B ''gui'':32B,71B,77B ''id'':33B,72B,78B,110B ''k'':31B,70B ''kickstart'':30B,69B ''l'':63B ''launchctl'':29B,48B,61B,68B,75B,85B ''listen'':98B ''lsof'':94B ''lstart'':44B,92B ''nohup'':24B ''o'':91B ''p'':93B ''print'':76B ''ps'':43B,90B ''received'':116B ''remove'':86B ''running'':82B ''sleep'':27B,66B ''state'':81B,114B ''stcp'':97B ''submit'':62B ''supervisor'':59B ''t'':107B,112B ''t-5042c7'':111B ''ti'':95B ''u'':34B,73B,79B ''w'':5A,14B ''w-e1fc9bb5'':4A,13B ''不能靠本进程的子进程派发'':9A,18B ''交给独立'':58B ''从'':115B ''从未被调用'':49B ''从计划键'':106B ''任务里自带'':84B ''但'':40B ''侥幸生效'':53B ''判据'':88B ''变'':117B ''变成台账'':109B ''可靠做法'':57B ''同一写法第一次'':50B ''后进程还是老的'':42B ''命令返回了'':37B ''子进程随命令结束被回收'':47B ''已调度'':39B ''并用'':74B ''延迟重启自己'':8A,17B ''怎么确认真重启了'':89B ''我以为重启过了'':56B ''日志文件为空'':46B ''未变'':45B ''本次'':101B ''本次已按此执行'':83B ''派发'':60B ''现场'':19B ''用'':23B ''的'':104B ''的启动时间必须变新'':99B ''看起来'':38B ''确认'':80B ''第二次静默失效'':54B ''线上行为证据'':100B ''自清'':87B ''让新代码生效'':22B ''调度'':36B ''运维教训'':7A,16B ''需要重启'':20B ''静默失效比失败更贵'':55B', '2026-09-19 00:31:47.386163', '2026-09-19 00:31:47.386163', '{}');
