INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('76bb307a-365d-4dac-be2a-c18cde955c37', 'REQ-81aabd 发版核验（2026-09-19 17:44-17:45，w-45748eec）', 'REQ-81aabd 发版核验（2026-09-19 17:44-17:45，w-45748eec）：planning→design 节点名统一 + 设计文档建模上线。①编排必须把迁移夹在「停与起之间」——JsonLedgerRepository 是 load-once + 每次 mutate 全量重写，进程存活时外部迁移会被内存旧快照静默覆盖（实测）；②macOS bash 3.2 下裸 $VAR 紧跟全角字符（如 $LABEL（ ）会把多字节吃进变量名，set -u 报 unbound variable —— 中文提示语里变量一律写 ${VAR}；③本机 launchd 作业 com.pi-investment.dsh 曾被卸载、实例由交互式 shell 拉起（kill 不会自动恢复），本轮 launchctl bootstrap 已恢复 KeepAlive 托管（pid 24494）；④验证『客户端产物是否真的换了』要直接 grep 产物文件与跑 verify-client-build.mjs，源码级绿灯无效。', 'knowledge', '{REQ-81aabd,reqboard,ledger-migration,launchd,bash32,客户端构建}', NULL, '''-09'':6A,20B ''-17'':10A,24B ''-19'':7A,21B ''17'':8A,22B ''2026'':5A,19B ''24494'':78B ''3.2'':47B ''44'':9A,23B ''45'':11A,25B ''45748eec'':14A,28B ''81aabd'':3A,17B ''bash'':46B ''bootstrap'':73B ''com.pi-investment.dsh'':64B ''design'':30B ''grep'':82B ''jsonledgerrepository'':35B ''keepalive'':75B ''kill'':69B ''label'':52B ''launchctl'':72B ''launchd'':62B ''load'':38B ''load-once'':37B ''macos'':45B ''mutate'':41B ''once'':39B ''pid'':77B ''planning'':29B ''req'':2A,16B ''req-81aabd'':1A,15B ''set'':54B ''shell'':67B ''u'':55B ''unbound'':57B ''var'':49B,60B ''variable'':58B ''verify-client-build.mjs'':84B ''w'':13A,27B ''w-45748eec'':12A,26B ''下裸'':48B ''不会自动恢复'':70B ''中文提示语里变量一律写'':59B ''产物文件与跑'':83B ''会把多字节吃进变量名'':53B ''作业'':63B ''停与起之间'':34B ''全量重写'':42B ''发版核验'':4A,18B ''如'':51B ''实例由交互式'':66B ''实测'':44B ''客户端产物是否真的换了'':80B ''已恢复'':74B ''托管'':76B ''报'':56B ''拉起'':68B ''是'':36B ''曾被卸载'':65B ''本机'':61B ''本轮'':71B ''每次'':40B ''源码级绿灯无效'':85B ''紧跟全角字符'':50B ''编排必须把迁移夹在'':33B ''节点名统一'':31B ''要直接'':81B ''设计文档建模上线'':32B ''进程存活时外部迁移会被内存旧快照静默覆盖'':43B ''验证'':79B', '2026-09-19 17:57:01.92731', '2026-09-19 17:57:01.92731', '{}');
