INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('acea6b97-79fe-488d-b144-02885e239d4e', '【REQ-640a55 阻塞·基线不一致】（2026-09-19，w-98f2b4b4）立项时对三处', '【REQ-640a55 阻塞·基线不一致】（2026-09-19，w-98f2b4b4）立项时对三处门禁失效的侦察是在【主工作区工作副本】做的，而该副本是另一窗口未提交的 WIP（git status 实测 133 文件、+1344/-868），worktree feat/pmboard-triad 停在 HEAD=3543dbf2，不含这些改动。实证：HEAD 全仓搜 checkClauseSequence / checkClauseDuplicates / checkRequirementDocFormatGate 命中 0；主工作区 content-gates.ts:274/:307 有定义（该文件主 314 行 vs HEAD 377 行，且主工作区新拆出 doc-parse.ts）。另：HEAD 的 RequirementStatus 仍是 brainstorming→planning（第 58 行），主工作区已 rename 为 design。逐文件比对（主工作区 vs HEAD）：content-gate-wiring.ts 366/302、content-gates.ts 314/377、Decompose.ts 374/369、TaskMoveTool.ts 141/140、MoveTool.ts 67/67、AmendTaskAcceptance.ts 98/97、SubmitArtifact.ts 293/286、artifact-gates.ts 182/178 全部 DIFF；仅 ReportTask.ts 182/182 SAME。结论：t-92e0b3（修两处编号判据）在 HEAD 上不可实现——不是"门禁坏了"，而是"这套门禁尚未提交"。教训（可复用）：立项侦察必须标注读的是【提交基线】还是【工作副本】；本仓多窗口并行，工作副本 ≠ 分支 HEAD。数据来源与口径：git status/diff + 文件逐对比对，2026-09-19；命令与输出见本窗口会话。', 'knowledge', '{REQ-640a55,pmboard,worktree,基线不一致,w-98f2b4b4}', NULL, '''+1344'':34B ''-09'':7A,19B,131B ''-19'':8A,20B,132B ''-868'':35B ''/:307'':53B ''0'':49B ''133'':32B ''141/140'':89B ''182/178'':97B ''182/182'':102B ''2026'':6A,18B,130B ''293/286'':95B ''314'':56B ''314/377'':85B ''3543dbf2'':40B ''366/302'':83B ''374/369'':87B ''377'':60B ''58'':72B ''640a55'':3A,15B ''67/67'':91B ''92e0b3'':107B ''98/97'':93B ''98f2b4b4'':11A,23B ''amendtaskacceptance.ts'':92B ''artifact-gates.ts'':96B ''brainstorming'':69B ''checkclauseduplicates'':46B ''checkclausesequence'':45B ''checkrequirementdocformatgate'':47B ''content-gate-wiring.ts'':82B ''content-gates.ts'':84B ''content-gates.ts:274'':52B ''content-gates.ts:274/:307'':51B ''decompose.ts'':86B ''design'':77B ''diff'':99B ''doc-parse.ts'':63B ''feat/pmboard-triad'':37B ''git'':29B,127B ''head'':39B,43B,59B,65B,81B,110B,125B ''movetool.ts'':90B '