INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('462e2b9a-aa8d-4db4-8c0c-29456a320a39', '【REQ-640a55 基线处置】（2026-09-19，w-98f2b4b4）处置：把主工作区未提', '【REQ-640a55 基线处置】（2026-09-19，w-98f2b4b4）处置：把主工作区未提交的 dsh-pmboard 改动全量封存为分支 wip/pmboard-inflight-20260919（快照提交 14bc211a，从 HEAD 3543dbf2 起，含未跟踪新文件；用临时 GIT_INDEX_FILE 构建，未触碰真实索引与工作区）。随后把 worktree .claude/worktrees/pmboard-triad 的分支 feat/pmboard-triad 重置到该快照（git reset --hard，非 merge）。核对：worktree 与运行实例的 packages/pages/dsh-pmboard/src 逐文件差异 = 0；主工作区仍是 main + 1146 条未提交改动（未被触碰）。归属核查：编号门禁（checkClauseSequence/checkClauseDuplicates/checkRequirementDocFormatGate）所属需求为 REQ-99b58f《修复 PM 插件生命周期流程》会话 session-84d369f2，该需求仍 brainstorming / 无计划 / 0 任务 / 最后活动 03:35，**未完成**，故未把该批改动提交进 main。收尾办法：真身提交后 git rebase --onto <真身> 14bc211a feat/pmboard-triad，即可丢掉快照层。', 'knowledge', '{REQ-640a55,pmboard,worktree,基线,w-98f2b4b4}', NULL, '''-09'':6A,18B ''-19'':7A,19B ''0'':59B,82B ''03'':85B ''1146'':62B ''14bc211a'':31B,96B ''2026'':5A,17B ''35'':86B ''3543dbf2'':34B ''640a55'':3A,15B ''84d369f2'':78B ''98f2b4b4'':10A,22B ''99b58f'':71B ''brainstorming'':80B ''checkclausesequence/checkclauseduplicates/checkrequirementdocformatgate'':67B ''claude/worktrees/pmboard-triad'':45B ''dsh'':26B ''dsh-pmboard'':25B ''feat/pmboard-triad'':47B,97B ''file'':40B ''git'':38B,49B,92B ''hard'':51B ''head'':33B ''index'':39B ''main'':61B,89B ''merge'':53B ''onto'':94B ''packages/pages/dsh-pmboard/src'':57B ''pm'':73B ''pmboard'':27B ''rebase'':93B ''req'':2A,14B,70B ''req-640a55'':1A,13B ''req-99b58f'':69B ''reset'':50B ''session'':77B ''session-84d369f2'':76B ''w'':9A,21B ''w-98f2b4b4'':8A,20B ''wip/pmboard-inflight-20260919'':29B ''worktree'':44B,55B ''与运行实例的'':56B ''主工作区仍是'':60B ''从'':32B ''任务'':83B ''会话'':75B ''修复'':72B ''即可丢掉快照层'':98B ''含未跟踪新文件'':36B ''基线处置'':4A,16B ''处置'':11A,23B ''归属核查'':65B ''快照提交'':30B ''所属需求为'':68B ''把主工作区未提'':12A ''把主工作区未提交的'':24B ''插件生命周期流程'':74B ''收尾办法'':90B ''改动全量封存为分支'':28B ''故未把该批改动提交进'':88B ''无计划'':81B ''最后活动'':84B ''未完成'':87B ''未被触碰'':64B ''未触碰真实索引与工作区'':42B ''条未提交改动'':63B ''构建'':41B ''核对'':54B ''用临时'':37B ''的分支'':46B ''真身'':95B ''真身提交后'':91B ''编号门禁'':66B ''该需求仍'':79B ''起'':35B ''逐文件差异'':58B ''重置到该快照'':48B ''随后把'':43B ''非'':52B', '2026-09-19 19:15:13.016788', '2026-09-19 19:15:13.016788', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('9b32d5c5-d1e7-4466-afca-0055612c990f', '【REQ-640a55 工具限制发现·done 凭证门只认运行实例工作区】（2026-09-19，w', '【REQ-640a55 工具限制发现·done 凭证门只认运行实例工作区】（2026-09-19，w-98f2b4b4）现象：t-92e0b3 修复已在 worktree 完成并提交（2cf2b57e），但 reqboard_task_move(in_review→done) 连续两次被拒 REQBOARD_NO_EVIDENCE（"开工以来无干活类工具动作，且汇报声明的改动文件不存在或早于开工时间"）。根因两条：① tools/ 内的工具活动痕迹（SessionProbeAdapter.toolActivitySince）在 PTC 模式下内部调用一律呈现为 run_code，且以 task.claimedAt 为界——本次编辑恰好发生在 claimedAt（19:16:47）之前约 30 秒，痕迹统计为 0；② 文件证据用 deps.docs.stat()，其 workspaceRoot = 运行实例 cwd（/Users/yunpeng/pi-investment/agent-dh）——**worktree 里的改动对凭证门不可见**。绕行（已验证可行）：把同一份修复同步落盘到运行实例工作区（3 个文件），并在 packages/pages/dsh-pmboard 跑 pnpm build:client 刷新 lib/client.js（否则触发 REQBOARD_STALE_BUILD：声明了 packages/pages/<pkg>/src/ 下的改动就必须让 lib/client.js 比它新）。通用教训：reqboard 的推进门禁（done 凭证 / STALE_BUILD）都以**运行实例工作区**为准；在 worktree 里干活可以在门禁上被判"证据不足"。要么让门禁支持 worktree 感知，要么在实例工作区落盘后再结单——别以为提交进分支就够了。另注：主工作区那批 1146 条未提交改动仍在（快照分支 wip/pmboard-inflight-20260919 = 14bc211a 兜底），我的 3 个文件已并入其中，未提交。', 'knowledge', '{REQ-640a55,pmboard,done凭证门,worktree,w-98f2b4b4}', NULL, '''-09'':8A,18B ''-19'':9A,19B ''/src'':94B ''/users/yunpeng/pi-investment/agent-dh'':72B ''0'':65B ''1146'':119B ''14bc211a'':123B ''16'':59B ''19'':58B ''2026'':7A,17B ''2cf2b57e'':30B ''3'':78B,126B ''30'':62B ''47'':60B ''640a55'':3A,13B ''92e0b3'':26B ''98f2b4b4'':22B ''build'':84B,91B,104B ''claimedat'':57B ''client'':85B ''code'':52B ''cwd'':71B ''deps.docs.stat'':67B ''done'':5A,15B,37B,101B ''evidence'':41B ''in'':35B ''lib/client.js'':87B,96B ''move'':34B ''no'':40B ''packages/pages'':93B ''packages/pages/dsh-pmboard'':81B ''pnpm'':83B ''ptc'':49B ''req'':2A,12B ''req-640a55'':1A,11B ''reqboard'':32B,39B,89B,99B ''review'':36B ''run'':51B ''sessionprobeadapter.toolactivitysince'':47B ''stale'':90B,103B ''t'':25B ''t-92e0b3'':24B ''task'':33B ''task.claimedat'':54B ''tools'':45B ''w'':10A,21B ''w-98f2b4b4'':20B ''wip/pmboard-inflight-20260919'':122B ''workspaceroot'':69B ''worktree'':28B,73B,109B,113B ''下的改动就必须让'':95B ''且以'':53B ''且汇报声明的改动文件不存在或早于开工时间'':43B ''个文件'':79B ''个文件已并入其中'':127B ''为准'':107B ''为界'':55B ''主工作区那批'':118B ''之前约'':61B ''但'':31B ''修复已在'':27B ''兜底'':124B ''其'':68B ''内的工具活动痕迹'':46B ''凭证'':102B ''凭证门只认运行实例工作区'':6A,16B ''别以为提交进分支就够了'':116B ''刷新'':86B ''另注'':117B ''否则触发'':88B ''在'':48B,108B ''声明了'':92B ''完成并提交'':29B ''工具限制发现'':4A,14B ''已验证可行'':76B ''并在'':80B ''开工以来无干活类工具动作'':42B ''快照分支'':121B ''感知'':114B ''我的'':125B ''把同一份修复同步落盘到运行实例工作区'':77B ''文件证据用'':66B ''未提交'':128B ''本次编辑恰好发生在'':56B ''条未提交改动仍在'':120B ''根因两条'':44B ''模式下内部调用一律呈现为'':50B ''比它新'':97B ''现象'':23B ''痕迹统计为'':64B ''的推进门禁'':100B ''秒'':63B ''绕行'':75B ''要么在实例工作区落盘后再结单'':115B ''要么让门禁支持'':112B ''证据不足'':111B ''跑'':82B ''运行实例'':70B ''运行实例工作区'':106B ''连续两次被拒'':38B ''通用教训'':98B ''都以'':105B ''里干活可以在门禁上被判'':110B ''里的改动对凭证门不可见'':74B', '2026-09-19 19:18:15.680654', '2026-09-19 19:18:15.680654', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('eafbe3f1-e113-46ad-a8cb-52b49200d88c', '【REQ-640a55 发现·改卡通道两个缺陷】（2026-09-19，w-98f2b4b4）现场：', '【REQ-640a55 发现·改卡通道两个缺陷】（2026-09-19，w-98f2b4b4）现场：t-fb5e66（done）的验收标准不满足验收期「怎么验」门禁（REQBOARD_ACCEPTANCE_NOT_EXECUTABLE），门禁提示用 reqboard_task_move(task_id, acceptance=...) 修订。实测两点：① 该调用把**台账**改了，随后因 done 是终态（TASK_TRANSITIONS.done = []）以 invalid_transition 失败——即"被拒绝的调用留下了副作用"（AmendTaskAcceptance 在转移校验之前就 mutate 台账）；② 卡文档同步是"尽力而为"（catch {} 吞异常），本次卡文档 mtime 未变、内容仍是旧文本 → 台账与人读的唯一事实源漂移且无人报错。为什么单测没发现：t4 的回归用例走 makeHarness 的内存假 docs，真实 FileDocRepository 上的这次静默失败照不出来（假通过）。处置：手工对齐卡文档；记为后续需求候选（非本次范围）：a) 终态任务的验收标准应有独立修订入口，不借道 task_move 的转移；b) 文档同步失败要降级留痕（doc_synced=false）而非静默；c) 改卡通道回归应跑真实 FileDocRepository。', 'knowledge', '{REQ-640a55,pmboard,改卡通道,发现,w-98f2b4b4}', NULL, '''-09'':7A,19B ''-19'':8A,20B ''2026'':6A,18B ''640a55'':3A,15B ''98f2b4b4'':11A,23B ''a'':85B ''acceptance'':33B,42B ''amendtaskacceptance'':58B ''b'':91B ''c'':97B ''catch'':64B ''doc'':93B ''docs'':76B ''done'':28B,49B ''executable'':35B ''false'':95B ''fb5e66'':27B ''filedocrepository'':78B,99B ''id'':41B ''invalid'':53B ''makeharness'':74B ''move'':39B,89B ''mtime'':67B ''mutate'':60B ''not'':34B ''req'':2A,14B ''req-640a55'':1A,13B ''reqboard'':32B,37B ''synced'':94B ''t'':26B ''t-fb5e66'':25B ''t4'':72B ''task'':38B,40B,88B ''task_transitions.done'':51B ''transition'':54B ''w'':10A,22B ''w-98f2b4b4'':9A,21B ''上的这次静默失败照不出来'':79B ''不借道'':87B ''为什么单测没发现'':71B ''以'':52B ''修订'':43B ''假通过'':80B ''内容仍是旧文本'':69B ''卡文档同步是'':62B ''即'':56B ''发现'':4A,16B ''台账'':46B,61B ''台账与人读的唯一事实源漂移且无人报错'':70B ''吞异常'':65B ''在转移校验之前就'':59B ''处置'':81B ''失败'':55B ''实测两点'':44B ''尽力而为'':63B ''怎么验'':30B ''手工对齐卡文档'':82B ''改了'':47B ''改卡通道两个缺陷'':5A,17B ''改卡通道回归应跑真实'':98B ''文档同步失败要降级留痕'':92B ''是终态'':50B ''未变'':68B ''本次卡文档'':66B ''现场'':12A,24B ''的内存假'':75B ''的回归用例走'':73B ''的转移'':90B ''的验收标准不满足验收期'':29B ''真实'':77B ''终态任务