INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('402a8661-6ea9-414d-b02e-bca7bfbd56c1', '【REQ-640a55 存量零误伤实测】（2026-09-19T11:32Z，w-98f2b4b4）', '【REQ-640a55 存量零误伤实测】（2026-09-19T11:32Z，w-98f2b4b4）口径：dsh-reqboard.json 非终态需求（draft/brainstorming/design/decomposing/implementing/accepting） + docs/requirements/<REQ>/tasks/<id>.md 卡文件（工作区=/Users/yunpeng/pi-investment/agent-dh，即运行实例读的那份），判定与门禁同源：标题行 ^#{1,6}\s*名称\s*$ 或 **名称** 开头。结果：非终态需求 11 条；在途卡（未 done/canceled，即还会触发结单门禁的）仅 2 张，均在 REQ-640a55 且已合规；**会被结单门禁拦下的卡 = 0**；卡文件缺失 = 0。出口门禁（decomposing→implementing）会跑的需求只有 REQ-6cbbf7（在途卡 0 张 → 门禁按设计跳过）。口径修正：此前审计说"10 条需求 / 19 张在途卡缺三要素"——那是把**已 done**的卡也算进去了；门禁只在卡还要移动时才判，故真实风险面是"还会结单的卡"= 2 张。另记一次自检：首版实测脚本只对三个节名中的一个做了标题行匹配（三元表达式写偏），把刚补齐的卡误报成"缺三要素"——实测口径本身也要对照事实自检，否则会用错口径得出"有风险"的假结论。', 'knowledge', '{REQ-640a55,pmboard,三要素门禁,存量零误伤,w-98f2b4b4}', NULL, '''-09'':6A,18B ''-19'':7A,19B ''/tasks'':30B ''/users/yunpeng/pi-investment/agent-dh'':34B ''0'':63B,65B,74B ''1'':38B ''10'':79B ''11'':48B ''19'':81B ''2'':55B,90B ''2026'':5A,17B ''32z'':9A,21B ''6'':39B ''640a55'':3A,15B,60B ''6cbbf7'':72B ''98f2b4b4'':12A,24B ''decomposing'':67B ''docs/requirements'':29B ''done'':85B ''done/canceled'':52B ''draft/brainstorming/design/decomposing/implementing/accepting'':28B ''dsh-reqboard.json'':26B ''implementing'':68B ''md'':31B ''req'':2A,14B,59B,71B ''req-640a55'':1A,13B,58B ''req-6cbbf7'':70B ''s'':40B,42B ''t11'':8A,20B ''w'':11A,23B ''w-98f2b4b4'':10A,22B ''三元表达式写偏'':94B ''且已合规'':61B ''仅'':54B ''会被结单门禁拦下的卡'':62B ''会跑的需求只有'':69B ''出口门禁'':66B ''判定与门禁同源'':36B ''卡文件'':32B ''卡文件缺失'':64B ''即运行实例读的那份'':35B ''即还会触发结单门禁的'':53B ''口径'':25B ''口径修正'':77B ''另记一次自检'':92B ''名称'':41B,44B ''否则会用错口径得出'':98B ''在途卡'':50B,73B ''均在'':57B ''存量零误伤实测'':4A,16B ''实测口径本身也要对照事实自检'':97B ''工作区'':33B ''已'':84B ''开头'':45B ''张'':56B,75B,91B ''张在途卡缺三要素'':82B ''或'':43B ''把刚补齐的卡误报成'':95B ''故真实风险面是'':88B ''有风险'':99B ''未'':51B ''条'':49B ''条需求'':80B ''标题行''