INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('00e2a88a-a631-4cf6-a11f-e9a722a6d73b', 'REQ-99f5fe 立项（bug/refactor，本窗口 w-b5b8ab06）：Capture', 'REQ-99f5fe 立项（bug/refactor，本窗口 w-b5b8ab06）：CaptureHook 注入提示词不触发立项弹框的根因不是链路而是文案——session/event user/message → pendingCapture → systemPrompt 段（order 60）注入链路经本窗口系统提示词实证每次都在（「## 项目捕获…检测到用户新输入」原文可见），但旧文案「请先判断是否属于这类工作」+「继续之前话题→正常回复即可」把多轮方案讨论的每次追问都放行成跳过，导致零弹框零 REQ。修复：capture-section.ts 两段文案改祈使句+三条必立规则（改动意图词/已产出方案后任何回应/拿不准默认弹框）+豁免收窄为纯寒暄·纯状态查询·纯知识问答，并显式声明「继续之前话题」不是豁免；同步与 CreateTool/prompt.ts 的「三问确认」对齐（原来两处口径一为两问一为三问，互相矛盾）。证据：用户原话「CaptureHook 注入的提示词有问题，导致没有让llm 触发创建立项的弹框」。', 'experience', '{reqboard,CaptureHook,立项,提示词,REQ-99f5fe}', NULL, '''60'':28B ''99f5fe'':3A,13B ''b5b8ab06'':9A,19B ''bug/refactor'':5A,15B ''capture'':10A ''capture-section.ts'':41B ''capturehook'':20B,62B ''createtool/prompt.ts'':54B ''order'':27B ''pendingcapture'':24B ''req'':2A,12B,39B ''req-99f5fe'':1A,11B ''session/event'':22B ''systemprompt'':25B ''user/message'':23B ''w'':8A,18B ''w-b5b8ab06'':7A,17B ''三条必立规则'':43B ''三问确认'':56B ''不是豁免'':52B ''两段文案改祈使句'':42B ''互相矛盾'':59B ''但旧文案'':33B ''修复'':40B ''原文可见'':32B ''原来两处口径一为两问一为三问'':58B ''同步与'':53B ''对齐'':57B ''导致没有让llm'':64B ''导致零弹框零'':38B ''已产出方案后任何回应'':45B ''并显式声明'':50B ''把多轮方案讨论的每次追问都放行成跳过'':37B ''拿不准默认弹框'':46B ''改动意图词'':44B ''本窗口'':6A,16B ''检测到用户新输入'':31B ''正常回复即可'':36B ''段'':26B ''注入提示词不触发立项弹框的根因不是链路而是文案'':21B ''注入的提示词有问题'':63B ''注入链路经本窗口系统提示词实证每次都在'':29B ''用户原话'':61B ''的'':55B ''立项'':4A,14B ''纯状态查询'':48B ''纯知识问答'':49B ''继续之前话题'':35B,51B ''触发创建立项的弹框'':65B ''证据'':60B ''请先判断是否属于这类工作'':34B ''豁免收窄为纯寒暄'':47B ''项目捕获'':30B', '2026-09-20 01:30:59.085479', '2026-09-20 01:30:59.085479', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('a46db405-7919-411c-9c31-eaaaa9aeb017', 'pmboard Hook 机制盘点（2026-09-20，w-b5b8ab06）：现有 10 条 h', 'pmboard Hook 机制盘点（2026-09-20，w-b5b8ab06）：现有 10 条 hook 行为（H1 立项登记/H2 接手推进/H3 阶段提示注入/H4 里程碑提醒/H5 节点结算隔离/H6 待捕获清除/H7 工具痕迹/H8 证据缓冲/H9 引导段渲染/H10 弹框作答自动继续）。四类病灶：A 判定在 CaptureHook、动作在 index.ts 闭包（散落无登记处）；B index.ts:256-269 残留 onAskUserQuestionAnswered——CaptureHookDeps 无此字段，tsc 报 5 个错误且违背用户裁定「ask_user_question 不得有自动继续」，已清理（tsc 6→1）；C 【最严重】业务弹框自动继续是半接线：ports.ts 声明✓、UserQuestionsAdapter 实现✓、use-cases 零 autoContinue 声明✗、index.ts:329 未传 onAnswered✗ → 运行时永不自动继续，但 pmboard-auto-continue.test.ts 6/6 绿（直接 new adapter 注入 spy）——又一次「源码级测试绿≠线上生效」；D 无 hook_decisions 日志，「为什么没触发」无法回答。设计稿：docs/hook-framework.md（规则注册表 HookRule + 四层 Collect/Decide/Act/Record + 门禁 G1-G5 其中 G2 专治半接线、G5 禁 ask_user_question 入白名单 + 迁移 T0-T6）。', 'experience', '{pmboard,hook,框架设计,半接线,假绿,w-b5b8ab06}', NULL, '''-09'':5A,18B ''-20'':6A,19B ''-269'':58B ''/h10'':46B ''/h2'':30B ''/h3'':32B ''/h4'':34B ''/h5'':36B ''/h6'':38B ''/h7'':40B ''/h8'':42B ''/h9'':44B ''1'':74B ''10'':11A,24B ''2026'':4A,17B ''5'':65B ''6'':73B ''6/6'':94B ''a'':49B ''adapter'':98B ''ask'':67B,126B ''autocontinue'':86B ''b'':56B ''b5b8ab06'':9A,22B ''c'':75B ''capturehook'':51B ''capturehookdeps'':61B ''cases'':84B ''collect/decide/act/record'':116B ''d'':104B ''decisions'':107B ''docs/hook-framework.md'':112B ''g1'':119B ''g1-g5'':118B ''g2'':122B ''g5'':120B,124B ''h'':13A ''h1'':28B ''hook'':2A,15B,26B,106B ''hookrule'':114B ''index.ts'':53B ''index.ts:256'':57B ''index.ts:329'':88B ''new'':97B ''onanswered'':90B ''onaskuserquestionanswered'':60B ''pmboard'':1A,14B ''pmboard-auto-continue.test.ts'':93B ''ports.ts'':78B ''question'':69B,128B ''spy'':100B ''t0'':132B ''t0-t6'':131B ''t6'':133B ''tsc'':63B,72B ''use'':83B ''use-cases'':82B ''user'':68B,127B ''userquestionsadapter'':80B ''w'':8A,21B ''w-b5b8ab06'':7A,20B '