INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('5b0d1dd0-02ed-4e16-9e1f-094d3214cdbe', '【口径纠正·2026-09-20 w-878da638】「归档」不是独立人工门（用户指正，代码复核一', '【口径纠正·2026-09-20 w-878da638】「归档」不是独立人工门（用户指正，代码复核一致）：
· 代码级仅人的集合（RequirementStatus.HUMAN_ONLY_REQ_TRANSITIONS）= 四道产物确认门（brainstorming>design、decomposing>implementing、accepting>archived；design>decomposing 由产物门 plan 拦截）+ 取消类（draft/brainstorming/decomposing/implementing/accepting > canceled、canceled>archived）。
· **没有独立的「归档」门**：accepting>archived 就是「验收通过」这道门的落地动作——人点"验收通过"即自动归档；其后的补归档材料（reqboard_submit(kind=archive)）**由 agent 自主完成，无人再点**（工作流指南原文：ACCEPT→ARCHIVED 已自动完成，无需再点归档）。
· 状态机事实：brainstorming 的出边只有 design｜draft｜canceled——`brainstorming → archived` 根本不是合法边，故对处于 brainstorming 的需求谈"归档"没有意义，只能"取消"。
· 影响：我此前把"让 REQ-99f5fe 停手"写成"取消/归档是人工闸门"是错的；正确说法是**只需取消需求**（agent 无权，`*>canceled` 代码级仅人）。
· 治理留痕：PRD REQ-e3b6a0 §12 D7 备注已按此改写，但需求已进入 implementing，reqboard_submit(kind=requirement) 被工具拒绝（文档只能在 brainstorming 阶段提交，重交会作废既有确认）——故本次修正只能落磁盘、无法重新登记；已在 t10 验收材料中显式记录，不静默。', 'knowledge', '{reqboard,人工闸门,归档语义,REQ-e3b6a0,口径纠正}', NULL, '''-09'':3A,14B ''-20'':4A,15B ''12'':108B ''2026'':2A,13B ''878da638'':7A,18B ''99f5fe'':91B ''accept'':66B ''accepting'':33B,48B ''agent'':62B,99B ''archive'':60B ''archived'':34B,44B,49B,67B,77B ''brainstorming'':29B,71B,76B,80B,119B ''canceled'':42B,43B,75B,101B ''d7'':109B ''decomposing'':31B,36B ''design'':30B,35B,73B ''draft'':74B ''draft/brainstorming/decomposing/implementing/accepting'':41B ''e3b6a0'':107B ''implementing'':32B,112B ''kind'':59B,115B ''only'':25B ''plan'':38B ''prd'':104B ''req'':26B,90B,106B ''req-99f5fe'':89B ''req-e3b6a0'':105B ''reqboard'':57B,113B ''requirement'':116B ''requirementstatus.human'':24B ''submit'':58B,114B ''t10'':125B ''transitions'':27B ''w'':6A,17B ''w-878da638'':5A,16B ''不是独立人工门'':9A,20B ''不静默'':127B ''人点'':53B ''代码复核一'':11A ''代码复核一致'':22B ''代码级仅人'':102B ''代码级仅人的集合'':23B ''但需求已进入'':111B ''停手'':92B ''其后的补归档材料'':56B ''写成'':93B ''即自动归档'':55B ''取消'':85B,94B ''取消类'':40B ''口径纠正'':1A,12B ''只能'':84B ''只需取消需求'':98B ''四道产物确认门'':28B ''备注已按此改写'':110B ''就是'':50B ''工作流指南原文'':65B ''已在'':124B ''已自动完成'':68B ''归档'':8A,19B,46B,82B ''归档是人工闸门'':95B ''影响'':86B ''我此前把'':87B ''拦截'':39B ''故对处于'':79B ''故本次修正只能落磁盘'':122B ''文档只能在'':118B ''无人再点'':64B ''无权'':100B ''无法重新登记'':123B ''无需再点归档'':69B ''是错的'':96B ''根本不是合法边'':78B ''正确说法是'':97B ''没有意义'':83B ''没有独立的'':45B ''治理留痕'':103B ''状态机事实'':70B ''用户指正'':10A,21B ''由'':61B ''由产物门'':37B ''的出边只有'':72B ''的需求谈'':81B ''自主完成'':63B ''被工具拒绝'':117B ''让'':88B ''这道门的落地动作'':52B ''重交会作废既有确认'':121B ''门'':47B ''阶段提交'':120B ''验收材料中显式记录'':126B ''验收通过'':51B,54B', '2026-09-20 14:38:25.022137', '2026-09-20 14:38:25.022137', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('0d524822-cbc2-43e0-ac8d-75b3c26b96ab', 'REQ-4842fe 失败告警机制修正（w-2105d331，2026-09-21）：用户裁定弹框指', 'REQ-4842fe 失败告警机制修正（w-2105d331，2026-09-21）：用户裁定弹框指令壳——FailureAlert 投递给来源窗口的文本从原始告警正文改为 popupInstructionFor 指令壳（指挥窗口 LLM 立即 ask_user_question 弹框：题干≤80字=哪条需求/停在哪张卡/为什么停，选项=重跑/退回上游/取消）。依据：用户原话「我希望通过弹框的方式来交流，要不用户不知道重点，发生了什么」。已落 §8 #18 + commit 49aba032。机制复用 CaptureHook 里程碑提醒 t09 的到时触发模式。', 'knowledge', '{REQ-4842fe,FailureAlert,弹框,w-2105d331}', NULL, '''-09'':9A,20B ''-21'':10A,21B ''18'':50B ''2026'':8A,19B ''2105d331'':7A,18B ''4842fe'':3A,14B ''49aba032'':52B ''8'':49B ''80字'':35B ''ask'':30B ''capturehook'':54B ''commit'':51B ''failurealert'':23B ''llm'':28B ''popupinstructionfor'':25B ''question'':32B ''req'':2A,13B ''req-4842fe'':1A,12B ''t09'':56B ''user'':31B ''w'':6A,17B ''w-2105d331'':5A,16B ''为什么停'':38B ''依据'':43B ''停在哪张卡'':37B ''发生了什么'':47B ''取消'':42B ''哪条需求'':36B ''失败告警机制修正'':4A,15B ''已落'':48B ''弹框'':33B ''我希望通过弹框的方式来交流'':45B ''投递给来源窗口的文本从原始告警正文改为'':24B ''指令壳'':26B ''指挥窗口'':27B ''机制复用'':53B ''用户原话'':44B ''用户裁定弹框指'':11A ''用户裁定弹框指令壳'':22B ''的到时触发模式'':57B ''立即'':29B ''要不用户不知道重点'':46B ''退回上游'':41B ''选项'':39B ''里程碑提醒'':55B ''重跑'':40B ''题干'':34B', '2026-09-21 03:05:23.999919', '2026-09-21 03:05:23.999919', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('d3f30707-e7e7-4ad0-a287-fb92c167d4e4', '【工程发现 · w-878da638 · 2026-09-20】agent-dh 仓库存在误提交的嵌', '【工程发现 · w-878da638 · 2026-09-20】agent-dh 仓库存在误提交的嵌套目录 agent-dh/agent-dh/（内含 docs/INDEX.md、docs/README.md、scripts/）。它会让 scripts/docs_index.py 的 root 探测（ad = join(root,''agent-dh'') if isdir else root）在 cwd=agent-dh 时误判 ad=agent-dh/agent-dh：①把「全站页面索引」与 wiki 首页自动区写到嵌套目录（git status 里显示为 agent-dh/agent-dh/docs/* 被改）；②随后在 agent-dh/docs/work-logs/README.md（嵌套路径不存在）上 FileNotFoundError 崩溃、退出码 1。复现：cd agent-dh && python3 scripts/docs_index.py → EXIT=1 且嵌套目录被写。正确用法：cd pi-investment && python3 agent-dh/scripts/docs_index.py（root 探测才命中真正的 agent-dh/docs），实测 EXIT=0。处置：已 git checkout 还原被误写的两个嵌套文件；未改脚本（属其他窗口/基础设施，登记线索待裁）。', 'knowledge', '{docs_index,agent-dh,嵌套目录,误提交,REQ-e3b6a0,w-878da638}', NULL, '''-09'':6A,17B ''-20'':7A,18B ''/agent-dh'':26B,56B ''/agent-dh/docs'':68B ''/docs'':106B ''/docs/work-logs/readme.md'':74B ''/scripts/docs_index.py'':100B ''0'':109B ''1'':80B,89B ''2026'':5A,16B ''878da638'':4A,15B ''ad'':36B,52B ''agent'':9A,20B,24B,40B,49B,54B,66B,72B,84B,98B,104B ''agent-dh'':8A,19B,23B,39B,48B,53B,65B,71B,83B,97B,103B ''cd'':82B,92B ''checkout'':113B ''cwd'':47B ''dh'':10A,21B,25B,41B,50B,55B,67B,73B,85B,99B,105B ''docs/index.md'':28B ''docs/readme.md'':29B ''else'':44B ''exit'':88B,108B ''filenotfounderror'':77B ''git'':62B,112B ''if'':42B ''investment'':95B ''isdir'':43B ''join'':37B ''pi'':94B ''pi-investment'':93B ''python3'':86B,96B ''root'':34B,38B,45B,101B ''scripts'':30B ''scripts/docs_index.py'':32B,87B ''status'':63B ''w'':3A,14B ''w-878da638'':2A,13B ''wiki'':60B ''上'':76B ''与'':59B ''且嵌套目录被写'':90B ''仓库存在误提交的嵌'':11A ''仓库存在误提交的嵌套目录'':22B ''全站页面索引'':58B ''内含'':27B ''在'':46B ''基础设施'':117B ''处置'':110B ''复现'':81B ''它会让'':31B ''实测'':107B ''属其他窗口'':116B ''崩溃'':78B ''嵌套路径不存在'':75B ''工程发现'':1A,12B ''已'':111B ''把'':57B ''探测'':35B ''探测才命中真正的''