INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('19abb2ba-a990-43be-9356-6eb864f795e4', 'git 协作教训补充（2026-09-20，w-ae7eb4c0，同日第二次）：①`git add ', 'git 协作教训补充（2026-09-20，w-ae7eb4c0，同日第二次）：①`git add <paths>` 任一 pathspec 不存在会**整体失败**（一个都不加），且 `2>/dev/null` 会把报错吞掉——本次 lib/client.d.ts 不存在导致整个 add 静默失败，commit 只打包了他人已暂存的删除；②add 与 commit 不要链在同一命令里，add 后必须单独 `git diff --cached --stat` 确认暂存内容=预期再 commit；③共享工作区他人暂存的东西不要替他提交——restore --staged 退回工作区让他自己处理。', 'experience', '{git,协作,提交纪律}', NULL, '''-09'':4A,15B ''-20'':5A,16B ''/dev/null'':30B ''2'':29B ''2026'':3A,14B ''add'':11A,22B,35B,39B,43B ''ae7eb4c0'':8A,19B ''cached'':47B ''commit'':37B,41B,51B ''diff'':46B ''git'':1A,10A,12B,21B,45B ''lib/client.d.ts'':33B ''pathspec'':24B ''restore'':53B ''staged'':54B ''stat'':48B ''w'':7A,18B ''w-ae7eb4c0'':6A,17B ''一个都不加'':27B ''不存在会'':25B ''不存在导致整个'':34B ''不要链在同一命令里'':42B ''与'':40B ''且'':28B ''任一'':23B ''会把报错吞掉'':31B ''共享工作区他人暂存的东西不要替他提交'':52B ''协作教训补充'':2A,13B ''只打包了他人已暂存的删除'':38B ''同日第二次'':9A,20B ''后必须单独'':44B ''整体失败'':26B ''本次'':32B ''确认暂存内容'':49B ''退回工作区让他自己处理'':55B ''静默失败'':36B ''预期再'':50B', '2026-09-20 17:37:16.888828', '2026-09-20 17:37:16.888828', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('d34bbe15-b08e-4bcb-9ac6-7e7d3ce994d0', 'reqboard 死锁根因与修复（2026-09-20，w-ae7eb4c0，REQ-6cbbf7 ', 'reqboard 死锁根因与修复（2026-09-20，w-ae7eb4c0，REQ-6cbbf7 事件）：需求未经计划批准进入 decomposing 后形成三面互锁——提计划要 design 态、离开 decomposing 要 decomposition 产物、拆卡要批准计划；连人工「取消」都被 assertArtifactGates 的产物存在门拦截（missing_artifact），且 UI 操作条只在 draft 渲染取消按钮。修复（b2b37d9b）：①assertArtifactGates 对 to=canceled 首行早退豁免（放弃路径不适用「节点完成=产物就位」闸门，与 gate-post-chain「取消不进链」对齐）；②操作条「立项取消」更名置首、全在途态渲染。验证：artifact-gates 路由级用例 3 条（对照组 →implementing 仍 400 missing_artifact）+ 视图用例 3 条 + agent actor 仍 403。教训：闸门设计要区分「推进路径」与「放弃路径」，放弃路径必须永远可达，否则异常状态不可恢复。', 'experience', '{reqboard,dsh-pmboard,闸门设计,死锁,REQ-6cbbf7}', NULL, '''-09'':4A,15B ''-20'':5A,16B ''2026'':3A,14B ''3'':75B,84B ''400'':80B ''403'':89B ''6cbbf7'':11A,22B ''actor'':87B ''ae7eb4c0'':8A,19B ''agent'':86B ''artifact'':42B,72B,82B ''artifact-gates'':71B ''assertartifactgates'':39B,50B ''b2b37d9b'':49B ''canceled'':53B ''chain'':63B ''decomposing'':25B,31B ''decomposition'':33B ''design'':28B ''draft'':46B ''gate'':61B ''gate-post-chain'':60B ''gates'':73B ''implementing'':78B ''missing'':41B,81B ''post'':62B ''req'':10A,21B ''req-6cbbf7'':9A,20B ''reqboard'':1A,12B ''to'':52B ''ui'':44B ''w'':7A,18B ''w-ae7eb4c0'':6A,17B ''与'':59B,93B ''且'':43B ''事件'':23B ''产物'':34B ''产物就位'':57B ''仍'':79B,88B ''修复'':48B ''全在途态渲染'':69B ''取消'':37B ''取消不进链'':64B ''后形成三面互锁'':26B ''否则异常状态不可恢复'':96B ''对'':51B ''对照组'':77B ''对齐'':65B ''态'':29B ''拆卡要批准计划'':35B ''推进路径'':92B ''提计划要'':27B ''操作条'':66B ''操作条只在'':45B ''放弃路径'':94B ''放弃路径不适用'':55B ''放弃路径必须永远可达'':95B ''教训'':90B ''更名置首'':68B ''条'':76B,85B ''死锁根因与修复'':2A,13B ''渲染取消按钮'':47B ''的产物存在门拦截'':40B ''离开'':30B ''立项取消'':67B ''节点完成'':56B ''要'':32B ''视图用例'':83B ''路由级用例'':74B ''连人工'':36B ''都被'':38B ''闸门'':58B ''闸门设计要区分'':91B ''需求未经计划批准进入'':24B ''首行早退豁免'':54B ''验证'':70B', '2026-09-20 17:55:03.281095', '2026-09-20 17:55:03.281095