INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('5bae97da-fd5f-42b8-a2e2-d8051d4018a7', '【智能执行「我来解决」不能选窗口 · 根因与修复闭环（2026-09-20，investor/w-6', '【智能执行「我来解决」不能选窗口 · 根因与修复闭环（2026-09-20，investor/w-6faac762）】现象：点错误事件「我来解决」弹 toast 但不出窗口列表（用户实证 18:32 两连击，DB 显示两事件 claim 成功 assignee=w-6faac762 但无投递）。根因双保险修复：①会话候选为空陷阱——sessionCandidates() 返回 [] 时旧代码跳过选择器直接静默直投主窗口（用户感知=不能选窗口）；修复=solve-kit openPicker 候选为空时回退 /online-windows 清单合成候选（label=w-XXXX 短码），仅在连在线清单都拿不到时才直投。②异步锚点归零——openPicker 的 renderPop 在 await online 之后才取 anchor.getBoundingClientRect()，而错误事件流程 claim 后立刻 fetchErrPage 静默重绘列表会让锚点脱离文档、rect 归零，弹层飞到视口左上角不可见；修复=openPicker 同步捕获 anchorRect 再进异步，且 left 钳位 min 6px。③board-mount sessionCandidates 加空候选诊断日志（快照 keys/ids/items/byId/rows/archived 计数），下次复发可直接看控制台定位过滤层。文件：packages/solve-kit/src/client/index.ts、packages/pages/execution/src/client/board-mount.ts；execution+holdings bundle 已重建（标记验证），wip 分支 agent-self/20260920-204418，测试 51/51。教训：『X 为空时静默降级到默认行为』是 UI 陷阱——降级路径要让用户可感知（toast/日志），且异步间隙里禁止再读 DOM 几何（先同步捕获）。', 'knowledge', '{solve-kit,picker,选窗口,dashboard-execution,根因,w-6faac762}', NULL, '''-09'':6A,14B ''-20'':7A,15B ''/20260920-204418'':106B ''/online-windows'':49B ''18'':24B ''2026'':5A,13B ''32'':25B ''51/51'':108B ''6faac762'':34B ''6px'':83B ''agent'':104B ''agent-self'':103B ''anchor.getboundingclientrect'':65B ''anchorrect'':77B ''assignee'':31B ''await'':62B ''board'':85B ''board-mount'':84B ''bundle'':98B ''claim'':29B,67B ''db'':27B ''dom'':119B ''execution'':96B ''fetcherrpage'':69B ''holdings'':97B ''investor/w-6'':8A ''investor/w-6faac762'':16B ''keys/ids/items/byid/rows/archived'':90B ''kit'':46B ''label'':51B ''left'':80B ''min'':82B ''mount'':86B ''online'':63B ''openpicker'':47B,58B,75B ''packages/pages/execution/src/client/board-mount.ts'':95B ''packages/solve-kit/src/client/index.ts'':94B ''rect'':71B ''renderpop'':60B ''self'':105B ''sessioncandidates'':38B,87B ''solve'':45B ''solve-kit'':44B ''toast'':21B,116B ''ui'':113B ''w'':33B,53B ''w-6faac762'':32B ''w-xxxx'':52B ''wip'':101B ''x'':110B ''xxxx'':54B ''下次复发可直接看控制台定位过滤层'':92B ''不能选窗口'':3A,11B,42B ''且'':79B ''且异步间隙里禁止再读'':118B ''两连击'':26B ''为空时静默降级到默认行为'':111B ''之后才取'':64B ''仅在连在线清单都拿不到时才直投'':56B ''会话候选为空陷阱'':37B ''但不出窗口列表'':22B ''但无投递'':35B ''修复'':43B,74B ''候选为空时回退'':48B ''先同步捕获'':121B ''再进异步'':78B ''几何'':120B ''分支'':102B ''加空候选诊断日志'':88B ''同步捕获'':76B ''后立刻'':68B ''在'':61B ''已重建'':99B ''异步锚点归零'':57B ''弹'':20B ''弹层飞到视口左上角不可见'':73B ''归零'':72B ''快照'':89B ''成功'':30B ''我来解决'':2A,10B,19B ''教训'':109B ''文件'':93B ''日志'':117B ''时旧代码跳过选择器直接静默直投主窗口'':40B ''是'':112B ''显示两事件'':28B ''智能执行'':1A,9B ''标记验证'':100B ''根因与修复闭环'':4A,12B ''根因双保险修复'':36B ''测试'':107B ''清单合成候选'':50B ''点错误事件'':18B ''现象'':17B ''用户实证'':23B ''用户感知'':41B ''的'':59B ''短码'':55B ''而错误事件流程'':66B ''计数'':91B ''返回'':39B ''钳位'':81B ''降级路径要让用户可感知'':115B ''陷阱'':114B ''静默重绘列表会让锚点脱离文档'':70B', '2026-09-20 20:50:09.157614', '2026-09-20 20:50:09.157614', '{}');
