INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('38adfe60-de0f-440e-8ee9-5d8314124096', '【每日蒸馏·evolution-distill-daily】2026-09-22 23:00 CST', '【每日蒸馏·evolution-distill-daily】2026-09-22 23:00 CST（触发 15:00Z），账户 agent_brain，模式 auto_apply=false（预览）。
