INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('efc3b210-5ca7-4bc6-af77-afb343ddc614', '【根因·reqboard 自动链恒 engine_unavailable（2026-09-22 查实', '【根因·reqboard 自动链恒 engine_unavailable（2026-09-22 查实，窗口 w-2c955dd9 / REQ-260922213356-4a45）】引擎服务 workflowEngine 由 @deepseek-ai/dsh-workflow-ptc 提供，dsh-web-app bundle 默认 `workflow-ptc: disabled: true`；agent-dh profile 的 config/cordis.yml 只把 `workflow-worker-thread` 置 disabled:false，而该 id 在 dsh 0.1.6-alpha.2 已不存在（base/web-app patch 与 dsh 包依赖均无，属 0.1.5 升级遗留死行）→ 引擎从未挂载，pmboard 的 ctx.inject([''workflowEngine'']) 拿到 undefined，子卡执行恒返回 ok:false reason=engine_unavailable。已改：config/cordis.yml 与 .dsh-data/profiles/agent-dh/cordis.patch.yml 各把该行换成 `workflow-ptc / disabled: false`（各留备份 *.bak-workflow-ptc-20260922-234606，YAML 已校验）；生效需重启 :13080（配置不热加载），重启动作待用户拍板。证据：台账 advance.history RUN_SUBTASK failed + 两处 patch grep。', 'experience', '{reqboard,workflowEngine,workflow-ptc,dsh-0.1.6,自动链,REQ-260922213356-4a45}', NULL, '''-09'':7A,16B ''-22'':8A,17B ''-234606'':107B ''-260922213356'':24B ''-4'':25B ''/dsh-workflow-ptc'':33B ''/profiles/agent-dh/cordis.patch.yml'':94B ''0.1.5'':73B ''0.1.6'':64B ''13080'':111B ''2026'':6A,15B ''20260922'':106B ''2c955dd9'':22B ''a45'':26B ''advance.history'':116B ''agent'':47B ''agent-dh'':46B ''ai'':32B ''alpha.2'':65B ''app'':38B ''bak'':103B ''bak-workflow-ptc'':102B ''base/web-app'':67B ''bundle'':39B ''config/cordis.yml'':51B,89B ''ctx.inject'':78B ''data'':93B ''deepseek'':31B ''deepseek-ai'':30B ''dh'':48B ''disabled'':44B,58B,99B ''dsh'':36B,63B,70B,92B ''dsh-data'':91B ''dsh-web-app'':35B ''engine'':4A,13B,86B ''failed'':119B ''false'':59B,84B,100B ''grep'':122B ''id'':61B ''ok'':83B ''patch'':68B,121B ''pmboard'':76B ''profile'':49B ''ptc'':43B,98B,105B ''reason'':85B ''req'':23B ''reqboard'':2A,11B ''run'':117B ''subtask'':118B ''thread'':56B ''true'':45B ''unavailable'':5A,14B,87B ''undefined'':81B ''w'':21B ''w-2c955dd9'':20B ''web'':37B ''worker'':55B ''workflow'':42B,54B,97B,104B ''workflow-ptc'':41B,96B ''workflow-worker-thread'':53B ''workflowengine'':28B,79B ''yaml'':108B ''与'':69B,90B ''两处'':120B ''包依赖均无'':71B ''升级遗留死行'':74B ''只把'':52B ''台账'':115B ''各把该行换成'':95B ''各留备份'':101B ''在'':62B ''子卡执行恒返回'':82B ''属'':72B ''已不存在'':66B ''已改'':88B ''已校验'':109B ''引擎从未挂载'':75B ''引擎服务'':27B ''拿到'':80B ''提供'':34B ''查实'':9A,18B ''根因'':1A,10B ''生效需重启'':110B ''由'':29B ''的'':50B,77B ''窗口'':19B ''置'':57B ''而该'':60B ''自动链恒'':3A,12B ''证据'':114B ''配置不热加载'':112B ''重启动作待用户拍板'':113B ''默认'':40B', '2026-09-22 23:46:16.89976', '2026-09-22 23:46:16.89976', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('c566b872-e2ef-4d30-afba-1e5311341720', '【缺陷·reqboard 自动链漏传调用者 agent（2026-09-23 查实并修，w-2c95', '【缺陷·reqboard 自动链漏传调用者 agent（2026-09-23 查实并修，w-2c955dd9）】引擎装上后暴露第二层阻塞：AdvanceChain.runSubtaskStep 调 executeSubtask 时只传 {subtaskId, windowKey:''system''}，exec 一路没透传 → ExecuteTask 里 parent=input.exec?.agent 恒 undefined → workflow-ptc 读 request.parent.session 抛 ''Cannot read properties of undefined (reading \''session\'')''，被判 start_failed（REQBOARD_SUBTASK_GATE）。设计蓝图 REQ-4842fe/design/architecture.md §3 明写 `parent: exec.agent`，实现丢了这条线，且因引擎一直不可用而潜伏。修法（加法、可选参）：advanceRequirement/runSelection/runSubtaskStep 加可选 exec 并逐层透传；AdvanceTool 与 TaskExecuteTool 传 exec；新增 tests/advance-chain.test.ts 4.8 断言 run 的 parent === exec.agent。验证：5 个相关测试文件 45 passed、pmboard typecheck exit 0、tsdown 重建 dist 且产物含 parent: input.exec?.agent。另注：pmboard 运行态加载 dist/index.mjs（main 指向 dist），源码改动必须构建才生效；dist 备份 /tmp/pmboard-dist-backup-20260923-000350。', 'experience', '{reqboard,auto-chain,workflowEngine,exec.agent,REQ-4842fe,REQ-260922213356-4a45}', NULL, '''-09'':6A,17B ''-23'':7A,18B ''/design/architecture.md'':63B ''/tmp/pmboard-dist-backup-20260923-000350'':116B ''0'':98B ''2026'':5A,16B ''2c95'':11A ''2c955dd9'':22B ''3'':64B ''4.8'':84B ''45'':93B ''4842fe'':62B ''5'':91B ''advancechain.runsubtaskstep'':24B ''advancerequirement/runselection/runsubtaskstep'':73B ''advancetool'':77B ''agent'':4A,15B,37B,105B ''cannot'':46B ''dist'':101B,112B,114B ''dist/index.mjs'':109B ''exec'':31B,75B,81B ''exec.agent'':67B,89B ''executesubtask'':26B ''executetask'':33B ''exit'':97B ''failed'':55B ''gate'':58B ''input.exec'':36B,104B ''main'':110B ''of'':49B ''parent'':35B,66B,88B,103B ''passed'':94B ''pmboard'':95B,107B ''properties'':48B ''ptc'':42B ''read'':47B ''reading'':51B ''req'':61B ''req-4842fe'':60B ''reqboard'':2A,13B,56B ''request.parent.session'':44B ''run'':86B ''session'':52B ''start'':54B ''subtask'':57B ''subtaskid'':28B ''system'':30B ''taskexecutetool'':79B ''tests/advance-chain.test.ts'':83B ''tsdown'':99B ''typecheck'':96B ''undefined'':39B,50B ''w'':10A,21B ''w-2c95'':9A ''w-2c955dd9'':20B ''windowkey'':29B ''workflow'':41B ''workflow-ptc'':40B ''一路没透传'':32B ''与'':78B ''且产物含'':102B ''且因引擎一直不可用而潜伏'':69B ''个相关测试文件'':92B ''传'':80B ''修法'':70B ''加可选'':74B ''加法'':71B ''另注'':106B ''可选参'':72B ''备份'':115B ''实现丢了这条线'':68B ''并逐层透传'':76B ''引擎装上后暴露第二层阻塞'':23B ''恒'':38B ''抛'':45B ''指向'':111B ''断言'':85B ''新增'':82B ''时只传'':27B ''明写'':65B ''查实并修'':8A,19B ''源码改动必须构建才生效'':113B ''的'':87B ''缺陷'':1A,12B ''自动链漏传调用者'':3A,14B ''被判'':53B ''设计蓝图'':59B ''读'':43B ''调'':25B ''运行态加载'':108B ''里'':34B ''重建'':100B ''验证'':90B', '2026-09-23 00:05:23.709475', '2026-09-23 00:05:23.709475', '{}');
