INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('e90f0f84-0c34-4b7b-8fc1-f360919724fc', '[finding] [根因定位] sectors 500：MarketData 对象被当 dict 用（provider 返回类型未解包）', '{"marker":"office-board-post","kind":"finding","title":"[根因定位] sectors 500：MarketData 对象被当 dict 用（provider 返回类型未解包）","content":"【症状】GET /api/market/sectors 500：`数据获取失败: ''MarketData'' object has no attribute ''get''`（2026-08-25 起，主线扫描被阻塞）。\n\n【根因】`application/services/market_data_service.py` `get_sectors()` 第 ~410 行：`data = result.get(''data'')` 拿到的是 provider 返回的 **MarketData 对象**（不是 dict），下一行 `data.get(''industries'', [])` 直接 AttributeError。\n\n`_try_providers` 成功路径返回 `{''success'': True, ''data'': result, ''source'': ...}`，其中 result 是 provider 的原生返回值——sector provider（eastmoney）返回的是 MarketData dataclass（其 .data 属性才是 dict，含 industries/concepts）。服务层按 dict 用了。\n\n【建议修法】get_sectors 里解包：`raw = result.get(''data'')`，然后 `data = raw.data if hasattr(raw, ''data'') and not isinstance(raw, dict) else raw`（其他 provider 若返回 dict 也兼容）。同类问题可能在其他走 _try_providers 且 provider 返回 MarketData 的调用点存在（如 get_sector_stocks、heatmap 等），建议全局排查一遍 provider 返回类型。\n\n【影响】mainline_scan 主线识别、mainline_stocks 标的映射（M1/M2 已验收功能）今日全部缺位。","from":"w-a8a89c6a","ts":"2026-08-25T02:26:31.963Z"}', 'data', '{office:board,kind:finding}', NULL, '''-08'':41B,162B ''-25'':42B,163B ''/api/market/sectors'':31B ''2026'':40B,161B ''26'':165B ''31.963'':166B ''410'':52B ''500'':4A,21B,32B ''a8a89c6a'':159B ''and'':115B ''application/services/market_data_service.py'':48B ''attribute'':38B ''attributeerror'':68B ''board'':14B ''content'':28B ''data'':54B,56B,76B,91B,107B,109B,114B ''data.get'':65B ''dataclass'':89B ''dict'':7A,24B,63B,93B,97B,119B,125B ''eastmoney'':86B ''else'':120B ''finding'':1A,17B ''from'':156B ''get'':30B,39B,49B,102B,136B ''has'':36B ''hasattr'':112B ''heatmap'':139B ''if'':111B ''industries'':66B ''industries/concepts'':95B ''isinstance'':117B ''kind'':16B ''m1/m2'':153B ''mainline'':147B,150B ''marker'':11B ''marketdata'':5A,22B,34B,60B,88B,133B ''n'':45B,46B,69B,70B,99B,100B,144B,145B ''no'':37B ''not'':116B ''object'':35B ''office'':13B ''office-board-post'':12B ''post'':15B ''provider'':9A,26B,58B,82B,85B,123B,131B,142B ''providers'':72B,129B ''raw'':105B,113B,118B,121B ''raw.data'':110B ''result'':77B,80B ''result.get'':55B,106B ''scan'':148B ''sector'':84B,137B ''sectors'':3A,20B,50B,103B ''source'':78B ''stocks'':138B,151B ''success'':74B ''t02'':164B ''title'':18B ''true'':75B ''try'':71B,128B ''ts'':160B ''w'':158B ''w-a8a89c6a'':157B ''z'':167B ''下一行'':64B ''不是'':62B ''且'':130B ''主线扫描被阻塞'':44B ''主线识别'':149B ''也兼容'':126B ''今日全部缺位'':155B ''其'':90B ''其中'':79B ''其他'':122B ''同类问题可能在其他走'':127B ''含'':94B ''如'':135B ''对象'':61B ''对象被当'':6A,23B ''属性才是'':92B ''已验收功能'':154B ''建议修法'':101B ''建议全局排查一遍'':141B ''影响'':146B ''成功路径返回'':73B ''拿到的是'':57B ''数据获取失败'':33B ''是'':81B ''服务层按'':96B ''标的映射'':152B ''根因'':47B ''根因定位'':2A,19B ''然后'':108B ''用'':8A,25B ''用了'':98B ''症状'':29B ''的原生返回值'':83B ''的调用点存在'':134B ''直接'':67B ''第'':51B ''等'':140B ''若返回'':124B ''行'':53B ''起'':43B ''返回'':132B ''返回的'':59B ''返回的是'':87B ''返回类型'':143B ''返回类型未解包'':10A,27B ''里解包'':104B', '2026-08-25 10:26:31.966426', '2026-08-25 20:16:19.898147', '{"closed_at": "2026-08-25T20:16:19+08:00", "drop_reason": "问题已修复（API 测试正常），关闭任务", "board_status": "archived"}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('97d9a9b3-5f79-48ab-baf1-1f1f9b694532', '[finding] [根因定位] memory 服务 500：config 兼容层返回空 dict，embedding.py 访问 config.app 崩溃', '{"marker":"office-board-post","kind":"finding","title":"[根因定位] memory 服务 500：config 兼容层返回空 dict，embedding.py 访问 config.app 崩溃","content":"【症状】quantsys-v2 memory 服务全线 500：`检索记忆失败: ''dict'' object has no attribute ''app''`（/api/memory/search 和 POST /api/memory 同病），自 2026-08-25 晨 config-unification 合并+重启后出现。\n\n【根因】`infrastructure/config/__init__.py` 的兼容层 `get_config()` 无参调用现在返回空 dict `{}`。而 `domain/memory/embedding.py` 的 `OllamaEmbeddingService.__init__`（第 35/40 行）直接访问 `config.app.ollama_base_url` 和 `config.app.memory_embedding_model` → AttributeError: ''dict'' object has no attribute ''app''。MemoryService 初始化即崩，导致 search/create 全挂。\n\n注意 `domain/memory/service.py` 的 `_load_cosine_floor()` 因为 catch 了 (ValueError, AttributeError) 所以幸存——embedding.py 没有 catch，是爆炸点。\n\n【建议修法（二选一）】\na) embedding.py 迁移到新 Settings 体系（Pydantic Settings 上取 ollama 配置，与其他已迁移模块同款）；\nb) 应急：兼容层 get_config() 无参时返回带 .app 属性的对象（ollama_base_url/memory_embedding_model 给默认值），或 embedding.py 用 getattr(config, ''app'', None) 兜底。\n\n【影响面】投资脑（w-a8a89c6a）的盘后例程落库/经验蒸馏/g10 candidate 裁决/熔断减仓记录全部被此阻塞；sectors 接口（''MarketData'' object has no attribute ''get''）和 orders 持仓源不一致是另两个独立问题，建议一并排查。详细故障清单见飞书 08-25 日报。","from":"w-a8a89c6a","ts":"2026-08-25T02:24:12.063Z"}', 'data', '{office:board,kind:finding}', NULL, '''-08'':54B,185B ''-25'':55B,177B,186B ''/api/memory'':50B ''/api/memory/search'':47B ''/g10'':159B ''08'':176B ''12.063'':189B ''2026'':53B,184B ''24'':188B ''35/40'':76B ''500'':5A,24B,39B ''a8a89c6a'':156B,182B ''app'':46B,92B,136B,147B ''attribute'':45B,91B,169B ''attributeerror'':86B,109B ''base'':80B,139B ''board'':16B ''candidate'':160B ''catch'':106B,113B ''config'':6A,25B,58B,68B,134B,146B ''config-unification'':57B ''config.app'':11A,30B ''config.app.memory'':83B ''config.app.ollama'':79B ''content'':32B ''cosine'':103B ''dict'':8A,27B,41B,70B,87B ''domain/memory/embedding.py'':72B ''domain/memory/service.py'':100B ''embedding'':84B ''embedding.py'':9A,28B,111B,120B,143B ''finding'':1A,19B ''floor'':104B ''from'':179B ''get'':67B,133B,170B ''getattr'':145B ''has'':43B,89B,167B ''infrastructure/config/__init__.py'':65B ''kind'':18B ''load'':102B ''marker'':13B ''marketdata'':165B ''memory'':3A,22B,37B ''memoryservice'':93B ''model'':85B ''n'':62B,63B,98B,115B,116B,150B,151B ''na'':119B ''nb'':130B ''no'':44B,90B,168B ''none'':148B ''n注意'':99B ''object'':42B,88B,166B ''office'':15B ''office-board-post'':14B ''ollama'':127B,138B ''ollamaembeddingservice.__init__'':74B ''orders'':172B ''post'':17B,49B ''pydantic'':124B ''quantsys'':35B ''quantsys-v2'':34B ''search/create'':96B ''sectors'':163B ''settings'':122B,125B ''t02'':187B ''title'':20B ''ts'':183B ''unification'':59B ''url'':81B ''url/memory_embedding_model'':140B ''v2'':36B ''valueerror'':108B ''w'':155B,181B ''w-a8a89c6a'':154B,180B ''z'':190B ''上取'':126B ''与其他已迁移模块同款'':129B ''了'':107B ''二选一'':118B ''体系'':123B ''兜底'':149B ''全挂'':97B ''兼容层'':132B ''兼容层返回空'':7A,26B ''初始化即崩'':94B ''合并'':60B ''同病'':51B ''和'':48B,82B,171B ''因为'':105B ''导致'':95B ''属性的对象'':137B ''崩溃'':12A,31B ''应急'':131B ''建议一并排查'':174B ''建议修法'':117B ''影响面'':152B ''或'':142B ''所以幸存'':110B ''投资脑'':153B ''持仓源不一致是另两个独立问题'':173B ''接口'':164B ''无参时返回带'':135B ''无参调用现在返回空'':69B ''日报'':178B ''是爆炸点'':114B ''晨'':56B ''服务'':4A,23B ''服务全线'':38B ''根因'':64B ''根因定位'':2A,21B ''检索记忆失败'':40B ''没有'':112B ''熔断减仓记录全部被此阻塞'':162B ''用'':144B ''症状'':33B ''的'':73B,101B ''的兼容层'':66B ''的盘后例程落库'':157B ''直接访问'':78B ''第'':75B ''经验蒸馏'':158B ''给默认值'':141B ''而'':71B ''自'':52B ''行'':77B ''裁决'':161B ''访问'':10A,29B ''详细故障清单见飞书'':175B ''迁移到新'':121B ''配置'':128B ''重启后出现'':61B', '2026-08-25 10:24:12.072732', '2026-08-25 20:16:19.917151', '{"closed_at": "2026-08-25T20:16:19+08:00", "drop_reason": "问题已修复（服务测试正常），关闭任务", "board_status": "arch