INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('5dc3bea1-505a-4bd8-9ce5-a82ac7cb6df4', 'REQ-260927144541-0481 根因修复（2026-09-27 17:35，窗口 ses', 'REQ-260927144541-0481 根因修复（2026-09-27 17:35，窗口 session-b71bb246）：实施链「反复失败 + 工具调用反复被掐断」查实为两个根因。①主根因：JobsPort 从未装配（index.ts 的 useCaseDeps 无 jobs 字段；DshJobsAdapter 只有 startJob/getJob，缺 deps.jobs 要求的 start/get/available）→ AdvanceChain.ts:412 永远走同步兼容路径：链在调用方工具栈里跑数分钟、绑定该 turn 的 abort signal（turn 一中断就 cancelled: workflow signal aborted），且成功也报「投递失败」。修：DshJobsAdapter 实现 JobsPort（start 原样透传 owner）+ index.ts 惰性注入 ctx.jobs；实测 ctx.jobs 对本 agent 可用（后台 bash 探针 jobid=bash-1）。②次根因：凭证门证据形态未传达给子代理——t-acd60f 的 integrate 子卡连续 2 次被判「属写入族，汇报未给出改动文件」（它按验收模板交了结论，门却要落盘文件）；修：buildSubtaskPrompt 如实写入「写入族/结论族」要求，不动门（守 decomposition §1.3）。验证：dsh-jobs-adapter 14 / apply-wiring 4 / execute-task 19 全绿，tsc 改动文件 0 错，dist 已重建（17:32）。证据文档：docs/requirements/REQ-260927144541-0481/tests/test-evidence.md §五。', 'knowledge', '{REQ-260927144541-0481,root-cause,JobsPort,dsh-pmboard,chain-reliability}', NULL, '''-0481'':3A,14B ''-09'':6A,17B ''-1'':81B ''-260927144541'':2A,13B ''-27'':7A,18B ''0'':123B ''1.3'':105B ''14'':111B ''17'':8A,19B,127B ''19'':119B ''2'':90B ''2026'':5A,16B ''32'':128B ''35'':9A,20B ''4'':115B ''abort'':51B ''aborted'':58B ''acd60f'':86B ''adapter'':110B ''advancechain.ts:412'':45B ''agent'':74B ''apply'':113B ''apply-wiring'':112B ''b71bb246'':24B ''bash'':77B,80B ''buildsubtaskprompt'':97B ''cancelled'':55B ''ctx.jobs'':70B,72B ''decomposition'':104B ''deps.jobs'':42B ''dist'':125B ''docs/requirements/req-260927144541-0481/tests/test-evidence.md'':130B ''dsh'':108B ''dsh-jobs-adapter'':107B ''dshjobsadapter'':38B,62B ''execute'':117B ''execute-task'':116B ''index.ts'':32B,68B ''integrate'':88B ''jobid'':79B ''jobs'':36B,109B ''jobsport'':30B,64B ''owner'':67B ''req'':1A,12B ''ses'':11A ''session'':23B ''session-b71bb246'':22B ''signal'':52B,57B ''start'':65B ''start/get/available'':44B ''startjob/getjob'':40B ''t'':85B ''t-acd60f'':84B ''task'':118B ''tsc'':121B ''turn'':49B,53B ''usecasedeps'':34B ''wiring'':114B ''workflow'':56B ''一中断就'':54B ''不动门'':102B ''且成功也报'':59B ''主根因'':29B ''五'':131B ''从未装配'':31B ''修'':61B,96B ''全绿'':120B ''写入族'':99B ''凭证门证据形态未传达给子代理'':83B ''原样透传'':66B ''反复失败'':26B ''只有'':39B ''可用'':75B ''后台'':76B ''如实写入'':98B ''子卡连续'':89B ''字段'':37B ''它按验收模板交了结论'':94B ''守'':103B ''实施链'':25B ''实测'':71B ''实现'':63B ''对本'':73B ''属写入族'':92B ''工具调用反复被掐断'':27B ''已重建'':126B ''惰性注入'':69B ''投递失败'':60B ''探针'':78B ''改动文件'':122B ''无'':35B ''查实为两个根因'':28B ''根因修复'':4A,15B ''次根因'':82B ''次被判'':91B ''永远走同步兼容路径'':46B ''汇报未给出改动文件'':93B ''的'':33B,50B,87B ''窗口'':10A,21B ''绑定该'':48B ''结论族'':100B ''缺'':41B ''要求'':101B ''要求的'':43B ''证据文档'':129B ''链在调用方工具栈里跑数分钟'':47B ''错'':124B ''门却要落盘文件'':95B ''验证'':106B', '2026-09-27 17:32:50.438233', '2026-09-27 17:32:50.438233', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('62091a51-94ca-438a-b217-85a84446c26b', 'REQ-260927144541-0481 投递失败根因（2026-09-27）：reqboard_', 'REQ-260927144541-0481 投递失败根因（2026-09-27）：reqboard_task_run 返回 REQBOARD_DISPATCH_FAILED「Cannot read properties of undefined (reading ''bind'')」。根因=适配层契约错配：DshJobsAdapter.start() 把应用层 async 执行函数直接当 DSH @deepseek-ai/dsh-jobs 的 JobStart.run 传入，而 DSH 要求 run() **同步返回 JobHooks** {cancel(reason?), done, readOutput?}（dsh-jobs-local/lib/index.js:138 调用 run()，:152 执行 hooks.cancel.bind(hooks)）→ async run 返回 Promise，hooks.cancel=undefined → undefined.bind TypeError。契约来源：@deepseek-ai/dsh-jobs lib/types/types.d.ts:39-83；JobOutcome status=completed|killed|failed。修法：在适配层把 (signal)=>Promise<void> 翻译为钩子（AbortController + done 结算，done 不得 reject），应用层端口形状不变。教训：①跨进程/跨框架的「执行函数」端口，必须对真实宿主的调用协议做契约测试（mock 只断言参数透传=没测）；②成功路径从未在线上直调时，「投递已修」只是假设（此前 integrate 联调全走未绑定错误分支）。证据文件：packages/web/dsh-pmboard/src/adapters/DshJobsAdapter.ts、tests/unit/dsh-jobs-adapter.test.ts（16 tests 绿）。', 'experience', '{REQ-260927144541-0481,dsh-pmboard,JobsPort,DSH,契约错配,根因}', NULL, '''-0481'':3A,11B ''-09'':6A,14B ''-260927144541'':2A,10B ''-27'':7A,15B ''-83'':81B ''/dsh-jobs'':40B,78B ''/lib/index.js'':58B ''138'':59B ''152'':62B ''16'':117B ''2026'':5A,13B ''39'':80B ''abortcontroller'':92B ''ai'':39B,77B ''async'':34B,66B ''bind'':29B ''cancel'':50B ''cannot'':23B ''completed'':84B ''deepseek'':38B,76B ''deepseek-ai'':37B,75B ''dispatch'':21B ''done'':52B,93B,95B ''dsh'':36B,45B,55B ''dsh-jobs-local'':54B ''dshjobsadapter.start'':32B ''failed'':22B,86B ''hooks'':65B ''hooks.cancel'':70B ''hooks.cancel.bind'':64B ''integrate'':112B ''jobhooks'':49B ''joboutcome'':82B ''jobs'':56B ''jobstart.run'':42B ''killed'':85B ''lib/types/types.d.ts'':79B ''local'':57B ''mock'':105B ''of'':26B ''packages/web/dsh-pmboard/src/adapters/dshjobsadapter.ts'':115B ''promise'':69B,90B ''properties'':25B ''read'':