INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('aa6c46c1-6838-40b7-9542-ec17264cee5c', 'REQ-260927144541-0481（对齐父卡/子卡工具面）实施链复盘（窗口 session-', 'REQ-260927144541-0481（对齐父卡/子卡工具面）实施链复盘（窗口 session-b71bb246，2026-09-27）：本需求 8 条父卡 × 4 子卡共 40 卡，从 11/20 推到 40/40 done 并 rollup 进 accepting。三条可复用教训：①【团队路径有状态】pmboard 自动链走 DSH Agent Teams：链派发子卡 run → 建/复用 team task → ensureWorker → awaitTeamTask（30min 墙）→ 读 Worker 写进台账的 lastReport。**stale 门 team_report_stale 要求 rep.at ≥ dispatchedAt**，所以顺序必须是「链先派发 → Worker 再写汇报 → complete」，反了必挂；用 claimedAt 判断「链是否已派发」是错的（claimedAt 在 run 成功后写）。②【宿主上限会做成死结】agent-team maxMembers=8（@deepseek-ai/dsh-experimental-agent-team-profile/cordis.patch.yml），而链每父卡 spawn 一个 Worker（名字 reqboard-<父卡id>，名册 append-only 无删除 API）→ **任何 ≥8 条父卡的需求，第 8 条必撞 TEAM_MEMBER_LIMIT 永久卡死**。已加用户层覆盖 maxMembers=16（active patch + config/cordis.yml 两处），根治应改为 Worker 跨父卡复用或 ensureWorker 显式降级。③【验收门三连拦截，都是模板/门禁口径问题】提交 verification 连续被拦：缺任务卡文档（t-c42bc0 台账 done 但卡文档没落盘，用 reqboard_task_report 补登即可生成骨架）→ 24 张卡的验收标准只有断言词无可执行锚点（子卡模板 STAGE_ACCEPTANCE 天然不过 acceptance-executable 门禁，须用 reqboard_task_move(acceptance=…) 逐卡补命令）→ 测试覆盖度 0%（需在 tests/*.md 用 covers: t-xxx 标注，40 条）。附带：reqboard_run_status 在无 active run 时返回 snapshot.runId=null 而 schema 声明 string → 绑定层拒收（属他线既存红）。', 'experience', '{pmboard,reqboard,agent-teams,TEAM_MEMBER_LIMIT,REQ-260927144541-0481,acceptance-gate}', NULL, '''-0481'':3A,11B ''-09'':20B ''-260927144541'':2A,10B ''-27'':21B ''/dsh-experimental-agent-team-profile/cordis.patch.yml'':91B ''0'':162B ''11/20'':30B ''16'':117B ''2026'':19B ''24'':145B ''30min'':53B ''4'':25B ''40'':27B,172B ''40/40'':32B ''8'':23B,87B,106B,109B ''acceptance'':149B,152B,159B ''acceptance-executable'':151B ''accepting'':37B ''active'':118B,179B ''agent'':43B,84B ''agent-team'':83B ''ai'':90B ''api'':104B ''append'':101B ''append-only'':100B ''awaitteamtask'':52B ''b71bb246'':18B ''c42bc0'':136B ''claimedat'':74B,78B ''complete'':71B ''config/cordis.yml'':120B ''covers'':167B ''deepseek'':89B ''deepseek-ai'':88B ''dispatchedat'':66B ''done'':33B,138B ''dsh'':42B ''ensureworker'':51B,125B ''executable'':153B ''lastreport'':58B ''limit'':113B ''maxmembers'':86B,116B ''md'':165B ''member'':112B ''move'':158B ''null'':183B ''only'':102B ''patch'':119B ''pmboard'':40B ''rep.at'':65B ''report'':62B,143B ''req'':1A,9B ''reqboard'':97B,141B,156B,175B ''rollup'':35B ''run'':46B,80B,176B,180B ''schema'':185B ''session'':8A,17B ''session-b71bb246'':16B ''snapshot.runid'':182B ''spawn'':93B ''stage'':148B ''stale'':59B,63B ''status'':177B ''string'':187B ''t'':135B,169B ''t-c42bc0'':134B ''t-xxx'':168B ''task'':50B,142B,157B ''team'':49B,61B,85B,111B ''teams'':44B ''tests'':164B ''verification'':131B ''worker'':56B,69B,95B,123B ''xxx'':170B ''一个'':94B ''三条可复用教训'':38B ''两处'':121B ''从'':29B ''任何'':105B ''但卡文档没落盘'':139B ''再写汇报'':70B ''写进台账的'':57B ''判断'':75B ''卡'':28B ''反了必挂'':72B ''台账'':137B ''名册'':99B ''名字'':96B ''团队路径有状态'':39B ''在'':79B ''在无'':178B ''墙'':54B ''声明'':186B ''复用'':48B ''天然不过'':150B ''子卡共'':26B ''子卡工具面'':5A,13B ''子卡模板'':147B ''实施链复盘'':6A,14B ''宿主上限会做成死结'':82B ''对齐父卡'':4A,12B ''属他线既存红'':189B ''已加用户层覆盖'':115B ''并'':34B ''建'':47B ''张卡的验收标准只有断言词无可执行锚点'':146B ''成功后写'':81B ''所以顺序必须是'':67B ''推到'':31B ''提交'':130B ''无删除'':103B ''时返回'':181B ''是错的'':77B ''显式降级'':126B ''本需求'':22B ''条'':173B ''条必撞'':110B ''条父卡'':24B ''条父卡的需求'':107B ''标注'':171B ''根治应改为'':122B ''永久卡死'':114B ''测试覆盖度'':161B ''父卡id'':98B ''用'':73B,140B,166B ''窗口'':7A,15B ''第'':108B ''绑定层拒收'':188B ''缺任务卡文档'':133B ''而'':184B ''而链每父卡'':92B ''自动链走'':41B ''补登即可生成骨架'':144B ''要求'':64B ''读'':55B ''跨父卡复用或'':124B ''进'':36B ''连续被拦'':132B ''逐卡补命令'':160B ''都是模板'':128B ''链先派发'':68B ''链是否已派发'':76B ''链派发子卡'':45B ''门'':60B ''门禁'':154B ''门禁口径问题'':129B ''附带'':174B ''需在'':163B ''须用'':155B ''验收门三连拦截'':127B', '2026-09-27 19:22:44.45732', '2026-09-27 19:22:44.45732', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('6ebf30cd-7676-41b5-87cb-edd13049a9d6', 'dsh-pmboard 验收流程两处实测缺陷（REQ-260927144541-0481 收尾时暴露', 'dsh-pmboard 验收流程两处实测缺陷（REQ-260927144541-0481 收尾时暴露，窗口 session-b71bb246，2026-09-27）：①【工具超时会静默丢弃已作答的验收裁决】reqboard_accept_sheet 是阻塞式弹框，且**在所有逐项裁决返回后才一次性落账**（AcceptSheet.ts：ask 返回 → 才写 sheet.items）。调用方若在等待期超时（PTC run_code 默认 120s）被中止，用户点击的整批答案随调用一起丢失、台账仍为 pending，我的第一批 10 个「通过」就是这么蒸发的——重试后必须把等待预算拉到接近 600s 才稳。建议改为逐项即时落账（每答一项写一次），或工具层明示最小等待预算。②【逐项裁决被按否定话术回报】逐项弹框也声明 gate=G4（AcceptSheet.ts:179），而 G4 的 post-chain 处理器 h4-resume.ts 只认 affirmative → 用户正常点「✅ 通过」却收到「【闸门待改进】G4 未通过，节点仍在 accepting」，第一次看到会以为点错了。建议逐项批次不声 G4（或按 verdict 语义分流文案），只在最终「验收通过并归档」那一次用 G4。', 'experience', '{pmboard,accept-sheet,G4,timeout,REQ-260927144541-0481}', NULL, '''-0481'':7A,15B ''-09'':22B ''-260927144541'':6A,14B ''-27'':23B ''10'':47B ''120s'':41B ''2026'':21B ''600s'':52B ''accept'':26B ''accepting'':79B ''acceptsheet.ts'':31B ''acceptsheet.ts:179'':61B ''affirmative'':71B ''ask'':32B ''b71bb246'':20B ''chain'':67B ''code'':39B ''dsh'':2A,10B ''dsh-pmboard'':1A,9B ''g4'':60B,63B,76B,82B,89B ''gate'':59B ''h4-resume.ts'':69B ''pending'':45B ''pmboard'':3A,11B ''post'':66B ''post-chain'':65B ''ptc'':37B ''req'':5A,13B ''reqboard'':25B ''run'':38B ''session'':19B ''session-b71bb246'':18B ''sheet'':27B ''sheet.items'':35B ''verdict'':84B ''且'':29B ''个'':48B ''却收到'':74B ''只在最终'':86B ''只认'':70B ''台账仍为'':44B ''在所有逐项裁决返回后才一次性落账'':30B ''处理器'':68B ''就是这么蒸发的'':50B ''工具超时会静默丢弃已作答的验收裁决'':24B ''建议改为逐项即时落账'':54B ''建议逐项批次不声'':81B ''我的第一批'':46B ''或工具层明示最小等待预算'':56B ''或按'':83B ''才写'':34B ''才稳'':53B ''收尾时暴露'':8A,16B ''是阻塞式弹框'':28B ''未通过'':77B ''每答一项写一次'':55B ''用户正常点'':72B ''用户点击的整批答案随调用一起丢失'':43B ''的'':64B ''窗口'':17B ''第一次看到会以为点错了'':80B ''而'':62B ''节点仍在'':78B ''被中止'':42B ''语义分流文案'':85B ''调用方若在等待期超时'':36B ''返回'':33B ''逐项弹框也声明'':58B ''逐项裁决被按否定话术回报'':57B ''通过'':49B,73B ''那一次用'':88B ''重试后必须把等待预算拉到接近'':51B ''闸门待改进'':75B ''验收流程两处实测缺陷'':4A,12B ''验收通过并归档'':87B ''默认'':40B', '2026-09-27 19:29:15.271562', '2026-09-27 19:29:15.271562', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('7f8288e8-e7b7-429f-a360-4dc7706a0046', 'dsh-pmboard G4 验收门「恒定误报」缺陷（REQ-260927144541-0481 收', 'dsh-pmboard G4 验收门「恒定误报」缺陷（REQ-260927144541-0481 收尾实测，窗口 session-b71bb246，2026-09-27）：现象——用户在验收弹框选「✅ 验收通过并归档」，需求确实已归档（台账 statusHistory: accepting→archived by human，43/43 验收项全过），但会话收到「【闸门待改进】G4 未通过，节点仍在 accepting」，让人以为点击没生效。根因——① G4 在 GateCatalog.ts:66-74 声明 autoAdvance=false（归档由 AcceptSheet 自己在弹框作答后完成，不进自动推进白名单）；② 判定肯定与否的 H1（application/gate/handlers/h1-advance.ts:34）拿「台账 requirement.status === ctx.to」当唯一依据；③ 弹框作答触发 gate post-chain 时归档尚未发生（AcceptSheet 的 questions.ask 先返回、post-chain 先跑，随后才 mutate 到 archived）→ status 仍是 accepting → verdict 恒为 negative → H4（h4-resume.ts:60-64）必然输出「待改进 + 节点仍在 from」。故对 autoAdvance=false 的门，H1 的状态判据在结构上不可能成立，属恒假断言，与用户选择无关。修法方向（三选一）：① 对 autoAdvance=false 的门，verdict 改由「作答是否命中肯定项标签」推导（AskConfirm.ts:288 已有 picked === optionLabels[0] 同款判据）；② 或让 AcceptSheet 在 post-chain 之前完成归档；③ 或 H4 对 per-item／自归档门特判文案。附带同源问题：逐项批次也声明 gate=G4（AcceptSheet.ts:179），而 G4 的 verdictShape 是 per-item，用户点「✅ 通过」同样收到「闸门待改进」，一天内两次误导。影响面：所有走验收单的 feature 需求都会看到这句假警报。', 'experience', '{pmboard,G4,h1-advance,h4-resume,false-negative,accept-sheet,REQ-260927144541-0481}', NULL, '''-0481'':10A,21B ''-09'':28B ''-260927144541'':9A,20B ''-27'':29B ''-64'':96B ''-74'':53B ''0'':123B ''2026'':27B ''34'':64B ''43/43'':40B ''accepting'':36B,47B,90B ''acceptsheet'':58B,76B,126B ''acceptsheet.ts:179'':143B ''application/gate/handlers/h1-advance.ts'':63B ''archived'':37B,87B ''askconfirm.ts:288'':119B ''autoadvance'':55B,102B,112B ''b71bb246'':26B ''by'':38B ''chain'':74B,82B,130B ''ctx.to'':68B ''dsh'':2A,13B ''dsh-pmboard'':1A,12B ''false'':56B,103B,113B ''feature'':159B ''from'':100B ''g4'':4A,15B,44B,50B,142B,145B ''gate'':71B,141B ''gatecatalog.ts:66'':52B ''h1'':62B,105B ''h4'':94B,133B ''h4-resume.ts:60'':95B ''human'':39B ''item'':137B,151B ''mutate'':85B ''negative'':93B ''optionlabels'':122B ''per'':136B,150B ''per-item'':135B,149B ''picked'':121B ''pmboard'':3A,14B ''post'':73B,81B,129B ''post-chain'':72B,80B,128B ''questions.ask'':78B ''req'':8A,19B ''requirement.status'':67B ''session'':25B ''session-b71bb246'':24B ''status'':88B ''statushistory'':35B ''verdict'':91B,115B ''verdictshape'':147B ''一天内两次误导'':156B ''三选一'':110B ''不进自动推进白名单'':60B ''与用户选择无关'':108B ''之前完成归档'':131B ''仍是'':89B ''但会话收到'':42B ''作答是否命中肯定项标签'':117B ''修法方向'':109B ''先跑'':83B ''先返回'':79B ''判定肯定与否的'':61B ''到'':86B ''台账'':34B,66B ''同样收到'':154B ''同款判据'':124B ''在'':51B,127B ''声明'':54B ''对'':111B,134B ''属恒假断言'':107B ''已有'':120B ''弹框作答触发'':70B ''归档由'':57B ''当唯一依据'':69B ''影响面'':157B ''待改进'':98B ''必然输出'':97B ''恒为'':92B ''恒定误报'':6A,17B ''或'':132B ''或让'':125B ''所有走验收单的'':158B ''拿'':65B ''推导'':118B ''收'':11A ''收尾实测'':22B ''改由'':116B ''故对'':101B ''时归档尚未发生'':75B ''是'':148B ''未通过'':45B ''根因'':49B ''现象'':30B ''用户在验收弹框选'':31B ''用户点'':152B ''的'':77B,146B ''的状态判据在结构上不可能成立'':106B ''的门'':104B,114B ''窗口'':23B ''缺陷'':7A,18B ''而'':144B ''自己在弹框作答后完成'':59B ''自归档门特判文案'':138B ''节点仍在'':46B,99B ''让人以为点击没生效'':48B ''逐项批次也声明'':140B ''通过'':153B ''闸门待改进'':43B,155B ''附带同源问题'':139B ''随后才'':84B ''需求确实已归档'':33B ''需求都会看到这句假警报'':160B ''验收通过并归档'':32B ''验收门'':5A,16B ''验收项全过'':41B', '2026-09-27 19:31:39.842184', '2026-09-27 19:31:39.842184', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('e1693d0b-083e-4652-ae78-50996266d193', '002007 neutral 2026-09-27 周度进化：evolution_run(strategy_id=202, symbol=002007, mod', '002007 交易经验（2026-09-27T12:10:18.536Z）
场景：2026-09-27 周度进化：evolution_run(strategy_id=202, symbol=002007, mode=propose, 2025-09-20~2026-09-20) 连续第二周诚实降级，degraded_reason 断言「基线回测零交易（total_trades=0），窗口无信号，拒绝以 0 收益为基线进化」。逐层复核后证伪该断言：直接 POST /api/backtest/strategy 得 equity 1,000,000→768,184.669、末日持仓市值 768,042、现金 142.67（明确已成交且仍持仓），而 totalTrades=0。反证三路——按策略代码逐字复现（pandas）得 5 个 buy 信号；引擎自身 IndicatorStrategyExecutor 在同数据上执行成功（signals 324 行）；quant.daily_klines 窗口内 241 根与 equityCurve 241 点一致。数据地基、策略参数、市场过滤（策略代码从不读 market_bear/csi300）全部无罪。
结果：neutral
教训：「零交易」不等于「没信号」：进化引擎用 total_trades<1 判定「窗口无信号」并降级整个 run，但回测服务的 trades 只在 SELL 分支 append（只记已平仓往返）、窗口结束不做强制平仓——于是「开仓但未平仓」的基线回测必然 total_trades=0 而被误判无信号。判别：若 equityCurve 有效且末点持仓市值>0 却报 totalTrades=0/trades=[]，即为记账口径缺陷而非无信号；跨层复用计数字段前先核对该字段的定义域（计数器名字 ≠ 被解释成的含义）。', 'experience', '{002007,neutral}', NULL, '''-09'':4A,18B,26B,39B ''-20'':40B ''-27'':5A,19B,27B ''/api/backtest/strategy'':57B ''0'':49B,52B,73B,130B,136B ''0/trades'':139B ''000'':61B,62B ''002007'':1A,13A,15B,35B ''042'':67B ''1'':60B,112B ''10'':21B ''142.67'':69B ''18.536'':22B ''184.669'':64B ''202'':11A,33B ''2025'':38B ''2026'':3A,17B,25B ''241'':91B,94B ''324'':86B ''5'':78B ''768'':63B,66B ''append'':122B ''bear/csi300'':101B ''buy'':80B ''degraded'':43B ''equity'':59B ''equitycurve'':93B,134B ''evolution'':7A,29B ''id'':10A,32B ''indicatorstrategyexecutor'':83B ''klines'':89B ''market'':100B ''mod'':14A ''mode'':36B ''neutral'':2A,104B ''pandas'':76B ''post'':56B ''propose'':37B ''quant.daily'':88B ''reason'':44B ''run'':8A,30B,116B ''sell'':120B ''signals'':85B ''strategy'':9A,31B ''symbol'':12A,34B ''t12'':20B ''total'':47B,110B,128B ''totaltrades'':72B,138B ''trades'':48B,111B,118B,129B ''z'':23B ''~2026-09-20'':41B ''不等于'':107B ''个'':79B ''于是'':125B ''交易经验'':16B ''但回测服务的'':117B ''信号'':81B ''全部无罪'':102B ''分支'':121B ''判别'':132B ''判定'':113B ''即为记账口径缺陷而非无信号'':140B ''却报'':137B ''反证三路'':74B ''只在'':119B ''只记已平仓往返'':123B ''周度进化'':6A,28B ''在同数据上执行成功'':84B ''场景'':24B ''基线回测零交易'':46B ''市场过滤'':98B ''并降级整个'':115B ''开仓但未平仓'':126B ''引擎自身'':82B ''得'':58B,77B ''拒绝以'':51B ''按策略代码逐字复现'':75B ''收益为基线进化'':53B ''教训'':105B ''数据地基'':96B ''断言'':45B ''明确已成交且仍持仓'':70B ''有效且末点持仓市值'':135B ''末日持仓市值'':65B ''根与'':92B ''没信号'':108B ''点一致'':95B ''现金'':68B ''的基线回测必然'':127B ''直接'':55B ''窗口内'':90B ''窗口无信号'':50B,114B ''窗口结束不做强制平仓'':124B ''策略代码从不读'':99B ''策略参数'':97B ''结果'':103B ''而'':71B ''而被误判无信号'':131B ''若'':133B ''行'':87B ''被解释成的含义'':143B ''计数器名字'':142B ''跨层复用计数字段前先核对该字段的定义域'':141B ''进化引擎用'':109B ''连续第二周诚实降级'':42B ''逐层复核后证伪该断言'':54B ''零交易'':106B', '2026-09-27 20:10:18.539223', '2026-09-27 20:10:18.539223', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('7343f771-762c-4c8a-bf1d-ef2064e8d4cb', '【周度进化·业绩归因】2026-09-21~09-27，投资脑自有账户 agent_brain **', '【周度进化·业绩归因】2026-09-21~09-27，投资脑自有账户 agent_brain **无交易层样本**：真实成交 0 笔（simulation_order 仅 2 笔工程验证单 54/55，submitted_by/decision_price/fill_price 全空）、自有决策评分 0 条（decision_scores(action=buy) 全量 27 条、matched 16、meanExcessPct -23.74%、lessonCoverage 1.0，但**全部 context.account=v14_simulation**，属策略线回填，不得当投资脑业绩先验）。按 R-016 因此**不新增/修改任何 R-xxx、信号分级阈值、仓位档位、止损线与拆单阈值**。本周缺口全部落在数据/工程通路，唯一定位到**回测引擎记账缺陷**：StrategyBacktestService.run_backtest_from_signals 的 trades 只在 SELL 分支 append（strategy_backtest_service.py:343/434），窗口结束**无强制平仓**，total_trades=len(trades)（:603）因此只计已平仓往返 → "开仓但未平仓"的基线回测被判成 total_trades=0 → strategy_evolution_service MIN_TRADES=1（:198）误读为"窗口无信号"并降级 evolution_run(202)（:201-202）。实证（2026-09-27）：POST /api/backtest/strategy（策略 202 / 002007 / 2025-09-20~2026-09-20）equityCurve 241 点收于 768,184.669、末日持仓市值 768,042、现金 142.67（明确已成交且仍持仓），而 totalTrades=0、trades=[]。反证三路排除其它嫌疑：按策略代码逐字 pandas 复现得 5 个 buy 信号；引擎自身 IndicatorStrategyExecutor 在同数据上执行成功（signals 324 行）；quant.daily_klines 同窗口 241 根与 equityCurve 241 点一致。结论：数据地基、策略参数、市场/bear 过滤（策略代码从不读 market_bear/csi300）均无罪。修补通道 = 工程（回测引擎），非策略参数、非基因组规则（SOP 禁止清单）。状态一致性（SOP 4.5）：validation_gate 11 watching / 0 转正 / 0 拒绝 / 11 延期（样本 0<3），异常 1 项"未登记版本"，连续两周复现且永不自动收敛。', 'knowledge', '{业绩归因,周度进化,回测引擎,evolution_run,total_trades,agent_brain,002007}', NULL, '''-016'':57B ''-09'':4A,13B,114B,122B ''-20'':123B ''-202'':111B ''-21'':5A,14B ''-23.74'':45B ''-27'':115B ''/434'':83B ''/api/backtest/strategy'':117B ''/bear'':166B ''0'':21B,33B,96B,138B,186B,188B,193B ''002007'':120B ''042'':132B ''1'':102B,196B ''1.0'':47B ''11'':184B,190B ''142.67'':134B ''16'':43B ''184.669'':129B ''198'':103B ''2'':26B ''201'':110B ''202'':109B,119B ''2025'':121B ''2026'':3A,12B,113B ''241'':126B,157B,160B ''27'':40B ''3'':194B ''324'':152B ''4.5'':181B ''