INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('e356c334-4c07-486d-b34b-f2bdb6debd45', '陈旧 advance run 锁无回收路径（reqboard 实施链在进程被 kill 后永久卡死）', '陈旧 advance run 锁无回收路径（reqboard 实施链在进程被 kill 后永久卡死）。2026-09-27 实测（w-3936d77f，REQ-260927202051-f6df / t-e77b06）：reqboard_task_run 报 REQBOARD_DISPATCH_FAILED「已有 run 在跑（run-1790521730304-pbbp4df）」，但 reqboard_run_status 同一 run 报 jobStatus=not_found（后台 job 不存在）。根因：锁只在 AdvanceChain.ts:365-378 的 finally 清理（进程被 quick_restart kill → 永不执行）；重投递判据 AdvanceChain.ts:416 只看 advance.runId 是否存在、不看过期时间（:411 的 advanceLockStaleMs=15min 只对 lockAt 提前返回 locked 生效），实测 lockAt 陈旧 27 分钟仍不放行；且无第二路可清——reqboard_clear_pause 只清 dive（ClearPause.ts:53-70）、orphan-collector.ts:49 是 TODO 桩、HTTP autorun 走同一个 deps.advance()。含义：「失败即暂停，人工处置后再次调用本工具续跑」这条恢复路径在 kill 场景下是死的；处置只能人工清台账 advance.runId/lockAt（需旧进程已死、新进程未 load() 的窗口，因为插件 boot 时急切 load：src/index.ts:132）。', 'experience', '{reqboard,实施链,advance-lock,断点续传,REQ-260927202051-f6df,w-3936d77f}', NULL, '''-09'':18B ''-1790521730304'':41B ''-260927202051'':25B ''-27'':19B ''-378'':59B ''-70'':95B ''/lockat'':113B ''132'':123B ''15min'':77B ''2026'':17B ''27'':86B ''3936d77f'':23B ''411'':74B ''advance'':2A,10B ''advance.runid'':71B,112B ''advance.runid/lockat'':111B ''advancechain.ts:365'':58B ''advancechain.ts:416'':69B ''advancelockstalems'':76B ''autorun'':101B ''boot'':119B ''clear'':90B ''clearpause.ts:53'':94B ''deps.advance'':103B ''dispatch'':35B ''dive'':93B ''e77b06'':29B ''f6df'':26B ''failed'':36B ''finally'':61B ''found'':52B ''http'':100B ''job'':54B ''jobstatus'':50B ''kill'':7A,15B,66B,108B ''load'':116B,121B ''lockat'':79B,84B ''locked'':81B ''not'':51B ''orphan-collector.ts:49'':96B ''pause'':91B ''pbbp4df'':42B ''quick'':64B ''req'':24B ''reqboard'':5A,13B,30B,34B,44B,89B ''restart'':65B ''run'':3A,11B,32B,38B,40B,45B,48B ''src/index.ts'':122B ''status'':46B ''t'':28B ''t-e77b06'':27B ''task'':31B ''todo'':98B ''w'':22B ''w-3936d77f'':21B ''不存在'':55B ''不看过期时间'':73B ''且无第二路可清'':88B ''人工处置后再次调用本工具续跑'':106B ''但'':43B ''分钟仍不放行'':87B ''只对'':78B ''只清'':92B ''只看'':70B ''同一'':47B ''后台'':53B ''后永久卡死'':8A,16B ''含义'':104B ''因为插件'':118B ''在跑'':39B ''场景下是死的'':109B ''处置只能人工清台账'':110B ''失败即暂停'':105B ''实施链在进程被'':6A,14B ''实测'':20B,83B ''已有'':37B ''报'':33B,49B ''提前返回'':80B ''新进程未'':115B ''时急切'':120B ''是'':97B ''是否存在'':72B ''根因'':56B ''桩'':99B ''永不执行'':67B ''清理'':62B ''生效'':82B ''的'':60B,75B ''的窗口'':117B ''走同一个'':102B ''这条恢复路径在'':107B ''进程被'':63B ''重投递判据'':68B ''锁只在'':57B ''锁无回收路径'':4A,12B ''陈旧'':1A,9B,85B ''需旧进程已死'':114B', '2026-09-27 23:37:02.429868', '2026-09-27 23:37:02.429868', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('2174eeef-7e63-47a7-b37b-066dac1150f2', '台账 migrations 迁移留痕会被"读路径不保留"的构建静默写丢；--verify 的退出码判', '台账 migrations 迁移留痕会被"读路径不保留"的构建静默写丢；--verify 的退出码判据必须在纯净副本上取证。2026-09-27 实测（w-3936d77f，REQ-260927202051-f6df）：活台账 .dsh-data/dsh-reqboard.json（schemaVersion 9、tasks 已移除、51 份 queue.json 已生成）却完全没有 migrations 字段 → migrate-ledger.ts --verify 退出码 1，首条问题「migrations 末条不是 {from:8,to:9}：undefined」。根因：v8→v9 --apply 在 22:55 执行（留痕已写入），但 22:58 才补上的 load() 保留逻辑（JsonLedgerRepository.ts:150-168）此前不存在，旧构建进程 load() 只重建 4 个字段，而落盘的是整册 draft ⇒ 第一次落盘即永久抹掉留痕；现 dist/index.mjs 已含 `...migrations !== void 0 ? { migrations } : {}`，补回后不再丢。真值仍在 dsh-reqboard.json.migrate-manifest-1790520911425.json（from/to/at/by），pre-v9 备份的 migrations=null，故补一条即复现迁移脚本写入结果。第二点：--verify 在跑过数小时运行期改动的活台账上**永远不为 0**（队列因链推进漂移、台账因评论/autoRun/artifact 漂移，脚本只归一化 migrations[].at）；实测把补好留痕的副本 + backup-1790520911425 重放，问题从 3 项降为 2 项，全是运行期漂移 ⇒ 验收标准「--verify 无差异、退出码 0」只能在 apply 后未被改动的纯净副本上取证。', 'experience', '{reqboard,migration,migrations-留痕,verify,REQ-260927202051-f6df,w-3936d77f}', NULL, '''-09'':16B ''-168'':69B ''-1790520911425'':111B ''-260927202051'':23B ''-27'':17B ''/autorun/artifact'':104B ''/dsh-reqboard.json'':29B ''0'':84B,101B,123B ''1'':44B ''2'':116B ''2026'':15B ''22'':58B,63B ''3'':114B ''3936d77f'':21B ''4'':74B ''51'':34B ''55'':59B ''58'':64B ''8'':49B ''9'':31B,51B ''apply'':56B,125B ''at'':108B ''backup'':110B ''data'':28B ''dist/index.mjs'':80B ''draft'':77B ''dsh'':27B ''dsh-data'':26B ''dsh-reqboard.json.migrate-manifest-1790520911425.json'':88B ''f6df'':24B ''from'':48B ''from/to/at/by'':89B ''jsonledgerrepository.ts:150'':68B ''load'':66B,72B ''migrate-ledger.ts'':41B ''migrations'':2A,9B,39B,46B,82B,85B,94B,107B ''null'':95B ''pre'':91B ''pre-v9'':90B ''queue.json'':36B ''req'':22B ''schemaversion'':30B ''tasks'':32B ''to'':50B ''undefined'':52B ''v8'':54B ''v9'':55B,92B ''verify'':6A,13B,42B,98B,120B ''void'':83B ''w'':20B ''w-3936d77f'':19B ''个字段'':75B ''份'':35B ''但'':62B ''保留逻辑'':67B ''全是运行期漂移'':118B ''却完全没有'':38B ''只能在'':124B ''只重建'':73B ''台账'':1A,8B ''台账因评论'':103B ''后未被改动的纯净副本上取证'':126B ''在'':57B ''在跑过数小时运行期改动的活台账上'':99B ''备份的'':93B ''字段'':40B ''实测'':18B ''实测把补好留痕的副本'':109B ''已含'':81B ''已生成'':37B ''已移除'':33B ''才补上的'':65B ''执行'':60B ''故补一条即复现迁移脚本写入结果'':96B ''无差异'':121B ''旧构建进程'':71B ''末条不是'':47B ''根因'':53B ''此前不存在'':70B ''永远不为'':100B ''活台账'':25B ''漂移'':105B ''现'':79B ''留痕已写入'':61B ''的构建静默写丢'':5A,12B ''的退出码判'':7A ''的退出码判据必须在纯净副本上取证'':14B ''真值仍在'':87B ''第一次落盘即永久抹掉留痕'':78B ''第二点'':97B ''而落盘的是整册'':76B ''脚本只归一化'':106B ''补回后不再丢'':86B ''读路径不保留'':4A,11B ''迁移留痕会被'':3A,10B ''退出码'':43B,122B ''重放'':112B ''问题从'':113B ''队列因链推进漂移'':102B ''项'':117B ''项降为'':115B ''首条问题'':45B ''验收标准'':119B', '2026-09-27 23:37:02.444095', '2026-09-27 23:37:02.444095', '{}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('8a0e9cd3-f0ea-4e77-9251-7d63312d9b24', '2026-09-27 23:00 本机网络卡顿排查（w-5b4f8aca）：本机/宽带侧健康——pi', '2026-09-27 23:00 本机网络卡顿排查（w-5b4f8aca）：本机/宽带侧健康——ping 223.5.5.5 30 包 0% 丢包 avg 11.6ms、网关 avg 4.9ms、DNS 0.00-0.02s、直连 mirrors.aliyun 5.7-9.0MB/s、networkQuality 下行 93.4Mbps/上行 80.2Mbps。瓶颈定位在境外线路：全部浏览器流量经 Clash Verge(mihomo v1.19.29, mixed-port 7897) 代理，proxied Cloudflare 仅 1.27MB/s vs 直连 5.7MB/s（约 4.5x），networkQuality base_rtt 93ms / TLS 握手 169-214ms；首次 https://www.google.com 15s 超时、github.com 首访 dns=3.1s total=14.1s。Clash 订阅自 2026-09-26 04:39 起持续更新失败（400 Bad Request），profiles/R5eMXkAIDFQA.yaml 停留在 09-13（节点表陈旧）。次要因素：本机 62G/64G 内存占用、11G compressor、Chrome 渲染进程 36-60% CPU + WindowServer 42% CPU；Wi-Fi 802.11ax 5GHz ch48/160MHz 信号 -61dBm，协商速率在 8-864Mbps 摆动；LAN 12 台设备共享空口，一条抖音 CDN 连接实时下载 42MB；路径 MTU≈1492（DF 1472 不通）。', 'knowledge', '{运维,网络诊断,clash-verge,mihomo,wifi,w-5b4f8aca}', NULL, '''-0.02'':39B ''-09'':2A,14B,100B ''-13'':111B ''-214'':83B ''-26'':101B ''-27'':3A,15B ''-60'':122B ''-61'':135B ''-864'':139B ''-9.0'':44B ''0'':28B ''0.00'':38B ''00'':5A,17B ''04'':102B ''09'':110B ''1.27'':67B ''11.6'':31B ''11g'':117B ''12'':143B ''14.1'':95B ''1472'':153B ''1492'':151B ''15s'':87B ''169'':82B ''2026'':1A,13B,99B ''223.5.5.5'':25B ''23'':4A,16B ''3.1'':92B ''30'':26B ''36'':121B ''39'':103B ''4.5'':74B ''4.9'':35B ''400'':105B ''42'':125B ''42mb'':148B ''5.7'':43B,71B ''5b4f8aca'':9A,21B ''5ghz'':132B ''62g/64g'':115B ''7897'':62B ''8'':138B ''80.2'':51B ''802.11'':130B ''93.4'':48B ''93ms'':79B ''avg'':30B,34B ''ax'':131B ''bad'':106B ''base'':77B ''cdn'':146B ''ch48/160mhz'':133B ''chrome'':119B ''clash'':55B,97B ''cloudflare'':65B ''compressor'':118B ''cpu'':123B,126B ''dbm'':136B ''df'':152B ''dns'':37B,91B ''fi'':129B ''github.com'':89B ''lan'':142B ''mb/s'':45B,68B,72B ''mbps'':49B,52B,140B ''mihomo'':57B ''mirrors.aliyun'':42B ''mixed'':60B 