INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('262b6c11-10a8-4052-a1c2-ad80b6e2525a', 'REQ-260927202051-f6df（DAG 任务队列机制）已交付并归档（2026-09-28', 'REQ-260927202051-f6df（DAG 任务队列机制）已交付并归档（2026-09-28，w-3936d77f）。结论：任务卡唯一存储 = docs/requirements/<REQ>/queue.json（含 DAG 层级 + ready 队列 + topo layers），台账 .dsh-data/dsh-reqboard.json 瘦身为 schemaVersion 9（只留 requirements/triages/migrations）；拆分写队列（plan-landing）、执行读队列（ExecuteTask 打印 Queue ready tasks:）、状态流转写回并解锁下游；顺序契约 taskStore.mutate 必须先于 repo.mutate（跨存储不再同事务）；原子写 persistAtomic。投产已执行：22:55 停机 --apply（51 份 queue.json / 616 条任务），看板真实浏览器实测 15/15 ×3 轮无回归，定向回归套 23 files / 223 tests 全绿，端到端 t17 EXIT=0。持久认知见 agent-dh/docs/architecture/reqboard-queue-storage.md（已挂 Wiki 卷 8 + 归档索引）。施工期自查修掉 3 处缺陷：①陈旧 advance 锁无回收路径（进程被 kill → finally 不执行、判据不看过期 → 只能人工清 advance.runId/lockAt，且必须落在旧进程死/新进程 load 之间的窗口）②(migrations 留痕被 load() 读路径抹掉，须原样带过)③ensureAgentHandle 加第 5 参 tasks 后一条 D14 旧测试未适配（首跑 22/220 → 修后 23/223）。另遗留两处「判据文本」口径问题（验收① curl /dashboard 是 hash 路由服务端 404；--verify 在活台账永不 exit 0，只能在纯净副本取证）——已在归档材料与 L2 文档中写明，未经人工改文本。', 'knowledge', '{reqboard,queue.json,ledger-v9,REQ-260927202051-f6df,归档,w-3936d77f}', NULL, '''-09'':8A,17B ''-260927202051'':2A,11B ''-28'':9A,18B ''/dashboard'':136B ''/docs/architecture/reqboard-queue-storage.md'':89B ''/dsh-reqboard.json'':37B ''/lockat'':109B ''/queue.json'':25B ''0'':84B,144B ''15/15'':72B ''2026'':7A,16B ''22'':62B ''22/220'':128B ''223'':78B ''23'':76B ''23/223'':130B ''3'':73B,96B ''3936d77f'':21B ''404'':140B ''5'':121B ''51'':66B ''55'':63B ''616'':69B ''8'':93B ''9'':40B ''advance'':99B ''advance.runid'':108B ''advance.runid/lockat'':107B ''agent'':87B ''agent-dh'':86B ''apply'':65B ''curl'':135B ''d14'':125B ''dag'':4A,13B,27B ''data'':36B ''dh'':88B ''docs/requirements'':24B ''dsh'':35B ''dsh-data'':34B ''ensureagenthandle'':119B ''executetask'':48B ''exit'':83B,143B ''f6df'':3A,12B ''files'':77B ''finally'':103B ''hash'':138B ''kill'':102B ''l2'':147B ''landing'':46B ''layers'':32B ''load'':112B,116B ''migrations'':114B ''persistatomic'':60B ''plan'':45B ''plan-landing'':44B ''queue'':50B ''queue.json'':68B ''ready'':29B,51B ''repo.mutate'':57B ''req'':1A,10B ''requirements/triages/migrations'':42B ''schemaversion'':39B ''t17'':82B ''tasks'':52B,123B ''taskstore.mutate'':55B ''tests'':79B ''topo'':31B ''verify'':141B ''w'':20B ''w-3936d77f'':19B ''wiki'':91B ''不执行'':104B ''且必须落在旧进程死'':110B ''之间的窗口'':113B ''任务卡唯一存储'':23B ''任务队列机制'':5A,14B ''份'':67B ''修后'':129B ''停机'':64B ''全绿'':80B ''判据不看过期'':105B ''判据文本'':132B ''加第'':120B ''卷'':92B ''原子写'':59B ''参'':122B ''口径问题'':133B ''另遗留两处'':131B ''只留'':41B ''只能人工清'':106B ''只能在纯净副本取证'':145B ''台账'':33B ''后一条'':124B ''含'':26B ''在活台账永不'':142B ''处缺陷'':97B ''定向回归套'':75B ''层级'':28B ''已交付并归档'':6A,15B ''已在归档材料与'':146B ''已挂'':90B ''归档索引'':94B ''必须先于'':56B ''打印'':49B ''执行读队列'':47B ''投产已执行'':61B ''拆分写队列'':43B ''持久认知见'':85B ''文档中写明'':148B ''新进程'':111B ''施工期自查修掉'':95B ''旧测试未适配'':126B ''是'':137B ''未经人工改文本'':149B ''条任务'':70B ''状态流转写回并解锁下游'':53B ''留痕被'':115B ''瘦身为'':38B ''看板真实浏览器实测'':71B ''端到端'':81B ''结论'':22B ''读路径抹掉'':117B ''跨存储不再同事务'':58B ''路由服务端'':139B ''轮无回归'':74B ''进程被'':101B ''锁无回收路径'':100B ''队列'':30B ''陈旧'':98B ''顺序契约'':54B ''须原样带过'':118B ''首跑'':127B ''验收'':134B', '2026-09-28 00:11:22.456668', '2026-09-28 00:11:22.456668', '{}');
