INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('654f19c7-ffe9-4504-a9de-d7787988381b', '600887 neutral 盘后复盘误判：凭周历把 2026-09-25 当作交易日后，将 signal_tracking 的 5 日回填窗口算错，得出"11', '600887 交易经验（2026-09-28T10:53:31.107Z）
场景：盘后复盘误判：凭周历把 2026-09-25 当作交易日后，将 signal_tracking 的 5 日回填窗口算错，得出"11 行逾期、回填自 09-18 后断裂"的否定性结论
结果：neutral
教训：交易日算术必须以 trading_calendar 工具为准，禁止用"周一至周五"推断。本次差点误报"signal_tracking.return_5d 回填断裂"：按周历把 2026-09-25（周五）算作交易日，得出 09-18 起 11 行逾期；实际 2026-09-25 是中秋节休市（trading_calendar 返回"❌ 非交易日"），故 09-18 的 5 日窗口落在 09-28（今日）、09-21 落在 09-29，均未逾期。回填本身健康（后端 updated_count=13、DB updated_at=18:50:26-27）。教训：涉及 N 日窗口、逾期判定、到期日计算的结论，先取交易日历核对，再下"断裂/逾期"这类否定性判断——否则会把正常的假期节奏误判成故障。', 'experience', '{600887,neutral}', NULL, '''-09'':6A,20B,30B,63B,75B ''-18'':44B,69B,84B ''-21'':92B ''-25'':7A,31B,64B,76B ''-27'':108B ''-28'':21B,89B ''-29'':95B ''09'':43B,68B,83B,88B,91B,94B ''11'':16A,40B,71B ''13'':101B ''18'':105B ''2026'':5A,19B,29B,62B,74B ''26'':107B ''31.107'':24B ''5'':13A,37B,86B ''50'':106B ''53'':23B ''5d'':59B ''600887'':1A,17B ''at'':104B ''calendar'':52B,79B ''count'':100B ''db'':102B ''n'':111B ''neutral'':2A,48B ''signal'':10A,34B ''signal_tracking.return'':58B ''t10'':22B ''tracking'':11A,35B ''trading'':51B,78B ''updated'':99B,103B ''z'':25B ''交易日算术必须以'':50B ''交易经验'':18B ''今日'':90B ''先取交易日历核对'':115B ''再下'':116B ''凭周历把'':4A,28B ''到期日计算的结论'':114B ''后断裂'':45B ''后端'':98B ''否则会把正常的假期节奏误判成故障'':120B ''周一至周五'':55B ''周五'':65B ''回填断裂'':60B ''回填本身健康'':97B ''回填自'':42B ''场景'':26B ''均未逾期'':96B ''实际'':73B ''将'':9A,33B ''工具为准'':53B ''当作交易日后'':8A,32B ''得出'':15A,39B,67B ''按周历把'':61B ''推断'':56B ''故'':82B ''教训'':49B,109B ''断裂'':117B ''日回填窗口算错'':14A,38B ''日窗口'':112B ''日窗口落在'':87B ''是中秋节休市'':77B ''本次差点误报'':57B ''涉及'':110B ''的'':12A,36B,85B ''的否定性结论'':46B ''盘后复盘误判'':3A,27B ''禁止用'':54B ''算作交易日'':66B ''结果'':47B ''落在'':93B ''行逾期'':41B,72B ''起'':70B ''返回'':80B ''这类否定性判断'':119B ''逾期'':118B ''逾期判定'':113B ''非交易日'':81B', '2026-09-28 18:53:31.108504', '2026-09-28 18:53:31.108504', '{}');
