INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('ade86d4f-c850-4644-b58e-05ef1742576b', '工程教训（2026-09-28，w-7f4acab0，REQ-260928185112-e20d 验', '工程教训（2026-09-28，w-7f4acab0，REQ-260928185112-e20d 验收实测）：自动实施链（reqboard_task_run）跑完卡后，验收会被三道门拦下——① REQBOARD_DOC_INCOMPLETE：workflow 路径的 executeSubtask 只写 queue.json 的 lastReport，不调 reqboard_task_report，故子卡 tasks/<id>.md 永不落盘（团队路径会写，两路径不一致）；② REQBOARD_ACCEPTANCE_NOT_EXECUTABLE：SubtaskTemplate 的子卡验收是写死的通用话术，未继承父卡命令；③ REQBOARD_TESTING_COVERAGE_GATE：accepting 覆盖度只认 <需求目录>/test-cases.md 或 tasks/*-test.md 里的 `## TC-N:` + `covers: t-xxx` 标注，链条不产出该文件。修复方向：workflow 收尾落子卡文档、子卡 acceptance 继承父卡可执行命令、链条生成 covers。纪律：链条越自动，越要确保「验收材料的生产者」与「验收门禁的消费者」对同一套文档契约负责。', 'experience', '{reqboard,实施链,验收门禁,REQ-260928185112-e20d,w-7f4acab0}', NULL, '''-09'':3A,14B ''-260928185112'':9A,20B ''-28'':4A,15B ''/test-cases.md'':63B ''2026'':2A,13B ''7f4acab0'':7A,18B ''acceptance'':50B,81B ''accepting'':60B ''coverage'':58B ''covers'':71B,84B ''doc'':30B ''e20d'':10A,21B ''executable'':52B ''executesubtask'':34B ''gate'':59B ''incomplete'':31B ''lastreport'':38B ''md'':45B ''n'':70B ''not'':51B ''queue.json'':36B ''report'':42B ''req'':8A,19B ''reqboard'':24B,29B,40B,49B,56B ''run'':26B ''subtasktemplate'':53B ''t'':73B ''t-xxx'':72B ''task'':25B,41B ''tasks'':44B,65B ''tc'':69B ''tc-n'':68B ''test.md'':66B ''testing'':57B ''w'':6A,17B ''w-7f4acab0'':5A,16B ''workflow'':32B,78B ''xxx'':74B ''不调'':39B ''与'':89B ''两路径不一致'':48B ''修复方向'':77B ''只写'':35B ''团队路径会写'':47B ''子卡'':80B ''对同一套文档契约负责'':91B ''工程教训'':1A,12B ''或'':64B ''收尾落子卡文档'':79B ''故子卡'':43B ''未继承父卡命令'':55B ''标注'':75B ''永不落盘'':46B ''的'':37B ''的子卡验收是写死的通用话术'':54B ''纪律'':85B ''继承父卡可执行命令'':82B ''自动实施链'':23B ''覆盖度只认'':61B ''越要确保'':87B ''跑完卡后'':27B ''路径的'':33B ''里的'':67B ''链条不产出该文件'':76B ''链条生成'':83B ''链条越自动'':86B ''需求目录'':62B ''验'':11A ''验收会被三道门拦下'':28B ''验收实测'':22B ''验收材料的生产者'':88B ''验收门禁的消费者'':90B', '2026-09-28 21:00:11.166629