INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('6d8dd47c-7ee1-4765-8d96-b0296b54c639', '000963 neutral 2026-09-29 09:43/09:53 盯盘规则#223（000963 华东医药）真实触发「放量上破 27.20」（量为同期', '000963 交易经验（2026-09-29T11:06:08.253Z）
