INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('96bfc61f-3152-4f98-8777-a487c1dd8ab2', '002007 neutral 2026-09-30 盘中窗口写入的未收盘快照K线污染了当日日线（18:00 读到 13.04，真实收盘 13.34，差 -2.3', '002007 交易经验（2026-09-30T11:23:43.123Z）
