INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('c443e14f-97e2-482b-83ab-abc6738751f3', '【每日复盘 agent-brain-daily-review（task a17c73b5，2026-', '【每日复盘 agent-brain-daily-review（task a17c73b5，2026-10-03 18:00 触发，周六·国庆休市）· 账户 agent_brain】

