INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('831ee762-fd6b-4ac5-b40a-8f703bb80cea', '600519 loss 2026-09-28 止损清仓 600519（agent_brain）：盘前 09:02 挂 market_open SELL 100 ', '600519 交易经验（2026-10-04T12:03:17.531Z）
