INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('20941f39-bfa9-4db3-bb58-971bb8ca3a79', '2026-09-01 sector 多数据源 failover（investor w-8366e52', '2026-09-01 sector 多数据源 failover（investor w-8366e526，1f5bb67e）：用户要求"EastmoneySectorProvider 多添加几个"。方案：新增 AkshareSectorProvider（adapters/outbound/datasources/providers/sector/akshare.py），走与东财完全独立的通道——新浪行业（ak.stock_sector_spot，49 大类，~0.1s，sina 通道）+ 同花顺概念（ak.stock_board_concept_name_ths，375 概念，~5s，ths 通道）；字段对齐东财（code/name/change_pct/change_amount/market_cap，新浪无市值、ths 概念仅名称代码则填默认值）；get_sector_stocks 返回 None（成分仍由 eastmoney 提供）。挂入 manager.sector_providers 走统一 _try_providers failover（eastmoney→akshare）。实测：正常 eastmoney 优先（496+504）；模拟 eastmoney 故障→akshare 顶上（49+375，source=akshare）。关键经验：①manager.py 是他人未提交改动区（+96/-19 超时配置/DataSourceCache），用 git reset + 拆单 hunk patch（git apply --cached）实现 hunk 级隔离提交，只提交自己的 2 行；git add -p 管道数 hunk 易错位（曾误 stage 他人 DataSourceCache，及时 reset）；②akshare 的东财通道接口（stock_board_industry_name_em）在本机被系统级代理（ClashX）拦截（ProxyError），清环境变量无效（requests trust_env 读 macOS 系统代理），但新浪/同花顺域名直连可用——选备选源时优先验证通道域名是否绕开代理。', 'knowledge', '{sector多数据源,akshare,failover,hunk级提交,w-8366e526}', NULL, '''+375'':85B ''+504'':78B ''+96'':91B ''-01'':3A,13B ''-09'':2A,12B ''-19'':92B ''/datasourcecache'':94B ''0.1'':36B ''1f5bb67e'':21B ''2'':108B ''2026'':1A,11B ''375'':46B ''49'':34B,84B ''496'':77B ''5s'':48B ''8366e52'':10A ''8366e526'':20B ''adapters/outbound/datasources/providers/sector/akshare.py'':28B ''add'':111B ''ak.stock'':31B,41B ''akshare'':72B,82B,87B,122B ''aksharesectorprovider'':27B ''apply'':102B ''board'':42B,125B ''cached'':103B ''clashx'':130B ''code/name/change_pct/change_amount/market_cap'':52B ''concept'':43B ''datasourcecache'':119B ''eastmoney'':62B,71B,75B,80B ''eastmoneysectorprovider'':23B ''em'':128B ''env'':136B ''failover'':6A,16B,70B ''get'':56B ''git'':96B,101B,110B ''hunk'':99B,105B,114B ''industry'':126B ''investor'':7A,17B ''macos'':138B ''manager.py'':89B ''manager.sector'':65B ''name'':44B,127B ''none'':60B ''p'':112B ''patch'':100B ''providers'':66B,69B ''proxyerror'':132B ''requests'':134B ''reset'':97B,121B ''s'':37B ''sector'':4A,14B,32B,57B ''sina'':38B ''source'':86B ''spot'':33B ''stage'':117B ''stock'':124B ''stocks'':58B ''ths'':45B,49B,54B ''trust'':135B ''try'':68B ''w'':9A,19B ''w-8366e52'':8A ''w-8366e526'':18B ''他人'':118B ''优先'':76B ''但新浪'':140B ''关键经验'':88B ''及时'':120B ''只提交自己的'':107B ''同花顺域名直连可用'':141B ''同花顺概念'':40B ''在本机被系统级代理'':129B ''多数据源'':5A,15B ''多添加几个'':24B ''大类'':35B ''字段对齐东财'':51B ''实测'':73B ''实现'':104B ''成分仍由'':61B ''拆单'':98B ''拦截'':131B ''挂入'':64B ''提供'':63B ''故障'':81B ''新增'':26B ''新浪无市值'':53B ''新浪行业'':30B ''方案'':25B ''易错位'':115B ''是他人未提交改动区'':90B ''曾误'':116B ''概念'':47B ''概念仅名称代码则填默认值'':55B ''模拟'':79B ''正常'':74B ''清环境变量无效'':133B ''用'':95B ''用户要求'':22B ''的东财通道接口'':123B ''管道数'':113B ''系统代理'':139B ''级隔离提交'':106B ''行'':109B ''读'':137B ''走与东财完全独立的通道'':29B ''走统一'':67B ''超时配置'':93B ''返回'':59B ''选备选源时优先验证通道域名是否绕开代理'':142B ''通道'':39B,50B ''顶上'':83B', '2026-09-01 22:08:39.230363', '2026-09-05 02:26:02.102633', '{"closed_at": "2026-09-05T02:26:02+08:00", "drop_reason": "旧格式帖子批量清理（无 metadata 结构，无法通过 board_update 操作）", "board_status": "archived"}');
INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('cc119fd6-028b-471d-90ee-3c3e40287ba6', 'M6-4 evolution 常态化完成（2026-09-01，investor w-8366e52', 'M6-4 evolution 常态化完成（2026-09-01，investor w-8366e526）：evolution_leaderboard 达 10 条唯一策略记录（验收达成），机制验证通过（evolution/run full/propose + leaderboard 全链路可用）。关键发现：5 个核心策略（635 macd/636 bollinger/637 rsi/638 dual-ma/639 momentum）的参数变体经真实回测全部优于默认参数（macd -0.045→+0.137 用 fast5/slow13/signal3、bollinger -0.477→+0.211 用 bb20/std3.0、rsi -0.411→+0.172 用 period7/oversold25/overbought75、momentum -0.453→+0.077 用 lookback5/threshold3.0、dual-ma -0.766→-0.333 用 fast5/slow20），平均提升 +0.28 Sharpe，证明参数进化有真实收益空间；但弱市区间即使最优参数也无法突破 Sharpe 1.0，单靠参数无法跨越市场状态，需叠加市场状态过滤（regime 弱市降仓/空仓）+ 回撤控制 -14%→-8%。fitness 估算值基于交易记录（当前稀疏），真实有效性以回测为准。', 'knowledge', '{M6-4,evolution,参数进化,夏普,macd,leaderboard}', NULL, '''+0.077'':64B ''+0.137'':49B ''+0.172'':59B ''+0.211'':54B ''+0.28'':75B ''-0.045'':48B ''-0.333'':71B ''-0.411'':58B ''-0.453'':63B ''-0.477'':53B ''-0.766'':70B ''-01'':7A,18B ''-09'':6A,17B ''-14'':87B ''-4'':2A,13B ''-8'':88B ''/639'':44B ''1.0'':80B ''10'':26B ''2026'':5A,16B ''5'':35B ''635'':37B ''8366e52'':11A ''8366e526'':22B ''bb20/std3.0'':56B ''bollinger'':52B ''bollinger/637'':39B ''dual'':42B,68B ''dual-ma'':41B,67B ''evolution'':3A,14B,23B ''evolution/run'':30B ''fast5/slow13/signal3'':51B ''fast5/slow20'':73B ''fitness'':89B ''full/propose'':31B ''investor'':8A,19B ''leaderboard'':24B,32B ''lookback5/threshold3.0'':66B ''m6'':1A,12B ''ma'':43B,69B ''macd'':47B ''macd/636'':38B ''momentum'':45B,62B ''period7/oversold25/overbought75'':61B ''regime'':83B ''rsi'':57B ''rsi/638'':40B ''sharpe'':76B,79B ''w'':10A,21B ''w-8366e52'':9A ''w-8366e526'':20B ''个核心策略'':36B ''估算值基于交易记录'':90B ''但弱市区间即使最优参数也无法突破'':78B ''全链路可用'':33B ''关键发现'':34B ''单靠参数无法跨越市场状态'':81B ''回撤控制'':86B ''常态化完成'':4A,15B ''平均提升'':74B ''弱市降仓'':84B ''当前稀疏'':91B ''机制验证通过'':29B ''条唯一策略记录'':27B ''用'':50B,55B,60B,65B,72B ''的参数变体经真实回测全部优于默认参数'':46B ''真实有效性以回测为准'':92B ''空仓'':85B ''证明参数进化有真实收益空间'':77B ''达'':25B ''需叠加市场状态过滤'':82B ''验收达成'':28B', '2026-09-01 00:20:57.745222', '2026-09-05 02:26:02.105656', '{"closed_at": "2026-09-05T02:26:02+08:00", "drop_reason": "旧格式帖子批量清理（无 metadata 结构，无法通过 board_update 操作）", "board_status": "archived"}');
