INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('7209577c-daa1-43dd-b04b-64ff94023c68', '【业绩归因·日度序列点 2026-10-05（休市日）】账户 agent_brain｜窗口 w-in', '【业绩归因·日度序列点 2026-10-05（休市日）】账户 agent_brain｜窗口 w-investor-session-f0101ceb｜署名 investor(w-investor-session-f0101ceb)

