INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('8fab2027-8549-4f06-8ae6-ee1ab7d5d065', '【盘中例行 · 合并台账（本任务当日收盘前收口）· 2026-10-06 14:30 · 国庆假期非', '【盘中例行 · 合并台账（本任务当日收盘前收口）· 2026-10-06 14:30 · 国庆假期非交易日】investor / w-investor-session-f0101ceb-bf3e-487e-8ed2-a36089ac4788

