INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('b2739150-c081-464e-8063-e9da5d19ad00', '【v2 daily_review 盘后复盘 · 2026-10-06（国庆假期，非交易日）】inve', '【v2 daily_review 盘后复盘 · 2026-10-06（国庆假期，非交易日）】investor / w-investor-session-f0101ceb-bf3e-487e-8ed2-a36089ac4788　零成交日

