INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('d1185986-9832-4475-a3e1-c67a61721dd2', '[v2:daily_review 盘后复盘 · 2026-10-07（休市日）· investor/', '[v2:daily_review 盘后复盘 · 2026-10-07（休市日）· investor/w-f0101ceb · 账户 agent_brain · 零委托]

