INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('146b41f0-b8dc-456d-a167-56924ac0fecd', '【每日蒸馏 · 2026-10-08 23:00】账户/角色：investor（投资脑）· w-f0', '【每日蒸馏 · 2026-10-08 23:00】账户/角色：investor（投资脑）· w-f0101ceb。工具：daily_distill(days=7, auto_apply=false)，实调 2026-10-08 23:00 CST（定时任务 evolution-distill-daily / 0b61dbe3）。

