INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('19acf760-c90a-4dfa-ada7-adcb3a1e7c7f', '【中国铝业 601600 外部实盘清仓确认 · 2026-10-16 · investor / w-', '【中国铝业 601600 外部实盘清仓确认 · 2026-10-16 · investor / w-977dc5e2】用户先报告“9.17元清仓了”，随后在确认问题中选择“实盘已清仓，关闭盯盘跟踪”。按用户外部实盘事实：原1000股@9.13，卖出价9.17，毛盈亏约+40元（+0.44%，未扣费）。注意：user_main_simulation 模拟账仍显示1000股可卖，且当日最高8.88、无9.17系统成交；不能据此宣称系统仓已平。拟停用持仓风控规则#252，但 watch_manage(disable) 连续两次10秒超时，/api/health与quantsys_v2_status亦超时，当前后端不可用，故规则停用仍为待办，不得写成已完成。后续后端恢复后：核验#252 enabled，若仍为true则按用户确认停用并补decision_audit；不改模拟仓、不代下单。', 'knowledge', '{601600,中国铝业,实盘清仓,规则252,待办,w-977dc5e2}', NULL, '''+0.44'':32B ''+40'':30B ''-10'':5A,13B ''-16'':6A,14B ''/api/health'':50B ''2026'':4A,12B ''252'':44B,59B ''601600'':2A,10B ''9.13'':27B ''9.17'':20B ''977dc5e2'':18B ''audit'':62B ''disable'':48B ''enabled'':60B ''investor'':7A,15B ''main'':36B ''manage'':47B ''simulation'':37B ''status亦超时'':53B ''user'':35B ''v2'':52B ''w'':8A,17B ''w-977dc5e2'':16B ''watch'':46B ''不代下单'':64B ''不得写成已完成'':56B ''不改模拟仓'':63B ''不能据此宣称系统仓已平'':42B ''与quantsys'':51B ''且当日最高8.88'':39B ''中国铝业'':1A,9B ''但'':45B ''元'':31B ''元清仓了'':21B ''关闭盯盘跟踪'':24B ''卖出价9.17'':28B ''原1000股'':26B ''后续后端恢复后'':57B ''外部实盘清仓确认'':3A,11B ''实盘已清仓'':23B ''当前后端不可用'':54B ''拟停用持仓风控规则'':43B ''按用户外部实盘事实'':25B ''故规则停用仍为待办'':55B ''无9.17'':40B ''未扣费'':33B ''核验'':58B ''模拟账仍显示1000股可卖'':38B ''毛盈亏约'':29B ''注意'':34B ''用户先报告'':19B ''系统成交'':41B ''若仍为true则按用户确认停用并补decision'':61B ''连续两次10秒超时'':49B ''随后在确认问题中选择'':22B', '2026-10-16 16:19:01.99603', '2026-10-16 16:19:01.99603', '{}');
