INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('6415e33f-55a6-4fbb-a0d2-a627fc5584ec', 'REQ-261019144524-ec50 自动链"静默空转"误判修正（w-503df447，202', 'REQ-261019144524-ec50 自动链"静默空转"误判修正（w-503df447，2026-10-20）：reqboard_task_run 派发并非空转——selectAdvanceEvent 优先级 1 是 FINALIZE_PARENT，t-f4e050（in_progress、子卡全 done、done 凭证门 REQBOARD_NO_EVIDENCE 正确拒绝）每次都先被选中、失败即 pauseRequirement(autoRun=false)，链永远到不了 t-aa8733。教训：①判断"链没在跑"前必须先读台账 advance.history（.dsh-data/dsh-reqboard.json），不能只看 advance-log.md 末尾有没有 RUN_SUBTASK；②dispatched 回执≠链推进成功，run_status snapshot 不含 stopped/pausedReason 是观测面缺口；③一张前提被证伪的父卡会把整条自动链堵死在优先级 1，处置=取消该卡（代码级只能人操作）。', 'knowledge', '{reqboard,自动链,REQ-261019144524-ec50,观测面,FINALIZE_PARENT}', NULL, '''-10'':21B ''-20'':22B ''-261019144524'':2A,12B ''/dsh-reqboard.json'':63B ''1'':29B,79B ''202'':10A ''2026'':20B ''503df447'':9A,19B ''aa8733'':54B ''advance-log.md'':65B ''advance.history'':59B ''autorun'':49B ''data'':62B ''dispatched'':69B ''done'':39B,40B ''dsh'':61B ''dsh-data'':60B ''ec50'':3A,13B ''evidence'':44B ''f4e050'':35B ''false'':50B ''finalize'':31B ''in'':36B ''no'':43B ''parent'':32B ''pauserequirement'':48B ''progress'':37B ''req'':1A,11B ''reqboard'':23B,42B ''run'':25B,67B,72B ''selectadvanceevent'':27B ''snapshot'':74B ''status'':73B ''stopped/pausedreason'':76B ''subtask'':68B ''t'':34B,53B ''t-aa8733'':52B ''t-f4e050'':33B ''task'':24B ''w'':8A,18B ''w-503df447'':7A,17B ''一张前提被证伪的父卡会把整条自动链堵死在优先级'':78B ''不含'':75B ''不能只看'':64B ''代码级只能人操作'':82B ''优先级'':28B ''凭证门'':41B ''判断'':56B ''前必须先读台账'':58B ''取消该卡'':81B ''回执'':70B ''处置'':80B ''失败即'':47B ''子卡全'':38B ''教训'':55B ''是'':30B ''是观测面缺口'':77B ''末尾有没有'':66B ''正确拒绝'':45B ''每次都先被选中'':46B ''派发并非空转'':26B ''自动链'':4A,14B ''误判修正'':6A,16B ''链推进成功'':71B ''链永远到不了'':51B ''链没在跑'':57B ''静默空转'':5A,15B', '2026-10-19 21:08:32.74775', '2026-10-19 21:08:32.74775', '{}');
