INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('48044b07-698f-494a-967b-9fd97856a8d0', '【试单授权已批准】2026-10-19 用户原话「试单授权 虚拟账户你说的算不需要审批」= RFC ', '【试单授权已批准】2026-10-19 用户原话「试单授权 虚拟账户你说的算不需要审批」= RFC 017 A 档生效。范围：仅 agent_brain 虚拟账户（真金不授权）。边界：单笔 ≤5000 元、总敞口 ≤10000 元、同时试单持仓 ≤2 只、仅 A 级信号（≥3 维共振）、月度试单亏损 2500 元熔断（触及当月停新开仓）、宪法止损不豁免、R-001/R-008/R-005 确认链逐笔照走并留 decision_audit。试行期 2026-10-20~2026-11-19，每周复盘附带试单小节，用户可随时撤销。执行前置：建仓冻结解除 + 交易时段 + A 级信号三者齐备。文档：docs/rfcs/017-small-position-trial-authorization.md（已落章）。', 'knowledge', '{RFC017,试单授权,已批准,agent_brain,2026-10-19}', NULL, '''-001'':47B ''-10'':3A,11B,54B ''-19'':4A,12B ''-20'':55B ''/r-008/r-005'':48B ''017'':17B ''10000'':31B ''2'':34B ''2026'':2A,10B,53B ''2500'':42B ''3'':39B ''5000'':28B ''a'':18B,37B,62B ''agent'':22B ''audit'':51B ''brain'':23B ''decision'':50B ''docs/rfcs/017-small-position-trial-authorization.md'':65B ''r'':46B ''rfc'':8A,16B ''~2026-11-19'':56B ''交易时段'':61B ''仅'':21B,36B ''元'':29B,32B ''元熔断'':43B ''单笔'':27B ''只'':35B ''同时试单持仓'':33B ''宪法止损不豁免'':45B ''已落章'':66B ''建仓冻结解除'':60B ''总敞口'':30B ''执行前置'':59B ''文档'':64B ''月度试单亏损'':41B ''档生效'':19B ''每周复盘附带试单小节'':57B ''用户原话'':5A,13B ''用户可随时撤销'':58B ''真金不授权'':25B ''确认链逐笔照走并留'':49B ''级信号'':38B ''级信号三者齐备'':63B ''维共振'':40B ''范围'':20B ''虚拟账户'':24B ''虚拟账户你说的算不需要审批'':7A,15B ''触及当月停新开仓'':44B ''试单授权'':6A,14B ''试单授权已批准'':1A,9B ''试行期'':52B ''边界'':26B', '2026-10-20 01:17:56.030106', '2026-10-20 01:17:56.030106', '{}');
