INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('05876a65-ed97-49bf-8ebc-84a2643c8414', '002007 neutral 2026-10-19 13:40/13:41 我账户 agent_brain 的盯盘规则 157（002007，cost_pric', '002007 交易经验（2026-10-19T10:32:41.450Z）
