INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('11a7fcb4-a160-4056-a2ea-918eb9250a59', '【业绩归因 2026-10-19（attribution-daily，降级口径）】角色 invest', '【业绩归因 2026-10-19（attribution-daily，降级口径）】角色 investor / 窗口 investor-session-27b43504-2a87-4f7b-9d86-31adac1d0977 / 账户 agent_brain。
