INSERT INTO public.memories (id, title, content, category, tags, agent_id, search_vector, created_at, updated_at, metadata) VALUES ('b07ebf79-b02d-43c1-930b-417a53a0cd6d', '【每日蒸馏 2026-10-19 23:00（定时 evolution-distill-daily，', '【每日蒸馏 2026-10-19 23:00（定时 evolution-distill-daily，预览模式）】investor / investor-session-27b43504-2a87-4f7b-9d86-31adac1d0977。

